CREATE OR REPLACE FUNCTION brand_finance_private.accept_cash_handover()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE h public.bf_cash_handovers%ROWTYPE;
BEGIN
 SELECT h1.* INTO h FROM public.bf_cash_handovers h1 WHERE h1.cafe_id=NEW.cafe_id AND h1.receiving_drawer_id=NEW.account_id AND h1.handover_type='next_shift' AND NOT EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts r WHERE r.handover_id=h1.id) ORDER BY h1.created_at,h1.id LIMIT 1 FOR UPDATE;
 IF FOUND THEN
  INSERT INTO public.bf_cash_handover_receipts(handover_id,cafe_id,received_by,received_by_name,received_counted_cash,receiving_shift_id,account_id)
  VALUES(h.id,NEW.cafe_id,NEW.user_id,brand_finance_private.cash_employee_name(NEW.cafe_id,NEW.user_id),NEW.opening_cash,NEW.id,NEW.account_id);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.apply_sale_customer(p_cafe uuid, p_document uuid, p_payload jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE d public.bf_documents;c public.loyalty_cards;r public.customer_reward_instances;v_phone text;v_card uuid;v_reward uuid;
 v_loyalty boolean;v_pager uuid;v_rewards integer;v_state text;v_existing public.pager_orders;v_hash text:=p_payload->>'pagerFeedbackHash';
BEGIN
 SELECT * INTO STRICT d FROM public.bf_documents WHERE cafe_id=p_cafe AND id=p_document AND kind='sale';
 v_phone:=d.customer_phone;v_reward:=nullif(p_payload->>'redeemRewardId','')::uuid;
 IF v_phone IS NULL THEN IF v_reward IS NOT NULL THEN RAISE EXCEPTION 'Customer phone required for reward'; END IF; RETURN NULL; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('loyalty-enroll:'||p_cafe::text||':'||v_phone,0));
 v_loyalty:=brand_finance_private.customer_loyalty_enabled(p_cafe);v_card:=CASE WHEN v_loyalty THEN brand_finance_private.customer_card(p_cafe,v_phone) END;
 -- Ambiguous, blocked or suspended identities never acquire a deferred reward
 IF (SELECT count(*) FROM public.customer_profiles WHERE cafe_id=p_cafe AND phone_normalized=v_phone)>1
 OR EXISTS(SELECT 1 FROM public.customer_profiles cp LEFT JOIN public.loyalty_cards lc ON lc.cafe_id=cp.cafe_id AND lc.customer_profile_id=cp.id
  WHERE cp.cafe_id=p_cafe AND cp.phone_normalized=v_phone AND (cp.status<>'active' OR cp.blocked_at IS NOT NULL OR cp.phone_auth_conflict OR lc.status<>'active')) THEN
  v_loyalty:=false;v_card:=NULL;
 END IF;
 IF v_reward IS NOT NULL THEN
  IF v_card IS NULL THEN RAISE EXCEPTION 'Customer reward unavailable'; END IF;
  -- Match the existing scanner lock order: card first, then reward
  SELECT * INTO STRICT c FROM public.loyalty_cards WHERE id=v_card FOR UPDATE;
  SELECT * INTO r FROM public.customer_reward_instances WHERE id=v_reward AND cafe_id=p_cafe AND loyalty_card_id=v_card AND source_type='loyalty' FOR UPDATE;
  IF NOT FOUND OR r.status<>'available' OR (r.expires_at IS NOT NULL AND r.expires_at<=now()) THEN RAISE EXCEPTION 'Customer reward unavailable'; END IF;
  UPDATE public.customer_reward_instances SET status='redeemed',redeemed_at=now(),redeemed_by=auth.uid(),updated_at=now(),
   metadata=metadata||jsonb_build_object('financeDocumentId',d.id,'financeDocumentNumber',d.number,'redeemedByFinanceUserId',auth.uid()) WHERE id=r.id;
  INSERT INTO public.customer_reward_redemptions(cafe_id,reward_instance_id,customer_id,redeemed_by,scanned_code) VALUES(p_cafe,r.id,r.customer_id,auth.uid(),r.reward_code);
  SELECT count(*) INTO v_rewards FROM public.customer_reward_instances WHERE cafe_id=p_cafe AND loyalty_card_id=v_card AND status='available' AND (expires_at IS NULL OR expires_at>now());
  UPDATE public.loyalty_cards SET available_rewards=v_rewards,last_used_at=now(),updated_at=now() WHERE id=v_card;
  INSERT INTO public.loyalty_card_events(cafe_id,card_id,performed_by,event_type,invoice_barcode,reward_delta,stamps_after,rewards_after,note)
  VALUES(p_cafe,v_card,auth.uid(),'redeem','POS-'||d.number::text,-1,c.stamps_in_cycle,v_rewards,'صرف مكافأة من نقطة البيع');
 END IF;
 IF pager_private.enabled(p_cafe) THEN
  IF v_hash IS NULL OR v_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Pager identity required'; END IF;
  SELECT * INTO v_existing FROM public.pager_orders WHERE cafe_id=p_cafe AND invoice_number=d.number::text AND status IN('waiting','ready') FOR UPDATE;
  IF FOUND THEN
   IF v_existing.phone<>v_phone OR EXISTS(SELECT 1 FROM public.bf_sale_customers WHERE pager_order_id=v_existing.id) THEN RAISE EXCEPTION 'رقم الفاتورة مرتبط بطلب بيجر آخر راجع رقم العميل قبل تأكيد البيع'; END IF;
   v_pager:=v_existing.id;
  ELSE
   v_pager:=p_request;
   PERFORM public.pager_create_order(v_pager,p_cafe,d.number::text,v_phone,brand_finance_private.treasury_actor_name(p_cafe,auth.uid()),'نقطة البيع',auth.uid(),v_hash);
  END IF;
 END IF;
 v_state:=CASE WHEN v_loyalty THEN 'pending_enrollment' ELSE 'unavailable' END;
 INSERT INTO public.bf_sale_customers(cafe_id,document_id,phone,pager_order_id,loyalty_status,redeemed_reward_id) VALUES(p_cafe,d.id,v_phone,v_pager,v_state,v_reward);
 IF v_card IS NOT NULL THEN PERFORM brand_finance_private.stamp_sale_customer(d.id,v_card); END IF;
 SELECT loyalty_status INTO v_state FROM public.bf_sale_customers WHERE document_id=d.id;
 IF v_loyalty THEN INSERT INTO public.bf_customer_message_jobs(cafe_id,document_id) VALUES(p_cafe,d.id); END IF;
 RETURN jsonb_build_object('phone',v_phone,'pagerOrderId',v_pager,'pagerStatus',CASE WHEN v_pager IS NULL THEN 'unavailable' ELSE coalesce(v_existing.status,'waiting') END,
  'loyaltyStatus',v_state,'rewardRedeemedId',v_reward,'notificationStatus',CASE WHEN v_loyalty THEN 'pending' ELSE 'not_applicable' END);
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.assert_job_access(p_cafe uuid, p_endpoint text, p_operation text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; allowed boolean:=false;
BEGIN
 r:=brand_finance_private.role_for(p_cafe);
 IF p_endpoint='brand_finance_execute' THEN
  allowed:=brand_finance_private.operation_allowed(r,p_operation);
 ELSIF r IN('owner','manager','cashier') THEN
  -- Preserve all existing, narrower guards for the established roles.
  RETURN;
 ELSIF p_endpoint='brand_finance_snapshot' THEN allowed:=true;
 ELSIF p_endpoint='brand_finance_history' THEN
  allowed:=r IN('accountant','auditor') OR (r='warehouse' AND p_operation='movements');
 ELSIF p_endpoint IN('brand_finance_treasury_snapshot','brand_finance_treasury_statement','brand_finance_treasury_history','brand_finance_terminal_fee_history','brand_finance_cash_differences','brand_finance_cash_handovers','brand_finance_shift_monitor','brand_finance_shift_analytics','brand_finance_pos_shift_report') THEN allowed:=r IN('accountant','auditor');
 ELSIF p_endpoint IN('brand_finance_treasury_execute','brand_finance_receive_shift_cash','brand_finance_save_customer') THEN allowed:=r='accountant';
 ELSIF p_endpoint='brand_finance_treasury_attachment' THEN allowed:=r='accountant' OR (r='auditor' AND p_operation IN('list','get'));
 ELSIF p_endpoint='brand_finance_shift_attachment' THEN allowed:=r IN('accountant','auditor') AND p_operation='read';
 END IF;
 IF NOT coalesce(allowed,false) THEN RAISE EXCEPTION 'لا تملك صلاحية تنفيذ هذه العملية' USING ERRCODE='42501'; END IF;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.assert_period_close(p_cafe uuid, p_payload jsonb, p_request uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE previous_cutoff date; cutoff date:=nullif(p_payload->>'closedThrough','')::date;
 cutoff_end timestamptz; reason text:=btrim(coalesce(p_payload->>'periodCloseReason',''));
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 IF brand_finance_private.role_for(p_cafe)<>'owner' THEN
  RAISE EXCEPTION 'إقفال الفترة متاح لمالك العلامة فقط' USING ERRCODE='42501';
 END IF;
 SELECT closed_through INTO previous_cutoff FROM public.bf_settings WHERE cafe_id=p_cafe FOR UPDATE;
 IF previous_cutoff IS NOT NULL AND (cutoff IS NULL OR cutoff<previous_cutoff) THEN
  RAISE EXCEPTION 'لا يمكن إعادة فتح فترة مقفلة';
 END IF;
 -- Unchanged policy updates and pre-existing closure dates do not create new closure events
 IF cutoff IS NOT DISTINCT FROM previous_cutoff THEN RETURN; END IF;
 IF cutoff IS NULL THEN RETURN; END IF;
 IF cutoff>=(now() AT TIME ZONE 'Asia/Riyadh')::date THEN
  RAISE EXCEPTION 'اختر نهاية يوم مكتمل قبل اليوم الحالي بتوقيت الرياض';
 END IF;
 IF length(reason) NOT BETWEEN 3 AND 1000 OR p_request IS NULL THEN
  RAISE EXCEPTION 'أدخل سبب إقفال الفترة من 3 إلى 1000 حرف';
 END IF;
 cutoff_end:=(cutoff+1)::timestamp AT TIME ZONE 'Asia/Riyadh';
 IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe
  AND status IN('open','handover') AND opened_at<cutoff_end) THEN
  RAISE EXCEPTION 'أكمل إقفال الورديات وتسليمها ضمن الفترة قبل إقفال الفترة المالية';
 END IF;
 IF EXISTS(SELECT 1 FROM public.bf_cash_handovers h
  JOIN public.bf_shifts s ON s.cafe_id=h.cafe_id AND s.id=h.shift_id
  WHERE h.cafe_id=p_cafe AND s.opened_at<cutoff_end
  AND NOT EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts r WHERE r.cafe_id=h.cafe_id AND r.handover_id=h.id)) THEN
  RAISE EXCEPTION 'أكد استلام جميع مبالغ تسليم الصناديق المرتبطة بورديات الفترة أولًا';
 END IF;
 INSERT INTO public.bf_period_closures(cafe_id,previous_closed_through,closed_through,reason,actor_id,request_id)
 VALUES(p_cafe,previous_cutoff,cutoff,reason,auth.uid(),p_request);
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.capture_invoice_line_notes(p_cafe_id uuid, p_draft_id uuid, p_document_id uuid, p_snapshot_lines jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE selection public.bf_invoice_line_note_drafts%ROWTYPE;draft public.bf_invoice_drafts%ROWTYPE;historical jsonb:='[]'::jsonb;normalized jsonb;
BEGIN
  SELECT * INTO draft FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=p_draft_id;
  SELECT * INTO selection FROM public.bf_invoice_line_note_drafts WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  IF selection.draft_id IS NOT NULL THEN
    IF selection.draft_revision<>draft.revision THEN RAISE EXCEPTION 'أعد حفظ ملاحظات البنود بعد تحديث المسودة' USING ERRCODE='40001';END IF;
    normalized:=brand_finance_private.validate_invoice_line_note_selection(selection.lines,draft.payload#>'{invoice,lines}');
    IF jsonb_array_length(p_snapshot_lines)<>jsonb_array_length(draft.payload#>'{invoice,lines}') THEN RAISE EXCEPTION 'تعذر مطابقة ملاحظات البنود مع الفاتورة' USING ERRCODE='22023';END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('lineIndex',d.position-1,'key',n->'key','notes',n->'notes') ORDER BY d.position),'[]'::jsonb) INTO historical
      FROM jsonb_array_elements(draft.payload#>'{invoice,lines}') WITH ORDINALITY d(value,position) JOIN jsonb_array_elements(normalized) n ON (n->>'key')::numeric=(d.value->>'key')::numeric;
  END IF;
  INSERT INTO public.bf_invoice_line_notes(cafe_id,document_id,lines,created_by) VALUES(p_cafe_id,p_document_id,historical,auth.uid());
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.cash_deletion_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));
 IF OLD.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'الخزينة محذوفة ولا يمكن إعادة استخدامها'; END IF;
 IF NEW.deleted_at IS NOT NULL AND NOT brand_finance_private.can_delete_cash(OLD.cafe_id,OLD.id) THEN
  RAISE EXCEPTION 'لا يمكن حذف خزينة رئيسية أو أساسية أو خزينة لها حركات أو ورديات أو ارتباطات';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.cash_shift_before()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.cafe_id,NEW.user_id,NEW.account_id,NEW.shift_number,NEW.opening_cash,NEW.opening_expected_cash,NEW.opening_variance,NEW.opened_at) IS DISTINCT FROM ROW(OLD.cafe_id,OLD.user_id,OLD.account_id,OLD.shift_number,OLD.opening_cash,OLD.opening_expected_cash,OLD.opening_variance,OLD.opened_at) THEN RAISE EXCEPTION 'بيانات بداية الوردية ثابتة'; END IF;
  RETURN NEW;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));
 INSERT INTO public.bf_shift_cash_numbers(cafe_id,last_number) VALUES(NEW.cafe_id,1) ON CONFLICT(cafe_id) DO UPDATE SET last_number=public.bf_shift_cash_numbers.last_number+1 RETURNING last_number INTO NEW.shift_number;
 SELECT coalesce(sum(debit-credit),0) INTO NEW.opening_expected_cash FROM public.bf_journal WHERE cafe_id=NEW.cafe_id AND account_id=NEW.account_id;
 NEW.opening_variance:=NEW.opening_cash-NEW.opening_expected_cash;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.cash_shift_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE phase text; expected numeric; counted numeric; delta numeric; doc uuid; event_id uuid; previous_user uuid; title text; prior_handover record; handover_previous_name text;
BEGIN
 IF TG_OP='INSERT' THEN phase:='opening';expected:=NEW.opening_expected_cash;counted:=NEW.opening_cash;
 ELSIF OLD.status='open' AND NEW.status IN('closed','handover') THEN phase:='closing';expected:=NEW.expected_cash;counted:=NEW.counted_cash;
 ELSE RETURN NEW; END IF;
 delta:=counted-expected;
 IF delta IS NULL OR delta=0 THEN RETURN NEW; END IF;
 title:=CASE phase WHEN 'opening' THEN 'فرق بداية الوردية رقم ' ELSE 'فرق إغلاق الوردية رقم ' END||NEW.shift_number||' - '||brand_finance_private.cash_employee_name(NEW.cafe_id,NEW.user_id);
 IF phase='opening' THEN
  doc:=gen_random_uuid();
  INSERT INTO public.bf_documents(id,cafe_id,kind,shift_id,account_id,total,paid,note,created_by) VALUES(doc,NEW.cafe_id,'shift_variance',NEW.id,NEW.account_id,abs(delta),abs(delta),title,NEW.user_id);
  PERFORM brand_finance_private.line(NEW.cafe_id,doc,NEW.account_id,greatest(delta,0),greatest(-delta,0));
  PERFORM brand_finance_private.line(NEW.cafe_id,doc,brand_finance_private.cash_pending_account(NEW.cafe_id),greatest(-delta,0),greatest(delta,0));
 ELSE
  SELECT d.id INTO doc FROM public.bf_documents d WHERE d.cafe_id=NEW.cafe_id AND d.shift_id=NEW.id AND d.kind='shift_variance' AND NOT EXISTS(SELECT 1 FROM public.bf_shift_cash_variances v WHERE v.document_id=d.id) ORDER BY d.number DESC LIMIT 1;
  IF doc IS NULL THEN RAISE EXCEPTION 'قيد فرق الإغلاق غير موجود'; END IF;
 END IF;
 SELECT s.user_id INTO previous_user FROM public.bf_shifts s WHERE s.cafe_id=NEW.cafe_id AND s.account_id=NEW.account_id AND s.id<>NEW.id AND (s.opened_at,s.shift_number)<(NEW.opened_at,NEW.shift_number) ORDER BY s.opened_at DESC,s.shift_number DESC LIMIT 1;
 IF phase='opening' THEN
  SELECT h.from_user_id,h.from_name INTO prior_handover FROM public.bf_cash_handovers h WHERE h.cafe_id=NEW.cafe_id AND h.receiving_drawer_id=NEW.account_id AND h.handover_type='next_shift' AND NOT EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts r WHERE r.handover_id=h.id) ORDER BY h.created_at,h.id LIMIT 1;
  IF FOUND THEN previous_user:=prior_handover.from_user_id;handover_previous_name:=prior_handover.from_name;END IF;
 END IF;
 INSERT INTO public.bf_shift_cash_variances(cafe_id,shift_id,shift_number,phase,drawer_id,drawer_name,employee_id,employee_name,previous_employee_id,previous_employee_name,expected_cash,counted_cash,difference,document_id)
 SELECT NEW.cafe_id,NEW.id,NEW.shift_number,phase,NEW.account_id,a.name,NEW.user_id,brand_finance_private.cash_employee_name(NEW.cafe_id,NEW.user_id),previous_user,coalesce(handover_previous_name,CASE WHEN previous_user IS NOT NULL THEN brand_finance_private.cash_employee_name(NEW.cafe_id,previous_user) END),expected,counted,delta,doc FROM public.bf_accounts a WHERE a.id=NEW.account_id RETURNING id INTO event_id;
 INSERT INTO public.bf_shift_cash_alerts(cafe_id,variance_id) VALUES(NEW.cafe_id,event_id);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.cashier_drawer(p_cafe uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE result uuid;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 SELECT id INTO result FROM public.bf_accounts WHERE cafe_id=p_cafe AND is_cashier_drawer AND deleted_at IS NULL
 ORDER BY (code='1001-CASHIER') DESC,id LIMIT 1;
 IF result IS NULL THEN
  INSERT INTO public.bf_accounts(cafe_id,code,name,kind,is_cashier_drawer,opening_recorded_at,opening_amount)
  VALUES(p_cafe,'1001-CASHIER','صندوق كاشير الفرع','cash',true,now(),0) RETURNING id INTO result;
 END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.cashier_drawer_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND NEW.is_cashier_drawer IS DISTINCT FROM OLD.is_cashier_drawer THEN RAISE EXCEPTION 'نوع صندوق الكاشير ثابت'; END IF;
 IF NEW.is_cashier_drawer AND NEW.deleted_at IS NULL AND (NOT NEW.active OR NEW.is_primary OR NEW.kind<>'cash') THEN RAISE EXCEPTION 'صندوق الكاشير مستقل ولا يمكن أرشفته أو اختياره خزينة رئيسية'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.close_cash_handover(p_cafe uuid, p_shift uuid, p_payload jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE sh public.bf_shifts%ROWTYPE; mode text:=coalesce(p_payload->>'handoverType','next_shift'); recipient uuid; recipient_name text; v_phone text; party uuid; doc uuid; receiving uuid; title text;
BEGIN
 SELECT * INTO sh FROM public.bf_shifts WHERE cafe_id=p_cafe AND id=p_shift AND (user_id=auth.uid() OR (p_payload->>'supervisorClose'='true' AND brand_finance_private.role_for(p_cafe) IN('owner','manager'))) AND status='closed' FOR UPDATE;
 IF NOT FOUND OR sh.counted_cash IS NULL THEN RAISE EXCEPTION 'أغلق ورديتك قبل تسجيل التسليم'; END IF;
 IF mode='no_cash' THEN
  IF sh.counted_cash<>0 THEN RAISE EXCEPTION 'لا يمكن إقفال الوردية دون تسليم إلا إذا كانت النقدية المعدودة صفرًا'; END IF;
  RETURN;
 END IF;
 IF mode NOT IN('next_shift','accountant','other') THEN RAISE EXCEPTION 'اختر طريقة تسليم النقدية'; END IF;
 IF mode='next_shift' THEN
  receiving:=CASE WHEN EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe AND id=sh.account_id AND is_cashier_drawer) THEN sh.account_id ELSE brand_finance_private.cashier_drawer(p_cafe) END;recipient_name:='موظف الوردية التالية';
  IF EXISTS(SELECT 1 FROM public.bf_cash_handovers h WHERE h.cafe_id=p_cafe AND h.receiving_drawer_id=receiving AND NOT EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts r WHERE r.handover_id=h.id)) THEN RAISE EXCEPTION 'يوجد تسليم سابق للصندوق لم يتم استلامه'; END IF;
  IF receiving<>sh.account_id AND EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe AND account_id=receiving AND status IN('open','handover')) THEN RAISE EXCEPTION 'صندوق الكاشير مستخدم في وردية أخرى اختر تسليم النقدية للمحاسب أو لمستلم آخر'; END IF;
 ELSE
  IF mode='accountant' THEN
   recipient:=nullif(p_payload->>'recipientUserId','')::uuid;
   SELECT s.name INTO recipient_name FROM public.bf_staff s JOIN public.profiles p ON p.id=s.user_id AND p.status='active' WHERE s.cafe_id=p_cafe AND s.user_id=recipient AND s.role IN('manager','accountant') AND s.active;
   IF recipient_name IS NULL THEN RAISE EXCEPTION 'اختر محاسبا نشطا من موظفي العلامة'; END IF;
   SELECT party_id INTO party FROM public.bf_cash_handover_parties WHERE cafe_id=p_cafe AND user_id=recipient;
  ELSE
   recipient_name:=btrim(coalesce(p_payload->>'recipientName',''));v_phone:=regexp_replace(translate(coalesce(p_payload->>'recipientPhone',''),'٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹','01234567890123456789'),'[[:space:]()-]','','g');
   IF v_phone ~ '^05[0-9]{8}$' THEN v_phone:='966'||substr(v_phone,2);ELSIF v_phone ~ '^\+[1-9][0-9]{7,14}$' THEN v_phone:=substr(v_phone,2); END IF;
   IF length(recipient_name) NOT BETWEEN 1 AND 100 OR v_phone !~ '^[1-9][0-9]{7,14}$' THEN RAISE EXCEPTION 'أدخل اسم المستلم ورقم جوال صحيحا'; END IF;
   SELECT party_id INTO party FROM public.bf_cash_handover_parties WHERE cafe_id=p_cafe AND user_id IS NULL AND bf_cash_handover_parties.phone=v_phone;
  END IF;
  IF party IS NULL THEN
   INSERT INTO public.bf_parties(cafe_id,name,kind,phone) VALUES(p_cafe,recipient_name,'employee',coalesce(v_phone,'')) RETURNING id INTO party;
   INSERT INTO public.bf_cash_handover_parties(cafe_id,user_id,phone,name,party_id) VALUES(p_cafe,recipient,v_phone,recipient_name,party);
  END IF;
 END IF;
 IF sh.counted_cash>0 AND (mode<>'next_shift' OR receiving<>sh.account_id) THEN
  doc:=gen_random_uuid();title:=left('تسليم نقدية الوردية رقم '||sh.shift_number||' من '||brand_finance_private.cash_employee_name(p_cafe,sh.user_id)||' إلى '||recipient_name,1000);
  INSERT INTO public.bf_documents(id,cafe_id,kind,shift_id,account_id,party_id,total,paid,note,created_by) VALUES(doc,p_cafe,'transfer',sh.id,sh.account_id,party,sh.counted_cash,sh.counted_cash,title,auth.uid());
  PERFORM brand_finance_private.line(p_cafe,doc,sh.account_id,0,sh.counted_cash);
  PERFORM brand_finance_private.line(p_cafe,doc,CASE WHEN mode='next_shift' THEN receiving ELSE brand_finance_private.account(p_cafe,'1030') END,sh.counted_cash,0,party);
 END IF;
 INSERT INTO public.bf_cash_handovers(cafe_id,shift_id,shift_number,drawer_id,drawer_name,receiving_drawer_id,receiving_drawer_name,amount,handover_type,from_user_id,from_name,recipient_user_id,recipient_name,recipient_phone,party_id,document_id)
 SELECT p_cafe,sh.id,sh.shift_number,sh.account_id,a.name,receiving,(SELECT name FROM public.bf_accounts WHERE id=receiving),sh.counted_cash,mode,sh.user_id,brand_finance_private.cash_employee_name(p_cafe,sh.user_id),recipient,recipient_name,v_phone,party,doc FROM public.bf_accounts a WHERE a.id=sh.account_id;
END $function$

