DECLARE d public.bf_documents%ROWTYPE;payment uuid:=gen_random_uuid();aid uuid;BEGIN
 SELECT * INTO d FROM public.bf_documents WHERE cafe_id=cafe AND id=invoice AND kind='sale' FOR UPDATE;
