CREATE OR REPLACE FUNCTION brand_finance_private.execute_before_inventory_catalog(p_cafe_id uuid, p_operation text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE sh public.bf_shifts%ROWTYPE; prior public.bf_requests%ROWTYPE; cfg public.bf_settings%ROWTYPE;
 amount numeric; available numeric; supplier_name text; supplier_phone text; note text; party uuid;
 doc uuid:=gen_random_uuid(); num bigint; ids uuid[]; matched integer; result jsonb;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_execute',p_operation);
 IF p_operation IS DISTINCT FROM 'supplier_payout' THEN RETURN brand_finance_private.execute_before_supplier_payout(p_cafe_id,p_operation,p_payload,p_request_id); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 PERFORM brand_finance_private.role_for(p_cafe_id);
 IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000 THEN RAISE EXCEPTION 'بيانات السداد غير صالحة'; END IF;
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.operation<>p_operation OR prior.payload IS DISTINCT FROM p_payload OR prior.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى'; END IF;
  RETURN prior.result||'{"duplicate":true}'::jsonb;
 END IF;
 SELECT * INTO sh FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND id=(p_payload->>'shiftId')::uuid AND user_id=auth.uid() AND status='open' FOR UPDATE;
 IF sh.id IS NULL THEN RAISE EXCEPTION 'السداد متاح من ورديتك المفتوحة فقط حدث الصفحة وتحقق من الوردية' USING ERRCODE='42501'; END IF;
 IF sh.supervisor_paused THEN RAISE EXCEPTION 'الوردية موقوفة إداريًا لا يمكن الصرف حتى استئنافها'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=sh.account_id AND kind='cash' AND active AND deleted_at IS NULL) THEN RAISE EXCEPTION 'صندوق الوردية غير متاح للسداد'; END IF;
 SELECT * INTO STRICT cfg FROM public.bf_settings WHERE cafe_id=p_cafe_id FOR UPDATE;
 IF cfg.closed_through IS NOT NULL AND (now() AT TIME ZONE 'Asia/Riyadh')::date<=cfg.closed_through THEN RAISE EXCEPTION 'الفترة المالية مقفلة'; END IF;
 supplier_name:=btrim(coalesce(p_payload->>'supplierName','')); supplier_phone:=btrim(coalesce(p_payload->>'supplierPhone','')); note:=btrim(coalesce(p_payload->>'note',''));
 IF jsonb_typeof(p_payload->'amount') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'أدخل مبلغًا صحيحًا للسداد'; END IF;
 amount:=(p_payload->>'amount')::numeric;
 IF amount<=0 OR amount>999999999 OR amount<>round(amount,2) OR length(supplier_name) NOT BETWEEN 1 AND 150 OR length(supplier_phone) NOT BETWEEN 5 AND 30 OR length(note)>500 THEN RAISE EXCEPTION 'راجع اسم المورد ورقم جواله ومبلغ السداد والبيان'; END IF;
 SELECT coalesce(sum(debit-credit),0) INTO available FROM public.bf_journal WHERE cafe_id=p_cafe_id AND account_id=sh.account_id;
 IF amount>available THEN RAISE EXCEPTION 'رصيد صندوق الوردية لا يكفي لهذا السداد'; END IF;
 IF jsonb_typeof(coalesce(p_payload->'attachmentIds','[]'::jsonb)) IS DISTINCT FROM 'array' OR jsonb_array_length(coalesce(p_payload->'attachmentIds','[]'::jsonb))>100 THEN RAISE EXCEPTION 'مرفقات السداد غير صالحة'; END IF;
 SELECT coalesce(array_agg(value::uuid),'{}'::uuid[]) INTO ids FROM jsonb_array_elements_text(coalesce(p_payload->'attachmentIds','[]'::jsonb));
 IF cardinality(ids)<>(SELECT count(DISTINCT x) FROM unnest(ids) x) THEN RAISE EXCEPTION 'المرفق مكرر في السداد'; END IF;
 PERFORM 1 FROM public.bf_shift_attachments WHERE id=ANY(ids) AND cafe_id=p_cafe_id AND shift_id=sh.id AND uploader_id=auth.uid() AND uploaded AND document_id IS NULL ORDER BY id FOR UPDATE;
 GET DIAGNOSTICS matched=ROW_COUNT;
 IF matched<>cardinality(ids) THEN RAISE EXCEPTION 'أكمل رفع المرفقات وتأكد أنها تخص ورديتك' USING ERRCODE='42501'; END IF;
 SELECT id INTO party FROM public.bf_parties WHERE cafe_id=p_cafe_id AND kind='supplier' AND name=supplier_name AND phone=supplier_phone AND active ORDER BY id LIMIT 1;
 IF party IS NULL THEN INSERT INTO public.bf_parties(cafe_id,kind,name,phone) VALUES(p_cafe_id,'supplier',supplier_name,supplier_phone) RETURNING id INTO party; END IF;
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,shift_id,account_id,total,paid,note,created_by)
 VALUES(doc,p_cafe_id,'settlement',party,sh.id,sh.account_id,amount,amount,note,auth.uid()) RETURNING number INTO num;
 INSERT INTO public.bf_shift_supplier_payouts VALUES(doc,p_cafe_id,sh.id,supplier_name,supplier_phone);
 PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'2000'),amount,0,party);
 PERFORM brand_finance_private.line(p_cafe_id,doc,sh.account_id,0,amount);
 UPDATE public.bf_shift_attachments SET document_id=doc WHERE id=ANY(ids);
 result:=jsonb_build_object('id',doc,'number',num,'status','posted');
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,p_operation,p_payload,result,auth.uid());
 INSERT INTO public.bf_treasury_audit(cafe_id,actor_id,operation,entity_id,after_data) VALUES(p_cafe_id,auth.uid(),'supplier_payout',doc,jsonb_build_object('shiftId',sh.id,'accountId',sh.account_id,'amount',amount,'supplierName',supplier_name));
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.execute_before_own_shift_purchase(p_cafe_id uuid, p_operation text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<inventory_item>>
DECLARE old public.bf_requests%ROWTYPE; prior public.bf_items%ROWTYPE; result jsonb; saved uuid; uid uuid; unit_name text; barcode text; code text; image_path text; links jsonb; l jsonb; q numeric; product uuid; mode text;
BEGIN
 IF p_operation<>'item' THEN RETURN brand_finance_private.execute_before_inventory_catalog(p_cafe_id,p_operation,p_payload,p_request_id); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 IF brand_finance_private.role_for(p_cafe_id) NOT IN('owner','manager','warehouse') THEN RAISE EXCEPTION 'لا تملك صلاحية إدارة المخزون' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000 OR p_payload::text ~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'Invalid inventory command'; END IF;
 SELECT * INTO old FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF old.operation<>p_operation OR old.payload<>p_payload OR old.created_by<>auth.uid() THEN RAISE EXCEPTION 'Request identifier conflict'; END IF; RETURN old.result||'{"duplicate":true}'::jsonb; END IF;
 IF EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe_id AND closed_through>=(now() AT TIME ZONE 'Asia/Riyadh')::date) THEN RAISE EXCEPTION 'الفترة المالية مقفلة'; END IF;
 saved:=coalesce(nullif(p_payload->>'id','')::uuid,gen_random_uuid());
 SELECT * INTO prior FROM public.bf_items WHERE cafe_id=p_cafe_id AND id=saved FOR UPDATE;
 IF p_payload ? 'id' AND NOT FOUND THEN RAISE EXCEPTION 'الصنف غير متاح'; END IF;
 PERFORM brand_finance_private.inventory_catalog_seed(p_cafe_id);
 IF nullif(p_payload->>'unitId','') IS NOT NULL THEN
  uid:=(p_payload->>'unitId')::uuid;SELECT name INTO unit_name FROM public.bf_item_units WHERE cafe_id=p_cafe_id AND id=uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'وحدة القياس غير متاحة'; END IF;
 ELSE
  unit_name:=coalesce(nullif(btrim(p_payload->>'unit'),''),prior.unit,'وحدة');
  INSERT INTO public.bf_item_units(cafe_id,name) VALUES(p_cafe_id,unit_name) ON CONFLICT(cafe_id,name) DO UPDATE SET name=excluded.name RETURNING id INTO uid;
 END IF;
 IF prior.id IS NOT NULL AND uid IS DISTINCT FROM prior.unit_id AND EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=p_cafe_id AND item_id=saved) THEN RAISE EXCEPTION 'لا يمكن تغيير وحدة صنف عليه حركات مخزنية'; END IF;
 barcode:=coalesce(nullif(btrim(p_payload->>'barcode'),''),prior.barcode);
 IF barcode IS NULL THEN
  FOR attempt IN 1..32 LOOP
   barcode:=lpad(floor(random()*1000000)::integer::text,6,'0');
   EXIT WHEN NOT EXISTS(SELECT 1 FROM public.bf_items i WHERE i.cafe_id=p_cafe_id AND i.barcode=inventory_item.barcode);
   barcode:=NULL;
  END LOOP;
  IF barcode IS NULL THEN
   -- A free code is zero or follows an existing code; never materialize the entire namespace
   SELECT lpad(candidate.n::text,6,'0') INTO barcode FROM (
    SELECT 0 n UNION SELECT i.barcode::integer+1 FROM public.bf_items i
    WHERE i.cafe_id=p_cafe_id AND i.barcode ~ '^[0-9]{6}$' AND i.barcode<'999999'
   ) candidate WHERE NOT EXISTS(SELECT 1 FROM public.bf_items i WHERE i.cafe_id=p_cafe_id AND i.barcode=lpad(candidate.n::text,6,'0')) ORDER BY candidate.n LIMIT 1;
  END IF;
  IF barcode IS NULL THEN RAISE EXCEPTION 'لا يتوفر باركود تلقائي أدخل باركودًا مختلفًا'; END IF;
 END IF;
 IF barcode !~ '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$' THEN RAISE EXCEPTION 'الباركود غير صالح'; END IF;
 IF EXISTS(SELECT 1 FROM public.bf_items i WHERE i.cafe_id=p_cafe_id AND i.barcode=inventory_item.barcode AND i.id<>saved) THEN RAISE EXCEPTION 'الباركود مستخدم لصنف آخر'; END IF;
 code:=coalesce(nullif(btrim(p_payload->>'sku'),''),prior.sku,barcode);
 IF EXISTS(SELECT 1 FROM public.bf_items i WHERE i.cafe_id=p_cafe_id AND i.sku=code AND i.id<>saved) THEN RAISE EXCEPTION 'رمز الصنف مستخدم'; END IF;
 mode:=coalesce(p_payload->>'costMode',prior.cost_mode,'full');
 image_path:=CASE WHEN p_payload ? 'imagePath' THEN nullif(p_payload->>'imagePath','') ELSE prior.image_path END;
 IF p_payload ? 'productLinks' THEN links:=p_payload->'productLinks';
 ELSIF p_payload ? 'menuProductId' THEN links:=CASE WHEN nullif(p_payload->>'menuProductId','') IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object('productId',p_payload->>'menuProductId','quantity',1)) END;
 ELSE SELECT coalesce(jsonb_agg(jsonb_build_object('productId',product_id,'quantity',quantity)),'[]'::jsonb) INTO links FROM public.bf_item_product_links WHERE cafe_id=p_cafe_id AND item_id=saved; END IF;
 IF jsonb_typeof(links) IS DISTINCT FROM 'array' OR jsonb_array_length(links)>200 OR (SELECT count(DISTINCT value->>'productId') FROM jsonb_array_elements(links))<>jsonb_array_length(links) THEN RAISE EXCEPTION 'روابط المنتجات غير صالحة أو مكررة'; END IF;
 INSERT INTO public.bf_items(id,cafe_id,name,sku,unit,unit_id,barcode,image_path,cost_mode,min_quantity)
 VALUES(saved,p_cafe_id,btrim(p_payload->>'name'),code,unit_name,uid,barcode,image_path,mode,coalesce((p_payload->>'minQuantity')::numeric,prior.min_quantity,0))
 ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,sku=excluded.sku,unit=excluded.unit,unit_id=excluded.unit_id,barcode=excluded.barcode,image_path=excluded.image_path,cost_mode=excluded.cost_mode,min_quantity=excluded.min_quantity,menu_product_id=NULL;
 DELETE FROM public.bf_item_product_links WHERE cafe_id=p_cafe_id AND item_id=saved;
 FOR l IN SELECT value FROM jsonb_array_elements(links) LOOP
  product:=nullif(l->>'productId','')::uuid;q:=(l->>'quantity')::numeric;
  IF q IS NULL OR q<=0 OR q>1000000 OR q<>round(q,3) OR NOT EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id=p_cafe_id AND id=product AND deleted_at IS NULL) THEN RAISE EXCEPTION 'اختر منتجًا وكمية استهلاك صحيحة'; END IF;
  INSERT INTO public.bf_item_product_links(cafe_id,item_id,product_id,quantity) VALUES(p_cafe_id,saved,product,q);
 END LOOP;
 result:=jsonb_build_object('id',saved,'barcode',barcode);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,p_operation,p_payload,result,auth.uid());
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.execute_before_supplier_payout(p_cafe_id uuid, p_operation text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; k text; mapped jsonb; prior public.bf_requests%ROWTYPE; source_account public.bf_accounts%ROWTYPE; target_account public.bf_accounts%ROWTYPE; answer jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 r:=brand_finance_private.role_for(p_cafe_id);
 IF p_operation='treasury' AND EXISTS(SELECT 1 FROM public.bf_cash_handover_parties WHERE cafe_id=p_cafe_id AND party_id=nullif(p_payload->>'partyId','')::uuid) THEN RAISE EXCEPTION 'استلم عهدة تسليم الوردية من سجل التسليم الخاص بها'; END IF;
 -- Retries of pre-migration requests remain no-ops instead of creating a second document
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id AND operation=p_operation;
 IF FOUND THEN
  IF prior.payload IS DISTINCT FROM p_payload OR prior.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Request identifier conflict'; END IF;
  RETURN prior.result||'{"duplicate":true}'::jsonb;
 END IF;
 IF p_operation='account' AND p_payload->>'kind' IN('cash','bank','pos') THEN
  mapped:=p_payload-'active';
  IF p_payload->>'kind'='pos' AND nullif(p_payload->>'linkedBankId','') IS NULL THEN
   PERFORM brand_finance_private.treasury_seed(p_cafe_id);
   mapped:=mapped||jsonb_build_object('linkedBankId',(SELECT id FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND code='1010' AND kind='bank' AND active));
  END IF;
  RETURN public.brand_finance_treasury_execute(p_cafe_id,'account_save',mapped,p_request_id);
 ELSIF p_operation='treasury' THEN
  k:=p_payload->>'kind';
  SELECT * INTO source_account FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=nullif(p_payload->>'accountId','')::uuid;
  SELECT * INTO target_account FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=nullif(p_payload->>'toAccountId','')::uuid;
  mapped:=p_payload;
  IF length(btrim(coalesce(mapped->>'note','')))<3 THEN mapped:=mapped||jsonb_build_object('note','سند خزينة'); END IF;
  IF source_account.kind='pos' AND k='transfer' THEN
   PERFORM brand_finance_private.treasury_seed(p_cafe_id);
   SELECT * INTO source_account FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=source_account.id;
   IF target_account.kind IS DISTINCT FROM 'bank' OR target_account.id IS DISTINCT FROM source_account.linked_bank_id THEN RAISE EXCEPTION 'حوّل الشبكة إلى حسابها البنكي المرتبط'; END IF;
   mapped:=mapped||jsonb_build_object('fee',0,'reference',coalesce(nullif(p_payload->>'reference',''),'LEGACY-'||p_request_id::text));
   RETURN public.brand_finance_treasury_execute(p_cafe_id,'pos_settle',mapped,p_request_id);
  ELSIF source_account.kind IN('cash','bank','pos') AND NOT (k='transfer' AND target_account.kind='employee') THEN
   IF k='opening' THEN RETURN public.brand_finance_treasury_execute(p_cafe_id,'opening',p_payload,p_request_id);
   ELSIF k='transfer' THEN RETURN public.brand_finance_treasury_execute(p_cafe_id,'transfer',mapped,p_request_id);
   ELSE
    IF nullif(mapped->>'counterAccountId','') IS NULL THEN mapped:=mapped||jsonb_build_object('counterAccountId',brand_finance_private.account(p_cafe_id,CASE WHEN k='receipt' THEN '4000' ELSE '5100' END)); END IF;
    RETURN public.brand_finance_treasury_execute(p_cafe_id,'voucher',mapped,p_request_id);
   END IF;
  END IF;
 ELSIF p_operation='journal' AND EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'lines') l JOIN public.bf_accounts a ON a.id=nullif(l->>'accountId','')::uuid AND a.cafe_id=p_cafe_id WHERE a.kind IN('cash','bank','pos')) THEN
  RAISE EXCEPTION 'استخدم سندات الخزينة أو اطلب تصحيح الإدارة' USING ERRCODE='42501';
 ELSIF p_operation IN('opening_balances','finance_reset') THEN
  RAISE EXCEPTION 'استخدم إجراءات الخزينة المعتمدة' USING ERRCODE='42501';
 END IF;
 answer:=brand_finance_private.execute_before_treasury(p_cafe_id,p_operation,p_payload,p_request_id);
 IF p_operation='treasury' THEN
  INSERT INTO public.bf_treasury_audit(cafe_id,actor_id,operation,entity_id,after_data) VALUES(p_cafe_id,auth.uid(),'legacy_custody',(answer->>'id')::uuid,p_payload||answer);
 END IF;
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.execute_before_treasury(p_cafe_id uuid, p_operation text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
DECLARE is_butcher boolean; butcher_unit jsonb; butcher_factor numeric; approval public.bf_refund_requests%ROWTYPE; canonical jsonb; result_status text; r text; pos integer:=0; old public.bf_requests%ROWTYPE; cfg public.bf_settings%ROWTYPE; d public.bf_documents%ROWTYPE; original public.bf_documents%ROWTYPE; sh public.bf_shifts%ROWTYPE; entry jsonb; prod record; it public.bf_items%ROWTYPE; id uuid:=gen_random_uuid(); aid uuid; aid2 uuid; pid uuid; wid uuid; iid uuid; sid uuid; uid uuid; qty numeric; price numeric; amount numeric; cost numeric:=0; subtotal numeric:=0; discount numeric:=0; tax numeric:=0; total numeric:=0; paid numeric:=0; net numeric; expected numeric; counted numeric; remaining numeric; tax_left numeric; line_tax numeric; note text:=coalesce(p_payload->>'note',''); result jsonb; kind text; n bigint; lines jsonb:='[]'; saved record;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 r:=brand_finance_private.role_for(p_cafe_id);
 SELECT coalesce(business_category='butcher_shops',false) INTO is_butcher FROM public.cafes WHERE cafes.id=p_cafe_id;
 SELECT NULL::uuid AS id,NULL::text AS name,NULL::numeric AS price,NULL::uuid AS item_id INTO prod;
 IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000 OR p_payload::text ~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'Invalid command'; END IF;
 -- One tenant posting lock gives deterministic document, stock and account ordering.
 SELECT * INTO old FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF old.operation<>p_operation OR old.payload<>p_payload OR old.created_by<>auth.uid() THEN RAISE EXCEPTION 'Request identifier conflict'; END IF; RETURN old.result||'{"duplicate":true}'::jsonb; END IF;
 IF r='cashier' AND p_operation NOT IN('sale','refund','shift_open','shift_close','shift_handover','shift_accept') THEN RAISE EXCEPTION 'Finance manager required' USING ERRCODE='42501'; END IF;
 IF p_operation IN('refund_approve','refund_reject') AND (r<>'owner' OR NOT EXISTS(SELECT 1 FROM public.cafes c WHERE c.id=p_cafe_id AND c.owner_user_id=auth.uid())) THEN RAISE EXCEPTION 'Brand owner approval required' USING ERRCODE='42501'; END IF;
 IF p_operation IN('settings','staff') AND r<>'owner' THEN RAISE EXCEPTION 'Finance owner required' USING ERRCODE='42501'; END IF;
 PERFORM brand_finance_private.seed(p_cafe_id);
 SELECT * INTO STRICT cfg FROM public.bf_settings WHERE cafe_id=p_cafe_id FOR UPDATE;
 IF cfg.closed_through IS NOT NULL AND (now() AT TIME ZONE 'Asia/Riyadh')::date<=cfg.closed_through AND p_operation NOT IN('settings','staff') THEN RAISE EXCEPTION 'الفترة المالية مقفلة'; END IF;
 aid:=nullif(p_payload->>'accountId','')::uuid; pid:=nullif(p_payload->>'partyId','')::uuid; wid:=nullif(p_payload->>'warehouseId','')::uuid; iid:=nullif(p_payload->>'itemId','')::uuid; sid:=nullif(p_payload->>'shiftId','')::uuid;
 IF aid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE bf_accounts.id=aid AND cafe_id=p_cafe_id AND active) THEN RAISE EXCEPTION 'Invalid account'; END IF;
 IF aid IS NOT NULL AND p_operation IN('purchase','settlement') AND NOT EXISTS(SELECT 1 FROM public.bf_accounts a WHERE a.id=aid AND a.cafe_id=p_cafe_id AND a.kind IN('cash','bank','pos')) THEN RAISE EXCEPTION 'Treasury payment account required'; END IF;
 IF pid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE bf_parties.id=pid AND cafe_id=p_cafe_id AND active) THEN RAISE EXCEPTION 'Invalid party'; END IF;
 IF wid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE bf_warehouses.id=wid AND cafe_id=p_cafe_id AND active) THEN RAISE EXCEPTION 'Invalid warehouse'; END IF;
 IF iid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_items WHERE bf_items.id=iid AND cafe_id=p_cafe_id AND active) THEN RAISE EXCEPTION 'Invalid item'; END IF;
 IF p_operation='settings' THEN
  PERFORM brand_finance_private.assert_period_close(p_cafe_id,p_payload,p_request_id);
  IF nullif(p_payload->>'closedThrough','')::date < cfg.closed_through OR (cfg.closed_through IS NOT NULL AND nullif(p_payload->>'closedThrough','') IS NULL) THEN RAISE EXCEPTION 'Closed period cannot be reopened'; END IF;
  UPDATE public.bf_settings SET vat_rate=(p_payload->>'vatRate')::numeric,tax_inclusive=(p_payload->>'taxInclusive')::boolean,closed_through=nullif(p_payload->>'closedThrough','')::date WHERE cafe_id=p_cafe_id; id:=p_cafe_id;
 ELSIF p_operation='staff' THEN
  IF nullif(p_payload->>'userId','') IS NOT NULL THEN
   SELECT s.user_id INTO uid FROM public.bf_staff s WHERE s.cafe_id=p_cafe_id AND s.user_id=(p_payload->>'userId')::uuid;
  ELSE
   SELECT u.id INTO uid FROM auth.users u JOIN public.profiles p ON p.id=u.id AND p.status='active' WHERE lower(u.email)=lower(btrim(p_payload->>'email'));
  END IF;
  IF uid IS NULL THEN RAISE EXCEPTION 'الموظف يحتاج حسابا مسجلا ونشطا بهذا البريد'; END IF;
  IF NOT coalesce((p_payload->>'active')::boolean,true) AND EXISTS(SELECT 1 FROM public.bf_shifts s WHERE s.cafe_id=p_cafe_id AND s.status IN('open','handover') AND (s.user_id=uid OR s.handover_to=uid)) THEN RAISE EXCEPTION 'أغلق وردية الموظف أو أكمل التسليم قبل إيقاف صلاحياته'; END IF;
  INSERT INTO public.bf_staff(cafe_id,user_id,name,role,active) VALUES(p_cafe_id,uid,btrim(p_payload->>'name'),p_payload->>'role',coalesce((p_payload->>'active')::boolean,true)) ON CONFLICT(cafe_id,user_id) DO UPDATE SET name=excluded.name,role=excluded.role,active=excluded.active; id:=uid;
 ELSIF p_operation='party' THEN
  id:=coalesce(nullif(p_payload->>'id','')::uuid,id);
  IF EXISTS(SELECT 1 FROM public.bf_parties p WHERE p.id=id AND p.cafe_id<>p_cafe_id) THEN RAISE EXCEPTION 'Invalid party'; END IF;
  INSERT INTO public.bf_parties(id,cafe_id,name,kind,phone,email,tax_number,active) VALUES(id,p_cafe_id,btrim(p_payload->>'name'),p_payload->>'kind',coalesce(p_payload->>'phone',''),coalesce(p_payload->>'email',''),coalesce(p_payload->>'taxNumber',''),coalesce((p_payload->>'active')::boolean,true)) ON CONFLICT ON CONSTRAINT bf_parties_cafe_id_id_key DO UPDATE SET name=excluded.name,phone=excluded.phone,email=excluded.email,tax_number=excluded.tax_number,active=excluded.active;
 ELSIF p_operation='account' THEN
  IF p_payload->>'kind' NOT IN('cash','bank','pos','employee') THEN RAISE EXCEPTION 'Invalid treasury account type'; END IF;
  INSERT INTO public.bf_accounts(id,cafe_id,name,code,kind) VALUES(id,p_cafe_id,btrim(p_payload->>'name'),'U-'||id::text,p_payload->>'kind');
 ELSIF p_operation='warehouse' THEN INSERT INTO public.bf_warehouses(id,cafe_id,name) VALUES(id,p_cafe_id,btrim(p_payload->>'name'));
 ELSIF p_operation='item' THEN
  id:=coalesce(nullif(p_payload->>'id','')::uuid,id); uid:=nullif(p_payload->>'menuProductId','')::uuid;
  IF uid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id=p_cafe_id AND menu_products.id=uid AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Invalid menu product'; END IF;
  INSERT INTO public.bf_items(id,cafe_id,name,sku,unit,menu_product_id,min_quantity) VALUES(id,p_cafe_id,btrim(p_payload->>'name'),btrim(p_payload->>'sku'),coalesce(nullif(p_payload->>'unit',''),'وحدة'),uid,coalesce((p_payload->>'minQuantity')::numeric,0)) ON CONFLICT ON CONSTRAINT bf_items_cafe_id_id_key DO UPDATE SET name=excluded.name,sku=excluded.sku,unit=excluded.unit,min_quantity=excluded.min_quantity;
 ELSIF p_operation='shift_open' THEN
  IF NOT EXISTS(SELECT 1 FROM public.bf_accounts dr WHERE dr.cafe_id=p_cafe_id AND dr.id=aid AND dr.is_cashier_drawer AND dr.active) THEN RAISE EXCEPTION 'اختر صندوق كاشير نشطا تابعا للعلامة'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND bf_accounts.id=aid AND bf_accounts.kind='cash' AND active) THEN RAISE EXCEPTION 'Cash drawer required'; END IF;
  amount:=round((p_payload->>'openingCash')::numeric,2);
  SELECT coalesce(sum(debit-credit),0) INTO expected FROM public.bf_journal WHERE cafe_id=p_cafe_id AND account_id=aid;
  IF amount IS NULL OR amount<0 THEN RAISE EXCEPTION 'أدخل النقدية المعدودة عند بداية الوردية'; END IF;
  INSERT INTO public.bf_shifts(id,cafe_id,user_id,account_id,opening_cash,expected_cash) VALUES(id,p_cafe_id,auth.uid(),aid,amount,amount);
 ELSIF p_operation IN('shift_close','shift_handover','shift_accept') THEN
  SELECT * INTO sh FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND bf_shifts.id=sid FOR UPDATE;
  IF sh.id IS NULL THEN RAISE EXCEPTION 'Shift not found'; END IF;
  counted:=round((p_payload->>'countedCash')::numeric,2); IF counted IS NULL OR counted<0 THEN RAISE EXCEPTION 'Cash count required'; END IF;
  SELECT coalesce(sum(debit-credit),0) INTO expected FROM public.bf_journal WHERE cafe_id=p_cafe_id AND account_id=sh.account_id;
  IF p_operation='shift_accept' THEN
   IF sh.status<>'handover' OR sh.handover_to<>auth.uid() OR counted<>sh.counted_cash OR counted<>expected THEN RAISE EXCEPTION 'استلام الوردية يتطلب مطابقة المبلغ المسلم'; END IF;
   UPDATE public.bf_shifts SET status='closed',closed_at=now() WHERE bf_shifts.id=sh.id;
   INSERT INTO public.bf_shifts(id,cafe_id,user_id,account_id,opening_cash,expected_cash) VALUES(id,p_cafe_id,auth.uid(),sh.account_id,counted,counted);
  ELSE
   IF p_operation='shift_close' AND p_payload->>'supervisorClose'='true' THEN
 IF r NOT IN('owner','manager') OR sh.status NOT IN('open','handover') OR length(btrim(coalesce(p_payload->>'reason',''))) NOT BETWEEN 3 AND 1000 OR p_payload->>'acknowledgeOffline' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'الإقفال الإداري يتطلب صلاحية إدارية وسبب الإجراء وتأكيد مراجعة الفواتير المحلية' USING ERRCODE='42501'; END IF;
 ELSE IF sh.user_id<>auth.uid() OR sh.status<>'open' THEN RAISE EXCEPTION 'Only current cashier can close own open shift'; END IF; END IF;
   IF p_operation='shift_handover' THEN
    IF EXISTS(SELECT 1 FROM public.bf_accounts drawer WHERE drawer.id=sh.account_id AND drawer.is_cashier_drawer) THEN RAISE EXCEPTION 'اختر طريقة التسليم من إجراء إغلاق الوردية'; END IF;
    uid:=(p_payload->>'toUserId')::uuid;
    IF uid=auth.uid() OR NOT(EXISTS(SELECT 1 FROM public.bf_staff WHERE cafe_id=p_cafe_id AND user_id=uid AND active AND role IN('manager','cashier')) OR EXISTS(SELECT 1 FROM public.cafes WHERE cafes.id=p_cafe_id AND owner_user_id=uid)) THEN RAISE EXCEPTION 'Invalid handover recipient'; END IF;
   END IF;
   IF sh.status='handover' AND (counted IS DISTINCT FROM sh.counted_cash OR counted<>expected) THEN RAISE EXCEPTION 'وردية التسليم مقفلة نقديًا يجب مطابقة المبلغ المسجل قبل إكمال الإقفال الإداري'; END IF;
   IF counted<>expected THEN
    INSERT INTO public.bf_documents(id,cafe_id,kind,shift_id,account_id,total,paid,note,created_by) VALUES(id,p_cafe_id,'shift_variance',sh.id,sh.account_id,abs(counted-expected),abs(counted-expected),left('فرق إغلاق الوردية رقم '||sh.shift_number||' - '||brand_finance_private.cash_employee_name(p_cafe_id,auth.uid())||' - '||note,1000),auth.uid());
    PERFORM brand_finance_private.line(p_cafe_id,id,sh.account_id,greatest(counted-expected,0),greatest(expected-counted,0));
    PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.cash_pending_account(p_cafe_id),greatest(expected-counted,0),greatest(counted-expected,0));
   END IF;
   UPDATE public.bf_shifts SET expected_cash=CASE WHEN sh.status='handover' THEN sh.expected_cash ELSE expected END,counted_cash=counted,variance=CASE WHEN sh.status='handover' THEN sh.variance ELSE counted-expected END,status=CASE WHEN p_operation='shift_close' THEN 'closed' ELSE 'handover' END,closed_at=CASE WHEN p_operation='shift_close' THEN now() ELSE NULL END,handover_to=uid,note=left(note,1000) WHERE bf_shifts.id=sh.id; id:=sh.id;
 IF p_operation='shift_close' AND p_payload->>'supervisorClose'='true' THEN
 INSERT INTO public.bf_shift_supervision(cafe_id,shift_id,action,reason,actor_id,actor_name,request_id,payload,result)
 VALUES(p_cafe_id,sh.id,'close',btrim(p_payload->>'reason'),auth.uid(),brand_finance_private.cash_employee_name(p_cafe_id,auth.uid()),p_request_id,p_payload,jsonb_build_object('id',sh.id));
 END IF;

   IF p_operation='shift_close' THEN PERFORM brand_finance_private.close_cash_handover(p_cafe_id,sh.id,p_payload); END IF;
  END IF;
 ELSIF p_operation IN('sale','purchase') THEN
  IF jsonb_typeof(p_payload->'lines')<>'array' OR jsonb_array_length(p_payload->'lines') NOT BETWEEN 1 AND 100 OR wid IS NULL THEN RAISE EXCEPTION 'Invoice lines and warehouse required'; END IF;
  IF p_payload ? 'vatRate' OR p_payload ? 'taxInclusive' THEN
   IF p_operation<>'sale' OR r NOT IN('owner','manager') THEN RAISE EXCEPTION 'Invoice tax override requires financial management' USING ERRCODE='42501'; END IF;
   IF jsonb_typeof(p_payload->'vatRate') IS DISTINCT FROM 'number' OR jsonb_typeof(p_payload->'taxInclusive') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid invoice tax options'; END IF;
   amount:=(p_payload->>'vatRate')::numeric;
   IF amount<0 OR amount>100 OR amount<>round(amount,2) THEN RAISE EXCEPTION 'Invalid invoice tax rate'; END IF;
   cfg.vat_rate:=amount; cfg.tax_inclusive:=(p_payload->>'taxInclusive')::boolean;
  END IF;
  IF p_operation='sale' THEN

   -- cfg is locked and any authorized invoice override has already been applied
   -- A committed request was returned earlier, before comparing current tax settings
   IF p_payload ?| ARRAY['offlineExpectedVatRate','offlineExpectedTaxInclusive','localReceiptReference','localCreatedAt'] THEN
    IF jsonb_typeof(p_payload->'offlineExpectedVatRate') IS DISTINCT FROM 'number'
       OR jsonb_typeof(p_payload->'offlineExpectedTaxInclusive') IS DISTINCT FROM 'boolean'
       OR jsonb_typeof(p_payload->'localReceiptReference') IS DISTINCT FROM 'string'
       OR jsonb_typeof(p_payload->'localCreatedAt') IS DISTINCT FROM 'string' THEN
     RAISE EXCEPTION 'بيانات مطابقة الفاتورة المحلية غير مكتملة';
    END IF;
    IF (p_payload->>'offlineExpectedVatRate')::numeric IS DISTINCT FROM cfg.vat_rate
       OR (p_payload->>'offlineExpectedTaxInclusive')::boolean IS DISTINCT FROM cfg.tax_inclusive THEN
     RAISE EXCEPTION 'تغيرت ضريبة الفاتورة المحلية احتفظ بالإيصال وراجع مسؤول العلامة لتسوية التعارض';
    END IF;
    IF length(p_payload->>'localReceiptReference')>96
       OR (p_payload->>'localReceiptReference') !~ '^L-[A-Za-z0-9-]+$'
       OR (p_payload->>'localCreatedAt') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
       OR NOT isfinite((p_payload->>'localCreatedAt')::timestamptz) THEN
     RAISE EXCEPTION 'مرجع الفاتورة المحلية أو وقت حفظها غير صالح';
    END IF;
   END IF;
   SELECT * INTO sh FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND bf_shifts.id=sid AND user_id=auth.uid() AND status='open' FOR UPDATE;
   IF sh.supervisor_paused THEN RAISE EXCEPTION 'الوردية موقوفة إداريًا احتفظ بالفاتورة وأعد المزامنة بعد استئناف الوردية'; END IF;
   IF sh.id IS NULL THEN
    IF NOT is_butcher OR sid IS NOT NULL THEN RAISE EXCEPTION 'ابدأ وردية قبل تسجيل المبيعات'; END IF;
    IF EXISTS(SELECT 1 FROM public.bf_shifts active_shift WHERE active_shift.cafe_id=p_cafe_id AND active_shift.user_id=auth.uid() AND active_shift.status IN('open','handover')) THEN
     RAISE EXCEPTION 'لديك وردية قائمة حدث الكاشير وأكمل البيع من ورديتك';
    END IF;
    IF aid IS NULL THEN RAISE EXCEPTION 'اختر حساب استلام قيمة البيع'; END IF;
    IF EXISTS(SELECT 1 FROM public.bf_accounts a WHERE a.id=aid AND a.kind='cash') AND
       (NOT EXISTS(SELECT 1 FROM public.bf_accounts a WHERE a.id=aid AND a.cafe_id=p_cafe_id AND a.is_cashier_drawer AND a.active)
        OR EXISTS(SELECT 1 FROM public.bf_shifts held WHERE held.cafe_id=p_cafe_id AND held.account_id=aid AND held.status IN('open','handover'))) THEN
     RAISE EXCEPTION 'اختر صندوق كاشير متاحًا لا يرتبط بوردية أخرى';
    END IF;
   END IF;
   IF aid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND bf_accounts.id=aid AND bf_accounts.kind IN('cash','bank','pos')) THEN RAISE EXCEPTION 'Invalid sale payment account'; END IF;
   IF EXISTS(SELECT 1 FROM public.bf_accounts WHERE bf_accounts.id=aid AND bf_accounts.kind='cash') AND aid<>sh.account_id THEN RAISE EXCEPTION 'Cash sale must use shift drawer'; END IF;
   IF pid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE bf_parties.id=pid AND bf_parties.kind='customer') THEN RAISE EXCEPTION 'Customer required'; END IF;
  ELSE
   IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE bf_parties.id=pid AND cafe_id=p_cafe_id AND bf_parties.kind='supplier') THEN RAISE EXCEPTION 'Supplier required'; END IF;
  END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(p_payload->'lines') LOOP
   qty:=(entry->>'quantity')::numeric; IF qty IS NULL OR qty<=0 OR qty>1000000 OR qty<>round(qty,3) THEN RAISE EXCEPTION 'Invalid quantity'; END IF;
   IF p_operation='sale' THEN
    SELECT mp.id,mp.name,mp.price,mp.butcher_details,bi.id item_id INTO prod FROM public.menu_products mp LEFT JOIN public.bf_items bi ON bi.menu_product_id=mp.id AND bi.cafe_id=p_cafe_id AND bi.active WHERE mp.id=(entry->>'productId')::uuid AND mp.cafe_id=p_cafe_id AND mp.deleted_at IS NULL AND mp.available FOR SHARE OF mp;
    IF prod.id IS NULL THEN RAISE EXCEPTION 'الصنف غير متاح للبيع'; END IF; price:=prod.price; iid:=prod.item_id;
    butcher_unit:=NULL; butcher_factor:=1;
    IF is_butcher AND prod.butcher_details IS NOT NULL THEN
     SELECT value INTO butcher_unit FROM jsonb_array_elements(prod.butcher_details->'units') WHERE value->>'id'=entry->>'unitId';
     IF butcher_unit IS NULL THEN RAISE EXCEPTION 'اختر وحدة بيع متاحة لهذا المنتج'; END IF;
     price:=(butcher_unit->>'price')::numeric;
     prod.name:=prod.name||' · '||(butcher_unit->>'label');
     butcher_factor:=brand_finance_private.butcher_stock_factor(prod.butcher_details->'units'->0->>'id',butcher_unit->>'id');
     IF butcher_factor IS NULL AND EXISTS(SELECT 1 FROM public.bf_item_product_links l JOIN public.bf_items i ON i.id=l.item_id AND i.cafe_id=l.cafe_id AND i.active WHERE l.cafe_id=p_cafe_id AND l.product_id=prod.id) THEN
      RAISE EXCEPTION 'وحدة البيع لا تتوافق مع وحدة المنتج المرتبط بالمخزون';
     END IF;
     butcher_factor:=coalesce(butcher_factor,1);
    ELSIF nullif(entry->>'unitId','') IS NOT NULL THEN RAISE EXCEPTION 'هذا المنتج لا يدعم وحدة البيع المحددة';
    END IF;

    IF (entry->>'expectedUnitPrice')::numeric IS DISTINCT FROM price THEN RAISE EXCEPTION 'تغير سعر الصنف حدث المنتجات وراجع الإجمالي قبل تأكيد البيع'; END IF;
   ELSE
    SELECT * INTO it FROM public.bf_items WHERE bf_items.id=(entry->>'itemId')::uuid AND cafe_id=p_cafe_id AND active;
    IF it.id IS NULL THEN RAISE EXCEPTION 'Invalid purchase item'; END IF; price:=round((entry->>'unitPrice')::numeric,2); iid:=it.id;
   END IF;
   IF price IS NULL OR price<0 OR price>10000000 THEN RAISE EXCEPTION 'Invalid unit price'; END IF;
   subtotal:=subtotal+round(qty*price,2);
   lines:=lines||jsonb_build_array(jsonb_build_object('productId',CASE WHEN p_operation='sale' THEN prod.id ELSE NULL END,'itemId',iid,'name',CASE WHEN p_operation='sale' THEN prod.name ELSE it.name END,'quantity',qty,'price',price,'unitId',CASE WHEN p_operation='sale' THEN butcher_unit->>'id' END,'unitLabel',CASE WHEN p_operation='sale' THEN butcher_unit->>'label' END,'stockUnitFactor',CASE WHEN p_operation='sale' THEN coalesce(butcher_factor,1) ELSE 1 END));
  END LOOP;
  discount:=round(coalesce((p_payload->>'discount')::numeric,0),2); IF discount<0 OR discount>subtotal THEN RAISE EXCEPTION 'Invalid discount'; END IF;
  amount:=subtotal-discount; tax:=CASE WHEN cfg.tax_inclusive THEN round(amount-amount/(1+cfg.vat_rate/100),2) ELSE round(amount*cfg.vat_rate/100,2) END; total:=CASE WHEN cfg.tax_inclusive THEN amount ELSE amount+tax END; net:=total-tax;
  IF total<=0 THEN RAISE EXCEPTION 'Invoice total must be positive'; END IF;
  IF p_operation='sale' AND (p_payload->>'expectedTotal')::numeric IS DISTINCT FROM total THEN RAISE EXCEPTION 'تغير إجمالي البيع حدث المنتجات وراجع الخصم والضريبة'; END IF;
  paid:=CASE WHEN p_operation='sale' THEN CASE WHEN aid IS NULL THEN 0 ELSE total END ELSE round(coalesce((p_payload->>'paid')::numeric,0),2) END;
  IF paid<0 OR paid>total OR (paid>0 AND aid IS NULL) OR (paid<total AND pid IS NULL) THEN RAISE EXCEPTION 'Invalid invoice payment'; END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,shift_id,account_id,warehouse_id,subtotal,discount,tax,total,paid,note,created_by,vat_rate,tax_inclusive,customer_phone,local_reference,local_created_at) VALUES(id,p_cafe_id,p_operation,pid,CASE WHEN p_operation='sale' THEN sid ELSE NULL END,aid,wid,subtotal,discount,tax,total,paid,note,auth.uid(),cfg.vat_rate,cfg.tax_inclusive,CASE WHEN p_operation='sale' AND NOT is_butcher THEN brand_finance_private.customer_phone(p_payload->>'customerPhone') END,CASE WHEN p_operation='sale' THEN p_payload->>'localReceiptReference' END,CASE WHEN p_operation='sale' THEN (p_payload->>'localCreatedAt')::timestamptz END) RETURNING number INTO n;
  remaining:=net; tax_left:=tax;
  FOR entry IN SELECT value FROM jsonb_array_elements(lines) LOOP
   pos:=pos+1;
   qty:=(entry->>'quantity')::numeric; price:=(entry->>'price')::numeric; iid:=(entry->>'itemId')::uuid;
   amount:=least(remaining,round(net*(qty*price)/subtotal,2)); remaining:=remaining-amount;
   line_tax:=least(tax_left,round(tax*(qty*price)/subtotal,2)); tax_left:=tax_left-line_tax;
   IF pos=jsonb_array_length(lines) THEN amount:=amount+remaining; remaining:=0; line_tax:=line_tax+tax_left; tax_left:=0; END IF;
   cost:=0; IF p_operation='purchase' AND iid IS NOT NULL THEN cost:=brand_finance_private.stock_move(p_cafe_id,id,iid,wid,CASE WHEN p_operation='sale' THEN -qty ELSE qty END,CASE WHEN p_operation='purchase' THEN amount/qty ELSE 0 END); END IF;
   INSERT INTO public.bf_document_lines(cafe_id,document_id,product_id,item_id,name,quantity,unit_price,net,tax,cost,unit_id,unit_label,stock_unit_factor) VALUES(p_cafe_id,id,(entry->>'productId')::uuid,iid,entry->>'name',qty,price,amount,line_tax,cost,entry->>'unitId',entry->>'unitLabel',coalesce((entry->>'stockUnitFactor')::numeric,1)) RETURNING bf_document_lines.cost INTO cost;
   IF p_operation='sale' THEN PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'5000'),cost,0); PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'1200'),0,cost); END IF;
  END LOOP;
  IF p_operation='sale' THEN
   PERFORM brand_finance_private.line(p_cafe_id,id,aid,paid,0); PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'1100'),total-paid,0,pid); PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'4000'),0,net); PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'2100'),0,tax);
  ELSE
   PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'1200'),net,0); PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'1300'),tax,0); PERFORM brand_finance_private.line(p_cafe_id,id,aid,0,paid); PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'2000'),0,total-paid,pid);
  END IF;
 ELSIF p_operation='refund' THEN
  SELECT * INTO original FROM public.bf_documents WHERE cafe_id=p_cafe_id AND bf_documents.id=(p_payload->>'documentId')::uuid;
  IF original.kind='sale' THEN
   canonical:=brand_finance_private.refund_quote(p_cafe_id,p_payload);
   INSERT INTO public.bf_refund_requests(id,cafe_id,document_id,document_number,payload,total,paid,created_by)
   VALUES(id,p_cafe_id,original.id,original.number,canonical,(canonical->>'expectedTotal')::numeric,(canonical->>'expectedPaid')::numeric,auth.uid());
   result_status:='pending';
  ELSE n:=brand_finance_private.post_refund(p_cafe_id,p_payload,id); END IF;
 ELSIF p_operation IN('refund_approve','refund_reject') THEN
  SELECT * INTO approval FROM public.bf_refund_requests WHERE cafe_id=p_cafe_id AND bf_refund_requests.id=(p_payload->>'requestId')::uuid FOR UPDATE;
  IF approval.id IS NULL OR approval.status<>'pending' THEN RAISE EXCEPTION 'طلب المرتجع غير متاح أو تمت مراجعته مسبقا'; END IF;
  IF p_operation='refund_reject' THEN
   IF nullif(btrim(note),'') IS NULL THEN RAISE EXCEPTION 'أدخل سبب رفض المرتجع'; END IF;
   UPDATE public.bf_refund_requests SET status='rejected',reviewed_by=auth.uid(),reviewed_at=now(),rejection_reason=left(note,1000) WHERE bf_refund_requests.id=approval.id;
   id:=approval.id; result_status:='rejected';
  ELSE
   canonical:=brand_finance_private.refund_quote(p_cafe_id,approval.payload);
   IF (p_payload ? 'expectedTotal' AND (p_payload->>'expectedTotal')::numeric IS DISTINCT FROM approval.total) OR (p_payload ? 'expectedPaid' AND (p_payload->>'expectedPaid')::numeric IS DISTINCT FROM approval.paid) THEN RAISE EXCEPTION 'تغير مبلغ المرتجع حدث البيانات قبل الاعتماد'; END IF;
   IF approval.paid>0 AND approval.paid>coalesce((SELECT sum(debit-credit) FROM public.bf_journal WHERE cafe_id=p_cafe_id AND account_id=(canonical->>'accountId')::uuid),0) THEN RAISE EXCEPTION 'رصيد حساب الدفع غير كاف لصرف المرتجع'; END IF;
   n:=brand_finance_private.post_refund(p_cafe_id,canonical,id);
   UPDATE public.bf_refund_requests SET status='approved',reviewed_by=auth.uid(),reviewed_at=now(),refund_document_id=id WHERE bf_refund_requests.id=approval.id;
   result_status:='approved';
  END IF;
 ELSIF p_operation='settlement' THEN
  SELECT * INTO original FROM public.bf_documents WHERE cafe_id=p_cafe_id AND bf_documents.id=(p_payload->>'documentId')::uuid AND bf_documents.kind IN('sale','purchase') FOR UPDATE;
  IF original.id IS NULL OR aid IS NULL THEN RAISE EXCEPTION 'Invalid settlement'; END IF;
  remaining:=(brand_finance_private.document_state(p_cafe_id,original.id)->>'outstanding')::numeric;
  amount:=round((p_payload->>'amount')::numeric,2); IF amount IS NULL OR amount<=0 OR amount>remaining THEN RAISE EXCEPTION 'مبلغ التسوية يتجاوز الرصيد المستحق'; END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,total,paid,reference_id,note,created_by) VALUES(id,p_cafe_id,'settlement',original.party_id,aid,amount,amount,original.id,note,auth.uid()) RETURNING number INTO n;
  IF original.kind='sale' THEN PERFORM brand_finance_private.line(p_cafe_id,id,aid,amount,0); PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'1100'),0,amount,original.party_id);
  ELSE PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'2000'),amount,0,original.party_id); PERFORM brand_finance_private.line(p_cafe_id,id,aid,0,amount); END IF;
 ELSIF p_operation IN('stock_adjust','stock_transfer') THEN
  SELECT coalesce(sum(s.quantity),0) INTO expected FROM public.bf_stock s WHERE s.cafe_id=p_cafe_id AND s.item_id=iid AND s.warehouse_id=wid;
  IF p_payload ? 'expectedQuantity' AND (p_payload->>'expectedQuantity')::numeric IS DISTINCT FROM expected THEN RAISE EXCEPTION 'تغير رصيد المخزون حدث الكميات قبل اعتماد الجرد'; END IF;
  IF p_operation='stock_adjust' AND p_payload ? 'countedQuantity' THEN
   counted:=(p_payload->>'countedQuantity')::numeric;
   IF counted IS NULL OR counted<0 OR NOT(p_payload ? 'expectedQuantity') THEN RAISE EXCEPTION 'Invalid stock count'; END IF;
   qty:=counted-expected;
  ELSE qty:=(p_payload->>'quantity')::numeric; END IF;
  IF iid IS NULL OR wid IS NULL OR qty IS NULL OR (qty=0 AND NOT(p_payload ? 'countedQuantity')) OR abs(qty)>1000000 OR qty<>round(qty,3) THEN RAISE EXCEPTION 'Invalid stock quantity'; END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,warehouse_id,note,created_by) VALUES(id,p_cafe_id,p_operation,wid,note,auth.uid()) RETURNING number INTO n;
  IF p_operation='stock_transfer' THEN
   aid2:=(p_payload->>'toWarehouseId')::uuid; IF qty<=0 OR aid2=wid OR NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE bf_warehouses.id=aid2 AND cafe_id=p_cafe_id AND active) THEN RAISE EXCEPTION 'Invalid destination'; END IF;
   cost:=brand_finance_private.stock_move(p_cafe_id,id,iid,wid,-qty,0); PERFORM brand_finance_private.stock_move(p_cafe_id,id,iid,aid2,qty,cost/qty);
  ELSE
   price:=coalesce((p_payload->>'unitCost')::numeric,0); IF price<0 THEN RAISE EXCEPTION 'Invalid stock cost'; END IF;
   cost:=CASE WHEN qty=0 THEN 0 ELSE brand_finance_private.stock_move(p_cafe_id,id,iid,wid,qty,price) END;
   PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'1200'),CASE WHEN qty>0 THEN cost ELSE 0 END,CASE WHEN qty<0 THEN cost ELSE 0 END);
   PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'5200'),CASE WHEN qty<0 THEN cost ELSE 0 END,CASE WHEN qty>0 THEN cost ELSE 0 END);
  END IF;
 ELSIF p_operation='treasury' THEN
  kind:=p_payload->>'kind'; amount:=round((p_payload->>'amount')::numeric,2); aid2:=nullif(p_payload->>'toAccountId','')::uuid;
  IF kind NOT IN('receipt','expense','transfer','opening') OR amount IS NULL OR amount<=0 OR aid IS NULL OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE bf_accounts.id=aid AND bf_accounts.kind IN('cash','bank','pos','employee')) THEN RAISE EXCEPTION 'Invalid treasury entry'; END IF;
  IF kind='transfer' AND (aid2 IS NULL OR aid=aid2 OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE bf_accounts.id=aid2 AND cafe_id=p_cafe_id AND active AND bf_accounts.kind IN('cash','bank','pos','employee'))) THEN RAISE EXCEPTION 'Invalid transfer destination'; END IF;
  IF EXISTS(SELECT 1 FROM public.bf_accounts a WHERE a.cafe_id=p_cafe_id AND a.id IN(aid,aid2) AND a.kind='employee') AND NOT EXISTS(SELECT 1 FROM public.bf_parties p WHERE p.cafe_id=p_cafe_id AND p.id=pid AND p.kind='employee' AND p.active) THEN RAISE EXCEPTION 'اختر الموظف صاحب العهدة'; END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,total,paid,note,created_by) VALUES(id,p_cafe_id,kind,pid,aid,amount,amount,note,auth.uid()) RETURNING number INTO n;
  IF kind IN('opening','receipt') THEN PERFORM brand_finance_private.line(p_cafe_id,id,aid,amount,0,pid); PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,CASE WHEN kind='opening' THEN '3000' ELSE '4000' END),0,amount);
  ELSIF kind='expense' THEN PERFORM brand_finance_private.line(p_cafe_id,id,brand_finance_private.account(p_cafe_id,'5100'),amount,0); PERFORM brand_finance_private.line(p_cafe_id,id,aid,0,amount,pid);
  ELSE PERFORM brand_finance_private.line(p_cafe_id,id,aid2,amount,0,pid); PERFORM brand_finance_private.line(p_cafe_id,id,aid,0,amount,pid); END IF;
 ELSIF p_operation='journal' THEN
  IF brand_finance_private.gl_enabled(p_cafe_id) THEN RAISE EXCEPTION 'سجل القيد من دفتر الأستاذ لإكمال المراجعة والاعتماد' USING ERRCODE='42501'; END IF;
  IF jsonb_typeof(p_payload->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'lines') NOT BETWEEN 2 AND 100 THEN RAISE EXCEPTION 'Invalid journal'; END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,note,created_by) VALUES(id,p_cafe_id,'journal',note,auth.uid()) RETURNING number INTO n;
  FOR entry IN SELECT value FROM jsonb_array_elements(p_payload->'lines') LOOP
   aid:=(entry->>'accountId')::uuid; amount:=round((entry->>'debit')::numeric,2); paid:=round((entry->>'credit')::numeric,2);
   IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE bf_accounts.id=aid AND cafe_id=p_cafe_id AND active AND bf_accounts.kind NOT IN('inventory','receivable','payable','employee')) OR amount IS NULL OR paid IS NULL THEN RAISE EXCEPTION 'Invalid journal account'; END IF;
   PERFORM brand_finance_private.line(p_cafe_id,id,aid,amount,paid);
  END LOOP;
  IF (SELECT count(*) FROM public.bf_journal j WHERE j.document_id=id)<2 THEN RAISE EXCEPTION 'Journal requires two positive entries'; END IF;
 ELSE RAISE EXCEPTION 'Unknown finance operation'; END IF;
 -- Reject overdrawing physical custody while allowing bank/clearing timing balances.
 IF EXISTS(SELECT 1 FROM public.bf_accounts a JOIN public.bf_journal j ON j.account_id=a.id WHERE a.cafe_id=p_cafe_id AND a.kind IN('cash','employee') GROUP BY a.id HAVING sum(j.debit-j.credit)<0) THEN RAISE EXCEPTION 'الرصيد النقدي أو رصيد العهدة غير كاف'; END IF;
 IF EXISTS(SELECT 1 FROM public.bf_accounts a JOIN public.bf_journal j ON j.account_id=a.id WHERE a.cafe_id=p_cafe_id AND a.kind='employee' GROUP BY a.id,j.party_id HAVING sum(j.debit-j.credit)<0) THEN RAISE EXCEPTION 'رصيد عهدة هذا الموظف غير كاف'; END IF;
 IF EXISTS(SELECT 1 FROM public.bf_journal WHERE cafe_id=p_cafe_id AND document_id=id GROUP BY document_id HAVING sum(debit)<>sum(credit)) THEN RAISE EXCEPTION 'Unbalanced journal'; END IF;
 result:=jsonb_build_object('id',id,'number',n)||CASE WHEN result_status IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('status',result_status) END;
 IF p_operation='sale' AND NOT is_butcher AND (nullif(btrim(p_payload->>'customerPhone'),'') IS NOT NULL OR nullif(p_payload->>'redeemRewardId','') IS NOT NULL) THEN result:=result||jsonb_build_object('customer',brand_finance_private.apply_sale_customer(p_cafe_id,id,p_payload,p_request_id)); END IF; INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,p_operation,p_payload,result,auth.uid());
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.freeze_issued_company_draft()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE draft_id=OLD.id) THEN RAISE EXCEPTION 'الفاتورة صادرة ولا يمكن تعديل مسودتها'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.gl_document_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NOT brand_finance_private.gl_enabled(NEW.cafe_id) THEN RETURN NEW; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));
  PERFORM brand_finance_private.gl_date_open(NEW.cafe_id,(NEW.created_at AT TIME ZONE 'Asia/Riyadh')::date);
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.gl_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.bf_accounts; d timestamptz;
BEGIN
  IF NOT brand_finance_private.gl_enabled(NEW.cafe_id) THEN RETURN NEW; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));
  SELECT * INTO a FROM public.bf_accounts WHERE cafe_id=NEW.cafe_id AND id=NEW.account_id FOR SHARE;
  IF a.id IS NULL OR a.is_group OR a.frozen OR NOT a.active THEN
    RAISE EXCEPTION 'الحساب غير نشط أو مجمد أو تجميعي';
  END IF;
  SELECT created_at INTO d FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.document_id;
  PERFORM brand_finance_private.gl_date_open(NEW.cafe_id,(d AT TIME ZONE 'Asia/Riyadh')::date);
  -- One accounting date for source document and every journal line
  NEW.created_at:=d;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.gl_lines(p_cafe uuid, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE x jsonb; a public.bf_accounts; dr numeric; cr numeric; sd numeric:=0; sc numeric:=0; result jsonb:='[]';
BEGIN
  IF jsonb_typeof(p_lines) IS DISTINCT FROM 'array' OR jsonb_array_length(p_lines) NOT BETWEEN 2 AND 100 THEN
    RAISE EXCEPTION 'أضف من سطرين إلى مئة سطر للقيد';
  END IF;
  FOR x IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    SELECT * INTO a FROM public.bf_accounts WHERE cafe_id=p_cafe AND id=(x->>'accountId')::uuid;
    IF a.id IS NULL OR NOT a.active OR a.frozen OR a.is_group OR a.kind NOT IN('expense','revenue','equity') THEN
      RAISE EXCEPTION 'اختر حسابًا نشطًا غير تجميعي ولا تستخدم حسابات الرقابة في القيد اليدوي';
    END IF;
    dr:=(x->>'debit')::numeric; cr:=(x->>'credit')::numeric;
    IF dr IS NULL OR cr IS NULL OR dr::text IN('NaN','Infinity','-Infinity') OR cr::text IN('NaN','Infinity','-Infinity')
      OR dr<0 OR cr<0 OR dr>999999999999 OR cr>999999999999 OR dr<>round(dr,2) OR cr<>round(cr,2)
      OR NOT ((dr>0 AND cr=0) OR (cr>0 AND dr=0)) THEN
      RAISE EXCEPTION 'كل سطر يحتاج مبلغًا موجبًا بمنزلتين في جانب واحد';
    END IF;
    IF length(coalesce(x->>'memo',''))>300 THEN RAISE EXCEPTION 'وصف السطر أطول من المسموح'; END IF;
    sd:=sd+dr; sc:=sc+cr;
    result:=result||jsonb_build_array(jsonb_build_object('accountId',a.id,'code',a.code,'name',a.name,
      'debit',dr,'credit',cr,'memo',coalesce(x->>'memo','')));
  END LOOP;
  IF sd<>sc OR sd<=0 THEN RAISE EXCEPTION 'القيد غير متوازن بين المدين والدائن'; END IF;
  RETURN result;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.inventory_line_components()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE doc public.bf_documents%ROWTYPE; original public.bf_document_lines%ROWTYPE; c record; s public.bf_stock%ROWTYPE;
 q numeric; actual numeric; allocated numeric; divisor integer; status text; returned_menu numeric; returned_qty numeric; returned_cost numeric; returned_allocated numeric; target_qty numeric;
BEGIN
 IF erp_sales_requisition_private.handles(NEW)THEN RETURN erp_sales_requisition_private.capture(NEW);END IF;
 IF NEW.reference_line_id IS NOT NULL THEN SELECT inventory_item_id INTO NEW.inventory_item_id FROM public.bf_document_lines WHERE cafe_id=NEW.cafe_id AND id=NEW.reference_line_id;END IF;
 IF NEW.activity_kind='service' THEN NEW.cost:=0;NEW.allocated_cost:=0;NEW.item_id:=NULL;RETURN NEW;END IF;
 SELECT * INTO STRICT doc FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.document_id;
 IF doc.kind='sale' THEN
  NEW.cost:=0;NEW.allocated_cost:=0;NEW.item_id:=NULL;
  IF NEW.inventory_item_id IS NOT NULL THEN
   IF NOT EXISTS(SELECT 1 FROM public.erp_inventory_items m WHERE m.cafe_id=NEW.cafe_id AND m.item_id=NEW.inventory_item_id AND m.kind='product' AND m.status='active') THEN RAISE EXCEPTION 'صنف المخزون غير متاح';END IF;
   IF erp_inventory_private.unit_factor(NEW.cafe_id,NEW.inventory_item_id,NEW.unit_label) IS DISTINCT FROM NEW.stock_unit_factor THEN RAISE EXCEPTION 'تحويل وحدة المخزون غير صالح';END IF;
   q:=NEW.quantity*NEW.stock_unit_factor;
   IF q<=0 OR q<>round(q,3) OR q>1000000 THEN RAISE EXCEPTION 'كمية المخزون غير صالحة';END IF;
   SELECT * INTO s FROM public.bf_stock WHERE cafe_id=NEW.cafe_id AND item_id=NEW.inventory_item_id AND warehouse_id=doc.warehouse_id FOR UPDATE;
   status:=CASE WHEN NOT coalesce(s.cost_known,false) THEN 'unknown' WHEN coalesce(s.quantity,0)-q<0 THEN 'estimated' ELSE 'known' END;
   actual:=brand_finance_private.stock_move(NEW.cafe_id,NEW.document_id,NEW.inventory_item_id,doc.warehouse_id,-q,0);
   INSERT INTO public.bf_line_components(cafe_id,line_id,item_id,warehouse_id,quantity,cost,allocated_cost,cost_mode,allocation_divisor,cost_status)
    VALUES(NEW.cafe_id,NEW.id,NEW.inventory_item_id,doc.warehouse_id,q,actual,actual,'full',1,status);
   NEW.cost:=actual;NEW.allocated_cost:=actual;NEW.item_id:=NEW.inventory_item_id;RETURN NEW;
  END IF;
  FOR c IN SELECT l.item_id,l.quantity,i.cost_mode,(SELECT count(*) FROM public.bf_item_product_links x JOIN public.menu_products p ON p.id=x.product_id AND p.cafe_id=x.cafe_id AND p.deleted_at IS NULL WHERE x.cafe_id=l.cafe_id AND x.item_id=l.item_id) linked_count
   FROM public.bf_item_product_links l JOIN public.bf_items i ON i.id=l.item_id AND i.cafe_id=l.cafe_id AND i.active
   WHERE l.cafe_id=NEW.cafe_id AND l.product_id=NEW.product_id ORDER BY l.item_id LOOP
   q:=round(NEW.quantity*c.quantity*NEW.stock_unit_factor,3);
   IF q<=0 THEN RAISE EXCEPTION 'كمية الاستهلاك أصغر من دقة الوحدة المخزنية'; END IF;
   SELECT * INTO s FROM public.bf_stock WHERE cafe_id=NEW.cafe_id AND item_id=c.item_id AND warehouse_id=doc.warehouse_id FOR UPDATE;
   status:=CASE WHEN NOT coalesce(s.cost_known,false) THEN 'unknown' WHEN coalesce(s.quantity,0)-q<0 THEN 'estimated' ELSE 'known' END;
   actual:=brand_finance_private.stock_move(NEW.cafe_id,NEW.document_id,c.item_id,doc.warehouse_id,-q,0);
   divisor:=CASE WHEN c.cost_mode='equal_split' THEN greatest(c.linked_count,1) ELSE 1 END;
   allocated:=round(actual/divisor,2);
   INSERT INTO public.bf_line_components(cafe_id,line_id,item_id,warehouse_id,quantity,cost,allocated_cost,cost_mode,allocation_divisor,cost_status)
    VALUES(NEW.cafe_id,NEW.id,c.item_id,doc.warehouse_id,q,actual,allocated,c.cost_mode,divisor,status);
   NEW.cost:=NEW.cost+actual;NEW.allocated_cost:=NEW.allocated_cost+allocated;NEW.item_id:=coalesce(NEW.item_id,c.item_id);
  END LOOP;
 ELSIF doc.kind='refund' AND NEW.reference_line_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.bf_line_components WHERE cafe_id=NEW.cafe_id AND line_id=NEW.reference_line_id) THEN
  SELECT * INTO STRICT original FROM public.bf_document_lines WHERE cafe_id=NEW.cafe_id AND id=NEW.reference_line_id; NEW.unit_id:=original.unit_id; NEW.unit_label:=original.unit_label; NEW.stock_unit_factor:=original.stock_unit_factor;
  SELECT coalesce(sum(quantity),0) INTO returned_menu FROM public.bf_document_lines WHERE cafe_id=NEW.cafe_id AND reference_line_id=original.id;
  NEW.cost:=0;NEW.allocated_cost:=0;NEW.item_id:=original.item_id;
  FOR c IN SELECT * FROM public.bf_line_components WHERE cafe_id=NEW.cafe_id AND line_id=original.id ORDER BY item_id LOOP
   SELECT coalesce(sum(quantity),0),coalesce(sum(cost),0),coalesce(sum(allocated_cost),0) INTO returned_qty,returned_cost,returned_allocated FROM public.bf_line_components WHERE original_component_id=c.id;
   target_qty:=round(c.quantity*(returned_menu+NEW.quantity)/original.quantity,3);q:=target_qty-returned_qty;
   IF q=0 THEN CONTINUE; END IF;
   IF q<0 OR target_qty>c.quantity THEN RAISE EXCEPTION 'Component refund exceeds original consumption'; END IF;
   actual:=round(c.cost*target_qty/c.quantity,2)-returned_cost;allocated:=round(c.allocated_cost*target_qty/c.quantity,2)-returned_allocated;
   IF NOT EXISTS(SELECT 1 FROM public.bf_sales_return_stock sr WHERE sr.cafe_id=NEW.cafe_id AND sr.return_id=NEW.document_id AND sr.status='pending') THEN
   PERFORM brand_finance_private.stock_move(NEW.cafe_id,NEW.document_id,c.item_id,c.warehouse_id,q,actual/q);
   END IF;
   INSERT INTO public.bf_line_components(cafe_id,line_id,item_id,warehouse_id,quantity,cost,allocated_cost,cost_mode,allocation_divisor,cost_status,original_component_id)
    VALUES(NEW.cafe_id,NEW.id,c.item_id,c.warehouse_id,q,actual,allocated,c.cost_mode,c.allocation_divisor,c.cost_status,c.id);
   NEW.cost:=NEW.cost+actual;NEW.allocated_cost:=NEW.allocated_cost+allocated;
  END LOOP;
 ELSE
  IF doc.kind='refund' AND NEW.reference_line_id IS NOT NULL THEN
   SELECT * INTO STRICT original FROM public.bf_document_lines WHERE cafe_id=NEW.cafe_id AND id=NEW.reference_line_id;
   NEW.unit_id:=original.unit_id; NEW.unit_label:=original.unit_label; NEW.stock_unit_factor:=original.stock_unit_factor;
  END IF;
  NEW.allocated_cost:=NEW.cost;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.invoice_actor_role(p_cafe uuid, p_actor uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text;
BEGIN
 IF p_actor IS NULL
   OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_actor AND status='active')
   OR NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe AND deleted_at IS NULL AND status IN('active','published'))
   OR NOT platform_access_private.service_enabled(p_cafe,'finance')
 THEN RAISE EXCEPTION 'Finance access denied' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe AND owner_user_id=p_actor) THEN RETURN 'owner'; END IF;
 IF EXISTS(SELECT 1 FROM public.profiles WHERE id=p_actor AND role='platform_admin' AND status='active') THEN RETURN 'manager'; END IF;
 SELECT role INTO r FROM public.bf_staff WHERE cafe_id=p_cafe AND user_id=p_actor AND active FOR SHARE;
 IF r IS NULL THEN RAISE EXCEPTION 'Finance staff access denied' USING ERRCODE='42501'; END IF;
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.invoice_advanced_validate(cafe uuid, v jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE defaults jsonb:=brand_finance_private.invoice_advanced_defaults();k text;x jsonb;y jsonb;ids text[];r text;counter_kind text;
BEGIN
 IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR octet_length(v::text)>1900000 OR (SELECT count(*) FROM jsonb_object_keys(v))<>(SELECT count(*) FROM jsonb_object_keys(defaults)) OR EXISTS(SELECT 1 FROM jsonb_object_keys(v) t WHERE NOT(defaults ? t)) THEN RAISE EXCEPTION 'Invalid advanced invoice settings' USING ERRCODE='22023';END IF;
 FOR k IN SELECT jsonb_object_keys(defaults) LOOP
  IF jsonb_typeof(v->k) IS DISTINCT FROM jsonb_typeof(defaults->k) THEN RAISE EXCEPTION 'Invalid advanced setting type: %',k USING ERRCODE='22023';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['numbering','debitNumbering'] LOOP
  x:=v->k;counter_kind:=CASE k WHEN 'numbering' THEN 'invoice' ELSE 'debit' END;
  IF NOT brand_finance_private.invoice_object_keys(x,ARRAY['prefix','next','padding','manual']) OR jsonb_typeof(x->'prefix') IS DISTINCT FROM 'string' OR length(x->>'prefix')>12 OR (x->>'prefix') ~ '[^A-Za-z0-9ء-ي_-]' OR jsonb_typeof(x->'manual') IS DISTINCT FROM 'boolean' OR NOT brand_finance_private.invoice_number_valid(x->'next',1,999999999999,0) OR NOT brand_finance_private.invoice_number_valid(x->'padding',1,12,0) THEN RAISE EXCEPTION 'Invalid invoice numbering' USING ERRCODE='22023';END IF;
  IF EXISTS(SELECT 1 FROM public.bf_invoice_number_counters WHERE cafe_id=cafe AND bf_invoice_number_counters.kind=counter_kind AND next_value>(x->>'next')::bigint) THEN RAISE EXCEPTION 'Invoice numbering cannot move backwards' USING ERRCODE='22023';END IF;
 END LOOP;
 IF v->>'billingMethod' NOT IN('print','email','both') OR v->>'defaultPaymentKind' NOT IN('cash','bank','pos','credit') OR v->>'activityKind' NOT IN('products','services','both') OR v->>'taxMode' NOT IN('product','none','specific') OR (v->>'specificTaxRate')::numeric NOT IN(0,15) OR length(v->>'exemptionReason')>250 OR length(v->>'journalTemplate')>500 OR (v->>'journalTemplate') ~ '\{(?!number\}|customer\}|date\}|total\})' THEN RAISE EXCEPTION 'Invalid advanced invoice option' USING ERRCODE='22023';END IF;
 IF v->>'defaultAccountId'<>'' AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=cafe AND id::text=v->>'defaultAccountId' AND active AND NOT is_cashier_drawer AND kind=v->>'defaultPaymentKind') THEN RAISE EXCEPTION 'Invalid default collection account' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(v->'currencies') NOT BETWEEN 1 AND 5 OR (SELECT count(DISTINCT currency_row->>'code') FROM jsonb_array_elements(v->'currencies') currency_row)<>jsonb_array_length(v->'currencies') OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'currencies') currency_row WHERE currency_row->>'code'='SAR' AND jsonb_typeof(currency_row->'rate')='number' AND (currency_row->>'rate')::numeric=1) THEN RAISE EXCEPTION 'Invalid invoice currencies' USING ERRCODE='22023';END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(v->'currencies') LOOP
  IF NOT brand_finance_private.invoice_object_keys(x,ARRAY['code','rate']) OR x->>'code' NOT IN('SAR','USD','EUR','GBP','AED') OR NOT brand_finance_private.invoice_number_valid(x->'rate',0.000001,1000000,6) THEN RAISE EXCEPTION 'Invalid currency rate' USING ERRCODE='22023';END IF;
 END LOOP;
 IF jsonb_array_length(v->'socialPlatforms')>3 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(v->'socialPlatforms') platform_row WHERE platform_row NOT IN('whatsapp','email','native')) OR (SELECT count(DISTINCT platform_row) FROM jsonb_array_elements_text(v->'socialPlatforms') platform_row)<>jsonb_array_length(v->'socialPlatforms') THEN RAISE EXCEPTION 'Invalid social platforms' USING ERRCODE='22023';END IF;
 FOREACH k IN ARRAY ARRAY['statuses','discountCaps','productPolicies','priceLists','adjustments','excludedCategories'] LOOP
  IF jsonb_array_length(v->k)>(CASE k WHEN 'discountCaps' THEN 200 WHEN 'productPolicies' THEN 500 WHEN 'excludedCategories' THEN 100 ELSE 30 END) THEN RAISE EXCEPTION 'Invoice setting list too long' USING ERRCODE='22023';END IF;
  ids:='{}';
  FOR x IN SELECT value FROM jsonb_array_elements(v->k) LOOP
   IF k='excludedCategories' THEN
    IF jsonb_typeof(x)<>'string' OR length(btrim(x#>>'{}')) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Invalid category exclusion' USING ERRCODE='22023';END IF;
    r:=x#>>'{}';
   ELSIF k='statuses' THEN
    IF NOT brand_finance_private.invoice_object_keys(x,ARRAY['id','name','color']) OR jsonb_typeof(x->'name')<>'string' OR length(btrim(x->>'name')) NOT BETWEEN 1 AND 80 OR coalesce(x->>'color','')!~'^#[0-9a-fA-F]{6}$' THEN RAISE EXCEPTION 'Invalid invoice status' USING ERRCODE='22023';END IF;r:=(x->>'id')::uuid::text;
   ELSIF k='discountCaps' THEN
    IF NOT brand_finance_private.invoice_object_keys(x,ARRAY['userId','percent']) OR NOT brand_finance_private.invoice_number_valid(x->'percent',0,100) OR NOT(EXISTS(SELECT 1 FROM public.cafes WHERE id=cafe AND owner_user_id=(x->>'userId')::uuid) OR EXISTS(SELECT 1 FROM public.bf_staff WHERE cafe_id=cafe AND user_id=(x->>'userId')::uuid AND active AND role IN('manager','accountant'))) THEN RAISE EXCEPTION 'Invalid user discount cap' USING ERRCODE='22023';END IF;r:=(x->>'userId')::uuid::text;
   ELSIF k='productPolicies' THEN
    IF NOT brand_finance_private.invoice_object_keys(x,ARRAY['productId','kind','minimumPrice','vatRate','taxCategory','exemptionReason']) OR coalesce(x->>'kind','') NOT IN('product','service') OR NOT brand_finance_private.invoice_number_valid(x->'minimumPrice',0,1000000000,2) OR NOT brand_finance_private.invoice_number_valid(x->'vatRate',0,15) OR (x->>'vatRate')::numeric NOT IN(0,15) OR x->>'taxCategory' NOT IN('S','Z','E','O') OR ((x->>'vatRate')::numeric=15) IS DISTINCT FROM (x->>'taxCategory'='S') OR jsonb_typeof(x->'exemptionReason') IS DISTINCT FROM 'string' OR length(x->>'exemptionReason')>250 OR NOT EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id=cafe AND id=(x->>'productId')::uuid AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Invalid product pricing/tax policy' USING ERRCODE='22023';END IF;r:=(x->>'productId')::uuid::text;
   ELSIF k='priceLists' THEN
    IF NOT brand_finance_private.invoice_object_keys(x,ARRAY['id','name','active','prices','partyIds']) OR jsonb_typeof(x->'name')<>'string' OR length(btrim(x->>'name')) NOT BETWEEN 1 AND 80 OR jsonb_typeof(x->'active')<>'boolean' OR jsonb_typeof(x->'prices')<>'array' OR jsonb_array_length(x->'prices')>500 OR jsonb_typeof(x->'partyIds')<>'array' OR jsonb_array_length(x->'partyIds')>500 THEN RAISE EXCEPTION 'Invalid price list' USING ERRCODE='22023';END IF;r:=(x->>'id')::uuid::text;
    IF (SELECT count(DISTINCT z->>'productId') FROM jsonb_array_elements(x->'prices') z)<>jsonb_array_length(x->'prices') OR (SELECT count(DISTINCT z) FROM jsonb_array_elements_text(x->'partyIds') z)<>jsonb_array_length(x->'partyIds') THEN RAISE EXCEPTION 'Duplicate price list reference' USING ERRCODE='22023';END IF;
    FOR y IN SELECT value FROM jsonb_array_elements(x->'prices') LOOP
     IF NOT brand_finance_private.invoice_object_keys(y- 'catalogSource',ARRAY['productId','price']) OR coalesce(y->>'catalogSource','menu') NOT IN('menu','inventory') OR NOT brand_finance_private.invoice_number_valid(y->'price',0,1000000000,2) OR
      (CASE WHEN y->>'catalogSource'='inventory' THEN NOT EXISTS(SELECT 1 FROM public.erp_inventory_items m JOIN public.bf_items b ON b.cafe_id=m.cafe_id AND b.id=m.item_id WHERE m.cafe_id=cafe AND m.item_id=(y->>'productId')::uuid AND m.status='active' AND b.active AND NOT EXISTS(SELECT 1 FROM public.menu_products p WHERE p.cafe_id=cafe AND p.id=m.item_id)) ELSE NOT EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id=cafe AND id=(y->>'productId')::uuid AND deleted_at IS NULL) END) THEN RAISE EXCEPTION 'Invalid listed product price' USING ERRCODE='22023';END IF;
    END LOOP;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(x->'partyIds') p WHERE NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=cafe AND id=p::uuid AND kind='customer' AND active)) THEN RAISE EXCEPTION 'Invalid price list customer' USING ERRCODE='22023';END IF;
   ELSE
    IF NOT brand_finance_private.invoice_object_keys(x,ARRAY['id','name','accountId','kind','taxable']) OR jsonb_typeof(x->'name')<>'string' OR length(btrim(x->>'name')) NOT BETWEEN 1 AND 80 OR coalesce(x->>'kind','') NOT IN('addition','deduction') OR jsonb_typeof(x->'taxable')<>'boolean' OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=cafe AND id=(x->>'accountId')::uuid AND active AND kind IN('revenue','expense') AND code NOT IN('5000')) THEN RAISE EXCEPTION 'Invalid invoice adjustment account' USING ERRCODE='22023';END IF;r:=(x->>'id')::uuid::text;
   END IF;
   IF r IS NULL OR r=ANY(ids) THEN RAISE EXCEPTION 'Duplicate or missing invoice setting id' USING ERRCODE='22023';END IF;ids:=array_append(ids,r);
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.invoice_line(cafe uuid, document uuid, account uuid, debit numeric, credit numeric, party uuid, memo text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=cafe AND account_id=account AND status='handover') THEN RAISE EXCEPTION 'الخزينة قيد تسليم الوردية انتظر قبول الاستلام';END IF;
 IF round(debit,2)=0 AND round(credit,2)=0 THEN RETURN;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bf_accounts a WHERE a.cafe_id=cafe AND a.id=account AND a.active AND a.deleted_at IS NULL AND NOT a.frozen AND NOT a.is_group) THEN RAISE EXCEPTION 'حساب القيد غير نشط أو مجمد';END IF;
 INSERT INTO public.bf_journal(cafe_id,document_id,account_id,debit,credit,party_id,memo) VALUES(cafe,document,account,round(debit,2),round(credit,2),party,left(coalesce(memo,''),300));
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.invoice_number_allocate(cafe uuid, document_kind text, config jsonb, manual_value text DEFAULT ''::text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE n bigint;display text;BEGIN
 IF coalesce(manual_value,'')<>'' THEN
  IF NOT(config->>'manual')::boolean OR length(btrim(manual_value)) NOT BETWEEN 1 AND 80 OR manual_value ~ '[[:cntrl:]]' THEN RAISE EXCEPTION 'رقم الفاتورة اليدوي غير صالح أو غير مسموح';END IF;
  display:=btrim(manual_value);
 ELSE
  n:=brand_finance_private.invoice_number_next(cafe,document_kind,config);display:=(config->>'prefix')||lpad(n::text,greatest(length(n::text),(config->>'padding')::integer),'0');
  INSERT INTO public.bf_invoice_number_counters(cafe_id,kind,next_value) VALUES(cafe,document_kind,n+1) ON CONFLICT(cafe_id,kind) DO UPDATE SET next_value=excluded.next_value;
 END IF;
 IF EXISTS(SELECT 1 FROM public.bf_invoice_extensions WHERE cafe_id=cafe AND lower(CASE WHEN display_number~'^[0-9]+$' THEN coalesce(nullif(ltrim(display_number,'0'),''),'0') ELSE display_number END)=lower(CASE WHEN display~'^[0-9]+$' THEN coalesce(nullif(ltrim(display,'0'),''),'0') ELSE display END)) OR EXISTS(SELECT 1 FROM public.bf_documents d WHERE d.cafe_id=cafe AND d.kind='sale' AND d.number::text=CASE WHEN display~'^[0-9]+$' THEN ltrim(display,'0') ELSE display END AND NOT EXISTS(SELECT 1 FROM public.bf_invoice_extensions e WHERE e.document_id=d.id AND e.metadata<>'{}'::jsonb)) THEN RAISE EXCEPTION 'رقم الفاتورة مستخدم اختر رقمًا آخر' USING ERRCODE='23505';END IF;
 RETURN display;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.invoice_payment_record(source bf_documents, invoice bf_documents)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE p public.bf_invoice_payments%ROWTYPE; values jsonb; paid numeric; state text; account public.bf_accounts%ROWTYPE; collector uuid; guard text; deletion_guard text; editable boolean;
BEGIN
 SELECT * INTO p FROM public.bf_invoice_payments WHERE cafe_id=source.cafe_id AND source_id=source.id;
 state:=coalesce(p.status,'completed');
 values:=coalesce(p.payload,jsonb_build_object('amount',CASE WHEN source.kind='sale' THEN source.paid ELSE source.total END,'date',(source.created_at AT TIME ZONE 'Asia/Riyadh')::date,'accountId',source.account_id,'status','completed','collectorId',source.created_by,'reference','','details',CASE WHEN source.kind='sale' THEN '' ELSE source.note END,'receiptNote','','attachments','[]'::jsonb));
 paid:=CASE WHEN state='completed' THEN (values->>'amount')::numeric ELSE 0 END;
 SELECT * INTO account FROM public.bf_accounts WHERE cafe_id=source.cafe_id AND id=(values->>'accountId')::uuid;
 collector:=(values->>'collectorId')::uuid;
 guard:=brand_finance_private.payment_financial_guard(source,invoice,account.id,coalesce(p.financial_at,source.created_at));
 deletion_guard:=guard;

 IF paid>0 AND (brand_finance_private.payment_document(invoice)).paid+coalesce((SELECT sum((brand_finance_private.payment_document(s)).total) FROM public.bf_documents s WHERE s.cafe_id=source.cafe_id AND s.reference_id=invoice.id AND s.kind='settlement'),0)-paid<coalesce((SELECT sum(r.paid) FROM public.bf_documents r WHERE r.cafe_id=source.cafe_id AND r.reference_id=invoice.id AND r.kind='refund'),0) THEN deletion_guard:=coalesce(deletion_guard,'لا يمكن حذف دفعة استندت إليها مبالغ معادة للعميل'); END IF;
 IF paid>0 AND brand_finance_private.treasury_balance(source.cafe_id,account.id)<paid THEN deletion_guard:=coalesce(deletion_guard,'رصيد حساب التحصيل لا يكفي لعكس هذه الدفعة'); END IF;
 editable:=coalesce(brand_finance_private.role_for(source.cafe_id),'') IN('owner','manager','accountant') AND state<>'deleted';
 RETURN jsonb_build_object('id',source.id,'invoiceId',invoice.id,'initial',source.id=invoice.id,'number',source.number,'revision',coalesce(p.revision,0),'status',state,
  'amount',(values->>'amount')::numeric,'effectiveAmount',paid,'date',values->>'date','accountId',account.id,'accountName',account.name,'method',account.kind,
  'collectorId',collector,'collectorName',coalesce((SELECT nullif(name,'') FROM public.bf_staff WHERE cafe_id=source.cafe_id AND user_id=collector),(SELECT nullif(full_name,'') FROM public.profiles WHERE id=collector),'مستخدم غير مسمى'),
  'reference',values->>'reference','details',values->>'details','receiptNote',values->>'receiptNote',
  'attachments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',f.id,'name',f.original_name,'size',f.size_bytes) ORDER BY a.ordinality) FROM jsonb_array_elements_text(values->'attachments') WITH ORDINALITY a(id,ordinality) JOIN public.bf_company_invoice_files f ON f.id=a.id::uuid AND f.cafe_id=source.cafe_id AND f.uploaded),'[]'::jsonb),
  'canEdit',editable,'canChangeFinancials',editable AND guard IS NULL,'canDelete',editable AND (paid=0 OR deletion_guard IS NULL),'blockedReason',CASE WHEN state='deleted' THEN 'تم حذف الدفعة مع حفظ أثر التصحيح' ELSE coalesce(guard,deletion_guard) END)||CASE WHEN EXISTS(SELECT 1 FROM public.bf_customer_credit_events WHERE cafe_id=source.cafe_id AND document_id=source.id AND action='apply') THEN jsonb_build_object('method','credit','accountName','رصيد العميل','canEdit',false,'canChangeFinancials',false,'canDelete',false,'blockedReason',CASE WHEN state='deleted' THEN 'تم إلغاء تطبيق رصيد العميل' ELSE 'ألغ تطبيق رصيد العميل من إدارة الأرصدة' END) ELSE '{}'::jsonb END;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.invoice_refund_adjustments(cafe uuid, refund uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE row record;before_qty numeric;share_net numeric;share_tax numeric;
BEGIN
 FOR row IN SELECT l.id,l.reference_line_id,l.quantity,a.net,a.tax,a.account_id,original.quantity AS original_quantity FROM public.bf_document_lines l JOIN public.bf_invoice_adjustment_lines a ON a.cafe_id=l.cafe_id AND a.line_id=l.reference_line_id JOIN public.bf_document_lines original ON original.id=l.reference_line_id WHERE l.cafe_id=cafe AND l.document_id=refund LOOP
  SELECT coalesce(sum(quantity),0) INTO before_qty FROM public.bf_document_lines WHERE cafe_id=cafe AND reference_line_id=row.reference_line_id AND id<>row.id;
  share_net:=round(row.net*(before_qty+row.quantity)/row.original_quantity,2)-round(row.net*before_qty/row.original_quantity,2);
  share_tax:=round(row.tax*(before_qty+row.quantity)/row.original_quantity,2)-round(row.tax*before_qty/row.original_quantity,2);
  IF share_net<>0 THEN
   PERFORM brand_finance_private.line(cafe,refund,row.account_id,greatest(share_net,0),greatest(-share_net,0));
   PERFORM brand_finance_private.line(cafe,refund,brand_finance_private.account(cafe,'4000'),greatest(-share_net,0),greatest(share_net,0));
  END IF;
  INSERT INTO public.bf_invoice_adjustment_lines(cafe_id,document_id,line_id,account_id,net,tax) VALUES(cafe,refund,row.id,row.account_id,share_net,share_tax);
 END LOOP;
 PERFORM brand_finance_private.shipping_refund_revenue(cafe,refund);
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.invoice_settings_maintenance(p_cafe_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE expires_at timestamptz; authorized jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RETURN false; END IF;
 SELECT CASE WHEN action='maintenance_mode_started' THEN (new_data->>'expires_at')::timestamptz END
 INTO expires_at FROM public.audit_logs
 WHERE actor_id=auth.uid() AND cafe_id=p_cafe_id AND action IN('maintenance_mode_started','maintenance_mode_ended')
 ORDER BY created_at DESC,id DESC LIMIT 1;
 IF expires_at IS NULL OR expires_at<=clock_timestamp() THEN RETURN false; END IF;
 authorized:=public.brand_finance_maintenance_cashier(p_cafe_id,auth.uid(),expires_at,'authorize','{}'::jsonb);
 RETURN authorized->>'authorized'='true';
EXCEPTION WHEN SQLSTATE '42501' OR invalid_datetime_format OR datetime_field_overflow THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.issue_company_invoice_actor(p_actor uuid, p_preview boolean, p_cafe_id uuid, p_draft_id uuid, p_revision integer, p_expected_total numeric, p_source_id uuid DEFAULT NULL::uuid, p_debit_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE inventory jsonb;inventory_factor numeric;inventory_unit text;inventory_source boolean;draft public.bf_invoice_drafts%ROWTYPE; customer public.bf_parties%ROWTYPE; cfg public.bf_settings%ROWTYPE;
  inv jsonb; seller jsonb; entry jsonb; product public.menu_products%ROWTYPE; existing jsonb; doc uuid:=gen_random_uuid();
  aid uuid; wid uuid; n bigint; issue_at timestamptz:=clock_timestamp(); supply_date date; rows jsonb:='[]'; final_rows jsonb:='[]';
  qty numeric; price numeric; gross numeric; row_discount numeric; rate numeric; row_after numeric; remaining numeric; base_left numeric;
  allocated numeric; taxable numeric; row_tax numeric; row_net numeric; row_total numeric; cost numeric; paid numeric;
  subtotal numeric:=0; after_rows numeric:=0; doc_discount numeric; tax numeric:=0; total numeric:=0; net numeric:=0;
  discount_value numeric; inclusive boolean; result jsonb; buyer_address text; seller_tax text; phone text; invoice_type text;
  deposit jsonb; deposit_value numeric; deposit_amount numeric; deposit_paid boolean; deposit_kind text;
  shipping_mode text; shipping_address text; delivery_confirmed boolean; delivery_date timestamptz;
  prefs jsonb;line_cost_status text;file_ids jsonb; file_id uuid; files jsonb:='[]'; attached public.bf_company_invoice_files%ROWTYPE;
  advanced jsonb;currency_code text;fx numeric;source_doc public.bf_documents%ROWTYPE;status_id uuid;list_id uuid;price_list jsonb;product_id uuid;policy jsonb;line_name text;line_kind text;catalog_price numeric;tax_category text;exemption text;cap numeric;
  adjustment_base numeric:=0;adjustment_id uuid;adjustment_rule jsonb;adjustment_amount numeric;adjustment_line_net numeric;adjustment_line_tax numeric;adjustment_net numeric:=0;adjustment_tax numeric:=0;
  sar_line_net numeric;sar_line_tax numeric;sar_net numeric:=0;sar_tax numeric:=0;sar_subtotal numeric:=0;sar_discount numeric;sar_total numeric;sar_adjustment_net numeric:=0;sar_adjustment_tax numeric:=0;
  credit_sar numeric;credit_foreign numeric;cash_sar numeric;display_number text;journal_note text;line_id uuid;
BEGIN
  IF p_actor IS NULL OR coalesce(brand_finance_private.invoice_actor_role(p_cafe_id,p_actor),'') NOT IN ('owner','manager','accountant')
  THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
  SELECT snapshot INTO existing FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  IF FOUND THEN RETURN existing; END IF;
  SELECT * INTO draft FROM public.bf_invoice_drafts WHERE id=p_draft_id AND cafe_id=p_cafe_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501'; END IF;
  IF draft.revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'Draft conflict' USING ERRCODE='40001'; END IF;
  prefs:=brand_finance_private.invoice_settings(p_cafe_id);
  inv:=draft.payload->'invoice'; seller:=draft.payload->'issuer';
  IF inv IS NULL OR jsonb_typeof(inv->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(inv->'lines') NOT BETWEEN 1 AND 100
    OR draft.payload::text ~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'Invalid invoice'; END IF;
  IF coalesce(length(btrim(seller->>'name')),0) NOT BETWEEN 2 AND 160 OR coalesce(length(btrim(seller->>'address')),0) NOT BETWEEN 8 AND 500
    OR octet_length(seller->>'name')>255 OR coalesce(seller->>'vatNumber','') !~ '^3[0-9]{13}3$' THEN RAISE EXCEPTION 'أكمل الاسم القانوني وعنوان البائع والرقم الضريبي الصحيح'; END IF;
  SELECT tax_number INTO seller_tax FROM public.cafe_settings WHERE cafe_id=p_cafe_id;
  IF nullif(btrim(seller_tax),'') IS NOT NULL AND btrim(seller_tax)<>seller->>'vatNumber' THEN RAISE EXCEPTION 'رقم البائع الضريبي لا يطابق إعدادات العلامة'; END IF;
  supply_date:=(draft.payload->>'supplyDate')::date;
  IF supply_date IS NULL OR NOT isfinite(supply_date) OR supply_date>(issue_at AT TIME ZONE 'Asia/Riyadh')::date THEN RAISE EXCEPTION 'اختر تاريخ توريد صالحًا'; END IF;
  PERFORM brand_finance_private.seed(p_cafe_id);
  SELECT * INTO STRICT cfg FROM public.bf_settings WHERE cafe_id=p_cafe_id FOR UPDATE;
  PERFORM brand_finance_private.gl_date_open(p_cafe_id,(issue_at AT TIME ZONE 'Asia/Riyadh')::date);
  SELECT * INTO customer FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id::text=(inv->>'partyId') AND active AND kind='customer';
  IF NOT FOUND THEN RAISE EXCEPTION 'اختر عميلًا نشطًا'; END IF;
  IF coalesce(customer.details->>'customerType','individual') NOT IN ('individual','business') THEN RAISE EXCEPTION 'حدد نوع العميل فردًا أو شركة'; END IF;
  invoice_type:=CASE WHEN coalesce(customer.details->>'customerType','individual')='individual' AND nullif(btrim(customer.tax_number),'') IS NULL THEN 'simplified' ELSE 'standard' END;
  IF invoice_type='standard' AND coalesce(customer.tax_number,'') !~ '^3[0-9]{13}3$' THEN RAISE EXCEPTION 'أكمل الرقم الضريبي الصحيح للعميل من ١٥ رقمًا'; END IF;
  buyer_address:=concat_ws(' ',nullif(customer.details->>'buildingNumber',''),nullif(customer.details->>'street',''),nullif(customer.details->>'district',''),nullif(customer.details->>'city',''),nullif(customer.details->>'postalCode',''),nullif(customer.details->>'country',''));
  IF invoice_type='standard' AND (coalesce(length(buyer_address),0)<8 OR nullif(customer.details->>'city','') IS NULL OR nullif(customer.details->>'street','') IS NULL) THEN RAISE EXCEPTION 'أكمل عنوان العميل في بياناته قبل الإصدار'; END IF;
  wid:=nullif(inv->>'warehouseId','')::uuid;
  IF NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id=wid AND active) THEN RAISE EXCEPTION 'اختر مستودعًا نشطًا'; END IF;
  IF coalesce(inv->>'paymentKind','') NOT IN ('cash','bank','pos','credit') THEN RAISE EXCEPTION 'Invalid payment'; END IF;
  IF inv->>'paymentKind'<>'credit' THEN
    aid:=nullif(inv->>'accountId','')::uuid;
    IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=aid AND active AND kind=inv->>'paymentKind' AND NOT is_cashier_drawer)
      THEN RAISE EXCEPTION 'اختر حساب تحصيل إداريًا نشطًا خارج صناديق ورديات الكاشير'; END IF;
  END IF;
  deposit:=coalesce(draft.payload->'deposit','{"kind":"amount","value":0,"paid":false}'::jsonb);
  deposit_kind:=deposit->>'kind';deposit_value:=(deposit->>'value')::numeric;deposit_paid:=(deposit->>'paid')::boolean;
  IF jsonb_typeof(deposit)<>'object' OR deposit_kind IS NULL OR deposit_kind NOT IN ('amount','percent') OR deposit_value IS NULL OR deposit_paid IS NULL OR deposit_value<0 OR deposit_value>1000000000 OR deposit_value<>round(deposit_value,2) OR (deposit_kind='percent' AND deposit_value>100) THEN RAISE EXCEPTION 'راجع قيمة الدفعة المقدمة'; END IF;
  IF deposit_value>0 AND ((deposit_paid AND aid IS NULL) OR (NOT deposit_paid AND aid IS NOT NULL)) THEN RAISE EXCEPTION 'حدد حالة تحصيل الدفعة وحسابها'; END IF;
  IF NOT (prefs->>'allowDeposits')::boolean AND deposit_value>0 THEN RAISE EXCEPTION 'Invoice settings: deposits disabled' USING ERRCODE='22023';END IF;
  shipping_mode:=coalesce(draft.payload->>'shipping','none');
  IF shipping_mode NOT IN ('none','main','secondary') THEN RAISE EXCEPTION 'Invalid shipping mode'; END IF;
  shipping_address:=CASE shipping_mode WHEN 'main' THEN buyer_address WHEN 'secondary' THEN concat_ws(' ',nullif(customer.details->>'shippingBuildingNumber',''),nullif(customer.details->>'shippingStreet',''),nullif(customer.details->>'shippingDistrict',''),nullif(customer.details->>'shippingCity',''),nullif(customer.details->>'shippingPostalCode',''),nullif(customer.details->>'shippingCountry','')) ELSE '' END;
  IF shipping_mode<>'none' AND (length(shipping_address)<8 OR nullif(customer.details->>CASE WHEN shipping_mode='main' THEN 'street' ELSE 'shippingStreet' END,'') IS NULL OR nullif(customer.details->>CASE WHEN shipping_mode='main' THEN 'city' ELSE 'shippingCity' END,'') IS NULL) THEN RAISE EXCEPTION 'أكمل عنوان الشحن المختار في بيانات العميل'; END IF;
  delivery_confirmed:=coalesce((draft.payload#>>'{delivery,confirmed}')::boolean,false);
  delivery_date:=nullif(draft.payload#>>'{delivery,date}','')::timestamptz;
  IF delivery_confirmed AND (delivery_date IS NULL OR NOT isfinite(delivery_date) OR delivery_date>issue_at) THEN RAISE EXCEPTION 'اختر وقت تسليم صحيحًا لا يتجاوز الوقت الحالي'; END IF;
  IF NOT delivery_confirmed THEN delivery_date:=NULL; END IF;
  file_ids:=coalesce(draft.payload->'attachments','[]'::jsonb);
  IF jsonb_typeof(file_ids)<>'array' OR jsonb_array_length(file_ids)>20 OR (SELECT count(DISTINCT value)<>count(*) FROM jsonb_array_elements(file_ids)) THEN RAISE EXCEPTION 'Invalid attachments'; END IF;
  FOR file_id IN SELECT value::uuid FROM jsonb_array_elements_text(file_ids) LOOP
    SELECT * INTO attached FROM public.bf_company_invoice_files WHERE id=file_id AND cafe_id=p_cafe_id AND uploaded FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'أحد المستندات غير متاح أو لم يكتمل رفعه'; END IF;
    files:=files||jsonb_build_array(jsonb_build_object('id',attached.id,'name',attached.original_name,'size',attached.size_bytes));
  END LOOP;
  inclusive:=coalesce((inv->>'taxInclusive')::boolean,cfg.tax_inclusive);
  advanced:=prefs->'advanced';currency_code:=coalesce(nullif(inv->>'currency',''),'SAR');
  SELECT (c->>'rate')::numeric INTO fx FROM jsonb_array_elements(advanced->'currencies') c WHERE c->>'code'=currency_code;
  IF fx IS NULL THEN RAISE EXCEPTION 'عملة الفاتورة غير مفعلة';END IF;
  IF NOT(advanced->>'showExchangeRate')::boolean AND inv ? 'exchangeRate' AND (inv->>'exchangeRate')::numeric IS DISTINCT FROM fx THEN RAISE EXCEPTION 'تعديل سعر الصرف غير مسموح في إعدادات الفاتورة';END IF;
  fx:=coalesce((inv->>'exchangeRate')::numeric,fx);
  IF fx<=0 OR fx>1000000 OR fx<>round(fx,6) OR (currency_code='SAR' AND fx<>1) THEN RAISE EXCEPTION 'راجع سعر صرف العملة';END IF;
  IF p_source_id IS NOT NULL THEN
   SELECT * INTO source_doc FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_source_id AND kind='sale' FOR UPDATE;
   IF source_doc.id IS NULL OR NOT(advanced->>'debitNotesEnabled')::boolean OR source_doc.party_id<>customer.id OR EXISTS(SELECT 1 FROM public.bf_invoice_extensions WHERE document_id=p_source_id AND source_id IS NOT NULL) OR (brand_finance_private.document_state(p_cafe_id,p_source_id)->>'refunded')::boolean OR length(btrim(p_debit_reason)) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'الفاتورة غير متاحة لإشعار مدين';END IF;
  END IF;
  status_id:=nullif(inv->>'statusId','')::uuid;
  IF status_id IS NOT NULL AND (NOT(advanced->>'customStatusesEnabled')::boolean OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(advanced->'statuses') s WHERE s->>'id'=status_id::text)) THEN RAISE EXCEPTION 'حالة الفاتورة غير متاحة';END IF;
  list_id:=nullif(inv->>'priceListId','')::uuid;
  IF list_id IS NOT NULL THEN
   SELECT x INTO price_list FROM jsonb_array_elements(advanced->'priceLists') x WHERE x->>'id'=list_id::text AND (x->>'active')::boolean;
   IF NOT(advanced->>'priceListsEnabled')::boolean OR price_list IS NULL OR (jsonb_array_length(price_list->'partyIds')>0 AND NOT(price_list->'partyIds' ? customer.id::text)) THEN RAISE EXCEPTION 'قائمة الأسعار غير متاحة لهذا العميل';END IF;
  END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(inv->'lines') LOOP
   product:=NULL;policy:=NULL;product_id:=nullif(entry->>'productId','')::uuid;inventory:=NULL;inventory_factor:=1;inventory_unit:='';
   IF coalesce(entry->>'catalogSource','menu') NOT IN('menu','inventory') THEN RAISE EXCEPTION 'مصدر البند غير صالح';END IF;
   inventory_source:=entry->>'catalogSource'='inventory';
   IF inventory_source THEN
    inventory:=erp_inventory_private.sale_item(p_cafe_id,product_id,coalesce(entry->>'unitName',''));
    inventory_factor:=(inventory->>'unitFactor')::numeric;inventory_unit:=inventory->>'unitName';
    IF entry ? 'unitFactor' AND (entry->>'unitFactor')::numeric IS DISTINCT FROM inventory_factor THEN RAISE EXCEPTION 'تغير تحويل الوحدة حدث الصنف ثم أعد المحاولة';END IF;
    IF round((entry->>'quantity')::numeric*inventory_factor,3) IS DISTINCT FROM (entry->>'quantity')::numeric*inventory_factor OR (entry->>'quantity')::numeric*inventory_factor>1000000 THEN RAISE EXCEPTION 'الكمية لا تطابق دقة وحدة المخزون';END IF;
    product.name:=inventory->>'name';product.description:=inventory->>'description';product.price:=(inventory->>'price')::numeric;
    policy:=inventory;line_name:=inventory->>'name';line_kind:=inventory->>'kind';
    IF line_kind='product' AND NOT erp_inventory_private.sale_warehouse_allowed(p_cafe_id,wid,p_actor) THEN RAISE EXCEPTION 'Inventory warehouse write denied' USING ERRCODE='42501';END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(advanced->'excludedCategories') x WHERE x=inventory->>'categoryId' OR x=inventory->>'category') THEN RAISE EXCEPTION 'صنف البند مستبعد من الفواتير';END IF;
   ELSIF product_id IS NULL THEN
    IF p_source_id IS NULL AND NOT(prefs->>'allowLineEditing')::boolean THEN RAISE EXCEPTION 'البنود الحرة غير مسموحة في إعدادات الفاتورة';END IF;
    line_name:=btrim(coalesce(entry->>'name',''));line_kind:=coalesce(entry->>'kind','');
    IF length(line_name) NOT BETWEEN 1 AND 160 OR line_kind NOT IN('product','service') THEN RAISE EXCEPTION 'أكمل اسم البند الحر ونوعه';END IF;
   ELSE
    SELECT * INTO product FROM public.menu_products WHERE cafe_id=p_cafe_id AND id=product_id AND deleted_at IS NULL AND available FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'أحد المنتجات غير متاح حدّث الفاتورة';END IF;
    SELECT x INTO policy FROM jsonb_array_elements(advanced->'productPolicies') x WHERE x->>'productId'=product_id::text;
    line_name:=product.name;line_kind:=coalesce(policy->>'kind','product');
    IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(advanced->'excludedCategories') x WHERE x=product.category_id::text OR x=product.legacy_category OR x=(SELECT name FROM public.menu_categories WHERE id=product.category_id AND cafe_id=p_cafe_id)) THEN RAISE EXCEPTION 'صنف البند مستبعد من الفواتير';END IF;
   END IF;
   IF p_source_id IS NULL AND ((advanced->>'activityKind'='products' AND line_kind<>'product') OR (advanced->>'activityKind'='services' AND line_kind<>'service')) THEN RAISE EXCEPTION 'نوع البند لا يطابق نشاط الفواتير';END IF;
   catalog_price:=product.price;
   IF price_list IS NOT NULL THEN SELECT coalesce((x->>'price')::numeric,product.price) INTO catalog_price FROM jsonb_array_elements(price_list->'prices') x WHERE x->>'productId'=product_id::text AND coalesce(x->>'catalogSource','menu')=CASE WHEN inventory_source THEN 'inventory' ELSE 'menu' END;
    IF inventory_source AND catalog_price IS NOT NULL THEN catalog_price:=round(catalog_price*inventory_factor/(inventory->>'saleUnitFactor')::numeric,2);END IF;
    catalog_price:=coalesce(catalog_price,product.price);END IF;
   catalog_price:=round(catalog_price/fx,2);qty:=(entry->>'quantity')::numeric;price:=coalesce((entry->>'price')::numeric,catalog_price);
   IF qty IS NULL OR qty<=0 OR qty>9999 OR qty<>round(qty,3) OR price IS NULL OR price<0 OR price>10000000 OR price<>round(price,2) OR length(coalesce(entry->>'description',''))>500 THEN RAISE EXCEPTION 'راجع كميات وأسعار البنود';END IF;
   IF product_id IS NOT NULL AND NOT(prefs->>'allowLineEditing')::boolean AND (price IS DISTINCT FROM catalog_price OR (coalesce(entry->>'description','')<>'' AND coalesce(entry->>'description','') IS DISTINCT FROM coalesce(product.description,''))) THEN RAISE EXCEPTION 'Invoice settings: catalog line editing disabled' USING ERRCODE='22023';END IF;
   rate:=CASE WHEN p_source_id IS NOT NULL THEN coalesce((entry->>'vatRate')::numeric,15) WHEN advanced->>'taxMode'='none' THEN 0 WHEN advanced->>'taxMode'='specific' THEN (advanced->>'specificTaxRate')::numeric WHEN product_id IS NOT NULL THEN coalesce((policy->>'vatRate')::numeric,15) ELSE coalesce((entry->>'vatRate')::numeric,15) END;
   tax_category:=CASE WHEN rate=15 THEN 'S' WHEN advanced->>'taxMode'='none' AND p_source_id IS NULL THEN 'O' WHEN advanced->>'taxMode'='product' AND product_id IS NOT NULL THEN coalesce(policy->>'taxCategory','Z') ELSE coalesce(nullif(entry->>'taxCategory','S'),'Z') END;
   exemption:=coalesce(nullif(entry->>'exemptionReason',''),nullif(policy->>'exemptionReason',''),advanced->>'exemptionReason','');
   IF rate NOT IN(0,15) OR tax_category NOT IN('S','Z','E','O') OR (rate=15) IS DISTINCT FROM(tax_category='S') OR length(exemption)>250 OR (rate=0 AND (advanced->>'taxRequired')::boolean AND btrim(exemption)='') THEN RAISE EXCEPTION 'أكمل فئة الضريبة وسبب الإعفاء أو النسبة الصفرية';END IF;
   gross:=round(qty*price,2);discount_value:=coalesce((entry->>'discount')::numeric,0);
   IF coalesce(entry->>'discountKind','amount') NOT IN('amount','percent') OR discount_value<0 OR discount_value>1000000000 OR (entry->>'discountKind'='percent' AND discount_value>100) THEN RAISE EXCEPTION 'Invalid line discount';END IF;
   row_discount:=round(CASE WHEN entry->>'discountKind'='percent' THEN gross*discount_value/100 ELSE discount_value END,2);
   IF prefs->>'discountMode'='invoice' AND row_discount>0 THEN RAISE EXCEPTION 'Invoice settings: line discounts disabled' USING ERRCODE='22023';END IF;
   IF row_discount>gross THEN RAISE EXCEPTION 'خصم البند أكبر من قيمته';END IF;
   row_after:=gross-row_discount;subtotal:=subtotal+gross;after_rows:=after_rows+row_after;
   rows:=rows||jsonb_build_array(jsonb_build_object('productId',coalesce(product_id::text,''),'catalogSource',CASE WHEN inventory_source THEN 'inventory' ELSE 'menu' END,'unitName',inventory_unit,'unitFactor',inventory_factor,'name',line_name,'kind',line_kind,'description',coalesce(entry->>'description',''),'quantity',qty,'price',price,'gross',gross,'rowDiscount',row_discount,'after',row_after,'vatRate',rate,'taxCategory',tax_category,'exemptionReason',exemption,'minimum',CASE WHEN (advanced->>'advancedPricing')::boolean THEN coalesce((policy->>'minimumPrice')::numeric,0) ELSE 0 END));
  END LOOP;
  discount_value:=CASE WHEN coalesce((inv->>'discountEnabled')::boolean,true) THEN coalesce((inv->>'discountValue')::numeric,0) ELSE 0 END;
  IF coalesce(inv->>'discountKind','amount') NOT IN('amount','percent') OR discount_value<0 OR discount_value>1000000000 OR (inv->>'discountKind'='percent' AND discount_value>100) THEN RAISE EXCEPTION 'Invalid invoice discount';END IF;
  doc_discount:=round(CASE WHEN inv->>'discountKind'='percent' THEN after_rows*discount_value/100 ELSE discount_value END,2);
  IF prefs->>'discountMode'='line' AND doc_discount>0 THEN RAISE EXCEPTION 'Invoice settings: invoice discounts disabled' USING ERRCODE='22023';END IF;
  IF doc_discount>after_rows THEN RAISE EXCEPTION 'خصم الفاتورة أكبر من قيمتها';END IF;
  cap:=100;IF (advanced->>'discountCapsEnabled')::boolean THEN SELECT (x->>'percent')::numeric INTO cap FROM jsonb_array_elements(advanced->'discountCaps') x WHERE x->>'userId'=p_actor::text;cap:=coalesce(cap,100);END IF;
  IF subtotal>0 AND subtotal-after_rows+doc_discount>round(subtotal*cap/100,2) THEN RAISE EXCEPTION 'الخصم يتجاوز الحد المسموح للمستخدم';END IF;
  remaining:=doc_discount;base_left:=after_rows;
  FOR entry IN SELECT value FROM jsonb_array_elements(rows) LOOP
   row_after:=(entry->>'after')::numeric;allocated:=least(row_after,remaining,CASE WHEN base_left=0 THEN 0 ELSE round(remaining*row_after/base_left,2) END);remaining:=remaining-allocated;base_left:=base_left-row_after;taxable:=row_after-allocated;rate:=(entry->>'vatRate')::numeric;
   row_tax:=CASE WHEN inclusive THEN round(taxable-taxable/(1+rate/100),2) ELSE round(taxable*rate/100,2) END;row_net:=CASE WHEN inclusive THEN taxable-row_tax ELSE taxable END;row_total:=row_net+row_tax;
   IF (CASE WHEN (advanced->>'minimumIncludesTax')::boolean THEN row_total ELSE row_net END)*fx < (entry->>'minimum')::numeric*(entry->>'quantity')::numeric THEN RAISE EXCEPTION 'سعر البند بعد الخصم أقل من الحد الأدنى';END IF;
   final_rows:=final_rows||jsonb_build_array(entry||jsonb_build_object('discount',(entry->>'rowDiscount')::numeric+allocated,'net',row_net,'tax',row_tax,'total',row_total));
   adjustment_base:=adjustment_base+CASE WHEN inclusive THEN row_total ELSE row_net END;
  END LOOP;
  adjustment_id:=nullif(inv#>>'{adjustment,typeId}','')::uuid;adjustment_amount:=coalesce((inv#>>'{adjustment,amount}')::numeric,0);
  IF adjustment_amount<0 OR adjustment_amount>1000000000 OR adjustment_amount<>round(adjustment_amount,2) OR (adjustment_id IS NULL AND adjustment_amount<>0) THEN RAISE EXCEPTION 'راجع قيمة التسوية';END IF;
  IF adjustment_id IS NOT NULL THEN
   SELECT x INTO adjustment_rule FROM jsonb_array_elements(advanced->'adjustments') x WHERE x->>'id'=adjustment_id::text;
   IF NOT(advanced->>'adjustmentsEnabled')::boolean OR adjustment_rule IS NULL OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=(adjustment_rule->>'accountId')::uuid AND active AND kind IN('revenue','expense') AND code<>'5000') THEN RAISE EXCEPTION 'حساب التسوية غير متاح';END IF;
   IF adjustment_rule->>'kind'='deduction' AND adjustment_amount>adjustment_base THEN RAISE EXCEPTION 'التسوية أكبر من قيمة الفاتورة';END IF;
   IF adjustment_rule->>'kind'='deduction' AND subtotal-after_rows+doc_discount+adjustment_amount>round(subtotal*cap/100,2) THEN RAISE EXCEPTION 'الخصم والتسوية يتجاوزان الحد المسموح للمستخدم';END IF;
  END IF;
  remaining:=adjustment_amount;base_left:=adjustment_base;rows:='[]';
  FOR entry IN SELECT value FROM jsonb_array_elements(final_rows) LOOP
   row_net:=(entry->>'net')::numeric;row_tax:=(entry->>'tax')::numeric;row_total:=(entry->>'total')::numeric;rate:=(entry->>'vatRate')::numeric;row_after:=CASE WHEN inclusive THEN row_total ELSE row_net END;
   allocated:=CASE WHEN base_left=0 THEN 0 ELSE round(remaining*row_after/base_left,2) END;remaining:=remaining-allocated;base_left:=base_left-row_after;
   IF adjustment_rule->>'kind'='deduction' THEN allocated:=-allocated;END IF;
   adjustment_line_tax:=CASE WHEN coalesce((adjustment_rule->>'taxable')::boolean,false) THEN CASE WHEN inclusive THEN round(allocated-allocated/(1+rate/100),2) ELSE round(allocated*rate/100,2) END ELSE 0 END;
   adjustment_line_net:=CASE WHEN inclusive AND coalesce((adjustment_rule->>'taxable')::boolean,false) THEN allocated-adjustment_line_tax ELSE allocated END;
   row_net:=row_net+adjustment_line_net;row_tax:=row_tax+adjustment_line_tax;row_total:=row_net+row_tax;
   IF row_net<0 OR row_tax<0 THEN RAISE EXCEPTION 'التسوية تنتج مبلغًا أو ضريبة سالبة';END IF;
   IF (CASE WHEN (advanced->>'minimumIncludesTax')::boolean THEN row_total ELSE row_net END)*fx < (entry->>'minimum')::numeric*(entry->>'quantity')::numeric THEN RAISE EXCEPTION 'سعر البند بعد التسوية أقل من الحد الأدنى';END IF;
   sar_line_net:=round(row_net*fx,2);sar_line_tax:=round(row_tax*fx,2);sar_net:=sar_net+sar_line_net;sar_tax:=sar_tax+sar_line_tax;sar_subtotal:=sar_subtotal+round((entry->>'gross')::numeric*fx,2);
   sar_adjustment_net:=sar_adjustment_net+round(adjustment_line_net*fx,2);sar_adjustment_tax:=sar_adjustment_tax+round(adjustment_line_tax*fx,2);
   net:=net+row_net;tax:=tax+row_tax;total:=total+row_total;adjustment_net:=adjustment_net+adjustment_line_net;adjustment_tax:=adjustment_tax+adjustment_line_tax;
   rows:=rows||jsonb_build_array(entry||jsonb_build_object('net',row_net,'tax',row_tax,'total',row_total,'sarNet',sar_line_net,'sarTax',sar_line_tax,'adjustmentNet',round(adjustment_line_net*fx,2),'adjustmentTax',round(adjustment_line_tax*fx,2)));
  END LOOP;
  final_rows:=rows;sar_total:=sar_net+sar_tax;sar_discount:=round((subtotal-after_rows+doc_discount)*fx,2);
  IF total<=0 OR total>1000000000 OR sar_total<=0 OR sar_total>1000000000 OR (NOT p_preview AND p_expected_total IS DISTINCT FROM total) THEN RAISE EXCEPTION 'راجع إجمالي الفاتورة قبل الإصدار';END IF;
  IF p_preview THEN RETURN jsonb_build_object('subtotal',subtotal,'discount',subtotal-after_rows+doc_discount,'tax',tax,'total',total,'lines',final_rows);END IF;
  credit_sar:=CASE WHEN p_source_id IS NULL AND coalesce((inv->>'applyCredit')::boolean,false) THEN least(sar_total,brand_finance_private.customer_credit_balance(p_cafe_id,customer.id)) ELSE 0 END;
  credit_foreign:=least(total,round(credit_sar/fx,2));deposit_amount:=round(CASE WHEN deposit_kind='percent' THEN total*deposit_value/100 ELSE deposit_value END,2);
  IF deposit_amount>total THEN RAISE EXCEPTION 'الدفعة المقدمة أكبر من إجمالي الفاتورة';END IF;
  paid:=CASE WHEN deposit_value>0 THEN CASE WHEN deposit_paid THEN deposit_amount ELSE 0 END WHEN aid IS NULL THEN 0 ELSE total-credit_foreign END;
  cash_sar:=CASE WHEN deposit_value=0 AND aid IS NOT NULL THEN sar_total-credit_sar ELSE round(paid*fx,2) END;
  IF cash_sar+credit_sar>sar_total THEN RAISE EXCEPTION 'الدفعة ورصيد العميل يتجاوزان المبلغ المستحق';END IF;
  display_number:=coalesce(erp_settings_private.prepare_advance(p_cafe_id,doc,p_draft_id,p_source_id,inv,final_rows,sar_net,sar_tax,sar_total,currency_code,fx,NULL,adjustment_id,issue_at),brand_finance_private.invoice_number_allocate(p_cafe_id,CASE WHEN p_source_id IS NULL THEN 'invoice' ELSE 'debit' END,advanced->CASE WHEN p_source_id IS NULL THEN 'numbering' ELSE 'debitNumbering' END,coalesce(inv->>'manualNumber','')));
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,warehouse_id,subtotal,discount,tax,total,paid,reference_id,note,created_by,created_at,vat_rate,tax_inclusive)
   VALUES(doc,p_cafe_id,'sale',customer.id,aid,wid,sar_subtotal,sar_discount,sar_tax,sar_total,cash_sar,p_source_id,left(coalesce(inv->>'note',''),1000),p_actor,issue_at,CASE WHEN tax=0 THEN 0 ELSE 15 END,inclusive) RETURNING number INTO n;
  journal_note:=CASE WHEN (advanced->>'journalTemplateEnabled')::boolean THEN replace(replace(replace(replace(advanced->>'journalTemplate','{number}',display_number),'{customer}',customer.name),'{date}',(issue_at AT TIME ZONE 'Asia/Riyadh')::date::text),'{total}',sar_total::text) ELSE '' END;journal_note:=left(journal_note,300);
  FOR entry IN SELECT value FROM jsonb_array_elements(final_rows) LOOP
   line_id:=gen_random_uuid();
   INSERT INTO public.bf_document_lines(id,cafe_id,document_id,product_id,name,quantity,unit_price,net,tax,cost,activity_kind,vat_rate,tax_category,exemption_reason,inventory_item_id,unit_label,stock_unit_factor)
    VALUES(line_id,p_cafe_id,doc,CASE WHEN entry->>'catalogSource'='inventory' THEN NULL ELSE nullif(entry->>'productId','')::uuid END,entry->>'name',(entry->>'quantity')::numeric,round((entry->>'price')::numeric*fx,2),(entry->>'sarNet')::numeric,(entry->>'sarTax')::numeric,0,entry->>'kind',(entry->>'vatRate')::numeric,entry->>'taxCategory',entry->>'exemptionReason',CASE WHEN entry->>'catalogSource'='inventory' THEN (entry->>'productId')::uuid ELSE NULL END,nullif(entry->>'unitName',''),coalesce((entry->>'unitFactor')::numeric,1))
    RETURNING bf_document_lines.cost,bf_document_lines.cost_status INTO cost,line_cost_status;
   IF p_source_id IS NULL AND entry->>'kind'='product' AND NOT(prefs->>'allowBelowCost')::boolean THEN
    IF line_cost_status IS DISTINCT FROM 'known' AND NOT EXISTS(SELECT 1 FROM public.erp_sales_requisition_lines pending WHERE pending.cafe_id=p_cafe_id AND pending.id=line_id) THEN RAISE EXCEPTION 'Invoice settings: known inventory cost required' USING ERRCODE='22023';END IF;
    IF (entry->>'sarNet')::numeric<cost THEN RAISE EXCEPTION 'Invoice settings: below inventory cost' USING ERRCODE='22023';END IF;
   END IF;
   IF adjustment_id IS NOT NULL AND ((entry->>'adjustmentNet')::numeric<>0 OR (entry->>'adjustmentTax')::numeric<>0) THEN INSERT INTO public.bf_invoice_adjustment_lines(cafe_id,document_id,line_id,account_id,net,tax) VALUES(p_cafe_id,doc,line_id,(adjustment_rule->>'accountId')::uuid,(entry->>'adjustmentNet')::numeric,(entry->>'adjustmentTax')::numeric);END IF;
   PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'5000'),cost,0,NULL,journal_note);PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'1200'),0,cost,NULL,journal_note);
  END LOOP;
  PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,aid,cash_sar,0,NULL,journal_note);
  PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'1100'),sar_total-cash_sar,0,customer.id,journal_note);
  PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,CASE WHEN EXISTS(SELECT 1 FROM public.erp_contracting_advance_invoices WHERE cafe_id=p_cafe_id AND invoice_id=doc) THEN brand_finance_private.customer_credit_account(p_cafe_id) ELSE brand_finance_private.account(p_cafe_id,'4000') END,0,sar_net-sar_adjustment_net,CASE WHEN EXISTS(SELECT 1 FROM public.erp_contracting_advance_invoices WHERE cafe_id=p_cafe_id AND invoice_id=doc) THEN customer.id ELSE NULL END,journal_note);
  IF sar_adjustment_net<>0 THEN PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,(adjustment_rule->>'accountId')::uuid,greatest(-sar_adjustment_net,0),greatest(sar_adjustment_net,0),NULL,journal_note);END IF;
  PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'2100'),0,sar_tax,NULL,journal_note);
  IF credit_sar>0 THEN PERFORM brand_finance_private.customer_credit_apply(p_cafe_id,doc,credit_sar);END IF;
  phone:=regexp_replace(translate(coalesce(customer.phone,''),'٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹','01234567890123456789'),'[^0-9]','','g');IF phone LIKE '00%' THEN phone:=substr(phone,3);END IF;IF phone~'^05[0-9]{8}$' THEN phone:='966'||substr(phone,2);ELSIF phone~'^5[0-9]{8}$' THEN phone:='966'||phone;END IF;
  IF coalesce(draft.payload->>'deliveryMethod','print') NOT IN('print','whatsapp','email','both') THEN RAISE EXCEPTION 'طريقة إرسال الفاتورة غير صالحة';END IF;
  IF draft.payload->>'deliveryMethod'='whatsapp' AND NOT((advanced->>'socialEnabled')::boolean AND advanced->'socialPlatforms' ? 'whatsapp') THEN RAISE EXCEPTION 'إرسال الواتساب غير مفعل في إعدادات الفواتير';END IF;
  IF draft.payload->>'deliveryMethod' IN('email','both') AND NOT(advanced->>'billingMethod' IN('email','both') OR ((advanced->>'socialEnabled')::boolean AND advanced->'socialPlatforms' ? 'email')) THEN RAISE EXCEPTION 'إرسال البريد الإلكتروني غير مفعل في إعدادات الفواتير';END IF;
  IF draft.payload->>'deliveryMethod'='whatsapp' AND phone!~'^9665[0-9]{8}$' THEN RAISE EXCEPTION 'أدخل رقم جوال سعودي صحيح للعميل قبل إرسال الواتساب';END IF;
  IF draft.payload->>'deliveryMethod' IN('email','both') AND coalesce(customer.email,'')!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'أكمل البريد الإلكتروني الصحيح للعميل';END IF;
  SELECT coalesce(jsonb_agg(x-ARRAY['sarNet','sarTax','adjustmentNet','adjustmentTax','minimum']), '[]') INTO final_rows FROM jsonb_array_elements(final_rows) x;
  result:=jsonb_build_object('id',doc,'number',n,'displayNumber',display_number,'type',invoice_type,'documentType',CASE WHEN p_source_id IS NULL THEN 'invoice' ELSE 'debit' END,'sourceId',p_source_id,'sourceNumber',coalesce((SELECT e.display_number FROM public.bf_invoice_extensions e WHERE e.document_id=p_source_id),source_doc.number::text),'reason',p_debit_reason,'issuedAt',issue_at,'supplyDate',supply_date,'seller',seller,
   'customer',jsonb_build_object('name',coalesce(nullif(customer.details->>'legalName',''),customer.name),'vatNumber',customer.tax_number,'address',buyer_address,'phone',phone,'email',customer.email),
   'lines',final_rows,'subtotal',subtotal,'discount',subtotal-after_rows+doc_discount,'tax',tax,'total',total,'paid',paid+credit_foreign,'cashPaid',paid,'creditApplied',credit_foreign,'taxInclusive',inclusive,'currency',currency_code,'exchangeRate',fx,'decimalDisplay',prefs->>'decimalDisplay',
   'sar',jsonb_build_object('subtotal',sar_subtotal,'discount',sar_discount,'tax',sar_tax,'total',sar_total,'paid',cash_sar+credit_sar,'cashPaid',cash_sar,'creditApplied',credit_sar),
   'adjustment',CASE WHEN adjustment_id IS NULL THEN NULL ELSE jsonb_build_object('typeId',adjustment_id,'amount',adjustment_amount,'kind',adjustment_rule->>'kind','taxable',(adjustment_rule->>'taxable')::boolean,'name',adjustment_rule->>'name','net',adjustment_net,'tax',adjustment_tax,'total',adjustment_net+adjustment_tax) END,
   'deposit',jsonb_build_object('kind',deposit_kind,'value',deposit_value,'amount',deposit_amount,'paid',deposit_paid),'shipping',jsonb_build_object('mode',shipping_mode,'address',shipping_address),'delivery',jsonb_build_object('confirmed',delivery_confirmed,'date',coalesce(delivery_date::text,'')),
   'attachments',files,'note',coalesce(inv->>'note',''),'extraFields',coalesce(draft.payload->'extraFields','[]'::jsonb),'template',draft.payload->>'template','deliveryMethod',coalesce(draft.payload->>'deliveryMethod','print'));
  IF EXISTS(SELECT 1 FROM public.erp_contracting_advance_invoices WHERE cafe_id=p_cafe_id AND invoice_id=doc) THEN result:=result||jsonb_build_object('documentType','advance','invoiceTypeCode','386','advancePayment',true);END IF; INSERT INTO public.bf_company_invoices(document_id,cafe_id,draft_id,snapshot) VALUES(doc,p_cafe_id,p_draft_id,result); SELECT snapshot INTO result FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND document_id=doc;
  INSERT INTO public.bf_invoice_extensions(cafe_id,document_id,display_number,source_id,status_id,metadata,created_by) VALUES(p_cafe_id,doc,display_number,p_source_id,status_id,jsonb_build_object('currency',currency_code,'exchangeRate',fx,'reason',p_debit_reason),p_actor);
  RETURN result;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.issue_manual_invoice_shipping_actor(p_actor uuid, p_preview boolean, p_cafe_id uuid, p_draft_id uuid, p_revision integer, p_expected_total numeric, p_source_id uuid DEFAULT NULL::uuid, p_debit_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE inventory jsonb;inventory_factor numeric;inventory_unit text;inventory_source boolean;draft public.bf_invoice_drafts%ROWTYPE; customer public.bf_parties%ROWTYPE; cfg public.bf_settings%ROWTYPE;
  inv jsonb; seller jsonb; entry jsonb; product public.menu_products%ROWTYPE; existing jsonb; doc uuid:=gen_random_uuid();
  aid uuid; wid uuid; n bigint; issue_at timestamptz:=clock_timestamp(); supply_date date; rows jsonb:='[]'; final_rows jsonb:='[]';
  qty numeric; price numeric; gross numeric; row_discount numeric; rate numeric; row_after numeric; remaining numeric; base_left numeric;
  allocated numeric; taxable numeric; row_tax numeric; row_net numeric; row_total numeric; cost numeric; paid numeric;
  subtotal numeric:=0; after_rows numeric:=0; doc_discount numeric; tax numeric:=0; total numeric:=0; net numeric:=0;
  discount_value numeric; inclusive boolean; result jsonb; buyer_address text; seller_tax text; phone text; invoice_type text;
  deposit jsonb; deposit_value numeric; deposit_amount numeric; deposit_paid boolean; deposit_kind text;
  shipping_mode text; shipping_address text; delivery_confirmed boolean; delivery_date timestamptz;
  prefs jsonb;line_cost_status text;file_ids jsonb; file_id uuid; files jsonb:='[]'; attached public.bf_company_invoice_files%ROWTYPE;
  advanced jsonb;currency_code text;fx numeric;source_doc public.bf_documents%ROWTYPE;status_id uuid;list_id uuid;price_list jsonb;product_id uuid;policy jsonb;line_name text;line_kind text;catalog_price numeric;tax_category text;exemption text;cap numeric;
  adjustment_base numeric:=0;adjustment_id uuid;adjustment_rule jsonb;adjustment_amount numeric;adjustment_line_net numeric;adjustment_line_tax numeric;adjustment_net numeric:=0;adjustment_tax numeric:=0;
  sar_line_net numeric;sar_line_tax numeric;sar_net numeric:=0;sar_tax numeric:=0;sar_subtotal numeric:=0;sar_discount numeric;sar_total numeric;sar_adjustment_net numeric:=0;sar_adjustment_tax numeric:=0;
  credit_sar numeric;credit_foreign numeric;cash_sar numeric;display_number text;journal_note text;line_id uuid;
  shipping_charge jsonb;shipping_net numeric:=0;shipping_tax numeric:=0;shipping_sar_net numeric:=0;shipping_sar_tax numeric:=0;shipping_line_id uuid;requested_shipping_mode text;cod_service_id text;cod_service_indices jsonb:='[]';
BEGIN
  IF p_actor IS NULL OR coalesce(brand_finance_private.invoice_actor_role(p_cafe_id,p_actor),'') NOT IN ('owner','manager','accountant')
  THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
  SELECT snapshot INTO existing FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  IF FOUND THEN RETURN existing; END IF;
  SELECT * INTO draft FROM public.bf_invoice_drafts WHERE id=p_draft_id AND cafe_id=p_cafe_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501'; END IF;
  IF draft.revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'Draft conflict' USING ERRCODE='40001'; END IF;
  prefs:=brand_finance_private.invoice_settings(p_cafe_id);
  inv:=draft.payload->'invoice'; seller:=draft.payload->'issuer';
  IF inv IS NULL OR jsonb_typeof(inv->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(inv->'lines') NOT BETWEEN 1 AND 100
    OR draft.payload::text ~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'Invalid invoice'; END IF;
  IF coalesce(length(btrim(seller->>'name')),0) NOT BETWEEN 2 AND 160 OR coalesce(length(btrim(seller->>'address')),0) NOT BETWEEN 8 AND 500
    OR octet_length(seller->>'name')>255 OR coalesce(seller->>'vatNumber','') !~ '^3[0-9]{13}3$' THEN RAISE EXCEPTION 'أكمل الاسم القانوني وعنوان البائع والرقم الضريبي الصحيح'; END IF;
  SELECT tax_number INTO seller_tax FROM public.cafe_settings WHERE cafe_id=p_cafe_id;
  IF nullif(btrim(seller_tax),'') IS NOT NULL AND btrim(seller_tax)<>seller->>'vatNumber' THEN RAISE EXCEPTION 'رقم البائع الضريبي لا يطابق إعدادات العلامة'; END IF;
  supply_date:=(draft.payload->>'supplyDate')::date;
  IF supply_date IS NULL OR NOT isfinite(supply_date) OR supply_date>(issue_at AT TIME ZONE 'Asia/Riyadh')::date THEN RAISE EXCEPTION 'اختر تاريخ توريد صالحًا'; END IF;
  PERFORM brand_finance_private.seed(p_cafe_id);
  SELECT * INTO STRICT cfg FROM public.bf_settings WHERE cafe_id=p_cafe_id FOR UPDATE;
  PERFORM brand_finance_private.gl_date_open(p_cafe_id,(issue_at AT TIME ZONE 'Asia/Riyadh')::date);
  SELECT * INTO customer FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id::text=(inv->>'partyId') AND active AND kind='customer';
  IF NOT FOUND THEN RAISE EXCEPTION 'اختر عميلًا نشطًا'; END IF;
  IF coalesce(customer.details->>'customerType','individual') NOT IN ('individual','business') THEN RAISE EXCEPTION 'حدد نوع العميل فردًا أو شركة'; END IF;
  invoice_type:=CASE WHEN coalesce(customer.details->>'customerType','individual')='individual' AND nullif(btrim(customer.tax_number),'') IS NULL THEN 'simplified' ELSE 'standard' END;
  IF invoice_type='standard' AND coalesce(customer.tax_number,'') !~ '^3[0-9]{13}3$' THEN RAISE EXCEPTION 'أكمل الرقم الضريبي الصحيح للعميل من ١٥ رقمًا'; END IF;
  buyer_address:=concat_ws(' ',nullif(customer.details->>'buildingNumber',''),nullif(customer.details->>'street',''),nullif(customer.details->>'district',''),nullif(customer.details->>'city',''),nullif(customer.details->>'postalCode',''),nullif(customer.details->>'country',''));
  IF invoice_type='standard' AND (coalesce(length(buyer_address),0)<8 OR nullif(customer.details->>'city','') IS NULL OR nullif(customer.details->>'street','') IS NULL) THEN RAISE EXCEPTION 'أكمل عنوان العميل في بياناته قبل الإصدار'; END IF;
  wid:=nullif(inv->>'warehouseId','')::uuid;
  IF NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id=wid AND active) THEN RAISE EXCEPTION 'اختر مستودعًا نشطًا'; END IF;
  IF coalesce(inv->>'paymentKind','') NOT IN ('cash','bank','pos','credit') THEN RAISE EXCEPTION 'Invalid payment'; END IF;
  IF inv->>'paymentKind'<>'credit' THEN
    aid:=nullif(inv->>'accountId','')::uuid;
    IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=aid AND active AND kind=inv->>'paymentKind' AND NOT is_cashier_drawer)
      THEN RAISE EXCEPTION 'اختر حساب تحصيل إداريًا نشطًا خارج صناديق ورديات الكاشير'; END IF;
  END IF;
  deposit:=coalesce(draft.payload->'deposit','{"kind":"amount","value":0,"paid":false}'::jsonb);
  deposit_kind:=deposit->>'kind';deposit_value:=(deposit->>'value')::numeric;deposit_paid:=(deposit->>'paid')::boolean;
  IF jsonb_typeof(deposit)<>'object' OR deposit_kind IS NULL OR deposit_kind NOT IN ('amount','percent') OR deposit_value IS NULL OR deposit_paid IS NULL OR deposit_value<0 OR deposit_value>1000000000 OR deposit_value<>round(deposit_value,2) OR (deposit_kind='percent' AND deposit_value>100) THEN RAISE EXCEPTION 'راجع قيمة الدفعة المقدمة'; END IF;
  IF deposit_value>0 AND ((deposit_paid AND aid IS NULL) OR (NOT deposit_paid AND aid IS NOT NULL)) THEN RAISE EXCEPTION 'حدد حالة تحصيل الدفعة وحسابها'; END IF;
  IF NOT (prefs->>'allowDeposits')::boolean AND deposit_value>0 THEN RAISE EXCEPTION 'Invoice settings: deposits disabled' USING ERRCODE='22023';END IF;
  shipping_mode:=coalesce(draft.payload->>'shipping','none');requested_shipping_mode:=shipping_mode;
  IF shipping_mode='auto' THEN
   shipping_mode:=CASE WHEN nullif(btrim(customer.details->>'shippingStreet'),'') IS NOT NULL AND nullif(btrim(customer.details->>'shippingCity'),'') IS NOT NULL AND nullif(btrim(customer.details->>'shippingCountry'),'') IS NOT NULL THEN 'secondary' ELSE 'main' END;
  END IF;
  IF shipping_mode NOT IN ('none','main','secondary') THEN RAISE EXCEPTION 'Invalid shipping mode'; END IF;
  shipping_address:=CASE shipping_mode WHEN 'main' THEN buyer_address WHEN 'secondary' THEN concat_ws(' ',nullif(customer.details->>'shippingBuildingNumber',''),nullif(customer.details->>'shippingStreet',''),nullif(customer.details->>'shippingDistrict',''),nullif(customer.details->>'shippingCity',''),nullif(customer.details->>'shippingPostalCode',''),nullif(customer.details->>'shippingCountry','')) ELSE '' END;
  IF shipping_mode<>'none' AND (length(shipping_address)<8 OR nullif(customer.details->>CASE WHEN shipping_mode='main' THEN 'street' ELSE 'shippingStreet' END,'') IS NULL OR nullif(customer.details->>CASE WHEN shipping_mode='main' THEN 'city' ELSE 'shippingCity' END,'') IS NULL) THEN RAISE EXCEPTION 'أكمل عنوان الشحن المختار في بيانات العميل'; END IF;
  delivery_confirmed:=coalesce((draft.payload#>>'{delivery,confirmed}')::boolean,false);
  delivery_date:=nullif(draft.payload#>>'{delivery,date}','')::timestamptz;
  IF delivery_confirmed AND (delivery_date IS NULL OR NOT isfinite(delivery_date) OR delivery_date>issue_at) THEN RAISE EXCEPTION 'اختر وقت تسليم صحيحًا لا يتجاوز الوقت الحالي'; END IF;
  IF NOT delivery_confirmed THEN delivery_date:=NULL; END IF;
  file_ids:=coalesce(draft.payload->'attachments','[]'::jsonb);
  IF jsonb_typeof(file_ids)<>'array' OR jsonb_array_length(file_ids)>20 OR (SELECT count(DISTINCT value)<>count(*) FROM jsonb_array_elements(file_ids)) THEN RAISE EXCEPTION 'Invalid attachments'; END IF;
  FOR file_id IN SELECT value::uuid FROM jsonb_array_elements_text(file_ids) LOOP
    SELECT * INTO attached FROM public.bf_company_invoice_files WHERE id=file_id AND cafe_id=p_cafe_id AND uploaded FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'أحد المستندات غير متاح أو لم يكتمل رفعه'; END IF;
    files:=files||jsonb_build_array(jsonb_build_object('id',attached.id,'name',attached.original_name,'size',attached.size_bytes));
  END LOOP;
  inclusive:=coalesce((inv->>'taxInclusive')::boolean,cfg.tax_inclusive);
  advanced:=prefs->'advanced';currency_code:=coalesce(nullif(inv->>'currency',''),'SAR');
  SELECT (c->>'rate')::numeric INTO fx FROM jsonb_array_elements(advanced->'currencies') c WHERE c->>'code'=currency_code;
  IF fx IS NULL THEN RAISE EXCEPTION 'عملة الفاتورة غير مفعلة';END IF;
  IF NOT(advanced->>'showExchangeRate')::boolean AND inv ? 'exchangeRate' AND (inv->>'exchangeRate')::numeric IS DISTINCT FROM fx THEN RAISE EXCEPTION 'تعديل سعر الصرف غير مسموح في إعدادات الفاتورة';END IF;
  fx:=coalesce((inv->>'exchangeRate')::numeric,fx);
  IF fx<=0 OR fx>1000000 OR fx<>round(fx,6) OR (currency_code='SAR' AND fx<>1) THEN RAISE EXCEPTION 'راجع سعر صرف العملة';END IF;
  IF p_source_id IS NOT NULL THEN
   SELECT * INTO source_doc FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_source_id AND kind='sale' FOR UPDATE;
   IF source_doc.id IS NULL OR NOT(advanced->>'debitNotesEnabled')::boolean OR source_doc.party_id<>customer.id OR EXISTS(SELECT 1 FROM public.bf_invoice_extensions WHERE document_id=p_source_id AND source_id IS NOT NULL) OR (brand_finance_private.document_state(p_cafe_id,p_source_id)->>'refunded')::boolean OR length(btrim(p_debit_reason)) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'الفاتورة غير متاحة لإشعار مدين';END IF;
  END IF;
  status_id:=nullif(inv->>'statusId','')::uuid;
  IF status_id IS NOT NULL AND (NOT(advanced->>'customStatusesEnabled')::boolean OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(advanced->'statuses') s WHERE s->>'id'=status_id::text)) THEN RAISE EXCEPTION 'حالة الفاتورة غير متاحة';END IF;
  list_id:=nullif(inv->>'priceListId','')::uuid;
  IF list_id IS NOT NULL THEN
   SELECT x INTO price_list FROM jsonb_array_elements(advanced->'priceLists') x WHERE x->>'id'=list_id::text AND (x->>'active')::boolean;
   IF NOT(advanced->>'priceListsEnabled')::boolean OR price_list IS NULL OR (jsonb_array_length(price_list->'partyIds')>0 AND NOT(price_list->'partyIds' ? customer.id::text)) THEN RAISE EXCEPTION 'قائمة الأسعار غير متاحة لهذا العميل';END IF;
  END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(inv->'lines') LOOP
   product:=NULL;policy:=NULL;product_id:=nullif(entry->>'productId','')::uuid;inventory:=NULL;inventory_factor:=1;inventory_unit:='';
   IF coalesce(entry->>'catalogSource','menu') NOT IN('menu','inventory') THEN RAISE EXCEPTION 'مصدر البند غير صالح';END IF;
   inventory_source:=entry->>'catalogSource'='inventory';
   IF inventory_source THEN
    inventory:=erp_inventory_private.sale_item(p_cafe_id,product_id,coalesce(entry->>'unitName',''));
    inventory_factor:=(inventory->>'unitFactor')::numeric;inventory_unit:=inventory->>'unitName';
    IF entry ? 'unitFactor' AND (entry->>'unitFactor')::numeric IS DISTINCT FROM inventory_factor THEN RAISE EXCEPTION 'تغير تحويل الوحدة حدث الصنف ثم أعد المحاولة';END IF;
    IF round((entry->>'quantity')::numeric*inventory_factor,3) IS DISTINCT FROM (entry->>'quantity')::numeric*inventory_factor OR (entry->>'quantity')::numeric*inventory_factor>1000000 THEN RAISE EXCEPTION 'الكمية لا تطابق دقة وحدة المخزون';END IF;
    product.name:=inventory->>'name';product.description:=inventory->>'description';product.price:=(inventory->>'price')::numeric;
    policy:=inventory;line_name:=inventory->>'name';line_kind:=inventory->>'kind';
    IF line_kind='product' AND NOT erp_inventory_private.sale_warehouse_allowed(p_cafe_id,wid,p_actor) THEN RAISE EXCEPTION 'Inventory warehouse write denied' USING ERRCODE='42501';END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(advanced->'excludedCategories') x WHERE x=inventory->>'categoryId' OR x=inventory->>'category') THEN RAISE EXCEPTION 'صنف البند مستبعد من الفواتير';END IF;
   ELSIF product_id IS NULL THEN
    IF p_source_id IS NULL AND NOT(prefs->>'allowLineEditing')::boolean THEN RAISE EXCEPTION 'البنود الحرة غير مسموحة في إعدادات الفاتورة';END IF;
    line_name:=btrim(coalesce(entry->>'name',''));line_kind:=coalesce(entry->>'kind','');
    IF length(line_name) NOT BETWEEN 1 AND 160 OR line_kind NOT IN('product','service') THEN RAISE EXCEPTION 'أكمل اسم البند الحر ونوعه';END IF;
   ELSE
    SELECT * INTO product FROM public.menu_products WHERE cafe_id=p_cafe_id AND id=product_id AND deleted_at IS NULL AND available FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'أحد المنتجات غير متاح حدّث الفاتورة';END IF;
    SELECT x INTO policy FROM jsonb_array_elements(advanced->'productPolicies') x WHERE x->>'productId'=product_id::text;
    line_name:=product.name;line_kind:=coalesce(policy->>'kind','product');
    IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(advanced->'excludedCategories') x WHERE x=product.category_id::text OR x=product.legacy_category OR x=(SELECT name FROM public.menu_categories WHERE id=product.category_id AND cafe_id=p_cafe_id)) THEN RAISE EXCEPTION 'صنف البند مستبعد من الفواتير';END IF;
   END IF;
   IF p_source_id IS NULL AND ((advanced->>'activityKind'='products' AND line_kind<>'product') OR (advanced->>'activityKind'='services' AND line_kind<>'service')) THEN RAISE EXCEPTION 'نوع البند لا يطابق نشاط الفواتير';END IF;
   catalog_price:=product.price;
   IF price_list IS NOT NULL THEN SELECT coalesce((x->>'price')::numeric,product.price) INTO catalog_price FROM jsonb_array_elements(price_list->'prices') x WHERE x->>'productId'=product_id::text AND coalesce(x->>'catalogSource','menu')=CASE WHEN inventory_source THEN 'inventory' ELSE 'menu' END;
    IF inventory_source AND catalog_price IS NOT NULL THEN catalog_price:=round(catalog_price*inventory_factor/(inventory->>'saleUnitFactor')::numeric,2);END IF;
    catalog_price:=coalesce(catalog_price,product.price);END IF;
   catalog_price:=round(catalog_price/fx,2);qty:=(entry->>'quantity')::numeric;price:=coalesce((entry->>'price')::numeric,catalog_price);
   IF qty IS NULL OR qty<=0 OR qty>9999 OR qty<>round(qty,3) OR price IS NULL OR price<0 OR price>10000000 OR price<>round(price,2) OR length(coalesce(entry->>'description',''))>500 THEN RAISE EXCEPTION 'راجع كميات وأسعار البنود';END IF;
   IF product_id IS NOT NULL AND NOT(prefs->>'allowLineEditing')::boolean AND (price IS DISTINCT FROM catalog_price OR (coalesce(entry->>'description','')<>'' AND coalesce(entry->>'description','') IS DISTINCT FROM coalesce(product.description,''))) THEN RAISE EXCEPTION 'Invoice settings: catalog line editing disabled' USING ERRCODE='22023';END IF;
   rate:=CASE WHEN p_source_id IS NOT NULL THEN coalesce((entry->>'vatRate')::numeric,15) WHEN advanced->>'taxMode'='none' THEN 0 WHEN advanced->>'taxMode'='specific' THEN (advanced->>'specificTaxRate')::numeric WHEN product_id IS NOT NULL THEN coalesce((policy->>'vatRate')::numeric,15) ELSE coalesce((entry->>'vatRate')::numeric,15) END;
   tax_category:=CASE WHEN rate=15 THEN 'S' WHEN advanced->>'taxMode'='none' AND p_source_id IS NULL THEN 'O' WHEN advanced->>'taxMode'='product' AND product_id IS NOT NULL THEN coalesce(policy->>'taxCategory','Z') ELSE coalesce(nullif(entry->>'taxCategory','S'),'Z') END;
   exemption:=coalesce(nullif(entry->>'exemptionReason',''),nullif(policy->>'exemptionReason',''),advanced->>'exemptionReason','');
   IF rate NOT IN(0,15) OR tax_category NOT IN('S','Z','E','O') OR (rate=15) IS DISTINCT FROM(tax_category='S') OR length(exemption)>250 OR (rate=0 AND (advanced->>'taxRequired')::boolean AND btrim(exemption)='') THEN RAISE EXCEPTION 'أكمل فئة الضريبة وسبب الإعفاء أو النسبة الصفرية';END IF;
   gross:=round(qty*price,2);discount_value:=coalesce((entry->>'discount')::numeric,0);
   IF coalesce(entry->>'discountKind','amount') NOT IN('amount','percent') OR discount_value<0 OR discount_value>1000000000 OR (entry->>'discountKind'='percent' AND discount_value>100) THEN RAISE EXCEPTION 'Invalid line discount';END IF;
   row_discount:=round(CASE WHEN entry->>'discountKind'='percent' THEN gross*discount_value/100 ELSE discount_value END,2);
   IF prefs->>'discountMode'='invoice' AND row_discount>0 THEN RAISE EXCEPTION 'Invoice settings: line discounts disabled' USING ERRCODE='22023';END IF;
   IF row_discount>gross THEN RAISE EXCEPTION 'خصم البند أكبر من قيمته';END IF;
   row_after:=gross-row_discount;subtotal:=subtotal+gross;after_rows:=after_rows+row_after;
   rows:=rows||jsonb_build_array(jsonb_build_object('productId',coalesce(product_id::text,''),'catalogSource',CASE WHEN inventory_source THEN 'inventory' ELSE 'menu' END,'unitName',inventory_unit,'unitFactor',inventory_factor,'name',line_name,'kind',line_kind,'description',coalesce(entry->>'description',''),'quantity',qty,'price',price,'gross',gross,'rowDiscount',row_discount,'after',row_after,'vatRate',rate,'taxCategory',tax_category,'exemptionReason',exemption,'minimum',CASE WHEN (advanced->>'advancedPricing')::boolean THEN coalesce((policy->>'minimumPrice')::numeric,0) ELSE 0 END));
  END LOOP;
  discount_value:=CASE WHEN coalesce((inv->>'discountEnabled')::boolean,true) THEN coalesce((inv->>'discountValue')::numeric,0) ELSE 0 END;
  IF coalesce(inv->>'discountKind','amount') NOT IN('amount','percent') OR discount_value<0 OR discount_value>1000000000 OR (inv->>'discountKind'='percent' AND discount_value>100) THEN RAISE EXCEPTION 'Invalid invoice discount';END IF;
  doc_discount:=round(CASE WHEN inv->>'discountKind'='percent' THEN after_rows*discount_value/100 ELSE discount_value END,2);
  IF prefs->>'discountMode'='line' AND doc_discount>0 THEN RAISE EXCEPTION 'Invoice settings: invoice discounts disabled' USING ERRCODE='22023';END IF;
  IF doc_discount>after_rows THEN RAISE EXCEPTION 'خصم الفاتورة أكبر من قيمتها';END IF;
  cap:=100;IF (advanced->>'discountCapsEnabled')::boolean THEN SELECT (x->>'percent')::numeric INTO cap FROM jsonb_array_elements(advanced->'discountCaps') x WHERE x->>'userId'=p_actor::text;cap:=coalesce(cap,100);END IF;
  IF subtotal>0 AND subtotal-after_rows+doc_discount>round(subtotal*cap/100,2) THEN RAISE EXCEPTION 'الخصم يتجاوز الحد المسموح للمستخدم';END IF;
  remaining:=doc_discount;base_left:=after_rows;
  FOR entry IN SELECT value FROM jsonb_array_elements(rows) LOOP
   row_after:=(entry->>'after')::numeric;allocated:=least(row_after,remaining,CASE WHEN base_left=0 THEN 0 ELSE round(remaining*row_after/base_left,2) END);remaining:=remaining-allocated;base_left:=base_left-row_after;taxable:=row_after-allocated;rate:=(entry->>'vatRate')::numeric;
   row_tax:=CASE WHEN inclusive THEN round(taxable-taxable/(1+rate/100),2) ELSE round(taxable*rate/100,2) END;row_net:=CASE WHEN inclusive THEN taxable-row_tax ELSE taxable END;row_total:=row_net+row_tax;
   IF (CASE WHEN (advanced->>'minimumIncludesTax')::boolean THEN row_total ELSE row_net END)*fx < (entry->>'minimum')::numeric*(entry->>'quantity')::numeric THEN RAISE EXCEPTION 'سعر البند بعد الخصم أقل من الحد الأدنى';END IF;
   final_rows:=final_rows||jsonb_build_array(entry||jsonb_build_object('discount',(entry->>'rowDiscount')::numeric+allocated,'net',row_net,'tax',row_tax,'total',row_total));
   adjustment_base:=adjustment_base+CASE WHEN inclusive THEN row_total ELSE row_net END;
  END LOOP;
  adjustment_id:=nullif(inv#>>'{adjustment,typeId}','')::uuid;adjustment_amount:=coalesce((inv#>>'{adjustment,amount}')::numeric,0);
  IF adjustment_amount<0 OR adjustment_amount>1000000000 OR adjustment_amount<>round(adjustment_amount,2) OR (adjustment_id IS NULL AND adjustment_amount<>0) THEN RAISE EXCEPTION 'راجع قيمة التسوية';END IF;
  IF adjustment_id IS NOT NULL THEN
   SELECT x INTO adjustment_rule FROM jsonb_array_elements(advanced->'adjustments') x WHERE x->>'id'=adjustment_id::text;
   IF NOT(advanced->>'adjustmentsEnabled')::boolean OR adjustment_rule IS NULL OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=(adjustment_rule->>'accountId')::uuid AND active AND kind IN('revenue','expense') AND code<>'5000') THEN RAISE EXCEPTION 'حساب التسوية غير متاح';END IF;
   IF adjustment_rule->>'kind'='deduction' AND adjustment_amount>adjustment_base THEN RAISE EXCEPTION 'التسوية أكبر من قيمة الفاتورة';END IF;
   IF adjustment_rule->>'kind'='deduction' AND subtotal-after_rows+doc_discount+adjustment_amount>round(subtotal*cap/100,2) THEN RAISE EXCEPTION 'الخصم والتسوية يتجاوزان الحد المسموح للمستخدم';END IF;
  END IF;
  remaining:=adjustment_amount;base_left:=adjustment_base;rows:='[]';
  FOR entry IN SELECT value FROM jsonb_array_elements(final_rows) LOOP
   row_net:=(entry->>'net')::numeric;row_tax:=(entry->>'tax')::numeric;row_total:=(entry->>'total')::numeric;rate:=(entry->>'vatRate')::numeric;row_after:=CASE WHEN inclusive THEN row_total ELSE row_net END;
   allocated:=CASE WHEN base_left=0 THEN 0 ELSE round(remaining*row_after/base_left,2) END;remaining:=remaining-allocated;base_left:=base_left-row_after;
   IF adjustment_rule->>'kind'='deduction' THEN allocated:=-allocated;END IF;
   adjustment_line_tax:=CASE WHEN coalesce((adjustment_rule->>'taxable')::boolean,false) THEN CASE WHEN inclusive THEN round(allocated-allocated/(1+rate/100),2) ELSE round(allocated*rate/100,2) END ELSE 0 END;
   adjustment_line_net:=CASE WHEN inclusive AND coalesce((adjustment_rule->>'taxable')::boolean,false) THEN allocated-adjustment_line_tax ELSE allocated END;
   row_net:=row_net+adjustment_line_net;row_tax:=row_tax+adjustment_line_tax;row_total:=row_net+row_tax;
   IF row_net<0 OR row_tax<0 THEN RAISE EXCEPTION 'التسوية تنتج مبلغًا أو ضريبة سالبة';END IF;
   IF (CASE WHEN (advanced->>'minimumIncludesTax')::boolean THEN row_total ELSE row_net END)*fx < (entry->>'minimum')::numeric*(entry->>'quantity')::numeric THEN RAISE EXCEPTION 'سعر البند بعد التسوية أقل من الحد الأدنى';END IF;
   sar_line_net:=round(row_net*fx,2);sar_line_tax:=round(row_tax*fx,2);sar_net:=sar_net+sar_line_net;sar_tax:=sar_tax+sar_line_tax;sar_subtotal:=sar_subtotal+round((entry->>'gross')::numeric*fx,2);
   sar_adjustment_net:=sar_adjustment_net+round(adjustment_line_net*fx,2);sar_adjustment_tax:=sar_adjustment_tax+round(adjustment_line_tax*fx,2);
   net:=net+row_net;tax:=tax+row_tax;total:=total+row_total;adjustment_net:=adjustment_net+adjustment_line_net;adjustment_tax:=adjustment_tax+adjustment_line_tax;
   rows:=rows||jsonb_build_array(entry||jsonb_build_object('net',row_net,'tax',row_tax,'total',row_total,'sarNet',sar_line_net,'sarTax',sar_line_tax,'adjustmentNet',round(adjustment_line_net*fx,2),'adjustmentTax',round(adjustment_line_tax*fx,2)));
  END LOOP;
  final_rows:=rows;sar_total:=sar_net+sar_tax;sar_discount:=round((subtotal-after_rows+doc_discount)*fx,2);
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60622));
  SELECT settings->>'codServiceId' INTO cod_service_id FROM public.bf_shipping_settings WHERE cafe_id=p_cafe_id;
  SELECT coalesce(jsonb_agg(ordinality-1 ORDER BY ordinality),'[]'::jsonb) INTO cod_service_indices FROM jsonb_array_elements(final_rows) WITH ORDINALITY row(value,ordinality) WHERE value->>'productId'=cod_service_id AND value->>'kind'='service';
  shipping_charge:=brand_finance_private.shipping_charge_for_issue(p_cafe_id,p_draft_id,p_revision);
  IF shipping_charge IS NOT NULL THEN
   shipping_net:=(shipping_charge->>'amount')::numeric;
   IF shipping_net>0 AND jsonb_array_length(final_rows)>99 THEN RAISE EXCEPTION 'الحد الأقصى ٩٩ بندًا عند إضافة رسوم الشحن' USING ERRCODE='22023';END IF;
   shipping_tax:=round(shipping_net*coalesce((shipping_charge->>'taxRate')::numeric,0)/100,2);
   shipping_sar_net:=round(shipping_net*fx,2);shipping_sar_tax:=round(shipping_tax*fx,2);
   net:=net+shipping_net;tax:=tax+shipping_tax;total:=total+shipping_net+shipping_tax;
   sar_net:=sar_net+shipping_sar_net;sar_tax:=sar_tax+shipping_sar_tax;sar_total:=sar_net+sar_tax;sar_subtotal:=sar_subtotal+shipping_sar_net+CASE WHEN inclusive THEN shipping_sar_tax ELSE 0 END;
  END IF;
  IF total<=0 OR total>1000000000 OR sar_total<=0 OR sar_total>1000000000 OR (NOT p_preview AND p_expected_total IS DISTINCT FROM total) THEN RAISE EXCEPTION 'راجع إجمالي الفاتورة قبل الإصدار';END IF;
  IF p_preview THEN RETURN jsonb_build_object('subtotal',subtotal,'discount',subtotal-after_rows+doc_discount,'tax',tax,'total',total,'lines',final_rows);END IF;
  credit_sar:=CASE WHEN p_source_id IS NULL AND coalesce((inv->>'applyCredit')::boolean,false) THEN least(sar_total,brand_finance_private.customer_credit_balance(p_cafe_id,customer.id)) ELSE 0 END;
  credit_foreign:=least(total,round(credit_sar/fx,2));deposit_amount:=round(CASE WHEN deposit_kind='percent' THEN total*deposit_value/100 ELSE deposit_value END,2);
  IF deposit_amount>total THEN RAISE EXCEPTION 'الدفعة المقدمة أكبر من إجمالي الفاتورة';END IF;
  paid:=CASE WHEN deposit_value>0 THEN CASE WHEN deposit_paid THEN deposit_amount ELSE 0 END WHEN aid IS NULL THEN 0 ELSE total-credit_foreign END;
  cash_sar:=CASE WHEN deposit_value=0 AND aid IS NOT NULL THEN sar_total-credit_sar ELSE round(paid*fx,2) END;
  IF cash_sar+credit_sar>sar_total THEN RAISE EXCEPTION 'الدفعة ورصيد العميل يتجاوزان المبلغ المستحق';END IF;
  display_number:=coalesce(erp_settings_private.prepare_advance(p_cafe_id,doc,p_draft_id,p_source_id,inv,final_rows,sar_net,sar_tax,sar_total,currency_code,fx,shipping_charge,adjustment_id,issue_at),brand_finance_private.invoice_number_allocate(p_cafe_id,CASE WHEN p_source_id IS NULL THEN 'invoice' ELSE 'debit' END,advanced->CASE WHEN p_source_id IS NULL THEN 'numbering' ELSE 'debitNumbering' END,coalesce(inv->>'manualNumber','')));
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,warehouse_id,subtotal,discount,tax,total,paid,reference_id,note,created_by,created_at,vat_rate,tax_inclusive)
   VALUES(doc,p_cafe_id,'sale',customer.id,aid,wid,sar_subtotal,sar_discount,sar_tax,sar_total,cash_sar,p_source_id,left(coalesce(inv->>'note',''),1000),p_actor,issue_at,CASE WHEN tax=0 THEN 0 ELSE 15 END,inclusive) RETURNING number INTO n;
  journal_note:=CASE WHEN (advanced->>'journalTemplateEnabled')::boolean THEN replace(replace(replace(replace(advanced->>'journalTemplate','{number}',display_number),'{customer}',customer.name),'{date}',(issue_at AT TIME ZONE 'Asia/Riyadh')::date::text),'{total}',sar_total::text) ELSE '' END;journal_note:=left(journal_note,300);
  FOR entry IN SELECT value FROM jsonb_array_elements(final_rows) LOOP
   line_id:=gen_random_uuid();
   INSERT INTO public.bf_document_lines(id,cafe_id,document_id,product_id,name,quantity,unit_price,net,tax,cost,activity_kind,vat_rate,tax_category,exemption_reason,inventory_item_id,unit_label,stock_unit_factor)
    VALUES(line_id,p_cafe_id,doc,CASE WHEN entry->>'catalogSource'='inventory' THEN NULL ELSE nullif(entry->>'productId','')::uuid END,entry->>'name',(entry->>'quantity')::numeric,round((entry->>'price')::numeric*fx,2),(entry->>'sarNet')::numeric,(entry->>'sarTax')::numeric,0,entry->>'kind',(entry->>'vatRate')::numeric,entry->>'taxCategory',entry->>'exemptionReason',CASE WHEN entry->>'catalogSource'='inventory' THEN (entry->>'productId')::uuid ELSE NULL END,nullif(entry->>'unitName',''),coalesce((entry->>'unitFactor')::numeric,1))
    RETURNING bf_document_lines.cost,bf_document_lines.cost_status INTO cost,line_cost_status;
   IF p_source_id IS NULL AND entry->>'kind'='product' AND NOT(prefs->>'allowBelowCost')::boolean THEN
    IF line_cost_status IS DISTINCT FROM 'known' AND NOT EXISTS(SELECT 1 FROM public.erp_sales_requisition_lines pending WHERE pending.cafe_id=p_cafe_id AND pending.id=line_id) THEN RAISE EXCEPTION 'Invoice settings: known inventory cost required' USING ERRCODE='22023';END IF;
    IF (entry->>'sarNet')::numeric<cost THEN RAISE EXCEPTION 'Invoice settings: below inventory cost' USING ERRCODE='22023';END IF;
   END IF;
   IF adjustment_id IS NOT NULL AND ((entry->>'adjustmentNet')::numeric<>0 OR (entry->>'adjustmentTax')::numeric<>0) THEN INSERT INTO public.bf_invoice_adjustment_lines(cafe_id,document_id,line_id,account_id,net,tax) VALUES(p_cafe_id,doc,line_id,(adjustment_rule->>'accountId')::uuid,(entry->>'adjustmentNet')::numeric,(entry->>'adjustmentTax')::numeric);END IF;
   PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'5000'),cost,0,NULL,journal_note);PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'1200'),0,cost,NULL,journal_note);
  END LOOP;
  IF shipping_charge IS NOT NULL THEN
