    shipping_line_id:=gen_random_uuid();
    INSERT INTO public.bf_document_lines(id,cafe_id,document_id,name,quantity,unit_price,net,tax,cost,activity_kind,vat_rate,tax_category,exemption_reason)
     VALUES(shipping_line_id,p_cafe_id,doc,shipping_charge->>'name',1,CASE WHEN inclusive THEN shipping_sar_net+shipping_sar_tax ELSE shipping_sar_net END,shipping_sar_net,shipping_sar_tax,0,'service',coalesce((shipping_charge->>'taxRate')::numeric,0),CASE WHEN shipping_charge->>'taxRate'='15' THEN 'S' ELSE 'O' END,'');
   END IF;
   shipping_charge:=shipping_charge||jsonb_build_object('tax',shipping_tax,'total',shipping_net+shipping_tax,'currency',currency_code,'exchangeRate',fx,'lineId',shipping_line_id,'sar',jsonb_build_object('amount',shipping_sar_net,'tax',shipping_sar_tax,'total',shipping_sar_net+shipping_sar_tax));
   INSERT INTO public.bf_invoice_shipping_charges(cafe_id,document_id,line_id,account_id,snapshot,created_by) VALUES(p_cafe_id,doc,shipping_line_id,(shipping_charge->>'accountId')::uuid,shipping_charge,p_actor);
   PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,(shipping_charge->>'accountId')::uuid,0,shipping_sar_net,NULL,journal_note);
  END IF;
  PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,aid,cash_sar,0,NULL,journal_note);
  PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'1100'),sar_total-cash_sar,0,customer.id,journal_note);
  PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,CASE WHEN EXISTS(SELECT 1 FROM public.erp_contracting_advance_invoices WHERE cafe_id=p_cafe_id AND invoice_id=doc) THEN brand_finance_private.customer_credit_account(p_cafe_id) ELSE brand_finance_private.account(p_cafe_id,'4000') END,0,sar_net-sar_adjustment_net-shipping_sar_net,CASE WHEN EXISTS(SELECT 1 FROM public.erp_contracting_advance_invoices WHERE cafe_id=p_cafe_id AND invoice_id=doc) THEN customer.id ELSE NULL END,journal_note);
  IF sar_adjustment_net<>0 THEN PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,(adjustment_rule->>'accountId')::uuid,greatest(-sar_adjustment_net,0),greatest(sar_adjustment_net,0),NULL,journal_note);END IF;
  PERFORM brand_finance_private.invoice_line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'2100'),0,sar_tax,NULL,journal_note);
  IF credit_sar>0 THEN PERFORM brand_finance_private.customer_credit_apply(p_cafe_id,doc,credit_sar);END IF;
  phone:=regexp_replace(translate(coalesce(customer.phone,''),'٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹','01234567890123456789'),'[^0-9]','','g');IF phone LIKE '00%' THEN phone:=substr(phone,3);END IF;IF phone~'^05[0-9]{8}$' THEN phone:='966'||substr(phone,2);ELSIF phone~'^5[0-9]{8}$' THEN phone:='966'||phone;END IF;
  IF coalesce(draft.payload->>'deliveryMethod','print') NOT IN('print','whatsapp','email','both') THEN RAISE EXCEPTION 'طريقة إرسال الفاتورة غير صالحة';END IF;
  IF draft.payload->>'deliveryMethod'='whatsapp' AND NOT((advanced->>'socialEnabled')::boolean AND advanced->'socialPlatforms' ? 'whatsapp') THEN RAISE EXCEPTION 'إرسال الواتساب غير مفعل في إعدادات الفواتير';END IF;
  IF draft.payload->>'deliveryMethod' IN('email','both') AND NOT(advanced->>'billingMethod' IN('email','both') OR ((advanced->>'socialEnabled')::boolean AND advanced->'socialPlatforms' ? 'email')) THEN RAISE EXCEPTION 'إرسال البريد الإلكتروني غير مفعل في إعدادات الفواتير';END IF;
  IF draft.payload->>'deliveryMethod'='whatsapp' AND phone!~'^9665[0-9]{8}$' THEN RAISE EXCEPTION 'أدخل رقم جوال سعودي صحيح للعميل قبل إرسال الواتساب';END IF;
  IF draft.payload->>'deliveryMethod' IN('email','both') AND coalesce(customer.email,'')!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'أكمل البريد الإلكتروني الصحيح للعميل';END IF;
  SELECT coalesce(jsonb_agg(x-ARRAY['sarNet','sarTax','adjustmentNet','adjustmentTax','minimum']), '[]') INTO final_rows FROM jsonb_array_elements(final_rows) x;
  result:=jsonb_build_object('id',doc,'number',n,'displayNumber',display_number,'type',invoice_type,'documentType',CASE WHEN p_source_id IS NULL THEN 'invoice' ELSE 'debit' END,'sourceId',p_source_id,'sourceNumber',coalesce((SELECT e.display_number FROM public.bf_invoice_extensions e WHERE e.document_id=p_source_id),source_doc.number::text),'reason',p_debit_reason,'issuedAt',issue_at,'supplyDate',supply_date,'seller',seller,
   'customer',jsonb_build_object('name',coalesce(nullif(customer.details->>'legalName',''),customer.name),'vatNumber',customer.tax_number,'address',buyer_address,'phone',phone,'email',customer.email),
   'lines',final_rows,'subtotal',subtotal,'discount',subtotal-after_rows+doc_discount,'tax',tax,'total',total,'paid',paid+credit_foreign,'cashPaid',paid,'creditApplied',credit_foreign,'taxInclusive',inclusive,'currency',currency_code,'exchangeRate',fx,'decimalDisplay',prefs->>'decimalDisplay',
   'sar',jsonb_build_object('subtotal',sar_subtotal,'discount',sar_discount,'tax',sar_tax,'total',sar_total,'paid',cash_sar+credit_sar,'cashPaid',cash_sar,'creditApplied',credit_sar),
   'adjustment',CASE WHEN adjustment_id IS NULL THEN NULL ELSE jsonb_build_object('typeId',adjustment_id,'amount',adjustment_amount,'kind',adjustment_rule->>'kind','taxable',(adjustment_rule->>'taxable')::boolean,'name',adjustment_rule->>'name','net',adjustment_net,'tax',adjustment_tax,'total',adjustment_net+adjustment_tax) END,
   'deposit',jsonb_build_object('kind',deposit_kind,'value',deposit_value,'amount',deposit_amount,'paid',deposit_paid),'codServiceLineIndices',cod_service_indices,'shippingCharge',shipping_charge,'shipping',jsonb_build_object('mode',requested_shipping_mode,'resolvedMode',shipping_mode,'address',shipping_address),'delivery',jsonb_build_object('confirmed',delivery_confirmed,'date',coalesce(delivery_date::text,'')),
   'attachments',files,'note',coalesce(inv->>'note',''),'extraFields',coalesce(draft.payload->'extraFields','[]'::jsonb),'template',draft.payload->>'template','deliveryMethod',coalesce(draft.payload->>'deliveryMethod','print'));
  IF EXISTS(SELECT 1 FROM public.erp_contracting_advance_invoices WHERE cafe_id=p_cafe_id AND invoice_id=doc) THEN result:=result||jsonb_build_object('documentType','advance','invoiceTypeCode','386','advancePayment',true);END IF; INSERT INTO public.bf_company_invoices(document_id,cafe_id,draft_id,snapshot) VALUES(doc,p_cafe_id,p_draft_id,result); SELECT snapshot INTO result FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND document_id=doc;
  INSERT INTO public.bf_invoice_extensions(cafe_id,document_id,display_number,source_id,status_id,metadata,created_by) VALUES(p_cafe_id,doc,display_number,p_source_id,status_id,jsonb_build_object('currency',currency_code,'exchangeRate',fx,'reason',p_debit_reason),p_actor);
  RETURN result;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.journal_detail_before_descriptions(p_cafe_id uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE source public.bf_documents%ROWTYPE; invoice_id uuid; payment_id uuid; result jsonb;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 SELECT * INTO source FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Journal document unavailable' USING ERRCODE='42501'; END IF;
 IF source.kind='sale' THEN invoice_id:=source.id;IF source.paid>0 THEN payment_id:=source.id;END IF;
 ELSIF source.kind IN('settlement','refund') AND EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=source.reference_id AND kind='sale') THEN invoice_id:=source.reference_id;payment_id:=source.id;
 ELSE SELECT e.invoice_id,e.source_id INTO invoice_id,payment_id FROM public.bf_invoice_payment_events e WHERE e.cafe_id=p_cafe_id AND e.correction_id=p_id LIMIT 1;
 END IF;
 WITH entries AS MATERIALIZED (
  SELECT j.id,j.account_id,a.code,a.name,j.debit,j.credit,j.memo,j.party_id,p.name party_name FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id LEFT JOIN public.bf_parties p ON p.cafe_id=j.cafe_id AND p.id=j.party_id WHERE j.cafe_id=p_cafe_id AND j.document_id=p_id
 ), related AS MATERIALIZED (
  SELECT d.id,d.number,d.kind,d.created_at,d.note FROM public.bf_documents d WHERE d.cafe_id=p_cafe_id AND d.id<>p_id AND (d.id=source.reference_id OR d.reference_id=p_id OR d.id IN(SELECT e.correction_id FROM public.bf_invoice_payment_events e WHERE e.cafe_id=p_cafe_id AND e.source_id=payment_id))
 ), activity AS MATERIALIZED (
  SELECT 'document:'||source.id id,'إنشاء المستند' action,source.created_at,source.created_by
  UNION ALL
  SELECT 'payment:'||e.id,CASE WHEN e.action='delete' THEN 'حذف الدفعة بتصحيح محاسبي' WHEN e.correction_id IS NOT NULL THEN 'تصحيح تحصيل الدفعة' ELSE 'تعديل بيانات الدفعة' END,e.created_at,e.created_by FROM public.bf_invoice_payment_events e WHERE e.cafe_id=p_cafe_id AND e.source_id=payment_id
 )
 SELECT jsonb_build_object('document',jsonb_build_object('id',source.id,'number',source.number,'kind',source.kind,'createdAt',source.created_at,'note',source.note,'total',source.total,'referenceId',source.reference_id,'creatorId',source.created_by,'creatorName',brand_finance_private.treasury_actor_name(p_cafe_id,source.created_by)),
  'journal',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'accountId',account_id,'accountCode',code,'accountName',name,'debit',debit,'credit',credit,'memo',memo,'partyId',party_id,'partyName',party_name) ORDER BY id) FROM (SELECT * FROM entries ORDER BY id LIMIT 2000) page),'[]'::jsonb),
  'totals',jsonb_build_object('debit',coalesce((SELECT sum(debit) FROM entries),0),'credit',coalesce((SELECT sum(credit) FROM entries),0)),'journalCount',(SELECT count(*) FROM entries),'journalTruncated',(SELECT count(*)>2000 FROM entries),
  'invoiceId',invoice_id,'sourcePaymentId',payment_id,
  'related',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'number',number,'kind',kind,'createdAt',created_at,'note',note) ORDER BY created_at DESC,id DESC) FROM (SELECT * FROM related ORDER BY created_at DESC,id DESC LIMIT 100) page),'[]'::jsonb),'relatedCount',(SELECT count(*) FROM related),'relatedTruncated',(SELECT count(*)>100 FROM related),
  'activity',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'action',action,'createdAt',created_at,'actor',brand_finance_private.treasury_actor_name(p_cafe_id,created_by)) ORDER BY created_at DESC,id DESC) FROM (SELECT * FROM activity ORDER BY created_at DESC,id DESC LIMIT 100) page),'[]'::jsonb),'activityCount',(SELECT count(*) FROM activity),'activityTruncated',(SELECT count(*)>100 FROM activity)
 ) INTO result;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.line_cost_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM public.bf_line_components WHERE cafe_id=NEW.cafe_id AND line_id=NEW.id) THEN
 SELECT CASE WHEN bool_or(cost_status='unknown') THEN 'unknown' WHEN bool_or(cost_status='estimated') THEN 'estimated' WHEN bool_or(cost_status='legacy') THEN 'legacy' ELSE 'known' END INTO NEW.cost_status FROM public.bf_line_components WHERE cafe_id=NEW.cafe_id AND line_id=NEW.id;
 RETURN NEW; END IF;
 IF NEW.item_id IS NULL THEN NEW.cost_status:='untracked';
 ELSIF NEW.reference_line_id IS NOT NULL THEN
  SELECT l.cost_status INTO NEW.cost_status FROM public.bf_document_lines l
  WHERE l.cafe_id=NEW.cafe_id AND l.id=NEW.reference_line_id;
  NEW.cost_status:=coalesce(NEW.cost_status,'unknown');
 ELSE
  SELECT CASE WHEN bool_or(m.cost_status='unknown') THEN 'unknown'
   WHEN bool_or(m.cost_status='estimated') THEN 'estimated'
   WHEN bool_and(m.cost_status='known') THEN 'known' ELSE 'unknown' END INTO NEW.cost_status
  FROM public.bf_movements m WHERE m.cafe_id=NEW.cafe_id AND m.document_id=NEW.document_id AND m.item_id=NEW.item_id;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.payment_financial_guard(source bf_documents, invoice bf_documents, account uuid, financial_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE a public.bf_accounts%ROWTYPE; today date:=(now() AT TIME ZONE 'Asia/Riyadh')::date;
BEGIN
 IF EXISTS(SELECT 1 FROM public.bf_customer_credit_events WHERE cafe_id=source.cafe_id AND document_id=source.id AND action='apply') THEN RETURN 'هذه الدفعة من رصيد العميل ألغ تطبيق الرصيد من إدارة الأرصدة';END IF;
 IF EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=source.cafe_id AND (closed_through>=today OR closed_through>=(source.created_at AT TIME ZONE 'Asia/Riyadh')::date))
  OR EXISTS(SELECT 1 FROM public.bf_gl_periods WHERE cafe_id=source.cafe_id AND closed AND (today BETWEEN period_start AND period_end OR (source.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN period_start AND period_end)) THEN RETURN 'الفترة المالية للدفعة أو التصحيح مقفلة'; END IF;
 IF invoice.shift_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=source.cafe_id AND id=invoice.shift_id AND status<>'open') THEN RETURN 'وردية الفاتورة مغلقة أو في التسليم ولا يمكن تغيير مبالغها'; END IF;
 IF source.shift_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=source.cafe_id AND id=source.shift_id AND status<>'open') THEN RETURN 'وردية الدفعة مغلقة أو في التسليم'; END IF;
 IF EXISTS(SELECT 1 FROM public.bf_refund_requests WHERE cafe_id=source.cafe_id AND document_id=invoice.id AND status='pending') THEN RETURN 'راجع طلب المرتجع المعلق قبل تغيير الدفعة'; END IF;
 SELECT * INTO a FROM public.bf_accounts WHERE cafe_id=source.cafe_id AND id=account;
 IF NOT FOUND OR NOT a.active OR a.deleted_at IS NOT NULL OR a.frozen OR a.is_group THEN RETURN 'حساب التحصيل غير نشط أو مجمد'; END IF;
 IF a.is_cashier_drawer AND NOT EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=source.cafe_id AND id=coalesce(source.shift_id,invoice.shift_id) AND account_id=a.id AND status='open') THEN RETURN 'صندوق الكاشير لا يتبع وردية الفاتورة المفتوحة'; END IF;
 IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=source.cafe_id AND account_id=a.id AND status IN('open','handover') AND (status='handover' OR id IS DISTINCT FROM coalesce(source.shift_id,invoice.shift_id))) THEN RETURN 'حساب التحصيل مرتبط بعهدة وردية أخرى'; END IF;
 IF EXISTS(SELECT 1 FROM public.bf_terminal_fee_charges f WHERE f.cafe_id=source.cafe_id AND (f.source_document_id=source.id OR f.source_document_id IN(SELECT correction_id FROM public.bf_invoice_payment_events WHERE cafe_id=source.cafe_id AND source_id=source.id))) THEN RETURN 'الدفعة مرتبطة برسوم شبكة مرحلة وتتطلب تصحيح الرسوم المرتبطة أولًا'; END IF;
 IF a.kind='pos' AND EXISTS(SELECT 1 FROM public.bf_treasury_documents t JOIN public.bf_documents d ON d.cafe_id=t.cafe_id AND d.id=t.document_id WHERE t.cafe_id=source.cafe_id AND t.account_id=a.id AND t.operation='pos_settle' AND d.created_at>=financial_at AND NOT EXISTS(SELECT 1 FROM public.bf_treasury_documents rev WHERE rev.cafe_id=t.cafe_id AND rev.reverses_id=d.id)) THEN RETURN 'تمت تسوية الشبكة بعد هذه الدفعة ولا يمكن تغيير التحصيل المسوى'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.pos_report_before_own_purchase(p_cafe_id uuid, p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb; payouts jsonb; total numeric;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_pos_shift_report',NULL);
 result:=brand_finance_private.pos_report_before_supplier_payout(p_cafe_id,p_shift_id);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',d.id,'number',d.number,'supplierName',p.supplier_name,'amount',d.paid,'note',d.note,'createdAt',d.created_at,
  'attachments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'name',a.original_name) ORDER BY a.created_at,a.id) FROM public.bf_shift_attachments a WHERE a.cafe_id=p_cafe_id AND a.document_id=d.id AND a.uploaded),'[]'::jsonb)) ORDER BY d.created_at,d.id),'[]'::jsonb),coalesce(sum(d.paid),0)
 INTO payouts,total FROM public.bf_shift_supplier_payouts p JOIN public.bf_documents d ON d.cafe_id=p.cafe_id AND d.id=p.document_id WHERE p.cafe_id=p_cafe_id AND p.shift_id=p_shift_id;
 RETURN result||jsonb_build_object('supplierPayoutTotal',total,'supplierPayouts',payouts);
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.pos_report_before_supplier_payout(p_cafe_id uuid, p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; sh public.bf_shifts%ROWTYPE; result jsonb;
BEGIN
 r:=brand_finance_private.role_for(p_cafe_id);
 SELECT * INTO sh FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND id=p_shift_id;
 IF sh.id IS NULL OR sh.status<>'closed' OR r NOT IN('owner','manager','accountant','auditor','cashier') OR (r='cashier' AND sh.user_id<>auth.uid()) THEN
  RAISE EXCEPTION 'Closed shift report access denied' USING ERRCODE='42501';
 END IF;
 WITH sales AS MATERIALIZED (
  SELECT d.id,d.total,(brand_finance_private.payment_document(d)).paid paid,(brand_finance_private.payment_document(d)).account_id account_id FROM public.bf_documents d WHERE d.cafe_id=p_cafe_id AND d.shift_id=p_shift_id AND d.kind='sale'
 ), related AS MATERIALIZED (
  SELECT d.kind,(brand_finance_private.payment_document(d)).total total,(brand_finance_private.payment_document(d)).paid paid,(brand_finance_private.payment_document(d)).account_id account_id FROM public.bf_documents d JOIN sales s ON s.id=d.reference_id WHERE d.cafe_id=p_cafe_id AND d.kind IN('refund','settlement')
 ), events AS (
  SELECT account_id,paid collected,0::numeric refunded FROM sales
  UNION ALL SELECT account_id,CASE WHEN kind='settlement' THEN total ELSE 0 END,CASE WHEN kind='refund' THEN paid ELSE 0 END FROM related
 ), payments AS (
  SELECT a.kind,sum(e.collected) collected,sum(e.refunded) refunded FROM events e JOIN public.bf_accounts a ON a.cafe_id=p_cafe_id AND a.id=e.account_id GROUP BY a.kind
 ), totals AS (
  SELECT (SELECT count(*) FROM sales) invoice_count,(SELECT coalesce(sum(total),0) FROM sales) sales_total,(SELECT coalesce(sum(total),0) FROM related WHERE kind='refund') refunds_total
 )
 SELECT jsonb_build_object(
  'shift',jsonb_build_object('id',sh.id,'user_id',sh.user_id,'account_id',sh.account_id,'status',sh.status,'shift_number',sh.shift_number,'opening_cash',sh.opening_cash,'expected_cash',sh.expected_cash,'counted_cash',sh.counted_cash,'variance',sh.variance,'opened_at',sh.opened_at,'closed_at',sh.closed_at,'handover_to',sh.handover_to,'note',sh.note),
  'brandName',(SELECT name FROM public.cafes WHERE id=p_cafe_id),
  'accountName',(SELECT name FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=sh.account_id),
  'generatedAt',now(),'invoiceCount',invoice_count,'salesTotal',sales_total,'refundsTotal',refunds_total,'netSales',sales_total-refunds_total,
  'payments',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.kind) FROM payments p),'[]'::jsonb)
 ) INTO result FROM totals;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.post_refund_before_purchase_services(p_cafe uuid, p_payload jsonb, p_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE original public.bf_documents%ROWTYPE; source jsonb; entry jsonb; available jsonb; selections jsonb; prepared jsonb:='[]'; state jsonb;
 qty numeric; before_qty numeric; line_net numeric; line_tax numeric; line_cost numeric; line_gross numeric; net numeric:=0; tax numeric:=0; gross numeric:=0; total numeric; discount numeric; debt numeric; paid numeric; actual_cost numeric; aid uuid; number bigint; item uuid; original_line public.bf_document_lines%ROWTYPE; defer_stock boolean:=false;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe),'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Finance manager required' USING ERRCODE='42501'; END IF;
 SELECT * INTO original FROM public.bf_documents WHERE cafe_id=p_cafe AND id=(p_payload->>'documentId')::uuid AND kind IN('sale','purchase') FOR UPDATE;
 IF original.kind='sale' AND NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe AND owner_user_id=auth.uid()) THEN RAISE EXCEPTION 'Brand owner required' USING ERRCODE='42501'; END IF;
 IF original.id IS NULL THEN RAISE EXCEPTION 'الفاتورة غير متاحة للإرجاع'; END IF;
 IF p_payload ? 'deferStock' AND jsonb_typeof(p_payload->'deferStock') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'خيار الاستلام المخزني غير صالح';END IF;
 defer_stock:=original.kind='sale' AND coalesce((p_payload->>'deferStock')::boolean,false);
 IF defer_stock AND EXISTS(SELECT 1 FROM public.gift_orders WHERE cafe_id=p_cafe AND finance_document_id=original.id) THEN RAISE EXCEPTION 'مرتجعات طلبات الهدايا تستخدم الاستلام المباشر للحفاظ على مخزون المتجر';END IF;
 available:=brand_finance_private.refund_lines(p_cafe,original.id,true);
 state:=brand_finance_private.document_state(p_cafe,original.id);
 IF (state->>'refunded')::boolean THEN RAISE EXCEPTION 'تم إرجاع جميع كميات الفاتورة'; END IF;
 IF p_payload ? 'lines' THEN selections:=p_payload->'lines'; ELSE
  SELECT jsonb_agg(jsonb_build_object('lineId',l->>'id','quantity',(l->>'quantity')::numeric-(l->>'returned_quantity')::numeric)) INTO selections FROM jsonb_array_elements(available) l WHERE (l->>'quantity')::numeric>(l->>'returned_quantity')::numeric;
 END IF;
 IF jsonb_typeof(selections) IS DISTINCT FROM 'array' OR jsonb_array_length(selections) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'حدد الأصناف والكميات المرتجعة'; END IF;
 IF (SELECT count(DISTINCT e->>'lineId') FROM jsonb_array_elements(selections) e)<>jsonb_array_length(selections) THEN RAISE EXCEPTION 'لا تكرر الصنف في طلب المرتجع'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(selections) LOOP
  SELECT l INTO source FROM jsonb_array_elements(available) l WHERE l->>'id'=entry->>'lineId';
  IF source IS NULL THEN RAISE EXCEPTION 'الصنف لا ينتمي إلى الفاتورة'; END IF;
  qty:=(entry->>'quantity')::numeric; before_qty:=(source->>'returned_quantity')::numeric;
  IF qty IS NULL OR qty<=0 OR qty<>round(qty,3) OR qty>(source->>'quantity')::numeric-before_qty THEN RAISE EXCEPTION 'الكمية المرتجعة تتجاوز الكمية المتبقية'; END IF;
  IF entry ? 'expectedReturnedQuantity' AND (entry->>'expectedReturnedQuantity')::numeric IS DISTINCT FROM before_qty THEN RAISE EXCEPTION 'تغيرت الكمية المرتجعة حدث الفاتورة ثم أعد المحاولة'; END IF;
  line_net:=round((source->>'net')::numeric*(before_qty+qty)/(source->>'quantity')::numeric,2)-(source->>'returned_net')::numeric;
  line_tax:=round((source->>'tax')::numeric*(before_qty+qty)/(source->>'quantity')::numeric,2)-(source->>'returned_tax')::numeric;
  line_cost:=round((source->>'cost')::numeric*(before_qty+qty)/(source->>'quantity')::numeric,2)-(source->>'returned_cost')::numeric;
  line_gross:=round(qty*(source->>'unit_price')::numeric,2);
  net:=net+line_net; tax:=tax+line_tax; gross:=gross+line_gross;
  prepared:=prepared||jsonb_build_array(source||jsonb_build_object('return_quantity',qty,'return_net',line_net,'return_tax',line_tax,'return_cost',line_cost));
 END LOOP;
 total:=net+tax;
 IF p_payload ? 'lines' AND (p_payload->>'expectedTotal')::numeric IS DISTINCT FROM total THEN RAISE EXCEPTION 'تغير إجمالي المرتجع راجع الكميات'; END IF;
 discount:=greatest(0,gross-net-CASE WHEN coalesce(original.tax_inclusive,true) THEN tax ELSE 0 END);
 debt:=least(total,(state->>'outstanding')::numeric); paid:=total-debt;
 aid:=nullif(p_payload->>'accountId','')::uuid;
 IF paid>0 AND aid IS NULL THEN
  aid:=CASE WHEN (brand_finance_private.payment_document(original)).paid>0 THEN (brand_finance_private.payment_document(original)).account_id ELSE NULL END;
  IF aid IS NULL THEN SELECT (brand_finance_private.payment_document(d)).account_id INTO aid FROM public.bf_documents d WHERE cafe_id=p_cafe AND reference_id=original.id AND kind='settlement' AND (brand_finance_private.payment_document(d)).paid>0 ORDER BY created_at DESC,id LIMIT 1; END IF;
 END IF;
 IF paid>0 AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe AND id=aid AND active AND kind IN('cash','bank','pos')) THEN RAISE EXCEPTION 'اختر حساب تسوية المبلغ المرتجع'; END IF;
 IF paid=0 THEN aid:=NULL; END IF;
 IF defer_stock THEN INSERT INTO public.bf_sales_return_stock(cafe_id,return_id,source_id,warehouse_id,created_by) VALUES(p_cafe,p_id,original.id,original.warehouse_id,auth.uid());END IF;
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,shift_id,account_id,warehouse_id,subtotal,discount,tax,total,paid,reference_id,note,created_by,vat_rate,tax_inclusive)
 VALUES(p_id,p_cafe,'refund',original.party_id,CASE WHEN original.kind='sale' THEN nullif(p_payload->>'shiftId','')::uuid ELSE NULL END,aid,original.warehouse_id,gross,discount,tax,total,paid,original.id,coalesce(p_payload->>'note',''),auth.uid(),original.vat_rate,original.tax_inclusive) RETURNING bf_documents.number INTO number;
 FOR entry IN SELECT value FROM jsonb_array_elements(prepared) LOOP
  qty:=(entry->>'return_quantity')::numeric; line_net:=(entry->>'return_net')::numeric; line_tax:=(entry->>'return_tax')::numeric; line_cost:=(entry->>'return_cost')::numeric; item:=(entry->>'item_id')::uuid;
  actual_cost:=0;
  IF NOT defer_stock AND item IS NOT NULL AND NOT (original.kind='sale' AND EXISTS(SELECT 1 FROM public.bf_line_components WHERE cafe_id=p_cafe AND line_id=(entry->>'id')::uuid)) THEN actual_cost:=brand_finance_private.stock_move(p_cafe,p_id,item,original.warehouse_id,CASE WHEN original.kind='sale' THEN qty ELSE -qty END,CASE WHEN original.kind='sale' THEN line_cost/qty ELSE 0 END); END IF;
  SELECT * INTO STRICT original_line FROM public.bf_document_lines WHERE cafe_id=p_cafe AND id=(entry->>'id')::uuid;
  INSERT INTO public.bf_document_lines(cafe_id,document_id,reference_line_id,product_id,item_id,name,quantity,unit_price,net,tax,cost,activity_kind,vat_rate,tax_category,exemption_reason)
  VALUES(p_cafe,p_id,(entry->>'id')::uuid,(entry->>'product_id')::uuid,item,entry->>'name',qty,(entry->>'unit_price')::numeric,line_net,line_tax,line_cost,original_line.activity_kind,original_line.vat_rate,original_line.tax_category,original_line.exemption_reason) RETURNING bf_document_lines.cost INTO line_cost;
  IF original.kind='sale' THEN
   IF NOT defer_stock THEN
   PERFORM brand_finance_private.line(p_cafe,p_id,brand_finance_private.account(p_cafe,'1200'),line_cost,0);
   PERFORM brand_finance_private.line(p_cafe,p_id,brand_finance_private.account(p_cafe,'5000'),0,line_cost);
   END IF;
  ELSE
   PERFORM brand_finance_private.line(p_cafe,p_id,brand_finance_private.account(p_cafe,'1200'),0,actual_cost);
   PERFORM brand_finance_private.line(p_cafe,p_id,brand_finance_private.account(p_cafe,'5200'),greatest(actual_cost-line_net,0),greatest(line_net-actual_cost,0));
  END IF;
 END LOOP;
 IF original.kind='sale' THEN
  PERFORM brand_finance_private.line(p_cafe,p_id,brand_finance_private.account(p_cafe,'4000'),net,0);
  PERFORM brand_finance_private.line(p_cafe,p_id,brand_finance_private.account(p_cafe,'2100'),tax,0);
  PERFORM brand_finance_private.line(p_cafe,p_id,brand_finance_private.account(p_cafe,'1100'),0,debt,original.party_id);
  PERFORM brand_finance_private.line(p_cafe,p_id,aid,0,paid);
 ELSE
  PERFORM brand_finance_private.line(p_cafe,p_id,brand_finance_private.account(p_cafe,'1300'),0,tax);
  PERFORM brand_finance_private.line(p_cafe,p_id,brand_finance_private.account(p_cafe,'2000'),debt,0,original.party_id);
  PERFORM brand_finance_private.line(p_cafe,p_id,aid,paid,0);
 END IF;
 PERFORM brand_finance_private.invoice_refund_adjustments(p_cafe,p_id);
 IF defer_stock AND NOT EXISTS(SELECT 1 FROM brand_finance_private.sales_return_components(p_cafe,p_id)) THEN UPDATE public.bf_sales_return_stock SET status='none' WHERE return_id=p_id;END IF;
 RETURN number;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.recurring_date(anchor date, unit text, step integer, idx integer)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE answer date;
BEGIN
 IF anchor IS NULL OR anchor<'1900-01-01'::date OR anchor>'9999-12-31'::date OR step IS NULL OR step NOT BETWEEN 1 AND 365 OR idx IS NULL OR idx NOT BETWEEN 0 AND 1000000 OR unit IS NULL OR unit NOT IN('day','week','month','year') THEN RAISE EXCEPTION 'راجع تاريخ وفترة التكرار';END IF;
 answer:=CASE unit WHEN 'day' THEN anchor+step*idx WHEN 'week' THEN anchor+7*step*idx WHEN 'month' THEN (anchor+make_interval(months=>step*idx))::date ELSE (anchor+make_interval(years=>step*idx))::date END;
 IF answer>'9999-12-31'::date THEN RAISE EXCEPTION 'تاريخ التكرار خارج النطاق المسموح';END IF;RETURN answer;
EXCEPTION WHEN datetime_field_overflow OR interval_field_overflow OR numeric_value_out_of_range THEN RAISE EXCEPTION 'تاريخ التكرار خارج النطاق المسموح';
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.recurring_detail(r bf_recurring_invoices, off integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE history jsonb;upcoming jsonb:='[]';idx integer;day date;last_day date;end_index integer;
BEGIN
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',h.id,'index',h.occurrence_index,'scheduledDate',h.scheduled_date,'issuedAt',h.issued_at,'invoiceId',h.document_id,'invoiceNumber',d.number,'displayNumber',i.snapshot->>'displayNumber','total',i.snapshot->'total','dueDate',h.due_date,'periodStart',h.scheduled_date,'periodEnd',h.period_end) ORDER BY h.occurrence_index DESC),'[]') INTO history
 FROM (SELECT * FROM public.bf_recurring_occurrences WHERE cafe_id=r.cafe_id AND subscription_id=r.id ORDER BY occurrence_index DESC LIMIT 30 OFFSET off) h JOIN public.bf_documents d ON d.cafe_id=h.cafe_id AND d.id=h.document_id JOIN public.bf_company_invoices i ON i.cafe_id=h.cafe_id AND i.document_id=h.document_id;
 end_index:=r.generated_count+4;IF (r.payload->>'count')::integer>0 THEN end_index:=least(end_index,(r.payload->>'count')::integer-1);END IF;
 IF r.status<>'deleted' THEN FOR idx IN r.generated_count..end_index LOOP
  day:=brand_finance_private.recurring_date((r.payload->>'firstDate')::date,r.payload->>'unit',(r.payload->>'interval')::integer,idx);
  last_day:=brand_finance_private.recurring_date((r.payload->>'firstDate')::date,r.payload->>'unit',(r.payload->>'interval')::integer,idx+1)-1;
  upcoming:=upcoming||jsonb_build_array(jsonb_build_object('index',idx,'date',day,'issueDate',day-(r.payload->>'leadDays')::integer,'dueDate',day+(r.payload->>'paymentTermsDays')::integer,'periodStart',day,'periodEnd',last_day));
 END LOOP;END IF;
 RETURN brand_finance_private.recurring_summary(r)||jsonb_build_object('payload',r.payload,'lines',r.totals->'lines','invoices',history,'historyTotal',r.generated_count,'historyOffset',off,'upcoming',upcoming);
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.recurring_worker()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE row record;answer jsonb;done integer:=0;failed integer:=0;
BEGIN
 IF NOT pg_try_advisory_xact_lock(60412020003) THEN RETURN jsonb_build_object('status','busy');END IF;
 FOR row IN SELECT id FROM public.bf_recurring_invoices WHERE status='active' AND next_issue_date<=(now() AT TIME ZONE 'Asia/Riyadh')::date AND next_attempt_at<=now() ORDER BY next_attempt_at,next_issue_date,id LIMIT 10 LOOP
  answer:=brand_finance_private.recurring_run_one(row.id);IF answer->>'status'='issued' THEN done:=done+1;ELSIF answer->>'status'='failed' THEN failed:=failed+1;END IF;
 END LOOP;RETURN jsonb_build_object('issued',done,'failed',failed);
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.refund_quote(p_cafe uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE original public.bf_documents%ROWTYPE; source jsonb; entry jsonb; available jsonb; selections jsonb; prepared jsonb:='[]'; state jsonb;
 qty numeric; before_qty numeric; line_net numeric; line_tax numeric; line_cost numeric; line_gross numeric; net numeric:=0; tax numeric:=0; gross numeric:=0; total numeric; discount numeric; debt numeric; paid numeric; actual_cost numeric; aid uuid; number bigint; item uuid; r text; sh public.bf_shifts%ROWTYPE;
BEGIN
 r:=brand_finance_private.role_for(p_cafe);
 IF p_payload ? 'deferStock' AND jsonb_typeof(p_payload->'deferStock') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'خيار الاستلام المخزني غير صالح';END IF;
 SELECT * INTO original FROM public.bf_documents WHERE cafe_id=p_cafe AND id=(p_payload->>'documentId')::uuid AND kind IN('sale','purchase') FOR UPDATE;
 IF original.id IS NULL THEN RAISE EXCEPTION 'الفاتورة غير متاحة للإرجاع'; END IF;
 IF original.kind<>'sale' OR (r='cashier' AND original.created_by<>auth.uid()) THEN RAISE EXCEPTION 'Sale refund access denied' USING ERRCODE='42501'; END IF;
 IF coalesce((p_payload->>'deferStock')::boolean,false) AND EXISTS(SELECT 1 FROM public.gift_orders WHERE cafe_id=p_cafe AND finance_document_id=original.id) THEN RAISE EXCEPTION 'مرتجعات طلبات الهدايا تستخدم الاستلام المباشر للحفاظ على مخزون المتجر';END IF;
 available:=brand_finance_private.refund_lines(p_cafe,original.id,true);
 state:=brand_finance_private.document_state(p_cafe,original.id);
 IF (state->>'refunded')::boolean THEN RAISE EXCEPTION 'تم إرجاع جميع كميات الفاتورة'; END IF;
 IF p_payload ? 'lines' THEN selections:=p_payload->'lines'; ELSE
  SELECT jsonb_agg(jsonb_build_object('lineId',l->>'id','quantity',(l->>'quantity')::numeric-(l->>'returned_quantity')::numeric)) INTO selections FROM jsonb_array_elements(available) l WHERE (l->>'quantity')::numeric>(l->>'returned_quantity')::numeric;
 END IF;
 IF jsonb_typeof(selections) IS DISTINCT FROM 'array' OR jsonb_array_length(selections) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'حدد الأصناف والكميات المرتجعة'; END IF;
 IF (SELECT count(DISTINCT e->>'lineId') FROM jsonb_array_elements(selections) e)<>jsonb_array_length(selections) THEN RAISE EXCEPTION 'لا تكرر الصنف في طلب المرتجع'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(selections) LOOP
  SELECT l INTO source FROM jsonb_array_elements(available) l WHERE l->>'id'=entry->>'lineId';
  IF source IS NULL THEN RAISE EXCEPTION 'الصنف لا ينتمي إلى الفاتورة'; END IF;
  qty:=(entry->>'quantity')::numeric; before_qty:=(source->>'returned_quantity')::numeric;
  IF qty IS NULL OR qty<=0 OR qty<>round(qty,3) OR qty>(source->>'quantity')::numeric-before_qty THEN RAISE EXCEPTION 'الكمية المرتجعة تتجاوز الكمية المتبقية'; END IF;
  IF entry ? 'expectedReturnedQuantity' AND (entry->>'expectedReturnedQuantity')::numeric IS DISTINCT FROM before_qty THEN RAISE EXCEPTION 'تغيرت الكمية المرتجعة حدث الفاتورة ثم أعد المحاولة'; END IF;
  line_net:=round((source->>'net')::numeric*(before_qty+qty)/(source->>'quantity')::numeric,2)-(source->>'returned_net')::numeric;
  line_tax:=round((source->>'tax')::numeric*(before_qty+qty)/(source->>'quantity')::numeric,2)-(source->>'returned_tax')::numeric;
  line_cost:=round((source->>'cost')::numeric*(before_qty+qty)/(source->>'quantity')::numeric,2)-(source->>'returned_cost')::numeric;
  line_gross:=round(qty*(source->>'unit_price')::numeric,2);
  net:=net+line_net; tax:=tax+line_tax; gross:=gross+line_gross;
  prepared:=prepared||jsonb_build_array(source||jsonb_build_object('return_quantity',qty,'return_net',line_net,'return_tax',line_tax,'return_cost',line_cost));
 END LOOP;
 total:=net+tax;
 IF p_payload ? 'lines' AND (p_payload->>'expectedTotal')::numeric IS DISTINCT FROM total THEN RAISE EXCEPTION 'تغير إجمالي المرتجع راجع الكميات'; END IF;
 discount:=greatest(0,gross-net-CASE WHEN coalesce(original.tax_inclusive,true) THEN tax ELSE 0 END);
 debt:=least(total,(state->>'outstanding')::numeric); paid:=total-debt;
 IF (p_payload->>'expectedPaid')::numeric IS DISTINCT FROM paid THEN RAISE EXCEPTION 'تغير المبلغ المدفوع للعميل ارفض الطلب وأنشئ طلبا محدثا'; END IF;
 IF nullif(btrim(p_payload->>'note'),'') IS NULL THEN RAISE EXCEPTION 'أدخل سبب المرتجع'; END IF;
 aid:=nullif(p_payload->>'accountId','')::uuid;
 IF paid>0 THEN
  IF p_payload->>'paymentMethod' NOT IN('cash','bank') OR p_payload->>'paymentMethod' IS NULL THEN RAISE EXCEPTION 'حدد دفع المرتجع نقدا أو بتحويل بنكي'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe AND id=aid AND active AND kind=p_payload->>'paymentMethod') THEN RAISE EXCEPTION 'حساب الدفع لا يطابق طريقة دفع المرتجع'; END IF;
  IF p_payload->>'paymentMethod'='cash' THEN
   SELECT * INTO sh FROM public.bf_shifts WHERE cafe_id=p_cafe AND account_id=aid AND status IN('open','handover') FOR UPDATE;
   IF sh.id IS NOT NULL THEN
    IF sh.status<>'open' OR nullif(p_payload->>'shiftId','')::uuid IS DISTINCT FROM sh.id OR (r='cashier' AND sh.user_id<>auth.uid()) OR (p_payload ? 'shiftUserId' AND (p_payload->>'shiftUserId')::uuid IS DISTINCT FROM sh.user_id) THEN RAISE EXCEPTION 'تغيرت عهدة الوردية أو حالتها أنشئ طلبا محدثا'; END IF;
   ELSIF nullif(p_payload->>'shiftId','') IS NOT NULL OR (r='cashier' AND NOT EXISTS(SELECT 1 FROM public.cafes c JOIN public.bf_accounts a ON a.cafe_id=c.id WHERE c.id=p_cafe AND c.business_category='butcher_shops' AND a.id=aid AND a.is_cashier_drawer AND a.active)) THEN RAISE EXCEPTION 'اختر وردية مفتوحة تابعة للكاشير لصرف المرتجع النقدي'; END IF;
  ELSIF nullif(p_payload->>'shiftId','') IS NOT NULL THEN RAISE EXCEPTION 'الصرف من الوردية متاح للدفع النقدي فقط'; END IF;
 ELSE aid:=NULL;
 END IF;
 SELECT jsonb_agg(jsonb_build_object('lineId',l->>'id','name',l->>'name','quantity',(l->>'return_quantity')::numeric,'expectedReturnedQuantity',(l->>'returned_quantity')::numeric,'unitPrice',(l->>'unit_price')::numeric,'net',(l->>'return_net')::numeric,'tax',(l->>'return_tax')::numeric)) INTO selections FROM jsonb_array_elements(prepared) l;
 RETURN jsonb_build_object('deferStock',coalesce((p_payload->>'deferStock')::boolean,false),'documentId',original.id,'documentNumber',original.number,'lines',selections,'expectedTotal',total,'expectedPaid',paid,'paymentMethod',CASE WHEN paid>0 THEN p_payload->>'paymentMethod' ELSE NULL END,'accountId',aid,'shiftId',sh.id,'shiftUserId',sh.user_id,'note',left(p_payload->>'note',1000));
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.role_for(p_cafe uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text;
BEGIN
 IF auth.uid() IS NULL
   OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='active')
   OR NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe AND deleted_at IS NULL AND status IN('active','published'))
   OR NOT platform_access_private.service_enabled(p_cafe,'finance')
 THEN RAISE EXCEPTION 'Finance access denied' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe AND owner_user_id=auth.uid()) THEN RETURN 'owner'; END IF;
 IF EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND role='platform_admin' AND status='active') THEN
  IF brand_finance_private.invoice_settings_maintenance(p_cafe) THEN RETURN 'owner'; END IF;
  RETURN 'manager';
 END IF;
 SELECT role INTO r FROM public.bf_staff WHERE cafe_id=p_cafe AND user_id=auth.uid() AND active FOR SHARE;
 IF r IS NULL THEN RAISE EXCEPTION 'Finance staff access denied' USING ERRCODE='42501'; END IF;
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.sales_return_detail(d bf_documents)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE answer jsonb;stock_status text;receipt uuid;lines jsonb;events jsonb;stock_lines jsonb;
BEGIN
 answer:=brand_finance_private.sales_return_summary(d);IF answer IS NULL THEN RETURN NULL;END IF;
 stock_status:=answer->>'stockStatus';
 SELECT receipt_document_id INTO receipt FROM public.bf_sales_return_stock WHERE cafe_id=d.cafe_id AND return_id=d.id;
 IF receipt IS NULL AND stock_status='received' THEN receipt:=d.id;END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',l.id,'name',l.name,'description','','quantity',l.quantity,'price',l.unit_price,
  'discount',greatest(0,round(l.quantity*l.unit_price,2)-l.net-CASE WHEN coalesce(d.tax_inclusive,true) THEN l.tax ELSE 0 END),'net',l.net,'tax',l.tax,'total',l.net+l.tax) ORDER BY l.id),'[]') INTO lines FROM public.bf_document_lines l WHERE l.cafe_id=d.cafe_id AND l.document_id=d.id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'itemName',i.name,'quantity',r.quantity,'receivedQuantity',CASE WHEN stock_status='received' THEN r.quantity ELSE 0 END,'unitCost',r.cost/r.quantity,'total',r.cost,'costStatus',r.cost_status) ORDER BY i.name,r.id),'[]') INTO stock_lines FROM brand_finance_private.sales_return_components(d.cafe_id,d.id) r JOIN public.bf_items i ON i.cafe_id=d.cafe_id AND i.id=r.item_id;
 SELECT coalesce(jsonb_agg(e.data ORDER BY e.created_at,e.id),'[]') INTO events FROM (
  SELECT d.id::text||':posted' id,d.created_at,jsonb_build_object('id',d.id::text||':posted','action','posted','actorName',answer->>'createdByName','createdAt',d.created_at,'note',d.note) data
  UNION ALL SELECT r.id::text||':requested',r.created_at,jsonb_build_object('id',r.id::text||':requested','action','requested','actorName',coalesce(st.name,CASE WHEN c.owner_user_id=r.created_by THEN 'مالك العلامة' ELSE 'موظف سابق' END),'createdAt',r.created_at,'note',r.payload->>'note') FROM public.bf_refund_requests r JOIN public.cafes c ON c.id=r.cafe_id LEFT JOIN public.bf_staff st ON st.cafe_id=r.cafe_id AND st.user_id=r.created_by WHERE r.cafe_id=d.cafe_id AND r.refund_document_id=d.id
  UNION ALL SELECT e.id::text,e.created_at,jsonb_build_object('id',e.id,'action',e.operation,'actorName',e.actor_name,'createdAt',e.created_at,'note',e.note) FROM public.bf_sales_return_stock_events e WHERE e.cafe_id=d.cafe_id AND e.return_id=d.id
 ) e;
 RETURN answer||jsonb_build_object('note',d.note,'taxInclusive',coalesce(d.tax_inclusive,true),'stockDocumentId',receipt,'lines',lines,'stockLines',stock_lines,'events',events);
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.shipping_charge_for_issue(p_cafe_id uuid, p_draft_id uuid, p_draft_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE chosen public.bf_invoice_shipping_drafts%ROWTYPE;settings jsonb;settings_revision integer;option public.bf_shipping_options%ROWTYPE;selected jsonb;aid uuid;
BEGIN
 SELECT * INTO chosen FROM public.bf_invoice_shipping_drafts WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
 IF chosen.draft_id IS NULL THEN RETURN NULL;END IF;
 IF chosen.draft_revision<>p_draft_revision THEN RAISE EXCEPTION 'أعد حفظ رسوم الشحن بعد تحديث المسودة' USING ERRCODE='40001';END IF;
 IF chosen.selection IS NULL THEN RETURN NULL;END IF;
 selected:=brand_finance_private.shipping_charge_selection(chosen.selection);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60622));
 SELECT s.settings,s.revision INTO settings,settings_revision FROM public.bf_shipping_settings s WHERE s.cafe_id=p_cafe_id;
 IF NOT coalesce((settings->>'enabled')::boolean,false) THEN RAISE EXCEPTION 'رسوم الشحن غير مفعلة' USING ERRCODE='22023';END IF;
 IF settings_revision IS DISTINCT FROM chosen.settings_revision THEN RAISE EXCEPTION 'Shipping settings conflict' USING ERRCODE='40001';END IF;
 IF selected->>'optionId' IS NOT NULL THEN
  SELECT * INTO option FROM public.bf_shipping_options WHERE cafe_id=p_cafe_id AND id=(selected->>'optionId')::uuid AND active AND deleted_at IS NULL FOR SHARE;
  IF option.id IS NULL THEN RAISE EXCEPTION 'خيار الشحن غير متاح اختر خيارًا نشطًا' USING ERRCODE='22023';END IF;
  IF option.revision IS DISTINCT FROM chosen.option_revision OR option.name IS DISTINCT FROM selected->>'name' THEN RAISE EXCEPTION 'Shipping option conflict' USING ERRCODE='40001';END IF;
 END IF;
 aid:=coalesce(option.account_id,brand_finance_private.account(p_cafe_id,'4000'));
 IF aid IS DISTINCT FROM chosen.account_id OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=aid AND active AND deleted_at IS NULL AND NOT frozen AND NOT is_group AND kind='revenue') THEN RAISE EXCEPTION 'حساب إيراد الشحن غير متاح' USING ERRCODE='22023';END IF;
 RETURN selected||jsonb_build_object('accountId',aid);
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.shipping_refund_revenue(p_cafe uuid, p_refund uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE row record;default_account uuid;
BEGIN
 FOR row IN SELECT l.id,l.net,l.tax,s.account_id,s.document_id AS source_id FROM public.bf_document_lines l JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=l.document_id AND d.kind='refund' JOIN public.bf_invoice_shipping_charges s ON s.cafe_id=l.cafe_id AND s.line_id=l.reference_line_id AND s.document_id=d.reference_id WHERE l.cafe_id=p_cafe AND l.document_id=p_refund AND NOT EXISTS(SELECT 1 FROM public.bf_invoice_shipping_refunds r WHERE r.cafe_id=p_cafe AND r.line_id=l.id) LOOP
  default_account:=brand_finance_private.account(p_cafe,'4000');
  IF row.account_id<>default_account THEN
   PERFORM brand_finance_private.invoice_line(p_cafe,p_refund,row.account_id,row.net,0,NULL,'عكس إيراد رسوم الشحن');
   PERFORM brand_finance_private.invoice_line(p_cafe,p_refund,default_account,0,row.net,NULL,'إعادة تصنيف إيراد الشحن المرتجع');
  END IF;
  INSERT INTO public.bf_invoice_shipping_refunds(line_id,cafe_id,document_id,source_document_id,account_id,net,tax) VALUES(row.id,p_cafe,p_refund,row.source_id,row.account_id,row.net,row.tax);
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.shipping_role(p_cafe_id uuid, p_write boolean DEFAULT false)
