CREATE OR REPLACE FUNCTION brand_finance_private.snapshot_before_inventory_catalog(p_cafe_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; answer jsonb;
BEGIN
 r:=brand_finance_private.role_for(p_cafe_id);
 answer:=brand_finance_private.snapshot_before_job_roles(p_cafe_id);
 -- Access and editability are deliberately separate; dashboard code uses capabilities.
 answer:=answer||jsonb_build_object('canManage',r<>'cashier','canAdminister',r='owner');
 IF r IN('accountant','auditor','warehouse') THEN answer:=answer||jsonb_build_object('staff','[]'::jsonb); END IF;
 IF r='cashier' THEN
  answer:=jsonb_set(answer,'{staff}',coalesce((SELECT jsonb_agg(s) FROM jsonb_array_elements(answer->'staff') s WHERE s->>'role' IN('manager','cashier')),'[]'::jsonb));
 END IF;
 IF r='warehouse' THEN
  answer:=answer||jsonb_build_object('accounts','[]'::jsonb,'parties','[]'::jsonb,'documents','[]'::jsonb,'journal','[]'::jsonb,'trialBalance','[]'::jsonb,'shifts','[]'::jsonb,'refundRequests','[]'::jsonb,
   'summary',jsonb_build_object('sales',0,'purchases',0,'expenses',0,'profit',0,'receivables',0,'payables',0,'inventoryValue',coalesce((answer->'summary'->>'inventoryValue')::numeric,0)));
 END IF;
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.stamp_sale_customer(p_document uuid, p_card uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE s public.bf_sale_customers; d public.bf_documents; c public.loyalty_cards; p public.cafe_loyalty_programs;
 v_stamps integer;v_rewards integer;v_reward boolean;v_event uuid;
BEGIN
 SELECT * INTO s FROM public.bf_sale_customers WHERE document_id=p_document FOR UPDATE;
 IF NOT FOUND OR s.loyalty_status<>'pending_enrollment' THEN RETURN; END IF;
 SELECT * INTO STRICT d FROM public.bf_documents WHERE id=p_document;
 IF (SELECT coalesce(sum(total),0) FROM public.bf_documents WHERE cafe_id=d.cafe_id AND kind='refund' AND reference_id=d.id)>=d.total THEN
  UPDATE public.bf_sale_customers SET loyalty_status='refunded' WHERE document_id=d.id; RETURN;
 END IF;
 IF NOT brand_finance_private.customer_loyalty_enabled(s.cafe_id) OR brand_finance_private.customer_card(s.cafe_id,s.phone) IS DISTINCT FROM p_card THEN RETURN; END IF;
 SELECT * INTO STRICT p FROM public.cafe_loyalty_programs WHERE cafe_id=s.cafe_id AND enabled FOR SHARE;
 SELECT * INTO STRICT c FROM public.loyalty_cards WHERE id=p_card AND cafe_id=s.cafe_id FOR UPDATE;

 IF NOT loyalty_read_private.french_daily_stamp_allowed(s.cafe_id,c.id,1) THEN
  UPDATE public.bf_sale_customers SET card_id=c.id,loyalty_status='unavailable' WHERE document_id=d.id;
  RETURN;
 END IF;
 SELECT count(*) INTO v_rewards FROM public.customer_reward_instances WHERE cafe_id=s.cafe_id AND loyalty_card_id=c.id AND status='available' AND (expires_at IS NULL OR expires_at>now());
 v_stamps:=c.stamps_in_cycle+1;v_reward:=v_stamps>=p.purchases_required;
 IF v_reward THEN v_stamps:=0;v_rewards:=v_rewards+1; END IF;
 UPDATE public.loyalty_cards SET stamps_in_cycle=v_stamps,available_rewards=v_rewards,total_purchases=total_purchases+1,
 completed_cycles=completed_cycles+CASE WHEN v_reward THEN 1 ELSE 0 END,last_used_at=now(),updated_at=now() WHERE id=c.id;
 INSERT INTO public.loyalty_card_events(cafe_id,card_id,performed_by,event_type,invoice_barcode,invoice_amount,stamps_added,reward_delta,stamps_after,rewards_after,note)
 VALUES(s.cafe_id,c.id,d.created_by,'stamp','POS-'||d.number::text,d.total,1,CASE WHEN v_reward THEN 1 ELSE 0 END,v_stamps,v_rewards,'ختم فاتورة نقطة البيع') RETURNING id INTO v_event;
 UPDATE public.bf_sale_customers SET card_id=c.id,stamp_event_id=v_event,loyalty_status='stamped' WHERE document_id=d.id;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.stock_move(p_cafe uuid, p_doc uuid, p_item uuid, p_warehouse uuid, p_quantity numeric, p_cost numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE policy jsonb;BEGIN
 IF auth.uid() IS NOT NULL AND NOT erp_inventory_private.warehouse_allowed(p_cafe,p_warehouse,'write') THEN RAISE EXCEPTION 'لا تملك تنفيذ حركة في هذا المستودع' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_inventory_items WHERE cafe_id=p_cafe AND item_id=p_item AND (kind<>'product' OR (status<>'active' AND NOT EXISTS(SELECT 1 FROM public.bf_documents d JOIN public.bf_movements m ON m.cafe_id=d.cafe_id AND m.document_id=d.reference_id WHERE d.cafe_id=p_cafe AND d.id=p_doc AND d.kind='refund' AND m.item_id=p_item AND m.warehouse_id=p_warehouse AND m.quantity*p_quantity<0)))) THEN RAISE EXCEPTION 'الصنف موقوف أو غير مخزني';END IF;
 SELECT payload INTO policy FROM public.erp_inventory_settings WHERE cafe_id=p_cafe;IF policy->>'allowNegative'='false' AND p_quantity<0 AND coalesce((SELECT quantity FROM public.bf_stock WHERE cafe_id=p_cafe AND item_id=p_item AND warehouse_id=p_warehouse),0)+p_quantity<0 THEN RAISE EXCEPTION 'إعدادات المخزون تمنع الكمية السالبة';END IF;
 RETURN erp_inventory_private.stock_move_before_inventory(p_cafe,p_doc,p_item,p_warehouse,p_quantity,p_cost);
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.template_claim_jobs(p_cafe uuid, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE d public.erp_template_deliveries%ROWTYPE;r public.erp_template_rules%ROWTYPE;t public.erp_document_templates%ROWTYPE;context jsonb;target text;answer jsonb:='[]';anchor timestamptz;
BEGIN
 UPDATE public.erp_template_deliveries SET status='unknown',last_error='انتهت مهلة تأكيد المزوّد ولن يكرر الإرسال تلقائيًا',lease_id=NULL,lease_until=NULL WHERE public.brand_account_not_cancelled(cafe_id) AND (p_cafe IS NULL OR cafe_id=p_cafe) AND status='sending' AND lease_until<now();
 UPDATE public.erp_template_deliveries SET status='cancelled',last_error='انتهت صلاحية الرسالة' WHERE public.brand_account_not_cancelled(cafe_id) AND (p_cafe IS NULL OR cafe_id=p_cafe) AND status IN('queued','blocked','failed') AND expires_at<now();
 FOR d IN SELECT * FROM public.erp_template_deliveries WHERE public.brand_account_not_cancelled(cafe_id) AND (p_cafe IS NULL OR cafe_id=p_cafe) AND status='queued' AND scheduled_at<=now() AND attempts<5 ORDER BY scheduled_at LIMIT greatest(1,least(p_limit,20)) FOR UPDATE SKIP LOCKED LOOP
  BEGIN
   SELECT * INTO r FROM public.erp_template_rules WHERE cafe_id=d.cafe_id AND id=d.rule_id AND active;
   SELECT * INTO t FROM public.erp_document_templates WHERE cafe_id=d.cafe_id AND id=d.template_id AND layout@>'{"active":true}';
   IF r.id IS NULL OR t.id IS NULL THEN UPDATE public.erp_template_deliveries SET status='cancelled',last_error='القالب أو القاعدة غير نشطة' WHERE cafe_id=d.cafe_id AND id=d.id;CONTINUE;END IF;
   context:=brand_finance_private.template_context(d.cafe_id,d.entity,d.entity_id);
   anchor:=nullif(context->>(r.payload->>'anchor'),'')::timestamptz;
   IF context IS NULL OR (coalesce(r.payload->>'status','')<>'' AND r.payload->>'status'<>context->>'status') OR (r.payload->>'payment'='unpaid' AND (context->>'paid')::numeric>0) OR (r.payload->>'payment'='partial' AND NOT((context->>'paid')::numeric>0 AND (context->>'outstanding')::numeric>0)) OR (r.payload->>'payment'='paid' AND (context->>'outstanding')::numeric>0) OR (anchor IS NOT NULL AND anchor IS DISTINCT FROM d.occurrence::timestamptz) THEN
    UPDATE public.erp_template_deliveries SET status='cancelled',last_error='لم تعد شروط الإرسال مطابقة لحالة المستند الحالية' WHERE cafe_id=d.cafe_id AND id=d.id;CONTINUE;
   END IF;
   target:=coalesce(context->>((r.payload->>'recipient')||CASE WHEN d.channel='email' THEN '_email' ELSE '_phone' END),'');
   IF target='' AND d.channel<>'system' THEN UPDATE public.erp_template_deliveries SET status='blocked',last_error='بيانات المستلم غير متاحة' WHERE cafe_id=d.cafe_id AND id=d.id;CONTINUE;END IF;
   UPDATE public.erp_template_deliveries SET status='sending',attempts=attempts+1,lease_id=gen_random_uuid(),lease_until=now()+interval '5 minutes',recipient=target,values=context->'values' WHERE cafe_id=d.cafe_id AND id=d.id RETURNING * INTO d;
   answer:=answer||jsonb_build_array(to_jsonb(d));
  EXCEPTION WHEN OTHERS THEN
   UPDATE public.erp_template_deliveries SET status='blocked',last_error='تعذر التحقق من حالة المستند الحالية' WHERE cafe_id=d.cafe_id AND id=d.id;
  END;
 END LOOP;RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.template_context(c uuid, e text, i uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE result jsonb;BEGIN
 result:=erp_payroll_private.template_context_before_preview(c,e,i);
 IF e='payroll_contract' AND EXISTS(SELECT 1 FROM public.erp_payroll_records WHERE cafe_id=c AND id=i AND coalesce((calculation->>'previewPending')::boolean,false)) THEN
  result:=result||jsonb_build_object('total',NULL,'outstanding',NULL,'previewPending',true);
  result:=jsonb_set(result,'{values}',(result->'values')||jsonb_build_object('المبلغ','يحسب عند تحديد فترة الراتب','المتبقي','يحسب عند تحديد فترة الراتب'));
 END IF;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.template_enqueue(c uuid, e text, i uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE context jsonb;r public.erp_template_rules%ROWTYPE;t public.erp_document_templates%ROWTYPE;anchor timestamptz;due_at timestamptz;expires timestamptz;span interval;target text;counted integer:=0;inserted integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.erp_template_rules WHERE cafe_id=c AND active AND payload->>'entity'=e) THEN RETURN 0;END IF;
 context:=brand_finance_private.template_context(c,e,i);IF context IS NULL THEN RETURN 0;END IF;
 FOR r IN SELECT * FROM public.erp_template_rules WHERE cafe_id=c AND active AND payload->>'entity'=e LOOP
  SELECT * INTO t FROM public.erp_document_templates WHERE cafe_id=c AND id=r.template_id AND layout@>'{"active":true}';IF NOT FOUND THEN CONTINUE;END IF;
  IF coalesce(r.payload->>'status','')<>'' AND r.payload->>'status'<>context->>'status' THEN UPDATE public.erp_template_deliveries SET status='cancelled',last_error='تغيرت حالة المستند' WHERE cafe_id=c AND rule_id=r.id AND entity_id=i AND status IN('queued','blocked','failed');CONTINUE;END IF;
  IF (r.payload->>'payment'='unpaid' AND (context->>'paid')::numeric>0) OR (r.payload->>'payment'='partial' AND NOT((context->>'paid')::numeric>0 AND (context->>'outstanding')::numeric>0)) OR (r.payload->>'payment'='paid' AND (context->>'outstanding')::numeric>0) THEN UPDATE public.erp_template_deliveries SET status='cancelled',last_error='تغيرت حالة السداد' WHERE cafe_id=c AND rule_id=r.id AND entity_id=i AND status IN('queued','blocked','failed');CONTINUE;END IF;
  anchor:=coalesce(nullif(context->>(r.payload->>'anchor'),'')::timestamptz,clock_timestamp());
  span:=CASE r.payload->>'unit' WHEN 'months' THEN make_interval(months=>(r.payload->>'offset')::integer) WHEN 'days' THEN make_interval(days=>(r.payload->>'offset')::integer) ELSE make_interval(hours=>(r.payload->>'offset')::integer) END;
  due_at:=CASE r.payload->>'timing' WHEN 'before' THEN anchor-span WHEN 'after' THEN anchor+span ELSE anchor END;
  expires:=CASE WHEN (r.payload->>'expires_after')::integer>0 THEN due_at+CASE r.payload->>'expires_unit' WHEN 'months' THEN make_interval(months=>(r.payload->>'expires_after')::integer) WHEN 'days' THEN make_interval(days=>(r.payload->>'expires_after')::integer) ELSE make_interval(hours=>(r.payload->>'expires_after')::integer) END ELSE NULL END;
  target:=coalesce(context->>((r.payload->>'recipient')||CASE WHEN r.payload->>'channel'='email' THEN '_email' ELSE '_phone' END),'');
  UPDATE public.erp_template_deliveries SET status='cancelled',last_error='تغير موعد المستند' WHERE cafe_id=c AND rule_id=r.id AND entity_id=i AND occurrence<>anchor::text AND status IN('queued','blocked','failed');
  INSERT INTO public.erp_template_deliveries(cafe_id,rule_id,template_id,entity_id,entity,occurrence,channel,recipient,subject,body,values,cc,bcc,status,scheduled_at,expires_at,last_error)
  VALUES(c,r.id,t.id,i,e,anchor::text,r.payload->>'channel',target,t.layout->>'subject',t.layout->>'body',context->'values',coalesce(t.layout->'cc','[]'),coalesce(t.layout->'bcc','[]')||CASE WHEN t.layout@>'{"bccSelf":true}' AND nullif(t.layout->>'bccSelfEmail','') IS NOT NULL THEN jsonb_build_array(t.layout->>'bccSelfEmail') ELSE '[]'::jsonb END,CASE WHEN target='' AND r.payload->>'channel'<>'system' THEN 'blocked' ELSE 'queued' END,due_at,expires,CASE WHEN target='' AND r.payload->>'channel'<>'system' THEN 'بيانات المستلم غير متاحة' ELSE '' END) ON CONFLICT(cafe_id,rule_id,entity_id,occurrence) DO NOTHING;
  GET DIAGNOSTICS inserted=ROW_COUNT;counted:=counted+inserted;
 END LOOP;RETURN counted;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.template_source_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE row_data jsonb:=to_jsonb(NEW);c uuid;target uuid;entity_name text;payment_doc jsonb;
BEGIN
 c:=(row_data->>'cafe_id')::uuid;target:=coalesce(nullif(row_data->>'document_id',''),nullif(row_data->>'id',''))::uuid;
 entity_name:=CASE TG_TABLE_NAME WHEN 'bf_company_invoices' THEN CASE WHEN row_data#>>'{snapshot,documentType}'='debit' THEN 'debit' ELSE 'invoice' END WHEN 'erp_bookings' THEN 'appointment' WHEN 'erp_booking_lines' THEN 'appointment' WHEN 'bf_quotes' THEN 'quotation' WHEN 'bf_credit_notes' THEN 'credit_note' WHEN 'erp_work_orders' THEN 'work_order' WHEN 'bf_documents' THEN CASE WHEN row_data->>'kind'='refund' THEN 'refund' WHEN row_data->>'kind'='settlement' THEN 'invoice' END END;
 IF TG_TABLE_NAME='erp_booking_lines' THEN target:=(row_data->>'booking_id')::uuid;END IF;
 IF TG_TABLE_NAME='bf_invoice_payments' THEN
  SELECT to_jsonb(d) INTO payment_doc FROM public.bf_documents d WHERE d.cafe_id=c AND d.id=(row_data->>'source_id')::uuid;
  target:=CASE WHEN payment_doc->>'kind'='settlement' THEN (payment_doc->>'reference_id')::uuid ELSE (payment_doc->>'id')::uuid END;
  IF payment_doc->>'kind' IN('sale','settlement') THEN entity_name:=CASE WHEN brand_finance_private.document_state(c,target)->>'document_type'='debit' THEN 'debit' ELSE 'invoice' END;END IF;
 END IF;
 IF TG_TABLE_NAME='bf_documents' AND row_data->>'kind'='settlement' THEN target:=(row_data->>'reference_id')::uuid;END IF;
 IF entity_name IS NOT NULL AND target IS NOT NULL THEN PERFORM brand_finance_private.template_enqueue(c,entity_name,target);END IF;RETURN NEW;
EXCEPTION WHEN OTHERS THEN INSERT INTO public.erp_template_events(cafe_id,record_id,action,actor) VALUES(c,target,'enqueue_failed:'||SQLSTATE,auth.uid());RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.terminal_fee_accrue(p_cafe uuid, p_terminal uuid, p_source uuid, p_month date, p_base numeric)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE a public.bf_accounts%ROWTYPE; f numeric; tax numeric; doc uuid:=gen_random_uuid(); k text; bank_label text;
BEGIN
 SELECT * INTO a FROM public.bf_accounts WHERE cafe_id=p_cafe AND id=p_terminal AND kind='pos' AND active;
 IF NOT FOUND OR a.linked_bank_id IS NULL THEN RETURN; END IF;
 k:=CASE WHEN p_month IS NULL THEN 'transaction' ELSE 'monthly' END;
 IF EXISTS(SELECT 1 FROM public.bf_terminal_fee_charges WHERE cafe_id=p_cafe AND terminal_id=p_terminal AND kind=k AND (source_document_id=p_source OR billing_month=p_month)) THEN RETURN; END IF;
 f:=CASE WHEN k='monthly' THEN a.monthly_subscription ELSE round(p_base*a.transaction_fee_percent/100,2) END;
 IF f<=0 THEN RETURN; END IF;
 tax:=round(f*a.fee_vat_rate/100,2);
 PERFORM brand_finance_private.terminal_fee_seed(p_cafe);
 SELECT name INTO bank_label FROM public.bf_accounts WHERE id=a.linked_bank_id AND cafe_id=p_cafe;
 INSERT INTO public.bf_documents(id,cafe_id,kind,account_id,reference_id,subtotal,tax,total,paid,note,created_by)
 VALUES(doc,p_cafe,'expense',p_terminal,p_source,f,tax,f+tax,0,CASE WHEN k='monthly' THEN 'اشتراك شبكة عن شهر '||p_month::text ELSE 'عمولة شبكة على التحصيل' END,auth.uid());
 PERFORM brand_finance_private.line(p_cafe,doc,brand_finance_private.account(p_cafe,'5110'),f,0);
 PERFORM brand_finance_private.line(p_cafe,doc,brand_finance_private.account(p_cafe,'1300'),tax,0);
 PERFORM brand_finance_private.line(p_cafe,doc,brand_finance_private.account(p_cafe,'2010'),0,f+tax);
 INSERT INTO public.bf_terminal_fee_charges(cafe_id,terminal_id,bank_id,terminal_name,bank_name,document_id,source_document_id,kind,billing_month,base_amount,fee_percent,vat_rate,fee,tax)
 VALUES(p_cafe,p_terminal,a.linked_bank_id,a.name,bank_label,doc,p_source,k,p_month,p_base,a.transaction_fee_percent,a.fee_vat_rate,f,tax);
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.terminal_fee_allocate(p_cafe uuid, p_terminal uuid, p_doc uuid, p_amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c record; remaining numeric:=p_amount; part numeric;
BEGIN
 IF p_amount>brand_finance_private.terminal_fees_due(p_cafe,p_terminal) THEN RAISE EXCEPTION 'مبلغ الرسوم المسددة يتجاوز الرسوم المستحقة'; END IF;
 FOR c IN SELECT id,total-brand_finance_private.terminal_fee_paid(p_cafe,id) due FROM public.bf_terminal_fee_charges WHERE cafe_id=p_cafe AND terminal_id=p_terminal ORDER BY created_at,id LOOP
  EXIT WHEN remaining<=0;
  part:=least(c.due,remaining);
  IF part>0 THEN INSERT INTO public.bf_terminal_fee_allocations(cafe_id,charge_id,document_id,amount) VALUES(p_cafe,c.id,p_doc,part); remaining:=remaining-part; END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.terminal_monthly_due_date(p_month date, p_day integer)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE first_day date:=date_trunc('month',p_month)::date; last_day date;
BEGIN
 IF p_month IS NULL OR p_day IS NULL OR p_day NOT BETWEEN 1 AND 31 THEN RAISE EXCEPTION 'اختر يوم استحقاق الاشتراك من ١ إلى ٣١'; END IF;
 last_day:=(first_day+interval '1 month'-interval '1 day')::date;
 RETURN first_day+least(p_day,extract(day FROM last_day)::integer)-1;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.terminal_monthly_ensure_at(p_cafe uuid, p_today date, p_skip_current_terminal uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE a record; month_value date; closed date; current_month date:=date_trunc('month',p_today)::date;
BEGIN
 IF p_today IS NULL THEN RAISE EXCEPTION 'Billing date required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 SELECT closed_through INTO closed FROM public.bf_settings WHERE cafe_id=p_cafe;
 IF closed>=(now() AT TIME ZONE 'Asia/Riyadh')::date THEN RETURN; END IF;
 FOR a IN SELECT id,fee_started_month,monthly_due_day FROM public.bf_accounts WHERE cafe_id=p_cafe AND kind='pos' AND active AND monthly_subscription>0 AND fee_started_month IS NOT NULL LOOP
  FOR month_value IN SELECT generate_series(a.fee_started_month,current_month,interval '1 month')::date LOOP
   IF month_value=current_month AND a.id=p_skip_current_terminal THEN CONTINUE; END IF;
   IF brand_finance_private.terminal_monthly_due_date(month_value,a.monthly_due_day)<=p_today THEN
    PERFORM brand_finance_private.terminal_fee_accrue(p_cafe,a.id,NULL,month_value,0);
   END IF;
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.terminal_sale_fee()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE d public.bf_documents%ROWTYPE;
BEGIN
 IF NEW.debit<=0 OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=NEW.cafe_id AND id=NEW.account_id AND kind='pos') THEN RETURN NEW; END IF;
 SELECT * INTO d FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.document_id;
 IF d.kind='sale' OR (d.kind='settlement' AND EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=d.cafe_id AND id=d.reference_id AND kind='sale')) THEN
  PERFORM brand_finance_private.terminal_monthly_ensure(NEW.cafe_id);
  PERFORM brand_finance_private.terminal_fee_accrue(NEW.cafe_id,NEW.account_id,NEW.document_id,NULL,NEW.debit);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.treasury_account_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE cap integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));
 IF TG_OP='INSERT' AND EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=NEW.cafe_id AND code=NEW.code) THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND (NEW.cafe_id<>OLD.cafe_id OR NEW.kind<>OLD.kind OR NEW.code<>OLD.code) THEN RAISE EXCEPTION 'Account identity is immutable'; END IF;
 IF TG_OP='UPDATE' AND OLD.kind='pos' AND (OLD.linked_bank_id IS DISTINCT FROM NEW.linked_bank_id OR (OLD.active AND NOT NEW.active)) AND brand_finance_private.terminal_fees_due(NEW.cafe_id,NEW.id)>0 THEN RAISE EXCEPTION 'سدد رسوم الشبكة المستحقة قبل أرشفتها أو تغيير البنك المرتبط'; END IF;
 IF NEW.kind IN('cash','bank','pos') THEN
  cap:=CASE NEW.kind WHEN 'bank' THEN 5 ELSE 3 END;
  IF NEW.deleted_at IS NULL AND (NEW.kind='cash' OR NEW.active) AND (TG_OP='INSERT' OR (NEW.active AND NOT OLD.active)) AND (SELECT count(*) FROM public.bf_accounts WHERE cafe_id=NEW.cafe_id AND kind=NEW.kind AND (active OR NEW.kind='cash') AND deleted_at IS NULL AND id<>NEW.id)>=cap THEN RAISE EXCEPTION 'تم الوصول إلى الحد المسموح للحسابات من هذا النوع'; END IF;
  IF NEW.linked_bank_id IS NOT NULL AND (NEW.kind<>'pos' OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=NEW.cafe_id AND id=NEW.linked_bank_id AND kind='bank' AND active)) THEN RAISE EXCEPTION 'اختر حسابا بنكيا نشطا لنقطة الشبكة'; END IF;
  IF TG_OP='UPDATE' AND OLD.linked_bank_id IS DISTINCT FROM NEW.linked_bank_id AND brand_finance_private.treasury_balance(NEW.cafe_id,NEW.id)<>0 THEN RAISE EXCEPTION 'سو رصيد الشبكة قبل تغيير الحساب البنكي المرتبط'; END IF;
  IF TG_OP='UPDATE' AND OLD.active AND NOT NEW.active THEN
   IF brand_finance_private.treasury_balance(NEW.cafe_id,NEW.id)<>0 OR EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=NEW.cafe_id AND account_id=NEW.id AND status IN('open','handover')) THEN RAISE EXCEPTION 'لا يمكن أرشفة حساب له رصيد أو وردية مفتوحة'; END IF;
   IF EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=NEW.cafe_id AND active AND linked_bank_id=NEW.id) THEN RAISE EXCEPTION 'الحساب مرتبط بنقطة شبكة نشطة'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.treasury_primary_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tenant uuid; category text;
BEGIN
 tenant:=CASE WHEN TG_OP='DELETE' THEN OLD.cafe_id ELSE NEW.cafe_id END;
 category:=CASE WHEN TG_OP='DELETE' THEN OLD.kind ELSE NEW.kind END;
 IF category IN('cash','bank','pos') AND EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=tenant AND kind=category AND active AND NOT is_cashier_drawer)
 AND (SELECT count(*) FROM public.bf_accounts WHERE cafe_id=tenant AND kind=category AND active AND is_primary)<>1 THEN
  RAISE EXCEPTION 'يجب تحديد حساب رئيسي واحد لكل نوع من الحسابات النشطة';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.treasury_primary_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));
 IF TG_OP='UPDATE' AND OLD.is_primary AND NOT NEW.active THEN RAISE EXCEPTION 'حدد حسابا رئيسيا بديلا قبل أرشفة هذا الحساب'; END IF;
 IF NEW.kind IN('cash','bank','pos') AND NEW.active AND NOT NEW.is_cashier_drawer AND (TG_OP='INSERT' OR NOT OLD.active) THEN
