CREATE OR REPLACE FUNCTION erp_access_private.action(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
BEGIN
 IF p_action IN('read','list','templates','submissions','quote','targets','customers','sales') THEN RETURN 'read';END IF;
 IF p_action~'(delete|remove)' THEN RETURN 'delete';END IF;
 IF p_action IN('settings','save_type','save_template','save_rule','rule','rule_delete','type','unit','season','location','service','package','availability','break','save_service','save_availability') THEN RETURN 'settings';END IF;
 IF p_action IN('note','link','assign','assign_sale','refresh','schedule','photo','cancel') THEN RETURN 'update';END IF;
 IF p_action IN('import','start_flow','submit') THEN RETURN 'create';END IF;
 IF p_action~'^(save|create)' OR p_action IN('reservation','contract','agreement','document','employee','activity') THEN RETURN CASE WHEN coalesce((p_data->>'revision')::integer,0)=0 THEN 'create' ELSE 'update' END;END IF;
 RETURN 'approve';
END $function$

CREATE OR REPLACE FUNCTION erp_access_private.allowed_before_system_settings(p_cafe uuid, p_domain text, p_action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.erp_roles%ROWTYPE;a public.erp_role_assignments%ROWTYPE;counted integer;base_role text;employee_active boolean;
BEGIN
 IF auth.uid() IS NULL OR p_domain IS NULL OR p_action IS NULL OR NOT p_domain=ANY(erp_access_private.domains()) OR p_action NOT IN('read','create','update','delete','approve','settings','files') THEN RETURN false;END IF;
 base_role:=brand_finance_private.role_for(p_cafe);IF base_role='owner' THEN RETURN true;END IF;IF base_role IS NULL THEN RETURN false;END IF;
 SELECT count(*) INTO counted FROM public.erp_role_assignments x LEFT JOIN public.erp_hr_employees e ON e.cafe_id=x.cafe_id AND e.id=x.employee_id WHERE x.cafe_id=p_cafe AND coalesce(x.user_id,e.user_id)=auth.uid();
 IF counted=0 THEN RETURN true;ELSIF counted<>1 THEN RETURN false;END IF;
 SELECT x.* INTO a FROM public.erp_role_assignments x LEFT JOIN public.erp_hr_employees e ON e.cafe_id=x.cafe_id AND e.id=x.employee_id WHERE x.cafe_id=p_cafe AND coalesce(x.user_id,e.user_id)=auth.uid();
 SELECT coalesce((SELECT active FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=a.employee_id),true) INTO employee_active; SELECT * INTO r FROM public.erp_roles WHERE cafe_id=p_cafe AND id=a.role_id;
 RETURN employee_active AND r.active AND NOT(r.blocked?p_domain) AND coalesce((r.permissions#>>ARRAY[p_domain,'read'])::boolean,false) AND coalesce((r.permissions#>>ARRAY[p_domain,p_action])::boolean,false);
END $function$

CREATE OR REPLACE FUNCTION erp_access_private.install_guard(p_name text, p_domain text, p_guard text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE item record;definition text;body text;patched text;
BEGIN
 IF NOT p_domain=ANY(erp_access_private.domains()) THEN RAISE EXCEPTION 'Invalid domain';END IF;
 FOR item IN SELECT p.oid,p.prosrc,l.lanname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND p.proname=p_name LOOP
  IF item.lanname<>'plpgsql' OR item.prosrc !~* '\mBEGIN\M' THEN RAISE EXCEPTION 'Unsupported guard target %',p_name;END IF;
  IF item.prosrc LIKE '%erp_access_private.assert_allowed(%' THEN CONTINUE;END IF;
  body:=regexp_replace(item.prosrc,'\mBEGIN\M','BEGIN '||p_guard,'i');definition:=pg_get_functiondef(item.oid);patched:=replace(definition,item.prosrc,body);EXECUTE patched;
  INSERT INTO erp_access_private.guard_registry VALUES(item.oid,p_domain,p_guard,md5(pg_get_functiondef(item.oid))) ON CONFLICT(function_id) DO UPDATE SET domain=excluded.domain,guard=excluded.guard,installed_definition_md5=excluded.installed_definition_md5;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_access_private.snapshot_erp_bookings_read(p_cafe_id uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; result jsonb;
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'bookings','read');
 r:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR coalesce(r,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Booking access denied' USING ERRCODE='42501'; END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_to<p_from OR p_to-p_from>62 THEN RAISE EXCEPTION 'Invalid date window' USING ERRCODE='22023'; END IF;
 SELECT jsonb_build_object('canWrite',r IN('owner','manager'),
 'settings',coalesce((SELECT to_jsonb(s)-'cafe_id' FROM erp_branch_private.erp_booking_settings s WHERE cafe_id=p_cafe_id),jsonb_build_object('revision',0,'assignment_mode','booking','service_mode','multiple','allow_unassigned',false,'allow_unscheduled',false,'default_service_id',null,'timezone','Asia/Riyadh','slot_minutes',30)),
 'services',coalesce((SELECT jsonb_agg(to_jsonb(s)-'cafe_id' ORDER BY name) FROM erp_branch_private.erp_booking_services s WHERE cafe_id=p_cafe_id),'[]'),
 'packages',coalesce((SELECT jsonb_agg(to_jsonb(s)-'cafe_id' ORDER BY name) FROM erp_branch_private.erp_booking_packages s WHERE cafe_id=p_cafe_id),'[]'),
 'availability',coalesce((SELECT jsonb_agg(to_jsonb(s)-'cafe_id') FROM erp_branch_private.erp_booking_availability s WHERE cafe_id=p_cafe_id),'[]'),
 'staff',coalesce((SELECT jsonb_agg(jsonb_build_object('id',user_id,'name',name)) FROM erp_branch_private.bf_staff WHERE cafe_id=p_cafe_id AND active),'[]')||jsonb_build_array((SELECT jsonb_build_object('id',owner_user_id,'name','مالك العلامة') FROM public.cafes WHERE id=p_cafe_id)),
 'branches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM erp_branch_private.branches WHERE cafe_id=p_cafe_id AND active AND deleted_at IS NULL),'[]'),
 'bookings',coalesce((SELECT jsonb_agg(to_jsonb(b)-'cafe_id'||jsonb_build_object('customer_name',c.name,'invoice_document_id',(SELECT document_id FROM erp_branch_private.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=b.invoice_draft_id),'lines',(SELECT coalesce(jsonb_agg(to_jsonb(l)-'cafe_id' ORDER BY position),'[]') FROM erp_branch_private.erp_booking_lines l WHERE booking_id=b.id),'events',(SELECT coalesce(jsonb_agg(to_jsonb(e)-'cafe_id' ORDER BY created_at),'[]') FROM erp_branch_private.erp_booking_events e WHERE booking_id=b.id)) ORDER BY b.created_at DESC) FROM erp_branch_private.erp_bookings b JOIN erp_branch_private.bf_parties c ON c.id=b.customer_id WHERE b.cafe_id=p_cafe_id AND EXISTS(SELECT 1 FROM erp_branch_private.erp_booking_lines l WHERE l.booking_id=b.id AND (l.starts_at IS NULL OR (l.starts_at<(p_to+1)::timestamptz+interval '1 day' AND l.ends_at>p_from::timestamptz-interval '1 day')))),'[]')) INTO result;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_access_private.snapshot_erp_contracting(p_cafe_id uuid, p_action text DEFAULT 'read'::text, p_input jsonb DEFAULT '{}'::jsonb, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
<<snapshot_erp_contracting>>
