  FOR l IN SELECT value FROM jsonb_array_elements(p_input->'lines') LOOP
   SELECT * INTO sl FROM public.erp_contracting_lines WHERE cafe_id=c AND document_id=s.id AND erp_contracting_lines.id=(l->>'source_line_id')::uuid AND kind='work';IF sl.id IS NULL OR (l->>'quantity')::numeric<=0 THEN RAISE EXCEPTION 'Invalid reverse source line' USING ERRCODE='22023';END IF;pos:=pos+1;
   INSERT INTO public.erp_contracting_lines(cafe_id,document_id,id,position,source_line_id,kind,name,unit,note,quantity,unit_price,markup,tax_rate) VALUES(c,id,(l->>'id')::uuid,pos,sl.id,'work',sl.name,sl.unit,coalesce(l->>'note',''),(l->>'quantity')::numeric,coalesce((SELECT unit_price FROM public.bf_document_lines WHERE cafe_id=c AND bf_document_lines.id=erp_contracting_private.invoice_line(c,s.id,sl.id)),sl.unit_price),0,sl.tax_rate);
  END LOOP;PERFORM erp_contracting_private.calculate(c,id);
 ELSE
  IF p_input->>'status'='issued' THEN
   IF d.kind='reverse_certificate' OR d.status<>'approved' OR d.invoice_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE cafe_id=c AND draft_id=d.invoice_draft_id) OR EXISTS(SELECT 1 FROM public.erp_contracting_documents WHERE cafe_id=c AND source_id=d.id AND status NOT IN('cancelled','rejected')) THEN RAISE EXCEPTION 'Billed or linked approval cannot be revoked' USING ERRCODE='22023';END IF;
   UPDATE public.erp_contracting_documents SET status='issued',revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=c AND erp_contracting_documents.id=d.id;
  ELSIF d.kind='reverse_certificate' AND p_input->>'status'='approved' THEN
   IF d.status<>'issued' THEN RAISE EXCEPTION 'Reverse must be issued before approval' USING ERRCODE='22023';END IF;PERFORM erp_access_private.assert_allowed(c,'finance','approve');
   PERFORM erp_contracting_private.calculate(c,id);SELECT * INTO d FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=snapshot_erp_contracting.id;SELECT * INTO s FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=d.source_id;
   result:='{}';IF d.total>0 THEN credit:=gen_random_uuid();UPDATE public.erp_contracting_reversals SET credit_note_id=credit WHERE cafe_id=c AND document_id=id;old_context:=current_setting('erp.contracting_reverse',true);PERFORM set_config('erp.contracting_reverse',id::text,true);payload:=erp_contracting_private.credit_payload(c,id);
   PERFORM public.brand_finance_save_credit_note(c,credit,0,payload);result:=public.brand_finance_transition_credit_note(c,credit,1,'issue',gen_random_uuid(),'');
   amount:=least(greatest(0,d.total-d.recovery),greatest(0,(brand_finance_private.document_state(c,s.invoice_id)->>'outstanding')::numeric));IF amount>0 THEN allocation:=brand_finance_private.customer_credit_apply(c,s.invoice_id,amount);END IF;
   IF to_regprocedure('erp_settings_private.reverse_advance_recovery(uuid,uuid,uuid,numeric)') IS NOT NULL THEN PERFORM erp_settings_private.reverse_advance_recovery(c,s.invoice_id,id,d.recovery);END IF;
   UPDATE public.erp_contracting_reversals SET credit_document_id=(result->>'journalId')::uuid,allocation_id=allocation WHERE cafe_id=c AND document_id=id;PERFORM set_config('erp.contracting_reverse',coalesce(old_context,''),true);END IF;
   UPDATE public.erp_contracting_documents SET status='approved',invoice_id=(result->>'journalId')::uuid,revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=c AND erp_contracting_documents.id=d.id;
   IF d.project_id IS NOT NULL AND d.total>0 THEN INSERT INTO public.erp_contracting_links(cafe_id,project_id,document_id,relation,amount) VALUES(c,d.project_id,(result->>'journalId')::uuid,'certificate_reversal',d.total);END IF;
  ELSIF d.kind='reverse_certificate' AND d.status IN('draft','issued') AND p_input->>'status'='cancelled' THEN UPDATE public.erp_contracting_documents SET status='cancelled',revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=c AND erp_contracting_documents.id=d.id;
  ELSE RAISE EXCEPTION 'Invalid reverse transition' USING ERRCODE='22023';END IF;
 END IF;
 result:=jsonb_build_object('id',id,'revision',(SELECT revision FROM public.erp_contracting_documents WHERE cafe_id=c AND erp_contracting_documents.id=snapshot_erp_contracting.id));INSERT INTO public.erp_contracting_events(cafe_id,document_id,action,note,actor) VALUES(c,id,CASE WHEN p_action='save' THEN 'reverse_saved' ELSE 'transition:'||(p_input->>'status') END,'',auth.uid());INSERT INTO public.erp_contracting_requests VALUES(c,p_request_id,cmd,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_access_private.snapshot_erp_installments_read(p_cafe_id uuid, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text;mode text:=coalesce(p_filters->>'mode','agreements');q text:=lower(btrim(coalesce(p_filters->>'query','')));status_filter text:=coalesce(p_filters->>'status','all');ordering text:=coalesce(p_filters->>'sort','newest');off integer:=coalesce((p_filters->>'offset')::integer,0);lim integer:=coalesce((p_filters->>'limit')::integer,30);date_from date:=nullif(p_filters->>'from','')::date;date_to date:=nullif(p_filters->>'to','')::date;items jsonb;cnt bigint;
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'installments','read');
 r:=brand_finance_private.role_for(p_cafe_id);IF auth.uid() IS NULL OR coalesce(r,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'لا تملك صلاحية عرض الأقساط' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_filters) IS DISTINCT FROM 'object' OR octet_length(p_filters::text)>3000 OR length(q)>100 OR mode NOT IN('agreements','installments','invoices') OR status_filter NOT IN('all','unpaid','partial','paid','overdue','cancelled') OR ordering NOT IN('newest','oldest','due','amount') OR off NOT BETWEEN 0 AND 100000 OR lim NOT BETWEEN 1 AND 100 OR date_from>date_to THEN RAISE EXCEPTION 'راجع خيارات البحث' USING ERRCODE='22023';END IF;
 WITH candidates AS MATERIALIZED(
 SELECT d.id FROM erp_branch_private.bf_documents d JOIN erp_branch_private.bf_parties c ON c.cafe_id=d.cafe_id AND c.id=d.party_id LEFT JOIN erp_branch_private.bf_invoice_management m ON m.cafe_id=d.cafe_id AND m.document_id=d.id LEFT JOIN erp_branch_private.bf_invoice_extensions e ON e.cafe_id=d.cafe_id AND e.document_id=d.id
 WHERE d.cafe_id=p_cafe_id AND d.kind='sale' AND (mode='invoices' OR jsonb_typeof(m.metadata->'schedule')='object') AND (q='' OR position(q IN lower(c.name||' '||d.number::text||' '||coalesce(e.display_number,'')))>0)
 ),agreements AS MATERIALIZED(SELECT erp_installment_private.agreement(p_cafe_id,id) item FROM candidates),expanded AS(
 SELECT a.item||jsonb_build_object('row',to_jsonb(t)) item FROM agreements a CROSS JOIN LATERAL erp_installment_private.rows((a.item->>'total')::numeric,(a.item->>'outstanding')::numeric,(a.item->>'refundedTotal')::numeric,a.item->'schedule') t WHERE mode='installments'
 UNION ALL SELECT a.item FROM agreements a WHERE mode<>'installments'
 ),matching AS MATERIALIZED(SELECT item FROM expanded WHERE (status_filter='all' OR CASE WHEN mode='installments' THEN item#>>'{row,status}' ELSE item->>'status' END=status_filter) AND (date_from IS NULL OR coalesce((item#>>'{row,date}')::date,(item->>'nextDue')::date,(item#>>'{schedule,start}')::date)>=date_from) AND (date_to IS NULL OR coalesce((item#>>'{row,date}')::date,(item->>'nextDue')::date,(item#>>'{schedule,start}')::date)<=date_to)),page AS(
 SELECT item,row_number() OVER(ORDER BY CASE WHEN ordering='due' THEN coalesce(item#>>'{row,date}',item->>'nextDue') END ASC NULLS LAST,CASE WHEN ordering='amount' THEN coalesce((item#>>'{row,remaining}')::numeric,(item->>'outstanding')::numeric) END DESC,CASE WHEN ordering='oldest' THEN item->>'createdAt' END ASC,CASE WHEN ordering<>'oldest' THEN item->>'createdAt' END DESC,item->>'id',item#>>'{row,number}') ordinal FROM matching
 ORDER BY ordinal LIMIT lim OFFSET off)
 SELECT (SELECT count(*) FROM matching),coalesce((SELECT jsonb_agg(item ORDER BY ordinal) FROM page),'[]') INTO cnt,items;
 RETURN jsonb_build_object('items',items,'total',cnt,'canWrite',r IN('owner','manager','accountant'),'actorId',auth.uid(),
 'accounts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'kind',kind) ORDER BY name) FROM erp_branch_private.bf_accounts WHERE cafe_id=p_cafe_id AND active AND deleted_at IS NULL AND NOT frozen AND NOT is_group AND NOT is_cashier_drawer AND kind IN('cash','bank','pos')),'[]'),
 'collectors',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM (SELECT p.id,coalesce(nullif(p.full_name,''),'مالك العلامة') name FROM public.cafes c JOIN public.profiles p ON p.id=c.owner_user_id AND p.status='active' WHERE c.id=p_cafe_id UNION SELECT s.user_id,coalesce(nullif(s.name,''),p.full_name) FROM erp_branch_private.bf_staff s JOIN public.profiles p ON p.id=s.user_id AND p.status='active' WHERE s.cafe_id=p_cafe_id AND s.active AND s.role IN('manager','accountant','cashier')) users),'[]'));
END $function$

CREATE OR REPLACE FUNCTION erp_access_private.snapshot_erp_manufacturing_read(p_cafe_id uuid, p_kind text DEFAULT 'orders'::text, p_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_status text DEFAULT ''::text, p_page integer DEFAULT 1, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tab text; rows jsonb; total integer; events jsonb; related jsonb; cfg jsonb; rev integer; r text; BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'manufacturing','read');
 r:=erp_manufacturing_private.authorize(p_cafe_id);tab:=erp_manufacturing_private.table_name(p_kind);
 IF tab IS NULL OR p_page NOT BETWEEN 1 AND 100000 OR length(p_query)>150 THEN RAISE EXCEPTION 'طلب قراءة غير صالح';END IF;
 SELECT value,revision INTO cfg,rev FROM erp_branch_private.erp_mfg_settings WHERE cafe_id=p_cafe_id;
 EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(t)-''cafe_id''-''created_by''||jsonb_build_object(''kind'',$1)),''[]'') FROM (SELECT * FROM erp_branch_private.%I WHERE cafe_id=$2 AND ($3 IS NULL OR id=$3) AND ($4='''' OR name ILIKE ''%%''||$4||''%%'' OR code ILIKE ''%%''||$4||''%%'') AND ($5='''' OR status=$5) AND erp_manufacturing_private.matches_fields($7,payload->''customValues'',$8) ORDER BY updated_at DESC,id LIMIT 50 OFFSET $6) t',tab) INTO rows USING p_kind,p_cafe_id,p_id,p_query,p_status,(p_page-1)*50,cfg->CASE p_kind WHEN 'orders' THEN 'orderFields' ELSE 'planFields' END,p_filters;
 EXECUTE format('SELECT count(*) FROM erp_branch_private.%I WHERE cafe_id=$1 AND ($2 IS NULL OR id=$2) AND ($3='''' OR name ILIKE ''%%''||$3||''%%'' OR code ILIKE ''%%''||$3||''%%'') AND ($4='''' OR status=$4) AND erp_manufacturing_private.matches_fields($5,payload->''customValues'',$6)',tab) INTO total USING p_cafe_id,p_id,p_query,p_status,cfg->CASE p_kind WHEN 'orders' THEN 'orderFields' ELSE 'planFields' END,p_filters;
 SELECT coalesce(jsonb_agg(to_jsonb(e)-'cafe_id'-'actor_id'||jsonb_build_object('actor_name',coalesce(s.name,'المالك')) ORDER BY e.created_at DESC),'[]') INTO events FROM erp_branch_private.erp_mfg_events e LEFT JOIN erp_branch_private.bf_staff s ON s.cafe_id=e.cafe_id AND s.user_id=e.actor_id WHERE e.cafe_id=p_cafe_id AND e.kind=p_kind AND e.record_id=p_id;
 SELECT coalesce(jsonb_agg(to_jsonb(o)-'cafe_id'-'created_by'||'{"kind":"orders"}'::jsonb ORDER BY created_at),'[]') INTO related FROM erp_branch_private.erp_mfg_orders o WHERE cafe_id=p_cafe_id AND plan_id=p_id;
 SELECT value,revision INTO cfg,rev FROM erp_branch_private.erp_mfg_settings WHERE cafe_id=p_cafe_id;
 RETURN jsonb_build_object('records',rows,'total',total,'events',events,'relatedOrders',related,'issues',coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id') FROM erp_branch_private.erp_mfg_material_issues x WHERE cafe_id=p_cafe_id AND order_id=p_id),'[]'),'allocations',coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id'||jsonb_build_object('order_name',o.name,'order_code',o.code)) FROM erp_branch_private.erp_mfg_overhead_allocations x JOIN erp_branch_private.erp_mfg_orders o ON o.cafe_id=x.cafe_id AND o.id=x.order_id WHERE x.cafe_id=p_cafe_id AND (x.overhead_id=p_id OR x.order_id=p_id)),'[]'),'role',r,'canWrite',r<>'auditor','canConfigure',r='owner','settings',coalesce(cfg,'{"autoStartOrders":true,"allowPartialMaterials":true,"orderStatuses":[],"planStatuses":[],"orderFields":[],"planFields":[],"orderForms":[],"planForms":[]}'::jsonb),'settingsRevision',coalesce(rev,0),'lookups',jsonb_build_object(
 'items',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'code',sku,'quantity',(SELECT coalesce(sum(quantity),0) FROM erp_branch_private.bf_stock WHERE cafe_id=p_cafe_id AND item_id=i.id))) FROM erp_branch_private.bf_items i WHERE cafe_id=p_cafe_id AND active),'[]'),
 'warehouses',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM erp_branch_private.bf_warehouses WHERE cafe_id=p_cafe_id AND active),'[]'),
 'accounts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'code',code,'status',kind)) FROM erp_branch_private.bf_accounts WHERE cafe_id=p_cafe_id AND active),'[]'),
 'customers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM erp_branch_private.bf_parties WHERE cafe_id=p_cafe_id AND active AND kind='customer'),'[]'),
 'employees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',user_id,'name',name)) FROM erp_branch_private.bf_staff WHERE cafe_id=p_cafe_id AND active),'[]'),
 'bom',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'code',code,'payload',payload)) FROM erp_branch_private.erp_mfg_boms WHERE cafe_id=p_cafe_id AND status='active'),'[]'),
 'routings',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'code',code,'payload',payload)) FROM erp_branch_private.erp_mfg_routings WHERE cafe_id=p_cafe_id),'[]'),
 'workstations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'code',code,'payload',payload)) FROM erp_branch_private.erp_mfg_workstations WHERE cafe_id=p_cafe_id AND status='active'),'[]'),
 'orders',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'code',code,'status',status,'payload',payload,'total',material_cost+additional_cost)) FROM erp_branch_private.erp_mfg_orders WHERE cafe_id=p_cafe_id AND status IN('ready','in_progress')),'[]'),
 'sources',coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.id,'name',d.number::text||' '||d.note,'total',d.total-coalesce((SELECT sum(amount) FROM erp_branch_private.erp_mfg_overhead_allocations WHERE cafe_id=p_cafe_id AND source_document_id=d.id),0),'status',d.kind)) FROM erp_branch_private.bf_documents d WHERE cafe_id=p_cafe_id AND kind IN('expense','sale')),'[]')));
END $function$

CREATE OR REPLACE FUNCTION erp_access_private.snapshot_erp_rentals_read(p_cafe_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;result jsonb:='{}';name text;items jsonb;
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'rentals','read');
 role_name:=brand_finance_private.role_for(p_cafe_id);IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Rental read denied' USING ERRCODE='42501';END IF;
 FOREACH name IN ARRAY ARRAY['rules','types','units','seasons'] LOOP EXECUTE format('SELECT coalesce(jsonb_agg(payload||jsonb_build_object(''id'',id,''revision'',revision) ORDER BY payload->>''name''),''[]'') FROM public.erp_rental_%I WHERE cafe_id=$1',name) INTO items USING p_cafe_id;result:=result||jsonb_build_object(name,items);END LOOP;
 RETURN result||jsonb_build_object('warehouseOptions',coalesce((SELECT jsonb_agg(jsonb_build_object('id',w.id,'name',w.name)) FROM erp_branch_private.bf_warehouses w WHERE w.cafe_id=p_cafe_id AND w.active),'[]'),'sourceOptions',brand_finance_private.order_source_settings(p_cafe_id)->'sources','sourceRequired',brand_finance_private.order_source_settings(p_cafe_id)->'required','salesAccounts',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'name',a.name) ORDER BY a.name) FROM erp_branch_private.bf_accounts a WHERE a.cafe_id=p_cafe_id AND a.kind='revenue' AND a.active AND NOT a.frozen AND NOT a.is_group AND a.deleted_at IS NULL),'[]'),'canWrite',role_name IN('owner','manager','accountant'),
 'settings',coalesce((SELECT payload||jsonb_build_object('revision',revision) FROM erp_branch_private.erp_rental_settings WHERE cafe_id=p_cafe_id),'{"revision":0,"lineMode":"single","invoiceStatus":"draft","onlineBooking":false,"fields":[]}'::jsonb),
 'reservations',coalesce((SELECT jsonb_agg(r.payload||jsonb_build_object('id',r.id,'revision',r.revision,'number',r.number,'status',r.status,'total',r.total,'draftId',r.draft_id,'recurringId',r.recurring_id,'invoiceId',i.document_id,'outstanding',CASE WHEN i.document_id IS NOT NULL THEN brand_finance_private.document_state(p_cafe_id,i.document_id)->'outstanding' END,'breakdown',r.breakdown,'customerName',p.name) ORDER BY r.created_at DESC) FROM erp_branch_private.erp_rental_reservations r JOIN erp_branch_private.bf_parties p ON p.cafe_id=r.cafe_id AND p.id=r.customer_id LEFT JOIN erp_branch_private.bf_company_invoices i ON i.cafe_id=r.cafe_id AND i.draft_id=r.draft_id WHERE r.cafe_id=p_cafe_id),'[]'),
 'contracts',coalesce((SELECT jsonb_agg(c.payload||jsonb_build_object('id',c.id,'revision',c.revision,'status',c.status,'customerName',p.name,'installments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'revision',x.revision,'contractId',x.contract_id,'due',x.due,'amount',x.amount,'note',x.note,'draftId',x.draft_id,'invoiceId',i.document_id,'invoiceTotal',d.total,'outstanding',CASE WHEN i.document_id IS NOT NULL THEN brand_finance_private.document_state(p_cafe_id,i.document_id)->'outstanding' END) ORDER BY x.due,x.id) FROM erp_branch_private.erp_rental_installments x LEFT JOIN erp_branch_private.bf_company_invoices i ON i.cafe_id=x.cafe_id AND i.draft_id=x.draft_id LEFT JOIN erp_branch_private.bf_documents d ON d.cafe_id=i.cafe_id AND d.id=i.document_id WHERE x.contract_id=c.id),'[]')) ORDER BY c.created_at DESC) FROM erp_branch_private.erp_rental_contracts c JOIN erp_branch_private.bf_parties p ON p.cafe_id=c.cafe_id AND p.id=c.customer_id WHERE c.cafe_id=p_cafe_id),'[]'),
 'events',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'entity',entity,'recordId',record_id,'action',action,'at',at,'details',details) ORDER BY at DESC) FROM erp_branch_private.erp_rental_events WHERE cafe_id=p_cafe_id),'[]'));
END $function$

CREATE OR REPLACE FUNCTION erp_access_private.snapshot_erp_templates(p_cafe_id uuid, p_action text DEFAULT 'read'::text, p_input jsonb DEFAULT '{}'::jsonb, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;prior public.erp_template_requests%ROWTYPE;t public.erp_document_templates%ROWTYPE;r public.erp_template_rules%ROWTYPE;cmd jsonb;answer jsonb;layout_data jsonb;row jsonb;doc_id uuid;draft_id uuid;old_revision integer;channel_name text;entity_name text;new_revision integer;
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'templates',erp_access_private.action(p_action,p_input));
 role_name:=brand_finance_private.role_for(p_cafe_id);IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_action='templates' THEN RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id' ORDER BY updated_at DESC) FROM erp_branch_private.erp_document_templates x WHERE cafe_id=p_cafe_id AND (nullif(p_input->>'kind','') IS NULL OR kind=p_input->>'kind')),'[]'::jsonb);END IF;
 IF p_action='read' THEN RETURN jsonb_build_object('templates',coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id' ORDER BY updated_at DESC) FROM erp_branch_private.erp_document_templates x WHERE cafe_id=p_cafe_id),'[]'::jsonb),'rules',coalesce((SELECT jsonb_agg(payload||jsonb_build_object('revision',revision)) FROM erp_branch_private.erp_template_rules WHERE cafe_id=p_cafe_id),'[]'::jsonb),'deliveries',coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id'-'lease_id'-'lease_until'-'values'-'cc'-'bcc' ORDER BY created_at DESC) FROM (SELECT * FROM erp_branch_private.erp_template_deliveries WHERE cafe_id=p_cafe_id ORDER BY created_at DESC LIMIT 300) x),'[]'::jsonb));END IF;
 IF role_name NOT IN('owner','manager','accountant') OR p_request_id IS NULL THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_input IS NULL OR jsonb_typeof(p_input)<>'object' OR octet_length(p_input::text)>300000 THEN RAISE EXCEPTION 'Invalid request' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,67152));cmd:=jsonb_build_object('action',p_action,'input',p_input);
 SELECT * INTO prior FROM erp_branch_private.erp_template_requests WHERE cafe_id=p_cafe_id AND id=p_request_id;IF FOUND THEN IF prior.command<>cmd THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;RETURN prior.result;END IF;
 doc_id:=nullif(p_input->>'id','')::uuid;
 IF p_action='save' THEN
  SELECT * INTO t FROM erp_branch_private.erp_document_templates WHERE cafe_id=p_cafe_id AND id=doc_id FOR UPDATE;
  IF coalesce(t.revision,0) IS DISTINCT FROM (p_input->>'revision')::integer OR (t.id IS NOT NULL AND (t.kind<>p_input->>'kind' OR t.channel<>p_input->>'channel')) THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  layout_data:=p_input->'layout';IF layout_data@>'{"bccSelf":true}' THEN layout_data:=layout_data||jsonb_build_object('bccSelfEmail',(SELECT email FROM auth.users WHERE id=auth.uid()));ELSE layout_data:=layout_data-'bccSelfEmail';END IF;
  IF jsonb_typeof(layout_data) IS DISTINCT FROM 'object' OR coalesce((layout_data->>'fontSize')::numeric,0) NOT BETWEEN 6 AND 40 OR coalesce((layout_data->>'margin')::numeric,-1) NOT BETWEEN 0 AND 50 OR coalesce((layout_data->>'width')::numeric,0) NOT BETWEEN 20 AND 420 OR coalesce((layout_data->>'height')::numeric,0) NOT BETWEEN 10 AND 594 OR coalesce(layout_data->>'paper','') NOT IN('A4','A3','A5','thermal','custom') OR coalesce(layout_data->>'language','') NOT IN('ar','en') OR coalesce(layout_data->>'font','') NOT IN('Tajawal','Arial','Tahoma','Verdana') OR coalesce(layout_data->>'orientation','') NOT IN('portrait','landscape') OR coalesce(layout_data->>'accent','')!~'^#[0-9a-fA-F]{6}$' OR coalesce(layout_data->>'tableStyle','') NOT IN('lines','striped','plain') OR length(coalesce(layout_data->>'body',''))>150000 OR length(coalesce(layout_data->>'footer',''))>5000 THEN RAISE EXCEPTION 'راجع مقاس الورق وتنسيق القالب' USING ERRCODE='22023';END IF;
  FOREACH channel_name IN ARRAY ARRAY['active','isDefault','showTable','showHeader','bccSelf'] LOOP IF jsonb_typeof(layout_data->channel_name) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid flags' USING ERRCODE='22023';END IF;END LOOP;
  FOREACH channel_name IN ARRAY ARRAY['cc','bcc','columns','invoiceLines'] LOOP IF jsonb_typeof(layout_data->channel_name) IS DISTINCT FROM 'array' OR jsonb_array_length(layout_data->channel_name)>100 THEN RAISE EXCEPTION 'Invalid list' USING ERRCODE='22023';END IF;END LOOP;
  FOR row IN SELECT value FROM jsonb_array_elements(layout_data->'invoiceLines') LOOP IF length(btrim(coalesce(row->>'name',''))) NOT BETWEEN 1 AND 160 OR coalesce((row->>'quantity')::numeric,0) NOT BETWEEN 0.001 AND 9999 OR coalesce((row->>'price')::numeric,-1) NOT BETWEEN 0 AND 1e9 OR coalesce((row->>'vatRate')::numeric,-1) NOT BETWEEN 0 AND 100 THEN RAISE EXCEPTION 'راجع بنود قالب الفاتورة' USING ERRCODE='22023';END IF;END LOOP;
  IF (layout_data->>'isDefault')::boolean THEN UPDATE public.erp_document_templates SET layout=jsonb_set(layout,'{isDefault}','false'),revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=p_cafe_id AND kind=p_input->>'kind' AND channel=p_input->>'channel' AND id<>doc_id AND layout@>'{"isDefault":true}';END IF;
  INSERT INTO public.erp_document_templates(cafe_id,id,kind,channel,name,layout) VALUES(p_cafe_id,doc_id,p_input->>'kind',p_input->>'channel',p_input->>'name',layout_data) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,layout=excluded.layout,revision=erp_document_templates.revision+1,updated_at=clock_timestamp() RETURNING revision INTO new_revision;
  IF NOT (layout_data->>'active')::boolean THEN UPDATE public.erp_template_deliveries SET status='cancelled',last_error='تم تعطيل القالب' WHERE cafe_id=p_cafe_id AND template_id=doc_id AND status IN('queued','blocked','failed');END IF;
  answer:=jsonb_build_object('id',doc_id,'revision',new_revision);
 ELSIF p_action='delete' THEN
  DELETE FROM erp_branch_private.erp_document_templates WHERE cafe_id=p_cafe_id AND id=doc_id AND revision=(p_input->>'revision')::integer RETURNING revision INTO new_revision;IF new_revision IS NULL THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;answer:=jsonb_build_object('id',doc_id,'revision',new_revision);
 ELSIF p_action='rule' THEN
  SELECT * INTO r FROM erp_branch_private.erp_template_rules WHERE cafe_id=p_cafe_id AND id=doc_id FOR UPDATE;
  IF coalesce(r.revision,0) IS DISTINCT FROM (p_input->>'revision')::integer THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  SELECT * INTO t FROM erp_branch_private.erp_document_templates WHERE cafe_id=p_cafe_id AND id=(p_input->>'template_id')::uuid;
  IF t.id IS NULL OR (p_input->>'channel'='email' AND t.channel<>'email') OR (p_input->>'channel' IN('sms','whatsapp','system') AND t.channel NOT IN('sms','email')) THEN RAISE EXCEPTION 'اختر قالبًا مناسبًا لطريقة الإرسال' USING ERRCODE='22023';END IF;
  IF coalesce(p_input->>'entity','') NOT IN('invoice','appointment','work_order','refund','debit','quotation','credit_note','payroll','payroll_contract') OR coalesce(p_input->>'channel','') NOT IN('email','sms','whatsapp','system') OR coalesce(p_input->>'recipient','') NOT IN('customer','employee') OR coalesce(p_input->>'anchor','') NOT IN('created','date','updated') OR coalesce(p_input->>'timing','') NOT IN('immediate','before','after') OR coalesce(p_input->>'payment','') NOT IN('any','unpaid','partial','paid') OR coalesce(p_input->>'unit','') NOT IN('hours','days','months') OR coalesce(p_input->>'expires_unit','') NOT IN('hours','days','months') OR coalesce((p_input->>'offset')::integer,-1) NOT BETWEEN 0 AND 8760 OR coalesce((p_input->>'expires_after')::integer,-1) NOT BETWEEN 0 AND 8760 OR jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع توقيت القاعدة وطريقة الإرسال' USING ERRCODE='22023';END IF;
  INSERT INTO public.erp_template_rules(cafe_id,id,name,template_id,active,payload) VALUES(p_cafe_id,doc_id,p_input->>'name',t.id,(p_input->>'active')::boolean,p_input) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,template_id=excluded.template_id,active=excluded.active,payload=excluded.payload,revision=erp_template_rules.revision+1 RETURNING revision INTO new_revision;
  IF NOT (p_input->>'active')::boolean THEN UPDATE public.erp_template_deliveries SET status='cancelled',last_error='تم تعطيل قاعدة الإرسال' WHERE cafe_id=p_cafe_id AND rule_id=doc_id AND status IN('queued','failed','blocked');END IF;
  answer:=jsonb_build_object('id',doc_id,'revision',new_revision);
 ELSIF p_action='rule_delete' THEN
  DELETE FROM erp_branch_private.erp_template_rules WHERE cafe_id=p_cafe_id AND id=doc_id AND revision=(p_input->>'revision')::integer RETURNING revision INTO new_revision;IF new_revision IS NULL THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  UPDATE public.erp_template_deliveries SET status='cancelled',last_error='تم حذف قاعدة الإرسال' WHERE cafe_id=p_cafe_id AND rule_id=doc_id AND status IN('queued','failed','blocked');answer:=jsonb_build_object('id',doc_id,'revision',new_revision);
 ELSIF p_action='enqueue' THEN
  answer:=jsonb_build_object('queued',brand_finance_private.template_enqueue(p_cafe_id,p_input->>'entity',(p_input->>'entity_id')::uuid));
 ELSIF p_action='retry' THEN
  UPDATE public.erp_template_deliveries SET status='queued',scheduled_at=clock_timestamp(),last_error='' WHERE cafe_id=p_cafe_id AND id=doc_id AND status IN('failed','blocked') AND attempts<5 AND (expires_at IS NULL OR expires_at>now()) AND EXISTS(SELECT 1 FROM erp_branch_private.erp_template_rules WHERE cafe_id=p_cafe_id AND id=rule_id AND active);IF NOT FOUND THEN RAISE EXCEPTION 'لا يمكن إعادة هذه الرسالة أو انتهت صلاحيتها' USING ERRCODE='22023';END IF;answer:=jsonb_build_object('id',doc_id);
 ELSIF p_action='cancel' THEN
  UPDATE public.erp_template_deliveries SET status='cancelled',last_error='إلغاء بواسطة المستخدم' WHERE cafe_id=p_cafe_id AND id=doc_id AND status IN('queued','failed','blocked','unknown');IF NOT FOUND THEN RAISE EXCEPTION 'الرسالة أرسلت أو قيد المعالجة' USING ERRCODE='22023';END IF;answer:=jsonb_build_object('id',doc_id);
 ELSIF p_action='invoice' THEN
  SELECT * INTO t FROM erp_branch_private.erp_document_templates WHERE cafe_id=p_cafe_id AND id=doc_id AND channel='invoice' AND layout@>'{"active":true}';IF t.id IS NULL OR jsonb_array_length(t.layout->'invoiceLines')=0 OR NOT EXISTS(SELECT 1 FROM erp_branch_private.bf_parties WHERE cafe_id=p_cafe_id AND id=(p_input->>'customer_id')::uuid AND kind='customer' AND active) THEN RAISE EXCEPTION 'اختر العميل وقالب فاتورة يحتوي على بنود' USING ERRCODE='22023';END IF;
  SELECT jsonb_agg(jsonb_build_object('key',ord,'productId','','name',v->>'name','description',v->>'description','kind','service','quantity',v->'quantity','price',v->'price','vatRate',v->'vatRate','taxCategory',CASE WHEN (v->>'vatRate')::numeric=0 THEN 'O' ELSE 'S' END,'exemptionReason',CASE WHEN (v->>'vatRate')::numeric=0 THEN 'خارج نطاق الضريبة حسب القالب' ELSE '' END)) INTO layout_data FROM jsonb_array_elements(t.layout->'invoiceLines') WITH ORDINALITY AS j(v,ord);
  layout_data:=jsonb_build_object('invoice',jsonb_build_object('lines',layout_data,'warehouseId','','partyId',p_input->>'customer_id','accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','taxInclusive',false,'note',left(t.layout->>'footer',500)),'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb);
  draft_id:=gen_random_uuid();PERFORM public.brand_finance_save_invoice_draft(p_cafe_id,draft_id,0,layout_data);answer:=jsonb_build_object('id',doc_id,'draftId',draft_id);
 ELSE RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023';END IF;
 INSERT INTO public.erp_template_events(cafe_id,record_id,action,actor) VALUES(p_cafe_id,doc_id,p_action,auth.uid());INSERT INTO public.erp_template_requests VALUES(p_cafe_id,p_request_id,cmd,answer);RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION erp_accounting_private.allocations(c uuid, d uuid, lines jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE line jsonb;allocation jsonb;i integer:=0;total numeric;seen uuid[];cid uuid;percentage numeric;BEGIN
 DELETE FROM public.erp_accounting_allocations WHERE cafe_id=c AND draft_id=d;
 FOR line IN SELECT * FROM jsonb_array_elements(lines) LOOP
  total:=0;seen:='{}';IF jsonb_typeof(coalesce(line->'costCenters','[]'))<>'array' OR jsonb_array_length(coalesce(line->'costCenters','[]'))>100 THEN RAISE EXCEPTION 'توزيع مراكز التكلفة غير صالح';END IF;
  FOR allocation IN SELECT * FROM jsonb_array_elements(coalesce(line->'costCenters','[]')) LOOP
   cid:=(allocation->>'id')::uuid;percentage:=(allocation->>'percentage')::numeric;
   IF cid=ANY(seen) OR NOT EXISTS(SELECT 1 FROM public.erp_cost_centers WHERE cafe_id=c AND id=cid AND active AND NOT is_group) OR percentage IS NULL OR percentage<=0 OR percentage>100 OR percentage='NaN'::numeric THEN RAISE EXCEPTION 'اختر مركز تكلفة فرعيًا نشطًا ونسبة صحيحة';END IF;
   seen:=array_append(seen,cid);total:=total+percentage;INSERT INTO public.erp_accounting_allocations(cafe_id,draft_id,line_index,cost_center_id,percentage) VALUES(c,d,i,cid,percentage);
  END LOOP;
  IF total<>0 AND total<>100 THEN RAISE EXCEPTION 'مجموع نسب توزيع السطر يجب أن يساوي مئة بالمئة';END IF;i:=i+1;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_accounting_private.asset_fields_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN
 IF TG_OP='UPDATE' AND NEW.payload IS NOT DISTINCT FROM OLD.payload AND NOT(OLD.status='draft' AND NEW.status='in_service') THEN RETURN NEW;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));
 PERFORM erp_accounting_private.validate_asset_values(coalesce((SELECT payload->'assetFields' FROM public.erp_accounting_settings WHERE cafe_id=NEW.cafe_id),'[]'),coalesce(NEW.payload->'customValues','{}'),NEW.cafe_id,NEW.id,'asset',0,NEW.status='draft');RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_accounting_private.gl_document(p_cafe_id uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE doc public.bf_documents;
BEGIN
  PERFORM erp_accounting_private.authorize(p_cafe_id);
  IF brand_finance_private.role_for(p_cafe_id) NOT IN('owner','manager','accountant','auditor') THEN
    RAISE EXCEPTION 'لا تملك صلاحية قراءة المستند' USING ERRCODE='42501'; END IF;
  SELECT * INTO doc FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_id;
  IF doc.id IS NULL THEN RAISE EXCEPTION 'المستند غير موجود'; END IF;
  RETURN jsonb_build_object('document',to_jsonb(doc)-'cafe_id',
    'lines',coalesce((SELECT jsonb_agg(to_jsonb(l)-'cafe_id' ORDER BY l.id) FROM public.bf_document_lines l WHERE cafe_id=p_cafe_id AND document_id=p_id),'[]'),
    'journal',coalesce((SELECT jsonb_agg(to_jsonb(j)-'cafe_id'||jsonb_build_object('accountName',a.name,'accountCode',a.code) ORDER BY j.id)
      FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=p_cafe_id AND j.document_id=p_id),'[]'),
    'partyName',(SELECT name FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=doc.party_id),
    'warehouseName',(SELECT name FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id=doc.warehouse_id));
END $function$

CREATE OR REPLACE FUNCTION erp_accounting_private.gl_execute(p_cafe_id uuid, p_action text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; old public.bf_requests; rec public.bf_gl_drafts; acc public.bf_accounts;
  cfg public.bf_gl_settings; period public.bf_gl_periods; x jsonb; normalized jsonb;
  eid uuid; did uuid; pid uuid; dt date; pend date; yr integer; n bigint; answer jsonb; expected integer;
  before_state jsonb; dr numeric; cr numeric; reason text; group_flag boolean;
BEGIN
  r:=brand_finance_private.role_for(p_cafe_id);
  PERFORM erp_accounting_private.authorize(p_cafe_id);
  IF r NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'لا تملك صلاحية تعديل دفتر الأستاذ' USING ERRCODE='42501'; END IF;
  IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000 THEN
    RAISE EXCEPTION 'بيانات الطلب غير صالحة';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
  PERFORM brand_finance_private.seed(p_cafe_id);
  INSERT INTO public.bf_gl_settings(cafe_id) VALUES(p_cafe_id) ON CONFLICT DO NOTHING;
  SELECT * INTO cfg FROM public.bf_gl_settings WHERE cafe_id=p_cafe_id;
  SELECT * INTO old FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
  IF FOUND THEN
    IF old.operation<>'gl:'||p_action OR old.payload<>p_payload OR old.created_by<>auth.uid() THEN
      RAISE EXCEPTION 'معرف الطلب مستخدم ببيانات مختلفة' USING ERRCODE='22023';
    END IF;
    RETURN old.result||jsonb_build_object('duplicate',true);
  END IF;
  eid:=nullif(p_payload->>'id','')::uuid;
  expected:=nullif(p_payload->>'revision','')::integer;
  reason:=btrim(coalesce(p_payload->>'reason',''));
  IF p_action='settings' THEN
    IF r<>'owner' THEN RAISE EXCEPTION 'إعداد الاعتماد للمالك فقط' USING ERRCODE='42501'; END IF;
    IF expected IS DISTINCT FROM cfg.revision THEN RAISE EXCEPTION 'تغير الإعداد حدث الصفحة' USING ERRCODE='40001'; END IF;
    IF length(reason) NOT BETWEEN 5 AND 1000 OR jsonb_typeof(p_payload->'makerChecker') IS DISTINCT FROM 'boolean' THEN
      RAISE EXCEPTION 'حدد سياسة الاعتماد وسبب تعديلها'; END IF;
    before_state:=to_jsonb(cfg);
    UPDATE public.bf_gl_settings SET maker_checker=(p_payload->>'makerChecker')::boolean,revision=revision+1 WHERE cafe_id=p_cafe_id RETURNING * INTO cfg;
    eid:=p_cafe_id; answer:=to_jsonb(cfg)-'cafe_id';
  ELSIF p_action='account_save' THEN
    IF coalesce(p_payload->>'kind','') NOT IN('expense','revenue','equity') THEN
      RAISE EXCEPTION 'أضف حسابات النقد والبنوك وأجهزة الدفع من الخزينة وحسابات الرقابة من وحداتها' USING ERRCODE='23514';
    END IF;
    IF r NOT IN('owner','accountant') THEN RAISE EXCEPTION 'تعديل دليل الحسابات للمالك والمحاسب' USING ERRCODE='42501'; END IF;
    IF eid IS NOT NULL THEN
      SELECT * INTO acc FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=eid FOR UPDATE;
      IF acc.id IS NULL THEN RAISE EXCEPTION 'الحساب غير موجود'; END IF;
      IF expected IS DISTINCT FROM acc.revision THEN RAISE EXCEPTION 'تغير الحساب حدث الصفحة' USING ERRCODE='40001'; END IF;
      before_state:=to_jsonb(acc);
    END IF;
    pid:=nullif(p_payload->>'parentId','')::uuid;
    group_flag:=coalesce((p_payload->>'isGroup')::boolean,false);
    IF length(btrim(coalesce(p_payload->>'name',''))) NOT BETWEEN 1 AND 100
      OR coalesce(p_payload->>'code','') !~ '^[A-Za-z0-9-]{1,30}$'
      OR coalesce(p_payload->>'kind','') NOT IN('cash','bank','pos','employee','receivable','payable','inventory','revenue','expense','equity','vat_input','vat_output','fixed_asset','accumulated_depreciation') THEN
      RAISE EXCEPTION 'راجع اسم الحساب ورمزه ونوعه'; END IF;
    IF pid IS NOT NULL THEN
      IF pid=eid OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=pid AND is_group AND active AND NOT frozen AND kind=p_payload->>'kind') THEN
        RAISE EXCEPTION 'اختر حسابًا أبًا تجميعيًا نشطًا من النوع نفسه'; END IF;
      IF EXISTS(WITH RECURSIVE ancestors AS (
        SELECT id,parent_id FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=pid
        UNION SELECT a.id,a.parent_id FROM public.bf_accounts a JOIN ancestors b ON a.id=b.parent_id WHERE a.cafe_id=p_cafe_id
      ) SELECT 1 FROM ancestors WHERE id=eid) THEN RAISE EXCEPTION 'لا يمكن إنشاء دورة في دليل الحسابات'; END IF;
    END IF;
    IF acc.id IS NOT NULL THEN
      IF acc.code IS DISTINCT FROM p_payload->>'code' OR acc.kind IS DISTINCT FROM p_payload->>'kind' THEN
        RAISE EXCEPTION 'رمز الحساب ونوعه ثابتان بعد إنشائه'; END IF;
      IF group_flag AND EXISTS(SELECT 1 FROM public.bf_journal WHERE cafe_id=p_cafe_id AND account_id=eid) THEN
        RAISE EXCEPTION 'لا يمكن تحويل حساب عليه قيود إلى حساب تجميعي'; END IF;
      IF NOT group_flag AND EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND parent_id=eid) THEN
        RAISE EXCEPTION 'الحساب الأب يجب أن يبقى تجميعيًا'; END IF;
      IF (group_flag OR coalesce((p_payload->>'frozen')::boolean,false) OR NOT coalesce((p_payload->>'active')::boolean,true))
        AND acc.code IN('1000','1010','1020','1030','1100','1200','1300','2000','2100','3000','4000','5000','5100','5200','5300','ERP-WIP','ASSET-COST','ASSET-ACCUM','ASSET-EXPENSE','ASSET-LOSS','ASSET-GAIN','ASSET-REVALUE') THEN
        RAISE EXCEPTION 'لا يمكن إيقاف حساب رقابي تستخدمه العمليات'; END IF;
      UPDATE public.bf_accounts SET name=btrim(p_payload->>'name'),parent_id=pid,is_group=group_flag,
        frozen=coalesce((p_payload->>'frozen')::boolean,false),active=coalesce((p_payload->>'active')::boolean,true),revision=revision+1
        WHERE cafe_id=p_cafe_id AND id=eid RETURNING * INTO acc;
    ELSE
      INSERT INTO public.bf_accounts(cafe_id,name,code,kind,parent_id,is_group)
        VALUES(p_cafe_id,btrim(p_payload->>'name'),p_payload->>'code',p_payload->>'kind',pid,group_flag) RETURNING * INTO acc;
      eid:=acc.id;
    END IF;
    answer:=to_jsonb(acc)-'cafe_id';
  ELSIF p_action IN('period_close','period_reopen') THEN
    IF r<>'owner' THEN RAISE EXCEPTION 'إدارة الفترات للمالك فقط' USING ERRCODE='42501'; END IF;
    dt:=(p_payload->>'from')::date; pend:=(p_payload->>'to')::date;
    IF dt IS NULL OR pend IS NULL OR NOT isfinite(dt) OR NOT isfinite(pend) OR pend<dt OR pend-dt>366
      OR length(reason) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'حدد فترة صحيحة لا تتجاوز عامًا وسبب الإجراء'; END IF;
    SELECT * INTO period FROM public.bf_gl_periods WHERE cafe_id=p_cafe_id AND period_start=dt FOR UPDATE;
    before_state:=to_jsonb(period);
    IF period.cafe_id IS NOT NULL AND (expected IS DISTINCT FROM period.revision OR pend<>period.period_end) THEN
      RAISE EXCEPTION 'تغيرت الفترة حدث الصفحة' USING ERRCODE='40001'; END IF;
    IF p_action='period_close' THEN
      IF pend>=(now() AT TIME ZONE 'Asia/Riyadh')::date THEN
        RAISE EXCEPTION 'اختر نهاية يوم مكتمل قبل اليوم الحالي بتوقيت الرياض';
      END IF;
      IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id
        AND status IN('open','handover') AND opened_at<(pend+1)::timestamp AT TIME ZONE 'Asia/Riyadh') THEN
        RAISE EXCEPTION 'أكمل إقفال الورديات وتسليمها ضمن الفترة قبل إقفال الفترة المالية';
      END IF;
      IF EXISTS(SELECT 1 FROM public.bf_cash_handovers h
        JOIN public.bf_shifts s ON s.cafe_id=h.cafe_id AND s.id=h.shift_id
        WHERE h.cafe_id=p_cafe_id AND s.opened_at<(pend+1)::timestamp AT TIME ZONE 'Asia/Riyadh'
        AND NOT EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts receipt WHERE receipt.cafe_id=h.cafe_id AND receipt.handover_id=h.id)) THEN
        RAISE EXCEPTION 'أكد استلام جميع مبالغ تسليم الصناديق المرتبطة بورديات الفترة أولًا';
      END IF;
      IF period.closed OR EXISTS(SELECT 1 FROM public.bf_gl_periods WHERE cafe_id=p_cafe_id AND closed
        AND period_start<>dt AND daterange(period_start,period_end,'[]') && daterange(dt,pend,'[]')) THEN
        RAISE EXCEPTION 'الفترة مقفلة أو تتداخل مع فترة مقفلة'; END IF;
      IF EXISTS(SELECT 1 FROM public.bf_gl_drafts WHERE cafe_id=p_cafe_id AND document_date BETWEEN dt AND pend AND status IN('submitted','approved')) THEN
        RAISE EXCEPTION 'رحل أو ألغ القيود المعلقة قبل الإقفال'; END IF;
      INSERT INTO public.bf_gl_periods(cafe_id,period_start,period_end) VALUES(p_cafe_id,dt,pend)
        ON CONFLICT(cafe_id,period_start) DO UPDATE SET closed=true,revision=public.bf_gl_periods.revision+1 RETURNING * INTO period;
    ELSE
      IF period.cafe_id IS NULL OR NOT period.closed THEN RAISE EXCEPTION 'الفترة ليست مقفلة'; END IF;
      IF EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe_id AND closed_through>=dt) THEN
        RAISE EXCEPTION 'الفترة مشمولة بإقفال قديم يحتاج مراجعة مستقلة قبل إعادة فتحه'; END IF;
      UPDATE public.bf_gl_periods SET closed=false,revision=revision+1 WHERE cafe_id=p_cafe_id AND period_start=dt RETURNING * INTO period;
    END IF;
    answer:=to_jsonb(period)-'cafe_id';
  ELSE
    IF eid IS NOT NULL THEN
      SELECT * INTO rec FROM public.bf_gl_drafts WHERE cafe_id=p_cafe_id AND id=eid FOR UPDATE;
      IF rec.id IS NULL THEN RAISE EXCEPTION 'القيد غير موجود'; END IF;
      IF expected IS DISTINCT FROM rec.revision THEN RAISE EXCEPTION 'تغير القيد حدث الصفحة قبل المتابعة' USING ERRCODE='40001'; END IF;
      before_state:=to_jsonb(rec);
    ELSIF p_action<>'save' THEN RAISE EXCEPTION 'اختر القيد'; END IF;
    IF p_action='save' THEN
      IF rec.id IS NOT NULL AND rec.status<>'draft' THEN RAISE EXCEPTION 'التعديل متاح للمسودة فقط'; END IF;
      dt:=(p_payload->>'date')::date; PERFORM brand_finance_private.gl_date_open(p_cafe_id,dt);
      IF length(btrim(coalesce(p_payload->>'title',''))) NOT BETWEEN 1 AND 150 OR length(coalesce(p_payload->>'note',''))>2000 THEN
        RAISE EXCEPTION 'اكتب عنوانًا صالحًا للقيد وملاحظة ضمن الحد'; END IF;
      normalized:=brand_finance_private.gl_lines(p_cafe_id,p_payload->'lines');
      IF rec.id IS NULL THEN
        yr:=erp_accounting_private.fiscal_year(p_cafe_id,dt);
        INSERT INTO public.bf_gl_sequences(cafe_id,kind,period,last_number) VALUES(p_cafe_id,'journal',yr,1)
          ON CONFLICT ON CONSTRAINT bf_gl_sequences_pkey DO UPDATE SET last_number=public.bf_gl_sequences.last_number+1 RETURNING last_number INTO n;
        INSERT INTO public.bf_gl_drafts(cafe_id,number,fiscal_year,title,document_date,note,lines,created_by,last_edited_by)
          VALUES(p_cafe_id,n,yr,btrim(p_payload->>'title'),dt,coalesce(p_payload->>'note',''),normalized,auth.uid(),auth.uid()) RETURNING * INTO rec;
      ELSE
        IF erp_accounting_private.fiscal_year(p_cafe_id,dt)<>rec.fiscal_year THEN RAISE EXCEPTION 'أنشئ مسودة جديدة عند تغيير سنة الترقيم'; END IF;
        UPDATE public.bf_gl_drafts SET title=btrim(p_payload->>'title'),document_date=dt,note=coalesce(p_payload->>'note',''),
          lines=normalized,last_edited_by=auth.uid(),revision=revision+1,updated_at=now() WHERE id=rec.id RETURNING * INTO rec;
      END IF;
    ELSIF p_action='submit' THEN
      IF rec.status<>'draft' THEN RAISE EXCEPTION 'الإرسال متاح للمسودة فقط'; END IF;
      PERFORM brand_finance_private.gl_lines(p_cafe_id,rec.lines);
      PERFORM brand_finance_private.gl_date_open(p_cafe_id,rec.document_date);
      UPDATE public.bf_gl_drafts SET status='submitted',revision=revision+1,updated_at=now() WHERE id=rec.id RETURNING * INTO rec;
    ELSIF p_action='approve' THEN
      IF rec.status<>'submitted' THEN RAISE EXCEPTION 'أرسل القيد للمراجعة أولًا'; END IF;
      IF cfg.maker_checker AND auth.uid() IN(rec.created_by,rec.last_edited_by) THEN RAISE EXCEPTION 'اعتماد المستند يتطلب مستخدمًا غير منشئه وآخر من عدل مسودته' USING ERRCODE='42501'; END IF;
      PERFORM brand_finance_private.gl_lines(p_cafe_id,rec.lines);
      UPDATE public.bf_gl_drafts SET status='approved',approved_by=auth.uid(),revision=revision+1,updated_at=now() WHERE id=rec.id RETURNING * INTO rec;
    ELSIF p_action='cancel' THEN
      IF rec.status NOT IN('draft','submitted','approved') OR length(reason) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'الإلغاء يحتاج قيدًا غير مرحل وسببًا واضحًا'; END IF;
      UPDATE public.bf_gl_drafts SET status='cancelled',revision=revision+1,updated_at=now() WHERE id=rec.id RETURNING * INTO rec;
    ELSIF p_action IN('post','reverse') THEN
      IF p_action='post' AND rec.status<>'approved' THEN RAISE EXCEPTION 'اعتمد القيد قبل الترحيل'; END IF;
      IF p_action='reverse' AND (rec.status<>'posted' OR length(reason) NOT BETWEEN 5 AND 1000) THEN RAISE EXCEPTION 'العكس يحتاج قيدًا مرحلًا وسببًا واضحًا'; END IF;
      dt:=CASE WHEN p_action='post' THEN rec.document_date ELSE (p_payload->>'date')::date END;
      PERFORM brand_finance_private.gl_date_open(p_cafe_id,dt);
      IF p_action='reverse' AND dt<rec.document_date THEN RAISE EXCEPTION 'تاريخ العكس لا يسبق تاريخ الأصل'; END IF;
      normalized:=brand_finance_private.gl_lines(p_cafe_id,rec.lines);
      IF normalized<>rec.lines THEN RAISE EXCEPTION 'تغيرت بيانات حسابات القيد ألغ القيد وأعد اعتماده'; END IF;
      did:=gen_random_uuid();
      INSERT INTO public.bf_documents(id,cafe_id,kind,note,created_by,created_at,reference_id)
        VALUES(did,p_cafe_id,'journal',left(rec.title||' — '||CASE WHEN p_action='reverse' THEN reason ELSE rec.note END,1000),
          auth.uid(),(dt+time '12:00') AT TIME ZONE 'Asia/Riyadh',CASE WHEN p_action='reverse' THEN rec.document_id ELSE NULL END);
      FOR x IN SELECT value FROM jsonb_array_elements(rec.lines) LOOP
        dr:=(x->>'debit')::numeric; cr:=(x->>'credit')::numeric;
        IF p_action='reverse' THEN dr:=(x->>'credit')::numeric; cr:=(x->>'debit')::numeric; END IF;
        IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND account_id=(x->>'accountId')::uuid AND status='handover') THEN
          RAISE EXCEPTION 'الخزينة قيد التسليم انتظر قبول الاستلام'; END IF;
        INSERT INTO public.bf_journal(cafe_id,document_id,account_id,debit,credit,memo)
          VALUES(p_cafe_id,did,(x->>'accountId')::uuid,dr,cr,coalesce(x->>'memo',''));
      END LOOP;
      IF EXISTS(SELECT 1 FROM public.bf_journal j JOIN public.bf_accounts a ON a.id=j.account_id AND a.cafe_id=j.cafe_id
        WHERE j.cafe_id=p_cafe_id AND a.kind IN('cash','employee') GROUP BY a.id HAVING sum(j.debit-j.credit)<0) THEN
        RAISE EXCEPTION 'رصيد النقدية أو العهدة غير كاف'; END IF;
      UPDATE public.bf_gl_drafts SET status=CASE WHEN p_action='post' THEN 'posted' ELSE 'reversed' END,
        document_id=CASE WHEN p_action='post' THEN did ELSE document_id END,
        reversal_document_id=CASE WHEN p_action='reverse' THEN did ELSE reversal_document_id END,
        revision=revision+1,updated_at=now() WHERE id=rec.id RETURNING * INTO rec;
    ELSE RAISE EXCEPTION 'إجراء دفتر الأستاذ غير معروف'; END IF;
    eid:=rec.id; answer:=to_jsonb(rec)-'cafe_id';
  END IF;
  INSERT INTO public.bf_gl_events(cafe_id,entity_id,action,details,created_by)
    VALUES(p_cafe_id,eid,p_action,jsonb_build_object('before',before_state,'after',answer,'reason',reason,'requestId',p_request_id),auth.uid());
  INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by)
    VALUES(p_cafe_id,p_request_id,'gl:'||p_action,p_payload,answer,auth.uid());
  RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION erp_accounting_private.gl_snapshot(p_cafe_id uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text;
BEGIN
  r:=brand_finance_private.role_for(p_cafe_id);
  PERFORM erp_accounting_private.authorize(p_cafe_id);
  IF r NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'لا تملك صلاحية قراءة دفتر الأستاذ' USING ERRCODE='42501'; END IF;
  IF p_offset IS NULL OR p_offset<0 OR p_offset>1000000 THEN RAISE EXCEPTION 'رقم الصفحة غير صالح'; END IF;
  RETURN jsonb_build_object(
    'settings',coalesce((SELECT to_jsonb(s)-'cafe_id'||jsonb_build_object('initialized',true) FROM erp_branch_private.bf_gl_settings s WHERE cafe_id=p_cafe_id),'{"maker_checker":true,"revision":1,"initialized":false}'::jsonb),
    'accounts',coalesce((SELECT jsonb_agg(to_jsonb(a)-'cafe_id' ORDER BY code) FROM erp_branch_private.bf_accounts a WHERE cafe_id=p_cafe_id),'[]'::jsonb),
    'drafts',coalesce((SELECT jsonb_agg(to_jsonb(d)-'cafe_id' ORDER BY created_at DESC,id) FROM
      (SELECT * FROM erp_branch_private.bf_gl_drafts WHERE cafe_id=p_cafe_id ORDER BY created_at DESC,id OFFSET p_offset LIMIT 100) d),'[]'::jsonb),
    'hasMore',EXISTS(SELECT 1 FROM erp_branch_private.bf_gl_drafts WHERE cafe_id=p_cafe_id OFFSET p_offset+100 LIMIT 1),
    'periods',coalesce((SELECT jsonb_agg(to_jsonb(p)-'cafe_id' ORDER BY period_start DESC) FROM erp_branch_private.bf_gl_periods p WHERE cafe_id=p_cafe_id),'[]'::jsonb)
  );
END $function$

CREATE OR REPLACE FUNCTION erp_accounting_private.line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE account public.bf_accounts;dated timestamptz;BEGIN
 IF EXISTS(SELECT 1 FROM public.erp_accounting_settings WHERE cafe_id=NEW.cafe_id) THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));SELECT * INTO account FROM public.bf_accounts WHERE cafe_id=NEW.cafe_id AND id=NEW.account_id FOR SHARE;
  IF NOT FOUND OR NOT account.active OR account.frozen OR account.is_group THEN RAISE EXCEPTION 'الحساب غير متاح للترحيل';END IF;
  SELECT created_at INTO dated FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.document_id;PERFORM brand_finance_private.gl_date_open(NEW.cafe_id,(dated AT TIME ZONE 'Asia/Riyadh')::date);NEW.created_at:=dated;
 END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_accounting_private.save_cost_center(c uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE old public.erp_cost_centers;answer public.erp_cost_centers;rid uuid:=coalesce((p->>'id')::uuid,gen_random_uuid());parent uuid:=(p->>'parentId')::uuid;BEGIN
 IF p->>'id' IS NOT NULL THEN SELECT * INTO old FROM public.erp_cost_centers WHERE cafe_id=c AND id=rid FOR UPDATE;IF NOT FOUND OR old.revision IS DISTINCT FROM (p->>'revision')::integer THEN RAISE EXCEPTION 'تغير مركز التكلفة' USING ERRCODE='40001';END IF;END IF;
 IF parent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_cost_centers WHERE cafe_id=c AND id=parent AND active AND is_group) THEN RAISE EXCEPTION 'اختر مركز تكلفة رئيسيًا نشطًا';END IF;
 IF parent=rid OR EXISTS(WITH RECURSIVE ancestors AS(SELECT id,parent_id FROM public.erp_cost_centers WHERE cafe_id=c AND id=parent UNION ALL SELECT x.id,x.parent_id FROM public.erp_cost_centers x JOIN ancestors a ON x.id=a.parent_id WHERE x.cafe_id=c) SELECT 1 FROM ancestors WHERE id=rid) THEN RAISE EXCEPTION 'لا يمكن إنشاء دورة في شجرة مراكز التكلفة';END IF;
 IF NOT coalesce((p->>'isGroup')::boolean,false) AND EXISTS(SELECT 1 FROM public.erp_cost_centers WHERE cafe_id=c AND parent_id=rid) THEN RAISE EXCEPTION 'المركز الرئيسي مرتبط بمراكز فرعية';END IF;
 IF coalesce((p->>'isGroup')::boolean,false) AND EXISTS(SELECT 1 FROM public.erp_accounting_allocations WHERE cafe_id=c AND cost_center_id=rid) THEN RAISE EXCEPTION 'المركز مستخدم في قيود ولا يمكن تحويله إلى رئيسي';END IF;
 INSERT INTO public.erp_cost_centers(id,cafe_id,code,name,parent_id,is_group,active) VALUES(rid,c,btrim(p->>'code'),btrim(p->>'name'),parent,(p->>'isGroup')::boolean,(p->>'active')::boolean) ON CONFLICT(id) DO UPDATE SET code=excluded.code,name=excluded.name,parent_id=excluded.parent_id,is_group=excluded.is_group,active=excluded.active,revision=erp_cost_centers.revision+1 RETURNING * INTO answer;RETURN to_jsonb(answer)-'cafe_id';
END $function$

CREATE OR REPLACE FUNCTION erp_accounting_private.validate_asset_values(fields jsonb, vals jsonb, p_cafe uuid DEFAULT NULL::uuid, p_record uuid DEFAULT NULL::uuid, p_kind text DEFAULT NULL::text, depth integer DEFAULT 0, p_draft boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE f jsonb;v jsonb;t text;x jsonb;txt text;tbl text;col text;valid boolean;metric numeric;BEGIN
 IF coalesce(jsonb_typeof(vals),'')<>'object' OR octet_length(vals::text)>262144 OR depth>2 THEN RAISE EXCEPTION 'بيانات الحقول الإضافية غير صالحة';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP
  t:=f->>'type';IF t IN('static','separator') THEN CONTINUE;END IF;
  v:=coalesce(vals->(f->>'id'),f->'defaultValue');
  IF coalesce((f->>'required')::boolean,false) AND NOT p_draft AND (v IS NULL OR v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb OR (t='checkbox' AND v<>'true')) THEN RAISE EXCEPTION 'أكمل الحقل المطلوب: %',f->>'label';END IF;
  IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
  IF t='subform' THEN
   IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>100 OR jsonb_array_length(v)<coalesce((f->>'minimumRows')::integer,0) THEN RAISE EXCEPTION 'عدد صفوف النموذج غير صالح';END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM erp_accounting_private.validate_asset_values(f->'fields',x,p_cafe,p_record,p_kind,depth+1,p_draft);END LOOP;CONTINUE;
  END IF;
  IF t='location' THEN
   IF jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'latitude')<>'number' OR jsonb_typeof(v->'longitude')<>'number' OR abs((v->>'latitude')::numeric)>90 OR abs((v->>'longitude')::numeric)>180 THEN RAISE EXCEPTION 'إحداثيات الموقع غير صالحة';END IF;CONTINUE;
  END IF;
  IF (t IN('number','currency') AND jsonb_typeof(v)<>'number') OR (t='checkbox' AND jsonb_typeof(v)<>'boolean') OR (t IN('multiselect','multidynamic') AND jsonb_typeof(v)<>'array') OR (t NOT IN('number','currency','checkbox','multiselect','multidynamic') AND jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'نوع قيمة الحقل غير صالح';END IF;
  txt:=v#>>'{}';
  IF length(txt)>20000 THEN RAISE EXCEPTION 'قيمة الحقل طويلة';END IF;
  IF (t='select' AND NOT(f->'options' @> jsonb_build_array(v))) OR (t='multiselect' AND NOT(f->'options' @> v)) THEN RAISE EXCEPTION 'اختيارات الحقل غير صالحة';END IF;
  IF t='email' AND txt!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'البريد الإلكتروني غير صالح';END IF;
  IF t='url' AND txt!~'^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'الرابط غير صالح';END IF;
  IF t='time' AND txt!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'الوقت غير صالح';END IF;
  IF t='date' THEN IF txt!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'التاريخ غير صالح';END IF;PERFORM txt::date;END IF;
  IF t IN('number','currency','text','textarea','formatted') THEN
   metric:=CASE WHEN t IN('number','currency') THEN txt::numeric ELSE length(txt) END;
   IF metric<nullif(f->>'minimum','')::numeric OR metric>nullif(f->>'maximum','')::numeric THEN RAISE EXCEPTION 'قيمة الحقل خارج الحدود: %',f->>'label';END IF;
  END IF;
  IF t IN('dynamic','multidynamic') THEN
   tbl:=CASE f->>'entity' WHEN 'items' THEN 'bf_items' WHEN 'customers' THEN 'bf_parties' WHEN 'employees' THEN 'erp_hr_employees' WHEN 'warehouses' THEN 'bf_warehouses' WHEN 'accounts' THEN 'bf_accounts' WHEN 'bom' THEN 'erp_mfg_boms' WHEN 'routings' THEN 'erp_mfg_routings' WHEN 'workstations' THEN 'erp_mfg_workstations' WHEN 'orders' THEN 'erp_mfg_orders' WHEN 'sources' THEN 'bf_documents' END;
   IF tbl IS NULL OR p_cafe IS NULL THEN RAISE EXCEPTION 'الكيان المرتبط غير صالح';END IF;col:=CASE WHEN tbl='bf_staff' THEN 'user_id' ELSE 'id' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN t='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND %I=$2)',tbl,col) INTO valid USING p_cafe,(x#>>'{}')::uuid;
    IF NOT valid THEN RAISE EXCEPTION 'القيمة المرتبطة غير موجودة في العلامة';END IF;
   END LOOP;
  END IF;
  IF t IN('file','image') THEN
   IF p_record IS NULL OR to_regclass('public.erp_files') IS NULL THEN RAISE EXCEPTION 'احفظ السجل وأضف المرفق أولًا';END IF;
   EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=$1 AND record_id=$2 AND id=$3 AND entity_type=$4 AND uploaded AND ($5<>''image'' OR mime IN(''image/jpeg'',''image/png'')))' INTO valid USING p_cafe,p_record,txt::uuid,'asset',t;
   IF NOT valid THEN RAISE EXCEPTION 'المرفق غير موجود في هذا السجل';END IF;
   PERFORM 1 FROM public.erp_files f WHERE f.cafe_id=p_cafe AND f.record_id=p_record AND f.id=txt::uuid AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='erp-record-files' AND o.name=f.path) FOR KEY SHARE OF f;
   IF NOT FOUND THEN RAISE EXCEPTION 'الملف المرفق لم يعد متاحًا';END IF;
  END IF;
  IF coalesce((f->>'unique')::boolean,false) AND depth=0 AND p_kind='asset' THEN
   tbl:='erp_assets';
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id IS DISTINCT FROM $2 AND payload->''customValues''->$3=$4)',tbl) INTO valid USING p_cafe,p_record,f->>'id',v;
   IF valid THEN RAISE EXCEPTION 'قيمة الحقل مستخدمة مسبقًا: %',f->>'label';END IF;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_accounting_private.validate_custom_values(fields jsonb, vals jsonb, p_cafe uuid DEFAULT NULL::uuid, p_record uuid DEFAULT NULL::uuid, p_kind text DEFAULT NULL::text, depth integer DEFAULT 0, p_draft boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE f jsonb;v jsonb;t text;x jsonb;txt text;tbl text;col text;valid boolean;metric numeric;BEGIN
 IF coalesce(jsonb_typeof(vals),'')<>'object' OR octet_length(vals::text)>262144 OR depth>2 THEN RAISE EXCEPTION 'بيانات الحقول الإضافية غير صالحة';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP
  t:=f->>'type';IF t IN('static','separator') THEN CONTINUE;END IF;
  v:=coalesce(vals->(f->>'id'),f->'defaultValue');
  IF coalesce((f->>'required')::boolean,false) AND NOT p_draft AND (v IS NULL OR v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb OR (t='checkbox' AND v<>'true')) THEN RAISE EXCEPTION 'أكمل الحقل المطلوب: %',f->>'label';END IF;
  IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
  IF t='subform' THEN
   IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>100 OR jsonb_array_length(v)<coalesce((f->>'minimumRows')::integer,0) THEN RAISE EXCEPTION 'عدد صفوف النموذج غير صالح';END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM erp_accounting_private.validate_custom_values(f->'fields',x,p_cafe,p_record,p_kind,depth+1,p_draft);END LOOP;CONTINUE;
  END IF;
  IF t='location' THEN
   IF jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'latitude')<>'number' OR jsonb_typeof(v->'longitude')<>'number' OR abs((v->>'latitude')::numeric)>90 OR abs((v->>'longitude')::numeric)>180 THEN RAISE EXCEPTION 'إحداثيات الموقع غير صالحة';END IF;CONTINUE;
  END IF;
  IF (t IN('number','currency') AND jsonb_typeof(v)<>'number') OR (t='checkbox' AND jsonb_typeof(v)<>'boolean') OR (t IN('multiselect','multidynamic') AND jsonb_typeof(v)<>'array') OR (t NOT IN('number','currency','checkbox','multiselect','multidynamic') AND jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'نوع قيمة الحقل غير صالح';END IF;
  txt:=v#>>'{}';
  IF length(txt)>20000 THEN RAISE EXCEPTION 'قيمة الحقل طويلة';END IF;
  IF (t='select' AND NOT(f->'options' @> jsonb_build_array(v))) OR (t='multiselect' AND NOT(f->'options' @> v)) THEN RAISE EXCEPTION 'اختيارات الحقل غير صالحة';END IF;
  IF t='email' AND txt!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'البريد الإلكتروني غير صالح';END IF;
  IF t='url' AND txt!~'^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'الرابط غير صالح';END IF;
  IF t='time' AND txt!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'الوقت غير صالح';END IF;
  IF t='date' THEN IF txt!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'التاريخ غير صالح';END IF;PERFORM txt::date;END IF;
  IF t IN('number','currency','text','textarea','formatted') THEN
   metric:=CASE WHEN t IN('number','currency') THEN txt::numeric ELSE length(txt) END;
   IF metric<nullif(f->>'minimum','')::numeric OR metric>nullif(f->>'maximum','')::numeric THEN RAISE EXCEPTION 'قيمة الحقل خارج الحدود: %',f->>'label';END IF;
  END IF;
  IF t IN('dynamic','multidynamic') THEN
   tbl:=CASE f->>'entity' WHEN 'items' THEN 'bf_items' WHEN 'customers' THEN 'bf_parties' WHEN 'employees' THEN 'erp_hr_employees' WHEN 'warehouses' THEN 'bf_warehouses' WHEN 'accounts' THEN 'bf_accounts' WHEN 'bom' THEN 'erp_mfg_boms' WHEN 'routings' THEN 'erp_mfg_routings' WHEN 'workstations' THEN 'erp_mfg_workstations' WHEN 'orders' THEN 'erp_mfg_orders' WHEN 'sources' THEN 'bf_documents' END;
   IF tbl IS NULL OR p_cafe IS NULL THEN RAISE EXCEPTION 'الكيان المرتبط غير صالح';END IF;col:=CASE WHEN tbl='bf_staff' THEN 'user_id' ELSE 'id' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN t='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND %I=$2)',tbl,col) INTO valid USING p_cafe,(x#>>'{}')::uuid;
    IF NOT valid THEN RAISE EXCEPTION 'القيمة المرتبطة غير موجودة في العلامة';END IF;
   END LOOP;
  END IF;
  IF t IN('file','image') THEN
   IF p_record IS NULL OR to_regclass('public.erp_files') IS NULL THEN RAISE EXCEPTION 'احفظ السجل وأضف المرفق أولًا';END IF;
   EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=$1 AND record_id=$2 AND id=$3 AND entity_type=$4 AND uploaded AND ($5<>''image'' OR mime IN(''image/jpeg'',''image/png'')))' INTO valid USING p_cafe,p_record,txt::uuid,'journal_draft',t;
   IF NOT valid THEN RAISE EXCEPTION 'المرفق غير موجود في هذا السجل';END IF;
   PERFORM 1 FROM public.erp_files f WHERE f.cafe_id=p_cafe AND f.record_id=p_record AND f.id=txt::uuid AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='erp-record-files' AND o.name=f.path) FOR KEY SHARE OF f;
   IF NOT FOUND THEN RAISE EXCEPTION 'الملف المرفق لم يعد متاحًا';END IF;
  END IF;
  IF coalesce((f->>'unique')::boolean,false) AND depth=0 AND p_kind='journal' THEN
   tbl:='erp_accounting_metadata';
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND draft_id IS DISTINCT FROM $2 AND payload->''customValues''->$3=$4)',tbl) INTO valid USING p_cafe,p_record,f->>'id',v;
   IF valid THEN RAISE EXCEPTION 'قيمة الحقل مستخدمة مسبقًا: %',f->>'label';END IF;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_asset_private.depreciate(p_cafe uuid, p_asset uuid, p_amount numeric, p_units numeric, p_date date, p_actor uuid, p_action text DEFAULT 'depreciate'::text, p_order uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE a public.erp_assets;d uuid;e uuid:=gen_random_uuid();available numeric;BEGIN
 SELECT * INTO a FROM public.erp_assets WHERE cafe_id=p_cafe AND id=p_asset FOR UPDATE;
 IF NOT FOUND OR a.status<>'in_service' OR p_date<(a.payload->>'inServiceOn')::date THEN RAISE EXCEPTION 'الأصل غير متاح للإهلاك في هذا التاريخ';END IF;
 available:=a.gross_value-a.accumulated_depreciation-round(a.residual_value*a.remaining_quantity/a.quantity,2);
 IF p_amount IS NULL OR p_amount<=0 OR p_amount<>round(p_amount,2) OR p_amount>available OR p_units<0 THEN RAISE EXCEPTION 'الإهلاك يتجاوز القيمة القابلة للإهلاك';END IF;
 PERFORM erp_asset_private.account(p_cafe,(a.payload->>'expenseAccountId')::uuid,ARRAY['expense']);PERFORM erp_asset_private.account(p_cafe,(a.payload->>'accumulatedAccountId')::uuid,ARRAY['accumulated_depreciation']);
 d:=erp_asset_private.document(p_cafe,p_date,p_amount,'إهلاك الأصل '||a.code,p_actor);
 PERFORM erp_asset_private.line(p_cafe,d,(a.payload->>'expenseAccountId')::uuid,p_amount,0);PERFORM erp_asset_private.line(p_cafe,d,(a.payload->>'accumulatedAccountId')::uuid,0,p_amount);
 UPDATE public.erp_assets SET accumulated_depreciation=accumulated_depreciation+p_amount,consumed_units=consumed_units+p_units,revision=revision+1,updated_at=now() WHERE id=p_asset AND cafe_id=p_cafe;
 INSERT INTO public.erp_asset_events(id,cafe_id,asset_id,action,effective_on,amount,quantity,document_id,manufacturing_order_id,created_by) VALUES(e,p_cafe,p_asset,p_action,p_date,p_amount,p_units,d,p_order,p_actor);RETURN e;
END $function$

CREATE OR REPLACE FUNCTION erp_asset_private.manufacturing_depreciation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE row record;dated date;BEGIN
 IF NEW.status='completed' AND OLD.status<>'completed' THEN
  SELECT (created_at AT TIME ZONE 'Asia/Riyadh')::date INTO dated FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.output_document_id;
  FOR row IN SELECT w.asset_id,sum((op->>'quantity')::numeric*(w.payload->>'assetsCost')::numeric) amount,sum((op->>'quantity')::numeric) units FROM jsonb_array_elements(NEW.payload->'operations') op JOIN public.erp_mfg_workstations w ON w.cafe_id=NEW.cafe_id AND w.id=(op->>'workstationId')::uuid WHERE w.asset_id IS NOT NULL AND w.payload->>'autoDepreciate'='true' GROUP BY w.asset_id LOOP
   PERFORM erp_asset_private.depreciate(NEW.cafe_id,row.asset_id,round(row.amount,2),row.units,dated,auth.uid(),'manufacturing_depreciation',NEW.id);
  END LOOP;
 ELSIF OLD.status='completed' AND NEW.status='in_progress' THEN
  FOR row IN SELECT id FROM public.erp_asset_events e WHERE cafe_id=NEW.cafe_id AND manufacturing_order_id=NEW.id AND action='manufacturing_depreciation' AND NOT EXISTS(SELECT 1 FROM public.erp_asset_events r WHERE r.cafe_id=e.cafe_id AND r.reversal_of=e.id) LOOP
   PERFORM erp_asset_private.reverse_depreciation(NEW.cafe_id,row.id,(now() AT TIME ZONE 'Asia/Riyadh')::date,auth.uid());
  END LOOP;
 END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_asset_private.reverse_depreciation(p_cafe uuid, p_event uuid, p_date date, p_actor uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE e public.erp_asset_events;a public.erp_assets;d uuid;line record;rid uuid:=gen_random_uuid();BEGIN
 SELECT * INTO e FROM public.erp_asset_events WHERE cafe_id=p_cafe AND id=p_event;
 IF NOT FOUND OR e.action NOT IN('depreciate','scheduled_depreciation','manufacturing_depreciation') OR EXISTS(SELECT 1 FROM public.erp_asset_events WHERE cafe_id=p_cafe AND reversal_of=p_event) THEN RAISE EXCEPTION 'حركة الإهلاك غير قابلة للعكس';END IF;
 SELECT * INTO a FROM public.erp_assets WHERE cafe_id=p_cafe AND id=e.asset_id FOR UPDATE;
 IF a.status<>'in_service' OR a.accumulated_depreciation<e.amount OR p_date<e.effective_on OR EXISTS(SELECT 1 FROM public.erp_asset_events x WHERE x.cafe_id=p_cafe AND x.asset_id=a.id AND x.action IN('sell','write_off') AND x.created_at>e.created_at) THEN RAISE EXCEPTION 'لا يمكن عكس الإهلاك بعد الاستبعاد أو قبل تاريخه';END IF;
 d:=erp_asset_private.document(p_cafe,p_date,e.amount,'عكس إهلاك الأصل '||a.code,p_actor);
 FOR line IN SELECT * FROM public.bf_journal WHERE cafe_id=p_cafe AND document_id=e.document_id LOOP PERFORM erp_asset_private.line(p_cafe,d,line.account_id,line.credit,line.debit);END LOOP;
 UPDATE public.erp_assets SET accumulated_depreciation=accumulated_depreciation-e.amount,consumed_units=greatest(0,consumed_units-e.quantity),revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe AND id=a.id;
 INSERT INTO public.erp_asset_events(id,cafe_id,asset_id,action,effective_on,amount,quantity,document_id,reversal_of,manufacturing_order_id,created_by) VALUES(rid,p_cafe,a.id,'reverse_depreciation',p_date,e.amount,e.quantity,d,e.id,e.manufacturing_order_id,p_actor);RETURN rid;
END $function$

CREATE OR REPLACE FUNCTION erp_asset_private.run_automatic()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE branch_prior jsonb;row record;prior text:=current_setting('request.jwt.claim.sub',true);processed integer:=0;BEGIN
 FOR row IN SELECT a.id,a.cafe_id,a.revision,c.owner_user_id FROM public.erp_assets a JOIN public.cafes c ON c.id=a.cafe_id JOIN public.profiles p ON p.id=c.owner_user_id AND p.status='active' WHERE a.status='in_service' AND a.payload->>'autoEnabled'='true' AND a.next_depreciation_on<=(now() AT TIME ZONE 'Asia/Riyadh')::date AND a.gross_value-a.accumulated_depreciation>round(a.residual_value*a.remaining_quantity/a.quantity,2) ORDER BY a.next_depreciation_on,a.id LIMIT 100 LOOP
  BEGIN
   PERFORM set_config('request.jwt.claim.sub',row.owner_user_id::text,true);
   branch_prior:=erp_branch_private.enter_job(row.cafe_id,'erp_assets',row.id,row.owner_user_id);PERFORM public.erp_asset_act(row.cafe_id,jsonb_build_object('action','run_due','id',row.id,'revision',row.revision,'requestId',gen_random_uuid(),'date',(now() AT TIME ZONE 'Asia/Riyadh')::date));PERFORM erp_branch_private.exit_job(branch_prior);processed:=processed+1;
  EXCEPTION WHEN OTHERS THEN
   INSERT INTO public.erp_asset_events(cafe_id,asset_id,action,effective_on,note,created_by) VALUES(row.cafe_id,row.id,'automation_failed',(now() AT TIME ZONE 'Asia/Riyadh')::date,'تعذر ترحيل الإهلاك الدوري راجع الفترة المالية وصلاحيات الحسابات',row.owner_user_id);
  END;
 END LOOP;
 PERFORM set_config('request.jwt.claim.sub',coalesce(prior,''),true);RETURN processed;
END $function$

CREATE OR REPLACE FUNCTION erp_asset_private.validate(p_cafe uuid, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE x jsonb;n numeric;qty integer;BEGIN
 IF coalesce(jsonb_typeof(p),'')<>'object' OR octet_length(p::text)>524288 OR length(btrim(coalesce(p->>'name',''))) NOT BETWEEN 1 AND 150 OR length(btrim(coalesce(p->>'code',''))) NOT BETWEEN 1 AND 60 OR length(coalesce(p->>'description',''))>4000 THEN RAISE EXCEPTION 'بيانات الأصل غير صالحة';END IF;
 qty:=erp_manufacturing_private.money(p->'quantity');IF qty NOT BETWEEN 1 AND 500 OR qty::numeric<>(p->>'quantity')::numeric THEN RAISE EXCEPTION 'كمية الأصل غير صالحة';END IF;
 n:=erp_manufacturing_private.money(p->'unitCost')*qty;IF n<=0 OR erp_manufacturing_private.money(p->'residualValue')>=n THEN RAISE EXCEPTION 'راجع سعر الشراء وقيمة الخردة';END IF;
 IF (p->>'usefulLifeMonths')::integer NOT BETWEEN 1 AND 1200 OR (p->>'intervalMonths')::integer NOT BETWEEN 1 AND 120 OR coalesce(p->>'method','') NOT IN('none','straight_line','declining','units') THEN RAISE EXCEPTION 'إعدادات الإهلاك غير صالحة';END IF;
 PERFORM erp_manufacturing_private.money(p->'depreciationAmount');PERFORM erp_manufacturing_private.money(p->'totalUnits');
 IF coalesce(jsonb_typeof(p->'autoEnabled'),'boolean')<>'boolean' OR (p->>'method'='declining' AND (coalesce((p->>'depreciationRate')::numeric,0)<=0 OR (p->>'depreciationRate')::numeric>100)) THEN RAISE EXCEPTION 'نسبة الإهلاك أو تفعيل الجدولة غير صالح';END IF;
 IF p->>'method'='straight_line' AND (p->>'depreciationAmount')::numeric<=0 OR p->>'method'='units' AND (p->>'totalUnits')::numeric<=0 THEN RAISE EXCEPTION 'أدخل قيمة الإهلاك أو الوحدات المتوقعة';END IF;
 IF coalesce(p->>'acquiredOn','')='' OR coalesce(p->>'inServiceOn','')='' OR coalesce(p->>'depreciationStarts','')='' OR (p->>'inServiceOn')::date<(p->>'acquiredOn')::date OR (p->>'depreciationStarts')::date<(p->>'inServiceOn')::date THEN RAISE EXCEPTION 'تسلسل تواريخ الأصل غير صحيح';END IF;
 PERFORM erp_asset_private.account(p_cafe,(p->>'assetAccountId')::uuid,ARRAY['fixed_asset']);PERFORM erp_asset_private.account(p_cafe,(p->>'cashAccountId')::uuid,ARRAY['cash','bank','pos']);PERFORM erp_asset_private.account(p_cafe,(p->>'accumulatedAccountId')::uuid,ARRAY['accumulated_depreciation']);PERFORM erp_asset_private.account(p_cafe,(p->>'expenseAccountId')::uuid,ARRAY['expense']);
 IF coalesce(jsonb_typeof(p->'taxes'),'')<>'array' OR jsonb_array_length(p->'taxes')>1 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'taxes') tr(value) WHERE tr.value<>'vat') THEN RAISE EXCEPTION 'الضريبة غير صالحة';END IF;
 IF coalesce(jsonb_typeof(p->'units'),'')<>'array' OR jsonb_array_length(p->'units') NOT BETWEEN 1 AND 500 OR ((p->>'individualUnits')::boolean AND jsonb_array_length(p->'units')<>qty) THEN RAISE EXCEPTION 'أكمل تفاصيل الوحدات';END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p->'units') LOOP
  IF length(coalesce(x->>'serial',''))>100 OR length(coalesce(x->>'barcode',''))>100 OR length(coalesce(x->>'description',''))>1000 THEN RAISE EXCEPTION 'بيانات الوحدة طويلة';END IF;
  IF nullif(x->>'employeeId','') IS NOT NULL AND NOT erp_employee_asset_private.staff(p_cafe,(x->>'employeeId')::uuid) THEN RAISE EXCEPTION 'الموظف غير متاح';END IF;
  IF nullif(x->>'locationId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_asset_locations WHERE cafe_id=p_cafe AND id=(x->>'locationId')::uuid) THEN RAISE EXCEPTION 'الموقع غير متاح';END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_asset_private.workstation_asset()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE a public.erp_assets;rate numeric;BEGIN
 NEW.asset_id:=nullif(NEW.payload->>'assetId','')::uuid;
 IF NEW.asset_id IS NULL THEN IF coalesce((NEW.payload->>'autoDepreciate')::boolean,false) THEN RAISE EXCEPTION 'اختر الأصل للإهلاك التلقائي';END IF;RETURN NEW;END IF;
 SELECT * INTO a FROM public.erp_assets WHERE cafe_id=NEW.cafe_id AND id=NEW.asset_id;
 IF NOT FOUND OR a.status<>'in_service' THEN RAISE EXCEPTION 'الأصل غير متاح لمحطة العمل';END IF;
 IF coalesce((NEW.payload->>'autoDepreciate')::boolean,false) THEN
  rate:=CASE WHEN a.payload->>'method'='units' THEN round((a.purchase_cost-a.residual_value)/(a.payload->>'totalUnits')::numeric,6) ELSE erp_manufacturing_private.money(NEW.payload->'assetsCost') END;
  IF rate<=0 THEN RAISE EXCEPTION 'أدخل تكلفة الإهلاك لكل وحدة';END IF;
  NEW.payload:=NEW.payload||jsonb_build_object('assetsCost',rate,'assetsAccountId',a.payload->>'expenseAccountId');
 END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.approvers(p_cafe uuid, p_employee uuid, p_level jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE e public.erp_hr_employees;ids uuid[]:='{}';candidate uuid;result jsonb;BEGIN
 e:=erp_attendance_private.employee(p_cafe,p_employee);
 IF coalesce((p_level->>'directManager')::boolean,false) THEN SELECT user_id INTO candidate FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=e.manager_id AND active;IF candidate IS NOT NULL THEN ids:=array_append(ids,candidate);END IF;END IF;
 IF coalesce((p_level->>'departmentManagers')::boolean,false) THEN ids:=ids||coalesce((SELECT manager_ids FROM public.erp_org_units WHERE cafe_id=p_cafe AND id=e.department_id AND kind='department'),'{}');END IF;
 FOR candidate IN SELECT (x#>>'{}')::uuid FROM jsonb_array_elements(coalesce(p_level->'employeeIds','[]'))x LOOP SELECT user_id INTO candidate FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=candidate AND active;IF candidate IS NOT NULL THEN ids:=array_append(ids,candidate);END IF;END LOOP;
 SELECT coalesce(jsonb_agg(DISTINCT p.id),'[]') INTO result FROM public.profiles p WHERE p.id=ANY(ids) AND p.status='active' AND p.id IS DISTINCT FROM e.user_id;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.assignment(p_cafe uuid, p jsonb, p_id uuid, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE rid uuid:=coalesce(p_id,gen_random_uuid());old public.erp_att_assignments;emp uuid:=(p->>'employeeId')::uuid;primary_id uuid:=(p->>'primaryShiftId')::uuid;secondary_id uuid:=nullif(p->>'secondaryShiftId','')::uuid;policy_id uuid:=nullif(p->>'leavePolicyId','')::uuid;restriction_id uuid:=nullif(p->>'restrictionId','')::uuid;start_date date:=(p->>'effectiveFrom')::date;end_date date:=nullif(p->>'effectiveTo','')::date;BEGIN
 PERFORM erp_attendance_private.employee(p_cafe,emp);IF start_date IS NULL OR NOT isfinite(start_date) OR (end_date IS NOT NULL AND (NOT isfinite(end_date) OR end_date<start_date)) THEN RAISE EXCEPTION 'فترة التعيين غير صالحة';END IF;
 IF p_id IS NOT NULL THEN SELECT * INTO old FROM public.erp_att_assignments WHERE cafe_id=p_cafe AND id=p_id FOR UPDATE;IF NOT FOUND OR old.employee_id<>emp THEN RAISE EXCEPTION 'تعيين الموظف غير متاح' USING ERRCODE='42501';END IF;IF old.revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'تغير تعيين الموظف' USING ERRCODE='40001';END IF;END IF;
 IF p_id IS NOT NULL AND old.effective_from=start_date AND old.primary_shift_id=primary_id AND old.secondary_shift_id IS NOT DISTINCT FROM secondary_id AND old.leave_policy_id IS NOT DISTINCT FROM policy_id AND old.restriction_id IS NOT DISTINCT FROM restriction_id THEN
  IF old.effective_to IS DISTINCT FROM end_date THEN PERFORM erp_attendance_private.period_open(p_cafe,emp,least(coalesce(old.effective_to,'infinity'),coalesce(end_date,'infinity'))+1,greatest(coalesce(old.effective_to,'infinity'),coalesce(end_date,'infinity')));END IF;
 ELSE
  IF p_id IS NOT NULL THEN PERFORM erp_attendance_private.period_open(p_cafe,emp,old.effective_from,coalesce(old.effective_to,'infinity'));END IF;
  PERFORM erp_attendance_private.period_open(p_cafe,emp,start_date,coalesce(end_date,'infinity'));
 END IF;
 IF EXISTS(SELECT 1 FROM public.erp_att_assignments WHERE cafe_id=p_cafe AND employee_id=emp AND id<>rid AND effective_from<=coalesce(end_date,'infinity') AND coalesce(effective_to,'infinity')>=start_date) THEN RAISE EXCEPTION 'فترة التعيين تتداخل مع تعيين سابق حدد نهاية الفترة السابقة';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.erp_att_shifts WHERE cafe_id=p_cafe AND id=primary_id AND active) OR (secondary_id IS NOT NULL AND (NOT coalesce((erp_attendance_private.settings(p_cafe)->>'secondaryShift')::boolean,false) OR secondary_id=primary_id OR NOT EXISTS(SELECT 1 FROM public.erp_att_shifts WHERE cafe_id=p_cafe AND id=secondary_id AND active))) THEN RAISE EXCEPTION 'اختر ورديات نشطة مختلفة وفعّل الوردية الثانية عند الحاجة';END IF;
 IF policy_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_att_policies WHERE cafe_id=p_cafe AND id=policy_id AND active) THEN RAISE EXCEPTION 'سياسة الإجازات غير متاحة';END IF;IF restriction_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_att_restrictions WHERE cafe_id=p_cafe AND id=restriction_id AND active) THEN RAISE EXCEPTION 'محدد الحضور غير متاح';END IF;
 PERFORM erp_attendance_private.compatible_shifts(p_cafe,primary_id,secondary_id);
 INSERT INTO public.erp_att_assignments(id,cafe_id,employee_id,primary_shift_id,secondary_shift_id,leave_policy_id,restriction_id,effective_from,effective_to) VALUES(rid,p_cafe,emp,primary_id,secondary_id,policy_id,restriction_id,start_date,end_date) ON CONFLICT(id) DO UPDATE SET primary_shift_id=excluded.primary_shift_id,secondary_shift_id=excluded.secondary_shift_id,leave_policy_id=excluded.leave_policy_id,restriction_id=excluded.restriction_id,effective_from=excluded.effective_from,effective_to=excluded.effective_to,revision=public.erp_att_assignments.revision+1;
 RETURN jsonb_build_object('id',rid);
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.authorize(p_cafe uuid, p_write boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ DECLARE r text;BEGIN
 r:=brand_finance_private.role_for(p_cafe);IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND status='active') THEN RAISE EXCEPTION 'سجل الدخول بحساب نشط' USING ERRCODE='42501';END IF;
 IF NOT coalesce(r IN('owner','manager','accountant','auditor'),false) THEN IF p_write OR NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND user_id=auth.uid() AND active) THEN RAISE EXCEPTION 'لا تملك صلاحية الحضور' USING ERRCODE='42501';END IF;RETURN 'self';END IF;
