CREATE OR REPLACE FUNCTION erp_attendance_private.balance(p_cafe uuid, p_employee uuid, p_type uuid, p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE fiscal date:=erp_attendance_private.fiscal_start(p_cafe,p_employee,p_date);a public.erp_att_assignments;p jsonb;t jsonb;annual numeric:=0;used numeric:=0;joined date;nextyear date;BEGIN
 SELECT * INTO a FROM public.erp_att_assignments WHERE cafe_id=p_cafe AND employee_id=p_employee AND effective_from<=p_date AND coalesce(effective_to,'infinity')>=p_date ORDER BY effective_from DESC LIMIT 1;
 SELECT payload INTO p FROM public.erp_att_policies WHERE cafe_id=p_cafe AND id=a.leave_policy_id;SELECT x INTO t FROM jsonb_array_elements(coalesce(p->'types','[]'))x WHERE x->>'typeId'=p_type::text;annual:=coalesce((t->>'annualDays')::numeric,0);
 nextyear:=erp_attendance_private.fiscal_start(p_cafe,p_employee,(fiscal+interval '1 year 2 days')::date);IF nextyear<=fiscal THEN nextyear:=(fiscal+interval '1 year')::date;END IF;
 IF coalesce((t->>'prorate')::boolean,false) THEN SELECT (payload->>'joinDate')::date INTO joined FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=p_employee;IF joined>fiscal THEN annual:=round(annual*greatest(0,nextyear-joined)/greatest(1,nextyear-fiscal),2);END IF;END IF;
 SELECT coalesce(sum(amount),0) INTO used FROM public.erp_att_balances WHERE cafe_id=p_cafe AND employee_id=p_employee AND leave_type_id=p_type AND fiscal_start=fiscal;
 RETURN jsonb_build_object('fiscalStart',fiscal,'annual',annual,'movements',used,'available',annual+used,'carryLimit',coalesce((t->>'carryLimit')::numeric,0),'includeWeekends',coalesce((t->>'includeWeekends')::boolean,false));
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.calculate_day(p_cafe uuid, p_employee uuid, p_date date, p_slot integer DEFAULT 0, p_override boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE assignment public.erp_att_assignments;old public.erp_att_days;shift public.erp_att_shifts;settings jsonb:=erp_attendance_private.settings(p_cafe);shift_id uuid;spec jsonb;win jsonb;enter timestamptz;leaving timestamptz;scheduled integer;worked integer:=0;late integer:=0;early integer:=0;overtime integer:=0;leave_minutes integer:=0;late_permission integer:=0;early_permission integer:=0;leave_fraction numeric:=0;state text;rid uuid;flags jsonb:='[]';flag public.erp_att_flags;values jsonb;amount numeric;log_ids jsonb;leave_ids jsonb;BEGIN
 PERFORM erp_attendance_private.employee(p_cafe,p_employee);IF p_slot NOT IN(0,1) THEN RAISE EXCEPTION 'فترة الوردية غير صالحة';END IF;
 SELECT * INTO old FROM public.erp_att_days WHERE cafe_id=p_cafe AND employee_id=p_employee AND work_date=p_date AND slot=p_slot FOR UPDATE;
 IF FOUND AND old.source='manual' AND NOT p_override THEN RETURN jsonb_build_object('skipped','manual','id',old.id);END IF;
 IF EXISTS(SELECT 1 FROM public.erp_att_sheets s WHERE s.cafe_id=p_cafe AND s.status='approved' AND s.payload->'employeeIds'?p_employee::text AND p_date BETWEEN s.from_date AND s.to_date) THEN RETURN jsonb_build_object('skipped','approved','id',old.id);END IF;
 SELECT * INTO assignment FROM public.erp_att_assignments WHERE cafe_id=p_cafe AND employee_id=p_employee AND effective_from<=p_date AND coalesce(effective_to,'infinity')>=p_date ORDER BY effective_from DESC LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('skipped','unassigned');END IF;
 IF p_slot=1 THEN IF assignment.secondary_shift_id IS NULL THEN RETURN jsonb_build_object('skipped','secondary_disabled');END IF;shift_id:=assignment.secondary_shift_id;
 ELSE SELECT a.shift_id INTO shift_id FROM public.erp_att_allocations a JOIN public.erp_att_allocation_employees e ON e.cafe_id=a.cafe_id AND e.allocation_id=a.id WHERE e.cafe_id=p_cafe AND e.employee_id=p_employee AND p_date BETWEEN a.from_date AND a.to_date ORDER BY a.from_date DESC LIMIT 1;shift_id:=coalesce(shift_id,assignment.primary_shift_id);END IF;
 PERFORM erp_attendance_private.compatible_shifts(p_cafe,CASE WHEN p_slot=0 THEN shift_id ELSE coalesce((SELECT al.shift_id FROM public.erp_att_allocations al JOIN public.erp_att_allocation_employees ae ON ae.cafe_id=al.cafe_id AND ae.allocation_id=al.id WHERE ae.cafe_id=p_cafe AND ae.employee_id=p_employee AND p_date BETWEEN al.from_date AND al.to_date LIMIT 1),assignment.primary_shift_id) END,assignment.secondary_shift_id);
 SELECT * INTO shift FROM public.erp_att_shifts WHERE cafe_id=p_cafe AND id=shift_id;SELECT x INTO spec FROM jsonb_array_elements(shift.payload->'days')x WHERE (x->>'weekday')::integer=extract(dow FROM p_date)::integer;
 IF spec IS NULL THEN RAISE EXCEPTION 'أوقات الوردية غير مكتملة';END IF;win:=erp_attendance_private.window(spec,p_date,settings->>'timezone');scheduled:=(win->>'duration')::integer;
 SELECT min(occurred_at) INTO enter FROM public.erp_att_logs WHERE cafe_id=p_cafe AND employee_id=p_employee AND NOT voided AND direction='in' AND occurred_at BETWEEN (win->>'inFrom')::timestamptz AND (win->>'inTo')::timestamptz;
 SELECT max(occurred_at) INTO leaving FROM public.erp_att_logs WHERE cafe_id=p_cafe AND employee_id=p_employee AND NOT voided AND direction='out' AND occurred_at BETWEEN (win->>'outFrom')::timestamptz AND (win->>'outTo')::timestamptz;
 SELECT coalesce(sum(CASE permission_type WHEN 'leave' THEN 1 WHEN 'half_leave' THEN 0.5 ELSE 0 END),0),coalesce(sum(minutes) FILTER(WHERE permission_type='delay'),0),coalesce(sum(minutes) FILTER(WHERE permission_type='early'),0),coalesce(jsonb_agg(id),'[]') INTO leave_fraction,late_permission,early_permission,leave_ids FROM public.erp_att_leaves WHERE cafe_id=p_cafe AND employee_id=p_employee AND status='approved' AND p_date BETWEEN from_date AND to_date;
 leave_fraction:=least(1,leave_fraction);leave_minutes:=round(scheduled*leave_fraction);late_permission:=least(late_permission,scheduled);early_permission:=least(early_permission,scheduled);
 IF NOT (win->>'working')::boolean AND NOT (win->>'workOnHoliday')::boolean THEN state:='holiday';scheduled:=0;leave_minutes:=0;enter:=null;leaving:=null;
 ELSIF leave_fraction=1 AND NOT (settings->>'logDuringLeave')::boolean THEN state:='leave';enter:=null;leaving:=null;
 ELSE
  IF enter IS NOT NULL AND leaving IS NOT NULL AND leaving>=enter THEN worked:=greatest(0,floor(extract(epoch FROM leaving-enter)/60)::integer-(win->>'breakMinutes')::integer);state:='present';
  ELSIF enter IS NOT NULL OR leaving IS NOT NULL THEN state:='partial';ELSE state:=CASE WHEN leave_fraction>0 THEN 'leave' ELSE 'absent' END;END IF;
  IF enter IS NOT NULL THEN late:=greatest(0,ceil(extract(epoch FROM enter-(win->>'start')::timestamptz)/60)::integer);IF late<=(win->>'grace')::integer THEN late:=0;ELSIF NOT (win->>'lateFromStart')::boolean THEN late:=late-(win->>'grace')::integer;END IF;late:=greatest(0,late-late_permission);END IF;
  IF leaving IS NOT NULL THEN early:=greatest(0,ceil(extract(epoch FROM (win->>'end')::timestamptz-leaving)/60)::integer-early_permission);END IF;
  overtime:=greatest(0,worked-scheduled);IF NOT (win->>'working')::boolean THEN scheduled:=0;overtime:=worked;END IF;
 END IF;
 values:=jsonb_build_object('worked',worked,'scheduled',scheduled,'late',late,'early',early,'overtime',overtime,'absent',CASE WHEN state='absent' THEN 1 ELSE 0 END,'leave',leave_minutes,'holiday',CASE WHEN NOT (win->>'working')::boolean THEN 1 ELSE 0 END);
 FOR flag IN SELECT * FROM public.erp_att_flags f WHERE cafe_id=p_cafe AND active AND (jsonb_array_length(coalesce(payload->'shiftIds','[]'))=0 OR payload->'shiftIds'?shift_id::text) ORDER BY name LOOP
  IF erp_attendance_private.evaluate(flag.condition_ast,values)<>0 THEN amount:=erp_attendance_private.evaluate(flag.formula_ast,values);flags:=flags||jsonb_build_array(jsonb_build_object('id',flag.id,'name',flag.name,'value',amount,'revision',flag.revision,'color',flag.payload->>'color'));END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(id ORDER BY occurred_at),'[]') INTO log_ids FROM public.erp_att_logs WHERE cafe_id=p_cafe AND employee_id=p_employee AND NOT voided AND occurred_at BETWEEN (win->>'inFrom')::timestamptz AND (win->>'outTo')::timestamptz;
 rid:=coalesce(old.id,gen_random_uuid());INSERT INTO public.erp_att_days(id,cafe_id,employee_id,work_date,slot,shift_id,source,status,check_in,check_out,scheduled_minutes,worked_minutes,late_minutes,early_minutes,overtime_minutes,leave_minutes,flags,snapshot) VALUES(rid,p_cafe,p_employee,p_date,p_slot,shift_id,'calculated',state,enter,leaving,scheduled,worked,late,early,overtime,leave_minutes,flags,jsonb_build_object('window',win,'timezone',settings->>'timezone','shiftRevision',shift.revision,'logIds',log_ids,'leaveIds',leave_ids))
 ON CONFLICT(cafe_id,employee_id,work_date,slot) DO UPDATE SET shift_id=excluded.shift_id,source='calculated',status=excluded.status,check_in=excluded.check_in,check_out=excluded.check_out,scheduled_minutes=excluded.scheduled_minutes,worked_minutes=excluded.worked_minutes,late_minutes=excluded.late_minutes,early_minutes=excluded.early_minutes,overtime_minutes=excluded.overtime_minutes,leave_minutes=excluded.leave_minutes,flags=excluded.flags,snapshot=excluded.snapshot,revision=public.erp_att_days.revision+1,calculated_at=now();
 RETURN jsonb_build_object('id',rid,'status',state);
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.capabilities(p_cafe uuid, p_role text, p_own boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE action text;allowed boolean;result jsonb:='{}';key text;manage boolean:=p_role IN('owner','manager');BEGIN
 FOREACH action IN ARRAY ARRAY['create','update','delete','approve','settings','files'] LOOP
  allowed:=CASE WHEN action='settings' THEN p_role='owner' ELSE manage OR p_own END;
  IF allowed AND to_regprocedure('erp_access_private.allowed(uuid,text,text)') IS NOT NULL THEN EXECUTE 'SELECT erp_access_private.allowed($1,''attendance'',$2)' INTO allowed USING p_cafe,action;END IF;
  key:=CASE action WHEN 'create' THEN 'canCreate' WHEN 'update' THEN 'canUpdate' WHEN 'delete' THEN 'canDelete' WHEN 'approve' THEN 'canApprove' WHEN 'settings' THEN 'canSettings' ELSE 'canFiles' END;
  result:=jsonb_set(result,ARRAY[key],to_jsonb(allowed));
 END LOOP;
 RETURN result||jsonb_build_object('canWrite',manage AND ((result->>'canCreate')::boolean OR (result->>'canUpdate')::boolean OR (result->>'canDelete')::boolean OR (result->>'canApprove')::boolean));
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.check_restrictions(p_cafe uuid, p_employee uuid, p_session uuid, p_input jsonb, p_proof uuid, p_photo uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE proof erp_attendance_private.proofs;setting jsonb:=erp_attendance_private.settings(p_cafe);today date:=(now() AT TIME ZONE(setting->>'timezone'))::date;restriction jsonb;loc jsonb;ip_ok boolean:=false;location_ok boolean:=false;photo_ok boolean:=false;latitude double precision;longitude double precision;accuracy numeric;distance double precision;BEGIN
 SELECT * INTO proof FROM erp_attendance_private.proofs WHERE id=p_proof AND cafe_id=p_cafe AND actor=auth.uid() AND session_id=p_session AND used_at IS NULL AND expires_at>=now() FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'انتهت صلاحية إثبات التوقيع أعد المحاولة';END IF;
 SELECT r.payload INTO restriction FROM public.erp_att_assignments a JOIN public.erp_att_restrictions r ON r.cafe_id=a.cafe_id AND r.id=a.restriction_id AND r.active WHERE a.cafe_id=p_cafe AND a.employee_id=p_employee AND a.effective_from<=today AND coalesce(a.effective_to,'infinity')>=today ORDER BY a.effective_from DESC LIMIT 1;
 IF coalesce((restriction->>'useIp')::boolean,false) THEN SELECT coalesce(bool_or(proof.ip<<=(x#>>'{}')::inet),false) INTO ip_ok FROM jsonb_array_elements(restriction->'ips')x;IF (restriction->>'ipRequired')::boolean AND NOT ip_ok THEN RAISE EXCEPTION 'تعذر تأكيد شبكة حضور مسموحة';END IF;END IF;
 IF p_input->'latitude' IS NOT NULL AND jsonb_typeof(p_input->'latitude')<>'null' THEN latitude:=(p_input->>'latitude')::double precision;longitude:=(p_input->>'longitude')::double precision;accuracy:=(p_input->>'accuracy')::numeric;IF latitude NOT BETWEEN -90 AND 90 OR longitude NOT BETWEEN -180 AND 180 OR accuracy<0 OR accuracy>100000 THEN RAISE EXCEPTION 'إحداثيات التوقيع غير صالحة';END IF;END IF;
 IF coalesce((restriction->>'useLocation')::boolean,false) THEN
  IF latitude IS NOT NULL AND longitude IS NOT NULL AND accuracy IS NOT NULL THEN FOR loc IN SELECT * FROM jsonb_array_elements(restriction->'locations') LOOP distance:=6371000*acos(least(1.0,greatest(-1.0,sin(radians(latitude))*sin(radians((loc->>'lat')::double precision))+cos(radians(latitude))*cos(radians((loc->>'lat')::double precision))*cos(radians(longitude-(loc->>'lng')::double precision)))));IF distance+accuracy<=(loc->>'radius')::numeric THEN location_ok:=true;END IF;END LOOP;END IF;
  IF (restriction->>'locationRequired')::boolean AND NOT location_ok THEN RAISE EXCEPTION 'الموقع خارج نطاق الحضور أو دقة الموقع غير كافية';END IF;
 END IF;
 IF p_photo IS NOT NULL THEN PERFORM 1 FROM public.erp_files f WHERE f.id=p_photo AND f.cafe_id=p_cafe AND f.entity_type='attendance_session' AND f.record_id=p_session AND f.uploaded AND f.mime IN('image/jpeg','image/png') AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='erp-record-files' AND o.name=f.path) FOR KEY SHARE OF f;photo_ok:=FOUND;IF NOT photo_ok THEN RAISE EXCEPTION 'صورة إثبات التوقيع غير متاحة';END IF;END IF;
 IF coalesce((restriction->>'useCamera')::boolean,false) AND (restriction->>'cameraRequired')::boolean AND NOT photo_ok THEN RAISE EXCEPTION 'أرفق صورة إثبات الحضور قبل التوقيع';END IF;
 UPDATE erp_attendance_private.proofs SET used_at=now() WHERE id=p_proof;
 RETURN jsonb_build_object('ipMatched',ip_ok,'ipAvailable',proof.ip IS NOT NULL,'locationMatched',location_ok,'photoMatched',photo_ok,'latitude',latitude,'longitude',longitude,'accuracy',accuracy,'checkedAt',now());
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.compatible_shifts(p_cafe uuid, p_primary uuid, p_secondary uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE a jsonb;b jsonb;wa jsonb;wb jsonb;d integer;offset_day integer;reference date:='2026-11-01';first_rules jsonb;second_rules jsonb;BEGIN
 IF p_secondary IS NULL THEN RETURN;END IF;
 SELECT payload->'days' INTO first_rules FROM public.erp_att_shifts WHERE cafe_id=p_cafe AND id=p_primary;
 SELECT payload->'days' INTO second_rules FROM public.erp_att_shifts WHERE cafe_id=p_cafe AND id=p_secondary;
 FOR d IN 0..6 LOOP
  SELECT value INTO a FROM jsonb_array_elements(first_rules) WHERE (value->>'weekday')::integer=d;
  IF NOT coalesce((a->>'working')::boolean,false) AND NOT coalesce((a->>'workOnHoliday')::boolean,false) THEN CONTINUE;END IF;
  wa:=erp_attendance_private.window(a,reference+d,'Asia/Riyadh');
  FOR offset_day IN -1..1 LOOP
   SELECT value INTO b FROM jsonb_array_elements(second_rules) WHERE (value->>'weekday')::integer=mod(d+offset_day+7,7);
   IF NOT coalesce((b->>'working')::boolean,false) AND NOT coalesce((b->>'workOnHoliday')::boolean,false) THEN CONTINUE;END IF;
   wb:=erp_attendance_private.window(b,reference+d+offset_day,'Asia/Riyadh');
   IF (wa->>'start')::timestamptz<(wb->>'end')::timestamptz AND (wb->>'start')::timestamptz<(wa->>'end')::timestamptz
    OR (wa->>'inFrom')::timestamptz<=(wb->>'inTo')::timestamptz AND (wb->>'inFrom')::timestamptz<=(wa->>'inTo')::timestamptz
    OR (wa->>'outFrom')::timestamptz<=(wb->>'outTo')::timestamptz AND (wb->>'outFrom')::timestamptz<=(wa->>'outTo')::timestamptz THEN RAISE EXCEPTION 'تتداخل الورديتان أو نوافذ تسجيلهما بما قد يكرر احتساب الحضور';END IF;
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.consume_settlement(p_cafe uuid, p_employee uuid, p_settlement uuid, p_payroll_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE a public.erp_att_settlements;BEGIN IF p_payroll_run IS NULL THEN RAISE EXCEPTION 'مرجع مسير المرتبات مطلوب';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));SELECT * INTO a FROM public.erp_att_settlements WHERE cafe_id=p_cafe AND employee_id=p_employee AND id=p_settlement FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'تسوية الموظف غير متاحة' USING ERRCODE='42501';END IF;
