 UPDATE public.erp_att_settlements SET status='consumed',payroll_run_id=p_payroll_run,revision=revision+1 WHERE cafe_id=p_cafe AND id=a.id;INSERT INTO public.erp_att_events(cafe_id,record_id,action,detail,actor) VALUES(p_cafe,a.id,'payroll_settlement',jsonb_build_object('payrollRunId',p_payroll_run,'days',a.days),auth.uid());RETURN jsonb_build_object('id',a.id,'days',a.days,'leaveTypeId',a.leave_type_id);
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.evaluate(p jsonb, v jsonb, p_depth integer DEFAULT 0)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE a numeric;b numeric;r numeric;op text;kind text:=p->>'type';BEGIN
 IF p_depth>24 OR octet_length(p::text)>20000 THEN RAISE EXCEPTION 'الصيغة معقدة أكثر من المسموح';END IF;
 IF kind='number' THEN r:=(p->>'value')::numeric;
 ELSIF kind='variable' THEN IF NOT coalesce(p->>'name'=ANY(ARRAY['worked','scheduled','late','early','overtime','absent','leave','holiday']),false) THEN RAISE EXCEPTION 'متغير غير مسموح في قاعدة الحضور';END IF;r:=coalesce((v->>(p->>'name'))::numeric,0);
 ELSIF kind='unary' THEN a:=erp_attendance_private.evaluate(p->'value',v,p_depth+1);op:=p->>'operator';CASE op WHEN '-' THEN r:=-a;WHEN '+' THEN r:=a;WHEN '!' THEN r:=CASE WHEN a=0 THEN 1 ELSE 0 END;ELSE RAISE EXCEPTION 'معامل غير مسموح';END CASE;
 ELSIF kind='binary' THEN a:=erp_attendance_private.evaluate(p->'left',v,p_depth+1);op:=p->>'operator';IF op='&&' AND a=0 THEN RETURN 0;ELSIF op='||' AND a<>0 THEN RETURN 1;END IF;b:=erp_attendance_private.evaluate(p->'right',v,p_depth+1);CASE op WHEN '+' THEN r:=a+b;WHEN '-' THEN r:=a-b;WHEN '*' THEN r:=a*b;WHEN '/' THEN IF b=0 THEN RAISE EXCEPTION 'قسمة على صفر في قاعدة الحضور';END IF;r:=a/b;WHEN '%' THEN IF b=0 THEN RAISE EXCEPTION 'باقي قسمة على صفر';END IF;r:=mod(a,b);WHEN '>' THEN r:=(a>b)::integer;WHEN '<' THEN r:=(a<b)::integer;WHEN '>=' THEN r:=(a>=b)::integer;WHEN '<=' THEN r:=(a<=b)::integer;WHEN '==' THEN r:=(a=b)::integer;WHEN '!=' THEN r:=(a<>b)::integer;WHEN '&&' THEN r:=(a<>0 AND b<>0)::integer;WHEN '||' THEN r:=(a<>0 OR b<>0)::integer;ELSE RAISE EXCEPTION 'معامل غير مسموح';END CASE;
 ELSIF kind='call' THEN op:=p->>'name';IF jsonb_array_length(p->'args')<>(CASE WHEN op IN('min','max') THEN 2 ELSE 1 END) THEN RAISE EXCEPTION 'عدد معاملات الدالة غير صحيح';END IF;a:=erp_attendance_private.evaluate(p->'args'->0,v,p_depth+1);IF op IN('min','max') THEN b:=erp_attendance_private.evaluate(p->'args'->1,v,p_depth+1);END IF;CASE op WHEN 'min' THEN r:=least(a,b);WHEN 'max' THEN r:=greatest(a,b);WHEN 'abs' THEN r:=abs(a);WHEN 'floor' THEN r:=floor(a);WHEN 'ceil' THEN r:=ceil(a);WHEN 'round' THEN r:=floor(a+0.5);ELSE RAISE EXCEPTION 'دالة غير مسموحة';END CASE;
 ELSE RAISE EXCEPTION 'صيغة قاعدة الحضور غير صالحة';END IF;
 IF r IS NULL OR r='NaN'::numeric OR abs(r)>1000000000 THEN RAISE EXCEPTION 'نتيجة قاعدة الحضور خارج الحدود المسموحة';END IF;RETURN r;
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.leave_action(p_cafe uuid, p_action text, p_data jsonb, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE rid uuid:=nullif(p_data->>'id','')::uuid;rev integer:=(p_data->>'revision')::integer;p jsonb:=coalesce(p_data->'payload',p_data);a public.erp_att_leaves;e public.erp_hr_employees;settings jsonb:=erp_attendance_private.settings(p_cafe);rule public.erp_att_approvals;levels jsonb:='[]';level jsonb;users jsonb;units jsonb;fiscal text;quantity numeric;balance jsonb;permission text;emp uuid;type_id uuid;start_date date;end_date date;dated date;note text:=coalesce(p->>'note','');next_level integer;index integer;candidate integer:=-1;BEGIN
 IF rid IS NOT NULL THEN SELECT * INTO a FROM public.erp_att_leaves WHERE cafe_id=p_cafe AND id=rid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'طلب الإجازة غير متاح' USING ERRCODE='42501';END IF;IF a.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'تغير طلب الإجازة' USING ERRCODE='40001';END IF;e:=erp_attendance_private.employee(p_cafe,a.employee_id);
 ELSE e:=erp_attendance_private.employee(p_cafe,(p->>'employeeId')::uuid);END IF;
 IF p_action NOT IN('approve_leave','reject_leave') AND p_role NOT IN('owner','manager') AND e.user_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'لا تملك صلاحية طلب هذا الموظف' USING ERRCODE='42501';END IF;
 IF p_action='save_leave' THEN
  IF rid IS NOT NULL AND a.status<>'draft' THEN RAISE EXCEPTION 'يمكن تعديل مسودة الإجازة فقط';END IF;
  emp:=(p->>'employeeId')::uuid;IF emp<>e.id THEN RAISE EXCEPTION 'لا تغير موظف طلب الإجازة';END IF;permission:=p->>'type';type_id:=nullif(p->>'leaveTypeId','')::uuid;start_date:=(p->>'from')::date;end_date:=(p->>'to')::date;
  IF start_date IS NULL OR end_date IS NULL OR NOT isfinite(start_date) OR NOT isfinite(end_date) OR end_date<start_date OR end_date-start_date>366 OR permission NOT IN('leave','half_leave','delay','early') OR length(coalesce(p->>'description',''))>10000 THEN RAISE EXCEPTION 'بيانات طلب الإجازة غير صالحة';END IF;
  IF permission IN('leave','half_leave') THEN IF NOT EXISTS(SELECT 1 FROM public.erp_att_leave_types WHERE cafe_id=p_cafe AND id=type_id AND active) THEN RAISE EXCEPTION 'اختر نوع إجازة نشطًا';END IF;units:=erp_attendance_private.leave_units(p_cafe,emp,type_id,start_date,end_date,permission='half_leave');IF (units->>'days')::numeric<=0 THEN RAISE EXCEPTION 'الفترة لا تتضمن أيام عمل مستحقة للإجازة';END IF;
  ELSE IF start_date<>end_date OR coalesce((p->>'minutes')::integer,0) NOT BETWEEN 1 AND 720 THEN RAISE EXCEPTION 'حدد دقائق إذن التأخير أو الانصراف ليوم واحد';END IF;units:='{"days":0,"years":{}}';END IF;
  IF p->>'kind'='permission' AND p_role NOT IN('owner','manager') THEN RAISE EXCEPTION 'إنشاء إذن إجازة مباشر للإدارة فقط' USING ERRCODE='42501';END IF;
  rid:=coalesce(rid,gen_random_uuid());INSERT INTO public.erp_att_leaves(id,cafe_id,employee_id,kind,leave_type_id,permission_type,from_date,to_date,minutes,days,payload,created_by) VALUES(rid,p_cafe,emp,CASE WHEN p->>'kind'='permission' THEN 'permission' ELSE 'application' END,type_id,permission,start_date,end_date,coalesce((p->>'minutes')::integer,0),(units->>'days')::numeric,p||jsonb_build_object('units',units),auth.uid())
  ON CONFLICT(id) DO UPDATE SET leave_type_id=excluded.leave_type_id,permission_type=excluded.permission_type,from_date=excluded.from_date,to_date=excluded.to_date,minutes=excluded.minutes,days=excluded.days,payload=excluded.payload,revision=public.erp_att_leaves.revision+1;
  RETURN jsonb_build_object('id',rid,'status','draft');
 ELSIF p_action='delete_leave' THEN IF a.status<>'draft' THEN RAISE EXCEPTION 'يمكن حذف مسودة الإجازة فقط';END IF;DELETE FROM public.erp_att_leaves WHERE cafe_id=p_cafe AND id=rid;RETURN jsonb_build_object('id',rid,'deleted',true);
 ELSIF p_action='submit_leave' THEN
  IF a.status<>'draft' THEN RAISE EXCEPTION 'الطلب ليس مسودة';END IF;PERFORM erp_attendance_private.period_open(p_cafe,e.id,a.from_date,a.to_date);
  SELECT * INTO rule FROM public.erp_att_approvals r WHERE r.cafe_id=p_cafe AND r.active AND (jsonb_array_length(coalesce(r.payload->'branchIds','[]'))=0 OR r.payload->'branchIds'?e.branch_id::text) AND(jsonb_array_length(coalesce(r.payload->'departmentIds','[]'))=0 OR r.payload->'departmentIds'?e.department_id::text) AND(jsonb_array_length(coalesce(r.payload->'leaveTypeIds','[]'))=0 OR r.payload->'leaveTypeIds'?a.leave_type_id::text) AND r.payload->'types'?a.permission_type ORDER BY jsonb_array_length(coalesce(r.payload->'departmentIds','[]')) DESC,jsonb_array_length(coalesce(r.payload->'branchIds','[]')) DESC,r.id LIMIT 1;
  IF a.from_date<(now() AT TIME ZONE(settings->>'timezone'))::date AND NOT coalesce((rule.payload->>'allowPast')::boolean,(settings->>'allowPastLeave')::boolean,false) THEN RAISE EXCEPTION 'الإعدادات لا تسمح بطلب إجازة لتاريخ سابق';END IF;
  IF rule.id IS NOT NULL THEN FOR level IN SELECT * FROM jsonb_array_elements(rule.payload->'levels') LOOP users:=erp_attendance_private.approvers(p_cafe,e.id,level);IF jsonb_array_length(users)=0 THEN RAISE EXCEPTION 'أحد مستويات الموافقة لا يملك معتمدًا نشطًا مرتبطًا بحساب دخول';END IF;levels:=levels||jsonb_build_array(jsonb_build_object('name',level->>'name','users',users));END LOOP;
  ELSE users:=erp_attendance_private.approvers(p_cafe,e.id,jsonb_build_object('directManager',settings->'directManagersApprove','departmentManagers',settings->'departmentManagersApprove','employeeIds',settings->'approverIds'));IF jsonb_array_length(users)=0 THEN SELECT jsonb_build_array(owner_user_id::text) INTO users FROM public.cafes WHERE id=p_cafe;END IF;levels:=jsonb_build_array(jsonb_build_object('name','الموافقة الافتراضية','users',users));END IF;
  IF NOT (settings->>'allowNegativeLeave')::boolean AND a.permission_type IN('leave','half_leave') THEN FOR fiscal,quantity IN SELECT key,value::text::numeric FROM jsonb_each(a.payload->'units'->'years') LOOP balance:=erp_attendance_private.balance(p_cafe,e.id,a.leave_type_id,greatest(a.from_date,fiscal::date));IF (balance->>'available')::numeric<quantity THEN RAISE EXCEPTION 'رصيد الإجازات غير كافٍ';END IF;END LOOP;END IF;
  UPDATE public.erp_att_leaves SET status='pending',approval_snapshot=levels,level=0,payload=payload||jsonb_build_object('approvalRuleId',rule.id,'allowEarly',coalesce((rule.payload->>'allowEarly')::boolean,false)),revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;
 ELSIF p_action IN('approve_leave','reject_leave') THEN
  IF a.status<>'pending' THEN RAISE EXCEPTION 'الطلب ليس قيد الموافقة';END IF;
  FOR index IN a.level..jsonb_array_length(a.approval_snapshot)-1 LOOP IF a.approval_snapshot->index->'users'?auth.uid()::text AND (index=a.level OR coalesce((a.payload->>'allowEarly')::boolean,false)) THEN candidate:=index;EXIT;END IF;END LOOP;
  IF p_role='owner' THEN candidate:=a.level;END IF;IF candidate<0 THEN RAISE EXCEPTION 'لست معتمدًا في مستوى الموافقة المتاح' USING ERRCODE='42501';END IF;IF length(note)>2000 THEN RAISE EXCEPTION 'ملاحظة الموافقة أطول من المسموح';END IF;
  IF p_action='reject_leave' THEN UPDATE public.erp_att_leaves SET status='rejected',revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;INSERT INTO public.erp_att_leave_decisions(cafe_id,leave_id,level,decision,note,actor) VALUES(p_cafe,rid,candidate,'rejected',note,auth.uid());
  ELSE next_level:=candidate+1;IF next_level=jsonb_array_length(a.approval_snapshot) THEN
    PERFORM erp_attendance_private.period_open(p_cafe,e.id,a.from_date,a.to_date);
    IF EXISTS(SELECT 1 FROM public.erp_att_leaves l WHERE l.cafe_id=p_cafe AND l.employee_id=e.id AND l.id<>rid AND l.status='approved' AND l.from_date<=a.to_date AND l.to_date>=a.from_date AND (l.permission_type IN('leave','half_leave') OR a.permission_type IN('leave','half_leave') OR l.permission_type=a.permission_type)) THEN RAISE EXCEPTION 'توجد إجازة معتمدة تتداخل مع الطلب';END IF;
    IF a.permission_type IN('leave','half_leave') THEN FOR fiscal,quantity IN SELECT key,value::text::numeric FROM jsonb_each(a.payload->'units'->'years') LOOP balance:=erp_attendance_private.balance(p_cafe,e.id,a.leave_type_id,greatest(a.from_date,fiscal::date));IF NOT (settings->>'allowNegativeLeave')::boolean AND (balance->>'available')::numeric<quantity THEN RAISE EXCEPTION 'رصيد الإجازات لم يعد كافيًا عند الاعتماد';END IF;INSERT INTO public.erp_att_balances(cafe_id,employee_id,leave_type_id,fiscal_start,amount,note,source,leave_id,created_by) VALUES(p_cafe,e.id,a.leave_type_id,fiscal::date,-quantity,'اعتماد إجازة','leave',rid,auth.uid());END LOOP;END IF;
    UPDATE public.erp_att_leaves SET status='approved',level=next_level,revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;
    dated:=a.from_date;WHILE dated<=a.to_date LOOP PERFORM erp_attendance_private.calculate_day(p_cafe,e.id,dated,0,false);PERFORM erp_attendance_private.calculate_day(p_cafe,e.id,dated,1,false);dated:=dated+1;END LOOP;
   ELSE UPDATE public.erp_att_leaves SET level=next_level,revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;END IF;INSERT INTO public.erp_att_leave_decisions(cafe_id,leave_id,level,decision,note,actor) VALUES(p_cafe,rid,candidate,'approved',note,auth.uid());END IF;
 ELSIF p_action='cancel_leave' THEN
  IF a.status NOT IN('draft','pending','approved') THEN RAISE EXCEPTION 'الطلب غير قابل للإلغاء';END IF;IF a.status='approved' AND p_role NOT IN('owner','manager') THEN RAISE EXCEPTION 'إلغاء الإجازة المعتمدة للإدارة فقط' USING ERRCODE='42501';END IF;
  IF a.status='approved' THEN PERFORM erp_attendance_private.period_open(p_cafe,e.id,a.from_date,a.to_date);INSERT INTO public.erp_att_balances(cafe_id,employee_id,leave_type_id,fiscal_start,amount,note,source,leave_id,created_by) SELECT cafe_id,employee_id,leave_type_id,fiscal_start,-amount,'إلغاء إجازة معتمدة','reversal',leave_id,auth.uid() FROM public.erp_att_balances WHERE cafe_id=p_cafe AND leave_id=rid AND source='leave';END IF;
  UPDATE public.erp_att_leaves SET status='cancelled',revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;INSERT INTO public.erp_att_leave_decisions(cafe_id,leave_id,level,decision,note,actor) VALUES(p_cafe,rid,a.level,'cancelled',note,auth.uid());
  IF a.status='approved' THEN dated:=a.from_date;WHILE dated<=a.to_date LOOP PERFORM erp_attendance_private.calculate_day(p_cafe,e.id,dated,0,false);PERFORM erp_attendance_private.calculate_day(p_cafe,e.id,dated,1,false);dated:=dated+1;END LOOP;END IF;
 ELSE RAISE EXCEPTION 'حركة الإجازة غير مدعومة';END IF;
 RETURN(SELECT jsonb_build_object('id',l.id,'status',l.status,'revision',l.revision,'level',l.level) FROM public.erp_att_leaves l WHERE l.cafe_id=p_cafe AND l.id=rid);
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.leave_units(p_cafe uuid, p_employee uuid, p_type uuid, p_from date, p_to date, p_half boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE dated date:=p_from;a public.erp_att_assignments;spec jsonb;total numeric:=0;byyear jsonb:='{}';balance jsonb;fiscal text;unit numeric:=CASE WHEN p_half THEN 0.5 ELSE 1 END;BEGIN
 IF p_from IS NULL OR p_to IS NULL OR p_to<p_from OR p_to-p_from>366 THEN RAISE EXCEPTION 'فترة الإجازة غير صالحة';END IF;
 WHILE dated<=p_to LOOP
  balance:=erp_attendance_private.balance(p_cafe,p_employee,p_type,dated);fiscal:=balance->>'fiscalStart';SELECT * INTO a FROM public.erp_att_assignments WHERE cafe_id=p_cafe AND employee_id=p_employee AND effective_from<=dated AND coalesce(effective_to,'infinity')>=dated ORDER BY effective_from DESC LIMIT 1;
  IF a.id IS NULL THEN RAISE EXCEPTION 'حدد تعيين الموظف خلال فترة الإجازة أولًا';END IF;
  SELECT x INTO spec FROM public.erp_att_shifts sh,LATERAL jsonb_array_elements(sh.payload->'days')x WHERE sh.cafe_id=p_cafe AND sh.id=coalesce((SELECT al.shift_id FROM public.erp_att_allocations al JOIN public.erp_att_allocation_employees ae ON ae.cafe_id=al.cafe_id AND ae.allocation_id=al.id WHERE ae.cafe_id=p_cafe AND ae.employee_id=p_employee AND dated BETWEEN al.from_date AND al.to_date LIMIT 1),a.primary_shift_id) AND (x->>'weekday')::integer=extract(dow FROM dated)::integer;
  IF (balance->>'includeWeekends')::boolean OR coalesce((spec->>'working')::boolean,false) THEN total:=total+unit;byyear:=jsonb_set(byyear,ARRAY[fiscal],to_jsonb(coalesce((byyear->>fiscal)::numeric,0)+unit));END IF;dated:=dated+1;
 END LOOP;RETURN jsonb_build_object('days',total,'years',byyear);
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.payroll_metrics(p_cafe uuid, p_employee uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE employee public.erp_hr_employees;dated date;start_date date;end_date date;assignment public.erp_att_assignments;expected integer;actual integer;approved integer;minutes jsonb;worked numeric:=0;scheduled numeric:=0;late numeric:=0;early numeric:=0;overtime numeric:=0;absent numeric:=0;leave_days numeric:=0;holiday numeric:=0;days integer:=0;complete boolean:=true;BEGIN
 IF p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to) OR p_to<p_from OR p_to-p_from>366 THEN RAISE EXCEPTION 'فترة مقاييس المرتبات غير صالحة';END IF;
 SELECT * INTO employee FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=p_employee;IF NOT FOUND THEN RAISE EXCEPTION 'موظف المرتبات غير متاح' USING ERRCODE='42501';END IF;
 start_date:=greatest(p_from,coalesce((employee.payload->>'joinDate')::date,p_from));end_date:=least(p_to,coalesce((employee.payload->>'endDate')::date,p_to));dated:=start_date;
 WHILE dated<=end_date LOOP
  SELECT * INTO assignment FROM public.erp_att_assignments WHERE cafe_id=p_cafe AND employee_id=p_employee AND effective_from<=dated AND coalesce(effective_to,'infinity')>=dated ORDER BY effective_from DESC LIMIT 1;
  expected:=CASE WHEN assignment.id IS NULL THEN 0 WHEN assignment.secondary_shift_id IS NULL THEN 1 ELSE 2 END;
  SELECT count(*),count(*) FILTER(WHERE EXISTS(SELECT 1 FROM public.erp_att_sheet_days sd JOIN public.erp_att_sheets s ON s.cafe_id=sd.cafe_id AND s.id=sd.sheet_id WHERE sd.cafe_id=d.cafe_id AND sd.day_id=d.id AND s.status='approved')),
   jsonb_build_object('worked',coalesce(sum(worked_minutes),0),'scheduled',coalesce(sum(scheduled_minutes),0),'late',coalesce(sum(late_minutes),0),'early',coalesce(sum(early_minutes),0),'overtime',coalesce(sum(overtime_minutes),0),'absent',count(*) FILTER(WHERE status='absent'),'leave',coalesce(sum(leave_minutes),0),'holiday',count(*) FILTER(WHERE status='holiday')) INTO actual,approved,minutes
  FROM public.erp_att_days d WHERE cafe_id=p_cafe AND employee_id=p_employee AND work_date=dated;
  IF expected=0 OR actual<>expected OR approved<>expected THEN complete:=false;END IF;
  IF actual>0 AND approved=actual THEN worked:=worked+(minutes->>'worked')::numeric;scheduled:=scheduled+(minutes->>'scheduled')::numeric;late:=late+(minutes->>'late')::numeric;early:=early+(minutes->>'early')::numeric;overtime:=overtime+(minutes->>'overtime')::numeric;absent:=absent+(minutes->>'absent')::numeric/greatest(actual,1);holiday:=holiday+(minutes->>'holiday')::numeric/greatest(actual,1);leave_days:=leave_days+CASE WHEN (minutes->>'scheduled')::numeric>0 THEN (minutes->>'leave')::numeric/(minutes->>'scheduled')::numeric ELSE 0 END;days:=days+1;END IF;
  dated:=dated+1;
 END LOOP;
 RETURN jsonb_build_object('worked',worked,'scheduled',scheduled,'late',late,'early',early,'overtime',overtime,'absent',round(absent,4),'leave',round(leave_days,4),'holiday',round(holiday,4),'days',days,'complete',complete,'from',start_date,'to',end_date);
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.save_catalog(p_cafe uuid, p_kind text, p jsonb, p_id uuid, p_revision integer, p_delete boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE tbl text;rid uuid:=coalesce(p_id,gen_random_uuid());old jsonb;result jsonb;v_active boolean:=coalesce((p->>'active')::boolean,true);BEGIN
 tbl:=CASE p_kind WHEN 'shifts' THEN 'erp_att_shifts' WHEN 'policies' THEN 'erp_att_policies' WHEN 'leave-types' THEN 'erp_att_leave_types' WHEN 'restrictions' THEN 'erp_att_restrictions' WHEN 'approvals' THEN 'erp_att_approvals' WHEN 'flags' THEN 'erp_att_flags' WHEN 'devices' THEN 'erp_att_devices' END;
 IF tbl IS NULL THEN RAISE EXCEPTION 'نوع الإعداد غير مدعوم';END IF;
 IF p_id IS NOT NULL THEN EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE cafe_id=$1 AND id=$2 FOR UPDATE',tbl) INTO old USING p_cafe,p_id;IF old IS NULL THEN RAISE EXCEPTION 'السجل غير متاح' USING ERRCODE='42501';END IF;IF (old->>'revision')::integer IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'تغير السجل أعد تحميل الصفحة' USING ERRCODE='40001';END IF;END IF;
 IF p_delete THEN
  IF p_id IS NULL THEN RAISE EXCEPTION 'اختر السجل المراد حذفه';END IF;
  IF p_kind='leave-types' AND EXISTS(SELECT 1 FROM public.erp_att_policies a,LATERAL jsonb_array_elements(a.payload->'types')x WHERE a.cafe_id=p_cafe AND x->>'typeId'=p_id::text) THEN RAISE EXCEPTION 'نوع الإجازة مستخدم في سياسة إجازات';END IF;
  EXECUTE format('DELETE FROM public.%I WHERE cafe_id=$1 AND id=$2',tbl) USING p_cafe,p_id;RETURN jsonb_build_object('id',rid,'deleted',true);
 END IF;
 PERFORM erp_attendance_private.validate_catalog(p_cafe,p_kind,p);
 IF p_kind='devices' THEN v_active:=false;END IF;
 IF p_id IS NULL THEN
  IF p_kind='flags' THEN INSERT INTO public.erp_att_flags(id,cafe_id,name,active,payload,condition_ast,formula_ast) VALUES(rid,p_cafe,btrim(p->>'name'),v_active,p-'conditionAst'-'formulaAst',p->'conditionAst',p->'formulaAst');
  ELSE EXECUTE format('INSERT INTO public.%I(id,cafe_id,name,active,payload) VALUES($1,$2,$3,$4,$5)',tbl) USING rid,p_cafe,btrim(p->>'name'),v_active,p-'communicationKey';END IF;
 ELSE
  IF p_kind='flags' THEN UPDATE public.erp_att_flags SET name=btrim(p->>'name'),active=v_active,payload=p-'conditionAst'-'formulaAst',condition_ast=p->'conditionAst',formula_ast=p->'formulaAst',revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;
  ELSE EXECUTE format('UPDATE public.%I SET name=$1,active=$2,payload=$3,revision=revision+1 WHERE cafe_id=$4 AND id=$5',tbl) USING btrim(p->>'name'),v_active,p-'communicationKey',p_cafe,rid;END IF;
 END IF;
 IF p_kind='devices' AND (p_id IS NULL OR coalesce(p->>'communicationKey','')<>'') THEN INSERT INTO erp_attendance_private.device_credentials(cafe_id,device_id,communication_key) VALUES(p_cafe,rid,coalesce(p->>'communicationKey','')) ON CONFLICT(device_id) DO UPDATE SET communication_key=excluded.communication_key;END IF;
 EXECUTE format('SELECT jsonb_build_object(''id'',id,''revision'',revision) FROM public.%I WHERE cafe_id=$1 AND id=$2',tbl) INTO result USING p_cafe,rid;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.session_action(p_cafe uuid, p_action text, p_data jsonb, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE rid uuid:=nullif(p_data->>'id','')::uuid;rev integer:=(p_data->>'revision')::integer;p jsonb:=coalesce(p_data->'payload',p_data);a public.erp_att_sessions;employee uuid;log_id uuid;v_proof jsonb;photo uuid:=nullif(p->>'photoId','')::uuid;setting jsonb:=erp_attendance_private.settings(p_cafe);dated date:=(now() AT TIME ZONE(setting->>'timezone'))::date;BEGIN
 IF p_action='prepare_session' THEN
  SELECT id INTO employee FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND user_id=auth.uid() AND active;IF employee IS NULL THEN RAISE EXCEPTION 'اربط حسابك بملف موظف نشط قبل تسجيل الحضور';END IF;
  SELECT * INTO a FROM public.erp_att_sessions WHERE cafe_id=p_cafe AND employee_id=employee AND status IN('draft','open') FOR UPDATE;IF FOUND THEN RETURN jsonb_build_object('id',a.id,'revision',a.revision,'status',a.status);END IF;
  rid:=gen_random_uuid();INSERT INTO public.erp_att_sessions(id,cafe_id,employee_id,status) VALUES(rid,p_cafe,employee,'draft');RETURN jsonb_build_object('id',rid,'revision',1,'status','draft');
 END IF;
 SELECT * INTO a FROM public.erp_att_sessions WHERE cafe_id=p_cafe AND id=rid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'جلسة الحضور غير متاحة' USING ERRCODE='42501';END IF;IF a.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'تغيرت جلسة الحضور' USING ERRCODE='40001';END IF;employee:=a.employee_id;
 IF p_action='void_session' THEN
  IF p_role NOT IN('owner','manager') OR a.status='void' OR coalesce(length(btrim(p->>'note')),0) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'إلغاء جلسة الحضور يتطلب صلاحية وسببًا واضحًا';END IF;
  IF a.check_in IS NOT NULL THEN PERFORM erp_attendance_private.log_unlocked(p_cafe,employee,(SELECT occurred_at FROM public.erp_att_logs WHERE cafe_id=p_cafe AND id=a.check_in));END IF;IF a.check_out IS NOT NULL THEN PERFORM erp_attendance_private.log_unlocked(p_cafe,employee,(SELECT occurred_at FROM public.erp_att_logs WHERE cafe_id=p_cafe AND id=a.check_out));END IF;
  UPDATE public.erp_att_logs SET voided=true,revision=revision+1 WHERE cafe_id=p_cafe AND id IN(a.check_in,a.check_out);UPDATE public.erp_att_sessions SET status='void',revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;RETURN jsonb_build_object('id',rid,'status','void');
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=employee AND user_id=auth.uid() AND active) THEN RAISE EXCEPTION 'لا تسجل توقيع الحضور بالنيابة عن موظف آخر' USING ERRCODE='42501';END IF;
 IF (p_action='check_in' AND a.status<>'draft') OR(p_action='check_out' AND a.status<>'open') THEN RAISE EXCEPTION 'حالة جلسة الحضور لا تسمح بهذا التوقيع';END IF;
 IF p_action='check_in' AND NOT (setting->>'logDuringLeave')::boolean AND EXISTS(SELECT 1 FROM public.erp_att_leaves WHERE cafe_id=p_cafe AND employee_id=employee AND status='approved' AND permission_type='leave' AND dated BETWEEN from_date AND to_date) THEN RAISE EXCEPTION 'التوقيع أثناء الإجازة المعتمدة غير مسموح';END IF;
 PERFORM erp_attendance_private.log_unlocked(p_cafe,employee,now());v_proof:=erp_attendance_private.check_restrictions(p_cafe,employee,rid,p,(p->>'proofId')::uuid,photo);log_id:=gen_random_uuid();INSERT INTO public.erp_att_logs(id,cafe_id,employee_id,occurred_at,direction,source,created_by) VALUES(log_id,p_cafe,employee,now(),CASE WHEN p_action='check_in' THEN 'in' ELSE 'out' END,'self',auth.uid());
 IF p_action='check_in' THEN UPDATE public.erp_att_sessions SET check_in=log_id,check_in_photo_id=photo,status='open',proof=jsonb_build_object('in',v_proof),revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;
 ELSE UPDATE public.erp_att_sessions SET check_out=log_id,check_out_photo_id=photo,status='closed',proof=public.erp_att_sessions.proof||jsonb_build_object('out',v_proof),revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;END IF;
 IF (setting->>'autoCalculate')::boolean THEN PERFORM erp_attendance_private.calculate_day(p_cafe,employee,dated,0,false);PERFORM erp_attendance_private.calculate_day(p_cafe,employee,dated,1,false);PERFORM erp_attendance_private.calculate_day(p_cafe,employee,dated-1,0,false);PERFORM erp_attendance_private.calculate_day(p_cafe,employee,dated-1,1,false);END IF;
 RETURN jsonb_build_object('id',rid,'status',CASE WHEN p_action='check_in' THEN 'open' ELSE 'closed' END,'revision',a.revision+1);
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.settlement_action(p_cafe uuid, p_action text, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE rid uuid:=nullif(p_data->>'id','')::uuid;rev integer:=(p_data->>'revision')::integer;p jsonb:=coalesce(p_data->'payload',p_data);a public.erp_att_settlements;emp uuid;balance jsonb;BEGIN
 IF rid IS NOT NULL THEN SELECT * INTO a FROM public.erp_att_settlements WHERE cafe_id=p_cafe AND id=rid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'تسوية الإجازة غير متاحة' USING ERRCODE='42501';END IF;IF a.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'تغيرت تسوية الإجازة' USING ERRCODE='40001';END IF;END IF;
 IF p_action='save_settlement' THEN
  emp:=(p->>'employeeId')::uuid;PERFORM erp_attendance_private.employee(p_cafe,emp);IF rid IS NOT NULL AND (a.status<>'draft' OR a.employee_id<>emp) THEN RAISE EXCEPTION 'يمكن تعديل مسودة التسوية للموظف نفسه فقط';END IF;rid:=coalesce(rid,gen_random_uuid());IF NOT isfinite((p->>'date')::date) THEN RAISE EXCEPTION 'تاريخ التسوية غير صالح';END IF;
  INSERT INTO public.erp_att_settlements(id,cafe_id,employee_id,leave_type_id,effective_on,days,note) VALUES(rid,p_cafe,emp,(p->>'leaveTypeId')::uuid,(p->>'date')::date,(p->>'days')::numeric,coalesce(p->>'note','')) ON CONFLICT(id) DO UPDATE SET leave_type_id=excluded.leave_type_id,effective_on=excluded.effective_on,days=excluded.days,note=excluded.note,revision=public.erp_att_settlements.revision+1;
 ELSIF p_action='approve_settlement' THEN
  IF a.status<>'draft' THEN RAISE EXCEPTION 'التسوية ليست مسودة';END IF;balance:=erp_attendance_private.balance(p_cafe,a.employee_id,a.leave_type_id,a.effective_on);IF (balance->>'available')::numeric<a.days THEN RAISE EXCEPTION 'الرصيد المتاح لا يكفي للتسوية';END IF;
  INSERT INTO public.erp_att_balances(cafe_id,employee_id,leave_type_id,fiscal_start,amount,note,source,settlement_id,created_by) VALUES(p_cafe,a.employee_id,a.leave_type_id,(balance->>'fiscalStart')::date,-a.days,'حجز رصيد تسوية الإجازة','settlement',rid,auth.uid());UPDATE public.erp_att_settlements SET status='approved',payload=jsonb_build_object('balanceBefore',balance),revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;
 ELSIF p_action='cancel_settlement' THEN
  IF a.status NOT IN('draft','approved') THEN RAISE EXCEPTION 'ألغ اعتماد المسير المرتبط قبل إلغاء التسوية';END IF;IF a.status='approved' THEN INSERT INTO public.erp_att_balances(cafe_id,employee_id,leave_type_id,fiscal_start,amount,note,source,settlement_id,created_by) SELECT cafe_id,employee_id,leave_type_id,fiscal_start,-amount,'إلغاء حجز تسوية الإجازة','settlement_reversal',settlement_id,auth.uid() FROM public.erp_att_balances WHERE cafe_id=p_cafe AND settlement_id=rid AND source='settlement';END IF;UPDATE public.erp_att_settlements SET status='cancelled',revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;
 ELSE RAISE EXCEPTION 'حركة تسوية الإجازة غير مدعومة';END IF;RETURN jsonb_build_object('id',rid);
END $function$

CREATE OR REPLACE FUNCTION erp_attendance_private.validate_catalog(p_cafe uuid, p_kind text, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE x jsonb;y jsonb;item uuid;seen text[]:='{}';subnet inet;setting jsonb;BEGIN
 IF coalesce(jsonb_typeof(p),'')<>'object' OR octet_length(p::text)>30000 OR coalesce(length(btrim(p->>'name')),0) NOT BETWEEN 1 AND 150 THEN RAISE EXCEPTION 'راجع اسم السجل والبيانات';END IF;
 IF coalesce(jsonb_typeof(p->'active'),'')<>'boolean' THEN RAISE EXCEPTION 'حدد حالة السجل';END IF;
 IF p_kind IN('shifts','flags','leave-types') AND coalesce(p->>'color','')!~'^#[0-9A-Fa-f]{6}$' THEN RAISE EXCEPTION 'لون السجل غير صالح';END IF;
 IF p_kind='leave-types' AND coalesce(jsonb_typeof(p->'paid'),'')<>'boolean' THEN RAISE EXCEPTION 'حدد ما إذا كانت الإجازة مدفوعة';END IF;
 IF p_kind='restrictions' AND EXISTS(SELECT 1 FROM unnest(ARRAY['useIp','ipRequired','useLocation','locationRequired','useCamera','cameraRequired'])k WHERE coalesce(jsonb_typeof(p->k),'')<>'boolean') THEN RAISE EXCEPTION 'راجع تفعيل محددات الحضور وحقول الإلزام';END IF;
 IF p_kind='shifts' THEN
  IF coalesce(p->>'type','') NOT IN('standard','advanced') OR coalesce(jsonb_array_length(p->'days'),0)<>7 OR (SELECT count(DISTINCT d->>'weekday') FROM jsonb_array_elements(p->'days')d)<>7 THEN RAISE EXCEPTION 'حدد نوع الوردية وأيام الأسبوع السبعة';END IF;
  FOR x IN SELECT * FROM jsonb_array_elements(p->'days') LOOP IF coalesce((x->>'weekday')::integer,-1) NOT BETWEEN 0 AND 6 OR EXISTS(SELECT 1 FROM unnest(ARRAY['working','workOnHoliday','lateFromStart'])k WHERE coalesce(jsonb_typeof(x->k),'')<>'boolean') OR coalesce(jsonb_typeof(x->'grace'),'')<>'number' OR coalesce(jsonb_typeof(x->'breakMinutes'),'')<>'number' THEN RAISE EXCEPTION 'يوم الوردية أو قواعده غير صالحة';END IF;PERFORM erp_attendance_private.window(x,current_date,'Asia/Riyadh');END LOOP;
 ELSIF p_kind='policies' THEN
  IF coalesce(jsonb_array_length(p->'types'),0) NOT BETWEEN 1 AND 40 THEN RAISE EXCEPTION 'حدد أنواع الإجازة في السياسة';END IF;
  FOR x IN SELECT * FROM jsonb_array_elements(p->'types') LOOP item:=(x->>'typeId')::uuid;IF item::text=ANY(seen) OR NOT EXISTS(SELECT 1 FROM public.erp_att_leave_types WHERE cafe_id=p_cafe AND id=item) OR coalesce((x->>'annualDays')::numeric,-1) NOT BETWEEN 0 AND 366 OR coalesce((x->>'carryLimit')::numeric,-1) NOT BETWEEN 0 AND 366 OR coalesce(jsonb_typeof(x->'prorate'),'')<>'boolean' OR coalesce(jsonb_typeof(x->'includeWeekends'),'')<>'boolean' THEN RAISE EXCEPTION 'راجع نوع الإجازة والاستحقاق والترحيل';END IF;seen:=array_append(seen,item::text);END LOOP;
 ELSIF p_kind='restrictions' THEN
  IF coalesce((p->>'useIp')::boolean,false) THEN IF coalesce(jsonb_array_length(p->'ips'),0) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'أدخل نطاق شبكة مسموحًا';END IF;FOR x IN SELECT * FROM jsonb_array_elements(p->'ips') LOOP subnet:=(x#>>'{}')::inet;END LOOP;END IF;
  IF coalesce((p->>'useLocation')::boolean,false) THEN IF coalesce(jsonb_array_length(p->'locations'),0) NOT BETWEEN 1 AND 30 THEN RAISE EXCEPTION 'حدد موقع الحضور ونطاقه';END IF;FOR x IN SELECT * FROM jsonb_array_elements(p->'locations') LOOP IF (x->>'lat')::numeric NOT BETWEEN -90 AND 90 OR (x->>'lng')::numeric NOT BETWEEN -180 AND 180 OR (x->>'radius')::numeric<=0 OR (x->>'radius')::numeric>100000 THEN RAISE EXCEPTION 'إحداثيات الحضور أو النطاق غير صالح';END IF;END LOOP;END IF;
 ELSIF p_kind='approvals' THEN
  IF coalesce(jsonb_array_length(p->'levels'),0) NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'أضف من مستوى إلى عشرة مستويات موافقة';END IF;
  FOR x IN SELECT * FROM jsonb_array_elements(p->'levels') LOOP IF NOT coalesce((x->>'directManager')::boolean,false) AND NOT coalesce((x->>'departmentManagers')::boolean,false) AND jsonb_array_length(coalesce(x->'employeeIds','[]'))=0 THEN RAISE EXCEPTION 'حدد معتمدي كل مستوى';END IF;FOR y IN SELECT * FROM jsonb_array_elements(coalesce(x->'employeeIds','[]')) LOOP PERFORM erp_attendance_private.employee(p_cafe,(y#>>'{}')::uuid);END LOOP;END LOOP;
  FOR x IN SELECT * FROM jsonb_array_elements(coalesce(p->'branchIds','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=p_cafe AND id=(x#>>'{}')::uuid AND deleted_at IS NULL) THEN RAISE EXCEPTION 'فرع الموافقة غير متاح';END IF;END LOOP;
  FOR x IN SELECT * FROM jsonb_array_elements(coalesce(p->'departmentIds','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM public.erp_org_units WHERE cafe_id=p_cafe AND id=(x#>>'{}')::uuid AND kind='department') THEN RAISE EXCEPTION 'قسم الموافقة غير متاح';END IF;END LOOP;
 ELSIF p_kind='flags' THEN
  FOR x IN SELECT * FROM jsonb_array_elements(coalesce(p->'shiftIds','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM public.erp_att_shifts WHERE cafe_id=p_cafe AND id=(x#>>'{}')::uuid) THEN RAISE EXCEPTION 'الوردية في قاعدة الحضور غير متاحة';END IF;END LOOP;
  PERFORM erp_attendance_private.evaluate(p->'conditionAst','{"worked":480,"scheduled":480,"late":15,"early":0,"overtime":30,"absent":0,"leave":0,"holiday":0}');PERFORM erp_attendance_private.evaluate(p->'formulaAst','{"worked":480,"scheduled":480,"late":15,"early":0,"overtime":30,"absent":0,"leave":0,"holiday":0}');
 ELSIF p_kind='devices' THEN IF coalesce(p->>'type','')<>'zkteco' OR coalesce((p->>'active')::boolean,true) OR (p->>'port')::integer NOT BETWEEN 1 AND 65535 OR length(p->>'communicationKey')>200 THEN RAISE EXCEPTION 'احفظ إعداد الجهاز دون تفعيل اتصال خارجي';END IF;
 ELSIF p_kind<>'leave-types' THEN RAISE EXCEPTION 'نوع إعداد الحضور غير مدعوم';END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.allowed_resource(c uuid, b uuid, k text, r uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE p jsonb;shared boolean;BEGIN
 IF b IS NULL THEN RETURN brand_finance_private.role_for(c) IN('owner','manager') OR NOT EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=c AND active AND deleted_at IS NULL);END IF;
 IF NOT erp_branch_private.branch_allowed(c,b) THEN RETURN false;END IF;
 SELECT payload INTO p FROM public.erp_branch_settings WHERE cafe_id=c;
 shared:=CASE k WHEN 'customer' THEN coalesce((p->>'shareCustomers')::boolean,true) WHEN 'supplier' THEN coalesce((p->>'shareSuppliers')::boolean,true) WHEN 'item' THEN coalesce((p->>'shareProducts')::boolean,true) WHEN 'cost_center' THEN coalesce((p->>'shareCostCenters')::boolean,true) WHEN 'unit_template' THEN coalesce((p->>'shareUnitTemplates')::boolean,true) WHEN 'account' THEN NOT coalesce((p->>'specifyAccounts')::boolean,false) ELSE false END;
 RETURN shared OR NOT EXISTS(SELECT 1 FROM public.erp_branch_resources WHERE cafe_id=c AND kind=k AND record_id=r) OR EXISTS(SELECT 1 FROM public.erp_branch_resources WHERE cafe_id=c AND kind=k AND record_id=r AND branch_id=b);
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.assert_context(c uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE s jsonb:=erp_branch_private.scope(c);expected jsonb;BEGIN
 IF erp_branch_private.job_context(c) IS NOT NULL THEN RETURN;END IF;IF (s->>'revision')::integer=0 THEN RETURN;END IF;
 BEGIN expected:=nullif(current_setting('erp.branch_expected',true),'')::jsonb;EXCEPTION WHEN OTHERS THEN expected:=NULL;END;
 IF expected IS NULL OR expected->'branchId' IS DISTINCT FROM s->'branchId' OR expected->'revision' IS DISTINCT FROM s->'revision' THEN RAISE EXCEPTION 'تغير فرع العمل أعد تحميل الصفحة قبل الحفظ' USING ERRCODE='40001';END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.assert_input(c uuid, j jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE v jsonb;b uuid:=erp_branch_private.current_branch(c);BEGIN
 IF NOT erp_branch_private.row_allowed(c,b,j,'') THEN RAISE EXCEPTION 'يتضمن المستند سجلًا غير متاح في الفرع المختار' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(j)='object' THEN FOR v IN SELECT value FROM jsonb_each(j) LOOP IF jsonb_typeof(v) IN('array','object') THEN PERFORM erp_branch_private.assert_input(c,v);END IF;END LOOP;
 ELSIF jsonb_typeof(j)='array' THEN FOR v IN SELECT value FROM jsonb_array_elements(j) LOOP PERFORM erp_branch_private.assert_input(c,v);END LOOP;END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.capture_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE c uuid:=NEW.cafe_id;b uuid;row jsonb:=to_jsonb(NEW);rid uuid;kind text;BEGIN
 IF nullif(current_setting('erp.branch_cafe',true),'') IS DISTINCT FROM c::text THEN RETURN NEW;END IF;b:=nullif(current_setting('erp.branch_id',true),'')::uuid;IF b IS NULL THEN RETURN NEW;END IF;
 IF NOT erp_branch_private.row_allowed(c,b,row,'') THEN RAISE EXCEPTION 'سجل خارج الفرع المختار' USING ERRCODE='42501';END IF;
 rid:=coalesce(nullif(row->>'id',''),nullif(row->>'item_id',''))::uuid;
 IF TG_TABLE_NAME='bf_documents' THEN
  IF NEW.reference_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=NEW.reference_id AND branch_id<>b) THEN RAISE EXCEPTION 'المستند الأصلي تابع لفرع آخر' USING ERRCODE='42501';END IF;
  INSERT INTO public.erp_branch_documents(cafe_id,document_id,branch_id) VALUES(c,rid,b);
 ELSE
  kind:=CASE TG_TABLE_NAME WHEN 'bf_parties' THEN row->>'kind' WHEN 'bf_items' THEN 'item' WHEN 'erp_cost_centers' THEN 'cost_center' WHEN 'erp_inventory_catalogs' THEN CASE WHEN row->>'kind'='unit_template' THEN 'unit_template' END ELSE NULL END;
  IF TG_TABLE_NAME='erp_inventory_catalogs' AND kind IS NULL THEN RETURN NEW;END IF;
  IF kind IS NOT NULL THEN INSERT INTO public.erp_branch_resources VALUES(c,kind,rid,b) ON CONFLICT DO NOTHING;ELSE INSERT INTO public.erp_branch_records VALUES(c,TG_TABLE_NAME,rid,b) ON CONFLICT DO NOTHING;END IF;
 END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.cleanup_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE row jsonb:=to_jsonb(OLD);rid uuid;k text;BEGIN
 rid:=coalesce(nullif(row->>'id',''),nullif(row->>'item_id',''))::uuid;k:=CASE TG_TABLE_NAME WHEN 'bf_parties' THEN row->>'kind' WHEN 'bf_items' THEN 'item' WHEN 'bf_accounts' THEN 'account' WHEN 'erp_cost_centers' THEN 'cost_center' WHEN 'erp_inventory_catalogs' THEN CASE WHEN row->>'kind'='unit_template' THEN 'unit_template' END END;
 DELETE FROM public.erp_branch_records WHERE cafe_id=OLD.cafe_id AND table_name=TG_TABLE_NAME AND record_id=rid;
 IF k IS NOT NULL THEN DELETE FROM public.erp_branch_resources WHERE cafe_id=OLD.cafe_id AND kind=k AND record_id=rid;END IF;RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.current_branch(c uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE j jsonb;b uuid;BEGIN
 j:=nullif(current_setting('erp.treasury_fee_source',true),'')::jsonb;
 IF j IS NOT NULL AND j->>'cafe'=c::text AND j->>'actor'=auth.uid()::text THEN
  b:=erp_treasury_private.fee_branch(c,(j->>'terminal')::uuid,nullif(j->>'source','')::uuid);
  IF to_jsonb(b) IS DISTINCT FROM nullif(j->'branchId','null'::jsonb) THEN RAISE EXCEPTION 'Treasury fee source changed' USING ERRCODE='40001';END IF;
  IF b IS NOT NULL AND NOT erp_branch_private.branch_allowed(c,b) THEN RAISE EXCEPTION 'Treasury fee branch unauthorized' USING ERRCODE='42501';END IF;RETURN b;
 END IF;RETURN erp_treasury_private.current_branch_before_treasury(c);
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.current_branch_before_provider_payment(c uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE b uuid;j jsonb;BEGIN j:=erp_branch_private.job_context(c);IF j IS NOT NULL THEN b:=(j->>'branchId')::uuid;IF b IS NOT NULL AND NOT erp_branch_private.branch_allowed(c,b) THEN RAISE EXCEPTION 'Scheduled branch unauthorized' USING ERRCODE='42501';END IF;RETURN b;END IF;
 SELECT branch_id INTO b FROM public.erp_branch_scopes WHERE cafe_id=c AND user_id=auth.uid();
 IF b IS NOT NULL AND NOT erp_branch_private.branch_allowed(c,b) THEN RAISE EXCEPTION 'الفرع المختار غير متاح لك اختر فرعًا آخر' USING ERRCODE='42501';END IF;
 IF b IS NULL AND brand_finance_private.role_for(c) NOT IN('owner','manager') AND EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=c AND active AND deleted_at IS NULL) THEN RAISE EXCEPTION 'اختر فرع العمل قبل متابعة العملية' USING ERRCODE='42501';END IF;RETURN b;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.enter_job(c uuid, t text, r uuid, actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE prior jsonb;b uuid;found_record boolean;BEGIN
 IF t NOT IN('erp_assets','erp_payroll_records','erp_finance_schedules','bf_recurring_invoices') THEN RAISE EXCEPTION 'Unsupported scheduled branch source';END IF;
 EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id=$2)',t) INTO found_record USING c,r;IF NOT found_record THEN RAISE EXCEPTION 'Scheduled branch source missing';END IF;
 SELECT branch_id INTO b FROM public.erp_branch_records WHERE cafe_id=c AND table_name=t AND record_id=r;
 prior:=jsonb_build_object('job',current_setting('erp.branch_job',true),'cafe',current_setting('erp.branch_cafe',true),'branch',current_setting('erp.branch_id',true),'expected',current_setting('erp.branch_expected',true),'sub',current_setting('request.jwt.claim.sub',true),'claims',current_setting('request.jwt.claims',true));
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor)::text,true);
 PERFORM set_config('erp.branch_job',jsonb_build_object('cafe',c,'table',t,'record',r,'branchId',b,'actor',actor)::text,true);PERFORM set_config('erp.branch_cafe',c::text,true);PERFORM set_config('erp.branch_id',coalesce(b::text,''),true);
 IF b IS NOT NULL AND NOT erp_branch_private.branch_allowed(c,b) THEN RAISE EXCEPTION 'Scheduled branch is no longer authorized' USING ERRCODE='42501';END IF;RETURN prior;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_accounting_cost_report_before_scope(p_cafe_id uuid, p_from date, p_to date, p_center uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE answer jsonb;BEGIN
 PERFORM erp_accounting_private.authorize(p_cafe_id);
 IF p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to) OR p_from>p_to OR p_to-p_from>3660 THEN RAISE EXCEPTION 'حدد فترة تقرير صحيحة لا تتجاوز عشر سنوات';END IF;
 IF p_center IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_cost_centers WHERE cafe_id=p_cafe_id AND id=p_center) THEN RAISE EXCEPTION 'مركز التكلفة غير متاح';END IF;
 WITH RECURSIVE selected AS(SELECT id FROM public.erp_cost_centers WHERE cafe_id=p_cafe_id AND id=p_center UNION ALL SELECT c.id FROM public.erp_cost_centers c JOIN selected s ON c.parent_id=s.id WHERE c.cafe_id=p_cafe_id),
 source AS(SELECT a.cost_center_id,(doc.created_at AT TIME ZONE 'Asia/Riyadh')::date dated,(line->>'debit')::numeric*a.percentage/100 debit,(line->>'credit')::numeric*a.percentage/100 credit FROM public.erp_accounting_allocations a JOIN public.bf_gl_drafts d ON d.cafe_id=a.cafe_id AND d.id=a.draft_id JOIN public.bf_documents doc ON doc.cafe_id=d.cafe_id AND doc.id=d.document_id CROSS JOIN LATERAL jsonb_array_elements(d.lines) WITH ORDINALITY x(line,n) WHERE a.cafe_id=p_cafe_id AND n=a.line_index+1
 UNION ALL SELECT a.cost_center_id,(doc.created_at AT TIME ZONE 'Asia/Riyadh')::date,(line->>'credit')::numeric*a.percentage/100,(line->>'debit')::numeric*a.percentage/100 FROM public.erp_accounting_allocations a JOIN public.bf_gl_drafts d ON d.cafe_id=a.cafe_id AND d.id=a.draft_id JOIN public.bf_documents doc ON doc.cafe_id=d.cafe_id AND doc.id=d.reversal_document_id CROSS JOIN LATERAL jsonb_array_elements(d.lines) WITH ORDINALITY x(line,n) WHERE a.cafe_id=p_cafe_id AND n=a.line_index+1),
 totals AS(SELECT c.id,c.code,c.name,c.is_group,c.parent_id,coalesce(sum(s.debit-s.credit) FILTER(WHERE s.dated<p_from),0) opening,coalesce(sum(s.debit) FILTER(WHERE s.dated BETWEEN p_from AND p_to),0) debit,coalesce(sum(s.credit) FILTER(WHERE s.dated BETWEEN p_from AND p_to),0) credit,coalesce(sum(s.debit-s.credit) FILTER(WHERE s.dated<=p_to),0) closing FROM public.erp_cost_centers c LEFT JOIN source s ON s.cost_center_id=c.id WHERE c.cafe_id=p_cafe_id AND(p_center IS NULL OR c.id IN(SELECT id FROM selected)) GROUP BY c.id)
 SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY code),'[]') INTO answer FROM totals t;
 RETURN jsonb_build_object('from',p_from,'to',p_to,'centerId',p_center,'currency','SAR','rows',answer);
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_accounting_read_before_scope(p_cafe_id uuid, p_query jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE answer jsonb;r text;BEGIN
 r:=erp_accounting_private.authorize(p_cafe_id);answer:=erp_accounting_private.gl_snapshot(p_cafe_id,coalesce((p_query->>'offset')::integer,0));
 IF p_query->>'id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(answer->'drafts') d WHERE d->>'id'=p_query->>'id') THEN
  answer:=jsonb_set(answer,'{drafts}',(answer->'drafts')||coalesce((SELECT jsonb_build_array(to_jsonb(d)-'cafe_id') FROM erp_branch_private.bf_gl_drafts d WHERE cafe_id=p_cafe_id AND id=(p_query->>'id')::uuid),'[]'::jsonb));
 END IF;
 answer:=answer||jsonb_build_object('canWrite',r<>'auditor','canSettings',r='owner','canApprove',r IN('owner','manager','accountant'),'costCenters',coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id' ORDER BY code) FROM erp_branch_private.erp_cost_centers x WHERE cafe_id=p_cafe_id),'[]'),'metadata',coalesce((SELECT jsonb_object_agg(draft_id,payload) FROM erp_branch_private.erp_accounting_metadata WHERE cafe_id=p_cafe_id),'{}'),'configuration',coalesce((SELECT payload||jsonb_build_object('revision',revision) FROM erp_branch_private.erp_accounting_settings WHERE cafe_id=p_cafe_id),'{"revision":0,"journalFields":[],"assetFields":[],"fiscalMonth":1}'::jsonb));
 RETURN erp_access_private.mask_snapshot(p_cafe_id,'accounting',answer);
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_accounting_write_before_scope(p_cafe_id uuid, p_action text, p_data jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;permission text;prior erp_accounting_private.requests;cmd jsonb:=jsonb_build_object('action',p_action,'data',p_data);result jsonb;payload jsonb;line jsonb;converted jsonb:='[]';rate numeric;currency text;rid uuid;revision integer;metadata jsonb;cfg jsonb;BEGIN
 permission:=CASE WHEN p_action IN('configuration','settings','period_close','period_reopen') THEN 'settings' WHEN p_action='cost_center_delete' THEN 'delete' WHEN p_action IN('save','account_save','cost_center') THEN CASE WHEN nullif(p_data->>'id','') IS NULL THEN 'create' ELSE 'update' END WHEN p_action IN('submit','approve','post','reverse','cancel') THEN 'approve' ELSE 'update' END;
 role_name:=erp_accounting_private.authorize(p_cafe_id,permission);
 IF p_request_id IS NULL OR p_action NOT IN('configuration','cost_center','cost_center_delete','save','submit','approve','post','reverse','cancel','account_save','period_close','period_reopen','settings') OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR octet_length(p_data::text)>400000 THEN RAISE EXCEPTION 'عملية الحسابات غير صالحة';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO prior FROM erp_accounting_private.requests WHERE cafe_id=p_cafe_id AND id=p_request_id;
 IF FOUND THEN IF prior.actor<>auth.uid() OR prior.command<>cmd THEN RAISE EXCEPTION 'معرف الطلب مستخدم ببيانات مختلفة';END IF;RETURN prior.result||'{"duplicate":true}'::jsonb;END IF;
 IF p_action='configuration' THEN
  PERFORM erp_manufacturing_private.validate_custom_fields(coalesce(p_data->'journalFields','[]'));PERFORM erp_manufacturing_private.validate_custom_fields(coalesce(p_data->'assetFields','[]'));
  IF coalesce((p_data->>'fiscalMonth')::integer,0) NOT BETWEEN 1 AND 12 THEN RAISE EXCEPTION 'اختر شهر بداية السنة المالية';END IF;
  IF (p_data->>'fiscalMonth')::integer<>coalesce((SELECT (s.payload->>'fiscalMonth')::integer FROM public.erp_accounting_settings s WHERE s.cafe_id=p_cafe_id),1) AND EXISTS(SELECT 1 FROM public.bf_gl_drafts WHERE cafe_id=p_cafe_id) THEN RAISE EXCEPTION 'تغيير بداية السنة متاح قبل تسجيل القيود للحفاظ على تسلسلها';END IF;
  SELECT s.revision INTO revision FROM public.erp_accounting_settings s WHERE cafe_id=p_cafe_id FOR UPDATE;IF coalesce(revision,0)<>coalesce((p_data->>'revision')::integer,0) THEN RAISE EXCEPTION 'تغيرت الإعدادات' USING ERRCODE='40001';END IF;
  INSERT INTO public.erp_accounting_settings(cafe_id,payload) VALUES(p_cafe_id,p_data) ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload,revision=erp_accounting_settings.revision+1 RETURNING jsonb_build_object('id',cafe_id,'revision',erp_accounting_settings.revision) INTO result;
 ELSIF p_action='cost_center' THEN result:=erp_accounting_private.save_cost_center(p_cafe_id,p_data);
 ELSIF p_action='cost_center_delete' THEN
  DELETE FROM public.erp_cost_centers WHERE cafe_id=p_cafe_id AND id=(p_data->>'id')::uuid AND erp_cost_centers.revision=(p_data->>'revision')::integer;
  IF NOT FOUND THEN RAISE EXCEPTION 'تغير مركز التكلفة' USING ERRCODE='40001';END IF;result:=jsonb_build_object('id',p_data->>'id','deleted',true);
 ELSE
  IF p_action='account_save' AND role_name NOT IN('owner','accountant') THEN RAISE EXCEPTION 'إدارة دليل الحسابات للمالك والمحاسب' USING ERRCODE='42501';END IF;
  INSERT INTO public.erp_accounting_settings(cafe_id) VALUES(p_cafe_id) ON CONFLICT DO NOTHING;
  SELECT s.payload INTO cfg FROM public.erp_accounting_settings s WHERE cafe_id=p_cafe_id;
  IF p_action='save' THEN
   currency:=coalesce(p_data->>'currency','SAR');rate:=coalesce((p_data->>'exchangeRate')::numeric,1);
   IF currency!~'^[A-Z]{3}$' OR rate<=0 OR rate>1000000 OR rate='NaN'::numeric OR(currency='SAR' AND rate<>1) THEN RAISE EXCEPTION 'راجع العملة وسعر الصرف';END IF;
   IF jsonb_typeof(p_data->'lines') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'أضف بنود القيد';END IF;
   FOR line IN SELECT * FROM jsonb_array_elements(p_data->'lines') LOOP
    converted:=converted||jsonb_build_array((line-'costCenters')||jsonb_build_object('debit',round((line->>'debit')::numeric*rate,2),'credit',round((line->>'credit')::numeric*rate,2)));
   END LOOP;
   payload:=(p_data-'customValues'-'currency'-'exchangeRate')||jsonb_build_object('lines',converted);
   result:=erp_accounting_private.gl_execute(p_cafe_id,p_action,payload,p_request_id);rid:=(result->>'id')::uuid;
   PERFORM erp_accounting_private.validate_custom_values(coalesce(cfg->'journalFields','[]'),coalesce(p_data->'customValues','{}'),p_cafe_id,rid,'journal',0,true);
   metadata:=jsonb_build_object('currency',currency,'exchangeRate',rate,'lines',p_data->'lines','customValues',coalesce(p_data->'customValues','{}'));
   INSERT INTO public.erp_accounting_metadata(cafe_id,draft_id,payload) VALUES(p_cafe_id,rid,metadata) ON CONFLICT(cafe_id,draft_id) DO UPDATE SET payload=excluded.payload;
   PERFORM erp_accounting_private.allocations(p_cafe_id,rid,p_data->'lines');
  ELSE
   IF p_action IN('submit','approve','post') THEN
    SELECT m.payload INTO metadata FROM public.erp_accounting_metadata m WHERE m.cafe_id=p_cafe_id AND m.draft_id=(p_data->>'id')::uuid;
    PERFORM erp_accounting_private.validate_custom_values(coalesce(cfg->'journalFields','[]'),coalesce(metadata->'customValues','{}'),p_cafe_id,(p_data->>'id')::uuid,'journal');
    IF EXISTS(SELECT 1 FROM public.erp_accounting_allocations a JOIN public.erp_cost_centers c ON c.cafe_id=a.cafe_id AND c.id=a.cost_center_id WHERE a.cafe_id=p_cafe_id AND a.draft_id=(p_data->>'id')::uuid AND(NOT c.active OR c.is_group)) THEN RAISE EXCEPTION 'أحد مراكز التكلفة لم يعد متاحًا';END IF;
   END IF;
   result:=erp_accounting_private.gl_execute(p_cafe_id,p_action,p_data,p_request_id);
  END IF;
 END IF;
 INSERT INTO erp_accounting_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),cmd,result);
 IF p_action IN('configuration','cost_center','cost_center_delete') THEN INSERT INTO public.bf_gl_events(cafe_id,entity_id,action,details,created_by) VALUES(p_cafe_id,(result->>'id')::uuid,p_action,jsonb_build_object('after',p_data),auth.uid());END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_asset_act_before_scope(p_cafe uuid, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE a public.erp_assets;action text:=p_command->>'action';rid uuid:=(p_command->>'id')::uuid;request uuid:=(p_command->>'requestId')::uuid;opdate date:=(p_command->>'date')::date;previous public.erp_asset_requests;result jsonb;d uuid;x jsonb;i integer;amount numeric:=0;tax numeric:=0;rate numeric:=0;qty integer;gross numeric;accum numeric;carrying numeric;difference numeric;cash uuid;counter uuid;selected uuid[];e uuid;available numeric;units numeric:=0;loops integer:=0;BEGIN PERFORM erp_access_private.assert_allowed(p_cafe,'assets',erp_access_private.action(p_command->>'action',p_command));
 PERFORM erp_asset_private.authorize(p_cafe,true);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 IF request IS NULL OR rid IS NULL OR length(coalesce(p_command->>'note',''))>4000 OR octet_length(p_command::text)>131072 THEN RAISE EXCEPTION 'طلب الأصل غير صالح';END IF;
 SELECT * INTO previous FROM public.erp_asset_requests WHERE cafe_id=p_cafe AND request_id=request;
 IF FOUND THEN IF previous.payload<>p_command OR previous.actor_id<>auth.uid() THEN RAISE EXCEPTION 'معرف الطلب مستخدم لمحتوى آخر';END IF;RETURN previous.result||'{"duplicate":true}';END IF;
 SELECT * INTO a FROM public.erp_assets WHERE cafe_id=p_cafe AND id=rid FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'الأصل غير موجود' USING ERRCODE='42501';END IF;
 IF a.revision IS DISTINCT FROM (p_command->>'revision')::integer THEN RAISE EXCEPTION 'تغير الأصل أعد تحميله' USING ERRCODE='40001';END IF;
 IF action NOT IN('note','delete') THEN PERFORM erp_asset_private.date_open(p_cafe,opdate);IF opdate<a.acquired_on THEN RAISE EXCEPTION 'تاريخ العملية يسبق شراء الأصل';END IF;END IF;
 result:=jsonb_build_object('id',rid);
 IF action='note' THEN IF length(btrim(coalesce(p_command->>'note','')))=0 THEN RAISE EXCEPTION 'أدخل الملاحظة';END IF;
 ELSIF action='delete' THEN
  IF a.status<>'draft' THEN RAISE EXCEPTION 'يمكن حذف المسودة فقط استخدم استبعاد للأصل المرحل';END IF;
  DELETE FROM public.erp_asset_events WHERE cafe_id=p_cafe AND asset_id=rid;DELETE FROM public.erp_assets WHERE cafe_id=p_cafe AND id=rid;result:=result||'{"deleted":true}';
 ELSIF action='purchase' THEN
  IF a.status<>'draft' THEN RAISE EXCEPTION 'تم ترحيل الشراء مسبقًا';END IF;
  PERFORM erp_asset_private.validate(p_cafe,a.payload);cash:=(a.payload->>'cashAccountId')::uuid;
  SELECT vat_rate INTO rate FROM public.bf_settings WHERE cafe_id=p_cafe;tax:=CASE WHEN a.payload->'taxes' @> '["vat"]' THEN round(a.purchase_cost*coalesce(rate,0)/100,2) ELSE 0 END;
  IF coalesce((SELECT sum(debit-credit) FROM public.bf_journal WHERE cafe_id=p_cafe AND account_id=cash),0)<a.purchase_cost+tax THEN RAISE EXCEPTION 'الرصيد النقدي غير كاف لشراء الأصل';END IF;
  d:=erp_asset_private.document(p_cafe,opdate,a.purchase_cost+tax,'شراء الأصل '||a.code,auth.uid());
  PERFORM erp_asset_private.line(p_cafe,d,(a.payload->>'assetAccountId')::uuid,a.purchase_cost,0);PERFORM erp_asset_private.line(p_cafe,d,brand_finance_private.account(p_cafe,'1300'),tax,0);PERFORM erp_asset_private.line(p_cafe,d,cash,0,a.purchase_cost+tax);
  FOR i IN 0..a.quantity-1 LOOP x:=CASE WHEN (a.payload->>'individualUnits')::boolean THEN a.payload->'units'->i ELSE a.payload->'units'->0 END;
   INSERT INTO public.erp_asset_units(cafe_id,asset_id,unit_index,serial,barcode,employee_id,location_id,description) VALUES(p_cafe,rid,i,CASE WHEN i=0 OR (a.payload->>'individualUnits')::boolean THEN coalesce(x->>'serial','') ELSE '' END,coalesce(x->>'barcode',''),nullif(x->>'employeeId','')::uuid,nullif(x->>'locationId','')::uuid,coalesce(x->>'description',''));
  END LOOP;
  UPDATE public.erp_assets SET status='in_service',gross_value=purchase_cost,purchase_document_id=d WHERE cafe_id=p_cafe AND id=rid;amount:=a.purchase_cost;
 ELSIF action IN('depreciate','run_due','edit_depreciation') THEN
  IF a.status<>'in_service' THEN RAISE EXCEPTION 'الأصل غير متاح للإهلاك';END IF;
  IF action IN('depreciate','edit_depreciation') THEN
   IF action='edit_depreciation' THEN
    SELECT id INTO e FROM public.erp_asset_events WHERE cafe_id=p_cafe AND asset_id=rid AND id=(p_command->>'eventId')::uuid AND manufacturing_order_id IS NULL;
    IF e IS NULL THEN RAISE EXCEPTION 'حركة الإهلاك غير موجودة في هذا الأصل';END IF;
    PERFORM erp_asset_private.reverse_depreciation(p_cafe,e,opdate,auth.uid());
   END IF;
   units:=erp_manufacturing_private.money(coalesce(p_command->'units','0'));
   amount:=CASE WHEN a.payload->>'method'='units' THEN round(units*(a.purchase_cost-a.residual_value)/(a.payload->>'totalUnits')::numeric,2) ELSE round(erp_manufacturing_private.money(p_command->'amount'),2) END;
   e:=erp_asset_private.depreciate(p_cafe,rid,amount,units,opdate,auth.uid());
  ELSE
   IF a.payload->>'method' NOT IN('straight_line','declining') OR a.next_depreciation_on IS NULL OR a.next_depreciation_on>opdate THEN RAISE EXCEPTION 'لا يوجد إهلاك دوري مستحق';END IF;
   WHILE a.next_depreciation_on<=opdate AND loops<1200 LOOP
    available:=a.gross_value-a.accumulated_depreciation-round(a.residual_value*a.remaining_quantity/a.quantity,2);EXIT WHEN available<=0;
    amount:=least(available,greatest(.01,CASE WHEN a.payload->>'method'='declining' THEN round((a.gross_value-a.accumulated_depreciation)*(a.payload->>'depreciationRate')::numeric/100,2) ELSE round((a.payload->>'depreciationAmount')::numeric*a.remaining_quantity/a.quantity,2) END));EXIT WHEN amount<=0;
    e:=erp_asset_private.depreciate(p_cafe,rid,amount,0,a.next_depreciation_on,auth.uid(),'scheduled_depreciation');
    UPDATE public.erp_assets SET next_depreciation_on=erp_asset_private.next_date((a.payload->>'depreciationStarts')::date,next_depreciation_on,(a.payload->>'intervalMonths')::integer) WHERE cafe_id=p_cafe AND id=rid;
    SELECT * INTO a FROM public.erp_assets WHERE cafe_id=p_cafe AND id=rid;loops:=loops+1;
   END LOOP;
   IF loops=0 THEN RAISE EXCEPTION 'اكتمل إهلاك القيمة القابلة للإهلاك';END IF;
  END IF;
 ELSIF action='reverse_depreciation' THEN
  SELECT id INTO e FROM public.erp_asset_events WHERE cafe_id=p_cafe AND asset_id=rid AND id=(p_command->>'eventId')::uuid AND manufacturing_order_id IS NULL;
  IF e IS NULL THEN RAISE EXCEPTION 'اختر إهلاكًا يدويًا أو دوريًا من هذا الأصل';END IF;e:=erp_asset_private.reverse_depreciation(p_cafe,e,opdate,auth.uid());
 ELSIF action IN('sell','write_off','revalue') THEN
  IF a.status<>'in_service' THEN RAISE EXCEPTION 'الأصل غير متاح للعملية';END IF;
  qty:=(p_command->>'quantity')::integer;IF qty NOT BETWEEN 1 AND a.remaining_quantity THEN RAISE EXCEPTION 'الكمية تتجاوز الوحدات المتاحة';END IF;
  IF action IN('sell','write_off') AND EXISTS(SELECT 1 FROM public.erp_mfg_orders o JOIN public.erp_mfg_workstations w ON w.cafe_id=o.cafe_id AND w.payload->>'assetId'=rid::text WHERE o.cafe_id=p_cafe AND o.status IN('ready','in_progress') AND o.payload->'operations' @> jsonb_build_array(jsonb_build_object('workstationId',w.id))) THEN RAISE EXCEPTION 'الأصل مرتبط بأمر تصنيع مفتوح';END IF;
  gross:=CASE WHEN qty=a.remaining_quantity THEN a.gross_value ELSE round(a.gross_value*qty/a.remaining_quantity,2) END;accum:=CASE WHEN qty=a.remaining_quantity THEN a.accumulated_depreciation ELSE round(a.accumulated_depreciation*qty/a.remaining_quantity,2) END;carrying:=gross-accum;
  amount:=round(erp_manufacturing_private.money(coalesce(p_command->'amount','0')),2);counter:=nullif(p_command->>'accountId','')::uuid;
  IF action='revalue' THEN
   difference:=amount-carrying;IF difference=0 OR amount<round(a.residual_value*qty/a.quantity,2) THEN RAISE EXCEPTION 'قيمة التقييم غير صالحة';END IF;
   PERFORM erp_asset_private.account(p_cafe,counter,CASE WHEN difference>0 THEN ARRAY['equity'] ELSE ARRAY['expense'] END);
   d:=erp_asset_private.document(p_cafe,opdate,abs(difference),'إعادة تقييم الأصل '||a.code,auth.uid());PERFORM erp_asset_private.line(p_cafe,d,(a.payload->>'assetAccountId')::uuid,greatest(difference,0),greatest(-difference,0));PERFORM erp_asset_private.line(p_cafe,d,counter,greatest(-difference,0),greatest(difference,0));
   UPDATE public.erp_assets SET gross_value=gross_value+difference WHERE cafe_id=p_cafe AND id=rid;
  ELSE
   SELECT coalesce(array_agg(id),'{}') INTO selected FROM (SELECT id FROM public.erp_asset_units WHERE cafe_id=p_cafe AND asset_id=rid AND status='in_service' AND (coalesce(jsonb_array_length(p_command->'unitIds'),0)=0 OR id IN(SELECT value::uuid FROM jsonb_array_elements_text(p_command->'unitIds'))) ORDER BY unit_index LIMIT qty) u;
   IF cardinality(selected)<>qty OR (coalesce(jsonb_array_length(p_command->'unitIds'),0)>0 AND jsonb_array_length(p_command->'unitIds')<>qty) THEN RAISE EXCEPTION 'اختر الوحدات المطلوب استبعادها';END IF;
   IF action='sell' THEN
    cash:=counter;PERFORM erp_asset_private.account(p_cafe,cash,ARRAY['cash','bank','pos']);SELECT vat_rate INTO rate FROM public.bf_settings WHERE cafe_id=p_cafe;
    IF coalesce(jsonb_typeof(p_command->'taxes'),'array')<>'array' OR coalesce(jsonb_array_length(p_command->'taxes'),0)>1 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(p_command->'taxes','[]')) x WHERE x<>'vat') THEN RAISE EXCEPTION 'الضريبة غير صالحة';END IF;
    tax:=CASE WHEN p_command->'taxes' @> '["vat"]' THEN round(amount*coalesce(rate,0)/100,2) ELSE 0 END;
   ELSE amount:=0;PERFORM erp_asset_private.account(p_cafe,counter,ARRAY['expense']);END IF;
   d:=erp_asset_private.document(p_cafe,opdate,greatest(gross,amount+tax),CASE WHEN action='sell' THEN 'بيع الأصل ' ELSE 'تكهين الأصل ' END||a.code,auth.uid());
   PERFORM erp_asset_private.line(p_cafe,d,(a.payload->>'accumulatedAccountId')::uuid,accum,0);PERFORM erp_asset_private.line(p_cafe,d,(a.payload->>'assetAccountId')::uuid,0,gross);
   IF action='sell' THEN PERFORM erp_asset_private.line(p_cafe,d,cash,amount+tax,0);PERFORM erp_asset_private.line(p_cafe,d,brand_finance_private.account(p_cafe,'2100'),0,tax);counter:=brand_finance_private.account(p_cafe,CASE WHEN amount>=carrying THEN '4100' ELSE '5410' END);END IF;
   PERFORM erp_asset_private.line(p_cafe,d,counter,greatest(carrying-amount,0),greatest(amount-carrying,0));
   UPDATE public.erp_asset_units SET status='disposed' WHERE cafe_id=p_cafe AND id=ANY(selected);
   UPDATE public.erp_assets SET gross_value=gross_value-gross,accumulated_depreciation=accumulated_depreciation-accum,remaining_quantity=remaining_quantity-qty,status=CASE WHEN remaining_quantity=qty THEN 'disposed' ELSE 'in_service' END WHERE cafe_id=p_cafe AND id=rid;
  END IF;
 ELSE RAISE EXCEPTION 'إجراء أصل غير معروف';END IF;
 IF action<>'delete' THEN
  UPDATE public.erp_assets SET revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe AND id=rid;
  IF action NOT IN('depreciate','edit_depreciation','run_due','reverse_depreciation') THEN INSERT INTO public.erp_asset_events(cafe_id,asset_id,action,effective_on,amount,quantity,note,payload,document_id,created_by) VALUES(p_cafe,rid,action,coalesce(opdate,(now() AT TIME ZONE 'Asia/Riyadh')::date),amount,coalesce(qty,0),coalesce(p_command->>'note',''),p_command,d,auth.uid());END IF;
  SELECT result||jsonb_build_object('revision',revision,'eventId',e,'documentId',d) INTO result FROM public.erp_assets WHERE cafe_id=p_cafe AND id=rid;
 END IF;
 INSERT INTO public.erp_asset_requests(cafe_id,request_id,payload,result,actor_id) VALUES(p_cafe,request,p_command,result,auth.uid());RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_asset_import_before_scope(p_cafe uuid, p_rows jsonb, p_post boolean DEFAULT false, p_request uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE previous public.erp_asset_requests;req jsonb;row jsonb;result jsonb;ids jsonb:='[]';BEGIN PERFORM erp_access_private.assert_allowed(p_cafe,'assets','create'); IF p_post THEN PERFORM erp_access_private.assert_allowed(p_cafe,'assets','approve');END IF;
 PERFORM erp_asset_private.authorize(p_cafe,true);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 IF p_request IS NULL OR coalesce(jsonb_typeof(p_rows),'')<>'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 100 OR octet_length(p_rows::text)>2097152 THEN RAISE EXCEPTION 'بيانات استيراد الأصول غير صالحة';END IF;
 req:=jsonb_build_object('import',p_rows,'post',p_post);SELECT * INTO previous FROM public.erp_asset_requests WHERE cafe_id=p_cafe AND request_id=p_request;
 IF FOUND THEN IF previous.payload<>req OR previous.actor_id<>auth.uid() THEN RAISE EXCEPTION 'تعارض معرف الاستيراد';END IF;RETURN previous.result||'{"duplicate":true}';END IF;
 FOR row IN SELECT value FROM jsonb_array_elements(p_rows) LOOP result:=public.erp_asset_save(p_cafe,row,NULL,0,p_post,gen_random_uuid());ids:=ids||jsonb_build_array(result->>'id');END LOOP;
 result:=jsonb_build_object('ids',ids,'count',jsonb_array_length(ids));INSERT INTO public.erp_asset_requests(cafe_id,request_id,payload,result,actor_id) VALUES(p_cafe,p_request,req,result,auth.uid());RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_asset_location_before_scope(p_cafe uuid, p_name text, p_description text DEFAULT ''::text, p_id uuid DEFAULT NULL::uuid, p_revision integer DEFAULT 0, p_delete boolean DEFAULT false, p_request uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE rid uuid:=coalesce(p_id,gen_random_uuid());previous public.erp_asset_requests;req jsonb;result jsonb;BEGIN PERFORM erp_access_private.assert_allowed(p_cafe,'assets',CASE WHEN p_delete THEN 'delete' ELSE 'settings' END);
 PERFORM erp_asset_private.authorize(p_cafe,true);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 req:=jsonb_build_object('location',p_id,'name',p_name,'description',p_description,'revision',p_revision,'delete',p_delete);
 SELECT * INTO previous FROM public.erp_asset_requests WHERE cafe_id=p_cafe AND request_id=p_request;
 IF FOUND THEN IF previous.payload<>req OR previous.actor_id<>auth.uid() THEN RAISE EXCEPTION 'تعارض معرف الطلب';END IF;RETURN previous.result||'{"duplicate":true}';END IF;
 IF p_request IS NULL OR length(btrim(coalesce(p_name,''))) NOT BETWEEN 1 AND 150 OR length(coalesce(p_description,''))>4000 THEN RAISE EXCEPTION 'أدخل اسم موقع ووصفًا صالحين';END IF;
 IF p_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_asset_locations WHERE cafe_id=p_cafe AND id=p_id AND revision=p_revision) THEN RAISE EXCEPTION 'الموقع غير موجود أو تغير أعد تحميله' USING ERRCODE='40001';END IF;
