  IF p_data->>'expenseAccountId' IS NOT NULL THEN PERFORM erp_asset_private.account(p_cafe_id,(p_data->>'expenseAccountId')::uuid,ARRAY['expense','equity']);END IF;
  IF p_data->>'receiptAccountId' IS NOT NULL THEN PERFORM erp_asset_private.account(p_cafe_id,(p_data->>'receiptAccountId')::uuid,ARRAY['revenue','equity']);END IF;
  SELECT revision INTO rev FROM public.erp_finance_settings WHERE cafe_id=p_cafe_id FOR UPDATE;IF coalesce(rev,0) IS DISTINCT FROM(p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت الإعدادات' USING ERRCODE='40001';END IF;
  INSERT INTO public.erp_finance_settings(cafe_id,payload) VALUES(p_cafe_id,p_data) ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload,revision=erp_finance_settings.revision+1;i:=p_cafe_id;
 ELSIF p_action='schedule' THEN i:=erp_finance_private.save_schedule(p_cafe_id,p_data);
 ELSIF p_action='generate_schedule' THEN result:=erp_finance_private.generate_schedule(p_cafe_id,i);
 ELSIF p_action='import_bank' THEN i:=erp_finance_private.import_statement(p_cafe_id,p_data);
 ELSIF p_action IN('match_bank','unmatch_bank') THEN i:=erp_finance_private.match_statement(p_cafe_id,p_data,p_action='unmatch_bank');
 ELSE RAISE EXCEPTION 'إجراء مالي غير صالح';END IF;
 result:=coalesce(result,'{}')||jsonb_build_object('id',i);PERFORM erp_finance_private.event(p_cafe_id,i,p_action,p_data);
 INSERT INTO erp_finance_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),cmd,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_installments_write_before_scope(p_cafe_id uuid, p_action text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;previous public.erp_installment_requests;d public.bf_documents;old_schedule jsonb;state jsonb;result jsonb;payment jsonb;part record;amount numeric;account public.bf_accounts;
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'installments',erp_access_private.action(p_action,p_payload));
 role_name:=brand_finance_private.role_for(p_cafe_id);IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'لا تملك صلاحية تعديل الأقساط' USING ERRCODE='42501';END IF;
 IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>250000 THEN RAISE EXCEPTION 'طلب غير صالح' USING ERRCODE='22023';END IF;
 -- Same lock and ordering as all financial postings and payment corrections.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO previous FROM public.erp_installment_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF previous.actor<>auth.uid() OR previous.action IS DISTINCT FROM p_action OR previous.payload IS DISTINCT FROM p_payload THEN RAISE EXCEPTION 'معرف الطلب مستخدم لتغيير آخر' USING ERRCODE='40001';END IF;RETURN previous.result;END IF;
 IF p_action IN('schedule','collect') THEN
  SELECT * INTO d FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=(p_payload->>'documentId')::uuid AND kind='sale' FOR UPDATE;
  IF NOT FOUND OR d.party_id IS NULL THEN RAISE EXCEPTION 'اختر فاتورة مرتبطة بعميل في هذه العلامة' USING ERRCODE='42501';END IF;
  SELECT metadata->'schedule' INTO old_schedule FROM public.bf_invoice_management WHERE cafe_id=p_cafe_id AND document_id=d.id;
  IF coalesce(old_schedule,'null') IS DISTINCT FROM p_payload->'expectedSchedule' THEN RAISE EXCEPTION 'تغيرت اتفاقية التقسيط' USING ERRCODE='40001';END IF;
  IF p_action='schedule' THEN
   IF NOT p_payload?'schedule' THEN RAISE EXCEPTION 'أرسل جدول الأقساط أو طلب إزالته صراحة' USING ERRCODE='22023';END IF;
   -- Existing sales management validates and persists the single source schedule.
   PERFORM public.brand_finance_invoice_management(p_cafe_id,jsonb_build_object('action','schedule','ids',jsonb_build_array(d.id),'schedule',p_payload->'schedule'));
   PERFORM 1 FROM erp_installment_private.rows(d.total,d.total,0,p_payload->'schedule');
   result:=jsonb_build_object('id',d.id);
  ELSE
   state:=brand_finance_private.document_state(p_cafe_id,d.id);
   IF (state->>'outstanding')::numeric IS DISTINCT FROM (p_payload->>'expectedOutstanding')::numeric THEN RAISE EXCEPTION 'تغير رصيد الفاتورة' USING ERRCODE='40001';END IF;
   SELECT * INTO part FROM erp_installment_private.rows(d.total,(state->>'outstanding')::numeric,(state->>'refunded_total')::numeric,old_schedule) r WHERE r.remaining>0 ORDER BY r.number LIMIT 1;
   IF NOT FOUND OR part.number IS DISTINCT FROM (p_payload->>'number')::integer THEN RAISE EXCEPTION 'ابدأ بتحصيل القسط الأقدم غير المسدد' USING ERRCODE='22023';END IF;
   amount:=(p_payload->>'amount')::numeric;
   IF amount IS NULL OR amount<.01 OR amount<>round(amount,2) OR amount>part.remaining OR amount>1000000000 THEN RAISE EXCEPTION 'المبلغ يتجاوز المتبقي في القسط' USING ERRCODE='22023';END IF;
   SELECT * INTO account FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=(p_payload->>'accountId')::uuid AND active AND deleted_at IS NULL AND NOT frozen AND NOT is_group AND NOT is_cashier_drawer AND kind IN('cash','bank','pos');
   IF NOT FOUND THEN RAISE EXCEPTION 'اختر حساب تحصيل إداريًا نشطًا' USING ERRCODE='22023';END IF;
   result:=public.brand_finance_execute(p_cafe_id,'settlement',jsonb_build_object('documentId',d.id,'accountId',account.id,'amount',amount,'note',left(coalesce(p_payload->>'details',''),500)),p_request_id);
   payment:=jsonb_build_object('amount',amount,'date',p_payload->>'date','accountId',account.id,'status',p_payload->>'status','collectorId',p_payload->>'collectorId','reference',p_payload->>'reference','details',p_payload->>'details','receiptNote',p_payload->>'receiptNote','attachments',coalesce(p_payload->'attachments','[]'));
   PERFORM public.brand_finance_manage_invoice_payment(p_cafe_id,jsonb_build_object('action','save','invoiceId',d.id,'paymentId',result->>'id','revision',0,'requestId',gen_random_uuid(),'payload',payment));
   result:=result||jsonb_build_object('invoiceId',d.id,'installment',part.number);
  END IF;
 ELSE RAISE EXCEPTION 'إجراء الأقساط غير معروف' USING ERRCODE='22023';END IF;
 INSERT INTO public.erp_installment_requests(cafe_id,request_id,actor,action,payload,result) VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_payload,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_insurance_write_before_scope(p_cafe uuid, p_action text, p_input jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i uuid;rev integer;old_rev integer;prior erp_insurance_private.requests;result jsonb;cl public.erp_insurance_classes;b public.erp_insurance_invoices;amount numeric;maximum numeric;payer text;document uuid;company uuid;customer uuid;
BEGIN
 IF p_request IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>100000 OR p_action NOT IN('company','class','enrollment','company_delete','class_delete','prepare','collect','unlink') THEN RAISE EXCEPTION 'الإجراء غير صالح';END IF;
 rev:=coalesce((p_input->>'revision')::integer,0);PERFORM erp_insurance_private.authorize(p_cafe,CASE WHEN p_action='collect' THEN 'approve' WHEN p_action LIKE '%_delete' OR p_action='unlink' THEN 'delete' WHEN p_action='prepare' THEN 'create' WHEN rev=0 THEN 'create' ELSE 'update' END);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67953));
 SELECT * INTO prior FROM erp_insurance_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>p_action OR prior.input<>p_input THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN prior.result;END IF;
 i:=nullif(p_input->>'id','')::uuid;
 IF p_action IN('company','company_delete') THEN
  SELECT revision INTO old_rev FROM public.erp_insurance_companies WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF coalesce(old_rev,0)<>rev THEN RAISE EXCEPTION 'تغيرت شركة التأمين' USING ERRCODE='40001';END IF;
  IF p_action='company_delete' THEN DELETE FROM public.erp_insurance_companies WHERE cafe_id=p_cafe AND id=i;IF NOT FOUND THEN RAISE EXCEPTION 'الشركة غير متاحة';END IF;
  ELSE
   IF jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' OR(coalesce(p_input->>'email','')<>'' AND(p_input->>'email')!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') OR(coalesce(p_input->>'website','')<>'' AND(p_input->>'website')!~'^https?://[^[:space:]]+$') THEN RAISE EXCEPTION 'راجع البريد والموقع وحالة الشركة';END IF;
   INSERT INTO public.erp_insurance_companies(cafe_id,id,name,phone,email,website,active,revision) VALUES(p_cafe,i,btrim(p_input->>'name'),coalesce(p_input->>'phone',''),coalesce(p_input->>'email',''),coalesce(p_input->>'website',''),(p_input->>'active')::boolean,rev+1) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,phone=excluded.phone,email=excluded.email,website=excluded.website,active=excluded.active,revision=excluded.revision;
  END IF;
 ELSIF p_action IN('class','class_delete') THEN
  SELECT * INTO cl FROM public.erp_insurance_classes WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF coalesce(cl.revision,0)<>rev THEN RAISE EXCEPTION 'تغيرت فئة التأمين' USING ERRCODE='40001';END IF;
  IF p_action='class_delete' THEN DELETE FROM public.erp_insurance_classes WHERE cafe_id=p_cafe AND id=i;IF NOT FOUND THEN RAISE EXCEPTION 'الفئة غير متاحة';END IF;
  ELSE
   company:=(p_input->>'companyId')::uuid;IF NOT EXISTS(SELECT 1 FROM public.erp_insurance_companies WHERE cafe_id=p_cafe AND id=company AND active) OR(cl.id IS NOT NULL AND cl.company_id<>company) OR jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'شركة التأمين غير متاحة أو تغيرت';END IF;
   PERFORM erp_insurance_private.validate_rules(p_cafe,p_input->'rules');
   INSERT INTO public.erp_insurance_classes(cafe_id,id,company_id,name,active,rules,revision) VALUES(p_cafe,i,company,btrim(p_input->>'name'),(p_input->>'active')::boolean,p_input->'rules',rev+1) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,active=excluded.active,rules=excluded.rules,revision=excluded.revision;
  END IF;
 ELSIF p_action='enrollment' THEN
  customer:=(p_input->>'customerId')::uuid;i:=customer;IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=customer AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
  SELECT revision INTO old_rev FROM public.erp_insurance_enrollments WHERE cafe_id=p_cafe AND customer_id=customer FOR UPDATE;IF coalesce(old_rev,0)<>rev THEN RAISE EXCEPTION 'تغير تأمين العميل' USING ERRCODE='40001';END IF;
  company:=nullif(p_input->>'companyId','')::uuid;
  IF company IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_insurance_classes x JOIN public.erp_insurance_companies c ON c.cafe_id=x.cafe_id AND c.id=x.company_id WHERE x.cafe_id=p_cafe AND x.id=(p_input->>'classId')::uuid AND x.company_id=company AND x.active AND c.active) THEN RAISE EXCEPTION 'شركة أو فئة التأمين غير متاحة';END IF;
  INSERT INTO public.erp_insurance_enrollments VALUES(p_cafe,customer,company,nullif(p_input->>'classId','')::uuid,coalesce(p_input->>'number',''),rev+1) ON CONFLICT(cafe_id,customer_id) DO UPDATE SET company_id=excluded.company_id,class_id=excluded.class_id,number=excluded.number,revision=excluded.revision;
 ELSIF p_action='prepare' THEN result:=erp_insurance_private.prepare(p_cafe,(p_input->>'draftId')::uuid,rev);i:=(result->>'id')::uuid;
 ELSIF p_action='unlink' THEN
  SELECT * INTO b FROM public.erp_insurance_invoices WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF b.id IS NULL OR b.revision<>rev THEN RAISE EXCEPTION 'تغير ربط التأمين' USING ERRCODE='40001';END IF;IF b.invoice_id IS NOT NULL THEN RAISE EXCEPTION 'لا يمكن تغيير فئة التأمين بعد إصدار الفاتورة';END IF;DELETE FROM public.erp_insurance_invoices WHERE cafe_id=p_cafe AND id=i;
 ELSIF p_action='collect' THEN
  SELECT * INTO b FROM public.erp_insurance_invoices WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF b.invoice_id IS NULL OR b.coverage IS NULL THEN RAISE EXCEPTION 'أصدر الفاتورة قبل التحصيل';END IF;
  payer:=p_input->>'payer';amount:=(p_input->>'amount')::numeric;IF coalesce(payer,'') NOT IN('company','customer') OR amount IS NULL OR amount<=0 OR amount>1e9 OR amount<>round(amount,2) THEN RAISE EXCEPTION 'راجع الجهة الدافعة ومبلغ التحصيل';END IF;
  maximum:=least((b.coverage->>payer)::numeric-erp_insurance_private.collected(p_cafe,b.id,payer),(brand_finance_private.document_state(p_cafe,b.invoice_id)->>'outstanding')::numeric);
  IF amount>maximum OR coalesce((brand_finance_private.document_state(p_cafe,b.invoice_id)->>'refunded_total')::numeric,0)>0 THEN RAISE EXCEPTION 'التحصيل يتجاوز الحصة المتفق عليها أو المتبقي على الفاتورة';END IF;
  result:=public.brand_finance_execute(p_cafe,'settlement',jsonb_build_object('documentId',b.invoice_id,'accountId',p_input->>'accountId','amount',amount,'note',left(CASE WHEN payer='company' THEN 'تحصيل حصة شركة التأمين '||(SELECT name FROM public.erp_insurance_companies WHERE cafe_id=p_cafe AND id=b.company_id) ELSE 'تحصيل حصة العميل' END||' — '||coalesce(p_input->>'note',''),1000)),p_request);
  document:=(result->>'id')::uuid;IF NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=p_cafe AND id=document AND kind='settlement' AND reference_id=b.invoice_id) THEN RAISE EXCEPTION 'لم يثبت التحصيل على فاتورة المالية';END IF;
  INSERT INTO public.erp_insurance_collections VALUES(p_cafe,b.id,document,payer);result:=jsonb_build_object('id',b.id,'paymentId',document);
 END IF;
 result:=coalesce(result,jsonb_build_object('id',i,'revision',rev+1,'deleted',p_action LIKE '%_delete' OR p_action='unlink'));
 INSERT INTO public.erp_insurance_events(cafe_id,record_id,action,actor) VALUES(p_cafe,i,p_action,auth.uid());INSERT INTO erp_insurance_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_inventory_read_before_scope(p_cafe uuid, p_query jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE r jsonb;items jsonb;stock jsonb;BEGIN
 r:=erp_inventory_private.erp_inventory_read_before_lifecycle(p_cafe,p_query);
 SELECT coalesce(jsonb_agg(x||jsonb_build_object('reserved',q.reserved,'available',(x->>'quantity')::numeric-q.reserved)),'[]') INTO stock FROM jsonb_array_elements(r->'stock')x CROSS JOIN LATERAL(SELECT erp_inventory_private.reserved(p_cafe,(x->>'item_id')::uuid,(x->>'warehouse_id')::uuid) reserved)q;
 SELECT coalesce(jsonb_agg(x||jsonb_build_object('reserved',q.reserved,'available',(x->>'quantity')::numeric-q.reserved)),'[]') INTO items FROM jsonb_array_elements(r->'items')x CROSS JOIN LATERAL(SELECT coalesce(sum((b->>'reserved')::numeric),0) reserved FROM jsonb_array_elements(stock)b WHERE b->>'item_id'=x->>'id')q;
 RETURN r||jsonb_build_object('items',items,'stock',stock);
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_inventory_write_before_scope(p_cafe uuid, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE a text:=p_command->>'action';p jsonb:=p_command->'payload';i uuid:=nullif(p_command->>'id','')::uuid;r jsonb;d public.erp_inventory_documents;cfg jsonb;l public.erp_inventory_lines;k text;BEGIN
 PERFORM erp_inventory_private.authorize(p_cafe,'read');PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 IF EXISTS(SELECT 1 FROM erp_inventory_private.requests WHERE cafe_id=p_cafe AND request_id=(p_command->>'requestId')::uuid) THEN RETURN erp_inventory_private.erp_inventory_write_before_lifecycle(p_cafe,p_command);END IF;
 SELECT payload INTO cfg FROM public.erp_inventory_settings WHERE cafe_id=p_cafe;
 IF a='settings' THEN
  FOREACH k IN ARRAY ARRAY['bundlesEnabled','showAvailableStock','countByDate'] LOOP IF p?k AND jsonb_typeof(p->k) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع خيارات المخزون';END IF;END LOOP;
  IF nullif(p->>'defaultAdjustmentAccountId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe AND id=(p->>'defaultAdjustmentAccountId')::uuid AND active AND kind IN('expense','equity') AND NOT coalesce(is_group,false) AND NOT coalesce(frozen,false) AND deleted_at IS NULL) THEN RAISE EXCEPTION 'اختر حساب تسوية نشطًا';END IF;
 ELSIF a='item' AND coalesce(p#>'{payload,bundleComponents}','[]')<>'[]'::jsonb THEN
  IF p->>'kind'<>'product' OR NOT coalesce((cfg->>'bundlesEnabled')::boolean,false) AND NOT EXISTS(SELECT 1 FROM public.erp_inventory_items WHERE cafe_id=p_cafe AND item_id=i AND payload->'bundleComponents'=p#>'{payload,bundleComponents}') THEN RAISE EXCEPTION 'فعّل نظام التجميعات للصنف المخزني';END IF;
  PERFORM erp_inventory_private.validate_bundle(p_cafe,i,p#>'{payload,bundleComponents}');
 ELSIF a='document' THEN
  IF p#>'{payload,reserveStock}' IS NOT NULL AND jsonb_typeof(p#>'{payload,reserveStock}') IS DISTINCT FROM 'boolean' OR p#>'{payload,countByDate}' IS NOT NULL AND jsonb_typeof(p#>'{payload,countByDate}') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع خيارات الحجز والجرد';END IF;
  IF p->>'kind' IN('assembly','disassembly') THEN
   IF NOT coalesce((cfg->>'bundlesEnabled')::boolean,false) AND i IS NULL THEN RAISE EXCEPTION 'فعّل نظام التجميعات من إعدادات المخزون';END IF;
   PERFORM erp_inventory_private.validate_bundle(p_cafe,(p#>>'{payload,bundleItemId}')::uuid,p->'lines');
   IF jsonb_typeof(p#>'{payload,bundleQuantity}') IS DISTINCT FROM 'number' OR(p#>>'{payload,bundleQuantity}')::numeric<=0 OR(p#>>'{payload,bundleQuantity}')::numeric>1000000 OR(p#>>'{payload,bundleQuantity}')::numeric<>round((p#>>'{payload,bundleQuantity}')::numeric,3) OR NOT EXISTS(SELECT 1 FROM public.erp_inventory_items WHERE cafe_id=p_cafe AND item_id=(p#>>'{payload,bundleItemId}')::uuid AND kind='product' AND status='active') THEN RAISE EXCEPTION 'حدد الصنف المركب والكمية';END IF;
  END IF;
 ELSIF a='submit' THEN
  SELECT * INTO d FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND id=i;
  IF d.payload->>'reserveStock'='true' THEN
   IF NOT EXISTS(SELECT 1 FROM public.erp_inventory_lines WHERE cafe_id=p_cafe AND document_id=i) THEN RAISE EXCEPTION 'أضف مكونات الحجز';END IF;
   FOR l IN SELECT * FROM public.erp_inventory_lines WHERE cafe_id=p_cafe AND document_id=i LOOP
    IF l.quantity<=0 OR coalesce((SELECT quantity FROM public.bf_stock WHERE cafe_id=p_cafe AND item_id=l.item_id AND warehouse_id=d.warehouse_id),0)-erp_inventory_private.reserved(p_cafe,l.item_id,d.warehouse_id,i)<l.quantity*l.factor THEN RAISE EXCEPTION 'الكمية المتاحة لا تكفي للحجز';END IF;
   END LOOP;
  END IF;
 END IF;
 r:=erp_inventory_private.erp_inventory_write_before_lifecycle(p_cafe,p_command);
 IF a IN('document','import_warehouse','sync_count') THEN
  SELECT * INTO d FROM public.erp_inventory_documents WHERE cafe_id=p_cafe AND id=(r->>'id')::uuid;
  IF d.kind='request' AND d.status='pending' AND d.payload->>'reserveStock'='true' THEN
   FOR l IN SELECT * FROM public.erp_inventory_lines WHERE cafe_id=p_cafe AND document_id=d.id LOOP
    IF l.quantity<=0 OR coalesce((SELECT quantity FROM public.bf_stock WHERE cafe_id=p_cafe AND item_id=l.item_id AND warehouse_id=d.warehouse_id),0)-erp_inventory_private.reserved(p_cafe,l.item_id,d.warehouse_id,d.id)<l.quantity*l.factor THEN RAISE EXCEPTION 'الكمية المتاحة لا تكفي لتعديل الحجز';END IF;
   END LOOP;
  END IF;
  IF a='document' AND nullif(d.payload->>'accountId','') IS NULL AND nullif(cfg->>'defaultAdjustmentAccountId','') IS NOT NULL THEN UPDATE public.erp_inventory_documents SET payload=payload||jsonb_build_object('accountId',cfg->>'defaultAdjustmentAccountId') WHERE cafe_id=p_cafe AND id=d.id;END IF;
  IF d.kind='stocktake' THEN
   IF NOT(d.payload?'countByDate') THEN d.payload:=d.payload||jsonb_build_object('countByDate',coalesce((cfg->>'countByDate')::boolean,false));UPDATE public.erp_inventory_documents SET payload=d.payload WHERE cafe_id=p_cafe AND id=d.id;END IF;
   IF d.payload->>'countByDate'='true' OR a='sync_count' THEN UPDATE public.erp_inventory_lines AS counted_line SET expected_quantity=erp_inventory_private.count_quantity(p_cafe,counted_line.item_id,d) WHERE counted_line.cafe_id=p_cafe AND counted_line.document_id=d.id;END IF;
  END IF;
 END IF;RETURN r;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_manufacturing_act_before_scope(p_cafe_id uuid, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE kind text:=p_command->>'kind'; action text:=p_command->>'action'; rid uuid:=(p_command->>'id')::uuid; reqid uuid:=(p_command->>'requestId')::uuid;
 tab text; old jsonb; body jsonb; x jsonb; y jsonb; bom jsonb; station jsonb; issue record; journal record; ord record; src record;
 existing public.erp_mfg_requests%ROWTYPE; result jsonb; document uuid; wip uuid; inventory uuid; wid uuid:=nullif(p_command->>'warehouseId','')::uuid;
 q numeric; need numeric; actual numeric:=0; total numeric:=0; extra numeric:=0; salvage numeric:=0; weight numeric; denominator numeric; share numeric; left_amount numeric;
 item uuid; new_id uuid; new_code text; settings jsonb; source_amount numeric; supplied numeric; cost_before numeric; note text:=coalesce(p_command->>'note','');
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'manufacturing',erp_access_private.action(p_command->>'action',p_command));
 PERFORM erp_manufacturing_private.authorize(p_cafe_id,true);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
