  FOR journal IN SELECT * FROM public.bf_journal WHERE cafe_id=p_cafe_id AND document_id=(old->>'output_document_id')::uuid LOOP PERFORM brand_finance_private.line(p_cafe_id,document,journal.account_id,journal.credit,journal.debit);END LOOP;
  IF total<>cost_before THEN PERFORM brand_finance_private.line(p_cafe_id,document,inventory,greatest(cost_before-total,0),greatest(total-cost_before,0));PERFORM brand_finance_private.line(p_cafe_id,document,brand_finance_private.account(p_cafe_id,'5200'),greatest(total-cost_before,0),greatest(cost_before-total,0));END IF;
  SELECT coalesce((payload->>'additionalCost')::numeric,0) INTO extra FROM public.erp_mfg_events WHERE cafe_id=p_cafe_id AND kind='orders' AND record_id=rid AND action='finish' ORDER BY created_at DESC LIMIT 1;
  UPDATE public.erp_mfg_orders SET status='in_progress',output_quantity=0,output_document_id=NULL,additional_cost=greatest(0,additional_cost-coalesce(extra,0)) WHERE cafe_id=p_cafe_id AND id=rid;
  UPDATE public.erp_mfg_plans SET status='in_progress',revision=revision+1 WHERE cafe_id=p_cafe_id AND id=(old->>'plan_id')::uuid;
 ELSE RAISE EXCEPTION 'الإجراء غير متاح لهذا السجل';
 END IF;
 IF action NOT IN('delete','copy') THEN EXECUTE format('UPDATE public.%I SET revision=revision+1,updated_at=now() WHERE cafe_id=$1 AND id=$2',tab) USING p_cafe_id,rid;END IF;
 INSERT INTO public.erp_mfg_events(cafe_id,record_id,kind,action,note,payload,document_id,actor_id) VALUES(p_cafe_id,rid,kind,action,note,p_command||result,document,auth.uid());
 INSERT INTO public.erp_mfg_requests(cafe_id,request_id,payload,result,actor_id) VALUES(p_cafe_id,reqid,p_command,result,auth.uid());RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_manufacturing_read_before_scope(p_cafe_id uuid, p_kind text DEFAULT 'orders'::text, p_id uuid DEFAULT NULL::uuid, p_query text DEFAULT ''::text, p_status text DEFAULT ''::text, p_page integer DEFAULT 1, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE result jsonb;items jsonb;BEGIN
 result:=erp_inventory_private.manufacturing_read_before_tracking(p_cafe_id,p_kind,p_id,p_query,p_status,p_page,p_filters);
 SELECT coalesce(jsonb_agg(x||jsonb_build_object('trackingMode',coalesce((SELECT tracking_mode FROM erp_branch_private.erp_inventory_items WHERE cafe_id=p_cafe_id AND item_id=(x->>'id')::uuid),'quantity'))),'[]') INTO items FROM jsonb_array_elements(result#>'{lookups,items}') x;
 RETURN jsonb_set(result,'{lookups,items}',items);
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_manufacturing_save_before_scope(p_cafe_id uuid, p_kind text, p_payload jsonb, p_id uuid DEFAULT NULL::uuid, p_revision integer DEFAULT 0, p_draft boolean DEFAULT false, p_request_id uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tab text; old jsonb; result jsonb; req jsonb; existing public.erp_mfg_requests%ROWTYPE; next_status text; rid uuid:=coalesce(p_id,gen_random_uuid()); BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'manufacturing',CASE WHEN p_kind='settings' THEN 'settings' WHEN p_revision=0 THEN 'create' ELSE 'update' END); IF p_kind IN('orders','plans') AND NOT p_draft THEN PERFORM erp_access_private.assert_allowed(p_cafe_id,'manufacturing','approve');END IF;
 PERFORM erp_manufacturing_private.authorize(p_cafe_id,true,p_kind='settings');
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 req:=jsonb_build_object('kind',p_kind,'payload',p_payload,'id',p_id,'revision',p_revision,'draft',p_draft);
 SELECT * INTO existing FROM public.erp_mfg_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF existing.payload<>req OR existing.actor_id<>auth.uid() THEN RAISE EXCEPTION 'تعارض معرف الطلب';END IF;RETURN existing.result||'{"duplicate":true}';END IF;
 IF p_kind='settings' THEN
  IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>262144 OR coalesce(jsonb_typeof(p_payload->'autoStartOrders'),'')<>'boolean' OR coalesce(jsonb_typeof(p_payload->'allowPartialMaterials'),'')<>'boolean' THEN RAISE EXCEPTION 'إعدادات التصنيع غير صالحة';END IF;
  IF EXISTS(SELECT 1 FROM unnest(ARRAY['orderStatuses','planStatuses','orderFields','planFields','orderForms','planForms']) k WHERE coalesce(jsonb_typeof(p_payload->k),'')<>'array' OR jsonb_array_length(p_payload->k)>100) THEN RAISE EXCEPTION 'إعدادات الحقول أو الحالات غير صالحة';END IF;
  PERFORM erp_manufacturing_private.validate_custom_fields(p_payload->'orderFields');PERFORM erp_manufacturing_private.validate_custom_fields(p_payload->'planFields');
  PERFORM erp_manufacturing_private.validate_custom_fields(form->'fields') FROM jsonb_array_elements((p_payload->'orderForms')||(p_payload->'planForms')) form;
  INSERT INTO public.erp_mfg_settings(cafe_id,revision,value) VALUES(p_cafe_id,1,p_payload) ON CONFLICT(cafe_id) DO UPDATE SET value=excluded.value,revision=erp_mfg_settings.revision+1,updated_at=now() WHERE erp_mfg_settings.revision=p_revision RETURNING jsonb_build_object('revision',revision) INTO result;
  IF result IS NULL OR (p_revision>0 AND (result->>'revision')::integer=1) THEN RAISE EXCEPTION 'تغيرت الإعدادات أعد تحميل الصفحة' USING ERRCODE='40001';END IF;
 ELSE
  tab:=erp_manufacturing_private.table_name(p_kind);IF tab IS NULL THEN RAISE EXCEPTION 'نوع التصنيع غير صالح';END IF;
  PERFORM erp_manufacturing_private.validate(p_cafe_id,p_kind,p_payload);
  IF p_kind IN('orders','plans') THEN
   p_payload:=jsonb_set(p_payload,'{customValues}',erp_manufacturing_private.custom_defaults(coalesce((SELECT value->CASE p_kind WHEN 'orders' THEN 'orderFields' ELSE 'planFields' END FROM public.erp_mfg_settings WHERE cafe_id=p_cafe_id),'[]'),coalesce(p_payload->'customValues','{}')));
   PERFORM erp_manufacturing_private.validate_custom_values(coalesce((SELECT value->CASE p_kind WHEN 'orders' THEN 'orderFields' ELSE 'planFields' END FROM public.erp_mfg_settings WHERE cafe_id=p_cafe_id),'[]'),coalesce(p_payload->'customValues','{}'),p_cafe_id,p_id,p_kind,0,p_draft);
  END IF;
  IF p_id IS NOT NULL THEN
   EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE cafe_id=$1 AND id=$2 FOR UPDATE',tab) INTO old USING p_cafe_id,p_id;
   IF old IS NULL THEN RAISE EXCEPTION 'السجل غير موجود' USING ERRCODE='42501';END IF;
   IF (old->>'revision')::integer IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'تغير السجل أعد تحميل الصفحة' USING ERRCODE='40001';END IF;
   IF p_kind IN('orders','plans','overheads') AND old->>'status' NOT IN('draft','ready') THEN RAISE EXCEPTION 'السجل المرحل لا يقبل تعديل البيانات';END IF;
   IF p_kind='plans' AND EXISTS(SELECT 1 FROM public.erp_mfg_orders WHERE cafe_id=p_cafe_id AND plan_id=p_id) THEN RAISE EXCEPTION 'لا تعدل خطة صدر منها أمر تصنيع';END IF;
  END IF;
  next_status:=CASE WHEN p_kind IN('bom','workstations') THEN CASE WHEN coalesce((p_payload->>'active')::boolean,true) THEN 'active' ELSE 'inactive' END WHEN p_kind='routings' THEN 'active' WHEN p_draft THEN 'draft' ELSE 'ready' END;
  IF p_kind='bom' AND coalesce((p_payload->>'isDefault')::boolean,false) THEN UPDATE public.erp_mfg_boms SET payload=jsonb_set(payload,'{isDefault}','false'),revision=revision+1 WHERE cafe_id=p_cafe_id AND id<>rid AND payload->>'productId'=p_payload->>'productId' AND payload->>'isDefault'='true';END IF;
  IF p_id IS NULL THEN EXECUTE format('INSERT INTO public.%I(id,cafe_id,name,code,status,payload,created_by) VALUES($1,$2,$3,$4,$5,$6,$7)',tab) USING rid,p_cafe_id,btrim(p_payload->>'name'),btrim(p_payload->>'code'),next_status,p_payload,auth.uid();
  ELSE EXECUTE format('UPDATE public.%I SET name=$3,code=$4,status=$5,payload=$6,revision=revision+1,updated_at=now() WHERE cafe_id=$1 AND id=$2',tab) USING p_cafe_id,rid,btrim(p_payload->>'name'),btrim(p_payload->>'code'),next_status,p_payload;END IF;
  result:=jsonb_build_object('id',rid,'revision',p_revision+1);
  INSERT INTO public.erp_mfg_events(cafe_id,record_id,kind,action,actor_id) VALUES(p_cafe_id,rid,p_kind,CASE WHEN p_id IS NULL THEN 'create' ELSE 'edit' END,auth.uid());
 END IF;
 INSERT INTO public.erp_mfg_requests(cafe_id,request_id,payload,result,actor_id) VALUES(p_cafe_id,p_request_id,req,result,auth.uid());RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_memberships_write_before_scope(p_cafe uuid, p_action text, p_input jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.erp_memberships;r public.erp_membership_renewals;first_r public.erp_membership_renewals;last_r public.erp_membership_renewals;prior erp_membership_private.requests;customer uuid;package uuid;joined date;ends date;snapshot jsonb;d public.bf_invoice_drafts;payload jsonb;tax numeric;total numeric;result jsonb;member_extension integer;
BEGIN
 IF p_action<>'edit_full' THEN RETURN public.erp_memberships_write_before_edit(p_cafe,p_action,p_input,p_request);END IF;
 PERFORM erp_membership_private.authorize(p_cafe,'update');PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67951));
 IF p_request IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>16000 THEN RAISE EXCEPTION 'بيانات التعديل غير صالحة';END IF;
 SELECT * INTO prior FROM erp_membership_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>'edit_full' OR prior.input<>p_input THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN prior.result;END IF;
 PERFORM erp_membership_private.sync(p_cafe);
 SELECT * INTO m FROM public.erp_memberships WHERE cafe_id=p_cafe AND id=(p_input->>'id')::uuid AND NOT deleted FOR UPDATE;
 IF m.id IS NULL THEN RAISE EXCEPTION 'العضوية غير متاحة';END IF;IF m.revision IS DISTINCT FROM (p_input->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت العضوية' USING ERRCODE='40001';END IF;
 customer:=(p_input->>'customerId')::uuid;package:=(p_input->>'packageId')::uuid;joined:=(p_input->>'joinedOn')::date;ends:=nullif(p_input->>'endsOn','')::date;
 IF customer IS NULL OR package IS NULL OR joined IS NULL OR NOT isfinite(joined) OR(ends IS NOT NULL AND(NOT isfinite(ends) OR ends<joined)) OR length(coalesce(p_input->>'description',''))>4000 THEN RAISE EXCEPTION 'راجع العميل والباقة وفترة العضوية';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=customer AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
 IF customer<>m.customer_id OR package<>m.package_id THEN
  IF(SELECT count(*) FROM public.erp_membership_renewals WHERE cafe_id=p_cafe AND membership_id=m.id)<>1 OR EXISTS(SELECT 1 FROM public.erp_membership_renewals WHERE cafe_id=p_cafe AND membership_id=m.id AND(invoice_id IS NOT NULL OR activated_at IS NOT NULL)) THEN RAISE EXCEPTION 'العميل والباقة مرتبطان باشتراك مصدر أو مفعل ولا يمكن نقلهما';END IF;
  SELECT * INTO r FROM public.erp_membership_renewals WHERE cafe_id=p_cafe AND membership_id=m.id FOR UPDATE;
  snapshot:=erp_membership_private.package(p_cafe,package);IF snapshot IS NULL OR NOT(snapshot->>'active')::boolean OR snapshot->>'kind'<>'membership' THEN RAISE EXCEPTION 'باقة العضوية غير متاحة';END IF;
  IF EXISTS(SELECT 1 FROM public.erp_credit_package_lines l JOIN public.erp_credit_types t ON t.cafe_id=l.cafe_id AND t.id=l.type_id WHERE l.cafe_id=p_cafe AND l.package_id=package AND NOT t.active) THEN RAISE EXCEPTION 'نوع رصيد الباقة غير نشط';END IF;
  SELECT * INTO d FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe AND id=r.draft_id FOR UPDATE;
  IF d.id IS NULL OR EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE cafe_id=p_cafe AND draft_id=d.id) THEN RAISE EXCEPTION 'المسودة غير متاحة للتعديل';END IF;
  IF EXISTS(SELECT 1 FROM public.erp_insurance_invoices WHERE cafe_id=p_cafe AND draft_id=d.id) THEN RAISE EXCEPTION 'ألغ ربط التأمين بالمسودة قبل تغيير اشتراكها';END IF;
  tax:=coalesce((d.payload#>>'{invoice,lines,0,vatRate}')::numeric,15);total:=(snapshot->>'price')::numeric+round((snapshot->>'price')::numeric*tax/100,2);
  payload:=d.payload;payload:=jsonb_set(payload,'{invoice,partyId}',to_jsonb(customer));payload:=jsonb_set(payload,'{invoice,lines}',jsonb_build_array(jsonb_build_object('key',1,'productId','','quantity',1,'price',snapshot->'price','name',snapshot->>'name','kind','service','vatRate',tax,'taxCategory',CASE WHEN tax=0 THEN 'O' ELSE 'S' END,'exemptionReason',CASE WHEN tax=0 THEN 'خدمة غير خاضعة للضريبة وفق إعدادات الفواتير' ELSE '' END)));payload:=jsonb_set(payload,'{invoice,discountValue}','0');payload:=jsonb_set(payload,'{invoice,taxInclusive}','false');payload:=jsonb_set(payload,'{invoice,currency}','"SAR"');payload:=jsonb_set(payload,'{invoice,exchangeRate}','1');payload:=jsonb_set(payload,'{invoice,adjustment}','null');
  IF total=0 THEN UPDATE public.erp_membership_renewals SET draft_id=NULL WHERE cafe_id=p_cafe AND id=r.id;DELETE FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe AND id=d.id;ELSE PERFORM public.brand_finance_save_invoice_draft(p_cafe,d.id,d.revision,payload);END IF;
  UPDATE public.erp_membership_renewals SET customer_id=customer,package_id=package,package_snapshot=snapshot,invoice_total=total WHERE cafe_id=p_cafe AND id=r.id;
 END IF;
 SELECT * INTO first_r FROM public.erp_membership_renewals WHERE cafe_id=p_cafe AND membership_id=m.id AND activated_at IS NOT NULL ORDER BY starts_on,created_at,id LIMIT 1;
 SELECT * INTO last_r FROM public.erp_membership_renewals WHERE cafe_id=p_cafe AND membership_id=m.id AND activated_at IS NOT NULL ORDER BY ends_on DESC,created_at DESC,id DESC LIMIT 1;
 IF first_r.id IS NULL THEN IF ends IS NOT NULL THEN RAISE EXCEPTION 'تحدد نهاية العضوية عند تفعيل الاشتراك بعد السداد';END IF;
 ELSE
  IF ends IS NULL OR joined>erp_membership_private.end_date(p_cafe,first_r.id) OR ends<last_r.starts_on OR EXISTS(SELECT 1 FROM public.erp_membership_renewals WHERE cafe_id=p_cafe AND membership_id=m.id AND activated_at IS NOT NULL AND id<>last_r.id AND erp_membership_private.end_date(p_cafe,id)>ends) THEN RAISE EXCEPTION 'الفترة الجديدة تتعارض مع مدد الاشتراكات المسجلة';END IF;
  SELECT coalesce(sum(ends_on-starts_on+1),0)::integer INTO member_extension FROM public.erp_membership_freezes WHERE cafe_id=p_cafe AND renewal_id=last_r.id AND NOT voided AND extend_membership;
  IF ends-member_extension<(CASE WHEN first_r.id=last_r.id THEN joined ELSE last_r.starts_on END) THEN RAISE EXCEPTION 'نهاية الفترة الأساسية تسبق بدايتها بعد احتساب التوقف';END IF;
  UPDATE public.erp_membership_renewals SET starts_on=joined WHERE cafe_id=p_cafe AND id=first_r.id;
  UPDATE public.erp_membership_renewals SET ends_on=ends-member_extension WHERE cafe_id=p_cafe AND id=last_r.id;
  IF EXISTS(SELECT 1 FROM public.erp_membership_freezes f JOIN public.erp_membership_renewals rr ON rr.cafe_id=f.cafe_id AND rr.id=f.renewal_id WHERE f.cafe_id=p_cafe AND f.membership_id=m.id AND NOT f.voided AND(f.starts_on<rr.starts_on OR f.starts_on>erp_membership_private.end_date(p_cafe,rr.id))) THEN RAISE EXCEPTION 'الفترة الجديدة تستبعد فترة توقف مسجلة';END IF;
  UPDATE public.erp_credit_charges SET starts_on=joined WHERE cafe_id=p_cafe AND source_kind='membership_renewal' AND source_id=first_r.id;
  IF EXISTS(SELECT 1 FROM public.erp_credit_allocations a JOIN public.erp_credit_usages u ON u.cafe_id=a.cafe_id AND u.id=a.usage_id JOIN public.erp_credit_charges ch ON ch.cafe_id=a.cafe_id AND ch.id=a.charge_id JOIN public.erp_membership_renewals rr ON rr.cafe_id=ch.cafe_id AND rr.id=ch.source_id WHERE a.cafe_id=p_cafe AND rr.membership_id=m.id AND(u.used_on<rr.starts_on OR u.used_on>erp_membership_private.end_date(p_cafe,rr.id,true))) THEN RAISE EXCEPTION 'الفترة الجديدة تستبعد استهلاك رصيد مسجل';END IF;
 END IF;
 UPDATE public.erp_memberships SET customer_id=customer,package_id=package,joined_on=joined,description=coalesce(p_input->>'description',''),revision=revision+1 WHERE cafe_id=p_cafe AND id=m.id;
 PERFORM erp_membership_private.sync(p_cafe);result:=jsonb_build_object('id',m.id);
 INSERT INTO public.erp_membership_events(cafe_id,membership_id,record_id,action,actor) VALUES(p_cafe,m.id,m.id,'edit_full',auth.uid());INSERT INTO erp_membership_private.requests VALUES(p_cafe,p_request,auth.uid(),'edit_full',p_input,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_payroll_import_before_scope(p_cafe_id uuid, p_kind text, p_rows jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE previous erp_payroll_private.requests;row jsonb;ids jsonb:='[]';rid uuid;result jsonb;body jsonb:=jsonb_build_object('kind',p_kind,'rows',p_rows);BEGIN
 PERFORM erp_payroll_private.authorize(p_cafe_id,true);
 PERFORM erp_payroll_private.access(p_cafe_id,'create');
 IF p_kind NOT IN('contract','payslip') OR p_request_id IS NULL OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 100 OR octet_length(p_rows::text)>1000000 THEN RAISE EXCEPTION 'استورد من صف إلى مائة صف صالح';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,95500));
 SELECT * INTO previous FROM erp_payroll_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF previous.actor<>auth.uid() OR previous.action<>'import' OR previous.payload<>body THEN RAISE EXCEPTION 'معرف الاستيراد مستخدم لعملية أخرى';END IF;RETURN previous.result;END IF;
 FOR row IN SELECT * FROM jsonb_array_elements(p_rows) LOOP
  IF row->>'id' IS NOT NULL OR coalesce((row->>'revision')::integer,0)<>0 THEN RAISE EXCEPTION 'الاستيراد مخصص لسجلات جديدة';END IF;
  rid:=erp_payroll_private.save_record(p_cafe_id,p_kind,row);ids:=ids||jsonb_build_array(rid);
  INSERT INTO public.erp_payroll_events(cafe_id,record_id,action,actor) VALUES(p_cafe_id,rid,'import',auth.uid());
 END LOOP;
 result:=jsonb_build_object('ids',ids,'count',jsonb_array_length(ids));INSERT INTO erp_payroll_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),'import',body,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_payroll_write_before_scope(p_cafe_id uuid, p_action text, p_data jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<command>>
DECLARE role_name text;rid uuid:=(p_data->>'id')::uuid;kind text:=p_data->>'kind';r public.erp_payroll_records;previous erp_payroll_private.requests;result jsonb;rev integer;doc uuid;row record;portion numeric;remaining numeric;amount numeric;settings jsonb;p jsonb;BEGIN
 role_name:=erp_payroll_private.authorize(p_cafe_id,true,p_action IN('approve','cancel','pay','reverse_payment','repay','reverse_repayment','renew','settings'));
 PERFORM erp_payroll_private.access(p_cafe_id,CASE WHEN p_action='settings' THEN 'settings' WHEN p_action='delete' THEN 'delete' WHEN p_action IN('component','structure','contract','run','payslip','loan') THEN CASE WHEN coalesce((p_data->>'revision')::integer,0)=0 THEN 'create' ELSE 'update' END WHEN p_action IN('generate','related_form') THEN 'create' ELSE 'approve' END);
 IF p_action='renew' THEN PERFORM erp_payroll_private.access(p_cafe_id,'create');END IF;
 IF p_request_id IS NULL OR p_action NOT IN('component','structure','contract','run','payslip','loan','settings','delete','approve','reject','cancel','renew','generate','pay','reverse_payment','repay','reverse_repayment','related_form') OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR octet_length(p_data::text)>500000 THEN RAISE EXCEPTION 'طلب المرتبات غير صالح';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,95500));
 SELECT * INTO previous FROM erp_payroll_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF previous.actor<>auth.uid() OR previous.action<>p_action OR previous.payload<>p_data THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى' USING ERRCODE='22023';END IF;RETURN previous.result;END IF;
 IF p_action='component' THEN
  IF length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 150 OR coalesce(p_data->>'code','')!~'^[a-z][a-z_]{0,39}$' OR p_data->>'code'=ANY(ARRAY['basic','days','period_days','worked','scheduled','late','early','overtime','absent','leave','holiday','earnings','deductions']) OR coalesce(p_data->>'kind','') NOT IN('earning','deduction') OR coalesce(p_data->>'method','') NOT IN('amount','formula') OR jsonb_typeof(p_data->'active') IS DISTINCT FROM 'boolean' OR coalesce((p_data->>'amount')::numeric,-1)<0 OR(p_data->>'amount')::numeric>1000000000 OR(p_data->>'amount')::numeric='NaN'::numeric THEN RAISE EXCEPTION 'راجع بيانات بند الراتب ورمزه';END IF;
  IF p_data->>'accountId' IS NOT NULL THEN PERFORM erp_asset_private.account(p_cafe_id,(p_data->>'accountId')::uuid,CASE WHEN p_data->>'kind'='earning' THEN ARRAY['expense'] ELSE ARRAY['expense','other_liability','payable','other_asset','receivable'] END);END IF;
  IF rid IS NOT NULL THEN SELECT revision INTO rev FROM public.erp_salary_components WHERE cafe_id=p_cafe_id AND id=rid FOR UPDATE;IF NOT FOUND OR rev<>(p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير البند أعد تحميله' USING ERRCODE='40001';END IF;END IF;
  rid:=coalesce(rid,gen_random_uuid());INSERT INTO public.erp_salary_components(id,cafe_id,name,code,kind,active,payload) VALUES(rid,p_cafe_id,btrim(p_data->>'name'),p_data->>'code',p_data->>'kind',(p_data->>'active')::boolean,p_data) ON CONFLICT(id) DO UPDATE SET name=excluded.name,code=excluded.code,kind=excluded.kind,active=excluded.active,payload=excluded.payload,revision=erp_salary_components.revision+1;
 ELSIF p_action='structure' THEN
  PERFORM erp_payroll_private.validate(p_cafe_id,'structure',p_data);PERFORM erp_payroll_private.calculate(p_cafe_id,p_data);
  IF length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 150 OR jsonb_typeof(p_data->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'أدخل اسم القالب وحالته';END IF;
  IF rid IS NOT NULL THEN SELECT revision INTO rev FROM public.erp_salary_structures WHERE cafe_id=p_cafe_id AND id=rid FOR UPDATE;IF NOT FOUND OR rev<>(p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير القالب أعد تحميله' USING ERRCODE='40001';END IF;END IF;
  rid:=coalesce(rid,gen_random_uuid());INSERT INTO public.erp_salary_structures(id,cafe_id,name,active,payload) VALUES(rid,p_cafe_id,btrim(p_data->>'name'),(p_data->>'active')::boolean,p_data) ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active,payload=excluded.payload,revision=erp_salary_structures.revision+1;
 ELSIF p_action IN('contract','run','payslip','loan') THEN rid:=erp_payroll_private.save_record(p_cafe_id,p_action,p_data);
 ELSIF p_action='related_form' THEN
  SELECT * INTO r FROM public.erp_payroll_records WHERE cafe_id=p_cafe_id AND id=rid AND erp_payroll_records.kind='contract' FOR UPDATE;
  IF NOT FOUND OR r.revision<>(p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير العقد أعد تحميله' USING ERRCODE='40001';END IF;
  SELECT value INTO p FROM public.erp_payroll_settings st CROSS JOIN LATERAL jsonb_array_elements(st.payload->'relatedForms') WHERE st.cafe_id=p_cafe_id AND value->>'id'=p_data->>'formId' AND(value->>'active')::boolean;
  IF p IS NULL THEN RAISE EXCEPTION 'النموذج غير متاح';END IF;
  PERFORM erp_payroll_private.validate_custom_values(p->'fields',coalesce(p_data->'values','{}'),p_cafe_id,rid,NULL);
  INSERT INTO public.erp_payroll_events(cafe_id,record_id,action,actor,detail) VALUES(p_cafe_id,rid,'related_form',auth.uid(),jsonb_build_object('formId',p->>'id','name',p->>'name','fields',p->'fields','values',p_data->'values'));
  UPDATE public.erp_payroll_records SET revision=revision+1 WHERE id=rid;
 ELSIF p_action='settings' THEN
  PERFORM erp_payroll_private.validate_mudad(p_cafe_id,p_data->'mudad');
  PERFORM erp_manufacturing_private.validate_custom_fields(coalesce(p_data->'contractFields','[]'));
  IF jsonb_typeof(coalesce(p_data->'relatedForms','[]'))<>'array' OR jsonb_array_length(coalesce(p_data->'relatedForms','[]'))>30 THEN RAISE EXCEPTION 'قائمة النماذج غير صالحة';END IF;
  FOR p IN SELECT * FROM jsonb_array_elements(coalesce(p_data->'relatedForms','[]')) LOOP
   IF coalesce(p->>'id','')!~'^[a-z][a-z0-9_]{0,59}$' OR length(btrim(coalesce(p->>'name',''))) NOT BETWEEN 1 AND 150 OR jsonb_typeof(p->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'بيانات النموذج غير صالحة';END IF;PERFORM erp_manufacturing_private.validate_custom_fields(p->'fields');
  END LOOP;
  PERFORM erp_asset_private.account(p_cafe_id,(p_data->>'expenseAccountId')::uuid,ARRAY['expense']);PERFORM erp_asset_private.account(p_cafe_id,(p_data->>'payableAccountId')::uuid,ARRAY['other_liability','payable']);PERFORM erp_asset_private.account(p_cafe_id,(p_data->>'receivableAccountId')::uuid,ARRAY['other_asset','receivable']);PERFORM erp_asset_private.account(p_cafe_id,(p_data->>'commissionAccountId')::uuid,ARRAY['expense']);
  IF p_data->>'emailTemplateId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_document_templates WHERE cafe_id=p_cafe_id AND id=(p_data->>'emailTemplateId')::uuid AND channel='email') THEN RAISE EXCEPTION 'قالب البريد غير متاح';END IF;
  SELECT revision INTO rev FROM public.erp_payroll_settings WHERE cafe_id=p_cafe_id FOR UPDATE;IF coalesce(rev,0)<>(p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت إعدادات المرتبات' USING ERRCODE='40001';END IF;
  INSERT INTO public.erp_payroll_settings(cafe_id,payload) VALUES(p_cafe_id,p_data) ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload,revision=erp_payroll_settings.revision+1;rid:=p_cafe_id;PERFORM erp_payroll_private.configure_email(p_cafe_id);
 ELSIF kind IN('component','structure') THEN
  IF p_action<>'delete' THEN RAISE EXCEPTION 'الإجراء غير مناسب لهذا النوع';END IF;
  IF kind='component' THEN
   IF EXISTS(SELECT 1 FROM public.erp_payroll_settings st WHERE st.cafe_id=p_cafe_id AND jsonb_path_exists(st.payload->'mudad','$.** ? (@ == $item)',jsonb_build_object('item',rid::text))) THEN RAISE EXCEPTION 'البند مرتبط بإعدادات مدد أزل التعيين قبل الحذف';END IF;
   IF EXISTS(SELECT 1 FROM public.erp_salary_structures WHERE cafe_id=p_cafe_id AND EXISTS(SELECT 1 FROM jsonb_array_elements(payload->'lines')x WHERE x->>'componentId'=rid::text)) OR EXISTS(SELECT 1 FROM public.erp_payroll_records WHERE cafe_id=p_cafe_id AND EXISTS(SELECT 1 FROM jsonb_array_elements(payload->'lines')x WHERE x->>'componentId'=rid::text)) THEN RAISE EXCEPTION 'البند مستخدم في قالب أو مستند عطله بدل حذفه';END IF;
   DELETE FROM public.erp_salary_components WHERE cafe_id=p_cafe_id AND id=rid AND revision=(p_data->>'revision')::integer;
  ELSE IF EXISTS(SELECT 1 FROM public.erp_payroll_records WHERE cafe_id=p_cafe_id AND payload->>'structureId'=rid::text) THEN RAISE EXCEPTION 'القالب مستخدم في عقد';END IF;DELETE FROM public.erp_salary_structures WHERE cafe_id=p_cafe_id AND id=rid AND revision=(p_data->>'revision')::integer;END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'تغير السجل أو لم يعد موجودًا' USING ERRCODE='40001';END IF;
 ELSE
  SELECT * INTO r FROM public.erp_payroll_records WHERE cafe_id=p_cafe_id AND id=rid AND erp_payroll_records.kind=command.kind FOR UPDATE;
  IF NOT FOUND OR r.revision<>(p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير السجل أعد تحميله' USING ERRCODE='40001';END IF;
  IF p_action='approve' THEN PERFORM erp_payroll_private.approve(p_cafe_id,rid);
  ELSIF p_action='generate' THEN IF r.kind<>'run' THEN RAISE EXCEPTION 'التوليد متاح للمسير فقط';END IF;PERFORM erp_payroll_private.generate(p_cafe_id,rid);
  ELSIF p_action='pay' THEN PERFORM erp_payroll_private.pay(p_cafe_id,rid,(p_data->>'accountId')::uuid,(p_data->>'date')::date);
  ELSIF p_action='cancel' THEN PERFORM erp_payroll_private.cancel(p_cafe_id,rid,coalesce((p_data->>'date')::date,current_date));
  ELSIF p_action='reject' THEN IF r.status<>'draft' THEN RAISE EXCEPTION 'رفض المسودة فقط';END IF;UPDATE public.erp_payroll_records SET status='rejected',revision=revision+1 WHERE id=rid;
  ELSIF p_action='delete' THEN IF r.status NOT IN('draft','rejected') THEN RAISE EXCEPTION 'السجل المعتمد محمي من الحذف';END IF;DELETE FROM public.erp_payroll_records WHERE id=rid;
  ELSIF p_action='reverse_payment' THEN
   IF r.kind<>'payslip' OR r.status<>'paid' THEN RAISE EXCEPTION 'اعكس صرف قسيمة مدفوعة';END IF;
   IF r.payment_id IS NOT NULL THEN doc:=erp_payroll_private.reverse(p_cafe_id,r.payment_id,(p_data->>'date')::date,'عكس صرف راتب #'||r.code);END IF;
   UPDATE public.erp_payroll_records SET status='approved',paid=0,payment_id=NULL,revision=revision+1 WHERE id=rid;
   UPDATE public.erp_payroll_records SET status='approved',paid=0,revision=revision+1 WHERE id=r.run_id AND status='paid';
  ELSIF p_action='renew' THEN
   IF r.kind<>'contract' OR r.status NOT IN('active','closed') THEN RAISE EXCEPTION 'جدد عقدًا نشطًا أو منتهيًا';END IF;
   rid:=erp_payroll_private.renew(p_cafe_id,r.id);
  ELSIF p_action='reverse_repayment' THEN
   IF r.kind<>'loan' OR r.status NOT IN('active','closed') THEN RAISE EXCEPTION 'اعكس تحصيل سلفة قائمة';END IF;
   SELECT x.document_id INTO doc FROM public.erp_payroll_loan_payments x JOIN public.erp_payroll_loan_installments li ON li.id=x.installment_id WHERE x.cafe_id=p_cafe_id AND x.id=(p_data->>'paymentId')::uuid AND li.loan_id=r.id AND x.payslip_id IS NULL AND NOT x.reversed;
   IF NOT FOUND THEN RAISE EXCEPTION 'التحصيل غير متاح للعكس أو مرتبط بقسيمة راتب';END IF;
   SELECT sum(x.amount) INTO amount FROM public.erp_payroll_loan_payments x JOIN public.erp_payroll_loan_installments li ON li.id=x.installment_id WHERE x.cafe_id=p_cafe_id AND x.document_id=doc AND li.loan_id=r.id AND NOT x.reversed;
   FOR row IN SELECT x.* FROM public.erp_payroll_loan_payments x JOIN public.erp_payroll_loan_installments li ON li.id=x.installment_id WHERE x.cafe_id=p_cafe_id AND x.document_id=doc AND li.loan_id=r.id AND NOT x.reversed FOR UPDATE OF x,li LOOP
    UPDATE public.erp_payroll_loan_installments SET repaid=repaid-row.amount WHERE id=row.installment_id;UPDATE public.erp_payroll_loan_payments SET reversed=true WHERE id=row.id;
   END LOOP;
   doc:=erp_payroll_private.reverse(p_cafe_id,doc,(p_data->>'date')::date,'عكس تحصيل سلفة #'||r.code);
   UPDATE public.erp_payroll_records SET paid=paid-command.amount,status='active',revision=revision+1 WHERE id=r.id;
  ELSIF p_action='repay' THEN
   amount:=round((p_data->>'amount')::numeric,2);IF r.kind<>'loan' OR r.status<>'active' OR amount IS NULL OR amount<=0 OR amount>r.amount-r.paid OR amount='NaN'::numeric THEN RAISE EXCEPTION 'مبلغ سداد السلفة غير صالح';END IF;
   PERFORM erp_asset_private.account(p_cafe_id,(p_data->>'accountId')::uuid,ARRAY['cash','bank']);settings:=r.calculation->'settings';PERFORM erp_asset_private.account(p_cafe_id,(settings->>'receivableAccountId')::uuid,ARRAY['other_asset','receivable']);
   doc:=erp_asset_private.document(p_cafe_id,(p_data->>'date')::date,round(amount*r.exchange_rate,2),'تحصيل سلفة #'||r.code,auth.uid());PERFORM erp_asset_private.line(p_cafe_id,doc,(p_data->>'accountId')::uuid,round(amount*r.exchange_rate,2),0);PERFORM erp_asset_private.line(p_cafe_id,doc,(settings->>'receivableAccountId')::uuid,0,round(amount*r.exchange_rate,2));remaining:=amount;
   FOR row IN SELECT * FROM public.erp_payroll_loan_installments WHERE cafe_id=p_cafe_id AND loan_id=r.id AND repaid<erp_payroll_loan_installments.amount ORDER BY due_on,id FOR UPDATE LOOP
    portion:=least(remaining,row.amount-row.repaid);EXIT WHEN portion<=0;UPDATE public.erp_payroll_loan_installments SET repaid=repaid+portion WHERE id=row.id;INSERT INTO public.erp_payroll_loan_payments(cafe_id,installment_id,document_id,amount) VALUES(p_cafe_id,row.id,doc,portion);remaining:=remaining-portion;
   END LOOP;
   IF remaining<>0 THEN RAISE EXCEPTION 'لا يطابق مبلغ السداد جدول الأقساط';END IF;
   UPDATE public.erp_payroll_records SET paid=paid+command.amount,status=CASE WHEN paid+command.amount=erp_payroll_records.amount THEN 'closed' ELSE 'active' END,revision=revision+1 WHERE id=r.id;
  END IF;
 END IF;
 IF p_action<>'related_form' THEN INSERT INTO public.erp_payroll_events(cafe_id,record_id,action,actor,detail) VALUES(p_cafe_id,rid,p_action,auth.uid(),jsonb_build_object('documentId',doc));END IF;
 result:=jsonb_build_object('id',rid);INSERT INTO erp_payroll_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_data,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_purchases_read_before_scope(p_cafe_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE result jsonb;defaults jsonb;BEGIN
 result:=erp_inventory_private.purchase_read_before_tracking(p_cafe_id);
 SELECT coalesce(jsonb_object_agg(i.id::text,coalesce(result#>ARRAY['itemDefaults',i.id::text],'{}')||jsonb_build_object('trackingMode',coalesce(m.tracking_mode,'quantity'))),'{}') INTO defaults FROM erp_branch_private.bf_items i LEFT JOIN erp_branch_private.erp_inventory_items m ON m.cafe_id=i.cafe_id AND m.item_id=i.id WHERE i.cafe_id=p_cafe_id;
 RETURN result||jsonb_build_object('itemDefaults',defaults);
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_purchases_write_before_scope(p_cafe_id uuid, p_action text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE c uuid:=p_cafe_id;p jsonb:=p_payload;r public.erp_purchase_documents%ROWTYPE;existing erp_purchase_private.requests%ROWTYPE;rid uuid;result jsonb;cfg jsonb;nextkind text;lines jsonb;row jsonb;sid uuid;BEGIN
 PERFORM erp_purchase_private.authorize(c,'read');IF p_request_id IS NULL OR jsonb_typeof(p) IS DISTINCT FROM 'object' OR octet_length(p::text)>500000 THEN RAISE EXCEPTION 'طلب المشتريات غير صالح';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(c::text,60412));SELECT * INTO existing FROM erp_purchase_private.requests WHERE cafe_id=c AND request_id=p_request_id;
 IF existing.request_id IS NOT NULL THEN IF existing.actor<>auth.uid() OR existing.action<>p_action OR existing.payload<>p THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى';END IF;RETURN existing.result;END IF;
 IF p_action='save' THEN IF coalesce((p->>'revision')::integer,0)=0 AND nullif(p->>'sourceId','') IS NOT NULL THEN RAISE EXCEPTION 'أنشئ المستند المرتبط من إجراء التحويل';END IF;rid:=erp_purchase_private.save(c,p);
 ELSIF p_action='supplier' THEN rid:=erp_purchase_private.supplier(c,p);
 ELSIF p_action='delete_supplier' THEN
  PERFORM erp_purchase_private.authorize(c,'delete');rid:=(p->>'id')::uuid;IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=rid AND kind='supplier') THEN RAISE EXCEPTION 'المورد غير متاح' USING ERRCODE='42501';END IF;
  IF coalesce((SELECT revision FROM public.erp_purchase_suppliers WHERE cafe_id=c AND id=rid),0) IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'المورد تغير' USING ERRCODE='40001';END IF;
  IF EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=c AND party_id=rid) OR EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=c AND(supplier_id=rid OR payload->'supplierIds'?rid::text)) THEN RAISE EXCEPTION 'المورد مرتبط بمعاملات ويمكن إيقافه بدل حذفه';END IF;
  DELETE FROM public.erp_purchase_suppliers WHERE cafe_id=c AND id=rid;DELETE FROM public.bf_parties WHERE cafe_id=c AND id=rid;
 ELSIF p_action='import_suppliers' THEN IF jsonb_array_length(p->'rows') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'حدد من مورد واحد إلى مئة مورد';END IF;FOR row IN SELECT value FROM jsonb_array_elements(p->'rows') LOOP PERFORM erp_purchase_private.supplier(c,row);END LOOP;result:=jsonb_build_object('count',jsonb_array_length(p->'rows'));
 ELSIF p_action='settings' THEN
  PERFORM erp_purchase_private.authorize(c,'settings');cfg:=erp_purchase_private.settings(c);IF(cfg->>'revision')::integer IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'الإعدادات تغيرت' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(p) IS DISTINCT FROM 'object'
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['revision','nextNumber','taxRate'])k WHERE jsonb_typeof(p->k) IS DISTINCT FROM 'number')
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['prefix','exchangeMode','discountMode','adjustmentLabel','journalDescription','taxMode'])k WHERE jsonb_typeof(p->k) IS DISTINCT FROM 'string')
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['shareEnabled','showExchangeRate','updateItemPrices','allowAdjustment','defaultPaid','allowDebitNotes','autoApplyCredit','warehouseRequisitions','defaultReceived'])k WHERE jsonb_typeof(p->k) IS DISTINCT FROM 'boolean')
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['exchangeRates','statuses','fields','excludedItemIds','excludedCategoryIds'])k WHERE jsonb_typeof(p->k) IS DISTINCT FROM 'array')
   OR NOT(p?'adjustmentAccountId') OR coalesce(jsonb_typeof(p->'adjustmentAccountId'),'') NOT IN('null','string')
  THEN RAISE EXCEPTION 'أكمل إعدادات المشتريات بالقيم الصحيحة';END IF;
  IF(p->>'nextNumber')::numeric NOT BETWEEN 1 AND 2147483646 OR trunc((p->>'nextNumber')::numeric)<>(p->>'nextNumber')::numeric
   OR length(p->>'prefix')>30 OR length(p->>'adjustmentLabel')>80 OR length(p->>'journalDescription')>1000
   OR coalesce(p->>'discountMode','') NOT IN('invoice','line','both') OR coalesce(p->>'exchangeMode','') NOT IN('manual','configured') OR coalesce(p->>'taxMode','') NOT IN('item','none','specific')
   OR(p->>'taxRate')::numeric NOT BETWEEN 0 AND 100 OR jsonb_array_length(p->'statuses')>100 OR jsonb_array_length(p->'exchangeRates')>100 OR jsonb_array_length(p->'excludedItemIds')>1000 OR jsonb_array_length(p->'excludedCategoryIds')>1000
  THEN RAISE EXCEPTION 'راجع إعدادات المشتريات';END IF;
  FOR row IN SELECT value FROM jsonb_array_elements(p->'exchangeRates') LOOP
   IF jsonb_typeof(row) IS DISTINCT FROM 'object' OR jsonb_typeof(row->'currency') IS DISTINCT FROM 'string' OR coalesce(row->>'currency','')!~'^[A-Z]{3}$' OR jsonb_typeof(row->'rate') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'راجع أسعار العملات';END IF;
   IF(row->>'rate')::numeric<=0 OR(row->>'rate')::numeric>1000000 THEN RAISE EXCEPTION 'راجع أسعار العملات';END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'exchangeRates')x GROUP BY x->>'currency' HAVING count(*)>1) THEN RAISE EXCEPTION 'عملة مكررة في أسعار الصرف';END IF;
  FOR row IN SELECT value FROM jsonb_array_elements(p->'statuses') LOOP
   IF jsonb_typeof(row) IS DISTINCT FROM 'object' OR jsonb_typeof(row->'id') IS DISTINCT FROM 'string' OR jsonb_typeof(row->'name') IS DISTINCT FROM 'string' OR length(btrim(coalesce(row->>'id',''))) NOT BETWEEN 1 AND 80 OR length(btrim(coalesce(row->>'name',''))) NOT BETWEEN 1 AND 100 OR coalesce(row->>'kind','') NOT IN('request','rfq','quotation','order','invoice') THEN RAISE EXCEPTION 'راجع حالات المشتريات';END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'statuses')x GROUP BY x->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'معرف حالة مكرر';END IF;
  FOR row IN SELECT value FROM jsonb_array_elements((p->'excludedItemIds')||(p->'excludedCategoryIds')) LOOP
   IF jsonb_typeof(row) IS DISTINCT FROM 'string' OR(row#>>'{}')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'راجع الأصناف والمجموعات المستبعدة';END IF;
  END LOOP;
  IF jsonb_typeof(p->'adjustmentAccountId')='string' AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=c AND id=(p->>'adjustmentAccountId')::uuid AND active AND NOT coalesce(is_group,false) AND deleted_at IS NULL) THEN RAISE EXCEPTION 'حساب التسوية غير متاح';END IF;
  PERFORM erp_manufacturing_private.validate_custom_fields(p->'fields');
  INSERT INTO public.erp_purchase_settings(cafe_id,payload) VALUES(c,p-'revision') ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload,revision=erp_purchase_settings.revision+1;
 ELSIF p_action IN('payment','return','debit','allocate','receive','apply_credit') THEN
  PERFORM erp_purchase_private.authorize(c,'approve');PERFORM brand_finance_private.assert_job_access(c,'brand_finance_execute',CASE WHEN p_action='return' THEN 'refund' WHEN p_action='payment' THEN 'settlement' ELSE 'purchase' END);
  IF p_action='apply_credit' THEN PERFORM erp_purchase_private.period(c,(now() AT TIME ZONE 'Asia/Riyadh')::date);rid:=(p->>'id')::uuid;PERFORM erp_purchase_private.apply_credit(c,rid);ELSIF p_action='payment' THEN rid:=erp_purchase_private.payment(c,p);ELSIF p_action='debit' THEN rid:=erp_purchase_private.debit(c,p);ELSIF p_action='allocate' THEN rid:=erp_purchase_private.allocate(c,p);ELSIF p_action='receive' THEN PERFORM erp_inventory_private.set_purchase_tracking(c,(p->>'id')::uuid,(p->>'revision')::integer,p->'tracking');rid:=erp_purchase_private.receive(c,(p->>'id')::uuid,(p->>'revision')::integer);
  ELSE IF NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=c AND id=(p->>'invoiceId')::uuid AND kind='purchase') OR EXISTS(SELECT 1 FROM public.erp_purchase_receipts WHERE cafe_id=c AND source_document_id=(p->>'invoiceId')::uuid AND status='pending') THEN RAISE EXCEPTION 'استلم البضاعة قبل تسجيل مرتجع مخزني';END IF;
   result:=public.brand_finance_execute(c,'refund',(p-'invoiceId')||jsonb_build_object('documentId',p->>'invoiceId'),gen_random_uuid());rid:=(result->>'id')::uuid;
  END IF;
 ELSE
  SELECT * INTO r FROM public.erp_purchase_documents WHERE cafe_id=c AND id=(p->>'id')::uuid FOR UPDATE;IF r.id IS NULL THEN RAISE EXCEPTION 'المستند غير متاح' USING ERRCODE='42501';END IF;IF r.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'المستند تغير' USING ERRCODE='40001';END IF;rid:=r.id;
  IF p_action='note' THEN PERFORM erp_purchase_private.authorize(c,'update');IF length(btrim(coalesce(p->>'note',''))) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'أدخل الملاحظة';END IF;UPDATE public.erp_purchase_documents SET revision=revision+1 WHERE id=r.id;result:=jsonb_build_object('id',r.id,'note',p->>'note');
  ELSIF p_action='delete' THEN PERFORM erp_purchase_private.authorize(c,'delete');IF r.status NOT IN('draft','rejected') THEN RAISE EXCEPTION 'لا يمكن حذف مستند معتمد';END IF;DELETE FROM public.erp_purchase_documents WHERE id=r.id;
  ELSIF p_action='copy' THEN PERFORM erp_purchase_private.authorize(c,'create');SELECT jsonb_agg(l||jsonb_build_object('id',gen_random_uuid())) INTO lines FROM jsonb_array_elements(r.payload->'lines')l;rid:=erp_purchase_private.save(c,r.payload||jsonb_build_object('customValues',erp_purchase_private.copy_values(erp_purchase_private.settings(c)->'fields',r.payload->'customValues'),'id',gen_random_uuid(),'revision',0,'number','','sourceId',NULL,'lines',lines,'paid',0));
  ELSIF p_action='convert' THEN
   PERFORM erp_purchase_private.authorize(c,'approve');PERFORM erp_purchase_private.authorize(c,'create');nextkind:=p->>'kind';IF r.status<>'approved' OR NOT(r.kind='request' AND nextkind IN('rfq','order') OR r.kind='rfq' AND nextkind='quotation' OR r.kind='quotation' AND nextkind='order' OR r.kind='order' AND nextkind='invoice') THEN RAISE EXCEPTION 'اعتمد المستند وحدد التحويل التالي في دورة الشراء';END IF;
   sid:=coalesce(nullif(p->>'supplierId','')::uuid,r.supplier_id);IF r.kind='rfq' AND NOT(r.payload->'supplierIds'?sid::text) THEN RAISE EXCEPTION 'المورد غير مدعو إلى طلب العرض';END IF;SELECT jsonb_agg(l||jsonb_build_object('id',gen_random_uuid())) INTO lines FROM jsonb_array_elements(r.payload->'lines')l;
   rid:=erp_purchase_private.save(c,r.payload||jsonb_build_object('customValues',erp_purchase_private.copy_values(erp_purchase_private.settings(c)->'fields',r.payload->'customValues'),'id',gen_random_uuid(),'revision',0,'kind',nextkind,'number','','sourceId',r.id,'supplierId',sid,'supplierIds',CASE WHEN nextkind='rfq' AND coalesce(jsonb_array_length(p->'supplierIds'),0)>0 THEN p->'supplierIds' ELSE r.payload->'supplierIds' END,'lines',lines,'paid',0));
   IF r.kind<>'rfq' THEN UPDATE public.erp_purchase_documents SET status='converted',revision=revision+1 WHERE id=r.id;ELSE IF EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=c AND source_id=r.id AND supplier_id=sid AND id<>rid AND status<>'cancelled') THEN RAISE EXCEPTION 'تم إنشاء عرض لهذا المورد من الطلب نفسه';END IF;END IF;
  ELSIF p_action='post' THEN PERFORM erp_purchase_private.authorize(c,'approve');rid:=erp_purchase_private.post(c,r,(p->>'expectedTotal')::numeric);result:=jsonb_build_object('id',r.id,'financeId',rid);
  ELSIF p_action IN('submit','approve','reject','cancel') THEN
   PERFORM erp_purchase_private.authorize(c,CASE WHEN p_action='submit' THEN 'update' ELSE 'approve' END);
   IF NOT(p_action='submit' AND r.status IN('draft','rejected') OR p_action IN('approve','reject') AND r.status='pending' OR p_action='cancel' AND r.status IN('draft','pending','approved','rejected') AND NOT EXISTS(SELECT 1 FROM public.erp_purchase_documents WHERE cafe_id=c AND source_id=r.id AND status<>'cancelled')) THEN RAISE EXCEPTION 'الانتقال غير متاح في الحالة الحالية';END IF;
   IF p_action='approve' THEN PERFORM erp_purchase_private.validate_values(erp_purchase_private.settings(c)->'fields',coalesce(r.payload->'customValues','{}'),c,r.id,r.kind,0,false);END IF;
   UPDATE public.erp_purchase_documents SET status=CASE p_action WHEN 'submit' THEN 'pending' WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' ELSE 'cancelled' END,revision=revision+1 WHERE id=r.id;
  ELSE RAISE EXCEPTION 'عملية المشتريات غير معروفة';END IF;
 END IF;
 IF p_action IN('delete','cancel') AND r.source_id IS NOT NULL THEN UPDATE public.erp_purchase_documents source SET status='approved',revision=revision+1 WHERE source.cafe_id=c AND source.id=r.source_id AND source.status='converted' AND NOT EXISTS(SELECT 1 FROM public.erp_purchase_documents child WHERE child.cafe_id=c AND child.source_id=source.id AND child.status<>'cancelled');END IF;
 result:=coalesce(result,jsonb_build_object('id',rid));INSERT INTO public.erp_purchase_events(cafe_id,record_id,action,payload,actor) VALUES(c,rid,p_action,result,auth.uid());INSERT INTO erp_purchase_private.requests(cafe_id,request_id,actor,action,payload,result) VALUES(c,p_request_id,auth.uid(),p_action,p,result);RETURN result;
END$function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_rentals_quote_before_scope(p_cafe_id uuid, p_unit_ids uuid[], p_start timestamp with time zone, p_end timestamp with time zone, p_exclude uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'rentals','read');
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Rental access denied' USING ERRCODE='42501';END IF;
 RETURN erp_rental_private.quote(p_cafe_id,p_unit_ids,p_start,p_end,p_exclude);
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_rentals_write_before_scope(p_cafe_id uuid, p_action text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;old_request public.erp_rental_requests;oid uuid;table_name text;old_revision integer;data jsonb;item jsonb;val numeric;ids uuid[];start_at timestamptz;end_at timestamptz;q jsonb;result jsonb;old_res public.erp_rental_reservations;old_contract public.erp_rental_contracts;entity text;state text;has_invoice boolean;amount numeric;affected integer;
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'rentals',erp_access_private.action(p_action,p_payload)); IF coalesce((p_payload->>'autoInvoice')::boolean,false) THEN PERFORM erp_access_private.assert_allowed(p_cafe_id,'rentals','approve');END IF;
 role_name:=brand_finance_private.role_for(p_cafe_id);IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Rental write denied' USING ERRCODE='42501';END IF;
 IF p_action='settings' AND role_name NOT IN('owner','manager') THEN RAISE EXCEPTION 'Rental settings denied' USING ERRCODE='42501';END IF;
 IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>500000 THEN RAISE EXCEPTION 'طلب غير صالح' USING ERRCODE='22023';END IF;
 -- Financial lock first: invoices, corrections and occupancy writes share one order.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO old_request FROM public.erp_rental_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF old_request.actor<>auth.uid() OR old_request.action IS DISTINCT FROM p_action OR old_request.payload IS DISTINCT FROM p_payload THEN RAISE EXCEPTION 'طلب متكرر ببيانات مختلفة' USING ERRCODE='40001';END IF;RETURN old_request.result;END IF;
 oid:=coalesce((p_payload->>'id')::uuid,p_cafe_id);entity:=p_action;
 IF NOT p_payload?'revision' OR jsonb_typeof(p_payload->'revision') IS DISTINCT FROM 'number' OR (p_payload->>'revision')::integer<0 OR (p_action<>'settings' AND (p_payload->>'id') IS NULL) THEN RAISE EXCEPTION 'معرف السجل وإصداره مطلوبان' USING ERRCODE='22023';END IF;
 IF p_action IN('rule','type','unit','season') AND (jsonb_typeof(p_payload->'name') IS DISTINCT FROM 'string' OR jsonb_typeof(p_payload->'active') IS DISTINCT FROM 'boolean') THEN RAISE EXCEPTION 'الاسم والحالة مطلوبان' USING ERRCODE='22023';END IF;
 IF p_action='rule' AND (p_payload->>'method' IS NULL OR jsonb_typeof(p_payload->'weekRates') IS DISTINCT FROM 'array' OR jsonb_typeof(p_payload->'rates') IS DISTINCT FROM 'object') THEN RAISE EXCEPTION 'طريقة التسعير والأسعار مطلوبة' USING ERRCODE='22023';END IF;
 IF p_action='season' AND (jsonb_typeof(p_payload->'typeIds') IS DISTINCT FROM 'array' OR jsonb_typeof(p_payload->'days') IS DISTINCT FROM 'array' OR p_payload->>'from' IS NULL OR p_payload->>'to' IS NULL OR (p_payload->>'priority')::integer NOT BETWEEN 0 AND 9999) THEN RAISE EXCEPTION 'أكمل فترة الموسم وأيامه ووحداته' USING ERRCODE='22023';END IF;
 IF p_action='contract' AND (jsonb_typeof(p_payload->'installments') IS DISTINCT FROM 'array' OR p_payload->>'code' IS NULL OR p_payload->>'taxRate' IS NULL OR p_payload->>'deposit' IS NULL) THEN RAISE EXCEPTION 'أكمل بيانات العقد وأقساطه' USING ERRCODE='22023';END IF;
 IF p_action='settings' AND (p_payload->>'lineMode' IS NULL OR p_payload->>'invoiceStatus' IS NULL OR jsonb_typeof(p_payload->'fields') IS DISTINCT FROM 'array') THEN RAISE EXCEPTION 'أكمل إعدادات الفواتير والحقول' USING ERRCODE='22023';END IF;
 IF p_action IN('rule','type','unit','season') THEN
  table_name:=CASE p_action WHEN 'rule' THEN 'rules' WHEN 'type' THEN 'types' WHEN 'unit' THEN 'units' ELSE 'seasons' END;
  EXECUTE format('SELECT revision FROM public.erp_rental_%I WHERE cafe_id=$1 AND id=$2',table_name) INTO old_revision USING p_cafe_id,oid;
  IF coalesce(old_revision,0) IS DISTINCT FROM (p_payload->>'revision')::integer THEN RAISE EXCEPTION 'تغير السجل' USING ERRCODE='40001';END IF;
  IF length(btrim(p_payload->>'name')) NOT BETWEEN 1 AND 160 OR jsonb_typeof(p_payload->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع الاسم والحالة' USING ERRCODE='22023';END IF;
  IF p_action='rule' THEN
   IF p_payload->>'method' NOT IN('minute','hour','day','mixed') OR jsonb_array_length(p_payload->'weekRates')<>7 THEN RAISE EXCEPTION 'راجع طريقة التسعير وأيام الأسبوع' USING ERRCODE='22023';END IF;
   FOR item IN SELECT p_payload->'rates' UNION ALL SELECT x FROM jsonb_array_elements(p_payload->'weekRates') x WHERE x<>'null' LOOP
    IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'أدخل الأسعار' USING ERRCODE='22023';END IF;
    FOREACH state IN ARRAY ARRAY['day','hour','minute'] LOOP val:=(item->>state)::numeric;IF val IS NULL OR val<0 OR val>1000000000 OR val<>round(val,2) OR val='NaN'::numeric THEN RAISE EXCEPTION 'سعر غير صالح' USING ERRCODE='22023';END IF;END LOOP;
   END LOOP;
  ELSIF p_action IN('type','season') THEN
   IF NOT EXISTS(SELECT 1 FROM public.erp_rental_rules WHERE cafe_id=p_cafe_id AND id=(p_payload->>'ruleId')::uuid) THEN RAISE EXCEPTION 'اختر قاعدة تسعير في هذه العلامة' USING ERRCODE='42501';END IF;
   IF p_action='type' AND ((p_payload->>'taxRate')::numeric NOT IN(0,15) OR p_payload->>'taxRate' IS NULL) THEN RAISE EXCEPTION 'الضريبة غير صالحة' USING ERRCODE='22023';END IF;
   IF p_action='season' THEN
    IF (p_payload->>'to')::date<(p_payload->>'from')::date OR jsonb_array_length(p_payload->'days') NOT BETWEEN 1 AND 7 OR jsonb_array_length(p_payload->'typeIds') NOT BETWEEN 1 AND 1000 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_payload->'days') x WHERE x::integer NOT BETWEEN 0 AND 6) THEN RAISE EXCEPTION 'راجع فترة الموسم وأيامه وأنواع الوحدات' USING ERRCODE='22023';END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_payload->'typeIds') x WHERE NOT EXISTS(SELECT 1 FROM public.erp_rental_types WHERE cafe_id=p_cafe_id AND id=x::uuid)) THEN RAISE EXCEPTION 'نوع وحدة غير متاح' USING ERRCODE='42501';END IF;
   END IF;
  ELSE
   IF NOT EXISTS(SELECT 1 FROM public.erp_rental_types WHERE cafe_id=p_cafe_id AND id=(p_payload->>'typeId')::uuid) THEN RAISE EXCEPTION 'اختر نوع الوحدة' USING ERRCODE='42501';END IF;
  END IF;
  data:=p_payload-'revision';EXECUTE format('INSERT INTO public.erp_rental_%I(id,cafe_id,revision,payload) VALUES($1,$2,$3,$4) ON CONFLICT(id) DO UPDATE SET revision=EXCLUDED.revision,payload=EXCLUDED.payload WHERE erp_rental_%I.cafe_id=EXCLUDED.cafe_id',table_name,table_name) USING oid,p_cafe_id,coalesce(old_revision,0)+1,data;
  GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>1 THEN RAISE EXCEPTION 'معرف السجل مستخدم' USING ERRCODE='42501';END IF;result:=jsonb_build_object('id',oid);
 ELSIF p_action='settings' THEN
  SELECT revision INTO old_revision FROM public.erp_rental_settings WHERE cafe_id=p_cafe_id;
  IF coalesce(old_revision,0) IS DISTINCT FROM (p_payload->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت الإعدادات' USING ERRCODE='40001';END IF;
  IF p_payload->>'lineMode' NOT IN('single','daily') OR p_payload->>'invoiceStatus' NOT IN('draft','issued') OR jsonb_typeof(p_payload->'onlineBooking') IS DISTINCT FROM 'boolean' OR jsonb_array_length(p_payload->'fields')>30 THEN RAISE EXCEPTION 'راجع الإعدادات' USING ERRCODE='22023';END IF;
  IF (SELECT count(DISTINCT f->>'key') FROM jsonb_array_elements(p_payload->'fields') f)<>jsonb_array_length(p_payload->'fields') THEN RAISE EXCEPTION 'معرفات الحقول الإضافية يجب ألا تتكرر' USING ERRCODE='22023';END IF;
  FOR item IN SELECT f FROM jsonb_array_elements(p_payload->'fields') f LOOP IF coalesce(item->>'key','')!~'^[a-z][a-z0-9_]{0,39}$' OR coalesce(length(btrim(item->>'label')),0) NOT BETWEEN 1 AND 100 OR coalesce(item->>'type','') NOT IN('text','number','date','checkbox') OR jsonb_typeof(item->'required') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع أسماء الحقول وأنواعها وحالتها' USING ERRCODE='22023';END IF;END LOOP;
  IF nullif(p_payload->>'warehouseId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id=(p_payload->>'warehouseId')::uuid AND active) THEN RAISE EXCEPTION 'اختر مستودعًا نشطًا في العلامة' USING ERRCODE='42501';END IF;
  IF nullif(p_payload->>'orderSourceId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(brand_finance_private.order_source_settings(p_cafe_id)->'sources') x WHERE x->>'id'=p_payload->>'orderSourceId' AND (x->>'active')::boolean) THEN RAISE EXCEPTION 'مصدر الطلب غير متاح' USING ERRCODE='22023';END IF;
  INSERT INTO public.erp_rental_settings VALUES(p_cafe_id,coalesce(old_revision,0)+1,p_payload-'revision') ON CONFLICT(cafe_id) DO UPDATE SET revision=EXCLUDED.revision,payload=EXCLUDED.payload;result:=jsonb_build_object('id',p_cafe_id);
 ELSIF p_action IN('reservation','contract') THEN
  IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=(p_payload->>'customerId')::uuid AND kind='customer' AND active) THEN RAISE EXCEPTION 'اختر عميلًا نشطًا في العلامة' USING ERRCODE='42501';END IF;
  IF p_action='reservation' THEN
   SELECT * INTO old_res FROM public.erp_rental_reservations WHERE cafe_id=p_cafe_id AND id=oid FOR UPDATE;old_revision:=old_res.revision;
   IF old_revision IS NOT NULL AND(old_res.status NOT IN('pending','confirmed') OR old_res.draft_id IS NOT NULL) THEN RAISE EXCEPTION 'لا يمكن تعديل حجز مغلق أو مفوتر' USING ERRCODE='22023';END IF;
   ids:=ARRAY(SELECT x::uuid FROM jsonb_array_elements_text(p_payload->'unitIds') x);start_at:=(p_payload->>'startsAt')::timestamptz;end_at:=(p_payload->>'endsAt')::timestamptz;
   q:=erp_rental_private.quote(p_cafe_id,ids,start_at,end_at,oid);IF (q->>'total')::numeric IS DISTINCT FROM (p_payload->>'expectedTotal')::numeric THEN RAISE EXCEPTION 'تغير سعر الحجز اطلب تسعيرًا جديدًا' USING ERRCODE='40001';END IF;
  ELSE
   SELECT * INTO old_contract FROM public.erp_rental_contracts WHERE cafe_id=p_cafe_id AND id=oid FOR UPDATE;old_revision:=old_contract.revision;
   IF old_revision IS NOT NULL AND(old_contract.status<>'active' OR EXISTS(SELECT 1 FROM public.erp_rental_installments WHERE contract_id=oid AND draft_id IS NOT NULL)) THEN RAISE EXCEPTION 'العقد مغلق أو مرتبط بفاتورة لا يمكن تعديل قيمه' USING ERRCODE='22023';END IF;
   ids:=ARRAY[(p_payload->>'unitId')::uuid];start_at:=((p_payload->>'startsAt')::date::timestamp AT TIME ZONE 'Asia/Riyadh');end_at:=((p_payload->>'endsAt')::date::timestamp AT TIME ZONE 'Asia/Riyadh');
   IF start_at IS NULL OR end_at IS NULL OR end_at<=start_at OR end_at-start_at>interval '100 years' OR NOT EXISTS(SELECT 1 FROM public.erp_rental_units WHERE cafe_id=p_cafe_id AND id=ids[1] AND (payload->>'active')::boolean) THEN RAISE EXCEPTION 'راجع الوحدة وفترة العقد' USING ERRCODE='22023';END IF;
   IF jsonb_array_length(p_payload->'installments') NOT BETWEEN 1 AND 600 OR length(btrim(p_payload->>'code')) NOT BETWEEN 1 AND 80 OR (p_payload->>'deposit')::numeric NOT BETWEEN 0 AND 1000000000 OR (p_payload->>'taxRate')::numeric NOT IN(0,15) THEN RAISE EXCEPTION 'راجع قيم العقد والأقساط' USING ERRCODE='22023';END IF;
   IF erp_rental_private.effective_tax(p_cafe_id,(p_payload->>'taxRate')::numeric) IS DISTINCT FROM (p_payload->>'taxRate')::numeric THEN RAISE EXCEPTION 'نسبة ضريبة العقد لا تطابق النسبة المفروضة في إعدادات الفواتير' USING ERRCODE='22023';END IF;
   IF p_payload->>'salesAccountId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=(p_payload->>'salesAccountId')::uuid AND active AND kind='revenue' AND NOT frozen AND NOT is_group AND deleted_at IS NULL) THEN RAISE EXCEPTION 'اختر حساب إيرادات نشطًا' USING ERRCODE='22023';END IF;
   amount:=0;FOR item IN SELECT x FROM jsonb_array_elements(p_payload->'installments') x LOOP
    val:=(item->>'amount')::numeric;IF val IS NULL OR val<=0 OR val>1000000000 OR val<>round(val,2) OR (item->>'due')::date NOT BETWEEN (p_payload->>'startsAt')::date AND (p_payload->>'endsAt')::date OR item->>'due' IS NULL THEN RAISE EXCEPTION 'قيمة القسط أو استحقاقه غير صالح' USING ERRCODE='22023';END IF;amount:=amount+val;
   END LOOP;IF amount>1000000000 THEN RAISE EXCEPTION 'قيمة العقد تتجاوز الحد المسموح' USING ERRCODE='22023';END IF;
  END IF;
  IF coalesce(old_revision,0) IS DISTINCT FROM (p_payload->>'revision')::integer THEN RAISE EXCEPTION 'تغير السجل أعد تحميله' USING ERRCODE='40001';END IF;
  IF EXISTS(SELECT 1 FROM public.erp_rental_reservation_units o WHERE o.cafe_id=p_cafe_id AND o.unit_id=ANY(ids) AND o.active AND o.starts_at<end_at AND o.ends_at>start_at AND coalesce(o.reservation_id,o.contract_id)<>oid) THEN RAISE EXCEPTION 'الوحدة محجوزة خلال الفترة' USING ERRCODE='23P01';END IF;
  IF p_action='reservation' THEN
   INSERT INTO public.erp_rental_reservations(id,cafe_id,customer_id,starts_at,ends_at,revision,payload,total,breakdown) VALUES(oid,p_cafe_id,(p_payload->>'customerId')::uuid,start_at,end_at,coalesce(old_revision,0)+1,(CASE WHEN old_res.customer_id=(p_payload->>'customerId')::uuid THEN coalesce(old_res.payload,'{}') ELSE '{}'::jsonb END)||p_payload-'revision'||jsonb_build_object('invoiceLineMode',q->>'lineMode'),(q->>'total')::numeric,q->'lines') ON CONFLICT(id) DO UPDATE SET customer_id=EXCLUDED.customer_id,starts_at=EXCLUDED.starts_at,ends_at=EXCLUDED.ends_at,revision=EXCLUDED.revision,payload=EXCLUDED.payload,total=EXCLUDED.total,breakdown=EXCLUDED.breakdown WHERE erp_rental_reservations.cafe_id=EXCLUDED.cafe_id;
  ELSE
   INSERT INTO public.erp_rental_contracts(id,cafe_id,customer_id,unit_id,starts_at,ends_at,revision,code,payload) VALUES(oid,p_cafe_id,(p_payload->>'customerId')::uuid,ids[1],(p_payload->>'startsAt')::date,(p_payload->>'endsAt')::date,coalesce(old_revision,0)+1,p_payload->>'code',p_payload-'revision'-'installments') ON CONFLICT(id) DO UPDATE SET customer_id=EXCLUDED.customer_id,unit_id=EXCLUDED.unit_id,starts_at=EXCLUDED.starts_at,ends_at=EXCLUDED.ends_at,revision=EXCLUDED.revision,code=EXCLUDED.code,payload=EXCLUDED.payload WHERE erp_rental_contracts.cafe_id=EXCLUDED.cafe_id;
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'السجل غير متاح' USING ERRCODE='42501';END IF;
  DELETE FROM public.erp_rental_reservation_units WHERE cafe_id=p_cafe_id AND coalesce(reservation_id,contract_id)=oid;
  INSERT INTO public.erp_rental_reservation_units SELECT p_cafe_id,x,CASE WHEN p_action='reservation' THEN oid END,CASE WHEN p_action='contract' THEN oid END,start_at,end_at,true FROM unnest(ids) x;
  IF p_action='contract' THEN DELETE FROM public.erp_rental_installments WHERE contract_id=oid;INSERT INTO public.erp_rental_installments(id,cafe_id,contract_id,due,amount,note) SELECT(x->>'id')::uuid,p_cafe_id,oid,(x->>'due')::date,(x->>'amount')::numeric,coalesce(x->>'note','') FROM jsonb_array_elements(p_payload->'installments') x;END IF;
  result:=jsonb_build_object('id',oid);
  IF p_action='reservation' AND coalesce((p_payload->>'autoInvoice')::boolean,false) THEN result:=erp_rental_private.invoice(p_cafe_id,'reservation',oid);END IF;
 ELSIF p_action IN('status','delete','invoice','recurring') THEN
  entity:=p_payload->>'entity';table_name:=CASE entity WHEN 'reservation' THEN 'reservations' WHEN 'contract' THEN 'contracts' WHEN 'installment' THEN 'installments' WHEN 'unit' THEN 'units' WHEN 'type' THEN 'types' WHEN 'rule' THEN 'rules' WHEN 'season' THEN 'seasons' END;
  IF table_name IS NULL THEN RAISE EXCEPTION 'نوع سجل غير صالح' USING ERRCODE='22023';END IF;
  EXECUTE format('SELECT revision FROM public.erp_rental_%I WHERE cafe_id=$1 AND id=$2',table_name) INTO old_revision USING p_cafe_id,oid;
  IF old_revision IS NULL THEN RAISE EXCEPTION 'السجل غير متاح' USING ERRCODE='42501';END IF;
  IF old_revision IS DISTINCT FROM (p_payload->>'revision')::integer THEN RAISE EXCEPTION 'تغير السجل' USING ERRCODE='40001';END IF;
  IF p_action='recurring' THEN
   IF entity<>'reservation' THEN RAISE EXCEPTION 'الفاتورة الدورية تخص أمر الحجز' USING ERRCODE='22023';END IF;
   SELECT * INTO old_res FROM public.erp_rental_reservations WHERE cafe_id=p_cafe_id AND id=oid;
   IF old_res.recurring_id IS NOT NULL THEN result:=jsonb_build_object('id',oid,'recurringId',old_res.recurring_id);
   ELSE
    result:=erp_rental_private.invoice(p_cafe_id,'reservation',oid,true);SELECT payload INTO data FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=(result->>'draftId')::uuid;
    state:=gen_random_uuid()::text;PERFORM public.brand_finance_save_recurring_invoice(p_cafe_id,state::uuid,0,jsonb_build_object('name','حجز وحدات #'||old_res.number,'active',false,'showPeriod',true,'unit','month','interval',1,'count',0,'leadDays',0,'paymentTermsDays',0,'firstDate',greatest((old_res.ends_at AT TIME ZONE 'Asia/Riyadh')::date,(now() AT TIME ZONE 'Asia/Riyadh')::date),'document',data));
    UPDATE public.erp_rental_reservations SET recurring_id=state::uuid,revision=revision+1 WHERE id=oid;result:=jsonb_build_object('id',oid,'recurringId',state::uuid);
   END IF;
  ELSIF p_action='invoice' THEN result:=erp_rental_private.invoice(p_cafe_id,entity,oid);
  ELSIF p_action='status' THEN
   state:=p_payload->>'status';IF (entity='reservation' AND state NOT IN('pending','confirmed','closed','cancelled')) OR (entity='contract' AND state NOT IN('active','closed','cancelled')) OR entity NOT IN('reservation','contract') OR state IS NULL THEN RAISE EXCEPTION 'الحالة غير صالحة' USING ERRCODE='22023';END IF;
   IF state NOT IN('closed','cancelled') AND EXISTS(SELECT 1 FROM public.erp_rental_reservation_units own JOIN public.erp_rental_reservation_units other ON own.cafe_id=other.cafe_id AND own.unit_id=other.unit_id AND own.starts_at<other.ends_at AND own.ends_at>other.starts_at WHERE own.cafe_id=p_cafe_id AND coalesce(own.reservation_id,own.contract_id)=oid AND coalesce(other.reservation_id,other.contract_id)<>oid AND other.active) THEN RAISE EXCEPTION 'تعارض إشغال عند إعادة الفتح' USING ERRCODE='23P01';END IF;
   EXECUTE format('UPDATE public.erp_rental_%I SET status=$1,revision=revision+1 WHERE cafe_id=$2 AND id=$3',table_name) USING state,p_cafe_id,oid;UPDATE public.erp_rental_reservation_units SET active=state NOT IN('closed','cancelled') WHERE cafe_id=p_cafe_id AND coalesce(reservation_id,contract_id)=oid;result:=jsonb_build_object('id',oid);
  ELSE
   IF entity='reservation' THEN SELECT draft_id IS NOT NULL INTO has_invoice FROM public.erp_rental_reservations WHERE id=oid;
   ELSIF entity='contract' THEN SELECT EXISTS(SELECT 1 FROM public.erp_rental_installments WHERE contract_id=oid AND draft_id IS NOT NULL) INTO has_invoice;
   ELSIF entity='installment' THEN RAISE EXCEPTION 'عدّل جدول الأقساط من العقد للحفاظ على إجماليه' USING ERRCODE='22023';END IF;
   IF has_invoice THEN RAISE EXCEPTION 'لا يمكن حذف سجل مرتبط بفاتورة استخدم الإلغاء مع مراجعة المالية' USING ERRCODE='22023';END IF;
   IF entity='rule' AND(EXISTS(SELECT 1 FROM public.erp_rental_types WHERE cafe_id=p_cafe_id AND payload->>'ruleId'=oid::text) OR EXISTS(SELECT 1 FROM public.erp_rental_seasons WHERE cafe_id=p_cafe_id AND payload->>'ruleId'=oid::text)) OR entity='type' AND(EXISTS(SELECT 1 FROM public.erp_rental_units WHERE cafe_id=p_cafe_id AND payload->>'typeId'=oid::text) OR EXISTS(SELECT 1 FROM public.erp_rental_seasons WHERE cafe_id=p_cafe_id AND payload->'typeIds'?oid::text)) THEN RAISE EXCEPTION 'السجل مستخدم عطل حالته بدلًا من حذفه' USING ERRCODE='22023';END IF;
   IF entity IN('reservation','contract') THEN DELETE FROM public.erp_rental_reservation_units WHERE cafe_id=p_cafe_id AND coalesce(reservation_id,contract_id)=oid;IF entity='contract' THEN DELETE FROM public.erp_rental_installments WHERE contract_id=oid;END IF;END IF;
   EXECUTE format('DELETE FROM public.erp_rental_%I WHERE cafe_id=$1 AND id=$2',table_name) USING p_cafe_id,oid;result:=jsonb_build_object('id',oid,'deleted',true);
  END IF;
 ELSE RAISE EXCEPTION 'الإجراء غير معروف' USING ERRCODE='22023';END IF;
 INSERT INTO public.erp_rental_events(cafe_id,record_id,entity,action,actor,details) VALUES(p_cafe_id,oid,entity,p_action,auth.uid(),jsonb_build_object('status',p_payload->>'status','result',result));
 INSERT INTO public.erp_rental_requests VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_payload,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_reports_write_before_scope(p_cafe_id uuid, p_action text, p_data jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE old public.erp_saved_reports;prior erp_reports_private.requests;i uuid:=coalesce((p_data->>'id')::uuid,gen_random_uuid());cmd jsonb:=jsonb_build_object('action',p_action,'data',p_data);result jsonb;BEGIN
 PERFORM erp_reports_private.authorize(p_cafe_id,CASE p_action WHEN 'delete' THEN 'delete' ELSE CASE WHEN p_data->>'id' IS NULL THEN 'create' ELSE 'update' END END);
 IF p_request_id IS NULL OR p_action NOT IN('save','delete') OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR octet_length(p_data::text)>60000 THEN RAISE EXCEPTION 'طلب التقرير غير صالح';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,67961));SELECT * INTO prior FROM erp_reports_private.requests WHERE cafe_id=p_cafe_id AND id=p_request_id;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.command<>cmd THEN RAISE EXCEPTION 'معرف الطلب مستخدم ببيانات أخرى';END IF;RETURN prior.result;END IF;
 IF p_data->>'id' IS NOT NULL THEN SELECT * INTO old FROM public.erp_saved_reports WHERE cafe_id=p_cafe_id AND id=i FOR UPDATE;IF NOT FOUND OR old.revision IS DISTINCT FROM(p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير التقرير أعد تحميله' USING ERRCODE='40001';END IF;PERFORM erp_reports_private.authorize_source(p_cafe_id,old.definition#>>'{query,source}');END IF;
 IF p_action='delete' THEN IF old.id IS NULL THEN RAISE EXCEPTION 'التقرير غير موجود';END IF;DELETE FROM public.erp_saved_reports WHERE cafe_id=p_cafe_id AND id=i;
 ELSE
  PERFORM erp_reports_private.authorize_source(p_cafe_id,p_data#>>'{query,source}');PERFORM erp_reports_private.validate_query(p_data->'query');IF length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 150 OR coalesce(p_data->>'family','') NOT IN('sales','purchases','accounting','cheques','manufacturing','sms','credits','employees','memberships','rentals','workflows','work-orders','customers','inventory','time','ai','activity') OR coalesce(p_data#>>'{chart,kind}','') NOT IN('none','bar','line','area','pie') THEN RAISE EXCEPTION 'راجع اسم التقرير ومخططه';END IF;
  IF jsonb_typeof(p_data#>'{chart,showLegend}') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_data#>'{chart,stacked}') IS DISTINCT FROM 'boolean' OR(p_data#>>'{chart,kind}'<>'none' AND(NOT(p_data#>'{query,columns}'?(p_data#>>'{chart,label}')) OR NOT(p_data#>'{query,columns}'?(p_data#>>'{chart,value}')) OR NOT(p_data#>>'{chart,value}'=ANY(erp_reports_private.numeric_fields())))) THEN RAISE EXCEPTION 'اختر حقول المخطط من أعمدة التقرير المحددة';END IF;
  INSERT INTO public.erp_saved_reports(cafe_id,id,name,family,definition,created_by) VALUES(p_cafe_id,i,btrim(p_data->>'name'),p_data->>'family',p_data-'id'-'revision'-'name'-'family',auth.uid()) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,family=excluded.family,definition=excluded.definition,revision=erp_saved_reports.revision+1,updated_at=now();
 END IF;result:=jsonb_build_object('id',i);INSERT INTO public.erp_report_events(cafe_id,record_id,action,actor) VALUES(p_cafe_id,i,p_action,auth.uid());INSERT INTO erp_reports_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),cmd,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_sales_requisitions_write_before_scope(p_cafe_id uuid, p_action text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE old erp_sales_requisition_private.requests;result jsonb;BEGIN
 PERFORM erp_inventory_private.authorize(p_cafe_id,'approve');IF p_action IS NULL OR p_action NOT IN('deliver','receive_return')OR p_request_id IS NULL OR jsonb_typeof(p_payload)IS DISTINCT FROM'object'OR octet_length(p_payload::text)>262144 OR length(coalesce(p_payload->>'note',''))>5000 THEN RAISE EXCEPTION 'بيانات إجراء الإذن غير صالحة';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO old FROM erp_sales_requisition_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;IF old.request_id IS NOT NULL THEN IF old.actor<>auth.uid()OR old.action<>p_action OR old.payload<>p_payload THEN RAISE EXCEPTION 'معرف الطلب مستخدم ببيانات مختلفة';END IF;RETURN old.result;END IF;
 result:=CASE p_action WHEN'deliver'THEN erp_sales_requisition_private.deliver(p_cafe_id,p_payload)ELSE erp_sales_requisition_private.receive_return(p_cafe_id,p_payload)END;INSERT INTO erp_sales_requisition_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_payload,result);RETURN result;
END$function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_tasks_execute_before_scope(p_cafe_id uuid, p_action text, p_data jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; previous erp_task_private.requests; result jsonb; v_id uuid:=nullif(p_data->>'id','')::uuid; item jsonb; old public.erp_tasks; v_rev integer; v_flow public.erp_task_flows; v_code text; v_line_id uuid; v_enabled text[];
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'tasks',erp_access_private.action(p_action,p_data));
 r:=erp_task_private.access(p_cafe_id,true,p_action IN('save_type','save_template','settings'));
 IF p_request_id IS NULL OR jsonb_typeof(p_data)<>'object' OR octet_length(p_data::text)>2000000 THEN RAISE EXCEPTION 'بيانات العملية غير صالحة' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text||':erp-tasks',0));
 IF v_id IS NOT NULL THEN
 IF EXISTS(SELECT 1 FROM public.erp_tasks WHERE cafe_id=p_cafe_id AND id=v_id)AND NOT erp_task_private.task_visible(p_cafe_id,v_id)THEN RAISE EXCEPTION 'المهمة خارج نطاق السجلات المسموحة' USING ERRCODE='42501';END IF;
 IF(p_action='save_flow'OR(p_action='delete'AND p_data->>'kind'='flow'))AND EXISTS(SELECT 1 FROM public.erp_tasks child WHERE child.cafe_id=p_cafe_id AND child.flow_id=v_id AND NOT erp_task_private.task_visible(p_cafe_id,child.id))THEN RAISE EXCEPTION 'المسار يحتوي مهام خارج النطاق المسموح' USING ERRCODE='42501';END IF;
 IF(p_action='save_template'OR(p_action='delete'AND p_data->>'kind'='template'))AND EXISTS(SELECT 1 FROM public.erp_task_templates t CROSS JOIN LATERAL jsonb_array_elements(t.lines)x WHERE t.cafe_id=p_cafe_id AND t.id=v_id AND NOT erp_task_private.target_scope_visible(p_cafe_id,nullif(x->>'targetKind',''),nullif(x->>'targetId','')::uuid))THEN RAISE EXCEPTION 'القالب يحتوي سجلات خارج النطاق المسموح' USING ERRCODE='42501';END IF;
 END IF;
 IF p_action='save_flow'AND nullif(p_data->>'templateId','')IS NOT NULL AND EXISTS(SELECT 1 FROM public.erp_task_templates t CROSS JOIN LATERAL jsonb_array_elements(t.lines)x WHERE t.cafe_id=p_cafe_id AND t.id=(p_data->>'templateId')::uuid AND NOT erp_task_private.target_scope_visible(p_cafe_id,nullif(x->>'targetKind',''),nullif(x->>'targetId','')::uuid))THEN RAISE EXCEPTION 'قالب المسار خارج النطاق المسموح' USING ERRCODE='42501';END IF;
 SELECT * INTO previous FROM erp_task_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN
  IF previous.actor<>auth.uid() OR previous.action<>p_action OR previous.payload<>p_data THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى' USING ERRCODE='22023'; END IF;
  RETURN previous.result||'{"duplicate":true}'::jsonb;
 END IF;
 IF p_action='save' THEN v_id:=erp_task_private.save_task(p_cafe_id,p_data);
 ELSIF p_action='save_type' THEN
  IF v_id IS NULL THEN INSERT INTO public.erp_task_types(cafe_id,name,description,active) VALUES(p_cafe_id,btrim(p_data->>'name'),coalesce(p_data->>'description',''),coalesce((p_data->>'active')::boolean,true)) RETURNING id INTO v_id;
  ELSE UPDATE public.erp_task_types SET name=btrim(p_data->>'name'),description=coalesce(p_data->>'description',''),active=coalesce((p_data->>'active')::boolean,true),revision=revision+1 WHERE cafe_id=p_cafe_id AND id=v_id AND revision=(p_data->>'revision')::integer;
   IF NOT FOUND THEN RAISE EXCEPTION 'تغير نوع المهمة أو لم يعد موجودًا' USING ERRCODE='40001'; END IF;
  END IF;
 ELSIF p_action IN('save_template','save_flow') THEN
  IF jsonb_typeof(p_data->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'lines') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'أضف مهمة واحدة على الأقل' USING ERRCODE='22023'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(p_data->'lines') LOOP
   IF length(btrim(coalesce(item->>'title',''))) NOT BETWEEN 1 AND 200 OR length(coalesce(item->>'description',''))>20000 OR coalesce(item->>'priority','medium') NOT IN('low','medium','high','urgent') OR coalesce((item->>'dueDays')::integer,0) NOT BETWEEN 0 AND 3650 THEN RAISE EXCEPTION 'راجع بيانات مهام المسار' USING ERRCODE='22023'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.erp_task_types WHERE cafe_id=p_cafe_id AND id=(item->>'typeId')::uuid AND active) THEN RAISE EXCEPTION 'نوع المهمة غير متاح' USING ERRCODE='22023'; END IF;
   IF nullif(item->>'assigneeId','') IS NOT NULL THEN PERFORM erp_task_private.assert_assignee(p_cafe_id,(item->>'assigneeId')::uuid); END IF;
   PERFORM erp_task_private.validate_target(p_cafe_id,nullif(item->>'targetKind',''),nullif(item->>'targetId','')::uuid);
  END LOOP;
  IF p_action='save_template' THEN
   IF v_id IS NULL THEN INSERT INTO public.erp_task_templates(cafe_id,name,description,active,lines) VALUES(p_cafe_id,btrim(p_data->>'name'),coalesce(p_data->>'description',''),coalesce((p_data->>'active')::boolean,true),p_data->'lines') RETURNING id INTO v_id;
   ELSE UPDATE public.erp_task_templates SET name=btrim(p_data->>'name'),description=coalesce(p_data->>'description',''),active=coalesce((p_data->>'active')::boolean,true),lines=p_data->'lines',revision=revision+1 WHERE cafe_id=p_cafe_id AND id=v_id AND revision=(p_data->>'revision')::integer;
    IF NOT FOUND THEN RAISE EXCEPTION 'تغير قالب المهام أعد تحميله' USING ERRCODE='40001'; END IF;
   END IF;
  ELSE
   PERFORM erp_task_private.assert_assignee(p_cafe_id,(p_data->>'assigneeId')::uuid);
   IF nullif(p_data->>'templateId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_task_templates WHERE cafe_id=p_cafe_id AND id=(p_data->>'templateId')::uuid AND active) THEN RAISE EXCEPTION 'القالب غير متاح' USING ERRCODE='22023'; END IF;
   IF v_id IS NOT NULL THEN
    SELECT * INTO v_flow FROM public.erp_task_flows WHERE cafe_id=p_cafe_id AND id=v_id FOR UPDATE;
    IF NOT FOUND OR v_flow.revision IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير مسار المهام أعد تحميله' USING ERRCODE='40001'; END IF;
    IF EXISTS(SELECT 1 FROM public.erp_tasks WHERE cafe_id=p_cafe_id AND flow_id=v_id AND status<>'pending') THEN RAISE EXCEPTION 'لا يمكن استبدال مهام مسار بدأ تنفيذه' USING ERRCODE='22023'; END IF;
    DELETE FROM public.erp_tasks WHERE cafe_id=p_cafe_id AND flow_id=v_id;
    UPDATE public.erp_task_flows SET name=btrim(p_data->>'name'),description=coalesce(p_data->>'description',''),assignee_id=(p_data->>'assigneeId')::uuid,revision=revision+1 WHERE cafe_id=p_cafe_id AND id=v_id;
   ELSE
    v_code:=btrim(coalesce(p_data->>'code',''));
    IF v_code='' THEN SELECT lpad((coalesce(max(number),0)+1)::text,5,'0') INTO v_code FROM public.erp_task_flows WHERE cafe_id=p_cafe_id; END IF;
    INSERT INTO public.erp_task_flows(cafe_id,code,name,assignee_id,template_id,description,created_by) VALUES(p_cafe_id,v_code,btrim(p_data->>'name'),(p_data->>'assigneeId')::uuid,nullif(p_data->>'templateId','')::uuid,coalesce(p_data->>'description',''),auth.uid()) RETURNING id INTO v_id;
   END IF;
   FOR item IN SELECT value FROM jsonb_array_elements(p_data->'lines') LOOP
    v_line_id:=erp_task_private.save_task(p_cafe_id,item||jsonb_build_object('assigneeId',coalesce(nullif(item->>'assigneeId',''),p_data->>'assigneeId'),'dueDate',((now() AT TIME ZONE 'Asia/Riyadh')::date+coalesce((item->>'dueDays')::integer,0))::text),v_id);
   END LOOP;
   INSERT INTO public.erp_task_events(cafe_id,flow_id,action,detail,actor) VALUES(p_cafe_id,v_id,'flow_saved',jsonb_build_object('count',jsonb_array_length(p_data->'lines')),auth.uid());
  END IF;
 ELSIF p_action IN('status','assign','link','note') THEN
  SELECT * INTO old FROM public.erp_tasks WHERE cafe_id=p_cafe_id AND id=v_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'المهمة غير موجودة' USING ERRCODE='22023'; END IF;
  IF p_action<>'note' AND old.revision IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت المهمة أعد تحميلها' USING ERRCODE='40001'; END IF;
  IF p_action='status' THEN
   IF NOT coalesce(CASE old.status WHEN 'pending' THEN p_data->>'status' IN('in_progress','cancelled') WHEN 'in_progress' THEN p_data->>'status' IN('completed','pending','cancelled') WHEN 'completed' THEN p_data->>'status'='in_progress' WHEN 'cancelled' THEN p_data->>'status'='pending' END,false) THEN RAISE EXCEPTION 'الانتقال إلى هذه الحالة غير مسموح' USING ERRCODE='22023'; END IF;
   UPDATE public.erp_tasks SET status=p_data->>'status',revision=revision+1,updated_at=now(),started_at=CASE WHEN p_data->>'status'='in_progress' THEN coalesce(started_at,now()) ELSE started_at END,completed_at=CASE WHEN p_data->>'status'='completed' THEN now() ELSE NULL END WHERE cafe_id=p_cafe_id AND id=v_id;
  ELSIF p_action='assign' THEN
   PERFORM erp_task_private.assert_assignee(p_cafe_id,(p_data->>'assigneeId')::uuid);
   UPDATE public.erp_tasks SET assignee_id=(p_data->>'assigneeId')::uuid,revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe_id AND id=v_id;
  ELSIF p_action='link' THEN
   PERFORM erp_task_private.validate_target(p_cafe_id,nullif(p_data->>'targetKind',''),nullif(p_data->>'targetId','')::uuid);
   UPDATE public.erp_tasks SET target_kind=nullif(p_data->>'targetKind',''),target_id=nullif(p_data->>'targetId','')::uuid,revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe_id AND id=v_id;
  ELSE
   INSERT INTO public.erp_task_notes(cafe_id,task_id,note,occurred_at,created_by,note_format,tags) VALUES(p_cafe_id,v_id,btrim(p_data->>'note'),coalesce((p_data->>'occurredAt')::timestamptz,now()),auth.uid(),CASE WHEN p_data?'format' THEN p_data->>'format' ELSE 'plain' END,CASE WHEN p_data?'tags' THEN p_data->'tags' ELSE '[]'::jsonb END);
  END IF;
  INSERT INTO public.erp_task_events(cafe_id,task_id,flow_id,action,detail,actor) VALUES(p_cafe_id,v_id,old.flow_id,p_action,(p_data-'note')||jsonb_build_object('previousStatus',old.status),auth.uid());
 ELSIF p_action='delete' THEN
  IF p_data->>'kind'='task' THEN DELETE FROM public.erp_tasks WHERE cafe_id=p_cafe_id AND id=v_id AND revision=(p_data->>'revision')::integer;
  ELSIF p_data->>'kind'='type' AND r='owner' THEN DELETE FROM public.erp_task_types WHERE cafe_id=p_cafe_id AND id=v_id AND revision=(p_data->>'revision')::integer;
  ELSIF p_data->>'kind'='template' AND r='owner' THEN DELETE FROM public.erp_task_templates WHERE cafe_id=p_cafe_id AND id=v_id AND revision=(p_data->>'revision')::integer;
  ELSIF p_data->>'kind'='flow' THEN
   SELECT revision INTO v_rev FROM public.erp_task_flows WHERE cafe_id=p_cafe_id AND id=v_id FOR UPDATE;
   IF v_rev IS DISTINCT FROM (p_data->>'revision')::integer OR v_rev IS NULL THEN RAISE EXCEPTION 'تغير المسار أعد تحميله' USING ERRCODE='40001'; END IF;
   IF EXISTS(SELECT 1 FROM public.erp_tasks WHERE cafe_id=p_cafe_id AND flow_id=v_id AND status<>'pending') THEN RAISE EXCEPTION 'لا يمكن حذف مسار بدأ تنفيذه' USING ERRCODE='22023'; END IF;
   DELETE FROM public.erp_tasks WHERE cafe_id=p_cafe_id AND flow_id=v_id;
   DELETE FROM public.erp_task_flows WHERE cafe_id=p_cafe_id AND id=v_id;
  ELSE RAISE EXCEPTION 'لا تملك صلاحية حذف هذا السجل' USING ERRCODE='42501'; END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'تغير السجل أو لم يعد موجودًا' USING ERRCODE='40001'; END IF;
  INSERT INTO public.erp_task_events(cafe_id,task_id,action,detail,actor) VALUES(p_cafe_id,v_id,'deleted',jsonb_build_object('kind',p_data->>'kind'),auth.uid());
 ELSIF p_action='settings' THEN
  IF jsonb_typeof(p_data->'enabledTargets') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'راجع الأقسام المختارة' USING ERRCODE='22023'; END IF;
  SELECT array_agg(DISTINCT value) INTO v_enabled FROM jsonb_array_elements_text(p_data->'enabledTargets');
  v_enabled:=coalesce(v_enabled,ARRAY[]::text[]);
  IF NOT v_enabled <@ ARRAY['customer','supplier','invoice','expense','purchase','item','warehouse','employee','purchase_request','purchase_rfq','purchase_quotation','purchase_order','purchase_document','work_order','appointment','customer_appointment','asset','asset_unit','employee_asset','custody','asset_type','asset_location','workflow','workflow_type','booking','booking_service','booking_package','rental_reservation','rental_contract','rental_unit','rental_installment','contract','payslip','payrun','loan','salary_component','salary_structure','cheque_book','payable_cheque','receivable_cheque','receipt','journal','account','cost_center','financial_custody','inventory_document','stocktake','inventory_request','time_entry','time_project','time_activity','task','task_type','task_template','task_flow']::text[] THEN RAISE EXCEPTION 'قسم غير صالح للربط' USING ERRCODE='22023'; END IF;
  SELECT revision INTO v_rev FROM public.erp_task_settings WHERE cafe_id=p_cafe_id FOR UPDATE;
  IF coalesce(v_rev,0) IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت الإعدادات أعد تحميلها' USING ERRCODE='40001'; END IF;
  INSERT INTO public.erp_task_settings(cafe_id,enabled_targets) VALUES(p_cafe_id,v_enabled) ON CONFLICT(cafe_id) DO UPDATE SET enabled_targets=excluded.enabled_targets,revision=erp_task_settings.revision+1;
 ELSE RAISE EXCEPTION 'إجراء غير معروف' USING ERRCODE='22023'; END IF;
 result:=jsonb_build_object('id',v_id,'saved',true);
 INSERT INTO erp_task_private.requests(cafe_id,request_id,actor,action,payload,result) VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_data,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_time_cost_report_before_scope(p_cafe_id uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE enabled boolean;BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'time','read');
 PERFORM erp_time_private.authorize(p_cafe_id,'read');IF p_from IS NULL OR p_to IS NULL OR p_to<p_from OR p_to-p_from>3660 THEN RAISE EXCEPTION 'فترة التقرير غير صالحة';END IF;
 SELECT include_wages INTO enabled FROM public.erp_time_settings WHERE cafe_id=p_cafe_id;
 RETURN jsonb_build_object('enabled',coalesce(enabled,false),'currency','SAR','classification','accrued_time_cost','cashPaid',0,'from',p_from,'to',p_to,'total',CASE WHEN enabled THEN coalesce((SELECT sum(round(extract(epoch FROM least(ends_at,(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh')-greatest(starts_at,p_from::timestamp AT TIME ZONE 'Asia/Riyadh'))/3600*cost_rate,2)) FROM public.erp_time_entries WHERE cafe_id=p_cafe_id AND ends_at IS NOT NULL AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(p_from::timestamp AT TIME ZONE 'Asia/Riyadh',(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh','[)')),0) ELSE 0 END,'rows',CASE WHEN enabled THEN coalesce((SELECT jsonb_agg(jsonb_build_object('entryId',id,'workerKind',worker_kind,'workerId',worker_id,'projectId',project_id,'sourceKind',source_kind,'sourceId',source_id,'seconds',extract(epoch FROM least(ends_at,(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh')-greatest(starts_at,p_from::timestamp AT TIME ZONE 'Asia/Riyadh')),'hourlyRate',cost_rate,'amount',round(extract(epoch FROM least(ends_at,(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh')-greatest(starts_at,p_from::timestamp AT TIME ZONE 'Asia/Riyadh'))/3600*cost_rate,2))) FROM public.erp_time_entries WHERE cafe_id=p_cafe_id AND ends_at IS NOT NULL AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(p_from::timestamp AT TIME ZONE 'Asia/Riyadh',(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh','[)')),'[]') ELSE '[]'::jsonb END);
END$function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_time_read_before_scope(p_cafe_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE sources jsonb:='[]';source_row record;source_data jsonb;BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'time','read');
 PERFORM erp_time_private.authorize(p_cafe_id,'read');
 IF(p_from IS NULL)<>(p_to IS NULL) OR p_to<p_from OR p_to-p_from>3660 THEN RAISE EXCEPTION 'فترة العرض غير صالحة';END IF;
 FOR source_row IN SELECT id,'work_order' kind FROM erp_branch_private.erp_work_orders WHERE cafe_id=p_cafe_id UNION ALL SELECT id,'workflow' FROM erp_branch_private.erp_workflow_records WHERE cafe_id=p_cafe_id UNION ALL SELECT id,'task' FROM erp_branch_private.erp_tasks WHERE cafe_id=p_cafe_id UNION ALL SELECT id,'contracting_project' FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id AND kind='project' LIMIT 2000 LOOP
  BEGIN source_data:=erp_time_private.source(p_cafe_id,source_row.kind,source_row.id);sources:=sources||jsonb_build_array(source_data||jsonb_build_object('id',source_row.id,'kind',source_row.kind));EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 END LOOP;
 RETURN jsonb_build_object('serverNow',clock_timestamp(),'entries',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'revision',e.revision,'workerKind',e.worker_kind,'workerId',e.worker_id,'workerName',CASE WHEN e.worker_kind='employee' THEN coalesce(h.first_name||' '||h.last_name,'موظف') ELSE coalesce(s.name,'المالك') END,'projectId',e.project_id,'projectName',p.name,'activityId',e.activity_id,'activityName',a.name,'customerId',p.customer_id,'start',e.starts_at,'end',e.ends_at,'seconds',extract(epoch FROM coalesce(e.ends_at,clock_timestamp())-e.starts_at)::integer,'note',e.note,'billable',e.billable,'sourceKind',e.source_kind,'sourceId',e.source_id,'costRate',e.cost_rate,'billingRate',e.billing_rate,'batchId',e.batch_id,'invoiceId',e.invoice_id,'createdAt',e.created_at) ORDER BY e.starts_at DESC) FROM erp_branch_private.erp_time_entries e JOIN erp_branch_private.erp_time_catalogs p ON p.cafe_id=e.cafe_id AND p.id=e.project_id JOIN erp_branch_private.erp_time_catalogs a ON a.cafe_id=e.cafe_id AND a.id=e.activity_id LEFT JOIN erp_branch_private.bf_staff s ON s.cafe_id=e.cafe_id AND s.user_id=e.worker_id AND e.worker_kind='user' LEFT JOIN erp_branch_private.erp_hr_employees h ON h.cafe_id=e.cafe_id AND h.id=e.worker_id AND e.worker_kind='employee' WHERE e.cafe_id=p_cafe_id AND (p_from IS NULL OR e.ends_at IS NULL OR e.starts_at<(p_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh' AND e.ends_at>p_from::timestamp AT TIME ZONE 'Asia/Riyadh')),'[]'),
 'catalogs',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'revision',revision,'kind',kind,'name',name,'active',active,'customerId',customer_id,'rate',rate,'description',description) ORDER BY kind,name) FROM erp_branch_private.erp_time_catalogs WHERE cafe_id=p_cafe_id),'[]'),
 'rates',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'revision',revision,'workerKind',worker_kind,'workerId',worker_id,'costRate',cost_rate,'billingRate',billing_rate,'effectiveFrom',effective_from) ORDER BY effective_from DESC) FROM erp_branch_private.erp_time_rates WHERE cafe_id=p_cafe_id),'[]'),
 'workers',coalesce((SELECT jsonb_agg(w) FROM(SELECT id,'employee' kind,first_name||' '||last_name name,active,user_id AS "userId" FROM erp_branch_private.erp_hr_employees WHERE cafe_id=p_cafe_id UNION ALL SELECT user_id,'user',name,active,user_id FROM erp_branch_private.bf_staff s WHERE cafe_id=p_cafe_id AND NOT EXISTS(SELECT 1 FROM erp_branch_private.erp_hr_employees WHERE cafe_id=p_cafe_id AND user_id=s.user_id AND active) UNION ALL SELECT owner_user_id,'user','المالك',true,owner_user_id FROM public.cafes c WHERE id=p_cafe_id AND NOT EXISTS(SELECT 1 FROM erp_branch_private.bf_staff WHERE cafe_id=c.id AND user_id=c.owner_user_id) AND NOT EXISTS(SELECT 1 FROM erp_branch_private.erp_hr_employees WHERE cafe_id=c.id AND user_id=c.owner_user_id AND active))w),'[]'),
 'batches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'revision',revision,'draftId',draft_id,'invoiceId',invoice_id,'status',status,'createdAt',created_at,'total',total) ORDER BY created_at DESC) FROM erp_branch_private.erp_time_batches WHERE cafe_id=p_cafe_id),'[]'),
 'settings',coalesce((SELECT jsonb_build_object('revision',revision,'includeWages',include_wages,'defaultBillingRate',default_billing_rate,'defaultCostRate',default_cost_rate) FROM erp_branch_private.erp_time_settings WHERE cafe_id=p_cafe_id),' {"revision":0,"includeWages":false,"defaultBillingRate":0,"defaultCostRate":0}'::jsonb),'sources',sources,
 'events',coalesce((SELECT jsonb_agg(x) FROM(SELECT id,action,at,record_id AS "recordId" FROM erp_branch_private.erp_time_events WHERE cafe_id=p_cafe_id ORDER BY at DESC LIMIT 500)x),'[]'),'canCreate',erp_time_private.allowed(p_cafe_id,'create'),'canUpdate',erp_time_private.allowed(p_cafe_id,'update'),'canDelete',erp_time_private.allowed(p_cafe_id,'delete'),'canApprove',erp_time_private.allowed(p_cafe_id,'approve'),'canConfigure',erp_time_private.allowed(p_cafe_id,'settings'));
END$function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_time_write_before_scope(p_cafe_id uuid, p_action text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<time_write>>
DECLARE rid uuid:=nullif(p_payload->>'id','')::uuid;rev integer:=coalesce((p_payload->>'revision')::integer,0);previous erp_time_private.requests%ROWTYPE;entry public.erp_time_entries%ROWTYPE;batch public.erp_time_batches%ROWTYPE;old_revision integer;result jsonb;row jsonb;ids uuid[]:='{}';end_at timestamptz;action_name text;BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'time',CASE WHEN p_action IN('settings','catalog','delete_catalog','rate','delete_rate') THEN 'settings' WHEN p_action='delete' THEN 'delete' WHEN p_action IN('invoice','cancel_invoice') THEN 'approve' WHEN p_action IN('start','import') OR p_action='entry' AND coalesce((p_payload->>'revision')::integer,0)=0 THEN 'create' ELSE 'update' END);
 IF auth.uid() IS NULL OR p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>1000000 THEN RAISE EXCEPTION 'طلب تتبع الوقت غير صالح';END IF;
 action_name:=CASE WHEN p_action IN('settings','catalog','delete_catalog','rate','delete_rate') THEN 'settings' WHEN p_action='delete' THEN 'delete' WHEN p_action IN('invoice','cancel_invoice') THEN 'approve' WHEN p_action IN('start','import') OR p_action='entry' AND rev=0 THEN 'create' ELSE 'update' END;PERFORM erp_time_private.authorize(p_cafe_id,action_name);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));SELECT * INTO previous FROM erp_time_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF previous.actor<>auth.uid() OR previous.action<>p_action OR previous.payload<>p_payload THEN RAISE EXCEPTION 'مفتاح الطلب مستخدم لعملية أخرى' USING ERRCODE='22023';END IF;RETURN previous.result;END IF;result:=jsonb_build_object('id',rid);
 IF p_action IN('entry','start') THEN rid:=erp_time_private.save_entry(p_cafe_id,p_payload,p_action='start');result:=jsonb_build_object('id',rid);
 ELSIF p_action='import' THEN
  IF jsonb_typeof(p_payload->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'rows') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'الحد الأقصى مائة سجل في الاستيراد';END IF;
  FOR row IN SELECT value FROM jsonb_array_elements(p_payload->'rows') LOOP IF coalesce((row->>'revision')::integer,0)<>0 THEN RAISE EXCEPTION 'الاستيراد يضيف سجلات جديدة فقط';END IF;ids:=array_append(ids,erp_time_private.save_entry(p_cafe_id,row,false));END LOOP;result:=jsonb_build_object('ids',ids,'count',cardinality(ids));
 ELSIF p_action IN('stop','delete') THEN
  SELECT * INTO entry FROM public.erp_time_entries WHERE cafe_id=p_cafe_id AND id=rid FOR UPDATE;IF entry.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'السجل تغير أو غير متاح' USING ERRCODE='40001';END IF;
  IF entry.batch_id IS NOT NULL OR entry.invoice_id IS NOT NULL THEN RAISE EXCEPTION 'الساعات محجوزة أو مفوترة';END IF;
  IF p_action='delete' THEN DELETE FROM public.erp_time_entries WHERE cafe_id=p_cafe_id AND id=rid;ELSE
   IF entry.ends_at IS NOT NULL THEN RAISE EXCEPTION 'المؤقت متوقف بالفعل';END IF;end_at:=clock_timestamp();IF end_at<=entry.starts_at THEN RAISE EXCEPTION 'انتظر بداية المؤقت';END IF;
   UPDATE public.erp_time_entries SET ends_at=end_at,revision=revision+1 WHERE cafe_id=p_cafe_id AND id=rid;
  END IF;
 ELSIF p_action='catalog' THEN
  SELECT revision INTO old_revision FROM public.erp_time_catalogs WHERE cafe_id=p_cafe_id AND id=rid;IF coalesce(old_revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'التعريف تغير' USING ERRCODE='40001';END IF;
  IF rid IS NULL OR coalesce(p_payload->>'kind','') NOT IN('project','activity') OR length(btrim(coalesce(p_payload->>'name',''))) NOT BETWEEN 1 AND 160 OR jsonb_typeof(p_payload->'active') IS DISTINCT FROM 'boolean' OR coalesce((p_payload->>'rate')::numeric,-1) NOT BETWEEN 0 AND 10000000 OR length(coalesce(p_payload->>'description',''))>2000 THEN RAISE EXCEPTION 'راجع بيانات المشروع أو النشاط';END IF;
  IF nullif(p_payload->>'customerId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=(p_payload->>'customerId')::uuid AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
  IF EXISTS(SELECT 1 FROM public.erp_time_catalogs c WHERE cafe_id=p_cafe_id AND id=rid AND (kind<>p_payload->>'kind' OR customer_id IS DISTINCT FROM nullif(p_payload->>'customerId','')::uuid)) AND EXISTS(SELECT 1 FROM public.erp_time_entries WHERE cafe_id=p_cafe_id AND(project_id=rid OR activity_id=rid)) THEN RAISE EXCEPTION 'لا تغير نوع التعريف أو العميل بعد تسجيل الوقت';END IF;
  INSERT INTO public.erp_time_catalogs(id,cafe_id,revision,kind,name,active,customer_id,rate,description) VALUES(rid,p_cafe_id,rev+1,p_payload->>'kind',btrim(p_payload->>'name'),(p_payload->>'active')::boolean,nullif(p_payload->>'customerId','')::uuid,(p_payload->>'rate')::numeric,coalesce(p_payload->>'description','')) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,kind=excluded.kind,name=excluded.name,active=excluded.active,customer_id=excluded.customer_id,rate=excluded.rate,description=excluded.description WHERE erp_time_catalogs.cafe_id=p_cafe_id;IF NOT FOUND THEN RAISE EXCEPTION 'التعريف غير متاح' USING ERRCODE='42501';END IF;
 ELSIF p_action='delete_catalog' THEN DELETE FROM public.erp_time_catalogs WHERE cafe_id=p_cafe_id AND id=rid AND revision=rev;IF NOT FOUND THEN RAISE EXCEPTION 'التعريف تغير' USING ERRCODE='40001';END IF;
 ELSIF p_action='settings' THEN
  SELECT revision INTO old_revision FROM public.erp_time_settings WHERE cafe_id=p_cafe_id;IF coalesce(old_revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'الإعدادات تغيرت' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(p_payload->'includeWages') IS DISTINCT FROM 'boolean' OR coalesce((p_payload->>'defaultCostRate')::numeric,-1) NOT BETWEEN 0 AND 10000000 OR coalesce((p_payload->>'defaultBillingRate')::numeric,-1) NOT BETWEEN 0 AND 10000000 THEN RAISE EXCEPTION 'راجع إعدادات التكلفة والأسعار';END IF;
  INSERT INTO public.erp_time_settings VALUES(p_cafe_id,rev+1,(p_payload->>'includeWages')::boolean,(p_payload->>'defaultBillingRate')::numeric,(p_payload->>'defaultCostRate')::numeric) ON CONFLICT(cafe_id) DO UPDATE SET revision=excluded.revision,include_wages=excluded.include_wages,default_billing_rate=excluded.default_billing_rate,default_cost_rate=excluded.default_cost_rate;
 ELSIF p_action='rate' THEN
  PERFORM erp_time_private.worker(p_cafe_id,p_payload->>'workerKind',(p_payload->>'workerId')::uuid);SELECT revision INTO old_revision FROM public.erp_time_rates WHERE cafe_id=p_cafe_id AND id=rid;IF coalesce(old_revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'سعر الساعة تغير' USING ERRCODE='40001';END IF;
  IF rid IS NULL OR coalesce((p_payload->>'costRate')::numeric,-1) NOT BETWEEN 0 AND 10000000 OR coalesce((p_payload->>'billingRate')::numeric,-1) NOT BETWEEN 0 AND 10000000 OR nullif(p_payload->>'effectiveFrom','')::date IS NULL THEN RAISE EXCEPTION 'راجع معدل الساعة وتاريخ السريان';END IF;
  INSERT INTO public.erp_time_rates(id,cafe_id,revision,worker_kind,worker_id,cost_rate,billing_rate,effective_from) VALUES(rid,p_cafe_id,rev+1,p_payload->>'workerKind',(p_payload->>'workerId')::uuid,(p_payload->>'costRate')::numeric,(p_payload->>'billingRate')::numeric,(p_payload->>'effectiveFrom')::date) ON CONFLICT(id) DO UPDATE SET revision=excluded.revision,worker_kind=excluded.worker_kind,worker_id=excluded.worker_id,cost_rate=excluded.cost_rate,billing_rate=excluded.billing_rate,effective_from=excluded.effective_from WHERE erp_time_rates.cafe_id=p_cafe_id;IF NOT FOUND THEN RAISE EXCEPTION 'السعر غير متاح' USING ERRCODE='42501';END IF;
 ELSIF p_action='delete_rate' THEN DELETE FROM public.erp_time_rates WHERE cafe_id=p_cafe_id AND id=rid AND revision=rev;IF NOT FOUND THEN RAISE EXCEPTION 'السعر تغير' USING ERRCODE='40001';END IF;
 ELSIF p_action='invoice' THEN result:=erp_time_private.make_invoice(p_cafe_id,p_payload);rid:=(result->>'id')::uuid;
 ELSIF p_action='cancel_invoice' THEN
  SELECT * INTO batch FROM public.erp_time_batches WHERE cafe_id=p_cafe_id AND id=rid FOR UPDATE;IF batch.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'دفعة الفوترة تغيرت' USING ERRCODE='40001';END IF;
  IF batch.status<>'draft' OR batch.invoice_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=batch.draft_id) THEN RAISE EXCEPTION 'الفاتورة صادرة ولا يمكن تحرير ساعاتها';END IF;
  UPDATE public.erp_time_entries SET batch_id=NULL,revision=revision+1 WHERE cafe_id=p_cafe_id AND batch_id=rid;UPDATE public.erp_time_batches SET status='cancelled',revision=revision+1 WHERE cafe_id=p_cafe_id AND id=rid;
 ELSE RAISE EXCEPTION 'إجراء تتبع الوقت غير متاح';END IF;
 INSERT INTO public.erp_time_events(cafe_id,record_id,action,detail,actor) VALUES(p_cafe_id,rid,p_action,p_payload,auth.uid());INSERT INTO erp_time_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_payload,result);RETURN result;
END$function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_work_order_targets_before_scope(p_cafe_id uuid, p_kind text, p_query text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE result jsonb;BEGIN
 PERFORM erp_work_private.authorize(p_cafe_id);IF length(p_query)>120 THEN RAISE EXCEPTION 'اختصر نص البحث';END IF;
 IF p_kind='document' THEN SELECT coalesce(jsonb_agg(erp_work_private.target(p_cafe_id,p_kind,id)),'[]') INTO result FROM(SELECT id FROM public.bf_documents WHERE cafe_id=p_cafe_id AND(number::text ILIKE '%'||p_query||'%' OR note ILIKE '%'||p_query||'%') ORDER BY created_at DESC LIMIT 100)d;
 ELSIF p_kind='quotation' THEN SELECT coalesce(jsonb_agg(erp_work_private.target(p_cafe_id,p_kind,id)),'[]') INTO result FROM(SELECT id FROM public.bf_quotes WHERE cafe_id=p_cafe_id AND(EXISTS(SELECT 1 FROM erp_settings_private.numbers sn WHERE sn.cafe_id=p_cafe_id AND sn.context='sales_quote' AND sn.record_id=bf_quotes.id AND sn.value ILIKE '%'||p_query||'%' AND erp_settings_private.sales_number_visible(p_cafe_id,to_jsonb(bf_quotes))) OR number::text ILIKE '%'||p_query||'%' OR customer_name ILIKE '%'||p_query||'%') ORDER BY created_at DESC LIMIT 100)d;
 ELSIF p_kind='credit_note' THEN SELECT coalesce(jsonb_agg(erp_work_private.target(p_cafe_id,p_kind,id)),'[]') INTO result FROM(SELECT id FROM public.bf_credit_notes WHERE cafe_id=p_cafe_id AND status<>'deleted' AND(EXISTS(SELECT 1 FROM erp_settings_private.numbers sn WHERE sn.cafe_id=p_cafe_id AND sn.context='sales_credit_note' AND sn.record_id=bf_credit_notes.id AND sn.value ILIKE '%'||p_query||'%' AND erp_settings_private.sales_number_visible(p_cafe_id,to_jsonb(bf_credit_notes))) OR number::text ILIKE '%'||p_query||'%' OR customer_name ILIKE '%'||p_query||'%') ORDER BY created_at DESC LIMIT 100)d;
 ELSIF p_kind='task' THEN SELECT coalesce(jsonb_agg(erp_work_private.target(p_cafe_id,p_kind,id)),'[]') INTO result FROM(SELECT id FROM public.erp_tasks WHERE cafe_id=p_cafe_id AND(title ILIKE '%'||p_query||'%' OR code ILIKE '%'||p_query||'%') ORDER BY created_at DESC LIMIT 100)d;
 ELSE RAISE EXCEPTION 'نوع المعاملة غير صالح';END IF;RETURN result;
END$function$

CREATE OR REPLACE FUNCTION erp_branch_private.erp_work_orders_write_before_scope(p_cafe_id uuid, p_action text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text;cfg jsonb;old public.erp_work_orders%ROWTYPE;req public.erp_work_order_requests%ROWTYPE;a public.erp_work_order_activities%ROWTYPE;rid uuid;rev integer;customer uuid;ids uuid[];st text;result jsonb;next_num bigint;next_code text;vals jsonb;target uuid;payload jsonb;x jsonb;idx integer;repeat_count integer;start_at timestamptz;end_at timestamptz;
BEGIN
 r:=erp_work_private.authorize(p_cafe_id,true,CASE WHEN p_action='settings' THEN 'settings' WHEN p_action='delete' THEN 'delete' WHEN p_action='save' AND coalesce((p_payload->>'revision')::integer,0)=0 OR p_action='copy' THEN 'create' WHEN p_action IN('status','financial','invoice','advance','debit') THEN 'approve' ELSE 'update' END);
 IF p_request_id IS NULL OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>500000 THEN RAISE EXCEPTION 'طلب غير صالح' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO req FROM public.erp_work_order_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF req.actor<>auth.uid() OR req.action<>p_action OR req.payload<>p_payload THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى' USING ERRCODE='22023';END IF;RETURN req.result;END IF;
 cfg:=erp_work_private.settings(p_cafe_id);rid:=nullif(p_payload->>'id','')::uuid;rev:=(p_payload->>'revision')::integer;
 IF p_action='settings' THEN
  IF r NOT IN('owner','manager') THEN RAISE EXCEPTION 'لا تملك صلاحية الإعدادات' USING ERRCODE='42501';END IF;
