 SELECT coalesce(jsonb_agg(jsonb_build_object('recordId',l.record_id,'kind',l.kind,'targetId',l.target_id,'at',l.at,'title',entry->>'label','documentKind',entry->>'kind','amount',coalesce(entry->'amount','0'),'outstanding',coalesce(entry->'outstanding','0'))),'[]') INTO links FROM erp_branch_private.erp_workflow_links l CROSS JOIN LATERAL erp_work_private.target(l.cafe_id,l.kind,l.target_id)entry WHERE l.cafe_id=p_cafe_id AND l.record_id=ANY(financial);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'recordId',e.record_id,'action',e.action,'note',e.note,'shared',coalesce((e.detail->>'shared')::boolean,false),'occurredAt',e.detail->>'occurredAt','actionId',e.detail->>'actionId','status',e.detail->>'status','at',e.at,'actorName',coalesce(s.name,'المالك')) ORDER BY e.at DESC),'[]') INTO events FROM erp_branch_private.erp_workflow_events e LEFT JOIN erp_branch_private.bf_staff s ON s.cafe_id=e.cafe_id AND s.user_id=e.actor WHERE e.cafe_id=p_cafe_id AND(e.record_id=ANY(visible) OR can_config AND e.record_id IS NULL);
