    INSERT INTO public.erp_workflow_records(id,cafe_id,type_id,code,status,draft,payload,created_by) VALUES(target,p_cafe_id,r.type_id,code,t.config#>>'{statuses,0,id}',true,data,auth.uid());UPDATE public.erp_workflow_types SET config=jsonb_set(erp_workflow_types.config,'{nextNumber}',to_jsonb(num+1)),revision=revision+1 WHERE cafe_id=p_cafe_id AND id=r.type_id;result:=jsonb_build_object('id',target);ev_record:=target;
   ELSIF p_action IN('status','note') THEN
    st:=nullif(p_payload->>'status','');IF st IS NOT NULL THEN
     IF r.draft OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(t.config->'statuses') state_row WHERE state_row->>'id'=st) OR NOT erp_workflow_private.allowed(p_cafe_id,t.config,'transition',st) THEN RAISE EXCEPTION 'الانتقال إلى الحالة غير مسموح' USING ERRCODE='42501';END IF;
     UPDATE public.erp_workflow_records SET status=st WHERE cafe_id=p_cafe_id AND id=rid;
    END IF;
    IF p_action='note' THEN IF length(btrim(coalesce(p_payload->>'note',''))) NOT BETWEEN 1 AND 20000 OR nullif(p_payload->>'occurredAt','')::timestamptz IS NULL OR jsonb_typeof(p_payload->'shared') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع الملاحظة وتاريخها';END IF;IF nullif(p_payload->>'actionId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(t.config->'actions') action_row WHERE action_row->>'id'=p_payload->>'actionId') THEN RAISE EXCEPTION 'الإجراء غير متاح';END IF;END IF;
   ELSIF p_action IN('link','unlink') THEN
    IF p_action='link' THEN PERFORM erp_workflow_private.link(p_cafe_id,rid,p_payload->>'kind',(p_payload->>'targetId')::uuid);ELSE
     IF NOT ARRAY['budget','customerId']::text[]<@erp_workflow_private.fields(p_cafe_id,t.config,'update') THEN RAISE EXCEPTION 'صلاحيات الحقول لا تسمح بإلغاء الارتباط' USING ERRCODE='42501';END IF;
     DELETE FROM public.erp_workflow_links WHERE cafe_id=p_cafe_id AND record_id=rid AND kind=p_payload->>'kind' AND target_id=(p_payload->>'targetId')::uuid;IF NOT FOUND THEN RAISE EXCEPTION 'الارتباط غير متاح';END IF;
    END IF;
   ELSIF p_action='activity' THEN
    target:=(p_payload->>'id')::uuid;SELECT revision INTO old_revision FROM public.erp_workflow_activities WHERE cafe_id=p_cafe_id AND id=target AND record_id=rid;
    IF coalesce(old_revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'الموعد تغير' USING ERRCODE='40001';END IF;
    begin_at:=(p_payload->>'start')::timestamptz;end_at:=(p_payload->>'end')::timestamptz;counted:=(p_payload->>'repeatCount')::integer;
    IF target IS NULL OR begin_at IS NULL OR end_at<=begin_at OR counted IS NULL OR counted NOT BETWEEN 1 AND 52 OR(old_revision IS NOT NULL AND counted<>1) OR coalesce((p_payload->>'repeatDays')::integer,0) NOT BETWEEN 1 AND 365 OR length(btrim(coalesce(p_payload->>'title',''))) NOT BETWEEN 1 AND 160 OR coalesce(p_payload->>'status','') NOT IN('planned','done','cancelled') OR length(coalesce(p_payload->>'note',''))>20000 THEN RAISE EXCEPTION 'راجع الموعد والتكرار';END IF;
    SELECT coalesce(array_agg(value::uuid),'{}') INTO ids FROM jsonb_array_elements_text(p_payload->'staffIds');PERFORM erp_work_private.staff(p_cafe_id,ids);
    FOR idx IN 0..counted-1 LOOP data:=p_payload-'id'-'revision'-'recordId'||jsonb_build_object('start',begin_at+make_interval(days=>idx*(p_payload->>'repeatDays')::integer),'end',end_at+make_interval(days=>idx*(p_payload->>'repeatDays')::integer),'repeatCount',1);INSERT INTO public.erp_workflow_activities(id,cafe_id,record_id,payload) VALUES(CASE WHEN idx=0 THEN target ELSE gen_random_uuid() END,p_cafe_id,rid,data) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,revision=erp_workflow_activities.revision+1 WHERE erp_workflow_activities.cafe_id=p_cafe_id AND erp_workflow_activities.record_id=rid;IF NOT FOUND THEN RAISE EXCEPTION 'الموعد غير متاح' USING ERRCODE='42501';END IF;END LOOP;
  ELSIF p_action='financial' THEN
   IF r.draft OR coalesce(p_payload->>'operation','') NOT IN('purchase','treasury','stock_adjust','stock_transfer','journal','refund','settlement') OR jsonb_typeof(p_payload->'values') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'راجع نوع المعاملة واحفظ الأمر أولًا';END IF;
   data:=p_payload->'values';IF p_payload->>'operation' IN('refund','settlement') AND NOT EXISTS(SELECT 1 FROM public.erp_workflow_links WHERE cafe_id=p_cafe_id AND record_id=rid AND kind='document' AND target_id=(data->>'documentId')::uuid) THEN RAISE EXCEPTION 'اربط الفاتورة أولًا';END IF;
   val:=public.brand_finance_execute(p_cafe_id,p_payload->>'operation',data,p_request_id);target:=nullif(val->>'id','')::uuid;
   IF target IS NULL OR val->>'status'='pending' THEN RAISE EXCEPTION 'المعاملة لم تعتمد ماليًا بعد';END IF;PERFORM erp_workflow_private.link(p_cafe_id,rid,'document',target);
  ELSIF p_action='debit' THEN
   IF r.draft OR NOT EXISTS(SELECT 1 FROM public.erp_workflow_links WHERE cafe_id=p_cafe_id AND record_id=rid AND kind='document' AND target_id=(p_payload->>'sourceId')::uuid) THEN RAISE EXCEPTION 'اختر فاتورة مرتبطة بأمر محفوظ';END IF;
   val:=public.brand_finance_invoice_extensions(p_cafe_id,(p_payload->>'sourceId')::uuid,'debit',jsonb_build_object('requestId',p_request_id,'amount',p_payload->'amount','vatRate',p_payload->'taxRate','description',p_payload->>'description','reason',p_payload->>'reason'));
   PERFORM erp_workflow_private.link(p_cafe_id,rid,'document',(val->>'id')::uuid);
  ELSIF p_action='advance' THEN
   IF r.draft OR nullif(r.payload->>'customerId','')::uuid IS NULL THEN RAISE EXCEPTION 'احفظ الأمر واختر العميل أولًا';END IF;
   val:=public.brand_finance_customer_credit(p_cafe_id,'receive',jsonb_build_object('partyId',nullif(r.payload->>'customerId','')::uuid,'requestId',p_request_id,'accountId',p_payload->>'accountId','amount',p_payload->'amount','note',left('دفعة دورة عمل '||r.code||' '||coalesce(p_payload->>'note',''),1000)));PERFORM erp_workflow_private.link(p_cafe_id,rid,'document',(val->>'id')::uuid);
  ELSIF p_action='invoice' THEN
   IF r.draft OR nullif(r.payload->>'customerId','')::uuid IS NULL OR coalesce((p_payload->>'amount')::numeric,0)<=0 OR coalesce((p_payload->>'taxRate')::numeric,-1) NOT BETWEEN 0 AND 100 THEN RAISE EXCEPTION 'اختر العميل وأدخل قيمة الفاتورة والضريبة';END IF;
   target:=gen_random_uuid();data:=jsonb_build_object('invoice',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('key',1,'productId','','quantity',1,'price',p_payload->'amount','name',left((r.payload->>'title'),160),'kind','service','vatRate',p_payload->'taxRate','taxCategory',CASE WHEN(p_payload->>'taxRate')::numeric=0 THEN 'O' ELSE 'S' END,'exemptionReason',coalesce(p_payload->>'taxReason',''))),'warehouseId','','partyId',nullif(r.payload->>'customerId','')::uuid,'accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','taxInclusive',false,'note','دورة عمل '||r.code,'currency','SAR','exchangeRate',1),'issuer',jsonb_build_object('name','','address','','vatNumber',''),'supplyDate',current_date,'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb);
   PERFORM public.brand_finance_save_invoice_draft(p_cafe_id,target,0,data);INSERT INTO public.erp_workflow_drafts VALUES(p_cafe_id,rid,target);result:=result||jsonb_build_object('draftId',target);
  ELSIF p_action='task' THEN
   val:=public.erp_tasks_execute(p_cafe_id,'save',jsonb_build_object('id',NULL,'revision',0,'title',p_payload->>'title','code','','priority','medium','typeId',p_payload->>'typeId','assigneeId',p_payload->>'assigneeId','dueDate',p_payload->'dueDate','description',p_payload->>'note','targetKind',CASE WHEN nullif(r.payload->>'customerId','')::uuid IS NOT NULL THEN 'customer' END,'targetId',nullif(r.payload->>'customerId','')::uuid),p_request_id);
   PERFORM erp_workflow_private.link(p_cafe_id,rid,'task',(val->>'id')::uuid);

   ELSE RAISE EXCEPTION 'إجراء الدورة غير متاح' USING ERRCODE='22023';END IF;
   IF p_action NOT IN('delete','copy') THEN UPDATE public.erp_workflow_records SET revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=p_cafe_id AND id=rid;END IF;
  END IF;
 END IF;
 INSERT INTO public.erp_workflow_events(cafe_id,type_id,record_id,action,note,detail,actor) VALUES(p_cafe_id,ev_type,ev_record,p_action,CASE WHEN p_action='note' THEN p_payload->>'note' ELSE '' END,p_payload,auth.uid());INSERT INTO erp_workflow_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_payload,result);RETURN result;
END$function$

CREATE OR REPLACE FUNCTION erp_branch_private.filter_json(c uuid, b uuid, j jsonb, context text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE result jsonb;key text;v jsonb;k text;filtered jsonb;BEGIN
 IF b IS NULL OR j IS NULL THEN RETURN j;END IF;
 k:=CASE context WHEN 'customers' THEN 'customer' WHEN 'suppliers' THEN 'supplier' WHEN 'items' THEN 'item' WHEN 'products' THEN 'item' WHEN 'accounts' THEN 'account' WHEN 'costCenters' THEN 'cost_center' WHEN 'centers' THEN 'cost_center' WHEN 'unitTemplates' THEN 'unit_template' ELSE '' END;
 IF jsonb_typeof(j)='array' THEN result:='[]';FOR v IN SELECT value FROM jsonb_array_elements(j) LOOP IF erp_branch_private.row_allowed(c,b,v,k) THEN filtered:=erp_branch_private.filter_json(c,b,v,context);IF filtered IS NOT NULL THEN result:=result||jsonb_build_array(filtered);END IF;END IF;END LOOP;RETURN result;
 ELSIF jsonb_typeof(j)='object' THEN
  IF NOT erp_branch_private.row_allowed(c,b,j,k) THEN RETURN NULL;END IF;
  result:='{}';FOR key,v IN SELECT * FROM jsonb_each(j) LOOP result:=result||jsonb_build_object(key,erp_branch_private.filter_json(c,b,v,key));END LOOP;RETURN result;
 END IF;RETURN j;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.guard_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE c uuid:=OLD.cafe_id;b uuid;row jsonb:=to_jsonb(OLD);kind text;BEGIN
 IF nullif(current_setting('erp.branch_cafe',true),'') IS DISTINCT FROM c::text THEN IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END IF;b:=nullif(current_setting('erp.branch_id',true),'')::uuid;
 kind:=CASE TG_TABLE_NAME WHEN 'bf_parties' THEN row->>'kind' WHEN 'bf_items' THEN 'item' WHEN 'bf_accounts' THEN 'account' WHEN 'erp_cost_centers' THEN 'cost_center' WHEN 'erp_inventory_catalogs' THEN CASE WHEN row->>'kind'='unit_template' THEN 'unit_template' ELSE '' END ELSE '' END;
 IF NOT erp_branch_private.row_allowed(c,b,row,kind) THEN RAISE EXCEPTION 'لا يمكن تعديل سجل خارج الفرع المختار' USING ERRCODE='42501';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE PERFORM erp_branch_private.assert_input(c,to_jsonb(NEW));RETURN NEW;END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.job_context(c uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE j jsonb;actual uuid;BEGIN
 j:=nullif(current_setting('erp.branch_job',true),'')::jsonb;IF j IS NULL OR j->>'cafe'<>c::text OR j->>'actor' IS DISTINCT FROM auth.uid()::text THEN RETURN NULL;END IF;
 SELECT branch_id INTO actual FROM public.erp_branch_records WHERE cafe_id=c AND table_name=j->>'table' AND record_id=(j->>'record')::uuid;
 IF to_jsonb(actual) IS DISTINCT FROM nullif(j->'branchId','null'::jsonb) THEN RAISE EXCEPTION 'Scheduled branch source changed' USING ERRCODE='40001';END IF;RETURN j;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.recurring_run_before_scope(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.bf_recurring_invoices%ROWTYPE;today date:=(now() AT TIME ZONE 'Asia/Riyadh')::date;draft uuid:=gen_random_uuid();doc jsonb;answer jsonb;last_day date;due_day date;next_day date;fields jsonb;err text;errcode text;
BEGIN
 SELECT * INTO r FROM public.bf_recurring_invoices WHERE id=p_id;
 IF NOT FOUND OR NOT pg_try_advisory_xact_lock(hashtextextended(r.cafe_id::text,60412)) THEN RETURN jsonb_build_object('status','busy');END IF;
 SELECT * INTO r FROM public.bf_recurring_invoices WHERE id=p_id FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','busy');END IF;
 IF r.status<>'active' OR r.next_date IS NULL OR r.next_issue_date IS NULL OR r.next_issue_date>today OR r.next_attempt_at>now() THEN RETURN jsonb_build_object('status','not_due');END IF;
 BEGIN
  IF coalesce(brand_finance_private.invoice_actor_role(r.cafe_id,r.actor_id),'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'لم تعد صلاحية مصدر الاشتراك متاحة' USING ERRCODE='42501';END IF;
  last_day:=brand_finance_private.recurring_date((r.payload->>'firstDate')::date,r.payload->>'unit',(r.payload->>'interval')::integer,r.generated_count+1)-1;
  due_day:=r.next_date+(r.payload->>'paymentTermsDays')::integer;
  doc:=r.payload->'document';fields:=coalesce(doc->'extraFields','[]')||jsonb_build_array(jsonb_build_object('key',900001,'title','تاريخ الاستحقاق','value',due_day));
  IF (r.payload->>'showPeriod')::boolean THEN fields:=fields||jsonb_build_array(jsonb_build_object('key',900002,'title','فترة الخدمة','value',r.next_date::text||' — '||last_day::text));END IF;
  doc:=jsonb_set(jsonb_set(doc,'{supplyDate}',to_jsonb(least(r.next_date,today)::text)),'{extraFields}',fields);
  INSERT INTO public.bf_invoice_drafts(id,cafe_id,payload,created_by,updated_by) VALUES(draft,r.cafe_id,doc,r.actor_id,r.actor_id);
  answer:=brand_finance_private.issue_company_invoice_actor(r.actor_id,false,r.cafe_id,draft,1,(r.totals->>'total')::numeric,NULL,'');
  INSERT INTO public.bf_recurring_occurrences(cafe_id,subscription_id,occurrence_index,scheduled_date,due_date,period_end,draft_id,document_id,subscription_revision) VALUES(r.cafe_id,r.id,r.generated_count,r.next_date,due_day,last_day,draft,(answer->>'id')::uuid,r.revision);
  next_day:=CASE WHEN (r.payload->>'count')::integer>0 AND r.generated_count+1>=(r.payload->>'count')::integer THEN NULL ELSE last_day+1 END;
  UPDATE public.bf_recurring_invoices SET generated_count=generated_count+1,next_date=next_day,next_issue_date=next_day-(r.payload->>'leadDays')::integer,status=CASE WHEN next_day IS NULL THEN 'completed' ELSE status END,last_issued_at=clock_timestamp(),next_attempt_at=now(),failure_count=0,last_error=NULL,revision=revision+1,updated_at=clock_timestamp() WHERE id=r.id;
  INSERT INTO public.bf_recurring_events(cafe_id,subscription_id,actor_id,action) VALUES(r.cafe_id,r.id,r.actor_id,'issued');
  RETURN jsonb_build_object('status','issued','invoiceId',answer->>'id','number',answer->'number');
 EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS err=MESSAGE_TEXT,errcode=RETURNED_SQLSTATE;
  err:=CASE WHEN err~'[ء-ي]' THEN left(err,500) WHEN errcode='42501' THEN 'توقفت صلاحية الإصدار أو باقة النظام للعلامة' ELSE 'تعذر إصدار الفاتورة راجع بيانات الاشتراك وإعدادات الفواتير' END;
  UPDATE public.bf_recurring_invoices SET failure_count=failure_count+1,last_error=err,next_attempt_at=now()+make_interval(mins=>least(60,5*(failure_count+1))),updated_at=clock_timestamp() WHERE id=r.id;
  INSERT INTO public.bf_recurring_events(cafe_id,subscription_id,actor_id,action,note) VALUES(r.cafe_id,r.id,r.actor_id,'failed',err);
  RETURN jsonb_build_object('status','failed','message',err);
 END;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.report_facts_before_scope(c uuid, s text, f date, t date)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$BEGIN
 PERFORM erp_reports_private.authorize_source(c,s);
 IF s IN('sales','sales-lines','sales-payments','purchase-documents','purchase-lines','purchase-payments','journal','accounts','cash-flow','customer-balances','supplier-balances','expenses','receipts') THEN RETURN QUERY SELECT * FROM erp_reports_private.financial_facts(c,s,f,t);
 ELSIF s IN('customers','suppliers','customer-credits','credit-charges','credit-usages','memberships','membership-renewals','customer-aging','supplier-aging') THEN RETURN QUERY SELECT * FROM erp_reports_private.customer_facts(c,s,f,t);
 ELSIF s IN('employees','employee-documents','employee-compliance','attendance','leave-balance','shifts','contracts','payslips','loans') THEN RETURN QUERY SELECT * FROM erp_reports_private.employee_facts(c,s,f,t);
 ELSIF s IN('stock','stock-movements','stock-aging','stock-turnover','stock-requests','manufacturing','assets') THEN RETURN QUERY SELECT * FROM erp_reports_private.inventory_facts(c,s,f,t);
 ELSE RETURN QUERY SELECT * FROM erp_reports_private.operational_facts(c,s,f,t);END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.row_allowed(c uuid, b uuid, j jsonb, k text DEFAULT ''::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE key text;v jsonb;rid uuid;kind text;scoped uuid;BEGIN
 IF b IS NULL THEN RETURN true;END IF;IF jsonb_typeof(j)<>'object' THEN RETURN true;END IF;
 IF coalesce(j->>'branchId',j->>'branch_id','')~'^[0-9a-f-]{36}$' AND coalesce(j->>'branchId',j->>'branch_id')::uuid<>b THEN RETURN false;END IF;
 IF coalesce(j->>'id','')~'^[0-9a-f-]{36}$' THEN
  rid:=(j->>'id')::uuid;
  IF k<>'' AND NOT erp_branch_private.allowed_resource(c,b,k,rid) THEN RETURN false;END IF;
  IF EXISTS(SELECT 1 FROM public.erp_branch_resources x WHERE x.cafe_id=c AND x.record_id=rid AND NOT erp_branch_private.allowed_resource(c,b,x.kind,rid)) THEN RETURN false;END IF;
  IF EXISTS(SELECT 1 FROM public.erp_branch_records WHERE cafe_id=c AND record_id=rid AND branch_id<>b) OR EXISTS(SELECT 1 FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=rid AND branch_id<>b) THEN RETURN false;END IF;
 END IF;
 FOR key,v IN SELECT * FROM jsonb_each(j) LOOP
  IF jsonb_typeof(v)='string' AND(v#>>'{}')~'^[0-9a-f-]{36}$' THEN
   rid:=(v#>>'{}')::uuid;kind:=CASE WHEN key IN('customerId','customer_id') THEN 'customer' WHEN key IN('supplierId','supplier_id') THEN 'supplier' WHEN key IN('itemId','item_id','productId','product_id','inventory_item_id','bundleItemId') THEN 'item' WHEN key IN('accountId','account_id','cashAccountId','counterAccountId','adjustmentAccountId','defaultAdjustmentAccountId') THEN 'account' WHEN key IN('costCenterId','cost_center_id','centerId') THEN 'cost_center' WHEN key IN('unitTemplateId','unit_template_id') THEN 'unit_template' ELSE '' END;
   IF key IN('partyId','party_id') THEN SELECT p.kind INTO kind FROM public.bf_parties p WHERE p.cafe_id=c AND p.id=rid;END IF;
   IF coalesce(kind,'')<>'' AND NOT erp_branch_private.allowed_resource(c,b,kind,rid) THEN RETURN false;END IF;
   IF EXISTS(SELECT 1 FROM public.erp_branch_resources x WHERE x.cafe_id=c AND x.record_id=rid AND NOT erp_branch_private.allowed_resource(c,b,x.kind,rid)) THEN RETURN false;END IF;
   IF EXISTS(SELECT 1 FROM public.erp_branch_records WHERE cafe_id=c AND record_id=rid AND branch_id<>b) THEN RETURN false;END IF;
   IF key IN('documentId','document_id','invoiceId','financeId','finance_document_id','source_document_id','reference_id') AND EXISTS(SELECT 1 FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=rid AND branch_id<>b) THEN RETURN false;END IF;
  ELSIF jsonb_typeof(v)='object' THEN IF NOT erp_branch_private.row_allowed(c,b,v,'') THEN RETURN false;END IF;
  END IF;
 END LOOP;RETURN true;
END $function$

CREATE OR REPLACE FUNCTION erp_cheque_private.act(c uuid, a text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE q public.erp_cheques;e public.erp_cheque_events;last_event public.erp_cheque_events;i uuid:=(p->>'id')::uuid;d date:=(p->>'date')::date;doc uuid;eid uuid;next text;holding uuid;deposit uuid;fee_account uuid;fee numeric:=coalesce((p->>'fee')::numeric,0);cfg jsonb:=erp_cheque_private.settings(c);BEGIN
 PERFORM erp_cheque_private.authorize(c,'approve');SELECT * INTO q FROM public.erp_cheques WHERE cafe_id=c AND id=i FOR UPDATE;IF q.id IS NULL THEN RAISE EXCEPTION 'الشيك غير متاح' USING ERRCODE='42501';END IF;IF q.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'حالة الشيك تغيرت' USING ERRCODE='40001';END IF;
 PERFORM erp_cheque_private.period(c,d);IF d<q.issued_on OR d<coalesce((SELECT max(effective_on)FROM public.erp_cheque_events WHERE cafe_id=c AND cheque_id=i),q.issued_on) OR length(coalesce(p->>'note',''))>5000 THEN RAISE EXCEPTION 'تاريخ العملية يسبق حركة سابقة';END IF;
 IF a IN('deliver','receive') THEN
  IF q.status<>'issued' OR(a='deliver')<>(q.kind='payable') THEN RAISE EXCEPTION 'هذه الحالة لا تسمح بالتسليم أو الاستلام';END IF;
  PERFORM erp_cheque_private.account(c,q.counter_account_id,CASE q.kind WHEN 'payable' THEN ARRAY['payable','expense','equity','receivable'] ELSE ARRAY['receivable','revenue','equity','payable'] END);
  holding:=erp_cheque_private.config_account(c,CASE q.kind WHEN 'payable' THEN 'payableAccountId' ELSE 'receivableAccountId' END);IF holding=q.counter_account_id THEN RAISE EXCEPTION 'حساب الطرف يختلف عن حساب أوراق الشيكات';END IF;
  doc:=erp_cheque_private.document(c,i,d,p->>'note');IF q.kind='payable' THEN PERFORM brand_finance_private.line(c,doc,q.counter_account_id,q.base_amount,0,q.party_id);PERFORM brand_finance_private.line(c,doc,holding,0,q.base_amount,q.party_id);next:='delivered';ELSE PERFORM brand_finance_private.line(c,doc,holding,q.base_amount,0,q.party_id);PERFORM brand_finance_private.line(c,doc,q.counter_account_id,0,q.base_amount,q.party_id);next:='received';END IF;
  UPDATE public.erp_cheques SET holding_account_id=holding WHERE id=i;
 ELSIF a='deposit' THEN
  IF q.kind<>'receivable' OR q.status<>'received' THEN RAISE EXCEPTION 'يمكن إيداع الشيك المستلم فقط';END IF;
  deposit:=coalesce((p->>'depositAccountId')::uuid,erp_cheque_private.config_account(c,'depositAccountId'));PERFORM erp_cheque_private.account(c,deposit,ARRAY['receivable']);IF deposit IN(q.holding_account_id,q.counter_account_id) THEN RAISE EXCEPTION 'اختر حسابًا مستقلًا للشيكات تحت التحصيل';END IF;
  PERFORM erp_cheque_private.account(c,q.bank_id,ARRAY['bank']);doc:=erp_cheque_private.document(c,i,d,p->>'note');PERFORM brand_finance_private.line(c,doc,deposit,q.base_amount,0,q.party_id);PERFORM brand_finance_private.line(c,doc,q.holding_account_id,0,q.base_amount,q.party_id);next:='deposited';UPDATE public.erp_cheques SET deposit_account_id=deposit WHERE id=i;
 ELSIF a='collect' THEN
  IF q.status NOT IN('delivered','received','deposited') THEN RAISE EXCEPTION 'الشيك غير متاح للتحصيل';END IF;
  IF q.due_on>d AND NOT(cfg->>'allowEarlyCollection')::boolean THEN RAISE EXCEPTION 'لم يصل تاريخ استحقاق الشيك';END IF;
  IF jsonb_typeof(p->'fee') IS DISTINCT FROM 'number' OR fee<0 OR fee<>round(fee,2) OR fee>=q.base_amount OR q.kind='payable' AND fee<>0 THEN RAISE EXCEPTION 'راجع رسوم التحصيل بالريال';END IF;
  PERFORM erp_cheque_private.account(c,q.bank_id,ARRAY['bank']);IF q.kind='payable' AND coalesce((SELECT sum(debit-credit)FROM public.bf_journal WHERE cafe_id=c AND account_id=q.bank_id),0)<q.base_amount THEN RAISE EXCEPTION 'رصيد البنك لا يكفي لصرف الشيك';END IF;
  doc:=erp_cheque_private.document(c,i,d,p->>'note');holding:=CASE q.status WHEN 'deposited' THEN q.deposit_account_id ELSE q.holding_account_id END;
  IF q.kind='payable' THEN PERFORM brand_finance_private.line(c,doc,holding,q.base_amount,0,q.party_id);PERFORM brand_finance_private.line(c,doc,q.bank_id,0,q.base_amount);
  ELSE PERFORM brand_finance_private.line(c,doc,q.bank_id,q.base_amount-fee,0);PERFORM brand_finance_private.line(c,doc,holding,0,q.base_amount,q.party_id);IF fee>0 THEN fee_account:=coalesce((p->>'feeAccountId')::uuid,erp_cheque_private.config_account(c,'feeAccountId'));PERFORM erp_cheque_private.account(c,fee_account,ARRAY['expense']);PERFORM brand_finance_private.line(c,doc,fee_account,fee,0);END IF;END IF;next:='collected';
 ELSIF a IN('undo_collect','undo_deposit','undo_deliver') THEN
  IF(a='undo_collect' AND q.status<>'collected')OR(a='undo_deposit' AND q.status<>'deposited')OR(a='undo_deliver' AND q.status<>'delivered')THEN RAISE EXCEPTION 'لا تتوفر هذه العملية في حالة الشيك الحالية';END IF;
  SELECT * INTO e FROM public.erp_cheque_events x WHERE x.cafe_id=c AND x.cheque_id=i AND x.action=CASE a WHEN 'undo_collect' THEN 'collect' WHEN 'undo_deposit' THEN 'deposit' ELSE 'deliver' END AND NOT EXISTS(SELECT 1 FROM public.erp_cheque_events r WHERE r.cafe_id=c AND r.reversal_of=x.id)ORDER BY x.created_at DESC LIMIT 1;
  IF a='undo_collect' AND q.kind='receivable' AND coalesce((SELECT sum(debit-credit)FROM public.bf_journal WHERE cafe_id=c AND account_id=q.bank_id),0)<q.base_amount-coalesce((e.payload->>'fee')::numeric,0) THEN RAISE EXCEPTION 'رصيد البنك لا يكفي للتراجع عن التحصيل';END IF;
  doc:=erp_cheque_private.reversal(c,e.id,d,p->>'note');next:=e.from_status;INSERT INTO public.erp_cheque_events(cafe_id,cheque_id,action,from_status,to_status,effective_on,document_id,reversal_of,payload,actor)VALUES(c,i,a,q.status,next,d,doc,e.id,p-'revision',auth.uid())RETURNING id INTO eid;
 ELSIF a IN('reject','cancel') THEN
  IF q.status IN('collected','rejected','cancelled') OR(a='cancel' AND q.status<>'issued') THEN RAISE EXCEPTION 'تراجع عن التحصيل أو التسليم قبل الإلغاء';END IF;
  next:=CASE a WHEN 'reject' THEN 'rejected' ELSE 'cancelled' END;
  FOR e IN SELECT * FROM public.erp_cheque_events x WHERE x.cafe_id=c AND x.cheque_id=i AND x.action IN('receive','deliver','deposit') AND NOT EXISTS(SELECT 1 FROM public.erp_cheque_events r WHERE r.cafe_id=c AND r.reversal_of=x.id)ORDER BY x.created_at DESC LOOP doc:=erp_cheque_private.reversal(c,e.id,d,p->>'note');INSERT INTO public.erp_cheque_events(cafe_id,cheque_id,action,from_status,to_status,effective_on,document_id,reversal_of,payload,actor)VALUES(c,i,a,q.status,next,d,doc,e.id,p-'revision',auth.uid())RETURNING id INTO eid;END LOOP;
 ELSE RAISE EXCEPTION 'إجراء الشيك غير معروف';END IF;
 IF eid IS NULL THEN INSERT INTO public.erp_cheque_events(cafe_id,cheque_id,action,from_status,to_status,effective_on,document_id,payload,actor)VALUES(c,i,a,q.status,next,d,doc,p-'revision',auth.uid())RETURNING id INTO eid;END IF;
 UPDATE public.erp_cheques SET status=next,revision=revision+1 WHERE id=i;
 IF doc IS NOT NULL AND EXISTS(SELECT 1 FROM public.bf_journal WHERE document_id=doc HAVING abs(sum(debit-credit))>.001) THEN RAISE EXCEPTION 'قيد الشيك غير متوازن';END IF;RETURN jsonb_build_object('id',i,'eventId',eid,'documentId',doc,'status',next);
END$function$

CREATE OR REPLACE FUNCTION erp_cheque_private.save(c uuid, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE old public.erp_cheques;b public.erp_cheque_books;i uuid:=(p->>'id')::uuid;amount numeric;rate numeric;d date;due date;counter uuid:=(p->>'counterAccountId')::uuid;party uuid:=(p->>'partyId')::uuid;BEGIN
 IF EXISTS(SELECT 1 FROM public.erp_cheques WHERE id=i AND cafe_id<>c)THEN RAISE EXCEPTION 'الشيك غير متاح' USING ERRCODE='42501';END IF;
 SELECT * INTO old FROM public.erp_cheques WHERE cafe_id=c AND id=i FOR UPDATE;PERFORM erp_cheque_private.authorize(c,CASE WHEN old.id IS NULL THEN 'create' ELSE 'update' END);IF coalesce(old.revision,0) IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'الشيك تغير أعد تحميله' USING ERRCODE='40001';END IF;
 IF i IS NULL OR coalesce(p->>'kind','') NOT IN('payable','receivable') OR jsonb_typeof(p->'amount') IS DISTINCT FROM 'number' OR jsonb_typeof(p->'exchangeRate') IS DISTINCT FROM 'number' OR coalesce(p->>'currency','')!~'^[A-Z]{3}$' OR length(btrim(coalesce(p->>'number',''))) NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(p->>'name',''))) NOT BETWEEN 1 AND 200 OR length(coalesce(p->>'note',''))>5000 OR length(coalesce(p->>'issuerBank',''))>200 OR length(coalesce(p->>'endorsementName',''))>200 OR jsonb_typeof(p->'endorsed') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع بيانات الشيك';END IF;
 amount:=(p->>'amount')::numeric;rate:=(p->>'exchangeRate')::numeric;d:=(p->>'issuedOn')::date;due:=(p->>'dueOn')::date;IF amount<=0 OR amount>1e9 OR amount<>round(amount,2) OR rate<=0 OR rate>1e6 OR round(amount*rate,2)>1e9 OR round(amount*rate,2)<=0 OR(p->>'currency'='SAR' AND rate<>1) OR d IS NULL OR NOT isfinite(d) OR due IS NOT NULL AND NOT isfinite(due) OR d>(now() AT TIME ZONE 'Asia/Riyadh')::date OR due<d THEN RAISE EXCEPTION 'راجع قيمة الشيك والعملات والتواريخ';END IF;
 IF(p->>'endorsed')::boolean AND length(btrim(coalesce(p->>'endorsementName','')))=0 THEN RAISE EXCEPTION 'أدخل اسم المظهر إليه';END IF;
 IF old.id IS NOT NULL AND old.kind IS DISTINCT FROM p->>'kind' THEN RAISE EXCEPTION 'لا يمكن تغيير نوع الشيك';END IF;
 IF old.id IS NOT NULL AND(old.status<>'issued' OR EXISTS(SELECT 1 FROM public.erp_cheque_events WHERE cafe_id=c AND cheque_id=i AND document_id IS NOT NULL)) THEN
  IF (old.payload-ARRAY['revision','name','dueOn','note','endorsed','endorsementName']) IS DISTINCT FROM(p-ARRAY['revision','name','dueOn','note','endorsed','endorsementName']) THEN RAISE EXCEPTION 'القيم المالية مثبتة بعد التسجيل وتعدل بالتراجع ثم إنشاء شيك بديل';END IF;
 ELSE
  PERFORM erp_cheque_private.account(c,(p->>'bankId')::uuid,ARRAY['bank']);PERFORM erp_cheque_private.account(c,counter,CASE p->>'kind' WHEN 'payable' THEN ARRAY['payable','expense','equity','receivable'] ELSE ARRAY['receivable','revenue','equity','payable'] END);
  IF EXISTS(SELECT 1 FROM public.bf_accounts WHERE id=counter AND kind IN('payable','receivable')) AND party IS NULL THEN RAISE EXCEPTION 'حدد العميل أو المورد المرتبط بحساب الذمم';END IF;
  IF party IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=party AND active) THEN RAISE EXCEPTION 'الطرف غير متاح';END IF;
  IF p->>'kind'='payable' THEN SELECT * INTO b FROM public.erp_cheque_books WHERE cafe_id=c AND id=(p->>'bookId')::uuid FOR UPDATE;IF b.id IS NULL OR NOT b.active OR b.bank_id IS DISTINCT FROM(p->>'bankId')::uuid OR b.currency<>p->>'currency' OR(p->>'number')!~'^[0-9]{1,12}$' THEN RAISE EXCEPTION 'حدد دفترًا نشطًا ورقم شيك صالحًا';END IF;IF(p->>'number')::bigint NOT BETWEEN b.first_serial AND b.last_serial OR(p->>'number')<>((p->>'number')::bigint)::text THEN RAISE EXCEPTION 'رقم الشيك خارج الدفتر';END IF;
  ELSIF nullif(p->>'bookId','') IS NOT NULL THEN RAISE EXCEPTION 'الشيك المستلم لا يرتبط بدفتر صادر';END IF;
 END IF;
 INSERT INTO public.erp_cheques(cafe_id,id,kind,status,number,book_id,bank_id,counter_account_id,party_id,amount,base_amount,currency,exchange_rate,issued_on,due_on,name,payload,created_by)VALUES(c,i,p->>'kind','issued',btrim(p->>'number'),(p->>'bookId')::uuid,(p->>'bankId')::uuid,counter,party,amount,round(amount*rate,2),p->>'currency',rate,d,due,btrim(p->>'name'),p-'revision',auth.uid())ON CONFLICT(id)DO UPDATE SET revision=erp_cheques.revision+1,number=excluded.number,book_id=excluded.book_id,bank_id=excluded.bank_id,counter_account_id=excluded.counter_account_id,party_id=excluded.party_id,amount=excluded.amount,base_amount=excluded.base_amount,currency=excluded.currency,exchange_rate=excluded.exchange_rate,issued_on=excluded.issued_on,due_on=excluded.due_on,name=excluded.name,payload=excluded.payload;
 INSERT INTO public.erp_cheque_events(cafe_id,cheque_id,action,from_status,to_status,effective_on,payload,actor)VALUES(c,i,CASE WHEN old.id IS NULL THEN 'create' ELSE 'edit' END,old.status,coalesce(old.status,'issued'),d,jsonb_build_object('name',p->>'name','dueOn',due),auth.uid());RETURN i;
END$function$

CREATE OR REPLACE FUNCTION erp_cheque_private.save_book(c uuid, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE old public.erp_cheque_books;i uuid:=(p->>'id')::uuid;f bigint;l bigint;BEGIN
 IF EXISTS(SELECT 1 FROM public.erp_cheque_books WHERE id=i AND cafe_id<>c)THEN RAISE EXCEPTION 'الدفتر غير متاح' USING ERRCODE='42501';END IF;
 SELECT * INTO old FROM public.erp_cheque_books WHERE cafe_id=c AND id=i FOR UPDATE;PERFORM erp_cheque_private.authorize(c,CASE WHEN old.id IS NULL THEN 'create' ELSE 'update' END);
 IF coalesce(old.revision,0) IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'دفتر الشيكات تغير' USING ERRCODE='40001';END IF;
 IF i IS NULL OR jsonb_typeof(p->'firstSerial') IS DISTINCT FROM 'number' OR jsonb_typeof(p->'lastSerial') IS DISTINCT FROM 'number' OR jsonb_typeof(p->'active') IS DISTINCT FROM 'boolean' OR coalesce(p->>'currency','')!~'^[A-Z]{3}$' OR length(btrim(coalesce(p->>'number',''))) NOT BETWEEN 1 AND 100 OR length(coalesce(p->>'note',''))>5000 THEN RAISE EXCEPTION 'راجع بيانات دفتر الشيكات';END IF;
 IF trunc((p->>'firstSerial')::numeric)<>(p->>'firstSerial')::numeric OR trunc((p->>'lastSerial')::numeric)<>(p->>'lastSerial')::numeric THEN RAISE EXCEPTION 'أرقام الشيكات يجب أن تكون صحيحة';END IF;f:=(p->>'firstSerial')::bigint;l:=(p->>'lastSerial')::bigint;IF f<1 OR l<f OR l>999999999999 OR l-f>1000000 THEN RAISE EXCEPTION 'نطاق أرقام الشيكات غير صالح';END IF;PERFORM erp_cheque_private.account(c,(p->>'bankId')::uuid,ARRAY['bank']);
 IF EXISTS(SELECT 1 FROM public.erp_cheque_books WHERE cafe_id=c AND id<>i AND bank_id=(p->>'bankId')::uuid AND first_serial<=l AND last_serial>=f) THEN RAISE EXCEPTION 'نطاق الأرقام يتداخل مع دفتر آخر';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_cheques WHERE cafe_id=c AND book_id=i) AND(old.bank_id IS DISTINCT FROM(p->>'bankId')::uuid OR old.currency IS DISTINCT FROM p->>'currency' OR EXISTS(SELECT 1 FROM public.erp_cheques WHERE cafe_id=c AND book_id=i AND number::bigint NOT BETWEEN f AND l)) THEN RAISE EXCEPTION 'لا يمكن تغيير البنك أو العملة أو استبعاد أرقام مستخدمة';END IF;
 INSERT INTO public.erp_cheque_books(cafe_id,id,bank_id,number,first_serial,last_serial,currency,active,note)VALUES(c,i,(p->>'bankId')::uuid,btrim(p->>'number'),f,l,p->>'currency',(p->>'active')::boolean,coalesce(p->>'note',''))ON CONFLICT(id)DO UPDATE SET revision=erp_cheque_books.revision+1,bank_id=excluded.bank_id,number=excluded.number,first_serial=excluded.first_serial,last_serial=excluded.last_serial,currency=excluded.currency,active=excluded.active,note=excluded.note;RETURN i;
END$function$

CREATE OR REPLACE FUNCTION erp_commission_private.authorize(p_cafe uuid, p_write boolean DEFAULT false, p_approve boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text;
BEGIN
 r:=brand_finance_private.role_for(p_cafe);
 IF auth.uid() IS NULL OR coalesce(r,'') NOT IN('owner','manager','accountant','auditor') OR (p_write AND r='auditor') OR (p_approve AND r NOT IN('owner','accountant')) THEN RAISE EXCEPTION 'لا تملك صلاحية إدارة عمولات المبيعات' USING ERRCODE='42501';END IF;
 RETURN r;
END $function$

CREATE OR REPLACE FUNCTION erp_commission_private.calculate(p_rule jsonb, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE line jsonb;item jsonb;achievement numeric:=0;commission numeric:=0;amount numeric;contribution numeric;percentage numeric;lower_t jsonb;upper_t jsonb;tier_value numeric:=0;included jsonb:='[]';
BEGIN
 FOR line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
  SELECT x.value INTO item FROM jsonb_array_elements(p_rule->'items') WITH ORDINALITY x(value,position) WHERE x.value->>'kind'='all' OR (x.value->>'kind'='product' AND x.value->'targets' ? (line->>'productId')) OR (x.value->>'kind'='category' AND x.value->'targets' ? (line->>'category')) ORDER BY CASE x.value->>'kind' WHEN 'product' THEN 0 WHEN 'category' THEN 1 ELSE 2 END,x.position LIMIT 1;
  IF item IS NULL THEN CONTINUE;END IF;
  contribution:=CASE p_rule->>'targetType' WHEN 'volume' THEN (line->>'quantity')::numeric ELSE (line->>'net')::numeric END;
  IF p_rule->>'type'='tiers' THEN contribution:=contribution*(item->>'amount')::numeric/100;END IF;
  achievement:=achievement+contribution;
  amount:=CASE WHEN p_rule->>'type'='flat' THEN round(CASE item->>'amountType' WHEN 'percentage' THEN (line->>'net')::numeric*(item->>'amount')::numeric/100 ELSE (item->>'amount')::numeric END,2) ELSE 0 END;
  commission:=commission+amount;included:=included||jsonb_build_array(line||jsonb_build_object('contribution',contribution,'commission',amount,'itemId',item->>'id'));
 END LOOP;
 percentage:=achievement/(p_rule->>'targetAmount')::numeric*100;
 IF p_rule->>'type'='tiers' THEN
  SELECT value INTO lower_t FROM jsonb_array_elements(p_rule->'tiers') t WHERE (t->>'target')::numeric<=percentage ORDER BY (t->>'target')::numeric DESC LIMIT 1;
  SELECT value INTO upper_t FROM jsonb_array_elements(p_rule->'tiers') t WHERE (t->>'target')::numeric>percentage ORDER BY (t->>'target')::numeric LIMIT 1;
  IF p_rule->>'interpolation'='steps' OR upper_t IS NULL THEN tier_value:=coalesce((lower_t->>'value')::numeric,0);
  ELSE lower_t:=coalesce(lower_t,'{"target":0,"value":0}');tier_value:=(lower_t->>'value')::numeric+((upper_t->>'value')::numeric-(lower_t->>'value')::numeric)*(percentage-(lower_t->>'target')::numeric)/((upper_t->>'target')::numeric-(lower_t->>'target')::numeric);END IF;
  commission:=CASE p_rule->>'tierType' WHEN 'percentage' THEN achievement*tier_value/100 ELSE tier_value END;
 END IF;
 RETURN jsonb_build_object('achievement',round(achievement,3),'percentage',percentage,'total',round(commission,2),'lines',included);
END $function$

CREATE OR REPLACE FUNCTION erp_commission_private.fill_period(p_cafe uuid, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE period public.erp_commission_periods;rule public.erp_commission_rules;all_lines jsonb;matched jsonb;calc jsonb;employee uuid;employee_name text;employee_role text;dep uuid;designation uuid;
BEGIN
 SELECT * INTO STRICT period FROM public.erp_commission_periods WHERE cafe_id=p_cafe AND id=p_id FOR UPDATE;
 IF period.status<>'open' THEN RAISE EXCEPTION 'الفترة المغلقة لا تقبل إعادة الاحتساب' USING ERRCODE='22023';END IF;
 all_lines:=erp_commission_private.sales(p_cafe,period.date_from,period.date_to);
 IF jsonb_array_length(all_lines)>10000 THEN RAISE EXCEPTION 'الفترة تحتوي معاملات كثيرة اختر فترة أقصر' USING ERRCODE='22023';END IF;
 DELETE FROM public.erp_commission_rows WHERE cafe_id=p_cafe AND period_id=p_id;
 FOR rule IN SELECT * FROM public.erp_commission_rules WHERE cafe_id=p_cafe AND active AND (jsonb_array_length(period.criteria->'ruleIds')=0 OR period.criteria->'ruleIds' ? id::text) LOOP
  FOR employee IN SELECT DISTINCT (l->>'employeeId')::uuid FROM jsonb_array_elements(all_lines) l LOOP
   IF NOT erp_org_private.staff(p_cafe,employee) OR (jsonb_array_length(period.criteria->'staffIds')>0 AND NOT(period.criteria->'staffIds' ? employee::text)) THEN CONTINUE;END IF;
   SELECT name,role INTO employee_name,employee_role FROM public.bf_staff WHERE cafe_id=p_cafe AND user_id=employee;
   IF employee_name IS NULL THEN SELECT name,'owner' INTO employee_name,employee_role FROM public.cafes WHERE id=p_cafe AND owner_user_id=employee;END IF;
   SELECT department_id,designation_id INTO dep,designation FROM public.erp_org_assignments WHERE cafe_id=p_cafe AND user_id=employee;
   IF (period.criteria->>'departmentId' IS NOT NULL AND period.criteria->>'departmentId' IS DISTINCT FROM dep::text) OR (period.criteria->>'designationId' IS NOT NULL AND period.criteria->>'designationId' IS DISTINCT FROM designation::text) THEN CONTINUE;END IF;
   SELECT coalesce(jsonb_agg(l),'[]') INTO matched FROM jsonb_array_elements(all_lines) l WHERE l->>'employeeId'=employee::text AND (period.criteria->>'branchId' IS NULL OR l->>'branchId'=period.criteria->>'branchId') AND (rule.payload->'staffIds' ? employee::text OR rule.payload->'roles' ? employee_role OR rule.payload->'departmentIds' ? dep::text OR rule.payload->'branchIds' ? (l->>'branchId'));
   calc:=erp_commission_private.calculate(rule.payload,matched);
   IF jsonb_array_length(calc->'lines')=0 THEN CONTINUE;END IF;
   IF EXISTS(SELECT 1 FROM public.erp_commission_rows x JOIN public.erp_commission_periods p ON p.cafe_id=x.cafe_id AND p.id=x.period_id WHERE x.cafe_id=p_cafe AND x.rule_id=rule.id AND x.employee_id=employee AND p.id<>p_id AND p.status<>'rejected' AND p.date_from<=period.date_to AND p.date_to>=period.date_from) THEN RAISE EXCEPTION 'توجد فترة عمولة متداخلة للموظف والقاعدة نفسها' USING ERRCODE='22023';END IF;
   INSERT INTO public.erp_commission_rows(cafe_id,period_id,employee_id,employee_name,rule_id,rule_name,rule_snapshot,target,achievement,total,lines) VALUES(p_cafe,p_id,employee,employee_name,rule.id,rule.name,rule.payload,(rule.payload->>'targetAmount')::numeric,(calc->>'achievement')::numeric,(calc->>'total')::numeric,calc->'lines');
  END LOOP;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM public.erp_commission_rows WHERE cafe_id=p_cafe AND period_id=p_id) THEN RAISE EXCEPTION 'لا توجد مبيعات مدفوعة مؤهلة للموظفين والقواعد المختارة' USING ERRCODE='22023';END IF;
 UPDATE public.erp_commission_periods SET total=(SELECT sum(total) FROM public.erp_commission_rows WHERE cafe_id=p_cafe AND period_id=p_id) WHERE cafe_id=p_cafe AND id=p_id;
END $function$

CREATE OR REPLACE FUNCTION erp_commission_private.validate_rule(p_cafe uuid, p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE item jsonb;entry jsonb;target text;key text;value text;
BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR octet_length(p::text)>100000 OR length(btrim(coalesce(p->>'name',''))) NOT BETWEEN 1 AND 150 OR length(coalesce(p->>'description',''))>10000 OR coalesce(p->>'type','') NOT IN('flat','tiers') OR coalesce(p->>'targetType','') NOT IN('revenue','volume') OR coalesce(p->>'tierType','') NOT IN('fixed','percentage') OR coalesce(p->>'interpolation','') NOT IN('linear','steps') OR jsonb_typeof(p->'targetAmount') IS DISTINCT FROM 'number' OR (p->>'targetAmount')::numeric NOT BETWEEN 0.000001 AND 1000000000 OR jsonb_typeof(p->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع بيانات قاعدة العمولة' USING ERRCODE='22023';END IF;
 IF jsonb_typeof(p->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'items') NOT BETWEEN 1 AND 100 OR jsonb_typeof(p->'tiers') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'tiers')>50 OR (p->>'type'='tiers' AND jsonb_array_length(p->'tiers')=0) THEN RAISE EXCEPTION 'أضف البنود ومستويات العمولة المطلوبة' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'items') x GROUP BY x->>'id' HAVING count(*)>1) OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'tiers') x GROUP BY (x->>'target')::numeric HAVING count(*)>1) THEN RAISE EXCEPTION 'البنود أو المستويات مكررة' USING ERRCODE='22023';END IF;
 FOR item IN SELECT x FROM jsonb_array_elements(p->'items') x LOOP
  IF coalesce(item->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'معرف بند العمولة غير صالح' USING ERRCODE='22023';END IF;
  IF coalesce(item->>'kind','') NOT IN('all','product','category') OR coalesce(item->>'amountType','') NOT IN('percentage','fixed') OR jsonb_typeof(item->'amount') IS DISTINCT FROM 'number' OR (item->>'amount')::numeric NOT BETWEEN 0 AND (CASE WHEN item->>'amountType'='percentage' OR p->>'type'='tiers' THEN 100 ELSE 1000000000 END) OR jsonb_typeof(item->'targets') IS DISTINCT FROM 'array' OR jsonb_array_length(item->'targets')>200 OR (item->>'kind'<>'all' AND jsonb_array_length(item->'targets')=0) THEN RAISE EXCEPTION 'راجع بنود قاعدة العمولة' USING ERRCODE='22023';END IF;
  FOR target IN SELECT jsonb_array_elements_text(item->'targets') LOOP
   IF (item->>'kind'='product' AND NOT EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id=p_cafe AND id::text=target AND deleted_at IS NULL)) OR (item->>'kind'='category' AND NOT EXISTS(SELECT 1 FROM public.menu_categories WHERE cafe_id=p_cafe AND name=target)) THEN RAISE EXCEPTION 'البند لا ينتمي إلى هذه العلامة' USING ERRCODE='42501';END IF;
  END LOOP;
 END LOOP;
 FOR entry IN SELECT x FROM jsonb_array_elements(p->'tiers') x LOOP
  IF jsonb_typeof(entry->'target') IS DISTINCT FROM 'number' OR jsonb_typeof(entry->'value') IS DISTINCT FROM 'number' OR (entry->>'target')::numeric NOT BETWEEN 0 AND 1000000000 OR (entry->>'value')::numeric NOT BETWEEN 0 AND (CASE p->>'tierType' WHEN 'percentage' THEN 100 ELSE 1000000000 END) THEN RAISE EXCEPTION 'قيم مستوى العمولة غير صالحة' USING ERRCODE='22023';END IF;
 END LOOP;
 FOREACH key IN ARRAY ARRAY['staffIds','roles','departmentIds','branchIds'] LOOP
  IF jsonb_typeof(p->key) IS DISTINCT FROM 'array' OR jsonb_array_length(p->key)>500 THEN RAISE EXCEPTION 'تعيين القاعدة غير صالح' USING ERRCODE='22023';END IF;
  FOR value IN SELECT jsonb_array_elements_text(p->key) LOOP
   IF (key='staffIds' AND NOT erp_org_private.staff(p_cafe,value::uuid)) OR (key='roles' AND value NOT IN('manager','cashier','accountant','warehouse','auditor')) OR (key='departmentIds' AND NOT EXISTS(SELECT 1 FROM public.erp_org_units WHERE cafe_id=p_cafe AND id::text=value AND kind='department' AND active)) OR (key='branchIds' AND NOT EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=p_cafe AND id::text=value AND active AND deleted_at IS NULL)) THEN RAISE EXCEPTION 'أحد تعيينات القاعدة غير متاح' USING ERRCODE='22023';END IF;
  END LOOP;
 END LOOP;
 IF jsonb_array_length(p->'staffIds')+jsonb_array_length(p->'roles')+jsonb_array_length(p->'departmentIds')+jsonb_array_length(p->'branchIds')=0 THEN RAISE EXCEPTION 'اختر تعيينًا واحدًا على الأقل' USING ERRCODE='22023';END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_contract_form_private.assert_entry(c uuid, i uuid, a text)
 RETURNS erp_contracting_form_entries
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE e public.erp_contracting_form_entries;cfg jsonb;BEGIN
 PERFORM erp_contract_form_private.authorize(c,a);
 SELECT * INTO e FROM public.erp_contracting_form_entries WHERE cafe_id=c AND id=i FOR KEY SHARE;
 SELECT config INTO cfg FROM public.erp_contracting_forms WHERE cafe_id=c AND id=e.model_id;
 IF e.id IS NULL OR NOT erp_contract_form_private.project_visible(c,e.project_id) OR NOT erp_contract_form_private.allowed(c,cfg,'read') OR NOT erp_contract_form_private.allowed(c,cfg,a) THEN RAISE EXCEPTION 'السجل غير متاح' USING ERRCODE='42501';END IF;RETURN e;
END $function$

CREATE OR REPLACE FUNCTION erp_contract_form_private.authorize(c uuid, a text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE r text;BEGIN
 r:=brand_finance_private.role_for(c);
 IF auth.uid() IS NULL OR NOT public.brand_account_not_cancelled(c) OR r IS NULL OR r NOT IN('owner','manager','accountant','auditor') OR(a<>'read' AND r='auditor') OR(a='settings' AND r<>'owner') THEN RAISE EXCEPTION 'لا تملك صلاحية نماذج المقاولات' USING ERRCODE='42501';END IF;
 PERFORM erp_access_private.assert_allowed(c,'contracting',a);
END $function$

CREATE OR REPLACE FUNCTION erp_contract_form_private.fields(c uuid, j jsonb, a text)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE result text[];r jsonb;BEGIN
 SELECT coalesce(array_agg(f->>'id'),'{}') INTO result FROM jsonb_array_elements(j->'fields') f;
 IF brand_finance_private.role_for(c)='owner' THEN RETURN result;END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(j#>'{permissions,fieldRules}') LOOP
  IF erp_workflow_private.selector(c,r->'selector') THEN SELECT ARRAY(SELECT unnest(result) INTERSECT SELECT jsonb_array_elements_text(r->a)) INTO result;END IF;
 END LOOP;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_contract_form_private.validate_values(fields jsonb, vals jsonb, p_cafe uuid DEFAULT NULL::uuid, p_record uuid DEFAULT NULL::uuid, p_scope uuid DEFAULT NULL::uuid, depth integer DEFAULT 0, p_draft boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE f jsonb;v jsonb;t text;x jsonb;txt text;tbl text;col text;valid boolean;metric numeric;BEGIN
 IF coalesce(jsonb_typeof(vals),'')<>'object' OR octet_length(vals::text)>262144 OR depth>2 THEN RAISE EXCEPTION 'بيانات الحقول الإضافية غير صالحة';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP
  t:=f->>'type';IF t IN('static','separator') THEN CONTINUE;END IF;
  v:=coalesce(vals->(f->>'id'),f->'defaultValue');
  IF coalesce((f->>'required')::boolean,false) AND NOT p_draft AND (v IS NULL OR v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb OR (t='checkbox' AND v<>'true')) THEN RAISE EXCEPTION 'أكمل الحقل المطلوب: %',f->>'label';END IF;
  IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
  IF t='subform' THEN
   IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>100 OR jsonb_array_length(v)<coalesce((f->>'minimumRows')::integer,0) THEN RAISE EXCEPTION 'عدد صفوف النموذج غير صالح';END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM erp_contract_form_private.validate_values(f->'fields',x,p_cafe,p_record,p_scope,depth+1,p_draft);END LOOP;CONTINUE;
  END IF;
  IF t='location' THEN
   IF jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'latitude')<>'number' OR jsonb_typeof(v->'longitude')<>'number' OR abs((v->>'latitude')::numeric)>90 OR abs((v->>'longitude')::numeric)>180 THEN RAISE EXCEPTION 'إحداثيات الموقع غير صالحة';END IF;CONTINUE;
  END IF;
  IF (t IN('number','currency') AND jsonb_typeof(v)<>'number') OR (t='checkbox' AND jsonb_typeof(v)<>'boolean') OR (t IN('multiselect','multidynamic') AND jsonb_typeof(v)<>'array') OR (t NOT IN('number','currency','checkbox','multiselect','multidynamic') AND jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'نوع قيمة الحقل غير صالح';END IF;
  txt:=v#>>'{}';
  IF length(txt)>20000 THEN RAISE EXCEPTION 'قيمة الحقل طويلة';END IF;
  IF (t='select' AND NOT(f->'options' @> jsonb_build_array(v))) OR (t='multiselect' AND NOT(f->'options' @> v)) THEN RAISE EXCEPTION 'اختيارات الحقل غير صالحة';END IF;
  IF t='email' AND txt!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'البريد الإلكتروني غير صالح';END IF;
  IF t='url' AND txt!~'^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'الرابط غير صالح';END IF;
  IF t='time' AND txt!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'الوقت غير صالح';END IF;
  IF t='date' THEN IF txt!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'التاريخ غير صالح';END IF;PERFORM txt::date;END IF;
  IF t IN('number','currency','text','textarea','formatted') THEN
   metric:=CASE WHEN t IN('number','currency') THEN txt::numeric ELSE length(txt) END;
   IF metric<nullif(f->>'minimum','')::numeric OR metric>nullif(f->>'maximum','')::numeric THEN RAISE EXCEPTION 'قيمة الحقل خارج الحدود: %',f->>'label';END IF;
  END IF;
  IF t IN('dynamic','multidynamic') THEN
   tbl:=CASE f->>'entity' WHEN 'items' THEN 'bf_items' WHEN 'customers' THEN 'bf_parties' WHEN 'employees' THEN 'bf_staff' WHEN 'warehouses' THEN 'bf_warehouses' WHEN 'accounts' THEN 'bf_accounts' WHEN 'bom' THEN 'erp_mfg_boms' WHEN 'routings' THEN 'erp_mfg_routings' WHEN 'workstations' THEN 'erp_mfg_workstations' WHEN 'orders' THEN 'erp_mfg_orders' WHEN 'sources' THEN 'bf_documents' END;
   IF tbl IS NULL OR p_cafe IS NULL THEN RAISE EXCEPTION 'الكيان المرتبط غير صالح';END IF;col:=CASE WHEN tbl='bf_staff' THEN 'user_id' ELSE 'id' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN t='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND %I=$2)',tbl,col) INTO valid USING p_cafe,(x#>>'{}')::uuid;
    IF NOT valid THEN RAISE EXCEPTION 'القيمة المرتبطة غير موجودة في العلامة';END IF;
   END LOOP;
  END IF;
  IF t IN('file','image') THEN
   IF p_record IS NULL OR to_regclass('public.erp_files') IS NULL THEN RAISE EXCEPTION 'احفظ السجل وأضف المرفق أولًا';END IF;
   EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=$1 AND record_id=$2 AND id=$3 AND entity_type=$4 AND uploaded AND ($5<>''image'' OR mime IN(''image/jpeg'',''image/png'')))' INTO valid USING p_cafe,p_record,txt::uuid,'contracting_form_entry',t;
   IF NOT valid THEN RAISE EXCEPTION 'المرفق غير موجود في هذا السجل';END IF;
  END IF;
  IF coalesce((f->>'unique')::boolean,false) AND depth=0 THEN
   tbl:='erp_contracting_form_entries';
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id IS DISTINCT FROM $2 AND field_values->$3=$4 AND model_id=$5)',tbl) INTO valid USING p_cafe,p_record,f->>'id',v,p_scope;
   IF valid THEN RAISE EXCEPTION 'قيمة الحقل مستخدمة مسبقًا: %',f->>'label';END IF;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_contract_form_private.value_scope(c uuid, fields jsonb, vals jsonb, depth integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE f jsonb;v jsonb;x jsonb;k text;b uuid:=erp_branch_private.current_branch(c);BEGIN
 IF depth>2 OR jsonb_typeof(vals) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(vals) q(value) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fields) ff(value) WHERE ff.value->>'id'=q.value)) THEN RETURN false;END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(fields) LOOP
  v:=vals->(f->>'id');IF v IS NULL OR v='null' OR v='""' THEN CONTINUE;END IF;
  IF f->>'type'='subform' THEN
   IF jsonb_typeof(v)<>'array' THEN RETURN false;END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP IF NOT erp_contract_form_private.value_scope(c,f->'fields',x,depth+1) THEN RETURN false;END IF;END LOOP;
  ELSIF f->>'type' IN('dynamic','multidynamic') THEN
   k:=CASE f->>'entity' WHEN 'customers' THEN 'customer' WHEN 'items' THEN 'item' WHEN 'accounts' THEN 'account' ELSE '' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN f->>'type'='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    IF k<>'' AND NOT erp_branch_private.allowed_resource(c,b,k,(x#>>'{}')::uuid) THEN RETURN false;END IF;
    IF NOT erp_branch_private.row_allowed(c,b,jsonb_build_object('id',x),'') THEN RETURN false;END IF;
    IF f->>'entity'='employees' AND b IS NOT NULL AND EXISTS(SELECT 1 FROM public.erp_hr_employees h WHERE h.cafe_id=c AND h.user_id=(x#>>'{}')::uuid AND h.active AND h.branch_id IS NOT NULL AND h.branch_id<>b AND NOT EXISTS(SELECT 1 FROM public.erp_branch_members bm WHERE bm.cafe_id=c AND bm.employee_id=h.id AND bm.branch_id=b)) THEN RETURN false;END IF;
    IF f->>'entity'='warehouses' AND NOT EXISTS(SELECT 1 FROM public.bf_warehouses w WHERE w.cafe_id=c AND w.id=(x#>>'{}')::uuid AND erp_branch_private.row_allowed(c,b,to_jsonb(w),'warehouse')) THEN RETURN false;END IF;
   END LOOP;
  END IF;
 END LOOP;RETURN true;
END $function$

CREATE OR REPLACE FUNCTION erp_contracting_private.before_reverse(p_cafe_id uuid, p_action text DEFAULT 'read'::text, p_input jsonb DEFAULT '{}'::jsonb, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
<<erp_contracting>>
DECLARE role_name text; d public.erp_contracting_documents%ROWTYPE; src public.erp_contracting_documents%ROWTYPE; old public.erp_contracting_documents%ROWTYPE; line jsonb; resource jsonb; source_line public.erp_contracting_lines%ROWTYPE; result jsonb; previous jsonb; cmd jsonb; config jsonb; kind_name text; doc_id uuid; source_id uuid; project_id uuid; customer_id uuid; number_code text; next_number bigint; n integer:=0; q numeric; used numeric; amount numeric; cost_total numeric; sub numeric; tax_total numeric; ret numeric; rec numeric; note_text text; payload jsonb; draft_result jsonb; status_name text;
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'contracting',erp_access_private.action(p_action,p_input));
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_action='read' THEN
   SELECT settings||jsonb_build_object('revision',revision) INTO config FROM erp_branch_private.erp_contracting_settings WHERE cafe_id=p_cafe_id;
   RETURN jsonb_build_object('documents',coalesce((SELECT jsonb_agg(brand_finance_private.contracting_record(p_cafe_id,id) ORDER BY updated_at DESC) FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id),'[]'::jsonb),'settings',coalesce(config,'{}'::jsonb),'events',coalesce((SELECT jsonb_agg(to_jsonb(e)-'cafe_id'-'actor' ORDER BY at DESC) FROM erp_branch_private.erp_contracting_events e WHERE cafe_id=p_cafe_id),'[]'::jsonb),'links',coalesce((SELECT jsonb_agg(to_jsonb(l)-'cafe_id') FROM erp_branch_private.erp_contracting_links l WHERE cafe_id=p_cafe_id),'[]'::jsonb),'activities',coalesce((SELECT jsonb_agg(to_jsonb(a)-'cafe_id' ORDER BY starts_at) FROM erp_branch_private.erp_contracting_activities a WHERE cafe_id=p_cafe_id),'[]'::jsonb),'drafts',coalesce((SELECT jsonb_agg(to_jsonb(a)-'cafe_id') FROM erp_branch_private.erp_contracting_invoice_drafts a WHERE cafe_id=p_cafe_id AND NOT EXISTS(SELECT 1 FROM erp_branch_private.bf_company_invoices i WHERE i.cafe_id=a.cafe_id AND i.draft_id=a.draft_id)),'[]'::jsonb));
 END IF;
 IF role_name NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_request_id IS NULL OR p_input IS NULL OR jsonb_typeof(p_input)<>'object' OR octet_length(p_input::text)>700000 THEN RAISE EXCEPTION 'Invalid request' USING ERRCODE='22023';END IF;
 -- Same lock ordering as the invoice issuer and customer credit ledger
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,67131));
 cmd:=jsonb_build_object('action',p_action,'input',p_input);
 SELECT command,result INTO previous,result FROM erp_branch_private.erp_contracting_requests WHERE cafe_id=p_cafe_id AND id=p_request_id;
 IF FOUND THEN IF previous<>cmd THEN RAISE EXCEPTION 'Request changed' USING ERRCODE='40001';END IF;RETURN result;END IF;
 INSERT INTO public.erp_contracting_settings(cafe_id) VALUES(p_cafe_id) ON CONFLICT DO NOTHING;
 SELECT settings INTO config FROM erp_branch_private.erp_contracting_settings WHERE cafe_id=p_cafe_id;
 IF p_action='settings' THEN
  IF role_name<>'owner' THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  IF (SELECT revision FROM erp_branch_private.erp_contracting_settings WHERE cafe_id=p_cafe_id) IS DISTINCT FROM (p_input->>'revision')::integer THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  IF coalesce(p_input->>'price_mode','') NOT IN('average','purchase') OR coalesce(p_input->>'alert_mode','') NOT IN('days','percent') OR coalesce((p_input->>'alert_threshold')::numeric,-1) NOT BETWEEN 0 AND (CASE WHEN p_input->>'alert_mode'='percent' THEN 100 ELSE 365 END) OR jsonb_typeof(p_input->'statuses') IS DISTINCT FROM 'array' OR jsonb_typeof(p_input->'fields') IS DISTINCT FROM 'array' OR jsonb_typeof(p_input->'actions') IS DISTINCT FROM 'array' OR length(coalesce(p_input->>'print_footer',''))>3000 THEN RAISE EXCEPTION 'Invalid settings' USING ERRCODE='22023';END IF;
  FOREACH kind_name IN ARRAY ARRAY['statuses','fields','actions'] LOOP
   IF jsonb_array_length(p_input->kind_name)>50 OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(p_input->kind_name) x)<>jsonb_array_length(p_input->kind_name) THEN RAISE EXCEPTION 'راجع عناصر الإعدادات' USING ERRCODE='22023';END IF;
   FOR line IN SELECT value FROM jsonb_array_elements(p_input->kind_name) LOOP
    IF (line->>'id')::uuid IS NULL OR length(btrim(coalesce(line->>'name',''))) NOT BETWEEN 1 AND 80 OR jsonb_typeof(line->'active') IS DISTINCT FROM 'boolean' OR (kind_name='statuses' AND (coalesce(line->>'type','') NOT IN('open','closed') OR coalesce(line->>'color','')!~'^#[0-9a-fA-F]{6}$')) OR (kind_name='fields' AND (coalesce(line->>'type','') NOT IN('text','number','date','textarea') OR jsonb_typeof(line->'required') IS DISTINCT FROM 'boolean')) OR (kind_name='actions' AND length(coalesce(line->>'description',''))>500) THEN RAISE EXCEPTION 'راجع تفاصيل عناصر الإعدادات' USING ERRCODE='22023';END IF;
   END LOOP;
  END LOOP;
  FOREACH kind_name IN ARRAY ARRAY['bid','project','cost_sheet','quotation','contract','certificate','reverse_certificate','work_item'] LOOP IF coalesce((p_input#>>ARRAY['numbering',kind_name])::bigint,0) NOT BETWEEN 1 AND 999999999 THEN RAISE EXCEPTION 'Invalid numbering' USING ERRCODE='22023';END IF;END LOOP;
  UPDATE public.erp_contracting_settings SET settings=p_input-'revision',revision=revision+1 WHERE cafe_id=p_cafe_id RETURNING jsonb_build_object('revision',revision) INTO result;
 ELSE
  doc_id:=(p_input->>'id')::uuid;
  SELECT * INTO old FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id AND id=doc_id FOR UPDATE;
  IF p_action='save' THEN
   kind_name:=p_input->>'kind';source_id:=nullif(p_input->>'source_id','')::uuid;project_id:=nullif(p_input->>'project_id','')::uuid;customer_id:=nullif(p_input->>'customer_id','')::uuid;
   IF doc_id IS NULL OR kind_name NOT IN('bid','project','cost_sheet','quotation','contract','certificate','work_item') OR coalesce((p_input->>'revision')::integer,-1)<>coalesce(old.revision,0) THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
   IF old.id IS NOT NULL AND (old.kind<>kind_name OR (old.status NOT IN('draft','issued') AND NOT(old.kind IN('project','work_item') AND old.status='active')) OR EXISTS(SELECT 1 FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id AND source_id=old.id)) THEN RAISE EXCEPTION 'المستند معتمد أو مرتبط بمستند آخر ولا يقبل التعديل' USING ERRCODE='22023';END IF;
   IF customer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM erp_branch_private.bf_parties WHERE cafe_id=p_cafe_id AND id=customer_id AND kind='customer' AND active) THEN RAISE EXCEPTION 'Invalid customer' USING ERRCODE='22023';END IF;
   IF kind_name<>'work_item' AND customer_id IS NULL THEN RAISE EXCEPTION 'اختر العميل' USING ERRCODE='22023';END IF;
   IF project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM erp_branch_private.erp_contracting_documents pr WHERE pr.cafe_id=p_cafe_id AND pr.id=erp_contracting.project_id AND pr.kind='project' AND pr.customer_id=erp_contracting.customer_id AND pr.status NOT IN('closed','cancelled')) THEN RAISE EXCEPTION 'راجع المشروع والعميل المرتبط به' USING ERRCODE='22023';END IF;
   IF source_id IS NOT NULL THEN
    SELECT * INTO src FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id AND id=erp_contracting.source_id;
    IF src.id IS NULL OR src.customer_id IS DISTINCT FROM customer_id OR src.status IN('draft','rejected','cancelled','closed') OR NOT((kind_name='cost_sheet' AND src.kind='bid') OR (kind_name='quotation' AND src.kind='cost_sheet' AND src.status='approved') OR (kind_name='contract' AND src.kind='quotation' AND src.status='approved') OR (kind_name='certificate' AND src.kind='contract' AND src.status='active') OR (kind_name='project' AND src.kind='bid')) THEN RAISE EXCEPTION 'مصدر التحويل أو حالته غير صالح' USING ERRCODE='22023';END IF;
    IF src.project_id IS NOT NULL AND src.project_id IS DISTINCT FROM project_id THEN RAISE EXCEPTION 'المشروع لا يطابق مصدر التحويل' USING ERRCODE='22023';END IF;
   ELSIF kind_name='certificate' THEN RAISE EXCEPTION 'اختر عقدًا نشطًا' USING ERRCODE='22023';END IF;
   IF kind_name='project' AND length(btrim(coalesce(p_input->>'cost_center','')))=0 THEN RAISE EXCEPTION 'أدخل مركز التكلفة' USING ERRCODE='22023';END IF;
   IF project_id=doc_id OR source_id=doc_id THEN RAISE EXCEPTION 'لا يمكن ربط المستند بنفسه' USING ERRCODE='22023';END IF;
   IF jsonb_typeof(p_input->'assigned_users') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'assigned_users')>50 OR jsonb_typeof(p_input->'custom_fields') IS DISTINCT FROM 'object' OR length(coalesce(p_input->>'description',''))>5000 OR coalesce((p_input->>'budget')::numeric,-1) NOT BETWEEN 0 AND 1e9 OR coalesce((p_input->>'duration')::numeric,-1) NOT BETWEEN 0 AND 1e9 OR p_input->>'duration_unit' NOT IN('days','weeks','months','years') THEN RAISE EXCEPTION 'راجع بيانات المشروع' USING ERRCODE='22023';END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_input->'assigned_users') u WHERE NOT EXISTS(SELECT 1 FROM erp_branch_private.bf_staff s WHERE s.cafe_id=p_cafe_id AND s.user_id=u::uuid AND s.active) AND NOT EXISTS(SELECT 1 FROM public.cafes c WHERE c.id=p_cafe_id AND c.owner_user_id=u::uuid)) THEN RAISE EXCEPTION 'الموظف غير متاح لهذه العلامة' USING ERRCODE='22023';END IF;
   FOR resource IN SELECT value FROM jsonb_array_elements(coalesce(config->'fields','[]')) LOOP
    IF (resource->>'active')::boolean AND (resource->>'required')::boolean AND length(btrim(coalesce(p_input#>>ARRAY['custom_fields',resource->>'id'],'')))=0 THEN RAISE EXCEPTION 'أكمل حقول المشروع المطلوبة' USING ERRCODE='22023';END IF;
   END LOOP;
   IF nullif(p_input->>'end_date','')::date<nullif(p_input->>'start_date','')::date THEN RAISE EXCEPTION 'تاريخ الانتهاء يسبق البداية' USING ERRCODE='22023';END IF;
   IF jsonb_typeof(p_input->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'lines')>100 OR (kind_name<>'project' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_input->'lines') l WHERE l->>'kind'='work' AND (l->>'quantity')::numeric>0)) THEN RAISE EXCEPTION 'أضف بنود الأعمال والكميات' USING ERRCODE='22023';END IF;
   number_code:=coalesce(old.number,nullif(btrim(p_input->>'number'),''));
   IF number_code IS NULL THEN next_number:=coalesce((config#>>ARRAY['numbering',kind_name])::bigint,1);WHILE EXISTS(SELECT 1 FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id AND kind=kind_name AND number=lpad(next_number::text,6,'0')) LOOP next_number:=next_number+1;END LOOP;number_code:=lpad(next_number::text,6,'0');UPDATE public.erp_contracting_settings SET settings=jsonb_set(jsonb_set(settings,'{numbering}',coalesce(settings->'numbering','{}'),true),ARRAY['numbering',kind_name],to_jsonb(next_number+1),true) WHERE cafe_id=p_cafe_id;END IF;
   status_name:=CASE WHEN coalesce((p_input->>'draft')::boolean,false) THEN 'draft' WHEN kind_name IN('project','work_item') THEN 'active' ELSE 'issued' END;
   INSERT INTO public.erp_contracting_documents(id,cafe_id,kind,title,number,status,customer_id,project_id,source_id,retention_rate,recovery_rate,advance_amount,details,actor)
   VALUES(doc_id,p_cafe_id,kind_name,p_input->>'title',number_code,status_name,customer_id,project_id,source_id,coalesce((p_input->>'retention_rate')::numeric,0),coalesce((p_input->>'recovery_rate')::numeric,0),coalesce((p_input->>'advance_amount')::numeric,0),p_input-ARRAY['id','kind','title','number','revision','status','customer_id','project_id','source_id','lines','draft','retention_rate','recovery_rate','advance_amount'],auth.uid())
   ON CONFLICT(cafe_id,id) DO UPDATE SET title=excluded.title,status=excluded.status,customer_id=excluded.customer_id,project_id=excluded.project_id,source_id=excluded.source_id,retention_rate=excluded.retention_rate,recovery_rate=excluded.recovery_rate,advance_amount=excluded.advance_amount,details=excluded.details,revision=erp_contracting_documents.revision+1,updated_at=clock_timestamp(),actor=auth.uid();
   DELETE FROM erp_branch_private.erp_contracting_lines WHERE cafe_id=p_cafe_id AND document_id=doc_id;
   FOR line IN SELECT value FROM jsonb_array_elements(p_input->'lines') LOOP
    n:=n+1;
    IF nullif(line->>'parent_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_input->'lines') p WHERE p->>'id'=line->>'parent_id' AND p->>'kind' IN('heading','subheading') AND p->>'id'<>line->>'id') THEN RAISE EXCEPTION 'راجع ترتيب البنود' USING ERRCODE='22023';END IF;
    IF EXISTS(WITH RECURSIVE parents AS(SELECT line->>'id' id,line->>'parent_id' parent,ARRAY[line->>'id'] seen,false cycle UNION ALL SELECT p->>'id',p->>'parent_id',a.seen||(p->>'id'),(p->>'id')=ANY(a.seen) FROM parents a JOIN jsonb_array_elements(p_input->'lines') p ON p->>'id'=a.parent WHERE NOT a.cycle) SELECT 1 FROM parents WHERE cycle) THEN RAISE EXCEPTION 'يوجد ارتباط دائري بين البنود' USING ERRCODE='22023';END IF;
    IF kind_name<>'certificate' AND nullif(line->>'source_line_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM erp_branch_private.erp_contracting_lines WHERE cafe_id=p_cafe_id AND document_id=erp_contracting.source_id AND id=(line->>'source_line_id')::uuid) THEN RAISE EXCEPTION 'بند المصدر غير متاح' USING ERRCODE='22023';END IF;
    IF kind_name='certificate' AND line->>'kind'='work' THEN
      SELECT * INTO source_line FROM erp_branch_private.erp_contracting_lines WHERE cafe_id=p_cafe_id AND document_id=source_id AND id=(line->>'source_line_id')::uuid AND kind='work';
      IF source_line.id IS NULL THEN RAISE EXCEPTION 'بند المستخلص غير موجود في العقد' USING ERRCODE='22023';END IF;
      line:=line||jsonb_build_object('unit_price',source_line.unit_price,'tax_rate',source_line.tax_rate,'unit',source_line.unit,'name',source_line.name);
    END IF;
    INSERT INTO public.erp_contracting_lines(cafe_id,document_id,id,position,parent_id,source_line_id,kind,name,unit,note,quantity,unit_price,markup,tax_rate) VALUES(p_cafe_id,doc_id,(line->>'id')::uuid,n,nullif(line->>'parent_id','')::uuid,nullif(line->>'source_line_id','')::uuid,line->>'kind',line->>'name',line->>'unit',coalesce(line->>'note',''),(line->>'quantity')::numeric,(line->>'unit_price')::numeric,(line->>'markup')::numeric,(line->>'tax_rate')::numeric);
    IF jsonb_typeof(line->'resources') IS DISTINCT FROM 'array' OR jsonb_array_length(line->'resources')>100 THEN RAISE EXCEPTION 'Invalid resources' USING ERRCODE='22023';END IF;
    FOR resource IN SELECT value FROM jsonb_array_elements(line->'resources') LOOP
      INSERT INTO public.erp_contracting_resources(cafe_id,document_id,line_id,id,item_id,kind,name,unit,consumption,unit_cost) VALUES(p_cafe_id,doc_id,(line->>'id')::uuid,(resource->>'id')::uuid,nullif(resource->>'item_id','')::uuid,resource->>'kind',resource->>'name',resource->>'unit',(resource->>'consumption')::numeric,(resource->>'unit_cost')::numeric);
    END LOOP;
   END LOOP;
   SELECT coalesce(sum(round(quantity*unit_price,2)),0),coalesce(sum(round(round(quantity*unit_price,2)*tax_rate/100,2)),0) INTO sub,tax_total FROM erp_branch_private.erp_contracting_lines WHERE cafe_id=p_cafe_id AND document_id=doc_id AND kind='work';
   SELECT coalesce(sum(round(l.quantity*r.consumption*r.unit_cost,2)),0) INTO cost_total FROM erp_branch_private.erp_contracting_lines l JOIN erp_branch_private.erp_contracting_resources r ON r.cafe_id=l.cafe_id AND r.document_id=l.document_id AND r.line_id=l.id WHERE l.cafe_id=p_cafe_id AND l.document_id=doc_id;
   ret:=0;rec:=0;
   IF kind_name='certificate' THEN ret:=round(sub*src.retention_rate/100,2);SELECT coalesce(sum(recovery),0) INTO used FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id AND source_id=src.id AND kind='certificate' AND status='approved';rec:=least(round(sub*src.recovery_rate/100,2),greatest(0,src.advance_amount-used+erp_contracting_private.reversed_recovery(p_cafe_id,src.id)));END IF;
   UPDATE public.erp_contracting_documents SET subtotal=sub,tax=tax_total,total=sub+tax_total,cost=cost_total,retention=ret,recovery=rec,net_due=sub+tax_total-ret-rec WHERE cafe_id=p_cafe_id AND id=doc_id;
   IF kind_name='work_item' AND coalesce((p_input->>'is_default')::boolean,false) THEN UPDATE public.erp_contracting_documents SET details=jsonb_set(details,'{is_default}','false'),revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=p_cafe_id AND id<>doc_id AND kind='work_item' AND details->>'is_default'='true';END IF;
   result:=jsonb_build_object('id',doc_id,'revision',coalesce(old.revision,0)+1);
  ELSE
   IF old.id IS NULL THEN RAISE EXCEPTION 'المستند غير متاح' USING ERRCODE='42501';END IF;
   IF old.revision IS DISTINCT FROM (p_input->>'revision')::integer THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
   IF p_action='transition' THEN
    status_name:=p_input->>'status';
    IF NOT((old.status='issued' AND status_name='approved' AND old.kind IN('cost_sheet','quotation','certificate')) OR (old.kind='contract' AND old.status='issued' AND status_name='active') OR (old.kind IN('project','contract') AND old.status='active' AND status_name='closed') OR (old.status='issued' AND status_name='rejected' AND old.kind='quotation') OR (old.status IN('draft','issued','active') AND status_name='cancelled')) THEN RAISE EXCEPTION 'انتقال الحالة غير مسموح' USING ERRCODE='22023';END IF;
    IF status_name='cancelled' AND EXISTS(SELECT 1 FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id AND source_id=old.id AND status NOT IN('cancelled','rejected')) THEN RAISE EXCEPTION 'يوجد مستند مرتبط يمنع الإلغاء' USING ERRCODE='22023';END IF;
    IF old.kind='certificate' AND status_name='approved' THEN
     SELECT * INTO src FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id AND id=old.source_id FOR UPDATE;
     IF src.status<>'active' THEN RAISE EXCEPTION 'العقد غير نشط' USING ERRCODE='22023';END IF;
     FOR source_line IN SELECT * FROM erp_branch_private.erp_contracting_lines WHERE cafe_id=p_cafe_id AND document_id=src.id AND kind='work' LOOP
       SELECT coalesce(sum(l.quantity),0) INTO used FROM erp_branch_private.erp_contracting_lines l JOIN erp_branch_private.erp_contracting_documents d ON d.cafe_id=l.cafe_id AND d.id=l.document_id WHERE d.cafe_id=p_cafe_id AND d.kind='certificate' AND d.source_id=src.id AND (d.status='approved' OR d.id=old.id) AND l.source_line_id=source_line.id;
       used:=used-erp_contracting_private.reversed_quantity(p_cafe_id,src.id,source_line.id);IF used>source_line.quantity THEN RAISE EXCEPTION 'كمية المستخلص تتجاوز المتبقي في العقد' USING ERRCODE='22023';END IF;
     END LOOP;
     SELECT coalesce(sum(recovery),0) INTO used FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id AND source_id=src.id AND kind='certificate' AND status='approved';
     rec:=least(round(old.subtotal*src.recovery_rate/100,2),greatest(0,src.advance_amount-used+erp_contracting_private.reversed_recovery(p_cafe_id,src.id)));
     UPDATE public.erp_contracting_documents SET recovery=rec,net_due=total-retention-rec WHERE cafe_id=p_cafe_id AND id=old.id;
    END IF;
    UPDATE public.erp_contracting_documents SET status=status_name,revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=p_cafe_id AND id=old.id;
    result:=jsonb_build_object('id',old.id);
   ELSIF p_action='delete' THEN
    IF old.status NOT IN('draft','issued') OR old.invoice_draft_id IS NOT NULL THEN RAISE EXCEPTION 'يمكن حذف المستندات غير المعتمدة فقط' USING ERRCODE='22023';END IF;
    DELETE FROM erp_branch_private.erp_contracting_documents WHERE cafe_id=p_cafe_id AND id=old.id;result:=jsonb_build_object('id',old.id,'deleted',true);
   ELSIF p_action='note' THEN
    note_text:=btrim(p_input->>'note');IF length(note_text) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'أدخل الملاحظة' USING ERRCODE='22023';END IF;result:=jsonb_build_object('id',old.id);
   ELSIF p_action='activity' THEN
    IF old.kind<>'project' OR p_input->>'kind' NOT IN('appointment','time','action') OR coalesce(p_input->>'status','') NOT IN('planned','done','cancelled') OR (p_input->>'ends_at')::timestamptz<(p_input->>'starts_at')::timestamptz THEN RAISE EXCEPTION 'راجع بيانات الموعد أو الوقت' USING ERRCODE='22023';END IF;
    IF nullif(p_input->>'staff_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM erp_branch_private.bf_staff WHERE cafe_id=p_cafe_id AND user_id=(p_input->>'staff_id')::uuid AND active) AND NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe_id AND owner_user_id=(p_input->>'staff_id')::uuid) THEN RAISE EXCEPTION 'الموظف غير متاح' USING ERRCODE='22023';END IF;
    SELECT to_jsonb(a) INTO previous FROM erp_branch_private.erp_contracting_activities a WHERE cafe_id=p_cafe_id AND id=(p_input->>'activity_id')::uuid;
    IF coalesce((previous->>'revision')::integer,0) IS DISTINCT FROM (p_input->>'activity_revision')::integer OR (previous IS NOT NULL AND previous->>'project_id'<>old.id::text) THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
    INSERT INTO public.erp_contracting_activities(cafe_id,project_id,id,kind,title,note,starts_at,ends_at,staff_id,status) VALUES(p_cafe_id,old.id,(p_input->>'activity_id')::uuid,p_input->>'kind',p_input->>'title',p_input->>'note',(p_input->>'starts_at')::timestamptz,(p_input->>'ends_at')::timestamptz,nullif(p_input->>'staff_id','')::uuid,p_input->>'status') ON CONFLICT(cafe_id,id) DO UPDATE SET title=excluded.title,note=excluded.note,starts_at=excluded.starts_at,ends_at=excluded.ends_at,staff_id=excluded.staff_id,status=excluded.status,revision=erp_contracting_activities.revision+1;
    note_text:=p_input->>'title';result:=jsonb_build_object('id',old.id);
   ELSIF p_action='advance' THEN
    IF old.kind<>'project' OR old.status<>'active' THEN RAISE EXCEPTION 'المشروع غير نشط' USING ERRCODE='22023';END IF;
    result:=public.brand_finance_customer_credit(p_cafe_id,'receive',jsonb_build_object('partyId',old.customer_id,'requestId',p_request_id,'accountId',p_input->>'account_id','amount',p_input->'amount','note','دفعة مقدمة للمشروع '||old.number||' — '||coalesce(p_input->>'note','')));
    INSERT INTO public.erp_contracting_links(cafe_id,project_id,document_id,relation,amount) VALUES(p_cafe_id,old.id,(result->>'id')::uuid,'advance_credit',(p_input->>'amount')::numeric) ON CONFLICT DO NOTHING;
    result:=jsonb_build_object('id',old.id,'credit',result);
   ELSIF p_action='project_invoice' THEN
    IF old.kind<>'project' OR old.status<>'active' OR p_input->>'invoice_kind' IS DISTINCT FROM 'invoice' THEN RAISE EXCEPTION 'المشروع غير نشط' USING ERRCODE='22023';END IF;
    amount:=coalesce((p_input->>'amount')::numeric,0);IF amount<=0 OR amount>1e9 OR coalesce((p_input->>'tax_rate')::numeric,-1) NOT BETWEEN 0 AND 100 THEN RAISE EXCEPTION 'أدخل مبلغ الفاتورة والضريبة' USING ERRCODE='22023';END IF;
    payload:=jsonb_build_object('invoice',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('key',1,'productId','','quantity',1,'price',amount,'name',CASE WHEN p_input->>'invoice_kind'='advance' THEN 'دفعة مقدمة — ' ELSE 'أعمال — ' END||old.title,'kind','service','vatRate',(p_input->>'tax_rate')::numeric,'taxCategory',CASE WHEN (p_input->>'tax_rate')::numeric=0 THEN 'O' ELSE 'S' END,'exemptionReason',CASE WHEN (p_input->>'tax_rate')::numeric=0 THEN 'خارج نطاق الضريبة حسب المشروع' ELSE '' END)),'warehouseId','','partyId',old.customer_id,'accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','taxInclusive',false,'note','مشروع مقاولات '||old.number,'currency','SAR','exchangeRate',1),'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb);
    source_id:=gen_random_uuid();PERFORM public.brand_finance_save_invoice_draft(p_cafe_id,source_id,0,payload);INSERT INTO public.erp_contracting_invoice_drafts VALUES(p_cafe_id,old.id,source_id,p_input->>'invoice_kind');result:=jsonb_build_object('id',old.id,'draft_id',source_id);
   ELSIF p_action='invoice' THEN
    IF old.kind<>'certificate' OR old.status<>'approved' OR old.total<=0 THEN RAISE EXCEPTION 'اعتمد المستخلص قبل إنشاء الفاتورة' USING ERRCODE='22023';END IF;
    IF old.invoice_draft_id IS NOT NULL THEN result:=jsonb_build_object('id',old.id,'draft_id',old.invoice_draft_id,'invoice_id',old.invoice_id);
    ELSE
     SELECT jsonb_agg(jsonb_build_object('key',position,'productId','','quantity',quantity,'price',unit_price,'description',note,'name',name,'kind','service','vatRate',tax_rate,'taxCategory',CASE WHEN tax_rate=0 THEN 'O' ELSE 'S' END,'exemptionReason',CASE WHEN tax_rate=0 THEN 'خارج نطاق الضريبة حسب بند العقد' ELSE '' END) ORDER BY position) INTO payload FROM erp_branch_private.erp_contracting_lines WHERE cafe_id=p_cafe_id AND document_id=old.id AND kind='work' AND quantity>0;
     payload:=jsonb_build_object('invoice',jsonb_build_object('lines',payload,'warehouseId','','partyId',old.customer_id,'accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','taxInclusive',false,'note','مستخلص مقاولات '||old.number||' | خصم ضمان الأعمال '||old.retention||' | استرداد الدفعة المقدمة '||old.recovery,'currency','SAR','exchangeRate',1),'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb);
     source_id:=gen_random_uuid();draft_result:=public.brand_finance_save_invoice_draft(p_cafe_id,source_id,0,payload);
     UPDATE public.erp_contracting_documents SET invoice_draft_id=erp_contracting.source_id,revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=p_cafe_id AND id=old.id;
     result:=jsonb_build_object('id',old.id,'draft_id',source_id,'invoice_id',NULL);
    END IF;
   ELSIF p_action='financial' THEN
    IF old.kind<>'project' OR old.status<>'active' OR p_input->>'operation' NOT IN('treasury','settlement','refund','stock_adjust','stock_transfer','journal','purchase') THEN RAISE EXCEPTION 'المعاملة غير متاحة للمشروع' USING ERRCODE='22023';END IF;
    payload:=p_input->'payload';
    IF p_input->>'operation' IN('settlement','refund') AND NOT EXISTS(SELECT 1 FROM erp_branch_private.erp_contracting_links WHERE cafe_id=p_cafe_id AND project_id=old.id AND document_id=(payload->>'documentId')::uuid) THEN RAISE EXCEPTION 'اربط الفاتورة بالمشروع أولًا' USING ERRCODE='22023';END IF;
    result:=public.brand_finance_execute(p_cafe_id,p_input->>'operation',payload,p_request_id);
    source_id:=coalesce(nullif(result->>'id','')::uuid,nullif(result->>'documentId','')::uuid);
    IF source_id IS NOT NULL AND EXISTS(SELECT 1 FROM erp_branch_private.bf_documents WHERE cafe_id=p_cafe_id AND id=source_id) THEN INSERT INTO public.erp_contracting_links(cafe_id,project_id,document_id,relation) VALUES(p_cafe_id,old.id,source_id,p_input->>'operation') ON CONFLICT DO NOTHING;END IF;
    result:=jsonb_build_object('id',old.id,'financial',result);
   ELSIF p_action='link' THEN
    IF old.kind<>'project' OR NOT EXISTS(SELECT 1 FROM erp_branch_private.bf_documents WHERE cafe_id=p_cafe_id AND id=(p_input->>'document_id')::uuid) THEN RAISE EXCEPTION 'المعاملة غير متاحة' USING ERRCODE='22023';END IF;
    INSERT INTO public.erp_contracting_links(cafe_id,project_id,document_id,relation) VALUES(p_cafe_id,old.id,(p_input->>'document_id')::uuid,'linked') ON CONFLICT DO NOTHING;result:=jsonb_build_object('id',old.id);
   ELSE RAISE EXCEPTION 'Unknown action' USING ERRCODE='22023';END IF;
  END IF;
 END IF;
 INSERT INTO public.erp_contracting_events(cafe_id,document_id,action,note,actor) VALUES(p_cafe_id,doc_id,p_action||CASE WHEN p_action='transition' THEN ':'||status_name ELSE '' END,coalesce(note_text,''),auth.uid());
 INSERT INTO public.erp_contracting_requests(cafe_id,id,command,result) VALUES(p_cafe_id,p_request_id,cmd,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_contracting_private.calculate(c uuid, rid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
<<calculate>>
DECLARE d public.erp_contracting_documents;s public.erp_contracting_documents;l record;v jsonb;available jsonb;prior_net numeric;prior_ret numeric;prior_rec numeric;sub numeric:=0;tax numeric:=0;ret numeric;rec numeric;used numeric;BEGIN
 SELECT * INTO d FROM public.erp_contracting_documents WHERE cafe_id=c AND id=rid FOR UPDATE;SELECT * INTO s FROM public.erp_contracting_documents WHERE cafe_id=c AND id=d.source_id FOR UPDATE;
 IF s.kind<>'certificate' OR s.status<>'approved' OR s.invoice_id IS NULL OR d.customer_id IS DISTINCT FROM s.customer_id OR d.project_id IS DISTINCT FROM s.project_id THEN RAISE EXCEPTION 'Reverse source must be billed certificate' USING ERRCODE='22023';END IF;
 PERFORM erp_branch_private.assert_input(c,jsonb_build_object('id',s.id,'documentId',s.invoice_id));available:=brand_finance_private.refund_lines(c,s.invoice_id,true);
 DELETE FROM public.erp_contracting_reverse_lines WHERE cafe_id=c AND document_id=rid;
 FOR l IN SELECT * FROM public.erp_contracting_lines WHERE cafe_id=c AND document_id=rid ORDER BY position LOOP
  SELECT x INTO v FROM jsonb_array_elements(available)x WHERE x->>'id'=erp_contracting_private.invoice_line(c,s.id,l.source_line_id)::text;
  IF v IS NULL OR l.quantity<=0 OR l.quantity<>round(l.quantity,3) OR l.quantity>(v->>'quantity')::numeric-(v->>'returned_quantity')::numeric THEN RAISE EXCEPTION 'Reverse quantity exceeds remaining billed quantity' USING ERRCODE='22023';END IF;
  IF EXISTS(SELECT 1 FROM public.erp_contracting_reverse_lines WHERE cafe_id=c AND document_id=rid AND invoice_line_id=(v->>'id')::uuid) THEN RAISE EXCEPTION 'Duplicate reverse source line' USING ERRCODE='22023';END IF;
  INSERT INTO public.erp_contracting_reverse_lines VALUES(c,rid,l.id,(v->>'id')::uuid,l.quantity,round((v->>'net')::numeric*((v->>'returned_quantity')::numeric+l.quantity)/(v->>'quantity')::numeric,2)-(v->>'returned_net')::numeric,round((v->>'tax')::numeric*((v->>'returned_quantity')::numeric+l.quantity)/(v->>'quantity')::numeric,2)-(v->>'returned_tax')::numeric);
 END LOOP;
 SELECT sum(net),sum(erp_contracting_reverse_lines.tax) INTO sub,tax FROM public.erp_contracting_reverse_lines WHERE cafe_id=c AND document_id=rid;
 SELECT coalesce(sum(subtotal),0),coalesce(sum(retention),0),coalesce(sum(recovery),0) INTO prior_net,prior_ret,prior_rec FROM public.erp_contracting_documents WHERE cafe_id=c AND source_id=s.id AND kind='reverse_certificate' AND status='approved';
 ret:=least(s.retention-prior_ret,greatest(0,round(s.retention*(prior_net+sub)/nullif(s.subtotal,0),2)-prior_ret));rec:=least(s.recovery-prior_rec,greatest(0,round(s.recovery*(prior_net+sub)/nullif(s.subtotal,0),2)-prior_rec));
 SELECT coalesce(sum(total),0) INTO used FROM public.bf_credit_notes WHERE cafe_id=c AND source_invoice_id=s.invoice_id AND status='issued';SELECT used+coalesce(sum(total),0) INTO used FROM public.bf_documents WHERE cafe_id=c AND reference_id=s.invoice_id AND kind='refund';
 IF sub+tax<0 OR sub+tax+used>s.total THEN RAISE EXCEPTION 'Reverse amount exceeds source balance' USING ERRCODE='22023';END IF;
 UPDATE public.erp_contracting_documents SET subtotal=sub,tax=calculate.tax,total=sub+calculate.tax,retention=coalesce(ret,0),recovery=coalesce(rec,0),net_due=sub+calculate.tax-coalesce(ret,0)-coalesce(rec,0) WHERE cafe_id=c AND id=rid;
END $function$

CREATE OR REPLACE FUNCTION erp_contracting_private.credit_validate_before_reverse(cafe uuid, p jsonb, strict_refs boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE e jsonb;rows jsonb:='[]';result_rows jsonb:='[]';prod public.menu_products%ROWTYPE;item public.bf_items%ROWTYPE;
 customer_name text:='';warehouse_name text:='';salesperson_name text:='';source public.bf_documents%ROWTYPE;
 qty numeric;price numeric;rate numeric;gross numeric;disc numeric;value numeric;after_row numeric;subtotal numeric:=0;after_rows numeric:=0;
 doc_discount numeric;remaining numeric;base_left numeric;allocated numeric;taxable numeric;row_tax numeric;row_total numeric;tax numeric:=0;total numeric:=0;cost numeric;cost_known boolean;inclusive boolean;k text;components jsonb;component record;
BEGIN
 IF p IS NULL OR jsonb_typeof(p) IS DISTINCT FROM 'object' OR octet_length(p::text)>100000 OR p::text ~* '"[-+]?(nan|infinity)"'
 OR jsonb_typeof(p->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'lines') NOT BETWEEN 1 AND 100
 OR coalesce(p->>'template','') NOT IN('standard','thermal') OR coalesce(p->>'deliveryMethod','')<>'print'
 OR jsonb_typeof(p->'taxInclusive') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p->'stockRequired') IS DISTINCT FROM 'boolean'
 OR coalesce(p->>'date','') !~ '^\d{4}-\d{2}-\d{2}$' OR coalesce(p->>'issueDate','') !~ '^\d{4}-\d{2}-\d{2}$'
 OR NOT isfinite((p->>'date')::date) OR NOT isfinite((p->>'issueDate')::date)
 OR coalesce(p->>'discountKind','') NOT IN('amount','percent') THEN RAISE EXCEPTION 'راجع بيانات الإشعار الدائن' USING ERRCODE='22023';END IF;
 FOREACH k IN ARRAY ARRAY['reason','note','terms'] LOOP
  IF jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR length(p->>k)>(CASE k WHEN 'terms' THEN 3000 WHEN 'note' THEN 1000 ELSE 500 END) THEN RAISE EXCEPTION 'راجع نص الإشعار';END IF;
 END LOOP;
 IF strict_refs AND length(trim(p->>'reason'))=0 THEN RAISE EXCEPTION 'حدد سبب إصدار الإشعار الدائن';END IF;
 IF nullif(p->>'partyId','') IS NOT NULL THEN
  SELECT name INTO customer_name FROM public.bf_parties WHERE cafe_id=cafe AND id::text=p->>'partyId' AND kind='customer' AND (NOT strict_refs OR active);
  IF NOT FOUND THEN RAISE EXCEPTION 'اختر عميلًا متاحًا للعلامة';END IF;
 ELSIF strict_refs THEN RAISE EXCEPTION 'اختر العميل';END IF;
 IF nullif(p->>'warehouseId','') IS NOT NULL THEN
  SELECT name INTO warehouse_name FROM public.bf_warehouses WHERE cafe_id=cafe AND id::text=p->>'warehouseId' AND (NOT strict_refs OR active);
  IF NOT FOUND THEN RAISE EXCEPTION 'اختر مستودعًا متاحًا للعلامة';END IF;
 ELSIF strict_refs AND (p->>'stockRequired')::boolean THEN RAISE EXCEPTION 'اختر المستودع لاستلام المنتجات';END IF;
 IF p->>'sourceInvoiceId' IS NOT NULL THEN
  SELECT * INTO source FROM public.bf_documents WHERE cafe_id=cafe AND id::text=p->>'sourceInvoiceId' AND kind='sale' AND party_id::text=p->>'partyId';
  IF NOT FOUND THEN RAISE EXCEPTION 'الفاتورة المرجعية لا تخص هذا العميل';END IF;
 END IF;
 IF p->>'salespersonId' IS NOT NULL THEN
  SELECT name INTO salesperson_name FROM public.bf_staff WHERE cafe_id=cafe AND user_id::text=p->>'salespersonId' AND active;
  IF NOT FOUND THEN RAISE EXCEPTION 'مسؤول المبيعات غير متاح';END IF;
 END IF;
 inclusive:=(p->>'taxInclusive')::boolean;
 IF NOT brand_finance_private.invoice_number_valid(p->'vatRate',0,100,2) OR NOT brand_finance_private.invoice_number_valid(p->'discountValue',0,1000000000,2) THEN RAISE EXCEPTION 'راجع الضريبة والخصم';END IF;
 FOR e IN SELECT x.value FROM jsonb_array_elements(p->'lines') x LOOP
  prod:=NULL;item:=NULL;cost:=0;cost_known:=false;components:='[]'::jsonb;
  IF jsonb_typeof(e) IS DISTINCT FROM 'object' OR NOT brand_finance_private.invoice_number_valid(e->'quantity',0.001,9999,3) OR NOT brand_finance_private.invoice_number_valid(e->'price',0,10000000,2)
   OR length(coalesce(e->>'description',''))>500 OR coalesce(e->>'discountKind','amount') NOT IN('amount','percent')
   OR (e ? 'discount' AND NOT brand_finance_private.invoice_number_valid(e->'discount',0,1000000000,2))
   OR (e ? 'vatRate' AND NOT brand_finance_private.invoice_number_valid(e->'vatRate',0,100,2)) THEN RAISE EXCEPTION 'راجع أسعار وكميات وخصومات البنود';END IF;
  IF nullif(e->>'productId','') IS NOT NULL THEN
   SELECT * INTO prod FROM public.menu_products WHERE cafe_id=cafe AND id::text=e->>'productId' AND deleted_at IS NULL;
   IF NOT FOUND THEN RAISE EXCEPTION 'الصنف غير متاح للعلامة';END IF;
   SELECT * INTO item FROM public.bf_items WHERE cafe_id=cafe AND menu_product_id=prod.id AND active;
   SELECT coalesce(st.average_cost,0),st.cost_known INTO cost,cost_known FROM public.bf_stock st WHERE cafe_id=cafe AND warehouse_id::text=p->>'warehouseId' AND item_id=item.id;
  ELSIF strict_refs THEN RAISE EXCEPTION 'حدد الصنف في كل بند';END IF;
  qty:=(e->>'quantity')::numeric;price:=(e->>'price')::numeric;rate:=coalesce((e->>'vatRate')::numeric,(p->>'vatRate')::numeric);gross:=round(qty*price,2);value:=coalesce((e->>'discount')::numeric,0);
  IF e->>'discountKind'='percent' AND value>100 THEN RAISE EXCEPTION 'نسبة الخصم تتجاوز ١٠٠';END IF;
  disc:=round(CASE WHEN e->>'discountKind'='percent' THEN gross*value/100 ELSE value END,2);
  IF disc>gross THEN RAISE EXCEPTION 'خصم البند أكبر من قيمته';END IF;
  FOR component IN
   SELECT i.id, l.quantity factor,coalesce(st.average_cost,0) unit_cost,coalesce(st.cost_known,false) cost_known FROM public.bf_item_product_links l JOIN public.bf_items i ON i.cafe_id=l.cafe_id AND i.id=l.item_id AND i.active LEFT JOIN public.bf_stock st ON st.cafe_id=i.cafe_id AND st.item_id=i.id AND st.warehouse_id::text=p->>'warehouseId' WHERE l.cafe_id=cafe AND l.product_id=prod.id
   UNION ALL SELECT item.id,1,coalesce(cost,0),coalesce(cost_known,false) WHERE item.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_item_product_links l WHERE l.cafe_id=cafe AND l.product_id=prod.id)
  LOOP
   IF strict_refs AND (p->>'stockRequired')::boolean AND NOT component.cost_known THEN RAISE EXCEPTION '??? ????? ?????? ?????? ??? ???? ??? ????? ??? ????????';END IF;
   IF qty*component.factor<>round(qty*component.factor,3) THEN RAISE EXCEPTION '???? ?????? ????? ??? ?? ???? ???????';END IF;
   components:=components||jsonb_build_array(jsonb_build_object('itemId',component.id,'quantity',qty*component.factor,'unitCost',component.unit_cost,'costKnown',component.cost_known));
  END LOOP;
  IF strict_refs AND (p->>'stockRequired')::boolean AND jsonb_array_length(components)=0 THEN RAISE EXCEPTION '?? ??? ???????? ??? ?? ???? ??????? ???? ????? ???';END IF;
  after_row:=gross-disc;subtotal:=subtotal+gross;after_rows:=after_rows+after_row;
  rows:=rows||jsonb_build_array(jsonb_build_object('productId',coalesce(e->>'productId',''),'name',coalesce(prod.name,''),'description',coalesce(e->>'description',''),'itemId',item.id,'unitCost',coalesce(cost,0),'components',components,'quantity',qty,'price',price,'rowDiscount',disc,'after',after_row,'vatRate',rate));
 END LOOP;
 value:=(p->>'discountValue')::numeric;
 IF p->>'discountKind'='percent' AND value>100 THEN RAISE EXCEPTION 'راجع نسبة خصم الإشعار';END IF;
 doc_discount:=round(CASE WHEN p->>'discountKind'='percent' THEN after_rows*value/100 ELSE value END,2);
 IF doc_discount>after_rows THEN RAISE EXCEPTION 'خصم الإشعار أكبر من قيمته';END IF;
 remaining:=doc_discount;base_left:=after_rows;
 FOR e IN SELECT x.value FROM jsonb_array_elements(rows) x LOOP
  after_row:=(e->>'after')::numeric;rate:=(e->>'vatRate')::numeric;allocated:=least(after_row,remaining,CASE WHEN base_left=0 THEN 0 ELSE round(remaining*after_row/base_left,2) END);
  remaining:=remaining-allocated;base_left:=base_left-after_row;taxable:=after_row-allocated;
  row_tax:=round(CASE WHEN inclusive THEN taxable-taxable/(1+rate/100) ELSE taxable*rate/100 END,2);row_total:=CASE WHEN inclusive THEN taxable ELSE taxable+row_tax END;
  tax:=tax+row_tax;total:=total+row_total;
  result_rows:=result_rows||jsonb_build_array((e-'after'-'rowDiscount')||jsonb_build_object('discount',(e->>'rowDiscount')::numeric+allocated,'net',row_total-row_tax,'tax',row_tax,'total',row_total));
 END LOOP;
 IF total>1000000000 OR (strict_refs AND total<=0) THEN RAISE EXCEPTION 'إجمالي الإشعار يجب أن يكون أكبر من صفر';END IF;
 IF strict_refs AND (p->>'stockRequired')::boolean AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result_rows) x WHERE jsonb_array_length(x->'components')>0) THEN RAISE EXCEPTION 'لا توجد أصناف مخزنية لاستلامها';END IF;
 RETURN jsonb_build_object('customerName',coalesce(customer_name,''),'warehouseName',coalesce(warehouse_name,''),'salespersonName',coalesce(salesperson_name,''),'sourceNumber',source.number,'lines',result_rows,'subtotal',subtotal,'discount',subtotal-after_rows+doc_discount,'tax',tax,'total',total);
END $function$

CREATE OR REPLACE FUNCTION erp_contracting_private.refund_lines_before_reverse(p_cafe uuid, p_doc uuid, p_managed boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE result jsonb:='[]';l jsonb;creditnet numeric;credittax numeric;remaining numeric;net numeric;tax numeric;effective numeric;BEGIN
 FOR l IN SELECT value FROM jsonb_array_elements(brand_finance_private.refund_lines_before_purchase_debits(p_cafe,p_doc,p_managed)) LOOP
  SELECT coalesce(sum(d.net),0),coalesce(sum(d.tax),0) INTO creditnet,credittax FROM public.erp_purchase_debits d WHERE cafe_id=p_cafe AND source_document_id=p_doc AND line_id=(l->>'id')::uuid;
  remaining:=(l->>'quantity')::numeric-(l->>'returned_quantity')::numeric;
  IF remaining>0 AND creditnet>0 THEN net:=greatest(0,(l->>'net')::numeric-(l->>'returned_net')::numeric-creditnet);tax:=greatest(0,(l->>'tax')::numeric-(l->>'returned_tax')::numeric-credittax);effective:=round(net*(l->>'quantity')::numeric/remaining,2);l:=l||jsonb_build_object('net',effective,'returned_net',effective-net);effective:=round(tax*(l->>'quantity')::numeric/remaining,2);l:=l||jsonb_build_object('tax',effective,'returned_tax',effective-tax);END IF;result:=result||jsonb_build_array(l);
 END LOOP;RETURN result;
END$function$

CREATE OR REPLACE FUNCTION erp_customer_form_private.assert_entry(c uuid, i uuid, a text)
 RETURNS erp_customer_form_entries
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE e public.erp_customer_form_entries;cfg jsonb;BEGIN
 PERFORM erp_customer_form_private.authorize(c,a);
 SELECT * INTO e FROM public.erp_customer_form_entries WHERE cafe_id=c AND id=i FOR KEY SHARE;
 SELECT config INTO cfg FROM public.erp_customer_forms WHERE cafe_id=c AND id=e.model_id;
 IF e.id IS NULL OR NOT erp_customer_form_private.record_visible(c,e.record_id,e.target_kind) OR NOT erp_customer_form_private.allowed(c,cfg,'read') OR NOT erp_customer_form_private.allowed(c,cfg,a) THEN RAISE EXCEPTION 'السجل غير متاح' USING ERRCODE='42501';END IF;RETURN e;
END $function$

CREATE OR REPLACE FUNCTION erp_customer_form_private.authorize(c uuid, a text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE r text;BEGIN
 r:=brand_finance_private.role_for(c);
 IF auth.uid() IS NULL OR NOT public.brand_account_not_cancelled(c) OR r IS NULL OR r NOT IN('owner','manager','accountant','auditor') OR(a<>'read' AND r='auditor') OR(a='settings' AND r<>'owner') THEN RAISE EXCEPTION 'لا تملك صلاحية نماذج العملاء' USING ERRCODE='42501';END IF;
 PERFORM erp_access_private.assert_allowed(c,'customers',a);
END $function$

CREATE OR REPLACE FUNCTION erp_customer_form_private.fields(c uuid, j jsonb, a text)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE result text[];r jsonb;BEGIN
 SELECT coalesce(array_agg(f->>'id'),'{}') INTO result FROM jsonb_array_elements(j->'fields') f;
 IF brand_finance_private.role_for(c)='owner' THEN RETURN result;END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(j#>'{permissions,fieldRules}') LOOP
  IF erp_workflow_private.selector(c,r->'selector') THEN SELECT ARRAY(SELECT unnest(result) INTERSECT SELECT jsonb_array_elements_text(r->a)) INTO result;END IF;
 END LOOP;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_customer_form_private.validate_values(fields jsonb, vals jsonb, p_cafe uuid DEFAULT NULL::uuid, p_record uuid DEFAULT NULL::uuid, p_scope uuid DEFAULT NULL::uuid, depth integer DEFAULT 0, p_draft boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE f jsonb;v jsonb;t text;x jsonb;txt text;tbl text;col text;valid boolean;metric numeric;BEGIN
 IF coalesce(jsonb_typeof(vals),'')<>'object' OR octet_length(vals::text)>262144 OR depth>2 THEN RAISE EXCEPTION 'بيانات الحقول الإضافية غير صالحة';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP
  t:=f->>'type';IF t IN('static','separator') THEN CONTINUE;END IF;
  v:=coalesce(vals->(f->>'id'),f->'defaultValue');
  IF coalesce((f->>'required')::boolean,false) AND NOT p_draft AND (v IS NULL OR v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb OR (t='checkbox' AND v<>'true')) THEN RAISE EXCEPTION 'أكمل الحقل المطلوب: %',f->>'label';END IF;
  IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
  IF t='subform' THEN
   IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>100 OR jsonb_array_length(v)<coalesce((f->>'minimumRows')::integer,0) THEN RAISE EXCEPTION 'عدد صفوف النموذج غير صالح';END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM erp_customer_form_private.validate_values(f->'fields',x,p_cafe,p_record,p_scope,depth+1,p_draft);END LOOP;CONTINUE;
  END IF;
  IF t='location' THEN
   IF jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'latitude')<>'number' OR jsonb_typeof(v->'longitude')<>'number' OR abs((v->>'latitude')::numeric)>90 OR abs((v->>'longitude')::numeric)>180 THEN RAISE EXCEPTION 'إحداثيات الموقع غير صالحة';END IF;CONTINUE;
  END IF;
  IF (t IN('number','currency') AND jsonb_typeof(v)<>'number') OR (t='checkbox' AND jsonb_typeof(v)<>'boolean') OR (t IN('multiselect','multidynamic') AND jsonb_typeof(v)<>'array') OR (t NOT IN('number','currency','checkbox','multiselect','multidynamic') AND jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'نوع قيمة الحقل غير صالح';END IF;
  txt:=v#>>'{}';
  IF length(txt)>20000 THEN RAISE EXCEPTION 'قيمة الحقل طويلة';END IF;
  IF (t='select' AND NOT(f->'options' @> jsonb_build_array(v))) OR (t='multiselect' AND NOT(f->'options' @> v)) THEN RAISE EXCEPTION 'اختيارات الحقل غير صالحة';END IF;
  IF t='email' AND txt!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'البريد الإلكتروني غير صالح';END IF;
  IF t='url' AND txt!~'^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'الرابط غير صالح';END IF;
  IF t='time' AND txt!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'الوقت غير صالح';END IF;
  IF t='date' THEN IF txt!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'التاريخ غير صالح';END IF;PERFORM txt::date;END IF;
  IF t IN('number','currency','text','textarea','formatted') THEN
   metric:=CASE WHEN t IN('number','currency') THEN txt::numeric ELSE length(txt) END;
   IF metric<nullif(f->>'minimum','')::numeric OR metric>nullif(f->>'maximum','')::numeric THEN RAISE EXCEPTION 'قيمة الحقل خارج الحدود: %',f->>'label';END IF;
  END IF;
  IF t IN('dynamic','multidynamic') THEN
   tbl:=CASE f->>'entity' WHEN 'items' THEN 'bf_items' WHEN 'customers' THEN 'bf_parties' WHEN 'employees' THEN 'bf_staff' WHEN 'warehouses' THEN 'bf_warehouses' WHEN 'accounts' THEN 'bf_accounts' WHEN 'bom' THEN 'erp_mfg_boms' WHEN 'routings' THEN 'erp_mfg_routings' WHEN 'workstations' THEN 'erp_mfg_workstations' WHEN 'orders' THEN 'erp_mfg_orders' WHEN 'sources' THEN 'bf_documents' END;
   IF tbl IS NULL OR p_cafe IS NULL THEN RAISE EXCEPTION 'الكيان المرتبط غير صالح';END IF;col:=CASE WHEN tbl='bf_staff' THEN 'user_id' ELSE 'id' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN t='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND %I=$2)',tbl,col) INTO valid USING p_cafe,(x#>>'{}')::uuid;
    IF NOT valid THEN RAISE EXCEPTION 'القيمة المرتبطة غير موجودة في العلامة';END IF;
   END LOOP;
  END IF;
  IF t IN('file','image') THEN
   IF p_record IS NULL OR to_regclass('public.erp_files') IS NULL THEN RAISE EXCEPTION 'احفظ السجل وأضف المرفق أولًا';END IF;
   EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=$1 AND record_id=$2 AND id=$3 AND entity_type=$4 AND uploaded AND ($5<>''image'' OR mime IN(''image/jpeg'',''image/png'')))' INTO valid USING p_cafe,p_record,txt::uuid,'customer_form_entry',t;
   IF NOT valid THEN RAISE EXCEPTION 'المرفق غير موجود في هذا السجل';END IF;
  END IF;
  IF coalesce((f->>'unique')::boolean,false) AND depth=0 THEN
   tbl:='erp_customer_form_entries';
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id IS DISTINCT FROM $2 AND field_values->$3=$4 AND model_id=$5)',tbl) INTO valid USING p_cafe,p_record,f->>'id',v,p_scope;
   IF valid THEN RAISE EXCEPTION 'قيمة الحقل مستخدمة مسبقًا: %',f->>'label';END IF;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_customer_form_private.value_scope(c uuid, fields jsonb, vals jsonb, depth integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE f jsonb;v jsonb;x jsonb;k text;b uuid:=erp_branch_private.current_branch(c);BEGIN
 IF depth>2 OR jsonb_typeof(vals) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(vals) q(value) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fields) ff(value) WHERE ff.value->>'id'=q.value)) THEN RETURN false;END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(fields) LOOP
  v:=vals->(f->>'id');IF v IS NULL OR v='null' OR v='""' THEN CONTINUE;END IF;
  IF f->>'type'='subform' THEN
   IF jsonb_typeof(v)<>'array' THEN RETURN false;END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP IF NOT erp_customer_form_private.value_scope(c,f->'fields',x,depth+1) THEN RETURN false;END IF;END LOOP;
  ELSIF f->>'type' IN('dynamic','multidynamic') THEN
   k:=CASE f->>'entity' WHEN 'customers' THEN 'customer' WHEN 'items' THEN 'item' WHEN 'accounts' THEN 'account' ELSE '' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN f->>'type'='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    IF k<>'' AND NOT erp_branch_private.allowed_resource(c,b,k,(x#>>'{}')::uuid) THEN RETURN false;END IF;
    IF NOT erp_branch_private.row_allowed(c,b,jsonb_build_object('id',x),'') THEN RETURN false;END IF;
    IF f->>'entity'='employees' AND b IS NOT NULL AND EXISTS(SELECT 1 FROM public.erp_hr_employees h WHERE h.cafe_id=c AND h.user_id=(x#>>'{}')::uuid AND h.active AND h.branch_id IS NOT NULL AND h.branch_id<>b AND NOT EXISTS(SELECT 1 FROM public.erp_branch_members bm WHERE bm.cafe_id=c AND bm.employee_id=h.id AND bm.branch_id=b)) THEN RETURN false;END IF;
    IF f->>'entity'='warehouses' AND NOT EXISTS(SELECT 1 FROM public.bf_warehouses w WHERE w.cafe_id=c AND w.id=(x#>>'{}')::uuid AND erp_branch_private.row_allowed(c,b,to_jsonb(w),'warehouse')) THEN RETURN false;END IF;
   END LOOP;
  END IF;
 END LOOP;RETURN true;
END $function$

CREATE OR REPLACE FUNCTION erp_customer_private.credit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE cfg jsonb;p jsonb;balance numeric;BEGIN
 IF NEW.kind<>'sale' OR NEW.shift_id IS NOT NULL OR NEW.party_id IS NULL OR NEW.total<=NEW.paid THEN RETURN NEW;END IF;
 SELECT s.payload,c.payload INTO cfg,p FROM public.erp_customer_profiles c LEFT JOIN public.erp_customer_settings s ON s.cafe_id=c.cafe_id WHERE c.cafe_id=NEW.cafe_id AND c.id=NEW.party_id;IF p IS NULL THEN RETURN NEW;END IF;
 IF coalesce((cfg->>'creditLimit')::boolean,false) AND nullif(p->>'creditLimit','') IS NOT NULL THEN
  SELECT coalesce(sum(j.debit-j.credit),0) INTO balance FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=NEW.cafe_id AND j.party_id=NEW.party_id AND a.kind='receivable';
  IF balance+NEW.total-NEW.paid>(p->>'creditLimit')::numeric THEN RAISE EXCEPTION 'الفاتورة تتجاوز الحد الائتماني للعميل';END IF;
 END IF;
 IF coalesce((cfg->>'creditDays')::boolean,false) AND nullif(p->>'creditDays','') IS NOT NULL AND EXISTS(SELECT 1 FROM public.bf_documents d WHERE d.cafe_id=NEW.cafe_id AND d.party_id=NEW.party_id AND d.kind='sale' AND (d.created_at AT TIME ZONE 'Asia/Riyadh')::date+(p->>'creditDays')::integer<(now() AT TIME ZONE 'Asia/Riyadh')::date AND (brand_finance_private.document_state(NEW.cafe_id,d.id)->>'outstanding')::numeric>0) THEN RAISE EXCEPTION 'للعميل فواتير تجاوزت المدة الائتمانية';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_customer_private.normalize_values(fields jsonb, vals jsonb, depth integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE f jsonb;v jsonb;arr jsonb;normalized jsonb:='{}';BEGIN
 IF depth>2 OR coalesce(jsonb_typeof(vals),'')<>'object' THEN RAISE EXCEPTION 'قيم الحقول غير صالحة';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP
  IF f->>'type' IN('static','separator') THEN CONTINUE;END IF;
  v:=coalesce(vals->(f->>'id'),f->'defaultValue');
  IF f->>'type'='subform' THEN
   IF v IS NULL THEN SELECT coalesce(jsonb_agg('{}'::jsonb),'[]') INTO v FROM generate_series(1,coalesce((f->>'minimumRows')::integer,0));END IF;
   IF jsonb_typeof(v)='array' THEN SELECT coalesce(jsonb_agg(erp_customer_private.normalize_values(f->'fields',x,depth+1)),'[]') INTO arr FROM jsonb_array_elements(v) x;v:=arr;END IF;
  END IF;
  IF v IS NOT NULL THEN normalized:=jsonb_set(normalized,ARRAY[f->>'id'],v);END IF;
 END LOOP;RETURN normalized;
END $function$

CREATE OR REPLACE FUNCTION erp_customer_private.save(c uuid, input jsonb, request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
DECLARE p public.bf_parties;old public.erp_customer_profiles;cfg jsonb;code text;n bigint;v jsonb;k text;fields jsonb;result jsonb;sid uuid;BEGIN
 SELECT * INTO p FROM public.bf_parties WHERE cafe_id=c AND id=(input->>'id')::uuid FOR UPDATE;
 IF p.id IS NOT NULL AND p.kind<>'customer' THEN RAISE EXCEPTION 'السجل ليس عميلًا';END IF;
 PERFORM erp_customer_private.authorize(c,CASE WHEN p.id IS NULL THEN 'create' ELSE 'update' END);
 SELECT * INTO old FROM public.erp_customer_profiles WHERE cafe_id=c AND id=(input->>'id')::uuid FOR UPDATE;
 IF coalesce(old.revision,0) IS DISTINCT FROM (input->>'revision')::integer OR (p.id IS NOT NULL AND erp_customer_private.fingerprint(p) IS DISTINCT FROM input->>'fingerprint') THEN RAISE EXCEPTION 'تغيرت بيانات العميل أعد تحميلها' USING ERRCODE='40001';END IF;
 IF length(btrim(input->>'name')) NOT BETWEEN 1 AND 150 OR length(coalesce(input->>'phone',''))>30 OR length(coalesce(input->>'email',''))>250 OR jsonb_typeof(input->'active') IS DISTINCT FROM 'boolean' OR jsonb_typeof(input->'categories') IS DISTINCT FROM 'array' OR jsonb_array_length(input->'categories')>50 OR jsonb_typeof(input->'customValues') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'راجع بيانات العميل';END IF;
 IF nullif(input->>'email','') IS NOT NULL AND input->>'email'!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'البريد الإلكتروني غير صالح';END IF;
 SELECT erp_customer_private.defaults()||coalesce((SELECT payload FROM public.erp_customer_settings WHERE cafe_id=c),'{}') INTO cfg;
 IF cfg->>'customerType'<>'both' AND cfg->>'customerType' IS DISTINCT FROM input#>>'{details,customerType}' THEN RAISE EXCEPTION 'نوع العميل يخالف إعدادات العلامة';END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(input->'categories') LOOP PERFORM erp_customer_private.assert_catalog(c,(v#>>'{}')::uuid,'category');END LOOP;
 PERFORM erp_customer_private.assert_catalog(c,nullif(input->>'statusId','')::uuid,'status');
 IF nullif(input->>'assignedUserId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_staff WHERE cafe_id=c AND user_id=(input->>'assignedUserId')::uuid AND active) THEN RAISE EXCEPTION 'الموظف غير نشط';END IF;
 IF nullif(input->>'birthDate','') IS NOT NULL THEN PERFORM (input->>'birthDate')::date;END IF;
 IF input->>'gender' NOT IN('','male','female') OR length(coalesce(input->>'barcode',''))>100 OR (nullif(input->>'website','') IS NOT NULL AND input->>'website'!~'^https?://[^[:space:]]+$') OR (input->'location'<>'null'::jsonb AND (jsonb_typeof(input->'location')<>'object' OR abs((input#>>'{location,latitude}')::numeric)>90 OR abs((input#>>'{location,longitude}')::numeric)>180)) OR (input->>'creditLimit')::numeric<0 OR (input->>'creditLimit')::numeric>1e12 OR (input->>'creditDays')::integer NOT BETWEEN 0 AND 3650 THEN RAISE EXCEPTION 'راجع بيانات الهوية والائتمان';END IF;
 IF nullif(input->>'barcode','') IS NOT NULL AND EXISTS(SELECT 1 FROM public.erp_customer_profiles WHERE cafe_id=c AND id<>(input->>'id')::uuid AND payload->>'barcode'=input->>'barcode') THEN RAISE EXCEPTION 'باركود العميل مستخدم بالفعل';END IF;
 IF nullif(input->>'photoId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=c AND record_id=(input->>'id')::uuid AND entity_type='customer_profile' AND id=(input->>'photoId')::uuid AND uploaded AND mime IN('image/jpeg','image/png')) THEN RAISE EXCEPTION 'اختر صورة مرفوعة في ملف العميل';END IF;
 fields:=cfg->'fields';input:=jsonb_set(input,'{customValues}',erp_customer_private.normalize_values(fields,input->'customValues'));PERFORM erp_customer_private.validate_custom_values(fields,input->'customValues',c,(input->>'id')::uuid,'customers');
 code:=btrim(coalesce(input->>'code',''));IF code='' THEN
  IF old.id IS NOT NULL THEN code:=old.code;ELSE n:=(cfg->>'nextNumber')::bigint;LOOP IF n>999999999 THEN RAISE EXCEPTION 'نفد نطاق ترقيم العملاء';END IF;code:=(cfg->>'prefix')||lpad(n::text,greatest(6,length(n::text)),'0');EXIT WHEN NOT EXISTS(SELECT 1 FROM public.erp_customer_profiles WHERE cafe_id=c AND erp_customer_profiles.code=code);n:=n+1;END LOOP;
  INSERT INTO public.erp_customer_settings(cafe_id,payload) VALUES(c,cfg||jsonb_build_object('nextNumber',n+1)) ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload,revision=erp_customer_settings.revision+1;END IF;
 END IF;
 result:=public.brand_finance_save_customer(c,jsonb_build_object('id',input->'id','kind','customer','name',btrim(input->>'name'),'phone',coalesce(input->>'phone',''),'email',coalesce(input->>'email',''),'taxNumber',coalesce(input->>'taxNumber',''),'active',input->'active','details',input->'details'),request);
 INSERT INTO public.erp_customer_profiles(cafe_id,id,code,payload) VALUES(c,(input->>'id')::uuid,code,input-ARRAY['id','revision','fingerprint','code','name','phone','email','taxNumber','active','details']) ON CONFLICT(cafe_id,id) DO UPDATE SET code=excluded.code,payload=excluded.payload,revision=erp_customer_profiles.revision+1,updated_at=now() RETURNING * INTO old;
 RETURN jsonb_build_object('id',old.id,'revision',old.revision,'code',old.code);
END $function$

CREATE OR REPLACE FUNCTION erp_customer_private.validate_custom_values(fields jsonb, vals jsonb, p_cafe uuid DEFAULT NULL::uuid, p_record uuid DEFAULT NULL::uuid, p_kind text DEFAULT NULL::text, depth integer DEFAULT 0, p_draft boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE f jsonb;v jsonb;t text;x jsonb;txt text;tbl text;col text;valid boolean;metric numeric;BEGIN
 IF coalesce(jsonb_typeof(vals),'')<>'object' OR octet_length(vals::text)>262144 OR depth>2 THEN RAISE EXCEPTION 'بيانات الحقول الإضافية غير صالحة';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP
  t:=f->>'type';IF t IN('static','separator') THEN CONTINUE;END IF;
  v:=coalesce(vals->(f->>'id'),f->'defaultValue');
  IF coalesce((f->>'required')::boolean,false) AND NOT p_draft AND (v IS NULL OR v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb OR (t='checkbox' AND v<>'true')) THEN RAISE EXCEPTION 'أكمل الحقل المطلوب: %',f->>'label';END IF;
  IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
  IF t='subform' THEN
   IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>100 OR jsonb_array_length(v)<coalesce((f->>'minimumRows')::integer,0) THEN RAISE EXCEPTION 'عدد صفوف النموذج غير صالح';END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM erp_customer_private.validate_custom_values(f->'fields',x,p_cafe,p_record,p_kind,depth+1,p_draft);END LOOP;CONTINUE;
  END IF;
  IF t='location' THEN
   IF jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'latitude')<>'number' OR jsonb_typeof(v->'longitude')<>'number' OR abs((v->>'latitude')::numeric)>90 OR abs((v->>'longitude')::numeric)>180 THEN RAISE EXCEPTION 'إحداثيات الموقع غير صالحة';END IF;CONTINUE;
  END IF;
  IF (t IN('number','currency') AND jsonb_typeof(v)<>'number') OR (t='checkbox' AND jsonb_typeof(v)<>'boolean') OR (t IN('multiselect','multidynamic') AND jsonb_typeof(v)<>'array') OR (t NOT IN('number','currency','checkbox','multiselect','multidynamic') AND jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'نوع قيمة الحقل غير صالح';END IF;
  txt:=v#>>'{}';
  IF length(txt)>20000 THEN RAISE EXCEPTION 'قيمة الحقل طويلة';END IF;
  IF (t='select' AND NOT(f->'options' @> jsonb_build_array(v))) OR (t='multiselect' AND NOT(f->'options' @> v)) THEN RAISE EXCEPTION 'اختيارات الحقل غير صالحة';END IF;
  IF t='email' AND txt!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'البريد الإلكتروني غير صالح';END IF;
  IF t='url' AND txt!~'^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'الرابط غير صالح';END IF;
  IF t='time' AND txt!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'الوقت غير صالح';END IF;
  IF t='date' THEN IF txt!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'التاريخ غير صالح';END IF;PERFORM txt::date;END IF;
  IF t IN('number','currency','text','textarea','formatted') THEN
   metric:=CASE WHEN t IN('number','currency') THEN txt::numeric ELSE length(txt) END;
   IF metric<nullif(f->>'minimum','')::numeric OR metric>nullif(f->>'maximum','')::numeric THEN RAISE EXCEPTION 'قيمة الحقل خارج الحدود: %',f->>'label';END IF;
  END IF;
  IF t IN('dynamic','multidynamic') THEN
   tbl:=CASE f->>'entity' WHEN 'items' THEN 'bf_items' WHEN 'customers' THEN 'bf_parties' WHEN 'employees' THEN 'bf_staff' WHEN 'warehouses' THEN 'bf_warehouses' WHEN 'accounts' THEN 'bf_accounts' WHEN 'bom' THEN 'erp_mfg_boms' WHEN 'routings' THEN 'erp_mfg_routings' WHEN 'workstations' THEN 'erp_mfg_workstations' WHEN 'orders' THEN 'erp_mfg_orders' WHEN 'sources' THEN 'bf_documents' END;
   IF tbl IS NULL OR p_cafe IS NULL THEN RAISE EXCEPTION 'الكيان المرتبط غير صالح';END IF;col:=CASE WHEN tbl='bf_staff' THEN 'user_id' ELSE 'id' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN t='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND %I=$2)',tbl,col) INTO valid USING p_cafe,(x#>>'{}')::uuid;
    IF NOT valid THEN RAISE EXCEPTION 'القيمة المرتبطة غير موجودة في العلامة';END IF;
   END LOOP;
  END IF;
  IF t IN('file','image') THEN
   IF p_record IS NULL OR to_regclass('public.erp_files') IS NULL THEN RAISE EXCEPTION 'احفظ السجل وأضف المرفق أولًا';END IF;
   EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=$1 AND record_id=$2 AND id=$3 AND entity_type=$4 AND uploaded AND ($5<>''image'' OR mime IN(''image/jpeg'',''image/png'')))' INTO valid USING p_cafe,p_record,txt::uuid,'customer_profile',t;
   IF NOT valid THEN RAISE EXCEPTION 'المرفق غير موجود في هذا السجل';END IF;
  END IF;
  IF coalesce((f->>'unique')::boolean,false) AND depth=0 THEN
   tbl:='erp_customer_profiles';
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id IS DISTINCT FROM $2 AND payload->''customValues''->$3=$4)',tbl) INTO valid USING p_cafe,p_record,f->>'id',v;
   IF valid THEN RAISE EXCEPTION 'قيمة الحقل مستخدمة مسبقًا: %',f->>'label';END IF;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_employee_asset_private.disposed_unit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE a public.erp_employee_assets;BEGIN
 IF NEW.status='disposed' AND OLD.status<>'disposed' THEN SELECT * INTO a FROM public.erp_employee_assets WHERE cafe_id=NEW.cafe_id AND financial_unit_id=NEW.id FOR UPDATE;
 IF FOUND THEN UPDATE public.erp_employee_assets SET status='retired',revision=revision+1,updated_at=now() WHERE cafe_id=a.cafe_id AND id=a.id;
 INSERT INTO public.erp_employee_asset_events(cafe_id,record_id,action,effective_at,note,before_state,after_state,actor_id) SELECT a.cafe_id,a.id,'financial_disposal',now(),'استبعاد الوحدة المرتبطة من الحسابات العامة',to_jsonb(a),to_jsonb(x),auth.uid() FROM public.erp_employee_assets x WHERE cafe_id=a.cafe_id AND id=a.id;END IF;END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_employee_asset_private.sync_unit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE aid uuid;BEGIN
 IF NEW.financial_unit_id IS NULL OR NEW.status='retired' THEN RETURN NEW;END IF;
 UPDATE public.erp_asset_units SET serial=NEW.serial,barcode=NEW.barcode,employee_id=NEW.holder_user_id,employee_profile_id=NEW.holder_employee_id,location_id=NEW.location_id,description=NEW.description WHERE cafe_id=NEW.cafe_id AND id=NEW.financial_unit_id AND ROW(serial,barcode,employee_id,employee_profile_id,location_id,description) IS DISTINCT FROM ROW(NEW.serial,NEW.barcode,NEW.holder_user_id,NEW.holder_employee_id,NEW.location_id,NEW.description) RETURNING asset_id INTO aid;
 IF aid IS NOT NULL THEN UPDATE public.erp_assets a SET payload=jsonb_set(jsonb_set(a.payload,'{individualUnits}','true'),'{units}',(SELECT jsonb_agg(jsonb_build_object('serial',u.serial,'barcode',u.barcode,'employeeId',coalesce(u.employee_id::text,''),'employeeProfileId',coalesce(u.employee_profile_id::text,''),'locationId',coalesce(u.location_id::text,''),'description',u.description) ORDER BY u.unit_index) FROM public.erp_asset_units u WHERE u.cafe_id=a.cafe_id AND u.asset_id=a.id)),revision=revision+1,updated_at=now() WHERE cafe_id=NEW.cafe_id AND id=aid;END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_employee_asset_private.unit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE linked public.erp_employee_assets;BEGIN
 IF NEW.employee_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.employee_id IS DISTINCT FROM OLD.employee_id) AND NOT erp_employee_asset_private.staff(NEW.cafe_id,NEW.employee_id) THEN RAISE EXCEPTION 'الموظف غير متاح في هذه العلامة';END IF;
 IF NEW.employee_profile_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.employee_profile_id IS DISTINCT FROM OLD.employee_profile_id) AND NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=NEW.cafe_id AND id=NEW.employee_profile_id AND active) THEN RAISE EXCEPTION 'ملف الموظف غير متاح لهذه العلامة';END IF;IF TG_OP='UPDATE' THEN SELECT * INTO linked FROM public.erp_employee_assets WHERE cafe_id=NEW.cafe_id AND financial_unit_id=NEW.id;
  IF FOUND AND NEW.status='disposed' AND OLD.status<>'disposed' AND linked.status IN('assigned','maintenance') THEN RAISE EXCEPTION 'أرجع العهدة وأنهِ الصيانة قبل الاستبعاد المحاسبي';END IF;
  IF FOUND AND pg_trigger_depth()=1 AND ROW(NEW.serial,NEW.barcode,NEW.employee_id,NEW.employee_profile_id,NEW.location_id,NEW.description) IS DISTINCT FROM ROW(OLD.serial,OLD.barcode,OLD.employee_id,OLD.employee_profile_id,OLD.location_id,OLD.description) THEN RAISE EXCEPTION 'عدل بيانات الوحدة المرتبطة من عهد الموظفين';END IF;
 END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_employee_asset_private.validate_holder(p_cafe uuid, p_kind text, p_user uuid, p_location uuid, p_assigned timestamp with time zone, p_return date)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ BEGIN
 IF p_kind NOT IN('unassigned','employee','warehouse') OR NOT EXISTS(SELECT 1 FROM public.erp_asset_locations WHERE cafe_id=p_cafe AND id=p_location) THEN RAISE EXCEPTION 'اختر نوع الحفظ والموقع الفعلي';END IF;
 IF p_kind='employee' AND NOT erp_employee_asset_private.staff(p_cafe,p_user) THEN RAISE EXCEPTION 'الموظف غير متاح في هذه العلامة';END IF;
 IF p_assigned IS NOT NULL AND (NOT isfinite(p_assigned) OR p_assigned>now()+interval '5 minutes') THEN RAISE EXCEPTION 'تاريخ التعيين غير صالح';END IF;
 IF p_return IS NOT NULL AND (NOT isfinite(p_return) OR p_return<(coalesce(p_assigned,now()) AT TIME ZONE 'Asia/Riyadh')::date) THEN RAISE EXCEPTION 'تاريخ الإرجاع المتوقع يسبق التعيين';END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_employee_asset_private.validate_holder_profile(p_cafe uuid, p_kind text, p_user uuid, p_location uuid, p_assigned timestamp with time zone, p_return date, p_employee uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$ BEGIN
 IF p_kind='employee' AND p_employee IS NOT NULL THEN
  IF p_user IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=p_employee AND active) THEN RAISE EXCEPTION 'اختر ملف موظف نشطًا من العلامة دون دمجه مع حساب آخر';END IF;
  PERFORM erp_employee_asset_private.validate_holder(p_cafe,'warehouse',null,p_location,p_assigned,p_return);
 ELSE
  IF p_employee IS NOT NULL OR p_kind<>'employee' AND p_user IS NOT NULL THEN RAISE EXCEPTION 'حدد موظفًا فقط للعهدة المخصصة إلى موظف';END IF;
  PERFORM erp_employee_asset_private.validate_holder(p_cafe,p_kind,p_user,p_location,p_assigned,p_return);
 END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_file_private.assert_record(p_cafe uuid, p_type text, p_record uuid, p_write boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE e public.erp_customer_form_entries;cfg jsonb;BEGIN
 IF p_type<>'customer_form_entry' THEN PERFORM erp_file_private.assert_record_before_customer_forms(p_cafe,p_type,p_record,p_write);RETURN;END IF;
 PERFORM erp_branch_private.enter(p_cafe);e:=erp_customer_form_private.assert_entry(p_cafe,p_record,CASE WHEN p_write THEN 'update' ELSE 'read' END);
 SELECT config INTO cfg FROM public.erp_customer_forms WHERE cafe_id=p_cafe AND id=e.model_id;
 IF cardinality(erp_customer_form_private.fields(p_cafe,cfg,'read'))<>jsonb_array_length(cfg->'fields') OR (p_write AND NOT coalesce((cfg->>'active')::boolean,false)) THEN RAISE EXCEPTION 'المرفقات غير متاحة لهذا النطاق' USING ERRCODE='42501';END IF;
 PERFORM erp_access_private.assert_allowed(p_cafe,'customers',CASE WHEN p_write THEN 'files' ELSE 'read' END);
END $function$

CREATE OR REPLACE FUNCTION erp_file_private.assert_record_before_accounting(p_cafe uuid, p_type text, p_record uuid, p_write boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE present boolean;BEGIN
 IF p_type<>'customer_profile' THEN PERFORM erp_file_private.assert_record_before_customers(p_cafe,p_type,p_record,p_write);RETURN;END IF;
 PERFORM erp_customer_private.authorize(p_cafe,CASE WHEN p_write THEN 'files' ELSE 'read' END);
 IF p_write THEN SELECT true INTO present FROM public.bf_parties WHERE cafe_id=p_cafe AND id=p_record AND kind='customer' FOR KEY SHARE;ELSE SELECT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=p_record AND kind='customer') INTO present;END IF;
 IF NOT coalesce(present,false) THEN RAISE EXCEPTION 'ملف العميل غير متاح' USING ERRCODE='42501';END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_file_private.assert_record_before_attendance(p_cafe uuid, p_type text, p_record uuid, p_write boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN
 IF p_type IS DISTINCT FROM 'work_order' THEN PERFORM erp_file_private.assert_record_before_work_orders(p_cafe,p_type,p_record,p_write);RETURN;END IF;
 PERFORM erp_work_private.authorize(p_cafe,p_write,CASE WHEN p_write THEN 'files' ELSE 'read' END);
 IF p_write THEN PERFORM 1 FROM public.erp_work_orders WHERE cafe_id=p_cafe AND id=p_record FOR KEY SHARE;ELSE PERFORM 1 FROM public.erp_work_orders WHERE cafe_id=p_cafe AND id=p_record;END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'أمر الشغل غير متاح' USING ERRCODE='42501';END IF;
END$function$

CREATE OR REPLACE FUNCTION erp_file_private.assert_record_before_branch_scope(p_cafe uuid, p_type text, p_record uuid, p_write boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$BEGIN
 IF p_type<>'branch' THEN PERFORM erp_file_private.assert_record_before_branches(p_cafe,p_type,p_record,p_write);RETURN;END IF;
 PERFORM erp_branch_private.authorize(p_cafe,CASE WHEN p_write THEN 'files' ELSE 'read' END);
