CREATE OR REPLACE FUNCTION erp_file_private.assert_record_before_workflows(p_cafe uuid, p_type text, p_record uuid, p_write boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text;employee uuid;state text;approvers jsonb;present boolean:=false;BEGIN
 IF p_type NOT IN('attendance_leave','attendance_sheet','attendance_session') THEN PERFORM erp_file_private.assert_record_before_attendance(p_cafe,p_type,p_record,p_write);RETURN;END IF;
 r:=erp_attendance_private.authorize(p_cafe);PERFORM erp_attendance_private.access(p_cafe,'files');
 IF p_type='attendance_leave' THEN
  IF p_write THEN SELECT true,employee_id,status,approval_snapshot INTO present,employee,state,approvers FROM public.erp_att_leaves WHERE cafe_id=p_cafe AND id=p_record FOR KEY SHARE;ELSE SELECT true,employee_id,status,approval_snapshot INTO present,employee,state,approvers FROM public.erp_att_leaves WHERE cafe_id=p_cafe AND id=p_record;END IF;
 ELSIF p_type='attendance_session' THEN
  IF p_write THEN SELECT true,employee_id,status INTO present,employee,state FROM public.erp_att_sessions WHERE cafe_id=p_cafe AND id=p_record FOR KEY SHARE;ELSE SELECT true,employee_id,status INTO present,employee,state FROM public.erp_att_sessions WHERE cafe_id=p_cafe AND id=p_record;END IF;
 ELSE IF p_write THEN SELECT true,status INTO present,state FROM public.erp_att_sheets WHERE cafe_id=p_cafe AND id=p_record FOR KEY SHARE;ELSE SELECT true,status INTO present,state FROM public.erp_att_sheets WHERE cafe_id=p_cafe AND id=p_record;END IF;END IF;
 IF NOT coalesce(present,false) THEN RAISE EXCEPTION 'سجل مرفقات الحضور غير متاح' USING ERRCODE='42501';END IF;
 IF r='self' OR (p_write AND r NOT IN('owner','manager') AND EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=employee AND user_id=auth.uid() AND active)) THEN
  IF NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=employee AND user_id=auth.uid() AND active) AND (p_write OR NOT coalesce(approvers @> jsonb_build_array(jsonb_build_object('users',jsonb_build_array(auth.uid()::text))),false)) THEN RAISE EXCEPTION 'السجل لا يخص الموظف الحالي' USING ERRCODE='42501';END IF;
  IF p_write AND state NOT IN('draft','pending','open') THEN RAISE EXCEPTION 'المرفقات للقراءة بعد إغلاق السجل' USING ERRCODE='42501';END IF;
 ELSIF p_write AND r NOT IN('owner','manager') THEN RAISE EXCEPTION 'لا تملك صلاحية تعديل مرفقات الحضور' USING ERRCODE='42501';END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.before_treasury_execute(p_cafe_id uuid, p_operation text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); r text; prior public.bf_requests%ROWTYPE; a public.bf_accounts%ROWTYPE; b public.bf_accounts%ROWTYPE;
 aid uuid; other_id uuid; doc uuid:=gen_random_uuid(); n bigint; amount numeric; fee numeric; counted numeric; balance numeric; note text; result jsonb; before_row jsonb; k text; linked uuid; category text; subcategory text; center text; fee_mode text; due numeric;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_treasury_execute',p_operation);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 r:=brand_finance_private.role_for(p_cafe_id);
 IF r NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Finance manager required' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000 OR p_payload::text ~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'Invalid command'; END IF;
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.operation<>'treasury:'||p_operation OR prior.payload<>p_payload OR prior.created_by<>actor THEN RAISE EXCEPTION 'Request identifier conflict'; END IF;
  RETURN prior.result||'{"duplicate":true}'::jsonb;
 END IF;
 IF p_operation<>'account_primary' THEN PERFORM brand_finance_private.treasury_seed(p_cafe_id); END IF;
 IF p_operation<>'account_primary' AND EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe_id AND closed_through>=(now() AT TIME ZONE 'Asia/Riyadh')::date) THEN RAISE EXCEPTION 'الفترة المالية مقفلة'; END IF;
 IF p_operation='account_save' AND p_payload ? 'monthlyDueDay' THEN
  IF jsonb_typeof(p_payload->'monthlyDueDay') IS DISTINCT FROM 'number' OR (p_payload->>'monthlyDueDay')::numeric NOT BETWEEN 1 AND 31 OR (p_payload->>'monthlyDueDay')::numeric<>trunc((p_payload->>'monthlyDueDay')::numeric) THEN RAISE EXCEPTION 'اختر يوم استحقاق صحيحا من ١ إلى ٣١'; END IF;
  -- Preserve prior-month rates, but never accrue this terminal's current month under its replaced day
  PERFORM brand_finance_private.terminal_monthly_ensure_at(p_cafe_id,brand_finance_private.terminal_monthly_today(),(SELECT id FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=nullif(p_payload->>'id','')::uuid AND monthly_due_day<>(p_payload->>'monthlyDueDay')::numeric));
 ELSIF p_operation<>'account_primary' THEN
  PERFORM brand_finance_private.terminal_monthly_ensure(p_cafe_id);
 END IF;
 note:=btrim(coalesce(p_payload->>'note',''));
 IF length(note)>1000 THEN RAISE EXCEPTION 'Note too long'; END IF;
 aid:=nullif(p_payload->>'accountId','')::uuid;
 IF p_operation='account_save' THEN aid:=nullif(p_payload->>'id','')::uuid; END IF;
 IF aid IS NOT NULL THEN
  SELECT * INTO a FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=aid;
  IF NOT FOUND OR a.deleted_at IS NOT NULL OR a.kind NOT IN('cash','bank','pos') THEN RAISE EXCEPTION 'Invalid treasury account'; END IF;
  before_row:=to_jsonb(a)-'cafe_id';
 END IF;
 IF p_operation='account_save' THEN
  k:=p_payload->>'kind'; linked:=nullif(p_payload->>'linkedBankId','')::uuid;
  IF p_payload ? 'cashierDrawer' THEN
   IF jsonb_typeof(p_payload->'cashierDrawer') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'نوع صندوق الكاشير غير صالح'; END IF;
   IF (p_payload->>'cashierDrawer')::boolean AND k<>'cash' THEN RAISE EXCEPTION 'صندوق الكاشير حساب نقدي مستقل'; END IF;
   IF aid IS NOT NULL AND (p_payload->>'cashierDrawer')::boolean IS DISTINCT FROM a.is_cashier_drawer THEN RAISE EXCEPTION 'نوع صندوق الكاشير ثابت'; END IF;
  END IF;

  IF k NOT IN('cash','bank','pos') OR length(btrim(coalesce(p_payload->>'name',''))) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid treasury account'; END IF;
  IF k='pos' AND linked IS NULL THEN RAISE EXCEPTION 'اختر البنك المرتبط بنقطة الشبكة'; END IF;
  IF k<>'pos' AND linked IS NOT NULL THEN RAISE EXCEPTION 'Only POS accounts can link a bank'; END IF;
  IF aid IS NULL THEN
   aid:=gen_random_uuid();
   INSERT INTO public.bf_accounts(id,cafe_id,name,code,kind,linked_bank_id,bank_name,iban,terminal_id,is_cashier_drawer)
   VALUES(aid,p_cafe_id,btrim(p_payload->>'name'),'T-'||replace(aid::text,'-',''),k,linked,coalesce(p_payload->>'bankName',''),upper(replace(coalesce(p_payload->>'iban',''),' ','')),coalesce(p_payload->>'terminalId',''),coalesce((p_payload->>'cashierDrawer')::boolean,false));
  ELSE
   IF a.kind<>k OR NOT a.active OR p_payload ? 'openingAmount' THEN RAISE EXCEPTION 'الرصيد الافتتاحي يسجل من إجراء مستقل لمرة واحدة'; END IF;
   UPDATE public.bf_accounts SET name=btrim(p_payload->>'name'),linked_bank_id=linked,bank_name=coalesce(p_payload->>'bankName',''),iban=upper(replace(coalesce(p_payload->>'iban',''),' ','')),terminal_id=coalesce(p_payload->>'terminalId','') WHERE id=aid;
  END IF;
  IF k<>'pos' AND ((p_payload ? 'transactionFeePercent') OR (p_payload ? 'monthlySubscription') OR (p_payload ? 'feeVatRate') OR (p_payload ? 'monthlyDueDay')) THEN RAISE EXCEPTION 'إعدادات الرسوم متاحة لنقاط الشبكة فقط'; END IF;
  IF k='pos' THEN
   UPDATE public.bf_accounts SET transaction_fee_percent=coalesce((p_payload->>'transactionFeePercent')::numeric,transaction_fee_percent),
    monthly_subscription=coalesce((p_payload->>'monthlySubscription')::numeric,monthly_subscription),
    fee_vat_rate=coalesce((p_payload->>'feeVatRate')::numeric,fee_vat_rate),
    monthly_due_day=coalesce((p_payload->>'monthlyDueDay')::numeric::smallint,monthly_due_day),
    fee_started_month=CASE WHEN coalesce((p_payload->>'monthlySubscription')::numeric,monthly_subscription)>0 THEN coalesce(fee_started_month,date_trunc('month',brand_finance_private.terminal_monthly_today())::date) ELSE NULL END
   WHERE id=aid;
   PERFORM brand_finance_private.terminal_monthly_ensure(p_cafe_id);
  END IF;
  IF p_payload ? 'openingAmount' THEN
   amount:=round((p_payload->>'openingAmount')::numeric,2);
   IF amount IS NULL OR amount<0 THEN RAISE EXCEPTION 'Invalid opening amount'; END IF;
   UPDATE public.bf_accounts SET opening_recorded_at=now(),opening_amount=amount WHERE id=aid;
   INSERT INTO public.bf_documents(id,cafe_id,kind,account_id,total,paid,note,created_by) VALUES(doc,p_cafe_id,'opening',aid,amount,amount,note,actor) RETURNING number INTO n;
   PERFORM brand_finance_private.line(p_cafe_id,doc,aid,amount,0);
   PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'3000'),0,amount);
   INSERT INTO public.bf_treasury_documents(cafe_id,document_id,operation) VALUES(p_cafe_id,doc,'opening');
  END IF;
  result:=jsonb_build_object('id',aid,'document_id',CASE WHEN n IS NOT NULL THEN doc ELSE NULL END,'number',n);
 ELSIF p_operation='account_primary' THEN
  IF aid IS NULL OR NOT a.active THEN RAISE EXCEPTION 'اختر حسابا نشطا ليكون الحساب الرئيسي'; END IF;
  SELECT id INTO linked FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND kind=a.kind AND active AND is_primary;
  before_row:=before_row||jsonb_build_object('previous_primary_id',linked);
  IF linked IS DISTINCT FROM aid THEN
   UPDATE public.bf_accounts SET is_primary=false WHERE cafe_id=p_cafe_id AND kind=a.kind AND is_primary;
   UPDATE public.bf_accounts SET is_primary=true WHERE cafe_id=p_cafe_id AND id=aid;
  END IF;
  result:=jsonb_build_object('id',aid,'previous_primary_id',linked);
 ELSIF p_operation='account_delete' THEN
  IF aid IS NULL OR NOT brand_finance_private.can_delete_cash(p_cafe_id,aid) THEN
   RAISE EXCEPTION 'لا يمكن حذف خزينة رئيسية أو أساسية أو خزينة لها حركات أو ورديات أو ارتباطات';
  END IF;
  UPDATE public.bf_accounts SET active=false,deleted_at=now() WHERE id=aid AND cafe_id=p_cafe_id;
  result:=jsonb_build_object('id',aid,'deleted',true);
 ELSIF p_operation='account_archive' THEN
  IF aid IS NULL OR NOT (p_payload ? 'active') OR jsonb_typeof(p_payload->'active')<>'boolean' THEN RAISE EXCEPTION 'Invalid archive request'; END IF;
  UPDATE public.bf_accounts SET active=(p_payload->>'active')::boolean WHERE id=aid;
  result:=jsonb_build_object('id',aid);
 ELSE
  IF aid IS NULL OR NOT a.active THEN RAISE EXCEPTION 'اختر حسابا نشطا'; END IF;
  balance:=brand_finance_private.treasury_balance(p_cafe_id,aid);
  amount:=round((p_payload->>'amount')::numeric,2);
  IF p_operation='reconcile' THEN
   counted:=round((p_payload->>'countedAmount')::numeric,2);
   IF counted IS NULL OR counted<0 OR (p_payload->>'expectedBalance')::numeric IS DISTINCT FROM balance THEN RAISE EXCEPTION 'تغير الرصيد حدث البيانات ثم أعد المطابقة'; END IF;
   INSERT INTO public.bf_treasury_reconciliations(id,cafe_id,account_id,expected_amount,counted_amount,note,created_by) VALUES(doc,p_cafe_id,aid,balance,counted,note,actor);
   result:=jsonb_build_object('id',doc,'difference',counted-balance);
  ELSE
   IF amount IS NULL OR amount<0 OR (p_operation NOT IN('opening','pos_settle','pos_fee_pay') AND amount=0) THEN RAISE EXCEPTION 'Invalid amount'; END IF;
   IF p_operation='opening' THEN
    IF a.opening_recorded_at IS NOT NULL OR EXISTS(SELECT 1 FROM public.bf_journal WHERE cafe_id=p_cafe_id AND account_id=aid) OR EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND account_id=aid AND status IN('open','handover')) THEN RAISE EXCEPTION 'سبق بدء الحساب ولا يمكن تكرار الرصيد الافتتاحي'; END IF;
    UPDATE public.bf_accounts SET opening_recorded_at=now(),opening_amount=amount WHERE id=aid;
    k:='opening'; other_id:=brand_finance_private.account(p_cafe_id,'3000');
   ELSIF p_operation='voucher' THEN
    k:=p_payload->>'kind'; other_id:=nullif(p_payload->>'counterAccountId','')::uuid;
    category:=coalesce(p_payload->>'category',''); subcategory:=coalesce(p_payload->>'subcategory',''); center:=btrim(coalesce(p_payload->>'costCenter',''));
    IF length(center)>100 THEN RAISE EXCEPTION 'اسم مركز التكلفة يجب ألا يتجاوز مئة حرف'; END IF;
    IF category<>'' THEN
     IF NOT ((k='receipt' AND category IN('other_income','owner_funding')) OR (k='expense' AND category IN('operating_expense','owner_draw'))) THEN RAISE EXCEPTION 'اختر تصنيفا مناسبا لسند القبض أو الصرف'; END IF;
     IF subcategory<>'' AND (category<>'operating_expense' OR subcategory NOT IN('rent','utilities','maintenance','wages','other')) THEN RAISE EXCEPTION 'اختر تصنيفا فرعيا صحيحا للمصروف التشغيلي'; END IF;
     PERFORM brand_finance_private.terminal_fee_seed(p_cafe_id);
     linked:=brand_finance_private.account(p_cafe_id,CASE category WHEN 'other_income' THEN '4010' WHEN 'owner_funding' THEN '3000' WHEN 'owner_draw' THEN '3010' ELSE '5100' END);
     IF other_id IS NOT NULL AND other_id<>linked THEN RAISE EXCEPTION 'الحساب المقابل لا يطابق تصنيف السند'; END IF;
     other_id:=linked;
    ELSIF subcategory<>'' THEN RAISE EXCEPTION 'اختر تصنيف السند قبل التصنيف الفرعي'; END IF;
    IF k NOT IN('receipt','expense') OR a.kind='pos' OR length(note)<3 OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=other_id AND active AND kind IN('revenue','expense','equity')) THEN RAISE EXCEPTION 'اختر الحساب المقابل واكتب بيان السند'; END IF;
    IF k='expense' AND balance<amount THEN RAISE EXCEPTION 'الرصيد غير كاف'; END IF;
   ELSIF p_operation='transfer' THEN
    k:='transfer'; other_id:=nullif(p_payload->>'toAccountId','')::uuid;
    IF a.kind NOT IN('cash','bank') OR other_id=aid OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=other_id AND active AND kind IN('cash','bank')) OR balance<amount OR length(note)<3 THEN RAISE EXCEPTION 'تحقق من حسابي التحويل والرصيد والبيان'; END IF;
   ELSIF p_operation IN('pos_settle','pos_fee_pay') THEN
    k:='transfer'; other_id:=a.linked_bank_id; fee_mode:=coalesce(p_payload->>'feeTreatment','legacy');
    due:=brand_finance_private.terminal_fees_due(p_cafe_id,aid);
    IF fee_mode NOT IN('legacy','net','gross') THEN RAISE EXCEPTION 'اختر طريقة إيداع البنك بالإجمالي أو بالصافي'; END IF;
    fee:=round(coalesce((p_payload->>'feesDeducted')::numeric,CASE WHEN p_operation='pos_fee_pay' THEN amount ELSE NULL END,(p_payload->>'fee')::numeric,0),2);
    IF a.kind<>'pos' OR other_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=other_id AND kind='bank' AND active) OR fee<0 OR length(btrim(coalesce(p_payload->>'reference',''))) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'تحقق من نقطة الشبكة والبنك المرتبط ومرجع العملية'; END IF;
    IF p_operation='pos_fee_pay' THEN
     IF (p_payload ? 'feesDeducted' AND round((p_payload->>'feesDeducted')::numeric,2) IS DISTINCT FROM amount) OR (p_payload ? 'fee' AND round((p_payload->>'fee')::numeric,2) IS DISTINCT FROM amount) THEN RAISE EXCEPTION 'مبلغ سداد الرسوم لا يطابق المبلغ المدخل'; END IF;
     fee:=amount; fee_mode:='net'; amount:=0;
     IF fee<=0 OR fee>due OR brand_finance_private.treasury_balance(p_cafe_id,other_id)<fee THEN RAISE EXCEPTION 'تحقق من مبلغ الرسوم المستحقة ورصيد البنك المتاح للسداد'; END IF;
    ELSE
     IF amount<=0 OR balance<amount OR fee>amount THEN RAISE EXCEPTION 'مبلغ التسوية يجب ألا يتجاوز رصيد الشبكة والرسوم يجب ألا تتجاوز التسوية'; END IF;
     IF fee_mode='gross' AND fee<>0 THEN RAISE EXCEPTION 'الإيداع بالإجمالي لا يتضمن خصم رسوم من المبلغ المودع'; END IF;
     IF fee_mode<>'legacy' AND fee>due THEN RAISE EXCEPTION 'الرسوم المخصومة تتجاوز الرسوم المستحقة على الشبكة'; END IF;
     IF fee_mode='legacy' AND (due>0 OR a.transaction_fee_percent>0 OR a.monthly_subscription>0 OR p_payload ? 'feesDeducted') THEN RAISE EXCEPTION 'اختر الإيداع بالإجمالي أو بالصافي لتجنب خصم الرسوم مرتين'; END IF;
    END IF;
    IF EXISTS(SELECT 1 FROM public.bf_treasury_documents WHERE cafe_id=p_cafe_id AND account_id=aid AND operation IN('pos_settle','pos_fee_pay') AND reference=btrim(p_payload->>'reference')) THEN RAISE EXCEPTION 'سبق تسجيل مرجع البنك لهذه الشبكة'; END IF;
   ELSE RAISE EXCEPTION 'Unknown treasury operation'; END IF;
   INSERT INTO public.bf_documents(id,cafe_id,kind,account_id,total,paid,note,created_by) VALUES(doc,p_cafe_id,k,aid,CASE WHEN p_operation='pos_fee_pay' THEN fee ELSE amount END,CASE WHEN p_operation='pos_fee_pay' THEN fee ELSE amount END,note,actor) RETURNING number INTO n;
   IF p_operation='pos_fee_pay' THEN
    PERFORM brand_finance_private.line(p_cafe_id,doc,other_id,0,fee);
    PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'2010'),fee,0);
    PERFORM brand_finance_private.terminal_fee_allocate(p_cafe_id,aid,doc,fee);
   ELSIF p_operation='pos_settle' AND fee_mode<>'legacy' THEN
    PERFORM brand_finance_private.line(p_cafe_id,doc,aid,0,amount);
    PERFORM brand_finance_private.line(p_cafe_id,doc,other_id,amount-fee,0);
    IF fee>0 THEN
     PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'2010'),fee,0);
     PERFORM brand_finance_private.terminal_fee_allocate(p_cafe_id,aid,doc,fee);
    END IF;
   ELSIF k IN('opening','receipt') THEN
    PERFORM brand_finance_private.line(p_cafe_id,doc,aid,amount,0); PERFORM brand_finance_private.line(p_cafe_id,doc,other_id,0,amount);
   ELSE
    PERFORM brand_finance_private.line(p_cafe_id,doc,aid,0,amount); PERFORM brand_finance_private.line(p_cafe_id,doc,other_id,amount-coalesce(fee,0),0);
    IF coalesce(fee,0)>0 THEN PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'5100'),fee,0); END IF;
   END IF;
   INSERT INTO public.bf_treasury_documents(cafe_id,document_id,account_id,operation,reference,fee,category,subcategory,cost_center) VALUES(p_cafe_id,doc,aid,p_operation,btrim(coalesce(p_payload->>'reference','')),coalesce(fee,0),coalesce(category,''),coalesce(subcategory,''),coalesce(center,''));
   result:=jsonb_build_object('id',doc,'number',n);
  END IF;
 END IF;
 INSERT INTO public.bf_treasury_audit(cafe_id,actor_id,operation,entity_id,before_data,after_data)
 VALUES(p_cafe_id,actor,p_operation,(result->>'id')::uuid,before_row,CASE WHEN p_operation IN('account_save','account_archive','account_primary','opening') THEN (SELECT to_jsonb(x)-'cafe_id' FROM public.bf_accounts x WHERE id=aid) ELSE p_payload||result END);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'treasury:'||p_operation,p_payload,result,actor);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.before_treasury_history(p_cafe_id uuid, p_account_id uuid, p_kind text, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; result jsonb;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_treasury_history',NULL);
 r:=brand_finance_private.role_for(p_cafe_id);
 IF r NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Finance manager required' USING ERRCODE='42501'; END IF;
 IF p_offset IS NULL OR p_offset<0 OR p_kind IS NULL OR p_kind NOT IN('audit','reconciliations') OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=p_account_id) THEN RAISE EXCEPTION 'Invalid account history'; END IF;
 IF p_kind='reconciliations' THEN
  WITH selected AS (
   SELECT rec.id,rec.account_id,rec.expected_amount expected_balance,rec.counted_amount,rec.difference variance,rec.note,rec.created_at,
    brand_finance_private.treasury_actor_name(p_cafe_id,rec.created_by) actor_name,s.document_id adjustment_document_id
   FROM public.bf_treasury_reconciliations rec LEFT JOIN public.bf_treasury_reconciliation_resolutions s ON s.cafe_id=rec.cafe_id AND s.reconciliation_id=rec.id
   WHERE rec.cafe_id=p_cafe_id AND rec.account_id=p_account_id
  ), page AS (SELECT * FROM selected ORDER BY created_at DESC,id DESC OFFSET p_offset LIMIT 100)
  SELECT jsonb_build_object('total',(SELECT count(*) FROM selected),'rows',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC,p.id DESC) FROM page p),'[]'::jsonb)) INTO result;
 ELSE
  WITH selected AS (
   SELECT au.id,p_account_id account_id,au.operation,coalesce(au.after_data->>'reason',au.after_data->>'note','') note,au.created_at,
    brand_finance_private.treasury_actor_name(p_cafe_id,au.actor_id) actor_name,d.id document_id
   FROM public.bf_treasury_audit au LEFT JOIN public.bf_documents d ON d.cafe_id=au.cafe_id AND d.id=au.entity_id
   WHERE au.cafe_id=p_cafe_id AND (
    (au.operation IN('account_save','account_archive','account_primary','opening') AND au.after_data->>'id'=p_account_id::text)
    OR au.after_data->>'accountId'=p_account_id::text OR au.after_data->>'toAccountId'=p_account_id::text
    OR EXISTS(SELECT 1 FROM public.bf_journal j WHERE j.cafe_id=p_cafe_id AND j.document_id=au.entity_id AND j.account_id=p_account_id))
  ), page AS (SELECT * FROM selected ORDER BY created_at DESC,id DESC OFFSET p_offset LIMIT 100)
  SELECT jsonb_build_object('total',(SELECT count(*) FROM selected),'rows',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC,p.id DESC) FROM page p),'[]'::jsonb)) INTO result;
 END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.cash_account(c uuid, i uuid, needed numeric DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$BEGIN
 PERFORM erp_asset_private.account(c,i,ARRAY['cash','bank']);
 IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=c AND account_id=i AND status IN('open','handover')) THEN RAISE EXCEPTION 'اختر خزينة غير مرتبطة بوردية مفتوحة أو بانتظار التسليم';END IF;
 IF needed>0 AND erp_finance_private.balance(c,i)<needed THEN RAISE EXCEPTION 'رصيد الخزينة لا يكفي';END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.custody_act(c uuid, action text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE custody public.erp_finance_custodies;movement public.erp_finance_custody_movements;account uuid;doc uuid;mid uuid:=gen_random_uuid();amount numeric;total numeric;calculation jsonb;l jsonb;cfg jsonb;employee_name text;d date:=(p->>'date')::date;BEGIN
 SELECT * INTO custody FROM public.erp_finance_custodies WHERE cafe_id=c AND id=(p->>'id')::uuid FOR UPDATE;IF NOT FOUND OR custody.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت العهدة أعد تحميلها' USING ERRCODE='40001';END IF;
 SELECT payload INTO cfg FROM public.erp_finance_settings WHERE cafe_id=c;
 IF action='fund' THEN
  IF custody.status<>'draft' THEN RAISE EXCEPTION 'العهدة مصروفة أو مغلقة';END IF;d:=(custody.payload->>'date')::date;amount:=round((custody.payload->>'amount')::numeric*(custody.payload->>'exchangeRate')::numeric,2);account:=(custody.payload->>'cashAccountId')::uuid;
  PERFORM erp_finance_private.validate_custody_fields(coalesce(cfg->'custodyFields','[]'),coalesce(custody.payload->'customValues','{}'),c,custody.id,'custody');PERFORM erp_finance_private.cash_account(c,account,amount);
  SELECT first_name||' '||last_name INTO employee_name FROM public.erp_hr_employees WHERE cafe_id=c AND id=custody.employee_id AND active;IF NOT FOUND THEN RAISE EXCEPTION 'الموظف غير نشط';END IF;
  custody.account_id:=gen_random_uuid();INSERT INTO public.bf_accounts(id,cafe_id,code,name,kind) VALUES(custody.account_id,c,'ERP-CUSTODY-'||custody.id::text,left(employee_name||' — '||custody.code,100),'employee');
  doc:=erp_finance_private.document(c,'transfer',d,amount,'صرف عهدة '||custody.code,account);PERFORM erp_asset_private.line(c,doc,account,0,amount);PERFORM erp_asset_private.line(c,doc,custody.account_id,amount,0);
  UPDATE public.erp_finance_custodies SET status='active',account_id=custody.account_id,funding_id=doc,revision=revision+1 WHERE cafe_id=c AND id=custody.id;
 ELSIF action='cancel_custody' THEN
  IF custody.status<>'draft' THEN RAISE EXCEPTION 'إلغاء العهدة متاح قبل صرفها فقط';END IF;UPDATE public.erp_finance_custodies SET status='cancelled',revision=revision+1 WHERE cafe_id=c AND id=custody.id;
 ELSIF action='close_custody' THEN
  IF custody.status<>'active' OR erp_finance_private.balance(c,custody.account_id)<>0 THEN RAISE EXCEPTION 'سو العهدة وأعد الرصيد المتبقي قبل إغلاقها';END IF;UPDATE public.erp_finance_custodies SET status='closed',revision=revision+1 WHERE cafe_id=c AND id=custody.id;
 ELSE
  IF custody.status<>'active' THEN RAISE EXCEPTION 'العهدة ليست نشطة';END IF;PERFORM erp_asset_private.date_open(c,d);IF d<(custody.payload->>'date')::date THEN RAISE EXCEPTION 'تاريخ التسوية يسبق صرف العهدة';END IF;
  IF action='settle_custody' THEN
   IF NOT EXISTS(SELECT 1 FROM public.erp_finance_categories WHERE cafe_id=c AND id=(p->>'typeId')::uuid AND kind='settlement' AND active) THEN RAISE EXCEPTION 'اختر نوع تسوية نشطًا';END IF;
   calculation:=erp_finance_private.validate_voucher(c,'expense',p||jsonb_build_object('kind','expense','code',custody.code,'cashAccountId',custody.payload->'cashAccountId','currency',custody.payload->'currency','exchangeRate',custody.payload->'exchangeRate','note',coalesce(nullif(p->>'note',''),'تسوية عهدة'),'partyId',NULL,'categoryId',NULL));amount:=(calculation->>'total')::numeric;
   IF erp_finance_private.balance(c,custody.account_id)<amount THEN RAISE EXCEPTION 'التسوية تتجاوز الرصيد المتبقي للعهدة';END IF;
   doc:=erp_finance_private.document(c,'expense',d,amount,'تسوية عهدة '||custody.code,custody.account_id,NULL,(calculation->>'net')::numeric,(calculation->>'tax')::numeric);
   PERFORM erp_asset_private.line(c,doc,custody.account_id,0,amount);FOR l IN SELECT * FROM jsonb_array_elements(calculation->'lines') LOOP PERFORM erp_asset_private.line(c,doc,(l->>'accountId')::uuid,(l->>'net')::numeric,0);END LOOP;
   IF(calculation->>'tax')::numeric>0 THEN PERFORM erp_asset_private.line(c,doc,brand_finance_private.account(c,'1300'),(calculation->>'tax')::numeric,0);END IF;
   INSERT INTO public.erp_finance_custody_movements(cafe_id,id,custody_id,kind,document_id,payload,amount,effective_on,created_by) VALUES(c,mid,custody.id,'settlement',doc,p||jsonb_build_object('calculation',calculation),amount,d,auth.uid());
  ELSIF action='return_custody' THEN
   amount:=round((p->>'amount')::numeric*(custody.payload->>'exchangeRate')::numeric,2);account:=(p->>'cashAccountId')::uuid;
   IF amount IS NULL OR amount<=0 OR amount>erp_finance_private.balance(c,custody.account_id) OR amount='NaN'::numeric OR(p->>'amount')::numeric<>round((p->>'amount')::numeric,2) THEN RAISE EXCEPTION 'راجع مبلغ الإرجاع ورصيد العهدة';END IF;PERFORM erp_finance_private.cash_account(c,account);
   doc:=erp_finance_private.document(c,'transfer',d,amount,'إرجاع عهدة '||custody.code,account);PERFORM erp_asset_private.line(c,doc,account,amount,0);PERFORM erp_asset_private.line(c,doc,custody.account_id,0,amount);
   INSERT INTO public.erp_finance_custody_movements(cafe_id,id,custody_id,kind,document_id,payload,amount,effective_on,created_by) VALUES(c,mid,custody.id,'return',doc,p,amount,d,auth.uid());
  ELSIF action='reverse_custody_movement' THEN
   SELECT * INTO movement FROM public.erp_finance_custody_movements WHERE cafe_id=c AND custody_id=custody.id AND id=(p->>'movementId')::uuid;
   IF NOT FOUND OR movement.kind='reversal' OR EXISTS(SELECT 1 FROM public.erp_finance_custody_movements WHERE cafe_id=c AND reversal_of=movement.id) THEN RAISE EXCEPTION 'الحركة غير قابلة للعكس';END IF;
   total:=erp_finance_private.balance(c,custody.account_id)+movement.amount;IF total>round((custody.payload->>'amount')::numeric*(custody.payload->>'exchangeRate')::numeric,2) THEN RAISE EXCEPTION 'العكس يتجاوز قيمة العهدة المصروفة';END IF;
   doc:=erp_finance_private.reverse_document(c,movement.document_id,d,p->>'note');INSERT INTO public.erp_finance_custody_movements(cafe_id,id,custody_id,kind,document_id,reversal_of,payload,amount,effective_on,created_by) VALUES(c,mid,custody.id,'reversal',doc,movement.id,p,movement.amount,d,auth.uid());
  ELSE RAISE EXCEPTION 'إجراء العهدة غير صالح';END IF;
  UPDATE public.erp_finance_custodies SET revision=revision+1 WHERE cafe_id=c AND id=custody.id;
 END IF;
 PERFORM erp_finance_private.event(c,custody.id,action,jsonb_build_object('documentId',doc,'movementId',mid,'input',p));RETURN jsonb_build_object('id',custody.id,'documentId',doc,'movementId',mid);
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.custody_costs()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE l jsonb;a jsonb;n integer:=0;j integer;remaining numeric;amount numeric;parts jsonb;net numeric;BEGIN
 IF NEW.kind<>'settlement' THEN RETURN NEW;END IF;
 FOR l IN SELECT * FROM jsonb_array_elements(NEW.payload->'lines') LOOP
  parts:=coalesce(l->'costCenters','[]');net:=(NEW.payload->'calculation'->'lines'->n->>'net')::numeric;remaining:=net;j:=0;
  FOR a IN SELECT * FROM jsonb_array_elements(parts) LOOP amount:=CASE WHEN j=jsonb_array_length(parts)-1 THEN remaining ELSE least(remaining,round(net*(a->>'percentage')::numeric/100,2)) END;remaining:=remaining-amount;INSERT INTO public.erp_finance_custody_costs VALUES(NEW.cafe_id,NEW.id,n,(a->>'id')::uuid,amount);j:=j+1;END LOOP;n:=n+1;
 END LOOP;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.generate_schedule(c uuid, i uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE s public.erp_finance_schedules;v public.erp_finance_vouchers;n uuid;d date;next_d date;step interval;BEGIN
 PERFORM erp_finance_private.authorize(c,'create');SELECT * INTO s FROM public.erp_finance_schedules WHERE cafe_id=c AND id=i FOR UPDATE;IF NOT FOUND OR NOT s.active OR s.next_date>(now() AT TIME ZONE 'Asia/Riyadh')::date THEN RAISE EXCEPTION 'التكرار غير نشط أو لم يحن موعده';END IF;
 IF s.auto_post THEN PERFORM erp_finance_private.authorize(c,'approve');END IF;
 SELECT * INTO v FROM public.erp_finance_vouchers WHERE cafe_id=c AND id=s.source_voucher;IF v.status='reversed' THEN RAISE EXCEPTION 'السند المصدر معكوس';END IF;
 d:=s.next_date;SELECT voucher_id INTO n FROM public.erp_finance_occurrences WHERE cafe_id=c AND schedule_id=i AND dated=d;
 IF n IS NULL THEN n:=erp_finance_private.save_voucher(c,v.payload||jsonb_build_object('id',NULL,'revision',0,'date',d,'code','REC-'||i::text||'-'||d::text,'customValues','{}'::jsonb));INSERT INTO public.erp_finance_occurrences VALUES(c,i,d,n);IF s.auto_post THEN PERFORM erp_finance_private.post_voucher(c,n);END IF;END IF;
 step:=CASE s.frequency WHEN 'weekly' THEN interval '7 days' WHEN 'biweekly' THEN interval '14 days' WHEN 'fourweekly' THEN interval '28 days' WHEN 'monthly' THEN interval '1 month' WHEN 'bimonthly' THEN interval '2 months' WHEN 'quarterly' THEN interval '3 months' WHEN 'semiannual' THEN interval '6 months' WHEN 'annual' THEN interval '1 year' ELSE interval '2 years' END;
 next_d:=(d+step)::date;UPDATE public.erp_finance_schedules SET next_date=CASE WHEN until_date IS NOT NULL AND next_d>until_date THEN next_date ELSE next_d END,active=(until_date IS NULL OR next_d<=until_date),revision=revision+1,last_error='' WHERE cafe_id=c AND id=i;
 PERFORM erp_finance_private.event(c,i,'generated',jsonb_build_object('voucherId',n,'date',d,'posted',s.auto_post));RETURN jsonb_build_object('voucherId',n);
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.import_statement(c uuid, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE i uuid:=gen_random_uuid();account uuid:=(p->>'accountId')::uuid;start_date date:=(p->>'from')::date;end_date date:=(p->>'to')::date;opening numeric:=(p->>'opening')::numeric;closing numeric:=(p->>'closing')::numeric;total numeric:=0;row jsonb;n integer:=0;amount numeric;BEGIN
 PERFORM erp_asset_private.account(c,account,ARRAY['bank']);
 IF length(btrim(coalesce(p->>'name',''))) NOT BETWEEN 1 AND 150 OR start_date IS NULL OR end_date IS NULL OR NOT isfinite(start_date) OR NOT isfinite(end_date) OR start_date>end_date OR end_date-start_date>3660 OR coalesce(p->>'sourceHash','')!~'^[a-f0-9]{64}$' OR opening IS NULL OR closing IS NULL OR abs(opening)>1e9 OR abs(closing)>1e9 OR opening IN('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) OR closing IN('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) OR opening<>round(opening,2) OR closing<>round(closing,2) OR jsonb_typeof(p->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'rows') NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'راجع فترة كشف البنك وأرصدته وحركاته';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_bank_statements WHERE cafe_id=c AND account_id=account AND source_hash=p->>'sourceHash') THEN RAISE EXCEPTION 'سبق استيراد هذا الملف للحساب';END IF;
 INSERT INTO public.erp_bank_statements(cafe_id,id,account_id,name,date_from,date_to,opening,closing,source_hash,created_by) VALUES(c,i,account,btrim(p->>'name'),start_date,end_date,opening,closing,p->>'sourceHash',auth.uid());
 FOR row IN SELECT * FROM jsonb_array_elements(p->'rows') LOOP
  amount:=(row->>'amount')::numeric;IF amount IS NULL OR amount=0 OR abs(amount)>1e9 OR amount IN('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric) OR amount<>round(amount,2) OR (row->>'date')::date NOT BETWEEN start_date AND end_date OR row->>'date' IS NULL OR length(coalesce(row->>'reference',''))>200 OR length(coalesce(row->>'description',''))>1000 THEN RAISE EXCEPTION 'راجع المبلغ والتاريخ في صف الكشف %',n+1;END IF;
  total:=total+amount;INSERT INTO public.erp_bank_statement_rows(cafe_id,statement_id,position,dated,reference,description,amount) VALUES(c,i,n,(row->>'date')::date,coalesce(row->>'reference',''),coalesce(row->>'description',''),amount);n:=n+1;
 END LOOP;
 IF opening+total<>closing THEN RAISE EXCEPTION 'رصيد الإقفال لا يساوي الافتتاحي ومجموع الحركات';END IF;
 RETURN i;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.match_statement(c uuid, p jsonb, remove boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE row public.erp_bank_statement_rows;account uuid;ids uuid[];actual numeric;BEGIN
 SELECT * INTO row FROM public.erp_bank_statement_rows WHERE cafe_id=c AND id=(p->>'id')::uuid FOR UPDATE;IF NOT FOUND OR row.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'تغير صف المطابقة أعد تحميله' USING ERRCODE='40001';END IF;
 SELECT account_id INTO account FROM public.erp_bank_statements WHERE cafe_id=c AND id=row.statement_id;
 IF remove THEN
  IF NOT EXISTS(SELECT 1 FROM public.erp_bank_matches WHERE cafe_id=c AND row_id=row.id) THEN RAISE EXCEPTION 'الصف غير مطابق';END IF;DELETE FROM public.erp_bank_matches WHERE cafe_id=c AND row_id=row.id;
 ELSE
  IF jsonb_typeof(p->'journalIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'journalIds') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'اختر الحركات المطابقة';END IF;
  SELECT array_agg(value::uuid) INTO ids FROM jsonb_array_elements_text(p->'journalIds');
  IF cardinality(ids)<>(SELECT count(DISTINCT x) FROM unnest(ids)x) OR EXISTS(SELECT 1 FROM public.erp_bank_matches WHERE cafe_id=c AND(row_id=row.id OR journal_id=ANY(ids))) OR(SELECT count(*) FROM public.bf_journal WHERE cafe_id=c AND account_id=account AND id=ANY(ids))<>cardinality(ids) THEN RAISE EXCEPTION 'الحركات مطابقة مسبقًا أو لا تخص الحساب البنكي';END IF;
  SELECT sum(debit-credit) INTO actual FROM public.bf_journal WHERE cafe_id=c AND account_id=account AND id=ANY(ids);IF actual<>row.amount THEN RAISE EXCEPTION 'مجموع حركات الحساب لا يساوي مبلغ صف البنك';END IF;
  INSERT INTO public.erp_bank_matches(cafe_id,row_id,journal_id,actor) SELECT c,row.id,x,auth.uid() FROM unnest(ids)x;
 END IF;
 UPDATE public.erp_bank_statement_rows SET revision=revision+1 WHERE cafe_id=c AND id=row.id;RETURN row.statement_id;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.post_voucher(c uuid, i uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE v public.erp_finance_vouchers;calculation jsonb;row jsonb;doc uuid;cash uuid;tax_account uuid;n integer:=0;allocation jsonb;allocated numeric;remaining numeric;items jsonb;last_index integer;index integer;cfg jsonb;BEGIN
 SELECT * INTO v FROM public.erp_finance_vouchers WHERE cafe_id=c AND id=i FOR UPDATE;IF NOT FOUND OR v.status<>'draft' THEN RAISE EXCEPTION 'السند غير متاح للترحيل';END IF;
 SELECT payload INTO cfg FROM public.erp_finance_settings WHERE cafe_id=c;PERFORM erp_finance_private.validate_voucher_fields(coalesce(cfg->CASE v.kind WHEN 'expense' THEN 'expenseFields' ELSE 'receiptFields' END,'[]'),coalesce(v.payload->'customValues','{}'),c,i,'voucher');
 calculation:=erp_finance_private.validate_voucher(c,v.kind,v.payload);cash:=(v.payload->>'cashAccountId')::uuid;PERFORM erp_finance_private.cash_account(c,cash,CASE v.kind WHEN 'expense' THEN(calculation->>'total')::numeric ELSE 0 END);
 doc:=erp_finance_private.document(c,v.kind,(v.payload->>'date')::date,(calculation->>'total')::numeric,v.payload->>'note',cash,v.party_id,(calculation->>'net')::numeric,(calculation->>'tax')::numeric);
 PERFORM erp_asset_private.line(c,doc,cash,CASE v.kind WHEN 'receipt' THEN(calculation->>'total')::numeric ELSE 0 END,CASE v.kind WHEN 'expense' THEN(calculation->>'total')::numeric ELSE 0 END);
 FOR row IN SELECT * FROM jsonb_array_elements(calculation->'lines') LOOP
  PERFORM erp_asset_private.line(c,doc,(row->>'accountId')::uuid,CASE v.kind WHEN 'expense' THEN(row->>'net')::numeric ELSE 0 END,CASE v.kind WHEN 'receipt' THEN(row->>'net')::numeric ELSE 0 END);
  items:=coalesce(v.payload->'lines'->n->'costCenters','[]');remaining:=(row->>'net')::numeric;last_index:=jsonb_array_length(items)-1;index:=0;
  FOR allocation IN SELECT * FROM jsonb_array_elements(items) LOOP
   allocated:=CASE WHEN index=last_index THEN remaining ELSE least(remaining,round((row->>'net')::numeric*(allocation->>'percentage')::numeric/100,2)) END;remaining:=remaining-allocated;
   INSERT INTO public.erp_finance_cost_allocations(cafe_id,voucher_id,line_index,center_id,percentage,base_amount) VALUES(c,i,n,(allocation->>'id')::uuid,(allocation->>'percentage')::numeric,allocated);index:=index+1;
  END LOOP;n:=n+1;
 END LOOP;
 IF(calculation->>'tax')::numeric>0 THEN tax_account:=brand_finance_private.account(c,CASE v.kind WHEN 'expense' THEN '1300' ELSE '2100' END);PERFORM erp_asset_private.line(c,doc,tax_account,CASE v.kind WHEN 'expense' THEN(calculation->>'tax')::numeric ELSE 0 END,CASE v.kind WHEN 'receipt' THEN(calculation->>'tax')::numeric ELSE 0 END);END IF;
 UPDATE public.erp_finance_vouchers SET document_id=doc,status='posted',revision=revision+1,payload=payload||jsonb_build_object('calculation',calculation) WHERE cafe_id=c AND id=i;
 PERFORM erp_finance_private.event(c,i,'post',jsonb_build_object('documentId',doc));RETURN doc;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.reverse_document(c uuid, original uuid, d date, note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE source public.bf_documents;doc uuid;line public.bf_journal;allocated boolean;BEGIN
 SELECT * INTO source FROM public.bf_documents WHERE cafe_id=c AND id=original;IF NOT FOUND OR d<(source.created_at AT TIME ZONE 'Asia/Riyadh')::date OR length(btrim(note)) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'راجع المستند وتاريخ العكس وسببه';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_bank_matches m JOIN public.bf_journal j ON j.id=m.journal_id WHERE m.cafe_id=c AND j.cafe_id=c AND j.document_id=original) THEN RAISE EXCEPTION 'ألغ المطابقة البنكية قبل عكس المستند';END IF;
 IF to_regclass('public.erp_purchase_allocations') IS NOT NULL THEN EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_purchase_allocations WHERE cafe_id=$1 AND expense_document_id=$2)' INTO allocated USING c,original;IF allocated THEN RAISE EXCEPTION 'المصروف موزع على مشتريات ولا يمكن عكس مصدره';END IF;END IF;
 FOR line IN SELECT * FROM public.bf_journal WHERE cafe_id=c AND document_id=original LOOP
  IF EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=c AND id=line.account_id AND kind IN('cash','bank')) THEN PERFORM erp_finance_private.cash_account(c,line.account_id,line.debit);END IF;
 END LOOP;
 doc:=erp_finance_private.document(c,'journal',d,source.total,note,source.account_id,source.party_id,0,0,original);
 FOR line IN SELECT * FROM public.bf_journal WHERE cafe_id=c AND document_id=original LOOP PERFORM erp_asset_private.line(c,doc,line.account_id,line.credit,line.debit);END LOOP;RETURN doc;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.save_custody(c uuid, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE old public.erp_finance_custodies;i uuid:=coalesce((p->>'id')::uuid,gen_random_uuid());amount numeric:=(p->>'amount')::numeric;rate numeric:=(p->>'exchangeRate')::numeric;cfg jsonb;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=c AND id=(p->>'employeeId')::uuid AND active) OR length(btrim(coalesce(p->>'code',''))) NOT BETWEEN 1 AND 60 OR length(coalesce(p->>'note',''))>4000 OR coalesce(p->>'currency','')!~'^[A-Z]{3}$' OR amount IS NULL OR amount<=0 OR amount>1e9 OR amount='NaN'::numeric OR amount<>round(amount,2) OR rate IS NULL OR rate<=0 OR rate>1000000 OR rate='NaN'::numeric OR(p->>'currency'='SAR' AND rate<>1) OR round(amount*rate,2) NOT BETWEEN .01 AND 1e9 THEN RAISE EXCEPTION 'راجع الموظف وبيانات العهدة';END IF;
 PERFORM erp_asset_private.date_open(c,(p->>'date')::date);PERFORM erp_asset_private.account(c,(p->>'cashAccountId')::uuid,ARRAY['cash','bank']);
 IF p->>'id' IS NOT NULL THEN SELECT * INTO old FROM public.erp_finance_custodies WHERE cafe_id=c AND id=i FOR UPDATE;IF NOT FOUND OR old.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت العهدة أعد تحميلها' USING ERRCODE='40001';END IF;IF old.status<>'draft' THEN RAISE EXCEPTION 'لا تعدل العهدة بعد صرفها';END IF;END IF;
 SELECT payload INTO cfg FROM public.erp_finance_settings WHERE cafe_id=c;PERFORM erp_finance_private.validate_custody_fields(coalesce(cfg->'custodyFields','[]'),coalesce(p->'customValues','{}'),c,i,'custody',0,true);
 INSERT INTO public.erp_finance_custodies(cafe_id,id,employee_id,code,payload,created_by) VALUES(c,i,(p->>'employeeId')::uuid,btrim(p->>'code'),p,auth.uid()) ON CONFLICT(cafe_id,id) DO UPDATE SET employee_id=excluded.employee_id,code=excluded.code,payload=excluded.payload,revision=erp_finance_custodies.revision+1;RETURN i;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.save_schedule(c uuid, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE i uuid:=coalesce((p->>'id')::uuid,gen_random_uuid());old public.erp_finance_schedules;v public.erp_finance_vouchers;d date:=(p->>'nextDate')::date;stop date:=(p->>'untilDate')::date;BEGIN
 IF p->>'id' IS NOT NULL THEN SELECT * INTO old FROM public.erp_finance_schedules WHERE cafe_id=c AND id=i FOR UPDATE;IF NOT FOUND OR old.revision IS DISTINCT FROM(p->>'revision')::integer THEN RAISE EXCEPTION 'تغير التكرار أعد تحميله' USING ERRCODE='40001';END IF;END IF;
 SELECT * INTO v FROM public.erp_finance_vouchers WHERE cafe_id=c AND id=(p->>'sourceId')::uuid;IF NOT FOUND OR v.status='reversed' THEN RAISE EXCEPTION 'اختر سندًا قائمًا للتكرار';END IF;
 IF d IS NULL OR NOT isfinite(d) OR d<(v.payload->>'date')::date OR(stop IS NOT NULL AND(NOT isfinite(stop) OR stop<d)) THEN RAISE EXCEPTION 'راجع فترة التكرار';END IF;
 IF coalesce((p->>'autoPost')::boolean,false) THEN PERFORM erp_finance_private.authorize(c,'approve');END IF;
 INSERT INTO public.erp_finance_schedules(cafe_id,id,source_voucher,active,next_date,until_date,frequency,auto_post,created_by) VALUES(c,i,v.id,(p->>'active')::boolean,d,stop,p->>'frequency',(p->>'autoPost')::boolean,auth.uid()) ON CONFLICT(cafe_id,id) DO UPDATE SET source_voucher=excluded.source_voucher,active=excluded.active,next_date=excluded.next_date,until_date=excluded.until_date,frequency=excluded.frequency,auto_post=excluded.auto_post,created_by=excluded.created_by,revision=erp_finance_schedules.revision+1,last_error='';RETURN i;
