CREATE OR REPLACE FUNCTION erp_finance_private.save_voucher(c uuid, p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE old public.erp_finance_vouchers;i uuid:=coalesce((p->>'id')::uuid,gen_random_uuid());kind text:=p->>'kind';cfg jsonb;BEGIN
 PERFORM erp_finance_private.validate_voucher(c,kind,p);
 IF p->>'id' IS NOT NULL THEN SELECT * INTO old FROM public.erp_finance_vouchers WHERE cafe_id=c AND id=i FOR UPDATE;IF NOT FOUND OR old.revision IS DISTINCT FROM (p->>'revision')::integer THEN RAISE EXCEPTION 'تغير السند أعد تحميله' USING ERRCODE='40001';END IF;IF old.status<>'draft' OR old.kind<>kind THEN RAISE EXCEPTION 'السند المرحل لا يعدل اعكسه ثم أنشئ سندًا مصححًا';END IF;END IF;
 SELECT payload INTO cfg FROM public.erp_finance_settings WHERE cafe_id=c;PERFORM erp_finance_private.validate_voucher_fields(coalesce(cfg->CASE kind WHEN 'expense' THEN 'expenseFields' ELSE 'receiptFields' END,'[]'),coalesce(p->'customValues','{}'),c,i,'voucher',0,true);
 INSERT INTO public.erp_finance_vouchers(cafe_id,id,kind,code,payload,category_id,party_id,created_by) VALUES(c,i,kind,btrim(p->>'code'),p-'calculation',nullif(p->>'categoryId','')::uuid,nullif(p->>'partyId','')::uuid,auth.uid()) ON CONFLICT(cafe_id,id) DO UPDATE SET code=excluded.code,payload=excluded.payload,category_id=excluded.category_id,party_id=excluded.party_id,revision=erp_finance_vouchers.revision+1;
 RETURN i;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.validate_custody_fields(fields jsonb, vals jsonb, p_cafe uuid DEFAULT NULL::uuid, p_record uuid DEFAULT NULL::uuid, p_kind text DEFAULT NULL::text, depth integer DEFAULT 0, p_draft boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE f jsonb;v jsonb;t text;x jsonb;txt text;tbl text;col text;valid boolean;metric numeric;BEGIN
 IF coalesce(jsonb_typeof(vals),'')<>'object' OR octet_length(vals::text)>262144 OR depth>2 THEN RAISE EXCEPTION 'بيانات الحقول الإضافية غير صالحة';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP
  t:=f->>'type';IF t IN('static','separator') THEN CONTINUE;END IF;
  v:=coalesce(vals->(f->>'id'),f->'defaultValue');
  IF coalesce((f->>'required')::boolean,false) AND NOT p_draft AND (v IS NULL OR v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb OR (t='checkbox' AND v<>'true')) THEN RAISE EXCEPTION 'أكمل الحقل المطلوب: %',f->>'label';END IF;
  IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
  IF t='subform' THEN
   IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>100 OR jsonb_array_length(v)<coalesce((f->>'minimumRows')::integer,0) THEN RAISE EXCEPTION 'عدد صفوف النموذج غير صالح';END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM erp_finance_private.validate_custody_fields(f->'fields',x,p_cafe,p_record,p_kind,depth+1,p_draft);END LOOP;CONTINUE;
  END IF;
  IF t='location' THEN
   IF jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'latitude')<>'number' OR jsonb_typeof(v->'longitude')<>'number' OR abs((v->>'latitude')::numeric)>90 OR abs((v->>'longitude')::numeric)>180 THEN RAISE EXCEPTION 'إحداثيات الموقع غير صالحة';END IF;CONTINUE;
  END IF;
  IF (t IN('number','currency') AND jsonb_typeof(v)<>'number') OR (t='checkbox' AND jsonb_typeof(v)<>'boolean') OR (t IN('multiselect','multidynamic') AND jsonb_typeof(v)<>'array') OR (t NOT IN('number','currency','checkbox','multiselect','multidynamic') AND jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'نوع قيمة الحقل غير صالح';END IF;
  txt:=v#>>'{}';
  IF length(txt)>20000 THEN RAISE EXCEPTION 'قيمة الحقل طويلة';END IF;
  IF (t='select' AND NOT(f->'options' @> jsonb_build_array(v))) OR (t='multiselect' AND NOT(f->'options' @> v)) THEN RAISE EXCEPTION 'اختيارات الحقل غير صالحة';END IF;
  IF t='email' AND txt!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'البريد الإلكتروني غير صالح';END IF;
  IF t='url' AND txt!~'^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'الرابط غير صالح';END IF;
  IF t='time' AND txt!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'الوقت غير صالح';END IF;
  IF t='date' THEN IF txt!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'التاريخ غير صالح';END IF;PERFORM txt::date;END IF;
  IF t IN('number','currency','text','textarea','formatted') THEN
   metric:=CASE WHEN t IN('number','currency') THEN txt::numeric ELSE length(txt) END;
   IF metric<nullif(f->>'minimum','')::numeric OR metric>nullif(f->>'maximum','')::numeric THEN RAISE EXCEPTION 'قيمة الحقل خارج الحدود: %',f->>'label';END IF;
  END IF;
  IF t IN('dynamic','multidynamic') THEN
   tbl:=CASE f->>'entity' WHEN 'items' THEN 'bf_items' WHEN 'customers' THEN 'bf_parties' WHEN 'employees' THEN 'erp_hr_employees' WHEN 'warehouses' THEN 'bf_warehouses' WHEN 'accounts' THEN 'bf_accounts' WHEN 'bom' THEN 'erp_mfg_boms' WHEN 'routings' THEN 'erp_mfg_routings' WHEN 'workstations' THEN 'erp_mfg_workstations' WHEN 'orders' THEN 'erp_mfg_orders' WHEN 'sources' THEN 'bf_documents' END;
   IF tbl IS NULL OR p_cafe IS NULL THEN RAISE EXCEPTION 'الكيان المرتبط غير صالح';END IF;col:=CASE WHEN tbl='bf_staff' THEN 'user_id' ELSE 'id' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN t='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND %I=$2)',tbl,col) INTO valid USING p_cafe,(x#>>'{}')::uuid;
    IF NOT valid THEN RAISE EXCEPTION 'القيمة المرتبطة غير موجودة في العلامة';END IF;
   END LOOP;
  END IF;
  IF t IN('file','image') THEN
   IF p_record IS NULL OR to_regclass('public.erp_files') IS NULL THEN RAISE EXCEPTION 'احفظ السجل وأضف المرفق أولًا';END IF;
   EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=$1 AND record_id=$2 AND id=$3 AND entity_type=$4 AND uploaded AND ($5<>''image'' OR mime IN(''image/jpeg'',''image/png'')))' INTO valid USING p_cafe,p_record,txt::uuid,'financial_custody',t;
   IF NOT valid THEN RAISE EXCEPTION 'المرفق غير موجود في هذا السجل';END IF;
   PERFORM 1 FROM public.erp_files f WHERE f.cafe_id=p_cafe AND f.record_id=p_record AND f.id=txt::uuid AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='erp-record-files' AND o.name=f.path) FOR KEY SHARE OF f;
   IF NOT FOUND THEN RAISE EXCEPTION 'الملف المرفق لم يعد متاحًا';END IF;
  END IF;
  IF coalesce((f->>'unique')::boolean,false) AND depth=0 AND p_kind='custody' THEN
   tbl:='erp_finance_custodies';
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id IS DISTINCT FROM $2 AND payload->''customValues''->$3=$4)',tbl) INTO valid USING p_cafe,p_record,f->>'id',v;
   IF valid THEN RAISE EXCEPTION 'قيمة الحقل مستخدمة مسبقًا: %',f->>'label';END IF;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.validate_voucher(c uuid, k text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE l jsonb;a uuid;rate numeric:=(p->>'exchangeRate')::numeric;currency text:=p->>'currency';amount numeric;tax numeric;net numeric:=0;vat numeric:=0;rows jsonb:='[]';allowed_tax numeric;center jsonb;centers uuid[];total_pct numeric;BEGIN
 IF k NOT IN('expense','receipt') OR jsonb_typeof(p) IS DISTINCT FROM 'object' OR jsonb_typeof(p->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'lines') NOT BETWEEN 1 AND 100 OR octet_length(p::text)>300000 OR length(btrim(coalesce(p->>'code',''))) NOT BETWEEN 1 AND 60 OR length(btrim(coalesce(p->>'note',''))) NOT BETWEEN 1 AND 4000 OR currency IS NULL OR currency!~'^[A-Z]{3}$' OR rate IS NULL OR rate<=0 OR rate>1000000 OR rate='NaN'::numeric OR(currency='SAR' AND rate<>1) THEN RAISE EXCEPTION 'راجع بيانات السند والعملة والتفاصيل';END IF;
 PERFORM erp_asset_private.date_open(c,(p->>'date')::date);PERFORM erp_asset_private.account(c,(p->>'cashAccountId')::uuid,ARRAY['cash','bank']);
 IF nullif(p->>'partyId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=(p->>'partyId')::uuid AND active AND kind=CASE k WHEN 'expense' THEN 'supplier' ELSE 'customer' END) THEN RAISE EXCEPTION 'اختر جهة نشطة من هذه العلامة';END IF;
 IF nullif(p->>'categoryId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_finance_categories WHERE cafe_id=c AND id=(p->>'categoryId')::uuid AND active AND kind=k) THEN RAISE EXCEPTION 'التصنيف غير متاح';END IF;
 SELECT vat_rate INTO allowed_tax FROM public.bf_settings WHERE cafe_id=c;
 FOR l IN SELECT * FROM jsonb_array_elements(p->'lines') LOOP
  a:=(l->>'accountId')::uuid;amount:=(l->>'amount')::numeric;tax:=(l->>'taxRate')::numeric;
  PERFORM erp_asset_private.account(c,a,CASE k WHEN 'expense' THEN ARRAY['expense','equity'] ELSE ARRAY['revenue','equity'] END);
  IF amount IS NULL OR amount<=0 OR amount>1e9 OR amount='NaN'::numeric OR amount<>round(amount,2) OR tax IS NULL OR tax NOT IN(0,coalesce(allowed_tax,0)) OR length(coalesce(l->>'description',''))>1000 THEN RAISE EXCEPTION 'راجع مبلغ البند والضريبة المعتمدة';END IF;
  amount:=round(amount*rate,2);tax:=round(amount*tax/100,2);IF amount<=0 THEN RAISE EXCEPTION 'مبلغ البند بعد التحويل أقل من هللة';END IF;
  net:=net+amount;vat:=vat+tax;rows:=rows||jsonb_build_array(jsonb_build_object('accountId',a,'net',amount,'tax',tax,'description',coalesce(l->>'description','')));
  IF jsonb_typeof(coalesce(l->'costCenters','[]'))<>'array' OR jsonb_array_length(coalesce(l->'costCenters','[]'))>100 THEN RAISE EXCEPTION 'توزيع التكلفة غير صالح';END IF;centers:='{}';total_pct:=0;
  FOR center IN SELECT * FROM jsonb_array_elements(coalesce(l->'costCenters','[]')) LOOP
   IF (center->>'id')::uuid=ANY(centers) OR NOT EXISTS(SELECT 1 FROM public.erp_cost_centers WHERE cafe_id=c AND id=(center->>'id')::uuid AND active AND NOT is_group) OR coalesce((center->>'percentage')::numeric,0)<=0 OR (center->>'percentage')::numeric>100 OR (center->>'percentage')::numeric='NaN'::numeric THEN RAISE EXCEPTION 'اختر مركز تكلفة فرعيًا ونسبة صالحة دون تكرار';END IF;
   centers:=array_append(centers,(center->>'id')::uuid);total_pct:=total_pct+(center->>'percentage')::numeric;
  END LOOP;
  IF cardinality(centers)>0 AND total_pct<>100 THEN RAISE EXCEPTION 'مجموع نسب توزيع البند يجب أن يساوي مئة بالمئة';END IF;
 END LOOP;
 IF net+vat>1e9 THEN RAISE EXCEPTION 'إجمالي السند أكبر من المسموح';END IF;RETURN jsonb_build_object('net',net,'tax',vat,'total',net+vat,'lines',rows);
END $function$

CREATE OR REPLACE FUNCTION erp_finance_private.validate_voucher_fields(fields jsonb, vals jsonb, p_cafe uuid DEFAULT NULL::uuid, p_record uuid DEFAULT NULL::uuid, p_kind text DEFAULT NULL::text, depth integer DEFAULT 0, p_draft boolean DEFAULT false)
