CREATE OR REPLACE FUNCTION erp_hr_private.file_delete_access_before_hr(p_path text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE f public.erp_files;
BEGIN
 SELECT * INTO f FROM public.erp_files WHERE path=p_path FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 PERFORM erp_file_private.assert_record(f.cafe_id,f.entity_type,f.record_id,true);
 IF f.entity_type='employee_asset' AND EXISTS(SELECT 1 FROM public.erp_employee_assets WHERE cafe_id=f.cafe_id AND photo_id=f.id) THEN RETURN false;END IF; RETURN true;
EXCEPTION WHEN SQLSTATE '42501' OR SQLSTATE '22023' THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION erp_hr_private.organization_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE e public.erp_hr_employees;manager_profile uuid;p jsonb;BEGIN
 IF current_setting('erp.hr.syncing',true)='true' THEN RETURN NEW;END IF;
 SELECT * INTO e FROM public.erp_hr_employees WHERE cafe_id=NEW.cafe_id AND user_id=NEW.user_id FOR UPDATE;IF NOT FOUND THEN RETURN NEW;END IF;
 SELECT id INTO manager_profile FROM public.erp_hr_employees WHERE cafe_id=NEW.cafe_id AND user_id=NEW.manager_id;
 p:=e.payload||jsonb_build_object('departmentId',NEW.department_id,'designationId',NEW.designation_id,'levelId',NEW.level_id,'typeId',NEW.type_id,'managerId',manager_profile);
 PERFORM erp_hr_private.validate(NEW.cafe_id,p,e.id);
 UPDATE public.erp_hr_employees SET department_id=NEW.department_id,designation_id=NEW.designation_id,level_id=NEW.level_id,type_id=NEW.type_id,manager_id=manager_profile,payload=p,revision=revision+1,updated_at=now() WHERE cafe_id=NEW.cafe_id AND id=e.id;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_hr_private.validate(p_cafe uuid, p jsonb, p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE k text;v text;ref uuid;expected text;BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR octet_length(p::text)>40000 OR length(btrim(coalesce(p->>'firstName',''))) NOT BETWEEN 1 AND 100 OR length(coalesce(p->>'middleName',''))>100 OR length(coalesce(p->>'lastName',''))>100 OR length(coalesce(p->>'code',''))>50 OR length(coalesce(p->>'note',''))>10000 OR jsonb_typeof(p->'active') IS DISTINCT FROM 'boolean' OR coalesce(p->>'country','')!~'^[A-Z]{2}$' OR coalesce(p->>'language','') NOT IN('ar','en') OR coalesce(p->>'gender','') NOT IN('','male','female') OR coalesce(p->>'citizenship','') NOT IN('','citizen','resident') THEN RAISE EXCEPTION 'راجع بيانات الموظف الأساسية' USING ERRCODE='22023';END IF;
 IF p->>'joinDate' IS NULL OR NOT isfinite((p->>'joinDate')::date) OR (p->>'birthDate')::date>=(p->>'joinDate')::date OR (p->>'birthDate')::date>current_date OR (p->>'endDate')::date<(p->>'joinDate')::date THEN RAISE EXCEPTION 'راجع تواريخ الموظف' USING ERRCODE='22023';END IF;
 FOREACH k IN ARRAY ARRAY['email','personalEmail','mobile','phone','officialId'] LOOP IF length(coalesce(p->>k,''))>254 THEN RAISE EXCEPTION 'بيانات الاتصال أطول من المسموح';END IF;END LOOP;
 FOREACH k IN ARRAY ARRAY['address','permanentAddress'] LOOP IF jsonb_typeof(p->k) IS DISTINCT FROM 'object' OR octet_length((p->k)::text)>4000 THEN RAISE EXCEPTION 'بيانات العنوان غير صالحة';END IF;END LOOP;
 IF (p->>'fiscalMonth' IS NULL)<>(p->>'fiscalDay' IS NULL) OR (p->>'fiscalMonth')::integer NOT BETWEEN 1 AND 12 OR (p->>'fiscalDay')::integer NOT BETWEEN 1 AND 31 THEN RAISE EXCEPTION 'التاريخ المالي غير صالح';END IF;
 IF p->>'fiscalMonth' IS NOT NULL THEN PERFORM make_date(2000,(p->>'fiscalMonth')::integer,(p->>'fiscalDay')::integer);END IF;
 IF p->>'userId' IS NOT NULL AND NOT erp_org_private.staff(p_cafe,(p->>'userId')::uuid) THEN RAISE EXCEPTION 'حساب الدخول لا ينتمي إلى فريق العلامة' USING ERRCODE='42501';END IF;
 IF p->>'branchId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=p_cafe AND id=(p->>'branchId')::uuid AND active AND deleted_at IS NULL) THEN RAISE EXCEPTION 'الفرع غير متاح';END IF;
 FOREACH k IN ARRAY ARRAY['department','designation','level','type'] LOOP ref:=(p->>(k||'Id'))::uuid;IF ref IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_org_units WHERE cafe_id=p_cafe AND id=ref AND kind=k AND active) THEN RAISE EXCEPTION 'ارتباط الهيكل التنظيمي غير صالح';END IF;END LOOP;
 IF p->>'designationId' IS NOT NULL AND EXISTS(SELECT 1 FROM public.erp_org_units WHERE cafe_id=p_cafe AND id=(p->>'designationId')::uuid AND parent_id IS NOT NULL AND parent_id IS DISTINCT FROM (p->>'departmentId')::uuid) THEN RAISE EXCEPTION 'المسمى الوظيفي يتبع قسمًا آخر';END IF;
 ref:=(p->>'managerId')::uuid;
 IF ref IS NOT NULL THEN
  IF ref=p_id OR NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=ref AND active) OR EXISTS(WITH RECURSIVE chain AS(SELECT id,manager_id,ARRAY[id] path FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=ref UNION ALL SELECT e.id,e.manager_id,c.path||e.id FROM public.erp_hr_employees e JOIN chain c ON e.id=c.manager_id WHERE e.cafe_id=p_cafe AND NOT e.id=ANY(c.path)) SELECT 1 FROM chain WHERE id=p_id) THEN RAISE EXCEPTION 'ارتباط المدير يكوّن حلقة أو يشير إلى موظف غير متاح';END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_installment_private.agreement(p_cafe uuid, p_document uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE d public.bf_documents;state jsonb;schedule jsonb;rows jsonb;outstanding numeric;credit numeric;next_due date;has_overdue boolean;status text;
BEGIN
 SELECT * INTO d FROM public.bf_documents WHERE cafe_id=p_cafe AND id=p_document AND kind='sale';IF NOT FOUND THEN RETURN NULL;END IF;
 state:=brand_finance_private.document_state(p_cafe,p_document);outstanding:=(state->>'outstanding')::numeric;credit:=coalesce((state->>'refunded_total')::numeric,0);
 SELECT metadata->'schedule' INTO schedule FROM public.bf_invoice_management WHERE cafe_id=p_cafe AND document_id=p_document;
 SELECT min(r.date) FILTER(WHERE r.remaining>0),bool_or(r.status='overdue') INTO next_due,has_overdue FROM erp_installment_private.rows(d.total,outstanding,credit,schedule) r;
 status:=CASE WHEN credit>=d.total THEN 'cancelled' WHEN outstanding<=0 THEN 'paid' WHEN has_overdue THEN 'overdue' WHEN outstanding<greatest(d.total-credit,0) THEN 'partial' ELSE 'unpaid' END;
 RETURN jsonb_build_object('id',d.id,'number',d.number,'invoiceNumber',coalesce(state->>'display_number',d.number::text),'customerId',d.party_id,'customerName',(SELECT name FROM public.bf_parties WHERE cafe_id=p_cafe AND id=d.party_id),'total',d.total,'outstanding',outstanding,'refundedTotal',credit,'refunded',coalesce((state->>'refunded')::boolean,false),'paid',greatest(d.total-credit-outstanding,0),'createdAt',d.created_at,'schedule',schedule,'nextDue',next_due,'status',status,'row',NULL);
END $function$

CREATE OR REPLACE FUNCTION erp_installment_private.rows(p_total numeric, p_outstanding numeric, p_refunded numeric, p_schedule jsonb)
 RETURNS TABLE(number integer, date date, amount numeric, paid numeric, cancelled numeric, remaining numeric, status text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE step numeric;count_rows integer;anchor date;frequency text;payable numeric;collected numeric;offset_amount numeric;due numeric;idx integer;months integer;
BEGIN
 IF jsonb_typeof(p_schedule) IS DISTINCT FROM 'object' THEN RETURN;END IF;
 step:=(p_schedule->>'amount')::numeric;anchor:=(p_schedule->>'start')::date;frequency:=p_schedule->>'frequency';
 IF step IS NULL OR step<.01 OR step<>round(step,2) OR step>p_total OR p_total<=0 OR ceil(p_total/step)>600 OR NOT isfinite(anchor) THEN RAISE EXCEPTION 'جدول الأقساط غير صالح' USING ERRCODE='22023';END IF;
 count_rows:=ceil(p_total/step);payable:=greatest(p_total-least(p_total,greatest(coalesce(p_refunded,0),0)),0);collected:=least(payable,greatest(payable-p_outstanding,0));
 months:=CASE frequency WHEN 'monthly' THEN 1 WHEN 'quarterly' THEN 3 WHEN 'half_yearly' THEN 6 WHEN 'yearly' THEN 12 END;
 IF months IS NULL AND frequency NOT IN('weekly','fortnightly') THEN RAISE EXCEPTION 'فترة التقسيط غير صالحة' USING ERRCODE='22023';END IF;
 FOR idx IN 0..count_rows-1 LOOP
  number:=idx+1;date:=CASE WHEN months IS NULL THEN anchor+idx*CASE WHEN frequency='weekly' THEN 7 ELSE 14 END ELSE (anchor+make_interval(months=>months*idx))::date END;
  IF date>'9999-12-31'::date THEN RAISE EXCEPTION 'تاريخ الأقساط خارج النطاق المسموح' USING ERRCODE='22023';END IF;
  offset_amount:=idx*step;amount:=least(step,p_total-offset_amount);due:=greatest(least(amount,payable-offset_amount),0);paid:=greatest(least(due,collected-offset_amount),0);cancelled:=amount-due;remaining:=due-paid;
  status:=CASE WHEN due=0 THEN 'cancelled' WHEN remaining=0 THEN 'paid' WHEN date<(now() AT TIME ZONE 'Asia/Riyadh')::date THEN 'overdue' WHEN paid>0 THEN 'partial' ELSE 'unpaid' END;RETURN NEXT;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_insurance_private.invoice_issued()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE binding public.erp_insurance_invoices;payload jsonb;entry jsonb;rule jsonb;rule_id text;totals jsonb:='{}';groups jsonb:='[]';amount numeric;company numeric;customer numeric;company_total numeric:=0;customer_total numeric:=0;max_amount numeric;category_names text;idx integer:=0;
BEGIN
 SELECT * INTO binding FROM public.erp_insurance_invoices WHERE cafe_id=NEW.cafe_id AND draft_id=NEW.draft_id FOR UPDATE;IF NOT FOUND THEN RETURN NEW;END IF;
 SELECT d.payload INTO payload FROM public.bf_invoice_drafts d WHERE d.cafe_id=NEW.cafe_id AND d.id=NEW.draft_id;
 IF binding.pricing_hash<>erp_insurance_private.pricing_hash(payload) OR NOT EXISTS(SELECT 1 FROM public.erp_insurance_enrollments e WHERE e.cafe_id=NEW.cafe_id AND e.customer_id=binding.customer_id AND e.revision=binding.enrollment_revision AND e.class_id=binding.class_id) THEN RAISE EXCEPTION 'تغيرت بنود الفاتورة أو فئة العميل أعد حساب التأمين قبل الإصدار' USING ERRCODE='22023';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.erp_insurance_companies WHERE cafe_id=NEW.cafe_id AND id=binding.company_id AND active) THEN RAISE EXCEPTION 'شركة التأمين غير نشطة';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.erp_insurance_classes WHERE cafe_id=NEW.cafe_id AND id=binding.class_id AND active AND rules=binding.rules_snapshot) THEN RAISE EXCEPTION 'تغيرت قواعد الفئة أعد حساب التأمين قبل الإصدار';END IF;
 IF jsonb_array_length(binding.line_rules)<>jsonb_array_length(NEW.snapshot->'lines') THEN RAISE EXCEPTION 'عدد بنود التغطية لا يطابق الفاتورة';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(NEW.snapshot->'lines') LOOP
  rule_id:=coalesce(binding.line_rules->idx->>'ruleId','uncovered');idx:=idx+1;amount:=(entry->>'total')::numeric;
  IF amount IS NULL OR amount<0 THEN RAISE EXCEPTION 'قيمة بند التأمين غير صالحة';END IF;
  totals:=jsonb_set(totals,ARRAY[rule_id],to_jsonb(coalesce((totals->>rule_id)::numeric,0)+amount));
 END LOOP;
 FOR rule_id,amount IN SELECT key,value::numeric FROM jsonb_each_text(totals) LOOP
  SELECT value INTO rule FROM jsonb_array_elements(binding.rules_snapshot) WHERE value->>'id'=rule_id;
  company:=round(amount*coalesce((rule->>'companyShare')::numeric,0)/100,2);customer:=amount-company;max_amount:=nullif(rule->>'maxCopayment','')::numeric;
  IF max_amount IS NOT NULL THEN IF rule->>'capFor'='company' THEN company:=least(company,max_amount);customer:=amount-company;ELSE customer:=least(customer,max_amount);company:=amount-customer;END IF;END IF;
  SELECT string_agg(name,' / ' ORDER BY name) INTO category_names FROM erp_insurance_private.categories(NEW.cafe_id) WHERE id::text IN(SELECT jsonb_array_elements_text(coalesce(rule->'categories','[]')));
  groups:=groups||jsonb_build_array(jsonb_build_object('ruleId',nullif(rule_id,'uncovered'),'label',CASE WHEN rule_id='uncovered' THEN 'غير مشمول' ELSE coalesce(category_names,'كل التصنيفات') END,'total',amount,'company',company,'customer',customer,'discount',coalesce(rule->'discount','0'::jsonb),'maxCopayment',max_amount,'capFor',coalesce(rule->>'capFor','customer')));company_total:=company_total+company;customer_total:=customer_total+customer;
 END LOOP;
 IF company_total+customer_total<>(NEW.snapshot->>'total')::numeric THEN RAISE EXCEPTION 'مجموع حصص التأمين لا يطابق إجمالي الفاتورة';END IF;
 UPDATE public.erp_insurance_invoices SET invoice_id=NEW.document_id,coverage=jsonb_build_object('total',company_total+customer_total,'company',company_total,'customer',customer_total,'groups',groups),revision=revision+1 WHERE cafe_id=NEW.cafe_id AND id=binding.id;
 INSERT INTO public.erp_insurance_events(cafe_id,record_id,action,actor) VALUES(NEW.cafe_id,binding.id,'invoice_issued',auth.uid());RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_insurance_private.payment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE link public.erp_insurance_collections;b public.erp_insurance_invoices;amount numeric;maximum numeric;BEGIN
 SELECT * INTO link FROM public.erp_insurance_collections WHERE cafe_id=NEW.cafe_id AND document_id=NEW.source_id;IF NOT FOUND THEN RETURN NEW;END IF;
