AS $function$BEGIN
 IF b IS NOT NULL THEN
  IF EXISTS(SELECT 1 FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=d AND branch_id<>b) THEN RAISE EXCEPTION 'فرع الإشعار لا يطابق مصدره' USING ERRCODE='42501';END IF;
