CREATE OR REPLACE FUNCTION erp_report_relation_private.fields(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE path text;p jsonb;f text;op text;result jsonb:='{}';cols jsonb;
BEGIN
 IF jsonb_typeof(coalesce(q->'relationPaths','[]'))<>'array' OR jsonb_array_length(coalesce(q->'relationPaths','[]'))>8 THEN RAISE EXCEPTION 'يمكن اختيار ثماني علاقات بعمق ثلاثة مستويات';END IF;
 IF jsonb_array_length(coalesce(q->'relationPaths','[]'))<>(SELECT count(DISTINCT v) FROM jsonb_array_elements_text(coalesce(q->'relationPaths','[]'))v) THEN RAISE EXCEPTION 'العلاقات مكررة';END IF;
 FOR path IN SELECT jsonb_array_elements_text(coalesce(q->'relationPaths','[]')) LOOP
  p:=erp_report_relation_private.path(q->>'source',path);
  IF strpos(path,'.')>0 AND NOT(q->'relationPaths'?regexp_replace(path,'[.][^.]+$','')) THEN RAISE EXCEPTION 'اختر العلاقة الأب قبل العلاقة المتداخلة';END IF;
  SELECT columns||'["date","year","quarter","month","week"]'::jsonb INTO cols FROM erp_reports_private.sources WHERE id=p->>'target';
  IF cols IS NULL THEN RAISE EXCEPTION 'مصدر العلاقة غير متاح';END IF;
  IF p->>'cardinality'='many' THEN result:=result||jsonb_build_object(path||'.count',jsonb_build_object('path',path,'source',p->>'target','field','count','operation','count','numeric',true));END IF;
  FOR f IN SELECT DISTINCT jsonb_array_elements_text(cols) LOOP
   IF p->>'cardinality'='one' THEN result:=result||jsonb_build_object(path||'.'||f,jsonb_build_object('path',path,'source',p->>'target','field',f,'operation','one','numeric',f=ANY(erp_reports_private.numeric_fields())));
   ELSIF f<>'count' THEN FOREACH op IN ARRAY CASE WHEN f=ANY(erp_reports_private.numeric_fields()) THEN ARRAY['sum','min','max'] ELSE ARRAY['list'] END LOOP result:=result||jsonb_build_object(path||'.'||op||'.'||f,jsonb_build_object('path',path,'source',p->>'target','field',f,'operation',op,'numeric',op<>'list'));END LOOP;
   END IF;
  END LOOP;
 END LOOP;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_report_relation_private.keys(c uuid, s text, r jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE extra jsonb:='{}';d uuid;ref uuid;profile jsonb;resource text;b uuid:=erp_branch_private.current_branch(c);
BEGIN
 -- Real foreign keys only: names and display numbers are never join keys.
 IF s IN('sales','business-sales','purchase-documents') THEN d:=(r->>'id')::uuid;
 ELSIF s IN('sales-lines','purchase-lines') THEN SELECT document_id INTO d FROM public.bf_document_lines WHERE cafe_id=c AND id::text=r->>'id';SELECT CASE WHEN kind='refund' THEN reference_id ELSE id END INTO ref FROM public.bf_documents WHERE cafe_id=c AND id=d;extra:=extra||jsonb_build_object('documentId',d,'invoiceId',ref);
 ELSIF s IN('journal','cash-flow','sales-payments','purchase-payments') THEN SELECT document_id INTO d FROM public.bf_journal WHERE cafe_id=c AND id::text=r->>'id';SELECT CASE WHEN kind IN('sale','purchase') THEN id ELSE reference_id END INTO ref FROM public.bf_documents WHERE cafe_id=c AND id=d;extra:=extra||jsonb_build_object('invoiceId',ref,'documentId',d);
 ELSIF s='customers' THEN
  SELECT erp_customer_private.profile(p) INTO profile FROM public.bf_parties p WHERE cafe_id=c AND id::text=r->>'id';
  extra:=jsonb_build_object('categoryIds',coalesce(profile->'categories','[]'),'statusId',profile->'statusId','assignedUserId',profile->'assignedUserId','priceListId',(SELECT price_list_id FROM public.erp_customer_portal_links WHERE cafe_id=c AND customer_id::text=r->>'id'));
 ELSIF s='employees' THEN extra:=jsonb_build_object('userId',(SELECT user_id FROM public.erp_hr_employees WHERE cafe_id=c AND id::text=r->>'id'));
 ELSIF s='manufacturing' THEN SELECT jsonb_build_object('productId',o.payload->>'productId','warehouseId',(SELECT warehouse_id FROM public.bf_documents WHERE cafe_id=c AND id=o.output_document_id)) INTO extra FROM public.erp_mfg_orders o WHERE cafe_id=c AND id::text=r->>'id';
 END IF;
 IF d IS NOT NULL THEN extra:=extra||jsonb_build_object('branchId',(SELECT branch_id FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=d));END IF;
 IF s IN('customers','customer-aging','customer-credits') AND coalesce(r->>'customerId','')='' AND r->>'id'~'^[0-9a-f-]{36}$' THEN extra:=extra||jsonb_build_object('customerId',r->>'id');END IF;
 IF s IN('suppliers','supplier-aging') THEN extra:=extra||jsonb_build_object('supplierId',r->>'id');END IF;
 resource:=CASE s WHEN 'customers' THEN 'customer' WHEN 'suppliers' THEN 'supplier' WHEN 'item-directory' THEN 'item' WHEN 'accounts' THEN 'account' END;
 IF resource IS NOT NULL THEN extra:=extra||jsonb_build_object('branchIds',coalesce((SELECT jsonb_agg(branch_id) FROM public.erp_branch_resources WHERE cafe_id=c AND kind=resource AND record_id::text=r->>'id' AND(b IS NULL OR branch_id=b) AND erp_branch_private.branch_allowed(c,branch_id)),'[]'));END IF;
 RETURN r||coalesce(extra,'{}');
END $function$

CREATE OR REPLACE FUNCTION erp_report_relation_private.matches(r jsonb, q jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE x jsonb;k text;v text;matched boolean;any_match boolean:=false;numerics text[]:=erp_report_relation_private.numeric_fields(q);BEGIN
 FOR k,v IN SELECT key,value FROM jsonb_each_text(q->'filters') LOOP IF v<>'' AND coalesce(r->>k,'')<>v THEN RETURN false;END IF;END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(q->'conditions') LOOP k:=x->>'field';v:=x->>'value';
  IF k=ANY(numerics) AND x->>'operator' IN('gte','lte') THEN IF v!~'^-?[0-9]+([.][0-9]+)?$' THEN RAISE EXCEPTION 'قيمة شرط العلاقة ليست رقمًا';END IF;matched:=coalesce(CASE x->>'operator' WHEN 'gte' THEN(r->>k)::numeric>=v::numeric ELSE(r->>k)::numeric<=v::numeric END,false);
  ELSE matched:=coalesce(erp_reports_private.condition(r,x),false);END IF;
  IF q->>'conditionMode'='all' AND NOT matched THEN RETURN false;END IF;any_match:=any_match OR matched;
 END LOOP;RETURN q->>'conditionMode'<>'any' OR jsonb_array_length(q->'conditions')=0 OR any_match;
END $function$

CREATE OR REPLACE FUNCTION erp_report_relation_private.metric(rows jsonb, field text, operation text, source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE value jsonb;BEGIN
 IF operation='count' THEN RETURN to_jsonb(jsonb_array_length(rows));END IF;
 IF operation='list' THEN SELECT to_jsonb(coalesce(string_agg(v,'، ' ORDER BY v),'')) INTO value FROM(SELECT DISTINCT x->>field v FROM jsonb_array_elements(rows)x WHERE coalesce(x->>field,'')<>'')q;IF length(value#>>'{}')>10000 THEN RAISE EXCEPTION 'قائمة العلاقة طويلة حدد شروطًا أدق' USING ERRCODE='54000';END IF;RETURN value;END IF;
 IF operation='one' THEN IF jsonb_array_length(rows)>1 THEN RAISE EXCEPTION 'علاقة السجل المفرد أعادت عدة سجلات';END IF;RETURN coalesce(rows->0->field,'null');END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(rows)x WHERE x->field='null'::jsonb) THEN RETURN 'null';END IF;
 IF operation='sum' THEN SELECT to_jsonb(coalesce(sum((x->>field)::numeric),0)) INTO value FROM jsonb_array_elements(rows)x WHERE jsonb_typeof(x->field)='number';RETURN value;END IF;
 SELECT CASE operation WHEN 'min' THEN to_jsonb(min((x->>field)::numeric)) WHEN 'max' THEN to_jsonb(max((x->>field)::numeric)) END INTO value FROM jsonb_array_elements(rows)x WHERE jsonb_typeof(x->field)='number';RETURN coalesce(value,'null');
END $function$

CREATE OR REPLACE FUNCTION erp_report_relation_private.path(source text, path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE target text:=source;k text;e jsonb;visited text[]:=ARRAY[source];many boolean:=false;labels text[]:='{}';chain jsonb:='[]';
BEGIN
 IF path!~'^[A-Za-z][A-Za-z0-9_-]*([.][A-Za-z][A-Za-z0-9_-]*){0,2}$' OR length(path)>120 THEN RAISE EXCEPTION 'مسار العلاقة غير صالح';END IF;
 FOREACH k IN ARRAY string_to_array(path,'.') LOOP
  SELECT value INTO e FROM jsonb_array_elements(erp_report_relation_private.edges()) WHERE value->>'source'=target AND value->>'key'=k;
  IF e IS NULL OR e->>'target'=ANY(visited) THEN RAISE EXCEPTION 'العلاقة غير متاحة أو تعيد المصدر نفسه';END IF;
  target:=e->>'target';visited:=array_append(visited,target);many:=many OR e->>'cardinality'='many';labels:=array_append(labels,e->>'label');chain:=chain||jsonb_build_array(e);
 END LOOP;
 RETURN jsonb_build_object('target',target,'cardinality',CASE WHEN many THEN 'many' ELSE 'one' END,'label',array_to_string(labels,' / '),'chain',chain);
END $function$

CREATE OR REPLACE FUNCTION erp_report_relation_private.prepare(c uuid, q jsonb)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE all_fields jsonb:=erp_report_relation_private.fields(q);pool jsonb:='{}';indexes jsonb:='{}';datasets text[]:=ARRAY[q->>'source'];historical text[]:='{}';source text;path text;spec jsonb;e jsonb;rows jsonb;idx jsonb;r jsonb;result jsonb;linked jsonb;parents jsonb;parent_path text;last_edge jsonb;keys text[];field record;selected text[];n integer:=0;traversals integer:=0;
BEGIN
 PERFORM erp_report_relation_private.authorize(c,q);
 SELECT array_agg(DISTINCT key) INTO selected FROM(SELECT jsonb_array_elements_text((q->'columns')||(q->'groupBy')||jsonb_build_array(q->>'sortBy')) key UNION SELECT jsonb_object_keys(q->'filters') UNION SELECT value->>'field' FROM jsonb_array_elements(q->'conditions'))v;
 FOR path IN SELECT jsonb_array_elements_text(q->'relationPaths') LOOP FOR e IN SELECT value FROM jsonb_array_elements(erp_report_relation_private.path(q->>'source',path)->'chain') LOOP IF e->>'cardinality'='one' THEN historical:=array_append(historical,e->>'target');END IF;IF NOT(e->>'target'=ANY(datasets)) THEN datasets:=array_append(datasets,e->>'target');END IF;END LOOP;END LOOP;
 FOREACH source IN ARRAY datasets LOOP
  rows:=erp_report_relation_private.dataset(c,source,(q->>'from')::date,(q->>'to')::date,source=ANY(historical));n:=n+jsonb_array_length(rows);IF n>20000 THEN RAISE EXCEPTION 'تجاوزت مصادر العلاقات عشرين ألف سجل حدد فترة أو مصادر أقل' USING ERRCODE='54000';END IF;
  pool:=pool||jsonb_build_object(source,rows);
 END LOOP;
 IF octet_length(pool::text)>20000000 THEN RAISE EXCEPTION 'حجم بيانات العلاقات كبير حدد فترة أصغر' USING ERRCODE='54000';END IF;
 FOR e IN SELECT DISTINCT value FROM jsonb_array_elements(erp_report_relation_private.edges()) WHERE value->>'source'=ANY(datasets) AND value->>'target'=ANY(datasets) LOOP
  SELECT coalesce(jsonb_object_agg(k,rs),'{}') INTO idx FROM(SELECT x->>(e->>'targetKey') k,jsonb_agg(x) rs FROM jsonb_array_elements(pool->(e->>'target'))x WHERE coalesce(x->>(e->>'targetKey'),'')<>'' GROUP BY 1)v;
  indexes:=indexes||jsonb_build_object((e->>'target')||':'||(e->>'targetKey'),idx);
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(pool->(q->>'source')) WHERE value->>'date' IS NULL OR(value->>'date')::date BETWEEN(q->>'from')::date AND(q->>'to')::date LOOP
  result:=r||'{"_relationRows":{}}'::jsonb;
  FOR path IN SELECT value FROM jsonb_array_elements_text(q->'relationPaths')v(value) ORDER BY length(value),value LOOP
   spec:=erp_report_relation_private.path(q->>'source',path);last_edge:=spec->'chain'->-1;parent_path:=CASE WHEN strpos(path,'.')>0 THEN regexp_replace(path,'[.][^.]+$','') ELSE '' END;
   parents:=CASE WHEN parent_path='' THEN jsonb_build_array(r) ELSE result#>ARRAY['_relationRows',parent_path] END;
   SELECT array_agg(DISTINCT k) INTO keys FROM jsonb_array_elements(parents)p CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(p->(last_edge->>'sourceKey'))='array' THEN p->(last_edge->>'sourceKey') ELSE jsonb_build_array(p->(last_edge->>'sourceKey')) END)k WHERE k IS NOT NULL AND k<>'';
   SELECT coalesce(jsonb_agg(x),'[]') INTO linked FROM(SELECT DISTINCT ON(x->>'id') x FROM unnest(keys)k CROSS JOIN LATERAL jsonb_array_elements(coalesce(indexes#>ARRAY[(last_edge->>'target')||':'||(last_edge->>'targetKey'),k],'[]'))x WHERE last_edge->>'cardinality'='one' OR x->>'date' IS NULL OR(x->>'date')::date BETWEEN(q->>'from')::date AND(q->>'to')::date ORDER BY x->>'id')v;
   traversals:=traversals+jsonb_array_length(linked);IF traversals>100000 THEN RAISE EXCEPTION 'العلاقات كثيرة حدد شروط المصدر أو فترة أصغر' USING ERRCODE='54000';END IF;
   IF spec->>'cardinality'='one' AND jsonb_array_length(linked)>1 THEN RAISE EXCEPTION 'علاقة مفردة غير متسقة مع بيانات المصدر';END IF;
   result:=jsonb_set(result,ARRAY['_relationRows',path],linked);
   FOR field IN SELECT key,value FROM jsonb_each(all_fields) WHERE value->>'path'=path AND key=ANY(selected) LOOP result:=result||jsonb_build_object(field.key,erp_report_relation_private.metric(linked,field.value->>'field',field.value->>'operation',field.value->>'source'));END LOOP;
  END LOOP;
  RETURN NEXT result;
 END LOOP;RETURN;
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.aggregate_metric(records jsonb[], field text, source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$DECLARE a numeric;b numeric;BEGIN
 IF field IN('average','turnover') AND source='stock-turnover' THEN SELECT coalesce(sum((r->>'opening')::numeric+(r->>'closing')::numeric),0)/2,coalesce(sum((r->>'issued')::numeric),0) INTO a,b FROM unnest(records)r;RETURN CASE WHEN field='average' THEN to_jsonb(a) WHEN a>0 THEN to_jsonb(b/a) ELSE 'null'::jsonb END;END IF;
 IF field='average' AND source='stock' THEN IF EXISTS(SELECT 1 FROM unnest(records)r WHERE r->'value'='null'::jsonb) THEN RETURN 'null'::jsonb;END IF;SELECT sum((r->>'value')::numeric),sum((r->>'closing')::numeric) INTO a,b FROM unnest(records)r;RETURN CASE WHEN b<>0 THEN to_jsonb(a/b) ELSE 'null'::jsonb END;END IF;
 IF EXISTS(SELECT 1 FROM unnest(records)r WHERE r?field AND r->field='null'::jsonb) THEN RETURN 'null'::jsonb;END IF;RETURN to_jsonb((SELECT coalesce(sum((r->>field)::numeric),0) FROM unnest(records)r WHERE jsonb_typeof(r->field)='number'));
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.authorize_source(c uuid, s text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE d text;r text;BEGIN
 r:=erp_reports_private.authorize(c);SELECT domain INTO d FROM erp_reports_private.sources WHERE id=s;IF NOT FOUND THEN RAISE EXCEPTION 'مصدر التقرير غير متاح';END IF;
 IF r='warehouse' AND d NOT IN('inventory','manufacturing') THEN RAISE EXCEPTION 'مصدر التقرير خارج صلاحية المخازن' USING ERRCODE='42501';END IF;
 IF d IN('settings','activity') THEN IF r<>'owner' THEN RAISE EXCEPTION 'هذا التقرير متاح لمالك العلامة' USING ERRCODE='42501';END IF;ELSIF d<>'sales' THEN PERFORM erp_access_private.assert_allowed(c,d,'read');END IF;
 IF s='cost-centers' THEN PERFORM erp_access_private.assert_allowed(c,'finance','read');PERFORM erp_access_private.assert_allowed(c,'purchases','read');END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.customer_facts_before_advance_invoices(c uuid, s text, f date, t date)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE x jsonb;r jsonb;BEGIN
 IF s IN('customers','suppliers') THEN
  RETURN QUERY SELECT erp_reports_private.fact(p.id::text,NULL,jsonb_build_object('name',p.name,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'phone',to_jsonb(p)->>'phone','email',to_jsonb(p)->>'email','country',to_jsonb(p)->>'country','state',to_jsonb(p)->>'state','city',to_jsonb(p)->>'city','status',CASE WHEN p.active THEN 'active' ELSE 'inactive' END,'href','/dashboard/system/'||CASE WHEN p.kind='customer' THEN 'customers/' ELSE 'purchases/suppliers/' END||p.id)) FROM public.bf_parties p WHERE p.cafe_id=c AND p.kind=CASE s WHEN 'customers' THEN 'customer' ELSE 'supplier' END;RETURN;
 ELSIF s IN('customer-aging','supplier-aging') THEN
  -- Document balances are current, aged against the selected closing date.
  RETURN QUERY WITH invoices AS(SELECT p.id,p.name,coalesce(nullif(to_jsonb(e)->>'due_date','')::date,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date) due,(brand_finance_private.document_state(c,d.id)->>'outstanding')::numeric amount FROM public.bf_documents d JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=d.party_id LEFT JOIN public.bf_invoice_extensions e ON e.cafe_id=d.cafe_id AND e.document_id=d.id WHERE d.cafe_id=c AND d.kind=CASE s WHEN 'customer-aging' THEN 'sale' ELSE 'purchase' END AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<=t)
  SELECT erp_reports_private.fact(id::text,NULL,jsonb_build_object('name',name,'current',coalesce(sum(amount) FILTER(WHERE due>=t),0),'age30',coalesce(sum(amount) FILTER(WHERE t-due BETWEEN 1 AND 30),0),'age60',coalesce(sum(amount) FILTER(WHERE t-due BETWEEN 31 AND 60),0),'age90',coalesce(sum(amount) FILTER(WHERE t-due BETWEEN 61 AND 90),0),'ageOlder',coalesce(sum(amount) FILTER(WHERE t-due>90),0),'outstanding',sum(amount))) FROM invoices GROUP BY id,name;RETURN;
 ELSIF s='customer-credits' THEN
  RETURN QUERY SELECT erp_reports_private.fact(p.id::text,NULL,jsonb_build_object('customer',p.name,'name',p.name,'amount',brand_finance_private.customer_credit_balance(c,p.id),'remaining',brand_finance_private.customer_credit_balance(c,p.id),'status',CASE WHEN p.active THEN 'active' ELSE 'inactive' END)) FROM public.bf_parties p WHERE p.cafe_id=c AND p.kind='customer' AND brand_finance_private.customer_credit_balance(c,p.id)<>0;RETURN;
 ELSIF s='credit-charges' THEN
  RETURN QUERY SELECT erp_reports_private.fact(ch.id::text,ch.starts_on,jsonb_build_object('number',ch.number,'customer',p.name,'customerId',p.id,'type',ct.name,'typeId',ct.id,'unit',ct.unit,'quantity',ch.quantity,'remaining',ch.quantity-coalesce((SELECT sum(a.quantity) FROM public.erp_credit_allocations a WHERE a.cafe_id=c AND a.charge_id=ch.id),0),'starts',ch.starts_on,'ends',ch.expires_on,'status',CASE WHEN ch.suspended THEN 'suspended' WHEN ch.expires_on<current_date THEN 'expired' WHEN ch.starts_on>current_date THEN 'pending' ELSE 'active' END,'href','/dashboard/system/credits/charges/'||ch.id)) FROM public.erp_credit_charges ch JOIN public.bf_parties p ON p.cafe_id=ch.cafe_id AND p.id=ch.customer_id JOIN public.erp_credit_types ct ON ct.cafe_id=ch.cafe_id AND ct.id=ch.type_id WHERE ch.cafe_id=c;RETURN;
 ELSIF s='credit-usages' THEN
  RETURN QUERY SELECT erp_reports_private.fact(u.id::text,u.used_on,jsonb_build_object('number',u.number,'customer',p.name,'customerId',p.id,'type',ct.name,'typeId',ct.id,'unit',ct.unit,'quantity',CASE WHEN u.voided THEN 0 ELSE u.quantity END,'status',CASE WHEN u.voided THEN 'void' ELSE 'active' END,'href','/dashboard/system/credits/usages/'||u.id)) FROM public.erp_credit_usages u JOIN public.bf_parties p ON p.cafe_id=u.cafe_id AND p.id=u.customer_id JOIN public.erp_credit_types ct ON ct.cafe_id=u.cafe_id AND ct.id=u.type_id WHERE u.cafe_id=c;RETURN;
 ELSIF s='memberships' THEN
  RETURN QUERY SELECT erp_reports_private.fact(m.id::text,m.joined_on,jsonb_build_object('number',m.number,'customer',p.name,'customerId',p.id,'package',pkg.name,'starts',m.joined_on,'ends',(SELECT max(erp_membership_private.end_date(c,rr.id)) FROM public.erp_membership_renewals rr WHERE rr.cafe_id=c AND rr.membership_id=m.id AND rr.status='paid'),'status',erp_membership_private.status(c,m.id),'href','/dashboard/system/memberships/'||m.id)) FROM public.erp_memberships m JOIN public.bf_parties p ON p.cafe_id=m.cafe_id AND p.id=m.customer_id JOIN public.erp_credit_packages pkg ON pkg.cafe_id=m.cafe_id AND pkg.id=m.package_id WHERE m.cafe_id=c AND NOT m.deleted;RETURN;
 ELSIF s='membership-renewals' THEN
  RETURN QUERY SELECT erp_reports_private.fact(r.id::text,r.invoice_date,jsonb_build_object('number',r.number,'customer',p.name,'customerId',p.id,'package',pkg.name,'starts',r.starts_on,'ends',CASE WHEN r.starts_on IS NOT NULL THEN erp_membership_private.end_date(c,r.id) END,'amount',CASE WHEN r.invoice_id IS NULL THEN NULL ELSE r.invoice_total END,'paid',CASE WHEN r.invoice_id IS NULL THEN 0 ELSE(brand_finance_private.document_state(c,r.invoice_id)->>'paid')::numeric END,'status',r.status,'href','/dashboard/system/memberships/'||r.membership_id)) FROM public.erp_membership_renewals r JOIN public.bf_parties p ON p.cafe_id=r.cafe_id AND p.id=r.customer_id JOIN public.erp_credit_packages pkg ON pkg.cafe_id=r.cafe_id AND pkg.id=r.package_id WHERE r.cafe_id=c AND r.kind='membership';RETURN;
 END IF;RAISE EXCEPTION 'مصدر تقرير العملاء غير معروف';
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.employee_facts(c uuid, s text, f date, t date)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE snap jsonb;x jsonb;y jsonb;b jsonb;BEGIN
 IF s='employees' THEN
  RETURN QUERY SELECT erp_reports_private.fact(e.id::text,NULL,jsonb_build_object('number',e.code,'name',concat_ws(' ',e.first_name,e.last_name),'starts',e.payload->>'joinDate','ends',e.payload->>'endDate','status',CASE WHEN e.active THEN 'active' ELSE 'inactive' END,'href','/dashboard/system/employees/'||e.id)||erp_reports_private.employee_dimensions(c,e.id)) FROM public.erp_hr_employees e WHERE e.cafe_id=c;RETURN;
 ELSIF s='employee-documents' THEN
  RETURN QUERY SELECT erp_reports_private.fact(d.id::text,NULL,jsonb_build_object('number',d.number,'type',dt.name,'typeId',dt.id,'starts',d.issued_on,'ends',d.expires_on,'status',CASE WHEN d.expires_on<t THEN 'expired' ELSE 'valid' END,'expiry',CASE WHEN d.expires_on<t THEN 'expired' ELSE 'valid' END,'residency',CASE WHEN dt.name ILIKE '%إقام%' OR dt.name ILIKE '%اقام%' OR dt.name ILIKE '%residen%' THEN 'true' ELSE 'false' END)||erp_reports_private.employee_dimensions(c,d.employee_id)) FROM public.erp_hr_documents d JOIN public.erp_hr_document_types dt ON dt.cafe_id=d.cafe_id AND dt.id=d.type_id WHERE d.cafe_id=c;RETURN;
 ELSIF s='employee-compliance' THEN
  RETURN QUERY SELECT erp_reports_private.fact(e.id::text||':'||dt.id::text,NULL,jsonb_build_object('type',dt.name,'typeId',dt.id,'required',1,'present',CASE WHEN present THEN 1 ELSE 0 END,'missing',CASE WHEN present THEN 0 ELSE 1 END,'status',CASE WHEN present THEN 'complete' ELSE 'missing' END)||erp_reports_private.employee_dimensions(c,e.id)) FROM public.erp_hr_employees e JOIN public.erp_hr_document_types dt ON dt.cafe_id=e.cafe_id AND dt.required AND dt.active CROSS JOIN LATERAL(SELECT EXISTS(SELECT 1 FROM public.erp_hr_documents d WHERE d.cafe_id=c AND d.employee_id=e.id AND d.type_id=dt.id AND(d.expires_on IS NULL OR d.expires_on>=t))present)x WHERE e.cafe_id=c AND e.active;RETURN;
 ELSIF s='attendance' THEN
  RETURN QUERY SELECT erp_reports_private.fact(d.id::text,d.work_date,jsonb_build_object('type',coalesce(sh.name,''),'status',d.status,'scheduledHours',d.scheduled_minutes/60.0,'hours',d.worked_minutes/60.0,'days',CASE WHEN d.slot=0 THEN 1 ELSE 0 END,'lateMinutes',d.late_minutes,'earlyMinutes',d.early_minutes,'overtimeHours',d.overtime_minutes/60.0)||erp_reports_private.employee_dimensions(c,d.employee_id)) FROM public.erp_att_days d LEFT JOIN public.erp_att_shifts sh ON sh.cafe_id=d.cafe_id AND sh.id=d.shift_id WHERE d.cafe_id=c;RETURN;
 ELSIF s='leave-balance' THEN
  FOR x IN SELECT jsonb_build_object('employeeId',e.id,'typeId',lt.id,'type',lt.name) FROM public.erp_hr_employees e JOIN public.erp_att_leave_types lt ON lt.cafe_id=e.cafe_id WHERE e.cafe_id=c AND e.active LOOP
   b:=erp_attendance_private.balance(c,(x->>'employeeId')::uuid,(x->>'typeId')::uuid,t);
   RETURN NEXT erp_reports_private.fact(x->>'employeeId'||':'||(x->>'typeId'),NULL,x||erp_reports_private.employee_dimensions(c,(x->>'employeeId')::uuid)||jsonb_build_object('opening',(b->>'annual')::numeric,'received',(SELECT coalesce(sum(amount),0) FROM public.erp_att_balances WHERE cafe_id=c AND employee_id=(x->>'employeeId')::uuid AND leave_type_id=(x->>'typeId')::uuid AND fiscal_start=(b->>'fiscalStart')::date AND amount>0),'issued',(SELECT -coalesce(sum(amount),0) FROM public.erp_att_balances WHERE cafe_id=c AND employee_id=(x->>'employeeId')::uuid AND leave_type_id=(x->>'typeId')::uuid AND fiscal_start=(b->>'fiscalStart')::date AND amount<0),'remaining',(b->>'available')::numeric));
  END LOOP;RETURN;
 ELSIF s='shifts' THEN
  RETURN QUERY SELECT erp_reports_private.fact(sh.id::text||':'||(day->>'weekday'),NULL,jsonb_build_object('name',sh.name,'type',sh.payload->>'type','starts',day->>'start','ends',day->>'end','hours',CASE WHEN(day->>'working')::boolean THEN(extract(epoch FROM((day->>'end')::time-(day->>'start')::time))/60+CASE WHEN(day->>'end')::time<=(day->>'start')::time THEN 1440 ELSE 0 END-(day->>'breakMinutes')::numeric)/60 ELSE 0 END,'status',CASE WHEN sh.active THEN 'active' ELSE 'inactive' END,'note',(ARRAY['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'])[(day->>'weekday')::integer+1])) FROM public.erp_att_shifts sh CROSS JOIN LATERAL jsonb_array_elements(sh.payload->'days')day WHERE sh.cafe_id=c;RETURN;
 ELSIF s IN('contracts','payslips','loans') THEN
  snap:=public.erp_payroll_read(c);FOR x IN SELECT value FROM jsonb_array_elements(snap->s) LOOP
   RETURN NEXT erp_reports_private.fact(x->>'id',coalesce(nullif(x#>>'{payload,date}','')::date,(x->>'createdAt')::timestamptz::date),jsonb_build_object('number',x->>'code','name',x->>'name','starts',x#>>'{payload,start}','ends',x#>>'{payload,end}','amount',x->'total','paid',x->'paid','outstanding',CASE WHEN x->'total'='null'::jsonb THEN NULL ELSE(x->>'total')::numeric-(x->>'paid')::numeric END,'status',x->>'status','href','/dashboard/system/payroll/'||s||'/'||(x->>'id'))||coalesce(erp_reports_private.employee_dimensions(c,(x->>'employeeId')::uuid),'{}'));
  END LOOP;RETURN;
 END IF;RAISE EXCEPTION 'مصدر تقرير الموظفين غير معروف';
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.financial_facts_before_deferred_cost(c uuid, s text, f date, t date)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$BEGIN
 IF s IN('sales','purchase-documents') THEN
  RETURN QUERY SELECT erp_reports_private.fact(d.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',coalesce(to_jsonb(e)->>'display_number',d.number::text),'name',coalesce(p.name,''),'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'customerId',CASE WHEN p.kind='customer' THEN p.id END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'supplierId',CASE WHEN p.kind='supplier' THEN p.id END,'employeeId',d.created_by,'employee',coalesce(st.name,''),'kind',d.kind,'note',d.note,'net',d.subtotal-d.discount,'tax',d.tax,'amount',d.total,'paid',coalesce((state->>'paid')::numeric,d.paid),'outstanding',coalesce((state->>'outstanding')::numeric,0),'refunded',coalesce((state->>'refunded_total')::numeric,0),'status',CASE WHEN coalesce((state->>'refunded')::boolean,false) THEN 'refunded' WHEN coalesce((state->>'outstanding')::numeric,0)<=0 THEN 'paid' WHEN coalesce((state->>'paid')::numeric,d.paid)>0 THEN 'partial' ELSE 'unpaid' END,'currency','SAR','electronicStatus',coalesce(to_jsonb(e)->>'e_invoice_status','not_submitted'),'href',CASE WHEN d.kind='sale' THEN '/dashboard/finance?section=sales&view=invoice&invoice=' ELSE '/dashboard/system/purchases/invoices/' END||d.id::text)||erp_reports_private.document_branch(c,to_jsonb(d)))
  FROM public.bf_documents d LEFT JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=d.party_id LEFT JOIN public.bf_invoice_extensions e ON e.cafe_id=d.cafe_id AND e.document_id=d.id LEFT JOIN public.bf_staff st ON st.cafe_id=d.cafe_id AND st.user_id=d.created_by CROSS JOIN LATERAL(SELECT brand_finance_private.document_state(c,d.id) state)x WHERE d.cafe_id=c AND d.kind=CASE s WHEN 'sales' THEN 'sale' ELSE 'purchase' END;RETURN;
 ELSIF s IN('sales-lines','purchase-lines') THEN
  RETURN QUERY SELECT erp_reports_private.fact(l.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',d.number,'product',l.name,'productId',coalesce(to_jsonb(l)->>'inventory_item_id',l.product_id::text,l.item_id::text),'category',coalesce(cat.name,icat.name,''),'categoryId',coalesce(cat.id,icat.id),'warehouse',coalesce(w.name,''),'warehouseId',d.warehouse_id,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'customerId',CASE WHEN p.kind='customer' THEN p.id END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'supplierId',CASE WHEN p.kind='supplier' THEN p.id END,'employeeId',d.created_by,'employee',coalesce(st.name,''),'kind',d.kind,'quantity',sign*l.quantity,'net',sign*l.net,'tax',sign*l.tax,'amount',sign*(l.net+l.tax),'cost',CASE WHEN l.cost_status IN('unknown','untracked') OR l.cost_status='legacy' AND l.cost=0 THEN NULL ELSE sign*coalesce((to_jsonb(l)->>'allocated_cost')::numeric,l.cost) END,'profit',CASE WHEN l.cost_status IN('unknown','untracked') OR l.cost_status='legacy' AND l.cost=0 THEN NULL ELSE sign*(l.net-coalesce((to_jsonb(l)->>'allocated_cost')::numeric,l.cost)) END,'unit',coalesce(to_jsonb(l)->>'unit_label',''),'href',CASE s WHEN 'sales-lines' THEN '/dashboard/finance?section=sales&view=invoice&invoice=' ELSE '/dashboard/system/purchases/invoices/' END||coalesce(d.reference_id,d.id)::text)||erp_reports_private.document_branch(c,to_jsonb(d)))
  FROM public.bf_document_lines l JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=l.document_id LEFT JOIN public.bf_documents original ON original.cafe_id=d.cafe_id AND original.id=d.reference_id LEFT JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=d.party_id LEFT JOIN public.menu_products product ON product.cafe_id=l.cafe_id AND product.id=l.product_id LEFT JOIN public.menu_categories cat ON cat.cafe_id=product.cafe_id AND cat.id=product.category_id LEFT JOIN public.erp_inventory_items item ON item.cafe_id=l.cafe_id AND item.item_id=coalesce(nullif(to_jsonb(l)->>'inventory_item_id','')::uuid,l.item_id) LEFT JOIN public.erp_inventory_catalogs icat ON icat.cafe_id=item.cafe_id AND icat.id=item.category_id LEFT JOIN public.bf_warehouses w ON w.cafe_id=d.cafe_id AND w.id=d.warehouse_id LEFT JOIN public.bf_staff st ON st.cafe_id=d.cafe_id AND st.user_id=d.created_by CROSS JOIN LATERAL(SELECT CASE WHEN d.kind='refund' THEN -1 ELSE 1 END sign)x WHERE l.cafe_id=c AND(d.kind=CASE s WHEN 'sales-lines' THEN 'sale' ELSE 'purchase' END OR d.kind='refund' AND original.kind=CASE s WHEN 'sales-lines' THEN 'sale' ELSE 'purchase' END);RETURN;
 ELSIF s IN('journal','cash-flow','sales-payments','purchase-payments') THEN
  RETURN QUERY SELECT erp_reports_private.fact(j.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',d.number,'name',a.name,'account',a.name,'accountId',a.id,'accountKind',a.kind,'accountClass',CASE WHEN a.kind IN('expense','revenue') THEN 'income' WHEN a.kind IN('vat_input','vat_output') THEN 'tax' ELSE 'balance' END,'kind',d.kind,'note',d.note,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'customerId',CASE WHEN p.kind='customer' THEN p.id END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'supplierId',CASE WHEN p.kind='supplier' THEN p.id END,'employeeId',d.created_by,'employee',coalesce(st.name,''),'debit',j.debit,'credit',j.credit,'balance',j.debit-j.credit,'received',j.debit,'issued',j.credit,'profit',CASE WHEN s='cash-flow' THEN CASE WHEN d.kind IN('sale','purchase','settlement','expense','receipt','refund') THEN j.debit-j.credit ELSE 0 END ELSE CASE WHEN a.kind IN('expense','revenue') THEN j.credit-j.debit ELSE 0 END END,'amount',CASE WHEN s='purchase-payments' THEN j.credit-j.debit ELSE j.debit-j.credit END,'status','posted','href','/dashboard/system/accounting/reports')||erp_reports_private.document_branch(c,to_jsonb(d)))
  FROM public.bf_journal j JOIN public.bf_documents d ON d.cafe_id=j.cafe_id AND d.id=j.document_id JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id LEFT JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=coalesce(j.party_id,d.party_id) LEFT JOIN public.bf_documents parent ON parent.cafe_id=d.cafe_id AND parent.id=d.reference_id LEFT JOIN public.bf_staff st ON st.cafe_id=d.cafe_id AND st.user_id=d.created_by WHERE j.cafe_id=c AND(s='journal' OR a.kind IN('cash','bank','pos') AND(s='cash-flow' OR s='sales-payments' AND(d.kind='sale' OR d.kind IN('settlement','refund') AND parent.kind='sale') OR s='purchase-payments' AND(d.kind='purchase' OR d.kind IN('settlement','refund') AND parent.kind='purchase')));RETURN;
 ELSIF s='accounts' THEN
  RETURN QUERY SELECT erp_reports_private.fact(a.id::text,NULL,jsonb_build_object('account',a.name,'accountId',a.id,'number',a.code,'name',a.name,'accountKind',a.kind,'accountClass',CASE WHEN a.kind IN('expense','revenue') THEN 'income' WHEN a.kind IN('vat_input','vat_output') THEN 'tax' ELSE 'balance' END,'opening',coalesce(sum(j.debit-j.credit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<f),0),'debit',coalesce(sum(j.debit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),'credit',coalesce(sum(j.credit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),'closing',coalesce(sum(j.debit-j.credit),0),'balance',CASE WHEN a.kind IN('revenue','expense') THEN coalesce(sum(j.credit-j.debit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0) ELSE coalesce(sum(j.debit-j.credit),0) END,'status',CASE WHEN a.active THEN 'active' ELSE 'inactive' END))
  FROM public.bf_accounts a LEFT JOIN(public.bf_journal j JOIN public.bf_documents d ON d.cafe_id=j.cafe_id AND d.id=j.document_id AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<=t) ON j.cafe_id=a.cafe_id AND j.account_id=a.id WHERE a.cafe_id=c AND NOT a.is_group GROUP BY a.id;RETURN;
 ELSIF s IN('customer-balances','supplier-balances') THEN
  RETURN QUERY SELECT erp_reports_private.fact(p.id::text,NULL,jsonb_build_object('name',p.name,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'customerId',CASE WHEN p.kind='customer' THEN p.id END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'supplierId',CASE WHEN p.kind='supplier' THEN p.id END,'opening',coalesce(sum(CASE p.kind WHEN 'customer' THEN j.debit-j.credit ELSE j.credit-j.debit END) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<f),0),'debit',coalesce(sum(j.debit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),'credit',coalesce(sum(j.credit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),'closing',coalesce(sum(CASE p.kind WHEN 'customer' THEN j.debit-j.credit ELSE j.credit-j.debit END),0),'status',CASE WHEN p.active THEN 'active' ELSE 'inactive' END))
  FROM public.bf_parties p LEFT JOIN(public.bf_journal j JOIN public.bf_documents d ON d.cafe_id=j.cafe_id AND d.id=j.document_id AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<=t JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id AND a.kind=CASE s WHEN 'customer-balances' THEN 'receivable' ELSE 'payable' END) ON j.cafe_id=p.cafe_id AND j.party_id=p.id WHERE p.cafe_id=c AND p.kind=CASE s WHEN 'customer-balances' THEN 'customer' ELSE 'supplier' END GROUP BY p.id;RETURN;
 ELSIF s IN('expenses','receipts') THEN
  RETURN QUERY SELECT erp_reports_private.fact(v.id::text,(v.payload->>'date')::date,jsonb_build_object('number',v.code,'name',v.payload->>'note','note',v.payload->>'note','category',coalesce(cat.name,''),'categoryId',v.category_id,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'customerId',CASE WHEN p.kind='customer' THEN p.id END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'supplierId',CASE WHEN p.kind='supplier' THEN p.id END,'account',a.name,'accountId',a.id,'net',(v.payload#>>'{calculation,net}')::numeric,'tax',(v.payload#>>'{calculation,tax}')::numeric,'amount',(v.payload#>>'{calculation,total}')::numeric,'status',v.status,'currency','SAR','href','/dashboard/system/finance/'||CASE v.kind WHEN 'expense' THEN 'expenses' ELSE 'receipts' END||'/'||v.id)) FROM public.erp_finance_vouchers v LEFT JOIN public.erp_finance_categories cat ON cat.cafe_id=v.cafe_id AND cat.id=v.category_id LEFT JOIN public.bf_parties p ON p.cafe_id=v.cafe_id AND p.id=v.party_id JOIN public.bf_accounts a ON a.cafe_id=v.cafe_id AND a.id=(v.payload->>'cashAccountId')::uuid WHERE v.cafe_id=c AND v.document_id IS NOT NULL AND v.kind=CASE s WHEN 'expenses' THEN 'expense' ELSE 'receipt' END;
  RETURN QUERY SELECT erp_reports_private.fact(v.id::text||'-reversal',(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',v.code,'name',d.note,'note',d.note,'category',coalesce(cat.name,''),'categoryId',v.category_id,'account',a.name,'accountId',a.id,'net',-(v.payload#>>'{calculation,net}')::numeric,'tax',-(v.payload#>>'{calculation,tax}')::numeric,'amount',-(v.payload#>>'{calculation,total}')::numeric,'status','reversal','currency','SAR','href','/dashboard/system/finance/'||CASE v.kind WHEN 'expense' THEN 'expenses' ELSE 'receipts' END||'/'||v.id)) FROM public.erp_finance_vouchers v JOIN public.bf_documents d ON d.cafe_id=v.cafe_id AND d.id=v.reversal_id LEFT JOIN public.erp_finance_categories cat ON cat.cafe_id=v.cafe_id AND cat.id=v.category_id JOIN public.bf_accounts a ON a.cafe_id=v.cafe_id AND a.id=(v.payload->>'cashAccountId')::uuid WHERE v.cafe_id=c AND v.kind=CASE s WHEN 'expenses' THEN 'expense' ELSE 'receipt' END;RETURN QUERY SELECT * FROM erp_reports_private.legacy_voucher_facts(c,s,f,t);RETURN;
 END IF;RAISE EXCEPTION 'مصدر الحقائق المالية غير معروف';
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.inventory_facts(c uuid, s text, f date, t date)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE x record;y jsonb;opening numeric;closing numeric;incoming numeric;outgoing numeric;v numeric;known boolean;history boolean;ages jsonb;BEGIN
 IF s='stock-movements' THEN
  RETURN QUERY SELECT erp_reports_private.fact(m.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,erp_reports_private.inventory_dimensions(c,m.item_id,m.warehouse_id)||jsonb_build_object('number',d.number,'kind',d.kind,'received',greatest(m.quantity,0),'issued',greatest(-m.quantity,0),'quantity',m.quantity,'value',CASE WHEN m.cost_status IN('known','estimated') THEN round(m.quantity*m.unit_cost,2)-m.valuation_adjustment END,'status',m.cost_status)) FROM erp_reports_private.inventory_ledger(c) m JOIN public.bf_documents d ON d.cafe_id=m.cafe_id AND d.id=m.document_id WHERE m.cafe_id=c AND erp_inventory_private.warehouse_allowed(c,m.warehouse_id);RETURN;
 ELSIF s IN('stock','stock-aging','stock-turnover') THEN
  FOR x IN SELECT * FROM public.bf_stock WHERE cafe_id=c AND erp_inventory_private.warehouse_allowed(c,warehouse_id) LOOP
   SELECT x.quantity-coalesce(sum(m.quantity) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date>=f),0),x.quantity-coalesce(sum(m.quantity) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date>t),0),coalesce(sum(greatest(m.quantity,0)) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),coalesce(sum(greatest(-m.quantity,0)) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),abs(x.quantity-coalesce(sum(m.quantity),0))<0.0005,abs(x.value-coalesce(sum(round(m.quantity*m.unit_cost,2)-m.valuation_adjustment),0))<0.02 AND coalesce(bool_and(m.cost_status IN('known','estimated')),false),x.value-coalesce(sum(round(m.quantity*m.unit_cost,2)-m.valuation_adjustment) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date>t),0) INTO opening,closing,incoming,outgoing,history,known,v FROM erp_reports_private.inventory_ledger(c) m JOIN public.bf_documents d ON d.cafe_id=m.cafe_id AND d.id=m.document_id WHERE m.cafe_id=c AND m.item_id=x.item_id AND m.warehouse_id=x.warehouse_id;
   IF t>=current_date THEN v:=x.value;known:=x.cost_known;END IF;
   y:=erp_reports_private.inventory_dimensions(c,x.item_id,x.warehouse_id)||jsonb_build_object('opening',opening,'received',incoming,'issued',outgoing,'closing',closing,'quantity',closing,'average',CASE WHEN s='stock-turnover' THEN(opening+closing)/2 WHEN known AND closing<>0 THEN v/closing END,'value',CASE WHEN known THEN v END,'turnover',CASE WHEN opening+closing>0 THEN outgoing/((opening+closing)/2) END,'status',CASE WHEN NOT history THEN 'incomplete_history' WHEN NOT known THEN 'unknown_cost' ELSE 'known' END);
   IF s='stock-aging' THEN
    WITH receipts AS(SELECT m.id,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date dated,m.quantity,coalesce(sum(m.quantity) OVER(ORDER BY d.created_at DESC,m.created_at DESC,m.id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) later FROM erp_reports_private.inventory_ledger(c) m JOIN public.bf_documents d ON d.cafe_id=m.cafe_id AND d.id=m.document_id WHERE m.cafe_id=c AND m.item_id=x.item_id AND m.warehouse_id=x.warehouse_id AND m.quantity>0 AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<=t),remaining AS(SELECT dated,least(quantity,greatest(0,closing-later)) q FROM receipts)
    SELECT jsonb_build_object('age30',CASE WHEN history THEN coalesce(sum(q) FILTER(WHERE t-dated<=30),0) END,'age60',CASE WHEN history THEN coalesce(sum(q) FILTER(WHERE t-dated BETWEEN 31 AND 60),0) END,'age90',CASE WHEN history THEN coalesce(sum(q) FILTER(WHERE t-dated BETWEEN 61 AND 90),0) END,'ageOlder',CASE WHEN history THEN coalesce(sum(q) FILTER(WHERE t-dated>90),0) END) INTO ages FROM remaining;y:=y||ages;
   END IF;RETURN NEXT erp_reports_private.fact(x.item_id::text||':'||x.warehouse_id::text,NULL,y);
  END LOOP;RETURN;
 ELSIF s='stock-requests' THEN
  RETURN QUERY SELECT erp_reports_private.fact(l.id::text,d.effective_on,erp_reports_private.inventory_dimensions(c,l.item_id,d.warehouse_id)||jsonb_build_object('number',d.code,'kind',CASE WHEN original.kind IN('sale','purchase') THEN original.kind ELSE fd.kind END,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'quantity',l.quantity*l.factor,'status',d.status,'href','/dashboard/system/inventory/'||CASE d.kind WHEN 'request' THEN 'requests' ELSE 'requisitions' END||'/'||d.id)) FROM public.erp_inventory_documents d JOIN public.erp_inventory_lines l ON l.cafe_id=d.cafe_id AND l.document_id=d.id LEFT JOIN public.bf_documents fd ON fd.cafe_id=d.cafe_id AND fd.id=d.finance_document_id LEFT JOIN public.bf_documents original ON original.cafe_id=fd.cafe_id AND original.id=fd.reference_id LEFT JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=d.party_id WHERE d.cafe_id=c AND erp_inventory_private.warehouse_allowed(c,d.warehouse_id);RETURN;
 ELSIF s='manufacturing' THEN
  RETURN QUERY SELECT erp_reports_private.fact(o.id::text,(coalesce(d.created_at,o.created_at) AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',o.code,'product',o.name,'kind','order','quantity',o.output_quantity,'cost',o.material_cost+o.additional_cost,'status',o.status,'href','/dashboard/system/manufacturing/orders/'||o.id)) FROM public.erp_mfg_orders o LEFT JOIN public.bf_documents d ON d.cafe_id=o.cafe_id AND d.id=o.output_document_id WHERE o.cafe_id=c AND(d.warehouse_id IS NULL OR erp_inventory_private.warehouse_allowed(c,d.warehouse_id)) AND NOT EXISTS(SELECT 1 FROM public.erp_mfg_material_issues mi WHERE mi.cafe_id=c AND mi.order_id=o.id AND NOT erp_inventory_private.warehouse_allowed(c,mi.warehouse_id));RETURN;
 ELSIF s='assets' THEN
  RETURN QUERY SELECT erp_reports_private.fact(a.id::text,NULL,jsonb_build_object('number',a.code,'name',a.name,'category',cat.name,'amount',a.gross_value,'cost',a.accumulated_depreciation,'balance',a.gross_value-a.accumulated_depreciation,'status',a.status,'starts',a.acquired_on,'employee',(SELECT string_agg(DISTINCT coalesce(e.first_name||' '||e.last_name,st.name),'، ') FROM public.erp_asset_units u LEFT JOIN public.erp_hr_employees e ON e.cafe_id=u.cafe_id AND e.id=nullif(to_jsonb(u)->>'employee_profile_id','')::uuid LEFT JOIN public.bf_staff st ON st.cafe_id=u.cafe_id AND st.user_id=u.employee_id WHERE u.cafe_id=c AND u.asset_id=a.id AND u.status='in_service'),'href','/dashboard/system/assets/'||a.id)) FROM public.erp_assets a LEFT JOIN public.bf_accounts cat ON cat.cafe_id=a.cafe_id AND cat.id=(a.payload->>'assetAccountId')::uuid WHERE a.cafe_id=c;RETURN;
 END IF;RAISE EXCEPTION 'مصدر تقرير المخزون غير معروف';
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.matches(r jsonb, q jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$DECLARE k text;v text;condition jsonb;matched boolean;any_match boolean:=false;BEGIN
 FOR k,v IN SELECT key,value FROM jsonb_each_text(coalesce(q->'filters','{}')) LOOP IF v<>'' AND coalesce(r->>k,'')<>v THEN RETURN false;END IF;END LOOP;
 FOR condition IN SELECT * FROM jsonb_array_elements(coalesce(q->'conditions','[]')) LOOP matched:=coalesce(erp_reports_private.condition(r,condition),false);IF q->>'conditionMode'='all' AND NOT matched THEN RETURN false;END IF;any_match:=any_match OR matched;END LOOP;
 RETURN q->>'conditionMode'<>'any' OR jsonb_array_length(coalesce(q->'conditions','[]'))=0 OR any_match;
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.operational_facts(c uuid, s text, f date, t date)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE snap jsonb;x jsonb;y jsonb;dim jsonb;doc public.bf_documents;duration numeric;costs jsonb;BEGIN
 IF s='time' THEN
  snap:=public.erp_time_read(c,f,t);costs:=public.erp_time_cost_report(c,f,t);FOR x IN SELECT value FROM jsonb_array_elements(snap->'entries') LOOP
   IF x->>'end' IS NULL THEN CONTINUE;END IF;duration:=extract(epoch FROM least((x->>'end')::timestamptz,(t+1)::timestamp AT TIME ZONE 'Asia/Riyadh')-greatest((x->>'start')::timestamptz,f::timestamp AT TIME ZONE 'Asia/Riyadh'))/3600;IF duration<=0 THEN CONTINUE;END IF;
   RETURN NEXT erp_reports_private.fact(x->>'id',greatest(((x->>'start')::timestamptz AT TIME ZONE 'Asia/Riyadh')::date,f),jsonb_build_object('employee',x->>'workerName','employeeId',x->>'workerId','project',x->>'projectName','projectId',x->>'projectId','activity',x->>'activityName','hours',duration,'amount',CASE WHEN(x->>'billable')::boolean THEN round(duration*(x->>'billingRate')::numeric,2) ELSE 0 END,'estimatedCost',CASE WHEN(costs->>'enabled')::boolean THEN round(duration*(x->>'costRate')::numeric,2) ELSE 0 END,'cashPaid',0,'status',CASE WHEN x->>'invoiceId' IS NOT NULL THEN 'invoiced' WHEN x->>'batchId' IS NOT NULL THEN 'reserved' ELSE 'unbilled' END,'href','/dashboard/system/time/list'));
  END LOOP;RETURN;
 ELSIF s IN('workflows','work-orders','work-order-finance') THEN
  snap:=CASE WHEN s='workflows' THEN public.erp_workflows_read(c) ELSE public.erp_work_orders_read(c) END;
  FOR x IN SELECT value FROM jsonb_array_elements(snap->'records') LOOP
   dim:=jsonb_build_object('name',coalesce(x->>'title',x->>'name'),'number',x->>'code','customer',x->>'customerName','customerId',x->>'customerId','employee',x->>'assigneeName','employeeId',x->>'assigneeId','type',(SELECT value->>'name' FROM jsonb_array_elements(coalesce(snap->'types','[]')) WHERE value->>'id'=x->>'typeId'),'status',x->>'status','budget',x->'budget','category',coalesce(x->'tags','[]'),'href','/dashboard/system/'||CASE WHEN s='workflows' THEN 'workflows/'||(x->>'typeId')||'/' ELSE 'work-orders/' END||(x->>'id'));
   IF s<>'work-order-finance' THEN
    -- Link visibility is already filtered by workflow type/state/field permissions.
    SELECT jsonb_build_object('amount',coalesce(sum(CASE WHEN a.kind='revenue' THEN j.credit-j.debit ELSE 0 END),0),'cost',coalesce(sum(CASE WHEN a.kind='expense' THEN j.debit-j.credit ELSE 0 END),0),'profit',coalesce(sum(CASE WHEN a.kind IN('revenue','expense') THEN j.credit-j.debit ELSE 0 END),0)) INTO y FROM erp_reports_private.linked_documents(c,snap->'links',(x->>'id')::uuid) d JOIN public.bf_journal j ON j.cafe_id=c AND j.document_id=d.id JOIN public.bf_accounts a ON a.cafe_id=c AND a.id=j.account_id WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t;
    IF s='workflows' AND NOT coalesce(x#>'{allowedFields,read}','[]')?'budget' THEN y:='{}';END IF;
    RETURN NEXT erp_reports_private.fact(x->>'id',NULL,dim||y);
   ELSE
    FOR doc IN SELECT * FROM erp_reports_private.linked_documents(c,snap->'links',(x->>'id')::uuid) LOOP
     RETURN NEXT erp_reports_private.fact(doc.id::text,(doc.created_at AT TIME ZONE 'Asia/Riyadh')::date,dim||jsonb_build_object('kind',doc.kind,'net',(SELECT coalesce(sum(j.credit-j.debit),0) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=doc.id AND a.kind='revenue'),'cost',(SELECT coalesce(sum(j.debit-j.credit),0) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=doc.id AND a.kind='expense'),'profit',(SELECT coalesce(sum(j.credit-j.debit),0) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.document_id=doc.id AND a.kind IN('expense','revenue'))));
    END LOOP;
   END IF;
  END LOOP;RETURN;
 ELSIF s='bookings' THEN
  RETURN QUERY SELECT erp_reports_private.fact(l.id::text,(l.starts_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',b.number,'name',l.service_name,'customer',p.name,'customerId',p.id,'employee',coalesce(st.name,''),'employeeId',l.staff_id,'branch',br.name,'branchId',b.branch_id,'starts',l.starts_at,'ends',l.ends_at,'status',b.status,'source','booking','href','/dashboard/system/bookings')) FROM public.erp_bookings b JOIN public.erp_booking_lines l ON l.cafe_id=b.cafe_id AND l.booking_id=b.id JOIN public.bf_parties p ON p.cafe_id=b.cafe_id AND p.id=b.customer_id LEFT JOIN public.bf_staff st ON st.cafe_id=l.cafe_id AND st.user_id=l.staff_id LEFT JOIN public.branches br ON br.cafe_id=b.cafe_id AND br.id=b.branch_id WHERE b.cafe_id=c;
  IF erp_access_private.allowed(c,'work_orders','read') THEN
   snap:=public.erp_work_orders_read(c);FOR x IN SELECT value FROM jsonb_array_elements(snap->'records') LOOP
    IF nullif(x->>'start','') IS NOT NULL THEN RETURN NEXT erp_reports_private.fact('work-order:'||(x->>'id'),((x->>'start')::timestamptz AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',x->>'code','name',x->>'title','customer',x->>'customerName','employee',x->>'assigneeName','status',x->>'status','source','work_order','starts',x->>'start','ends',x->>'end'));END IF;
   END LOOP;
  END IF;RETURN;
 ELSIF s='installments' THEN
  FOR x IN SELECT erp_installment_private.agreement(c,d.id) FROM public.bf_documents d JOIN public.bf_invoice_management m ON m.cafe_id=d.cafe_id AND m.document_id=d.id WHERE d.cafe_id=c AND d.kind='sale' AND jsonb_typeof(m.metadata->'schedule')='object' LOOP
   FOR y IN SELECT to_jsonb(r) FROM erp_installment_private.rows((x->>'total')::numeric,(x->>'outstanding')::numeric,(x->>'refundedTotal')::numeric,x->'schedule')r LOOP
    RETURN NEXT erp_reports_private.fact((x->>'id')||':'||(y->>'number'),(y->>'date')::date,jsonb_build_object('number',(x->>'invoiceNumber')||' / '||(y->>'number'),'customer',x->>'customerName','customerId',x->>'customerId','due',y->>'date','amount',y->'amount','paid',y->'paid','outstanding',y->'remaining','status',y->>'status','href','/dashboard/system/installments'));
   END LOOP;
  END LOOP;RETURN;
 ELSIF s IN('rental-units','rental-installments','rental-finance') THEN
  snap:=public.erp_rentals_read(c);
  IF s='rental-units' THEN
   FOR x IN SELECT value FROM jsonb_array_elements(snap->'units') LOOP
    SELECT value INTO y FROM jsonb_array_elements(snap->'types') WHERE value->>'id'=x->>'typeId';
    SELECT value INTO dim FROM jsonb_array_elements(snap->'rules') WHERE value->>'id'=y->>'ruleId';
    RETURN NEXT erp_reports_private.fact(x->>'id',NULL,jsonb_build_object('name',x->>'name','type',y->>'name','unit',dim->>'method','amount',CASE dim->>'method' WHEN 'day' THEN dim#>'{rates,day}' WHEN 'hour' THEN dim#>'{rates,hour}' WHEN 'minute' THEN dim#>'{rates,minute}' ELSE NULL END,'status',CASE WHEN(x->>'active')::boolean THEN 'active' ELSE 'inactive' END,'available',CASE WHEN(x->>'active')::boolean AND NOT EXISTS(SELECT 1 FROM public.erp_rental_reservation_units u WHERE u.cafe_id=c AND u.unit_id=(x->>'id')::uuid AND u.active AND u.starts_at<(t+1)::timestamp AT TIME ZONE 'Asia/Riyadh' AND u.ends_at>f::timestamp AT TIME ZONE 'Asia/Riyadh') THEN 'true' ELSE 'false' END));
   END LOOP;RETURN;
  ELSIF s='rental-installments' THEN
   FOR x IN SELECT value FROM jsonb_array_elements(snap->'contracts') LOOP FOR y IN SELECT value FROM jsonb_array_elements(x->'installments') LOOP
    RETURN NEXT erp_reports_private.fact(y->>'id',(y->>'due')::date,jsonb_build_object('due',y->>'due','number',x->>'code','customer',x->>'customerName','customerId',x->>'customerId','name',(SELECT value->>'name' FROM jsonb_array_elements(snap->'units') WHERE value->>'id'=x->>'unitId'),'amount',y->'amount','paid',CASE WHEN y->>'invoiceId' IS NULL THEN 0 ELSE(y->>'invoiceTotal')::numeric-(y->>'outstanding')::numeric END,'outstanding',coalesce(y->'outstanding',y->'amount'),'status',CASE WHEN y->>'invoiceId' IS NULL THEN 'unissued' WHEN(y->>'outstanding')::numeric=0 THEN 'paid' ELSE 'unpaid' END));
   END LOOP;END LOOP;RETURN;
  ELSE
   -- Financial facts use issued document links; unissued booking totals are excluded.
   RETURN QUERY WITH links AS(SELECT r.id source_id,u.unit_id,i.document_id,1.0/count(*) OVER(PARTITION BY r.id) share FROM public.erp_rental_reservations r JOIN public.erp_rental_reservation_units u ON u.cafe_id=r.cafe_id AND u.reservation_id=r.id JOIN public.bf_company_invoices i ON i.cafe_id=r.cafe_id AND i.draft_id=r.draft_id WHERE r.cafe_id=c UNION ALL SELECT x.id,r.unit_id,i.document_id,1.0 FROM public.erp_rental_installments x JOIN public.erp_rental_contracts r ON r.cafe_id=x.cafe_id AND r.id=x.contract_id JOIN public.bf_company_invoices i ON i.cafe_id=x.cafe_id AND i.draft_id=x.draft_id WHERE x.cafe_id=c),moves AS(SELECT l.*,d.id posted_id,d.created_at FROM links l JOIN public.bf_documents d ON d.cafe_id=c AND(d.id=l.document_id OR d.reference_id=l.document_id AND d.kind='refund'))
   SELECT erp_reports_private.fact(m.posted_id::text||':'||m.unit_id::text,(m.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('name',u.payload->>'name','type',ty.payload->>'name','net',coalesce(sum(j.credit-j.debit) FILTER(WHERE a.kind='revenue'),0)*m.share,'cost',coalesce(sum(j.debit-j.credit) FILTER(WHERE a.kind='expense'),0)*m.share,'profit',coalesce(sum(j.credit-j.debit) FILTER(WHERE a.kind IN('revenue','expense')),0)*m.share)) FROM moves m JOIN public.erp_rental_units u ON u.cafe_id=c AND u.id=m.unit_id LEFT JOIN public.erp_rental_types ty ON ty.cafe_id=c AND ty.id=(u.payload->>'typeId')::uuid JOIN public.bf_journal j ON j.cafe_id=c AND j.document_id=m.posted_id JOIN public.bf_accounts a ON a.cafe_id=c AND a.id=j.account_id GROUP BY m.posted_id,m.unit_id,m.created_at,u.payload,ty.payload,m.share;RETURN;
  END IF;
 ELSIF s='cost-centers' THEN RETURN QUERY SELECT * FROM erp_reports_private.cost_facts(c,f,t);RETURN;
 ELSIF s IN('messages','ai-usage','activity','cheques') THEN RETURN QUERY SELECT * FROM erp_reports_private.settings_facts(c,s,f,t);RETURN;
 END IF;RAISE EXCEPTION 'مصدر التقرير التشغيلي غير معروف';
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.run(p_cafe_id uuid, p_query jsonb, p_export boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN
 PERFORM erp_reports_private.validate_query(p_query);
 IF jsonb_array_length(coalesce(p_query->'relationPaths','[]'))=0 THEN RETURN erp_report_relation_private.run_before_relations(p_cafe_id,p_query,p_export);END IF;
 RETURN erp_report_relation_private.run(p_cafe_id,p_query,p_export);
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.settings_facts_before_system_usage(c uuid, s text, f date, t date)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE x jsonb;table_name text;label text;actor uuid;BEGIN
 IF s='cheques' THEN FOR x IN SELECT value FROM jsonb_array_elements(public.erp_cheques_report(c,f,t)->'rows') LOOP RETURN NEXT erp_reports_private.fact(x->>'id',(x->>'date')::date,x||'{"currency":"SAR"}'::jsonb);END LOOP;RETURN;
 ELSIF s='messages' THEN
  RETURN QUERY SELECT erp_reports_private.fact(d.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('name',coalesce(nullif(d.subject,''),tm.name),'type',d.channel,'status',d.status,'count',1)) FROM public.erp_template_deliveries d JOIN public.erp_document_templates tm ON tm.cafe_id=d.cafe_id AND tm.id=d.template_id WHERE d.cafe_id=c AND d.channel='sms';RETURN;
 ELSIF s='ai-usage' THEN
  IF to_regclass('public.erp_ai_usage') IS NOT NULL THEN RETURN QUERY EXECUTE 'SELECT erp_reports_private.fact(u.id::text,(u.created_at AT TIME ZONE ''Asia/Riyadh'')::date,jsonb_build_object(''employee'',coalesce(st.name,''''),''employeeId'',u.actor,''type'',u.operation,''quantity'',u.units,''status'',u.status)) FROM public.erp_ai_usage u LEFT JOIN public.bf_staff st ON st.cafe_id=u.cafe_id AND st.user_id=u.actor WHERE u.cafe_id=$1' USING c;END IF;RETURN;
 ELSIF s='activity' THEN
  FOR table_name,label IN SELECT * FROM(VALUES('bf_invoice_activity','المبيعات'),('erp_finance_events','المالية'),('erp_accounting_events','الحسابات العامة'),('erp_purchase_events','المشتريات'),('erp_inventory_events','المخزون'),('erp_mfg_events','التصنيع'),('erp_customer_events','العملاء'),('erp_membership_events','العضويات'),('erp_credit_events','أرصدة الخدمات'),('erp_hr_events','الموظفون'),('erp_att_events','الحضور'),('erp_payroll_events','المرتبات'),('erp_rental_events','الإيجارات'),('erp_work_order_events','أوامر الشغل'),('erp_workflow_events','دورات العمل'),('erp_time_events','تتبع الوقت'),('erp_cheque_audit','الشيكات'),('erp_request_events','الطلبات'),('erp_report_events','التقارير'),('erp_settings_events','الإعدادات'),('erp_customer_portal_events','بوابة العميل'))q(tab,title) LOOP
   IF to_regclass('public.'||table_name) IS NULL THEN CONTINUE;END IF;
   FOR x IN EXECUTE format('SELECT to_jsonb(e) FROM public.%I e WHERE cafe_id=$1 AND(coalesce(to_jsonb(e)->>''created_at'',to_jsonb(e)->>''at'')::timestamptz AT TIME ZONE ''Asia/Riyadh'')::date BETWEEN $2 AND $3',table_name) USING c,f,t LOOP
    actor:=coalesce(x->>'actor',x->>'actor_id',x->>'created_by')::uuid;
    RETURN NEXT erp_reports_private.fact(table_name||':'||(x->>'id'),(coalesce(x->>'created_at',x->>'at')::timestamptz AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('employee',coalesce((SELECT name FROM public.bf_staff WHERE cafe_id=c AND user_id=actor),(SELECT 'المالك' FROM public.cafes WHERE id=c AND owner_user_id=actor),''),'employeeId',actor,'type',label,'name',x->>'action','note',coalesce(x->>'note','')));
   END LOOP;
  END LOOP;RETURN;
 END IF;RAISE EXCEPTION 'مصدر تقرير الإعدادات غير معروف';
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.validate_query(q jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE f jsonb;allowed jsonb;numerics text[];k text;x jsonb;
BEGIN
 IF NOT(q?'relationPaths') OR q->'relationPaths'='[]'::jsonb THEN PERFORM erp_reports_private.validate_query_before_relations(q);RETURN;END IF;
 f:=erp_report_relation_private.fields(q);numerics:=erp_report_relation_private.numeric_fields(q);
 PERFORM erp_reports_private.validate_query_before_relations(q||'{"columns":["date"],"groupBy":[],"sortBy":"date","conditions":[],"filters":{},"summary":false}'::jsonb);
 SELECT columns||'["date","year","quarter","month","week"]'::jsonb||coalesce((SELECT jsonb_agg(key) FROM jsonb_each(f)),'[]') INTO allowed FROM erp_reports_private.sources WHERE id=q->>'source';
 IF jsonb_typeof(q->'columns') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'columns') NOT BETWEEN 1 AND 40 OR jsonb_typeof(q->'groupBy') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'groupBy')>4 OR jsonb_typeof(q->'conditions') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'conditions')>30 OR jsonb_typeof(q->'filters') IS DISTINCT FROM 'object' OR jsonb_typeof(q->'summary') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع أعمدة التقرير وشروطه وتجميعه';END IF;
 IF jsonb_array_length(q->'columns')<>(SELECT count(DISTINCT x) FROM jsonb_array_elements_text(q->'columns')x) OR jsonb_array_length(q->'groupBy')<>(SELECT count(DISTINCT x) FROM jsonb_array_elements_text(q->'groupBy')x) THEN RAISE EXCEPTION 'أعمدة التقرير أو مجموعاته مكررة';END IF;
 FOR k IN SELECT jsonb_array_elements_text((q->'columns')||(q->'groupBy')||jsonb_build_array(q->>'sortBy')) LOOP IF NOT(allowed?k) THEN RAISE EXCEPTION 'العمود غير متاح في علاقات التقرير المختارة';END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(q->'groupBy')k WHERE k=ANY(numerics)) OR ((q->>'summary')::boolean AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(q->'columns')k WHERE NOT(k=ANY(numerics)) AND NOT(q->'groupBy'?k))) THEN RAISE EXCEPTION 'راجع حقول التجميع والقيم الرقمية للملخص';END IF;
 FOR x IN SELECT * FROM jsonb_array_elements(q->'conditions') LOOP IF jsonb_typeof(x) IS DISTINCT FROM 'object' OR jsonb_typeof(x->'field') IS DISTINCT FROM 'string' OR jsonb_typeof(x->'value') IS DISTINCT FROM 'string' OR NOT(allowed?(x->>'field')) OR coalesce(x->>'operator','') NOT IN('eq','neq','contains','starts','ends','gte','lte','empty','not_empty') OR length(x->>'value')>1000 THEN RAISE EXCEPTION 'شرط العلاقة غير صالح';END IF;END LOOP;
 FOR k IN SELECT jsonb_object_keys(q->'filters') LOOP IF (NOT(allowed?k) AND k NOT IN('accountClass','accountKind','source','expiry','residency','available','kind','status')) OR jsonb_typeof(q->'filters'->k) IS DISTINCT FROM 'string' OR length(q->'filters'->>k)>1000 THEN RAISE EXCEPTION 'مرشح العلاقة غير صالح';END IF;END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_reports_private.validate_query_before_relations(q jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE allowed jsonb;column_name text;condition jsonb;BEGIN
 SELECT columns||'["date","year","quarter","month","week"]'::jsonb INTO allowed FROM erp_reports_private.sources WHERE id=q->>'source';IF NOT FOUND THEN RAISE EXCEPTION 'مصدر التقرير غير متاح';END IF;
 IF jsonb_typeof(q) IS DISTINCT FROM 'object' OR octet_length(q::text)>50000 OR jsonb_typeof(q->'columns') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'columns') NOT BETWEEN 1 AND 40 OR jsonb_typeof(q->'groupBy') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'groupBy')>4 OR jsonb_typeof(q->'conditions') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'conditions')>30 OR jsonb_typeof(q->'filters') IS DISTINCT FROM 'object' OR jsonb_typeof(q->'summary') IS DISTINCT FROM 'boolean' OR jsonb_typeof(q->'descending') IS DISTINCT FROM 'boolean' OR coalesce(q->>'conditionMode','') NOT IN('all','any') OR(q->>'from')::date IS NULL OR(q->>'to')::date IS NULL OR NOT isfinite((q->>'from')::date) OR NOT isfinite((q->>'to')::date) OR(q->>'to')::date<(q->>'from')::date OR(q->>'to')::date-(q->>'from')::date>3660 OR coalesce((q->>'offset')::integer,-1) NOT BETWEEN 0 AND 10000000 OR coalesce((q->>'limit')::integer,0) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'راجع فترة التقرير والأعمدة والمرشحات';END IF;
 FOR column_name IN SELECT jsonb_array_elements_text((q->'columns')||(q->'groupBy')||jsonb_build_array(q->>'sortBy')) LOOP IF NOT(allowed?column_name) THEN RAISE EXCEPTION 'عمود التقرير غير متاح للمصدر';END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(q->'groupBy')v WHERE v=ANY(erp_reports_private.numeric_fields())) OR jsonb_array_length(q->'columns')<>(SELECT count(DISTINCT x) FROM jsonb_array_elements_text(q->'columns')x) OR jsonb_array_length(q->'groupBy')<>(SELECT count(DISTINCT x) FROM jsonb_array_elements_text(q->'groupBy')x) THEN RAISE EXCEPTION 'الأعمدة أو التجميعات مكررة أو غير صالحة';END IF;
 FOR condition IN SELECT * FROM jsonb_array_elements(q->'conditions') LOOP IF jsonb_typeof(condition) IS DISTINCT FROM 'object' OR jsonb_typeof(condition->'field') IS DISTINCT FROM 'string' OR jsonb_typeof(condition->'value') IS DISTINCT FROM 'string' OR NOT(allowed?(condition->>'field')) OR coalesce(condition->>'operator','') NOT IN('eq','neq','contains','starts','ends','gte','lte','empty','not_empty') OR length(coalesce(condition->>'value',''))>1000 THEN RAISE EXCEPTION 'شرط التقرير غير صالح';END IF;END LOOP;
 IF jsonb_typeof(q->'sortBy') IS DISTINCT FROM 'string' OR NOT(allowed?(q->>'sortBy')) THEN RAISE EXCEPTION 'حدد عمود ترتيب صالحًا';END IF;
 FOR column_name IN SELECT jsonb_object_keys(q->'filters') LOOP IF NOT(allowed?column_name) AND column_name NOT IN('accountClass','accountKind','source','expiry','residency','available','kind','status') THEN RAISE EXCEPTION 'مرشح التقرير غير متاح للمصدر';END IF;IF jsonb_typeof(q->'filters'->column_name) IS DISTINCT FROM 'string' OR length(q->'filters'->>column_name)>1000 THEN RAISE EXCEPTION 'قيمة مرشح التقرير غير صالحة';END IF;END LOOP;
 IF(q->>'summary')::boolean AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(q->'columns')k WHERE NOT(k=ANY(erp_reports_private.numeric_fields())) AND NOT(q->'groupBy'?k)) THEN RAISE EXCEPTION 'أعمدة الملخص يجب أن تكون قيمًا رقمية أو حقول التجميع';END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_requests_private.base(c uuid, a text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE r text:=brand_finance_private.role_for(c);BEGIN
 IF auth.uid() IS NULL OR coalesce(r,'') NOT IN('owner','manager','accountant','auditor','cashier','warehouse') THEN RETURN false;END IF;
 IF a='settings' AND r<>'owner' THEN RETURN false;END IF;
 IF r='auditor' AND a<>'read' THEN RETURN false;END IF;
 RETURN erp_access_private.allowed(c,'requests',a);
END $function$

CREATE OR REPLACE FUNCTION erp_requests_private.can(c uuid, r erp_staff_requests, t jsonb, a text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE own boolean:=coalesce(erp_requests_private.self(c,r.employee_id,r.user_id),false);owner boolean:=brand_finance_private.role_for(c)='owner';BEGIN
 IF r.deleted OR NOT erp_requests_private.base(c,CASE a WHEN 'view' THEN 'read' WHEN 'edit' THEN 'update' WHEN 'revoke' THEN 'approve' WHEN 'close' THEN 'approve' ELSE a END) THEN RETURN false;END IF;
 IF a='view' THEN RETURN own OR owner OR erp_requests_private.type_allowed(c,t,'view');END IF;
 IF NOT erp_requests_private.can(c,r,t,'view') THEN RETURN false;END IF;
 IF a IN('edit','files','delete') THEN RETURN NOT r.closed AND r.status IN('draft','pending') AND (owner OR own AND erp_requests_private.type_allowed(c,t,'create') OR erp_requests_private.type_allowed(c,t,'others'));END IF;
 IF a IN('approve','revoke','close') THEN
  IF NOT erp_requests_private.type_allowed(c,t,'approve') OR (own AND NOT coalesce((r.config->>'allowSelfApproval')::boolean,false)) THEN RETURN false;END IF;
  IF a='close' THEN RETURN r.status IN('approved','rejected');END IF;
  IF r.closed THEN RETURN false;END IF;
  IF a='revoke' THEN RETURN r.status IN('approved','rejected') OR r.status='pending' AND r.step>0;END IF;
  RETURN r.status='pending' AND (owner OR erp_workflow_private.selector(c,r.config->'steps'->r.step->'selector'));
 END IF;RETURN false;
END $function$

CREATE OR REPLACE FUNCTION erp_requests_private.field_scope(fields jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE f jsonb;BEGIN
 FOR f IN SELECT value FROM jsonb_array_elements(fields) LOOP
 IF f->>'type' IN('dynamic','multidynamic') AND f->>'entity'<>'employees' THEN RAISE EXCEPTION 'اختر حساب موظف من مصادر الطلبات المتاحة';END IF;
 IF f->>'type'='subform' THEN PERFORM erp_requests_private.field_scope(f->'fields');END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_requests_private.validate_more(fields jsonb, vals jsonb, p_cafe uuid DEFAULT NULL::uuid, p_record uuid DEFAULT NULL::uuid, p_scope uuid DEFAULT NULL::uuid, depth integer DEFAULT 0, p_draft boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE f jsonb;v jsonb;t text;x jsonb;txt text;tbl text;col text;valid boolean;metric numeric;BEGIN
 IF coalesce(jsonb_typeof(vals),'')<>'object' OR octet_length(vals::text)>262144 OR depth>2 THEN RAISE EXCEPTION 'بيانات الحقول الإضافية غير صالحة';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP
  t:=f->>'type';IF t IN('static','separator') THEN CONTINUE;END IF;
  v:=coalesce(vals->(f->>'id'),f->'defaultValue');
  IF coalesce((f->>'required')::boolean,false) AND NOT p_draft AND (v IS NULL OR v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb OR (t='checkbox' AND v<>'true')) THEN RAISE EXCEPTION 'أكمل الحقل المطلوب: %',f->>'label';END IF;
  IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
  IF t='subform' THEN
   IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>100 OR jsonb_array_length(v)<coalesce((f->>'minimumRows')::integer,0) THEN RAISE EXCEPTION 'عدد صفوف النموذج غير صالح';END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM erp_requests_private.validate_more(f->'fields',x,p_cafe,p_record,p_scope,depth+1,p_draft);END LOOP;CONTINUE;
  END IF;
  IF t='location' THEN
   IF jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'latitude') IS DISTINCT FROM 'number' OR jsonb_typeof(v->'longitude') IS DISTINCT FROM 'number' OR abs((v->>'latitude')::numeric)>90 OR abs((v->>'longitude')::numeric)>180 THEN RAISE EXCEPTION 'إحداثيات الموقع غير صالحة';END IF;CONTINUE;
  END IF;
  IF (t IN('number','currency') AND jsonb_typeof(v)<>'number') OR (t='checkbox' AND jsonb_typeof(v)<>'boolean') OR (t IN('multiselect','multidynamic') AND jsonb_typeof(v)<>'array') OR (t NOT IN('number','currency','checkbox','multiselect','multidynamic') AND jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'نوع قيمة الحقل غير صالح';END IF;
  txt:=v#>>'{}';
  IF length(txt)>20000 THEN RAISE EXCEPTION 'قيمة الحقل طويلة';END IF;
  IF (t='select' AND NOT(f->'options' @> jsonb_build_array(v))) OR (t='multiselect' AND NOT(f->'options' @> v)) THEN RAISE EXCEPTION 'اختيارات الحقل غير صالحة';END IF;
  IF t='email' AND txt!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'البريد الإلكتروني غير صالح';END IF;
  IF t='url' AND txt!~'^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'الرابط غير صالح';END IF;
  IF t='time' AND txt!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'الوقت غير صالح';END IF;
  IF t='date' THEN IF txt!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'التاريخ غير صالح';END IF;PERFORM txt::date;END IF;
  IF t IN('number','currency','text','textarea','formatted') THEN
   metric:=CASE WHEN t IN('number','currency') THEN txt::numeric ELSE length(txt) END;
   IF metric<nullif(f->>'minimum','')::numeric OR metric>nullif(f->>'maximum','')::numeric THEN RAISE EXCEPTION 'قيمة الحقل خارج الحدود: %',f->>'label';END IF;
  END IF;
  IF t IN('dynamic','multidynamic') THEN
   tbl:=CASE f->>'entity' WHEN 'items' THEN 'bf_items' WHEN 'customers' THEN 'bf_parties' WHEN 'employees' THEN 'bf_staff' WHEN 'warehouses' THEN 'bf_warehouses' WHEN 'accounts' THEN 'bf_accounts' WHEN 'bom' THEN 'erp_mfg_boms' WHEN 'routings' THEN 'erp_mfg_routings' WHEN 'workstations' THEN 'erp_mfg_workstations' WHEN 'orders' THEN 'erp_mfg_orders' WHEN 'sources' THEN 'bf_documents' END;
   IF tbl IS NULL OR p_cafe IS NULL THEN RAISE EXCEPTION 'الكيان المرتبط غير صالح';END IF;col:=CASE WHEN tbl='bf_staff' THEN 'user_id' ELSE 'id' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN t='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND %I=$2)',tbl,col) INTO valid USING p_cafe,(x#>>'{}')::uuid;
    IF NOT valid THEN RAISE EXCEPTION 'القيمة المرتبطة غير موجودة في العلامة';END IF;
   END LOOP;
  END IF;
  IF t IN('file','image') THEN
   IF p_record IS NULL OR to_regclass('public.erp_files') IS NULL THEN RAISE EXCEPTION 'احفظ السجل وأضف المرفق أولًا';END IF;
   EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=$1 AND record_id=$2 AND id=$3 AND entity_type=$4 AND uploaded AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id=''erp-record-files'' AND o.name=path) AND ($5<>''image'' OR mime IN(''image/jpeg'',''image/png'')))' INTO valid USING p_cafe,p_record,txt::uuid,'request_type',t;
   IF NOT valid THEN RAISE EXCEPTION 'المرفق غير موجود في هذا السجل';END IF;
  END IF;
  IF coalesce((f->>'unique')::boolean,false) AND depth=0 THEN
   tbl:='erp_request_types';
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id IS DISTINCT FROM $2 AND config->''moreValues''->$3=$4 AND $5 IS NULL)',tbl) INTO valid USING p_cafe,p_record,f->>'id',v,p_scope;
   IF valid THEN RAISE EXCEPTION 'قيمة الحقل مستخدمة مسبقًا: %',f->>'label';END IF;
  END IF;
 END LOOP;
END $function$

