CREATE OR REPLACE FUNCTION erp_settings_private.advance_credit_settle(c uuid, source uuid, credit uuid, amount numeric)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE a public.erp_contracting_advance_invoices;used numeric;prior numeric;outstanding numeric;BEGIN
 SELECT * INTO a FROM public.erp_contracting_advance_invoices WHERE cafe_id=c AND invoice_id=source FOR UPDATE;IF NOT FOUND THEN RETURN;END IF;
 used:=erp_settings_private.advance_used(c,source);SELECT coalesce(sum(total),0) INTO prior FROM public.bf_credit_notes WHERE cafe_id=c AND source_invoice_id=source AND status='issued' AND id<>credit;
 IF amount>a.total-used-prior THEN RAISE EXCEPTION 'الإشعار يتجاوز الرصيد غير المخصص من الدفعة المقدمة' USING ERRCODE='22023';END IF;
 outstanding:=(brand_finance_private.document_state(c,source)->>'outstanding')::numeric;
 IF outstanding>0 THEN PERFORM brand_finance_private.customer_credit_apply(c,source,least(amount,outstanding));END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_settings_private.allocate_number(p_cafe uuid, p_context text, p_record uuid, p_time timestamp with time zone DEFAULT now())
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE cfg jsonb;v text;n bigint;prefix text;v_bucket text;last text;zone text;ctx erp_settings_private.number_contexts;present boolean;tries integer:=0;BEGIN
 SELECT payload INTO cfg FROM public.erp_system_numbering WHERE cafe_id=p_cafe AND context=p_context FOR UPDATE;IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT value INTO v FROM erp_settings_private.numbers WHERE cafe_id=p_cafe AND context=p_context AND record_id=p_record;IF FOUND THEN RETURN v;END IF;
 SELECT * INTO ctx FROM erp_settings_private.number_contexts WHERE context=p_context;
 zone:=coalesce((SELECT payload->>'timezone' FROM public.erp_system_settings WHERE cafe_id=p_cafe AND kind='general'),'Asia/Riyadh');
 prefix:=erp_settings_private.format_number(1,'numeric',1,cfg->>'prefix',p_time,zone);prefix:=left(prefix,length(prefix)-1);v_bucket:=CASE WHEN cfg->>'reset'='separate' THEN prefix ELSE '*' END;
 SELECT next_number,last_prefix INTO n,last FROM erp_settings_private.number_counters WHERE cafe_id=p_cafe AND context=p_context AND erp_settings_private.number_counters.bucket=v_bucket FOR UPDATE;
 IF n IS NULL THEN n:=(cfg->>'next')::bigint;ELSIF cfg->>'reset'='change' AND last<>prefix THEN n:=1;END IF;
 LOOP
  v:=erp_settings_private.format_number(n,cfg->>'mode',(cfg->>'padding')::integer,cfg->>'prefix',p_time,zone);
  IF length(v)>40 THEN RAISE EXCEPTION 'الرقم المنسق يتجاوز 40 حرفًا';END IF;
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I r WHERE cafe_id=$1 AND (CASE WHEN $6 THEN lower(to_jsonb(r)#>>$2::text[]) ELSE to_jsonb(r)#>>$2::text[] END)=(CASE WHEN $6 THEN lower($3) ELSE $3 END) AND ($4::text IS NULL OR to_jsonb(r)->>$4=$5))',ctx.table_name) INTO present USING p_cafe,string_to_array(ctx.column_path,'.'),v,ctx.filter_key,ctx.filter_value,ctx.table_name='erp_branch_details';
  EXIT WHEN NOT present AND NOT EXISTS(SELECT 1 FROM erp_settings_private.numbers WHERE cafe_id=p_cafe AND context=p_context AND value=v);
  n:=n+1;tries:=tries+1;IF tries>10000 THEN RAISE EXCEPTION 'اختر رقم بداية أعلى من الأرقام المستخدمة';END IF;
 END LOOP;
 INSERT INTO erp_settings_private.number_counters VALUES(p_cafe,p_context,v_bucket,n+1,prefix) ON CONFLICT(cafe_id,context,bucket) DO UPDATE SET next_number=excluded.next_number,last_prefix=excluded.last_prefix;
 UPDATE public.erp_system_numbering SET payload=jsonb_set(payload,'{next}',to_jsonb(n+1)),revision=revision+1 WHERE cafe_id=p_cafe AND context=p_context;
 INSERT INTO erp_settings_private.numbers(cafe_id,context,record_id,value) VALUES(p_cafe,p_context,p_record,v);RETURN v;
END $function$

CREATE OR REPLACE FUNCTION erp_settings_private.apply_advance_recovery(c uuid, invoice uuid, amount numeric, certificate uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE cert public.erp_contracting_documents;target public.bf_documents;a public.erp_contracting_advance_invoices;available numeric;remaining numeric:=amount;part numeric;tax_part numeric;used numeric;capacity numeric;payment uuid;last_payment uuid;aid uuid;
BEGIN
 SELECT * INTO target FROM public.bf_documents WHERE cafe_id=c AND id=invoice FOR UPDATE;
 SELECT * INTO cert FROM public.erp_contracting_documents WHERE cafe_id=c AND id=certificate AND kind='certificate' AND status='approved' FOR UPDATE;
 IF cert.id IS NULL OR cert.customer_id<>target.party_id OR amount<=0 OR amount>(brand_finance_private.document_state(c,invoice)->>'outstanding')::numeric THEN RAISE EXCEPTION 'استرداد الدفعة لا يطابق المستخلص' USING ERRCODE='22023';END IF;
 aid:=brand_finance_private.customer_credit_account(c);
 FOR a IN SELECT m.* FROM public.erp_contracting_advance_invoices m JOIN public.erp_contracting_advance_assignments z ON z.cafe_id=m.cafe_id AND z.invoice_id=m.invoice_id WHERE m.cafe_id=c AND m.project_id=cert.project_id AND m.party_id=cert.customer_id AND z.contract_id=cert.source_id ORDER BY erp_settings_private.advance_available(c,m.invoice_id) DESC,m.created_at,m.invoice_id FOR UPDATE OF m,z LOOP
  EXIT WHEN remaining=0;available:=erp_settings_private.advance_available(c,a.invoice_id);IF available<=0 THEN CONTINUE;END IF;
  SELECT coalesce(sum(l.net+l.tax),0)-coalesce((SELECT sum(x.amount) FROM public.erp_contracting_advance_allocations x JOIN public.erp_contracting_advance_invoices z ON z.cafe_id=x.cafe_id AND z.invoice_id=x.advance_id WHERE x.cafe_id=c AND x.invoice_id=invoice AND z.tax_rate=a.tax_rate),0) INTO capacity FROM public.bf_document_lines l WHERE l.cafe_id=c AND l.document_id=invoice AND l.vat_rate=a.tax_rate;
  part:=least(available,remaining,greatest(capacity,0));IF part<=0 THEN CONTINUE;END IF;
  used:=erp_settings_private.advance_used(c,a.invoice_id);tax_part:=round((used+part)*a.tax/a.total,2)-round(used*a.tax/a.total,2);payment:=gen_random_uuid();
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,total,paid,reference_id,note,created_by) VALUES(payment,c,'settlement',target.party_id,part,part,invoice,'تسوية فاتورة دفعة مقدمة للمستخلص',auth.uid());
  PERFORM brand_finance_private.invoice_line(c,payment,aid,part-tax_part,0,target.party_id,'استرداد صافي الدفعة المقدمة');
  PERFORM brand_finance_private.invoice_line(c,payment,brand_finance_private.account(c,'2100'),tax_part,0,NULL,'تسوية ضريبة الدفعة المقدمة');
  PERFORM brand_finance_private.invoice_line(c,payment,brand_finance_private.account(c,'1100'),0,part,target.party_id,'تسوية ذمة المستخلص');
  INSERT INTO public.erp_contracting_advance_allocations(cafe_id,advance_id,invoice_id,document_id,amount,net,tax) VALUES(c,a.invoice_id,invoice,payment,part,part-tax_part,tax_part);
  INSERT INTO public.erp_contracting_links(cafe_id,project_id,document_id,relation,amount) VALUES(c,cert.project_id,payment,'advance_invoice_recovery',part);remaining:=remaining-part;last_payment:=payment;
 END LOOP;
 IF remaining>0 THEN last_payment:=brand_finance_private.customer_credit_apply(c,invoice,remaining);END IF;
 RETURN last_payment;
END $function$

CREATE OR REPLACE FUNCTION erp_settings_private.assign_display_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE j jsonb:=to_jsonb(NEW);ctx text;reference public.bf_documents;draft uuid;BEGIN
 IF TG_TABLE_NAME='bf_documents' THEN
  SELECT * INTO reference FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.reference_id;
  IF NEW.kind='settlement' THEN
   ctx:=CASE reference.kind WHEN 'sale' THEN 'invoice_payment' WHEN 'purchase' THEN 'purchase_payment' WHEN 'refund' THEN CASE WHEN EXISTS(SELECT 1 FROM public.bf_documents d WHERE d.cafe_id=NEW.cafe_id AND d.id=reference.reference_id AND d.kind='purchase') THEN 'purchase_return_payment' ELSE 'refund_payment' END END;
  ELSIF NEW.kind='refund' THEN
   ctx:=CASE WHEN reference.kind='purchase' THEN CASE WHEN EXISTS(SELECT 1 FROM public.erp_purchase_debits WHERE cafe_id=NEW.cafe_id AND document_id=NEW.id) THEN 'purchase_debit' ELSE 'purchase_return' END WHEN reference.kind='sale' THEN 'sales_return' END;
  ELSIF NEW.kind='journal' THEN
   SELECT id INTO draft FROM public.bf_gl_drafts WHERE cafe_id=NEW.cafe_id AND document_id=NEW.id;
   IF draft IS NOT NULL THEN RETURN NEW;END IF;ctx:='automatic_journal';
  END IF;
 ELSE ctx:=CASE TG_TABLE_NAME WHEN 'erp_bookings' THEN 'booking' WHEN 'erp_rental_reservations' THEN 'rental_reservation' WHEN 'erp_task_templates' THEN 'task_template' WHEN 'bf_gl_drafts' THEN 'manual_journal' WHEN 'erp_finance_custody_movements' THEN CASE WHEN j->>'kind'='settlement' THEN 'custody_settlement' END END;
 END IF;
 IF ctx IS NOT NULL THEN PERFORM erp_settings_private.allocate_number((j->>'cafe_id')::uuid,ctx,(j->>'id')::uuid,coalesce((j->>'created_at')::timestamptz,now()));END IF;
 -- A paid refund is itself the actual cash movement, not a fictitious settlement child
 IF TG_TABLE_NAME='bf_documents' AND j->>'kind'='refund' AND coalesce((j->>'paid')::numeric,0)>0 AND reference.kind IN('sale','purchase') THEN PERFORM erp_settings_private.allocate_number(NEW.cafe_id,CASE reference.kind WHEN 'purchase' THEN 'purchase_return_payment' ELSE 'refund_payment' END,NEW.id,NEW.created_at);END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_settings_private.assign_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE ctx erp_settings_private.number_contexts;j jsonb:=to_jsonb(NEW);v text;present boolean;BEGIN
