AS $function$DECLARE d public.erp_system_product_defaults;tax numeric;BEGIN
 IF EXISTS(SELECT 1 FROM public.erp_inventory_items WHERE cafe_id=NEW.cafe_id AND item_id=NEW.item_id) THEN RETURN NEW;END IF;
