CREATE OR REPLACE FUNCTION erp_time_private.make_invoice(c uuid, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE ids uuid[];entry public.erp_time_entries%ROWTYPE;customer uuid:=(p->>'customerId')::uuid;draft uuid:=gen_random_uuid();batch uuid:=gen_random_uuid();lines jsonb:='[]';data jsonb;grouped jsonb:='{}';descs jsonb;key text;label text;line jsonb;worker_name text;project_name text;activity_name text;hours numeric;rate numeric;tax numeric:=(p->>'taxRate')::numeric;total numeric:=0;n integer:=0;BEGIN
 PERFORM erp_time_private.authorize(c,'approve');SELECT array_agg(value::uuid) INTO ids FROM jsonb_array_elements_text(p->'ids');
 IF coalesce(cardinality(ids),0) NOT BETWEEN 1 AND 200 OR cardinality(ids)<>(SELECT count(DISTINCT x) FROM unnest(ids)x) OR NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=c AND id=customer AND kind='customer' AND active) OR p->>'group' NOT IN('project','activity','worker','date') OR p->>'format' NOT IN('grouped','detailed') OR coalesce(tax,-1) NOT BETWEEN 0 AND 100 OR coalesce((p->>'defaultRate')::numeric,-1) NOT BETWEEN 0 AND 10000000 OR jsonb_typeof(p->'overrideRate') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p->'description') IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'description') x WHERE x NOT IN('project','activity','worker','date','note')) THEN RAISE EXCEPTION 'راجع الساعات والعميل وخيارات الفوترة';END IF;
 IF(SELECT count(*) FROM public.erp_time_entries WHERE cafe_id=c AND id=ANY(ids) AND ends_at IS NOT NULL AND billable AND batch_id IS NULL AND invoice_id IS NULL)<>cardinality(ids) THEN RAISE EXCEPTION 'الساعات قيد التشغيل أو مفوترة أو محجوزة أو غير متاحة';END IF;
 FOR entry IN SELECT * FROM public.erp_time_entries WHERE cafe_id=c AND id=ANY(ids) ORDER BY starts_at,id FOR UPDATE LOOP
  IF EXISTS(SELECT 1 FROM public.erp_time_catalogs WHERE cafe_id=c AND id=entry.project_id AND customer_id IS NOT NULL AND customer_id<>customer) THEN RAISE EXCEPTION 'العميل لا يطابق مشروع الوقت';END IF;
  IF entry.source_kind='workflow' AND NOT EXISTS(SELECT 1 FROM public.erp_workflow_records r JOIN public.erp_workflow_types t ON t.cafe_id=r.cafe_id AND t.id=r.type_id WHERE r.cafe_id=c AND r.id=entry.source_id AND 'customerId'=ANY(erp_workflow_private.fields(c,t.config,'read'))) THEN RAISE EXCEPTION 'صلاحيات حقول الدورة لا تسمح بفوترة وقتها' USING ERRCODE='42501';END IF;
  data:=erp_time_private.source(c,entry.source_kind,entry.source_id);IF nullif(data->>'customerId','')::uuid IS NOT NULL AND nullif(data->>'customerId','')::uuid<>customer THEN RAISE EXCEPTION 'العميل لا يطابق مصدر الوقت';END IF;
  rate:=CASE WHEN(p->>'overrideRate')::boolean THEN(p->>'defaultRate')::numeric ELSE coalesce(nullif(entry.billing_rate,0),(p->>'defaultRate')::numeric) END;IF rate<=0 THEN RAISE EXCEPTION 'حدد سعر ساعة موجبًا لجميع السجلات';END IF;
  SELECT name INTO project_name FROM public.erp_time_catalogs WHERE cafe_id=c AND id=entry.project_id;SELECT name INTO activity_name FROM public.erp_time_catalogs WHERE cafe_id=c AND id=entry.activity_id;
  IF entry.worker_kind='employee' THEN SELECT first_name||' '||last_name INTO worker_name FROM public.erp_hr_employees WHERE cafe_id=c AND id=entry.worker_id;ELSE SELECT name INTO worker_name FROM public.bf_staff WHERE cafe_id=c AND user_id=entry.worker_id;worker_name:=coalesce(worker_name,'المالك');END IF;
  label:=concat_ws(' — ',CASE WHEN p->'description'?'project' THEN project_name END,CASE WHEN p->'description'?'activity' THEN activity_name END,CASE WHEN p->'description'?'worker' THEN worker_name END,CASE WHEN p->'description'?'date' THEN(entry.starts_at AT TIME ZONE 'Asia/Riyadh')::date::text END,CASE WHEN p->'description'?'note' THEN nullif(entry.note,'') END);IF label='' THEN label:='ساعات عمل';END IF;
  hours:=extract(epoch FROM entry.ends_at-entry.starts_at)/3600;key:=CASE WHEN p->>'format'='detailed' THEN entry.id::text ELSE CASE p->>'group' WHEN 'project' THEN entry.project_id::text WHEN 'activity' THEN entry.activity_id::text WHEN 'worker' THEN entry.worker_kind||entry.worker_id::text ELSE(entry.starts_at AT TIME ZONE 'Asia/Riyadh')::date::text END||':'||rate::text END;
  line:=grouped->key;IF line IS NULL THEN grouped:=jsonb_set(grouped,ARRAY[key],jsonb_build_object('hours',hours,'rate',rate,'description',label));ELSE grouped:=jsonb_set(grouped,ARRAY[key],line||jsonb_build_object('hours',(line->>'hours')::numeric+hours,'description',left(line->>'description'||' | '||label,500)));END IF;
 END LOOP;
 FOR line IN SELECT value FROM jsonb_each(grouped) LOOP n:=n+1;IF n>100 THEN RAISE EXCEPTION 'الحد الأقصى مائة بند في الفاتورة استخدم التجميع أو حدد ساعات أقل';END IF;hours:=round((line->>'hours')::numeric,6);rate:=(line->>'rate')::numeric;total:=total+round(hours*rate,2)+round(round(hours*rate,2)*tax/100,2);lines:=lines||jsonb_build_array(jsonb_build_object('key',n,'productId','','name',left(line->>'description',160),'kind','service','quantity',hours,'price',rate,'vatRate',tax,'taxCategory',CASE WHEN tax=0 THEN 'O' ELSE 'S' END,'exemptionReason',coalesce(p->>'taxReason','')));END LOOP;
 data:=jsonb_build_object('invoice',jsonb_build_object('lines',lines,'warehouseId','','partyId',customer,'accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','taxInclusive',false,'note','فاتورة ساعات عمل','currency','SAR','exchangeRate',1),'issuer',jsonb_build_object('name','','address','','vatNumber',''),'supplyDate',current_date,'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb);
 PERFORM public.brand_finance_save_invoice_draft(c,draft,0,data);INSERT INTO public.erp_time_batches(id,cafe_id,draft_id,customer_id,expected_invoice,total) VALUES(batch,c,draft,customer,erp_time_private.invoice_signature(data),total);UPDATE public.erp_time_entries SET batch_id=batch,revision=revision+1 WHERE cafe_id=c AND id=ANY(ids);
 RETURN jsonb_build_object('id',batch,'draftId',draft);
END$function$

CREATE OR REPLACE FUNCTION erp_time_private.save_entry(c uuid, p jsonb, running boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE eid uuid:=(p->>'id')::uuid;old public.erp_time_entries%ROWTYPE;worker uuid;begin_at timestamptz;end_at timestamptz;cost numeric;rate numeric;project public.erp_time_catalogs%ROWTYPE;source jsonb;BEGIN
 SELECT * INTO old FROM public.erp_time_entries WHERE cafe_id=c AND id=eid FOR UPDATE;
 PERFORM erp_time_private.authorize(c,CASE WHEN old.id IS NULL THEN 'create' ELSE 'update' END);
 IF eid IS NULL OR coalesce(old.revision,0) IS DISTINCT FROM coalesce((p->>'revision')::integer,0) THEN RAISE EXCEPTION 'سجل الوقت تغير' USING ERRCODE='40001';END IF;
 IF old.batch_id IS NOT NULL OR old.invoice_id IS NOT NULL THEN RAISE EXCEPTION 'الساعات محجوزة لفاتورة ولا يمكن تغييرها';END IF;
 IF running AND old.id IS NOT NULL THEN RAISE EXCEPTION 'المؤقت مسجل مسبقًا';END IF;
 worker:=erp_time_private.worker(c,p->>'workerKind',(p->>'workerId')::uuid);begin_at:=CASE WHEN running THEN clock_timestamp() ELSE (p->>'start')::timestamptz END;end_at:=CASE WHEN running THEN NULL ELSE(p->>'end')::timestamptz END;
 IF begin_at IS NULL OR NOT running AND(end_at IS NULL OR end_at<=begin_at OR end_at-begin_at>interval '24 hours') OR begin_at>clock_timestamp()+interval '366 days' OR length(coalesce(p->>'note',''))>5000 OR jsonb_typeof(p->'billable') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع الفترة والمدة وبيانات الوقت';END IF;
 SELECT * INTO project FROM public.erp_time_catalogs WHERE cafe_id=c AND id=(p->>'projectId')::uuid AND kind='project' AND active;
 IF project.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.erp_time_catalogs WHERE cafe_id=c AND id=(p->>'activityId')::uuid AND kind='activity' AND active) THEN RAISE EXCEPTION 'اختر مشروعًا ونشاطًا نشطين';END IF;
 source:=erp_time_private.source(c,p->>'sourceKind',nullif(p->>'sourceId','')::uuid);
 IF project.customer_id IS NOT NULL AND nullif(source->>'customerId','')::uuid IS NOT NULL AND project.customer_id<>nullif(source->>'customerId','')::uuid THEN RAISE EXCEPTION 'عميل المشروع لا يطابق السجل المرتبط';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_time_entries WHERE cafe_id=c AND worker_key=worker AND id<>eid AND tstzrange(starts_at,ends_at,'[)')&&tstzrange(begin_at,end_at,'[)')) THEN RAISE EXCEPTION 'توجد ساعات متداخلة للموظف نفسه' USING ERRCODE='23P01';END IF;
 SELECT cost_rate,billing_rate INTO cost,rate FROM public.erp_time_rates WHERE cafe_id=c AND worker_kind=p->>'workerKind' AND worker_id=(p->>'workerId')::uuid AND effective_from<=(begin_at AT TIME ZONE 'Asia/Riyadh')::date ORDER BY effective_from DESC LIMIT 1;
 cost:=coalesce(cost,(SELECT default_cost_rate FROM public.erp_time_settings WHERE cafe_id=c),0);rate:=coalesce(nullif(project.rate,0),nullif(rate,0),(SELECT default_billing_rate FROM public.erp_time_settings WHERE cafe_id=c),0);
 INSERT INTO public.erp_time_entries(id,cafe_id,worker_kind,worker_id,worker_key,project_id,activity_id,starts_at,ends_at,note,billable,source_kind,source_id,cost_rate,billing_rate,created_by) VALUES(eid,c,p->>'workerKind',(p->>'workerId')::uuid,worker,project.id,(p->>'activityId')::uuid,begin_at,end_at,coalesce(p->>'note',''),(p->>'billable')::boolean,p->>'sourceKind',nullif(p->>'sourceId','')::uuid,cost,rate,auth.uid()) ON CONFLICT(id) DO UPDATE SET revision=erp_time_entries.revision+1,worker_kind=excluded.worker_kind,worker_id=excluded.worker_id,worker_key=excluded.worker_key,project_id=excluded.project_id,activity_id=excluded.activity_id,starts_at=excluded.starts_at,ends_at=excluded.ends_at,note=excluded.note,billable=excluded.billable,source_kind=excluded.source_kind,source_id=excluded.source_id,cost_rate=excluded.cost_rate,billing_rate=excluded.billing_rate WHERE erp_time_entries.cafe_id=c;
 IF NOT FOUND THEN RAISE EXCEPTION 'السجل غير متاح' USING ERRCODE='42501';END IF;RETURN eid;
END$function$

CREATE OR REPLACE FUNCTION erp_time_private.source(c uuid, k text, i uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE data jsonb;r public.erp_workflow_records%ROWTYPE;BEGIN
 IF k='none' AND i IS NULL THEN RETURN NULL;END IF;
 IF k='work_order' THEN PERFORM erp_work_private.authorize(c);SELECT jsonb_build_object('name',title,'customerId',customer_id) INTO data FROM public.erp_work_orders WHERE cafe_id=c AND id=i;
 ELSIF k='workflow' THEN r:=erp_workflow_private.assert_record(c,i);SELECT erp_workflow_private.mask(c,r,config) INTO data FROM public.erp_workflow_types WHERE cafe_id=c AND id=r.type_id;data:=jsonb_build_object('name',coalesce(data->>'title','دورة عمل'),'customerId',data->'customerId','href','/dashboard/system/workflows/'||r.type_id||'/'||r.id);
 ELSIF k='task' THEN PERFORM erp_access_private.assert_allowed(c,'tasks','read');SELECT jsonb_build_object('name',title,'customerId',CASE WHEN target_kind='customer' THEN target_id END) INTO data FROM public.erp_tasks WHERE cafe_id=c AND id=i;
 ELSIF k='contracting_project' THEN PERFORM erp_access_private.assert_allowed(c,'contracting','read');SELECT jsonb_build_object('name',title,'customerId',customer_id) INTO data FROM public.erp_contracting_documents WHERE cafe_id=c AND id=i AND kind='project';END IF;
 IF data IS NULL THEN RAISE EXCEPTION 'السجل المرتبط غير متاح' USING ERRCODE='42501';END IF;RETURN data;
END$function$

CREATE OR REPLACE FUNCTION erp_time_private.source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN
 IF TG_TABLE_NAME='bf_documents' THEN IF EXISTS(SELECT 1 FROM public.erp_time_batches WHERE cafe_id=OLD.cafe_id AND invoice_id=OLD.id) AND(TG_OP='DELETE' OR OLD.party_id IS DISTINCT FROM NEW.party_id OR OLD.total IS DISTINCT FROM NEW.total) THEN RAISE EXCEPTION 'فاتورة ساعات العمل لا تعدل خارج مسار التصحيح المالي';END IF;
 ELSE IF EXISTS(SELECT 1 FROM public.erp_time_entries WHERE cafe_id=OLD.cafe_id AND source_id=OLD.id AND source_kind=TG_ARGV[0]) THEN RAISE EXCEPTION 'السجل مرتبط بساعات عمل';END IF;END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
END$function$

CREATE OR REPLACE FUNCTION erp_time_private.worker(c uuid, k text, i uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE result uuid;BEGIN
 IF k='user' AND(EXISTS(SELECT 1 FROM public.bf_staff WHERE cafe_id=c AND user_id=i AND active) OR EXISTS(SELECT 1 FROM public.cafes WHERE id=c AND owner_user_id=i)) THEN RETURN i;END IF;
 IF k='employee' THEN SELECT coalesce(user_id,id) INTO result FROM public.erp_hr_employees WHERE cafe_id=c AND id=i AND active;END IF;
 IF result IS NULL THEN RAISE EXCEPTION 'الموظف غير متاح لهذه العلامة' USING ERRCODE='42501';END IF;RETURN result;
END$function$

CREATE OR REPLACE FUNCTION erp_treasury_private.before_treasury_execute(p_cafe_id uuid, p_operation text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); r text; prior public.bf_requests%ROWTYPE; a public.bf_accounts%ROWTYPE; b public.bf_accounts%ROWTYPE;
 aid uuid; other_id uuid; doc uuid:=gen_random_uuid(); n bigint; amount numeric; fee numeric; counted numeric; balance numeric; note text; result jsonb; before_row jsonb; k text; linked uuid; category text; subcategory text; center text; fee_mode text; due numeric;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_treasury_execute',p_operation);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 r:=brand_finance_private.role_for(p_cafe_id);
 IF r NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Finance manager required' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000 OR p_payload::text ~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'Invalid command'; END IF;
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.operation<>'treasury:'||p_operation OR prior.payload<>p_payload OR prior.created_by<>actor THEN RAISE EXCEPTION 'Request identifier conflict'; END IF;
  RETURN prior.result||'{"duplicate":true}'::jsonb;
 END IF;
 IF p_operation<>'account_primary' THEN PERFORM brand_finance_private.treasury_seed(p_cafe_id); END IF;
 IF p_operation<>'account_primary' AND EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe_id AND closed_through>=(now() AT TIME ZONE 'Asia/Riyadh')::date) THEN RAISE EXCEPTION 'الفترة المالية مقفلة'; END IF;
 IF p_operation='account_save' AND p_payload ? 'monthlyDueDay' THEN
  IF jsonb_typeof(p_payload->'monthlyDueDay') IS DISTINCT FROM 'number' OR (p_payload->>'monthlyDueDay')::numeric NOT BETWEEN 1 AND 31 OR (p_payload->>'monthlyDueDay')::numeric<>trunc((p_payload->>'monthlyDueDay')::numeric) THEN RAISE EXCEPTION 'اختر يوم استحقاق صحيحا من ١ إلى ٣١'; END IF;
  -- Preserve prior-month rates, but never accrue this terminal's current month under its replaced day
  PERFORM erp_treasury_private.terminal_monthly_ensure_at(p_cafe_id,brand_finance_private.terminal_monthly_today(),(SELECT id FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=nullif(p_payload->>'id','')::uuid AND monthly_due_day<>(p_payload->>'monthlyDueDay')::numeric));
 ELSIF p_operation<>'account_primary' THEN
  PERFORM erp_treasury_private.terminal_monthly_ensure(p_cafe_id);
 END IF;
 note:=btrim(coalesce(p_payload->>'note',''));
 IF length(note)>1000 THEN RAISE EXCEPTION 'Note too long'; END IF;
 aid:=nullif(p_payload->>'accountId','')::uuid;
 IF p_operation='account_save' THEN aid:=nullif(p_payload->>'id','')::uuid; END IF;
 IF aid IS NOT NULL THEN
  SELECT * INTO a FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=aid;
  IF NOT FOUND OR a.deleted_at IS NOT NULL OR a.kind NOT IN('cash','bank','pos') THEN RAISE EXCEPTION 'Invalid treasury account'; END IF;
  before_row:=to_jsonb(a)-'cafe_id';
 END IF;
 IF p_operation='account_save' THEN
  k:=p_payload->>'kind'; linked:=nullif(p_payload->>'linkedBankId','')::uuid;
  IF p_payload ? 'cashierDrawer' THEN
   IF jsonb_typeof(p_payload->'cashierDrawer') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'نوع صندوق الكاشير غير صالح'; END IF;
   IF (p_payload->>'cashierDrawer')::boolean AND k<>'cash' THEN RAISE EXCEPTION 'صندوق الكاشير حساب نقدي مستقل'; END IF;
   IF aid IS NOT NULL AND (p_payload->>'cashierDrawer')::boolean IS DISTINCT FROM a.is_cashier_drawer THEN RAISE EXCEPTION 'نوع صندوق الكاشير ثابت'; END IF;
  END IF;

  IF k NOT IN('cash','bank','pos') OR length(btrim(coalesce(p_payload->>'name',''))) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid treasury account'; END IF;
  IF k='pos' AND linked IS NULL THEN RAISE EXCEPTION 'اختر البنك المرتبط بنقطة الشبكة'; END IF;
  IF k<>'pos' AND linked IS NOT NULL THEN RAISE EXCEPTION 'Only POS accounts can link a bank'; END IF;
  IF aid IS NULL THEN
   aid:=gen_random_uuid();
   INSERT INTO public.bf_accounts(id,cafe_id,name,code,kind,linked_bank_id,bank_name,iban,terminal_id,is_cashier_drawer)
   VALUES(aid,p_cafe_id,btrim(p_payload->>'name'),'T-'||replace(aid::text,'-',''),k,linked,coalesce(p_payload->>'bankName',''),upper(replace(coalesce(p_payload->>'iban',''),' ','')),coalesce(p_payload->>'terminalId',''),coalesce((p_payload->>'cashierDrawer')::boolean,false));
  PERFORM erp_treasury_private.register_account(p_cafe_id,aid); ELSE
   IF a.kind<>k OR NOT a.active OR p_payload ? 'openingAmount' THEN RAISE EXCEPTION 'الرصيد الافتتاحي يسجل من إجراء مستقل لمرة واحدة'; END IF;
   UPDATE public.bf_accounts SET name=btrim(p_payload->>'name'),linked_bank_id=linked,bank_name=coalesce(p_payload->>'bankName',''),iban=upper(replace(coalesce(p_payload->>'iban',''),' ','')),terminal_id=coalesce(p_payload->>'terminalId','') WHERE id=aid;
  END IF;
  IF k<>'pos' AND ((p_payload ? 'transactionFeePercent') OR (p_payload ? 'monthlySubscription') OR (p_payload ? 'feeVatRate') OR (p_payload ? 'monthlyDueDay')) THEN RAISE EXCEPTION 'إعدادات الرسوم متاحة لنقاط الشبكة فقط'; END IF;
  IF k='pos' THEN
   UPDATE public.bf_accounts SET transaction_fee_percent=coalesce((p_payload->>'transactionFeePercent')::numeric,transaction_fee_percent),
    monthly_subscription=coalesce((p_payload->>'monthlySubscription')::numeric,monthly_subscription),
    fee_vat_rate=coalesce((p_payload->>'feeVatRate')::numeric,fee_vat_rate),
    monthly_due_day=coalesce((p_payload->>'monthlyDueDay')::numeric::smallint,monthly_due_day),
    fee_started_month=CASE WHEN coalesce((p_payload->>'monthlySubscription')::numeric,monthly_subscription)>0 THEN coalesce(fee_started_month,date_trunc('month',brand_finance_private.terminal_monthly_today())::date) ELSE NULL END
   WHERE id=aid;
   PERFORM erp_treasury_private.terminal_monthly_ensure(p_cafe_id);
  END IF;
  IF p_payload ? 'openingAmount' THEN
   amount:=round((p_payload->>'openingAmount')::numeric,2);
   IF amount IS NULL OR amount<0 THEN RAISE EXCEPTION 'Invalid opening amount'; END IF;
   UPDATE public.bf_accounts SET opening_recorded_at=now(),opening_amount=amount WHERE id=aid;
   INSERT INTO public.bf_documents(id,cafe_id,kind,account_id,total,paid,note,created_by) VALUES(doc,p_cafe_id,'opening',aid,amount,amount,note,actor) RETURNING number INTO n;
   PERFORM brand_finance_private.line(p_cafe_id,doc,aid,amount,0);
   PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'3000'),0,amount);
   INSERT INTO public.bf_treasury_documents(cafe_id,document_id,operation) VALUES(p_cafe_id,doc,'opening');
  END IF;
  result:=jsonb_build_object('id',aid,'document_id',CASE WHEN n IS NOT NULL THEN doc ELSE NULL END,'number',n);
 ELSIF p_operation='account_primary' THEN
  IF aid IS NULL OR NOT a.active THEN RAISE EXCEPTION 'اختر حسابا نشطا ليكون الحساب الرئيسي'; END IF;
  SELECT id INTO linked FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND kind=a.kind AND active AND is_primary;
  before_row:=before_row||jsonb_build_object('previous_primary_id',linked);
  IF linked IS DISTINCT FROM aid THEN
   UPDATE public.bf_accounts SET is_primary=false WHERE cafe_id=p_cafe_id AND kind=a.kind AND is_primary;
   UPDATE public.bf_accounts SET is_primary=true WHERE cafe_id=p_cafe_id AND id=aid;
  END IF;
  result:=jsonb_build_object('id',aid,'previous_primary_id',linked);
 ELSIF p_operation='account_delete' THEN
  IF aid IS NULL OR NOT brand_finance_private.can_delete_cash(p_cafe_id,aid) THEN
   RAISE EXCEPTION 'لا يمكن حذف خزينة رئيسية أو أساسية أو خزينة لها حركات أو ورديات أو ارتباطات';
  END IF;
  UPDATE public.bf_accounts SET active=false,deleted_at=now() WHERE id=aid AND cafe_id=p_cafe_id;
  result:=jsonb_build_object('id',aid,'deleted',true);
 ELSIF p_operation='account_archive' THEN
  IF aid IS NULL OR NOT (p_payload ? 'active') OR jsonb_typeof(p_payload->'active')<>'boolean' THEN RAISE EXCEPTION 'Invalid archive request'; END IF;
  UPDATE public.bf_accounts SET active=(p_payload->>'active')::boolean WHERE id=aid;
  result:=jsonb_build_object('id',aid);
 ELSE
  IF aid IS NULL OR NOT a.active THEN RAISE EXCEPTION 'اختر حسابا نشطا'; END IF;
  balance:=brand_finance_private.treasury_balance(p_cafe_id,aid);
  amount:=round((p_payload->>'amount')::numeric,2);
  IF p_operation='reconcile' THEN
   counted:=round((p_payload->>'countedAmount')::numeric,2);
   IF counted IS NULL OR counted<0 OR (p_payload->>'expectedBalance')::numeric IS DISTINCT FROM balance THEN RAISE EXCEPTION 'تغير الرصيد حدث البيانات ثم أعد المطابقة'; END IF;
   INSERT INTO public.bf_treasury_reconciliations(id,cafe_id,account_id,expected_amount,counted_amount,note,created_by) VALUES(doc,p_cafe_id,aid,balance,counted,note,actor);
   result:=jsonb_build_object('id',doc,'difference',counted-balance);
  ELSE
   IF amount IS NULL OR amount<0 OR (p_operation NOT IN('opening','pos_settle','pos_fee_pay') AND amount=0) THEN RAISE EXCEPTION 'Invalid amount'; END IF;
   IF p_operation='opening' THEN
    IF a.opening_recorded_at IS NOT NULL OR EXISTS(SELECT 1 FROM public.bf_journal WHERE cafe_id=p_cafe_id AND account_id=aid) OR EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND account_id=aid AND status IN('open','handover')) THEN RAISE EXCEPTION 'سبق بدء الحساب ولا يمكن تكرار الرصيد الافتتاحي'; END IF;
    UPDATE public.bf_accounts SET opening_recorded_at=now(),opening_amount=amount WHERE id=aid;
    k:='opening'; other_id:=brand_finance_private.account(p_cafe_id,'3000');
   ELSIF p_operation='voucher' THEN
    k:=p_payload->>'kind'; other_id:=nullif(p_payload->>'counterAccountId','')::uuid;
    category:=coalesce(p_payload->>'category',''); subcategory:=coalesce(p_payload->>'subcategory',''); center:=btrim(coalesce(p_payload->>'costCenter',''));
    IF length(center)>100 THEN RAISE EXCEPTION 'اسم مركز التكلفة يجب ألا يتجاوز مئة حرف'; END IF;
    IF category<>'' THEN
     IF NOT ((k='receipt' AND category IN('other_income','owner_funding')) OR (k='expense' AND category IN('operating_expense','owner_draw'))) THEN RAISE EXCEPTION 'اختر تصنيفا مناسبا لسند القبض أو الصرف'; END IF;
     IF subcategory<>'' AND (category<>'operating_expense' OR subcategory NOT IN('rent','utilities','maintenance','wages','other')) THEN RAISE EXCEPTION 'اختر تصنيفا فرعيا صحيحا للمصروف التشغيلي'; END IF;
     PERFORM brand_finance_private.terminal_fee_seed(p_cafe_id);
     linked:=brand_finance_private.account(p_cafe_id,CASE category WHEN 'other_income' THEN '4010' WHEN 'owner_funding' THEN '3000' WHEN 'owner_draw' THEN '3010' ELSE '5100' END);
     IF other_id IS NOT NULL AND other_id<>linked THEN RAISE EXCEPTION 'الحساب المقابل لا يطابق تصنيف السند'; END IF;
     other_id:=linked;
    ELSIF subcategory<>'' THEN RAISE EXCEPTION 'اختر تصنيف السند قبل التصنيف الفرعي'; END IF;
    IF k NOT IN('receipt','expense') OR a.kind='pos' OR length(note)<3 OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=other_id AND active AND kind IN('revenue','expense','equity')) THEN RAISE EXCEPTION 'اختر الحساب المقابل واكتب بيان السند'; END IF;
    IF k='expense' AND balance<amount THEN RAISE EXCEPTION 'الرصيد غير كاف'; END IF;
   ELSIF p_operation='transfer' THEN
    k:='transfer'; other_id:=nullif(p_payload->>'toAccountId','')::uuid;
    IF a.kind NOT IN('cash','bank') OR other_id=aid OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=other_id AND active AND kind IN('cash','bank')) OR balance<amount OR length(note)<3 THEN RAISE EXCEPTION 'تحقق من حسابي التحويل والرصيد والبيان'; END IF;
   ELSIF p_operation IN('pos_settle','pos_fee_pay') THEN
    k:='transfer'; other_id:=a.linked_bank_id; fee_mode:=coalesce(p_payload->>'feeTreatment','legacy');
    due:=brand_finance_private.terminal_fees_due(p_cafe_id,aid);
    IF fee_mode NOT IN('legacy','net','gross') THEN RAISE EXCEPTION 'اختر طريقة إيداع البنك بالإجمالي أو بالصافي'; END IF;
    fee:=round(coalesce((p_payload->>'feesDeducted')::numeric,CASE WHEN p_operation='pos_fee_pay' THEN amount ELSE NULL END,(p_payload->>'fee')::numeric,0),2);
    IF a.kind<>'pos' OR other_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=other_id AND kind='bank' AND active) OR fee<0 OR length(btrim(coalesce(p_payload->>'reference',''))) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'تحقق من نقطة الشبكة والبنك المرتبط ومرجع العملية'; END IF;
    IF p_operation='pos_fee_pay' THEN
     IF (p_payload ? 'feesDeducted' AND round((p_payload->>'feesDeducted')::numeric,2) IS DISTINCT FROM amount) OR (p_payload ? 'fee' AND round((p_payload->>'fee')::numeric,2) IS DISTINCT FROM amount) THEN RAISE EXCEPTION 'مبلغ سداد الرسوم لا يطابق المبلغ المدخل'; END IF;
     fee:=amount; fee_mode:='net'; amount:=0;
     IF fee<=0 OR fee>due OR brand_finance_private.treasury_balance(p_cafe_id,other_id)<fee THEN RAISE EXCEPTION 'تحقق من مبلغ الرسوم المستحقة ورصيد البنك المتاح للسداد'; END IF;
    ELSE
     IF amount<=0 OR balance<amount OR fee>amount THEN RAISE EXCEPTION 'مبلغ التسوية يجب ألا يتجاوز رصيد الشبكة والرسوم يجب ألا تتجاوز التسوية'; END IF;
     IF fee_mode='gross' AND fee<>0 THEN RAISE EXCEPTION 'الإيداع بالإجمالي لا يتضمن خصم رسوم من المبلغ المودع'; END IF;
     IF fee_mode<>'legacy' AND fee>due THEN RAISE EXCEPTION 'الرسوم المخصومة تتجاوز الرسوم المستحقة على الشبكة'; END IF;
     IF fee_mode='legacy' AND (due>0 OR a.transaction_fee_percent>0 OR a.monthly_subscription>0 OR p_payload ? 'feesDeducted') THEN RAISE EXCEPTION 'اختر الإيداع بالإجمالي أو بالصافي لتجنب خصم الرسوم مرتين'; END IF;
    END IF;
    IF EXISTS(SELECT 1 FROM public.bf_treasury_documents WHERE cafe_id=p_cafe_id AND account_id=aid AND operation IN('pos_settle','pos_fee_pay') AND reference=btrim(p_payload->>'reference')) THEN RAISE EXCEPTION 'سبق تسجيل مرجع البنك لهذه الشبكة'; END IF;
   ELSE RAISE EXCEPTION 'Unknown treasury operation'; END IF;
   INSERT INTO public.bf_documents(id,cafe_id,kind,account_id,total,paid,note,created_by) VALUES(doc,p_cafe_id,k,aid,CASE WHEN p_operation='pos_fee_pay' THEN fee ELSE amount END,CASE WHEN p_operation='pos_fee_pay' THEN fee ELSE amount END,note,actor) RETURNING number INTO n;
   IF p_operation='pos_fee_pay' THEN
    PERFORM brand_finance_private.line(p_cafe_id,doc,other_id,0,fee);
    PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'2010'),fee,0);
    PERFORM brand_finance_private.terminal_fee_allocate(p_cafe_id,aid,doc,fee);
   ELSIF p_operation='pos_settle' AND fee_mode<>'legacy' THEN
    PERFORM brand_finance_private.line(p_cafe_id,doc,aid,0,amount);
    PERFORM brand_finance_private.line(p_cafe_id,doc,other_id,amount-fee,0);
    IF fee>0 THEN
     PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'2010'),fee,0);
     PERFORM brand_finance_private.terminal_fee_allocate(p_cafe_id,aid,doc,fee);
    END IF;
   ELSIF k IN('opening','receipt') THEN
    PERFORM brand_finance_private.line(p_cafe_id,doc,aid,amount,0); PERFORM brand_finance_private.line(p_cafe_id,doc,other_id,0,amount);
   ELSE
    PERFORM brand_finance_private.line(p_cafe_id,doc,aid,0,amount); PERFORM brand_finance_private.line(p_cafe_id,doc,other_id,amount-coalesce(fee,0),0);
    IF coalesce(fee,0)>0 THEN PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'5100'),fee,0); END IF;
   END IF;
   INSERT INTO public.bf_treasury_documents(cafe_id,document_id,account_id,operation,reference,fee,category,subcategory,cost_center) VALUES(p_cafe_id,doc,aid,p_operation,btrim(coalesce(p_payload->>'reference','')),coalesce(fee,0),coalesce(category,''),coalesce(subcategory,''),coalesce(center,''));
   result:=jsonb_build_object('id',doc,'number',n);
  END IF;
 END IF;
 INSERT INTO public.bf_treasury_audit(cafe_id,actor_id,operation,entity_id,before_data,after_data)
 VALUES(p_cafe_id,actor,p_operation,(result->>'id')::uuid,before_row,CASE WHEN p_operation IN('account_save','account_archive','account_primary','opening') THEN (SELECT to_jsonb(x)-'cafe_id' FROM public.bf_accounts x WHERE id=aid) ELSE p_payload||result END);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'treasury:'||p_operation,p_payload,result,actor);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_treasury_private.before_treasury_history(p_cafe_id uuid, p_account_id uuid, p_kind text, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; result jsonb;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_treasury_history',NULL);
 r:=brand_finance_private.role_for(p_cafe_id);
 IF r NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Finance manager required' USING ERRCODE='42501'; END IF;
 IF p_offset IS NULL OR p_offset<0 OR p_kind IS NULL OR p_kind NOT IN('audit','reconciliations') OR NOT EXISTS(SELECT 1 FROM erp_branch_private.bf_accounts WHERE cafe_id=p_cafe_id AND id=p_account_id) THEN RAISE EXCEPTION 'Invalid account history'; END IF;
 IF p_kind='reconciliations' THEN
  WITH selected AS (
   SELECT rec.id,rec.account_id,rec.expected_amount expected_balance,rec.counted_amount,rec.difference variance,rec.note,rec.created_at,
    brand_finance_private.treasury_actor_name(p_cafe_id,rec.created_by) actor_name,s.document_id adjustment_document_id
   FROM erp_branch_private.bf_treasury_reconciliations rec LEFT JOIN erp_branch_private.bf_treasury_reconciliation_resolutions s ON s.cafe_id=rec.cafe_id AND s.reconciliation_id=rec.id
   WHERE rec.cafe_id=p_cafe_id AND rec.account_id=p_account_id
  ), page AS (SELECT * FROM selected ORDER BY created_at DESC,id DESC OFFSET p_offset LIMIT 100)
  SELECT jsonb_build_object('total',(SELECT count(*) FROM selected),'rows',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC,p.id DESC) FROM page p),'[]'::jsonb)) INTO result;
 ELSE
  WITH selected AS (
   SELECT au.id,p_account_id account_id,au.operation,coalesce(au.after_data->>'reason',au.after_data->>'note','') note,au.created_at,
    brand_finance_private.treasury_actor_name(p_cafe_id,au.actor_id) actor_name,d.id document_id
   FROM erp_branch_private.bf_treasury_audit au LEFT JOIN erp_branch_private.bf_documents d ON d.cafe_id=au.cafe_id AND d.id=au.entity_id
   WHERE au.cafe_id=p_cafe_id AND (
    (au.operation IN('account_save','account_archive','account_primary','opening') AND au.after_data->>'id'=p_account_id::text)
    OR au.after_data->>'accountId'=p_account_id::text OR au.after_data->>'toAccountId'=p_account_id::text
    OR EXISTS(SELECT 1 FROM erp_branch_private.bf_journal j WHERE j.cafe_id=p_cafe_id AND j.document_id=au.entity_id AND j.account_id=p_account_id))
  ), page AS (SELECT * FROM selected ORDER BY created_at DESC,id DESC OFFSET p_offset LIMIT 100)
  SELECT jsonb_build_object('total',(SELECT count(*) FROM selected),'rows',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.created_at DESC,p.id DESC) FROM page p),'[]'::jsonb)) INTO result;
 END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_treasury_private.brand_finance_cash_handovers(p_cafe_id uuid, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; managed boolean; drawer uuid;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_cash_handovers',NULL);
 role_name:=brand_finance_private.role_for(p_cafe_id);managed:=role_name IN('owner','manager','accountant','auditor');
 IF p_offset IS NULL OR p_offset<0 OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'نطاق سجلات التسليم غير صالح'; END IF;
 PERFORM brand_finance_private.seed(p_cafe_id);drawer:=brand_finance_private.cashier_drawer(p_cafe_id);
 RETURN jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY created_at DESC,id DESC) FROM (
  SELECT h.id,h.shift_id,h.shift_number,h.drawer_id,h.drawer_name,h.receiving_drawer_id,h.receiving_drawer_name,h.amount,h.handover_type,h.from_user_id,h.from_name,h.recipient_user_id,h.recipient_name,h.recipient_phone,h.created_at,
   CASE WHEN r.handover_id IS NULL THEN 'pending' ELSE 'received' END status,r.received_at,r.received_by_name,r.received_counted_cash,d.number document_number,rd.number receipt_document_number
  FROM erp_branch_private.bf_cash_handovers h LEFT JOIN erp_branch_private.bf_cash_handover_receipts r ON r.handover_id=h.id LEFT JOIN erp_branch_private.bf_documents d ON d.id=h.document_id LEFT JOIN erp_branch_private.bf_documents rd ON rd.id=r.document_id
  WHERE h.cafe_id=p_cafe_id AND (managed OR h.from_user_id=auth.uid() OR r.received_by=auth.uid()) ORDER BY h.created_at DESC,h.id DESC OFFSET p_offset LIMIT p_limit
 ) x),'[]'::jsonb),
 'total',(SELECT count(*) FROM erp_branch_private.bf_cash_handovers h LEFT JOIN erp_branch_private.bf_cash_handover_receipts r ON r.handover_id=h.id WHERE h.cafe_id=p_cafe_id AND (managed OR h.from_user_id=auth.uid() OR r.received_by=auth.uid())),
 'canReceive',role_name IN('owner','manager','accountant'),'cashierDrawerId',drawer,
 'cashierDrawers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'busy',EXISTS(SELECT 1 FROM erp_branch_private.bf_shifts s WHERE s.cafe_id=p_cafe_id AND s.account_id=a.id AND s.status IN('open','handover'))) ORDER BY (a.code='1001-CASHIER') DESC,a.id) FROM erp_branch_private.bf_accounts a WHERE a.cafe_id=p_cafe_id AND a.is_cashier_drawer AND a.active),'[]'::jsonb),

 'accountants',coalesce((SELECT jsonb_agg(jsonb_build_object('user_id',s.user_id,'name',s.name) ORDER BY s.name,s.user_id) FROM erp_branch_private.bf_staff s JOIN public.profiles p ON p.id=s.user_id AND p.status='active' WHERE s.cafe_id=p_cafe_id AND s.role IN('manager','accountant') AND s.active),'[]'::jsonb));
END $function$

CREATE OR REPLACE FUNCTION erp_treasury_private.brand_finance_receive_shift_cash(p_cafe_id uuid, p_handover_id uuid, p_account_id uuid, p_note text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE h public.bf_cash_handovers%ROWTYPE; role_name text; prior public.bf_requests%ROWTYPE; payload jsonb; result jsonb; doc uuid; n bigint; title text;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_receive_shift_cash',NULL);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));role_name:=brand_finance_private.role_for(p_cafe_id);
 IF role_name NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'استلام العهدة متاح لمالك العلامة أو المحاسب' USING ERRCODE='42501'; END IF;
 p_note:=btrim(coalesce(p_note,''));
 IF p_handover_id IS NULL OR p_account_id IS NULL OR p_request_id IS NULL OR length(p_note)>1000 THEN RAISE EXCEPTION 'بيانات استلام العهدة غير مكتملة'; END IF;
 payload:=jsonb_build_object('handoverId',p_handover_id,'accountId',p_account_id,'note',p_note);
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.operation<>'shift_cash_receive' OR prior.payload<>payload OR prior.created_by<>auth.uid() THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى'; END IF;
  RETURN prior.result||'{"duplicate":true}'::jsonb;
 END IF;
 IF EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe_id AND closed_through>=(now() AT TIME ZONE 'Asia/Riyadh')::date) THEN RAISE EXCEPTION 'الفترة المالية مقفلة'; END IF;
 SELECT * INTO h FROM public.bf_cash_handovers WHERE cafe_id=p_cafe_id AND id=p_handover_id FOR UPDATE;
 IF NOT FOUND OR h.handover_type='next_shift' OR EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts WHERE handover_id=h.id) THEN RAISE EXCEPTION 'سجل التسليم غير متاح للاستلام أو سبق استلامه'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=p_account_id AND kind IN('cash','bank') AND active AND NOT is_cashier_drawer) THEN RAISE EXCEPTION 'اختر خزينة أو حسابا بنكيا نشطا غير صندوق الكاشير'; END IF;
 IF h.amount>0 THEN
  IF coalesce((SELECT sum(debit-credit) FROM public.bf_journal WHERE cafe_id=p_cafe_id AND account_id=brand_finance_private.account(p_cafe_id,'1030') AND party_id=h.party_id),0)<h.amount THEN RAISE EXCEPTION 'رصيد عهدة المستلم لا يكفي لهذه العملية'; END IF;
  doc:=gen_random_uuid();title:=left('استلام نقدية الوردية رقم '||h.shift_number||' المسلمة من '||h.from_name||' إلى عهدة '||h.recipient_name||CASE WHEN p_note='' THEN '' ELSE ' - '||p_note END,1000);
  INSERT INTO public.bf_documents(id,cafe_id,kind,shift_id,account_id,party_id,total,paid,reference_id,note,created_by) VALUES(doc,p_cafe_id,'receipt',h.shift_id,p_account_id,h.party_id,h.amount,h.amount,h.document_id,title,auth.uid()) RETURNING number INTO n;
  PERFORM brand_finance_private.line(p_cafe_id,doc,p_account_id,h.amount,0);
  PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'1030'),0,h.amount,h.party_id);
 END IF;
 INSERT INTO public.bf_cash_handover_receipts(handover_id,cafe_id,received_by,received_by_name,received_counted_cash,account_id,document_id,note) VALUES(h.id,p_cafe_id,auth.uid(),brand_finance_private.cash_employee_name(p_cafe_id,auth.uid()),h.amount,p_account_id,doc,p_note);
 result:=jsonb_build_object('id',h.id,'document_id',doc,'number',n,'amount',h.amount);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'shift_cash_receive',payload,result,auth.uid());
 INSERT INTO public.bf_treasury_audit(cafe_id,actor_id,operation,entity_id,after_data) VALUES(p_cafe_id,auth.uid(),'shift_cash_receive',coalesce(doc,h.id),payload||result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_treasury_private.brand_finance_terminal_fee_history(p_cafe_id uuid, p_account_id uuid DEFAULT NULL::uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; answer jsonb;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_terminal_fee_history',NULL);
 r:=brand_finance_private.role_for(p_cafe_id);
 IF r NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Finance manager required' USING ERRCODE='42501'; END IF;
 IF p_offset IS NULL OR p_offset<0 OR (p_account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM erp_branch_private.bf_accounts WHERE cafe_id=p_cafe_id AND id=p_account_id AND kind IN('bank','pos'))) THEN RAISE EXCEPTION 'اختر حسابا بنكيا أو نقطة شبكة لعرض سجل الرسوم'; END IF;
 WITH filtered AS (
  SELECT c.*,s.number source_number,brand_finance_private.terminal_fee_paid(p_cafe_id,c.id) paid,c.total-brand_finance_private.terminal_fee_paid(p_cafe_id,c.id) remaining
  FROM erp_branch_private.bf_terminal_fee_charges c LEFT JOIN erp_branch_private.bf_documents s ON s.cafe_id=c.cafe_id AND s.id=c.source_document_id
  WHERE c.cafe_id=p_cafe_id AND (p_account_id IS NULL OR c.terminal_id=p_account_id OR c.bank_id=p_account_id)
 ), page AS(SELECT * FROM filtered ORDER BY created_at DESC,id DESC OFFSET p_offset LIMIT 100)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM filtered),'rows',coalesce((SELECT jsonb_agg(to_jsonb(p)-'cafe_id' ORDER BY p.created_at DESC,p.id DESC) FROM page p),'[]'::jsonb)) INTO answer;
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION erp_treasury_private.brand_finance_treasury_attachment(p_cafe_id uuid, p_document_id uuid, p_action text DEFAULT 'list'::text, p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_size bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.bf_treasury_attachments; obj jsonb; result jsonb; r text;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_treasury_attachment',p_action);
 r := brand_finance_private.role_for(p_cafe_id);
 IF r NOT IN ('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Treasury management required' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_document_id
   AND kind IN ('receipt','expense','transfer','opening','journal'))
 THEN RAISE EXCEPTION 'Treasury document unavailable' USING ERRCODE='42501'; END IF;
 IF p_action='list' THEN
   SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.created_at),'[]'::jsonb) INTO result
   FROM public.bf_treasury_attachments t WHERE cafe_id=p_cafe_id AND document_id=p_document_id AND uploaded;
   RETURN result;
 END IF;
 IF p_action='stale' THEN
   WITH expired AS (
     UPDATE public.bf_treasury_attachments SET abandoned=true
     WHERE cafe_id=p_cafe_id AND document_id=p_document_id AND NOT uploaded AND expires_at<now()
     RETURNING *
   ) SELECT coalesce(jsonb_agg(to_jsonb(expired)),'[]'::jsonb) INTO result FROM expired;
   RETURN result;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_document_id::text,78021));
 SELECT * INTO a FROM public.bf_treasury_attachments WHERE id=p_id FOR UPDATE;
 IF a.id IS NOT NULL AND (a.cafe_id<>p_cafe_id OR a.document_id<>p_document_id)
 THEN RAISE EXCEPTION 'Attachment unavailable' USING ERRCODE='42501'; END IF;
 IF p_action='prepare' THEN
   IF p_id IS NULL OR p_name IS NULL OR length(trim(p_name)) NOT BETWEEN 1 AND 180
      OR p_name ~ '[[:cntrl:]/\\]' OR p_size IS NULL OR p_size < 1
   THEN RAISE EXCEPTION 'Invalid attachment'; END IF;
   IF a.id IS NOT NULL THEN
     IF a.abandoned OR a.uploader_id<>auth.uid() OR a.original_name<>trim(p_name) OR a.size_bytes<>p_size
     THEN RAISE EXCEPTION 'Attachment request mismatch' USING ERRCODE='42501'; END IF;
     IF NOT a.uploaded THEN UPDATE public.bf_treasury_attachments SET expires_at=now()+interval '3 hours' WHERE id=a.id RETURNING * INTO a; END IF;
     RETURN to_jsonb(a);
   END IF;
   INSERT INTO public.bf_treasury_attachments(id,cafe_id,document_id,uploader_id,storage_path,original_name,size_bytes)
   VALUES(p_id,p_cafe_id,p_document_id,auth.uid(),p_cafe_id::text||'/'||p_document_id::text||'/'||p_id::text,trim(p_name),p_size)
   RETURNING * INTO a;
   RETURN to_jsonb(a);
 END IF;
 IF a.id IS NULL THEN RAISE EXCEPTION 'Attachment unavailable' USING ERRCODE='42501'; END IF;
 IF p_action='get' AND a.uploaded THEN RETURN to_jsonb(a); END IF;
 IF p_action='finalize' THEN
   IF a.abandoned OR a.uploader_id<>auth.uid() THEN RAISE EXCEPTION 'Own attachment required' USING ERRCODE='42501'; END IF;
   IF a.uploaded THEN RETURN to_jsonb(a); END IF;
   SELECT metadata INTO obj FROM storage.objects WHERE bucket_id='branda-finance-treasury-files' AND name=a.storage_path;
   IF obj IS NULL OR (obj->>'size')::bigint IS DISTINCT FROM a.size_bytes
   THEN RAISE EXCEPTION 'Uploaded object size mismatch'; END IF;
   UPDATE public.bf_treasury_attachments SET uploaded=true WHERE id=a.id RETURNING * INTO a;
   RETURN to_jsonb(a);
 END IF;
 IF p_action='purge' AND a.abandoned AND NOT a.uploaded AND a.expires_at<now() THEN
   -- Storage API must delete bytes first; never remove metadata-only storage rows
   IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='branda-finance-treasury-files' AND name=a.storage_path)
   THEN RAISE EXCEPTION 'Storage object still exists'; END IF;
   DELETE FROM public.bf_treasury_attachments WHERE id=a.id;
   RETURN jsonb_build_object('purged',true);
 END IF;
 RAISE EXCEPTION 'Attachment action denied' USING ERRCODE='42501';
END $function$

CREATE OR REPLACE FUNCTION erp_treasury_private.brand_finance_treasury_correct(p_cafe_id uuid, p_actor_id uuid, p_maintenance_expires_at timestamp with time zone, p_operation text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE audit_record record; prior public.bf_requests%ROWTYPE; original public.bf_documents%ROWTYPE; recon public.bf_treasury_reconciliations%ROWTYPE;
 a public.bf_accounts%ROWTYPE; line record; doc uuid:=gen_random_uuid(); n bigint; aid uuid; amount numeric; balance numeric; reason text; result jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_actor_id AND role='platform_admin' AND status='active') OR NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe_id AND deleted_at IS NULL AND status IN('active','published')) OR NOT platform_access_private.service_enabled(p_cafe_id,'finance') THEN RAISE EXCEPTION 'Maintenance administrator required' USING ERRCODE='42501'; END IF;
 SELECT action,new_data INTO audit_record FROM public.audit_logs WHERE actor_id=p_actor_id AND cafe_id=p_cafe_id AND action IN('maintenance_mode_started','maintenance_mode_ended') ORDER BY created_at DESC,id DESC LIMIT 1;
 IF NOT FOUND OR audit_record.action<>'maintenance_mode_started' OR p_maintenance_expires_at IS NULL OR p_maintenance_expires_at<=now() OR (audit_record.new_data->>'expires_at')::timestamptz IS DISTINCT FROM p_maintenance_expires_at THEN RAISE EXCEPTION 'Active matching maintenance session required' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000 OR p_payload::text ~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'Invalid command'; END IF;
 reason:=btrim(coalesce(p_payload->>'reason',''));
 IF length(reason) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'سبب التصحيح مطلوب'; END IF;
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.operation<>'treasury_correct:'||p_operation OR prior.payload<>p_payload OR prior.created_by<>p_actor_id THEN RAISE EXCEPTION 'Request identifier conflict'; END IF;
  RETURN prior.result||'{"duplicate":true}'::jsonb;
 END IF;
 IF EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe_id AND closed_through>=(now() AT TIME ZONE 'Asia/Riyadh')::date) THEN RAISE EXCEPTION 'الفترة المالية مقفلة'; END IF;

 IF p_operation IN('reset','reconcile_adjust') AND EXISTS(SELECT 1 FROM public.bf_shift_cash_variances v WHERE v.cafe_id=p_cafe_id AND NOT EXISTS(SELECT 1 FROM public.bf_shift_cash_resolutions r WHERE r.variance_id=v.id)) THEN RAISE EXCEPTION 'سو فروقات الورديات المعلقة قبل تصحيح الأرصدة'; END IF;
 IF p_operation='reverse' AND (EXISTS(SELECT 1 FROM public.bf_shift_cash_variances WHERE cafe_id=p_cafe_id AND document_id=(p_payload->>'documentId')::uuid) OR EXISTS(SELECT 1 FROM public.bf_shift_cash_resolutions WHERE cafe_id=p_cafe_id AND document_id=(p_payload->>'documentId')::uuid)) THEN RAISE EXCEPTION 'قيود فروقات الورديات لا تعكس من التصحيح العام'; END IF;

 IF p_operation IN('reset','reconcile_adjust') AND EXISTS(SELECT 1 FROM public.bf_cash_handovers h WHERE h.cafe_id=p_cafe_id AND NOT EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts r WHERE r.handover_id=h.id)) THEN RAISE EXCEPTION 'استلم تسليمات النقدية المعلقة قبل تصحيح الأرصدة'; END IF;
 IF p_operation='reverse' AND (EXISTS(SELECT 1 FROM public.bf_cash_handovers WHERE cafe_id=p_cafe_id AND document_id=(p_payload->>'documentId')::uuid) OR EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts WHERE cafe_id=p_cafe_id AND document_id=(p_payload->>'documentId')::uuid)) THEN RAISE EXCEPTION 'قيود تسليم واستلام الورديات لا تعكس من التصحيح العام'; END IF;
 IF p_operation='reverse' THEN
  SELECT d.* INTO original FROM public.bf_documents d JOIN public.bf_treasury_documents t ON t.cafe_id=d.cafe_id AND t.document_id=d.id
  WHERE d.cafe_id=p_cafe_id AND d.id=(p_payload->>'documentId')::uuid AND t.operation IN('opening','voucher','transfer','pos_settle','pos_fee_pay');
  IF NOT FOUND OR EXISTS(SELECT 1 FROM public.bf_treasury_documents WHERE cafe_id=p_cafe_id AND reverses_id=original.id) THEN RAISE EXCEPTION 'المستند غير قابل للعكس أو سبق عكسه'; END IF;
  IF EXISTS(SELECT 1 FROM public.bf_terminal_fee_allocations paid JOIN public.bf_terminal_fee_charges charge ON charge.id=paid.charge_id JOIN public.bf_accounts terminal ON terminal.id=charge.terminal_id WHERE paid.cafe_id=p_cafe_id AND paid.document_id=original.id AND terminal.linked_bank_id IS DISTINCT FROM charge.bank_id) THEN RAISE EXCEPTION 'أعد ربط الشبكة بالبنك الأصلي قبل عكس سداد الرسوم'; END IF;
  IF EXISTS(SELECT 1 FROM public.bf_journal j JOIN public.bf_accounts acc ON acc.cafe_id=j.cafe_id AND acc.id=j.account_id WHERE j.cafe_id=p_cafe_id AND j.document_id=original.id AND NOT acc.active) THEN RAISE EXCEPTION 'أعد تفعيل الحساب المؤرشف قبل عكس مستنده'; END IF;
  IF EXISTS(SELECT 1 FROM public.bf_journal j JOIN public.bf_shifts s ON s.cafe_id=j.cafe_id AND s.account_id=j.account_id WHERE j.cafe_id=p_cafe_id AND j.document_id=original.id AND s.status IN('open','handover')) THEN RAISE EXCEPTION 'أغلق الوردية قبل تصحيح حسابها'; END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,account_id,total,reference_id,note,created_by) VALUES(doc,p_cafe_id,'journal',original.account_id,original.total,original.id,reason,p_actor_id) RETURNING number INTO n;
  FOR line IN SELECT * FROM public.bf_journal WHERE cafe_id=p_cafe_id AND document_id=original.id LOOP
   PERFORM brand_finance_private.line(p_cafe_id,doc,line.account_id,line.credit,line.debit,line.party_id);
  END LOOP;
  INSERT INTO public.bf_treasury_documents(cafe_id,document_id,operation,reverses_id) VALUES(p_cafe_id,doc,'reverse',original.id);
 ELSE
  IF p_operation='reconcile_adjust' THEN
   SELECT * INTO recon FROM public.bf_treasury_reconciliations WHERE cafe_id=p_cafe_id AND id=(p_payload->>'reconciliationId')::uuid;
   IF NOT FOUND OR recon.difference=0 OR EXISTS(SELECT 1 FROM public.bf_treasury_reconciliation_resolutions WHERE cafe_id=p_cafe_id AND reconciliation_id=recon.id) THEN RAISE EXCEPTION 'المطابقة غير قابلة للتسوية'; END IF;
   aid:=recon.account_id; amount:=recon.difference;
   IF brand_finance_private.treasury_balance(p_cafe_id,aid)<>recon.expected_amount THEN RAISE EXCEPTION 'تغير الرصيد سجل مطابقة جديدة قبل التسوية'; END IF;
  ELSIF p_operation='reset' THEN
   aid:=nullif(p_payload->>'accountId','')::uuid; balance:=brand_finance_private.treasury_balance(p_cafe_id,aid);
   IF balance IS DISTINCT FROM (p_payload->>'expectedBalance')::numeric THEN RAISE EXCEPTION 'تغير الرصيد حدث البيانات قبل التصحيح'; END IF;
   amount:=-balance;
  ELSE RAISE EXCEPTION 'Unknown treasury correction'; END IF;
  SELECT * INTO a FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=aid AND kind IN('cash','bank','pos') AND active;
  IF NOT FOUND OR amount IS NULL OR amount=0 THEN RAISE EXCEPTION 'Invalid correction account or amount'; END IF;
  IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND account_id=aid AND status IN('open','handover')) THEN RAISE EXCEPTION 'أغلق الوردية قبل تصحيح حسابها'; END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,account_id,total,note,created_by) VALUES(doc,p_cafe_id,'journal',aid,abs(amount),reason,p_actor_id) RETURNING number INTO n;
  PERFORM brand_finance_private.line(p_cafe_id,doc,aid,greatest(amount,0),greatest(-amount,0));
  PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,CASE WHEN p_operation='reset' THEN '3000' ELSE '5300' END),greatest(-amount,0),greatest(amount,0));
  INSERT INTO public.bf_treasury_documents(cafe_id,document_id,operation) VALUES(p_cafe_id,doc,p_operation);
  IF p_operation='reconcile_adjust' THEN INSERT INTO public.bf_treasury_reconciliation_resolutions(cafe_id,reconciliation_id,document_id) VALUES(p_cafe_id,recon.id,doc); END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM public.bf_accounts acc JOIN public.bf_journal j ON j.cafe_id=acc.cafe_id AND j.account_id=acc.id WHERE acc.cafe_id=p_cafe_id AND acc.kind IN('cash','bank','pos') AND acc.id IN(SELECT account_id FROM public.bf_journal WHERE cafe_id=p_cafe_id AND document_id=doc) GROUP BY acc.id HAVING sum(j.debit-j.credit)<0) THEN RAISE EXCEPTION 'التصحيح يؤدي إلى رصيد سالب'; END IF;
 result:=jsonb_build_object('id',doc,'number',n);
 INSERT INTO public.bf_treasury_audit(cafe_id,actor_id,operation,entity_id,after_data) VALUES(p_cafe_id,p_actor_id,p_operation,doc,p_payload||result);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'treasury_correct:'||p_operation,p_payload,result,p_actor_id);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION erp_treasury_private.current_branch_before_treasury(c uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$DECLARE proof_id uuid:=nullif(current_setting('erp.payment_proof',true),'')::uuid;invoice_id uuid;b uuid;BEGIN
 IF proof_id IS NOT NULL THEN
  SELECT p.invoice_id INTO invoice_id FROM erp_settings_private.payment_proofs p WHERE p.id=proof_id AND p.cafe_id=c AND p.actor=auth.uid() AND brand_finance_private.role_for(c)='owner';
  IF invoice_id IS NULL THEN RAISE EXCEPTION 'سياق تحصيل غير مصرح' USING ERRCODE='42501';END IF;
  SELECT branch_id INTO b FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=invoice_id;
  IF b IS NOT NULL AND NOT erp_branch_private.branch_allowed(c,b) THEN RAISE EXCEPTION 'فرع تحصيل غير متاح' USING ERRCODE='42501';END IF;RETURN b;
 END IF;RETURN erp_branch_private.current_branch_before_provider_payment(c);
END $function$

CREATE OR REPLACE FUNCTION erp_treasury_private.terminal_fee_accrue(p_cafe uuid, p_terminal uuid, p_source uuid, p_month date, p_base numeric)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE b uuid;prior jsonb;BEGIN
 PERFORM erp_branch_private.assert_input(p_cafe,jsonb_build_object('accountId',p_terminal,'documentId',p_source));b:=erp_treasury_private.fee_branch(p_cafe,p_terminal,p_source);
 IF b IS NOT NULL AND NOT erp_branch_private.branch_allowed(p_cafe,b) THEN RETURN;END IF;
 prior:=jsonb_build_object('source',current_setting('erp.treasury_fee_source',true),'branch',current_setting('erp.branch_id',true),'cafe',current_setting('erp.branch_cafe',true));
 PERFORM set_config('erp.treasury_fee_source',jsonb_build_object('cafe',p_cafe,'terminal',p_terminal,'source',p_source,'actor',auth.uid(),'branchId',b)::text,true);PERFORM set_config('erp.branch_cafe',p_cafe::text,true);PERFORM set_config('erp.branch_id',coalesce(b::text,''),true);
 PERFORM brand_finance_private.terminal_fee_accrue(p_cafe,p_terminal,p_source,p_month,p_base);
 PERFORM set_config('erp.treasury_fee_source',coalesce(prior->>'source',''),true);PERFORM set_config('erp.branch_cafe',coalesce(prior->>'cafe',''),true);PERFORM set_config('erp.branch_id',coalesce(prior->>'branch',''),true);
END $function$

CREATE OR REPLACE FUNCTION erp_treasury_private.terminal_monthly_ensure_at(p_cafe uuid, p_today date, p_skip_current_terminal uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE a record; month_value date; closed date; current_month date:=date_trunc('month',p_today)::date;
BEGIN
 IF p_today IS NULL THEN RAISE EXCEPTION 'Billing date required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 SELECT closed_through INTO closed FROM erp_branch_private.bf_settings WHERE cafe_id=p_cafe;
 IF closed>=(now() AT TIME ZONE 'Asia/Riyadh')::date THEN RETURN; END IF;
 FOR a IN SELECT id,fee_started_month,monthly_due_day FROM erp_branch_private.bf_accounts WHERE cafe_id=p_cafe AND kind='pos' AND active AND monthly_subscription>0 AND fee_started_month IS NOT NULL LOOP
  FOR month_value IN SELECT generate_series(a.fee_started_month,current_month,interval '1 month')::date LOOP
   IF month_value=current_month AND a.id=p_skip_current_terminal THEN CONTINUE; END IF;
   IF brand_finance_private.terminal_monthly_due_date(month_value,a.monthly_due_day)<=p_today THEN
    PERFORM erp_treasury_private.terminal_fee_accrue(p_cafe,a.id,NULL,month_value,0);
   END IF;
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION erp_work_private.link(c uuid, o uuid, k text, i uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE t jsonb;customer uuid;BEGIN
 t:=erp_work_private.target(c,k,i);IF t IS NULL THEN RAISE EXCEPTION 'المعاملة غير متاحة لهذه العلامة' USING ERRCODE='22023';END IF;
 SELECT customer_id INTO customer FROM public.erp_work_orders WHERE cafe_id=c AND id=o;
 IF t->>'kind' IN('sale','quotation','credit_note') AND nullif(t->>'partyId','')::uuid IS DISTINCT FROM customer THEN RAISE EXCEPTION 'عميل المعاملة لا يطابق عميل أمر الشغل' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM public.erp_work_order_links WHERE cafe_id=c AND kind=k AND target_id=i AND order_id<>o) THEN RAISE EXCEPTION 'المعاملة مرتبطة بأمر شغل آخر' USING ERRCODE='23505';END IF;
 INSERT INTO public.erp_work_order_links(cafe_id,order_id,kind,target_id) VALUES(c,o,k,i) ON CONFLICT DO NOTHING;
END$function$

CREATE OR REPLACE FUNCTION erp_work_private.source_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE k text:=CASE TG_TABLE_NAME WHEN 'bf_documents' THEN 'document' WHEN 'bf_quotes' THEN 'quotation' WHEN 'bf_credit_notes' THEN 'credit_note' ELSE 'task' END;data jsonb;customer uuid;linked public.erp_work_order_links%ROWTYPE;
BEGIN
 SELECT * INTO linked FROM public.erp_work_order_links WHERE cafe_id=OLD.cafe_id AND kind=k AND target_id=OLD.id;
 IF NOT FOUND THEN IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'ألغ ارتباط المعاملة بأمر الشغل قبل حذفها' USING ERRCODE='23503';END IF;
 data:=to_jsonb(NEW);
 IF NEW.cafe_id IS DISTINCT FROM OLD.cafe_id OR NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'لا تغير ملكية معاملة مرتبطة' USING ERRCODE='23503';END IF;
 IF k IN('quotation','credit_note') OR(k='document' AND data->>'kind'='sale') THEN
  customer:=nullif(CASE WHEN k='quotation' THEN data#>>'{payload,invoice,partyId}' ELSE data->>'party_id' END,'')::uuid;
  IF EXISTS(SELECT 1 FROM public.erp_work_orders WHERE cafe_id=linked.cafe_id AND id=linked.order_id AND customer_id IS DISTINCT FROM customer) THEN RAISE EXCEPTION 'عميل المعاملة لا يطابق أمر الشغل' USING ERRCODE='22023';END IF;
 END IF;RETURN NEW;
END$function$

CREATE OR REPLACE FUNCTION erp_work_private.target(c uuid, k text, i uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE r jsonb;v text;row_data jsonb;BEGIN
 r:=erp_work_private.target_before_sales_display(c,k,i);
 IF r IS NULL OR k NOT IN('quotation','credit_note') THEN RETURN r;END IF;
 IF k='quotation' THEN SELECT to_jsonb(q) INTO row_data FROM public.bf_quotes q WHERE q.cafe_id=c AND q.id=i;ELSE SELECT to_jsonb(n) INTO row_data FROM public.bf_credit_notes n WHERE n.cafe_id=c AND n.id=i;END IF;
 IF NOT erp_settings_private.sales_number_visible(c,row_data) THEN RETURN r;END IF;
 v:=erp_settings_private.display_record(c,r,ARRAY[CASE k WHEN 'quotation' THEN 'sales_quote' ELSE 'sales_credit_note' END])->>'displayNumber';
 RETURN CASE WHEN v IS NULL THEN r ELSE r||jsonb_build_object('displayNumber',v,'label',CASE k WHEN 'quotation' THEN 'عرض سعر #' ELSE 'إشعار دائن #' END||v) END;
END$function$

CREATE OR REPLACE FUNCTION erp_work_private.target_before_sales_display(c uuid, k text, i uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE r jsonb;BEGIN
 IF k='document' THEN SELECT jsonb_build_object('id',d.id,'kind',d.kind,'label',d.kind||' #'||d.number,'amount',coalesce((brand_finance_private.document_state(c,d.id)->>'total')::numeric,CASE WHEN d.kind='journal' AND d.total=0 THEN (SELECT coalesce(sum(j.debit),0) FROM public.bf_journal j WHERE j.cafe_id=c AND j.document_id=d.id) ELSE d.total END),'partyId',d.party_id,'outstanding',(brand_finance_private.document_state(c,d.id)->>'outstanding')::numeric,'refunded',coalesce((brand_finance_private.document_state(c,d.id)->>'refunded_total')::numeric,0)) INTO r FROM public.bf_documents d WHERE cafe_id=c AND id=i;
 ELSIF k='quotation' THEN SELECT jsonb_build_object('id',id,'kind','quotation','label','عرض سعر #'||number,'amount',total,'partyId',payload#>>'{invoice,partyId}') INTO r FROM public.bf_quotes WHERE cafe_id=c AND id=i;
 ELSIF k='credit_note' THEN SELECT jsonb_build_object('id',id,'kind','credit_note','label','إشعار دائن #'||number,'amount',CASE WHEN status='issued' THEN total ELSE 0 END,'partyId',party_id) INTO r FROM public.bf_credit_notes WHERE cafe_id=c AND id=i AND status<>'deleted';
 ELSIF k='task' THEN SELECT jsonb_build_object('id',id,'kind','task','label',title,'amount',0) INTO r FROM public.erp_tasks WHERE cafe_id=c AND id=i;
 END IF;RETURN r;END$function$

CREATE OR REPLACE FUNCTION erp_work_private.validate_values(fields jsonb, vals jsonb, p_cafe uuid DEFAULT NULL::uuid, p_record uuid DEFAULT NULL::uuid, depth integer DEFAULT 0, p_draft boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE f jsonb;v jsonb;t text;x jsonb;txt text;tbl text;col text;valid boolean;metric numeric;BEGIN
 IF coalesce(jsonb_typeof(vals),'')<>'object' OR octet_length(vals::text)>262144 OR depth>2 THEN RAISE EXCEPTION 'بيانات الحقول الإضافية غير صالحة';END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(coalesce(fields,'[]')) LOOP
  t:=f->>'type';IF t IN('static','separator') THEN CONTINUE;END IF;
  v:=coalesce(vals->(f->>'id'),f->'defaultValue');
  IF coalesce((f->>'required')::boolean,false) AND NOT p_draft AND (v IS NULL OR v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb OR (t='checkbox' AND v<>'true')) THEN RAISE EXCEPTION 'أكمل الحقل المطلوب: %',f->>'label';END IF;
  IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb THEN CONTINUE;END IF;
  IF t='subform' THEN
   IF jsonb_typeof(v)<>'array' OR jsonb_array_length(v)>100 OR jsonb_array_length(v)<coalesce((f->>'minimumRows')::integer,0) THEN RAISE EXCEPTION 'عدد صفوف النموذج غير صالح';END IF;
   FOR x IN SELECT value FROM jsonb_array_elements(v) LOOP PERFORM erp_work_private.validate_values(f->'fields',x,p_cafe,p_record,depth+1,p_draft);END LOOP;CONTINUE;
  END IF;
  IF t='location' THEN
   IF jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'latitude')<>'number' OR jsonb_typeof(v->'longitude')<>'number' OR abs((v->>'latitude')::numeric)>90 OR abs((v->>'longitude')::numeric)>180 THEN RAISE EXCEPTION 'إحداثيات الموقع غير صالحة';END IF;CONTINUE;
  END IF;
  IF (t IN('number','currency') AND jsonb_typeof(v)<>'number') OR (t='checkbox' AND jsonb_typeof(v)<>'boolean') OR (t IN('multiselect','multidynamic') AND jsonb_typeof(v)<>'array') OR (t NOT IN('number','currency','checkbox','multiselect','multidynamic') AND jsonb_typeof(v)<>'string') THEN RAISE EXCEPTION 'نوع قيمة الحقل غير صالح';END IF;
  txt:=v#>>'{}';
  IF length(txt)>20000 THEN RAISE EXCEPTION 'قيمة الحقل طويلة';END IF;
  IF (t='select' AND NOT(f->'options' @> jsonb_build_array(v))) OR (t='multiselect' AND NOT(f->'options' @> v)) THEN RAISE EXCEPTION 'اختيارات الحقل غير صالحة';END IF;
  IF t='email' AND txt!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'البريد الإلكتروني غير صالح';END IF;
  IF t='url' AND txt!~'^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'الرابط غير صالح';END IF;
  IF t='time' AND txt!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'الوقت غير صالح';END IF;
  IF t='date' THEN IF txt!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'التاريخ غير صالح';END IF;PERFORM txt::date;END IF;
  IF t IN('number','currency','text','textarea','formatted') THEN
   metric:=CASE WHEN t IN('number','currency') THEN txt::numeric ELSE length(txt) END;
   IF metric<nullif(f->>'minimum','')::numeric OR metric>nullif(f->>'maximum','')::numeric THEN RAISE EXCEPTION 'قيمة الحقل خارج الحدود: %',f->>'label';END IF;
  END IF;
  IF t IN('dynamic','multidynamic') THEN
   tbl:=CASE f->>'entity' WHEN 'items' THEN 'bf_items' WHEN 'customers' THEN 'bf_parties' WHEN 'employees' THEN 'bf_staff' WHEN 'warehouses' THEN 'bf_warehouses' WHEN 'accounts' THEN 'bf_accounts' WHEN 'bom' THEN 'erp_mfg_boms' WHEN 'routings' THEN 'erp_mfg_routings' WHEN 'workstations' THEN 'erp_mfg_workstations' WHEN 'orders' THEN 'erp_mfg_orders' WHEN 'sources' THEN 'bf_documents' END;
   IF tbl IS NULL OR p_cafe IS NULL THEN RAISE EXCEPTION 'الكيان المرتبط غير صالح';END IF;col:=CASE WHEN tbl='bf_staff' THEN 'user_id' ELSE 'id' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN t='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND %I=$2)',tbl,col) INTO valid USING p_cafe,(x#>>'{}')::uuid;
    IF NOT valid THEN RAISE EXCEPTION 'القيمة المرتبطة غير موجودة في العلامة';END IF;
   END LOOP;
  END IF;
  IF t IN('file','image') THEN
   IF p_record IS NULL OR to_regclass('public.erp_files') IS NULL THEN RAISE EXCEPTION 'احفظ السجل وأضف المرفق أولًا';END IF;
   EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=$1 AND record_id=$2 AND id=$3 AND entity_type=$4 AND uploaded AND ($5<>''image'' OR mime IN(''image/jpeg'',''image/png'')))' INTO valid USING p_cafe,p_record,txt::uuid,'work_order',t;
   IF NOT valid THEN RAISE EXCEPTION 'المرفق غير موجود في هذا السجل';END IF;
  END IF;
  IF coalesce((f->>'unique')::boolean,false) AND depth=0 THEN
   tbl:='erp_work_orders';
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id IS DISTINCT FROM $2 AND custom_values->$3=$4)',tbl) INTO valid USING p_cafe,p_record,f->>'id',v;
