  ELSIF mode='roles' THEN IF to_regclass('public.erp_roles') IS NULL THEN valid:=false;ELSE SELECT EXISTS(SELECT 1 FROM public.erp_roles WHERE cafe_id=c AND id=x::uuid AND active) INTO valid;END IF;
