  IF t IN('dynamic','multidynamic') THEN
   tbl:=CASE f->>'entity' WHEN 'items' THEN 'bf_items' WHEN 'customers' THEN 'bf_parties' WHEN 'employees' THEN 'bf_staff' WHEN 'warehouses' THEN 'bf_warehouses' WHEN 'accounts' THEN 'bf_accounts' WHEN 'bom' THEN 'erp_mfg_boms' WHEN 'routings' THEN 'erp_mfg_routings' WHEN 'workstations' THEN 'erp_mfg_workstations' WHEN 'orders' THEN 'erp_mfg_orders' WHEN 'sources' THEN 'bf_documents' END;
   IF tbl IS NULL OR p_cafe IS NULL THEN RAISE EXCEPTION 'الكيان المرتبط غير صالح';END IF;col:=CASE WHEN tbl='bf_staff' THEN 'user_id' ELSE 'id' END;
   FOR x IN SELECT value FROM jsonb_array_elements(CASE WHEN t='dynamic' THEN jsonb_build_array(v) ELSE v END) LOOP
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND %I=$2)',tbl,col) INTO valid USING p_cafe,(x#>>'{}')::uuid;
    IF NOT valid THEN RAISE EXCEPTION 'القيمة المرتبطة غير موجودة في العلامة';END IF;
   END LOOP;
  END IF;
  IF t IN('file','image') THEN
   IF p_record IS NULL OR to_regclass('public.erp_files') IS NULL THEN RAISE EXCEPTION 'احفظ السجل وأضف المرفق أولًا';END IF;
   EXECUTE 'SELECT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=$1 AND record_id=$2 AND id=$3 AND entity_type=$4 AND uploaded AND ($5<>''image'' OR mime IN(''image/jpeg'',''image/png'')))' INTO valid USING p_cafe,p_record,txt::uuid,'workflow_record',t;
   IF NOT valid THEN RAISE EXCEPTION 'المرفق غير موجود في هذا السجل';END IF;
  END IF;
  IF coalesce((f->>'unique')::boolean,false) AND depth=0 THEN
   tbl:='erp_workflow_records';
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id IS DISTINCT FROM $2 AND payload->''customValues''->$3=$4 AND type_id=$5)',tbl) INTO valid USING p_cafe,p_record,f->>'id',v,p_scope;
   IF valid THEN RAISE EXCEPTION 'قيمة الحقل مستخدمة مسبقًا: %',f->>'label';END IF;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_add_invoice_line_notes(p_cafe_id uuid, p_texts jsonb, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE state jsonb; settings jsonb; entry_value jsonb; notes jsonb; added boolean:=false;
BEGIN
  IF auth.uid() IS NULL OR brand_finance_private.role_for(p_cafe_id) IS DISTINCT FROM 'owner' THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  IF p_revision IS NULL OR p_revision<0 OR jsonb_typeof(p_texts) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'راجع الملاحظات المراد حفظها' USING ERRCODE='22023';END IF;
  IF jsonb_array_length(p_texts) NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'الحد الأقصى ١٠ ملاحظات في المرة الواحدة' USING ERRCODE='22023';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60621));
  state:=public.brand_finance_invoice_line_notes(p_cafe_id);settings:=state->'settings';notes:=settings->'notes';
  FOR entry_value IN SELECT x FROM jsonb_array_elements(p_texts) x LOOP
    IF jsonb_typeof(entry_value) IS DISTINCT FROM 'string' OR length(entry_value#>>'{}') NOT BETWEEN 1 AND 50 OR entry_value#>>'{}' !~ '[^[:space:]]' THEN RAISE EXCEPTION 'نص الملاحظة مطلوب وبحد أقصى ٥٠ حرفًا مع المسافات' USING ERRCODE='22023';END IF;
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(notes) n WHERE lower(btrim(n->>'text'))=lower(btrim(entry_value#>>'{}'))) THEN
      notes:=notes||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'text',entry_value#>>'{}','active',true));added:=true;
    END IF;
  END LOOP;
  IF NOT added THEN RETURN state;END IF;
  RETURN public.brand_finance_invoice_line_notes(p_cafe_id,'save',jsonb_set(settings,'{notes}',notes),p_revision);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_add_sales_cashier(p_cafe_id uuid, p_user_id uuid, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_name text:=btrim(p_name); v_user auth.users%ROWTYPE;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_add_sales_cashier',NULL);
 IF brand_finance_private.role_for(p_cafe_id)<>'owner'
   OR NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe_id AND owner_user_id=auth.uid())
   THEN RAISE EXCEPTION 'Finance owner access required' USING ERRCODE='42501'; END IF;
 IF v_name IS NULL OR length(v_name) NOT BETWEEN 2 AND 100 OR p_user_id IS NULL
   THEN RAISE EXCEPTION 'Invalid sales cashier'; END IF;
 SELECT * INTO v_user FROM auth.users WHERE id=p_user_id FOR UPDATE;
 IF NOT FOUND OR v_user.phone_confirmed_at IS NULL
   OR regexp_replace(coalesce(v_user.phone,''),'^\+','') !~ '^9665[0-9]{8}$'
   OR v_user.raw_app_meta_data->'finance_staff_provisioned' IS DISTINCT FROM 'true'::jsonb
   OR v_user.raw_app_meta_data->>'finance_cafe_id' IS DISTINCT FROM p_cafe_id::text
   OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user_id AND status='active' AND role='customer')
   THEN RAISE EXCEPTION 'Trusted sales cashier identity required' USING ERRCODE='42501'; END IF;
 -- No upsert: existing accounts and existing memberships are never repurposed.
 IF EXISTS(SELECT 1 FROM public.bf_staff WHERE user_id=p_user_id)
   THEN RAISE EXCEPTION 'Sales cashier already assigned' USING ERRCODE='23505'; END IF;
 INSERT INTO public.bf_staff(cafe_id,user_id,name,role,active) VALUES(p_cafe_id,p_user_id,v_name,'cashier',true);
 RETURN jsonb_build_object('id',p_user_id,'role','cashier');
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_cash_differences(p_cafe_id uuid, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; result jsonb;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_cash_differences',NULL);
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF role_name NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'إدارة المالية مطلوبة لعرض الفروقات' USING ERRCODE='42501'; END IF;
 IF p_offset IS NULL OR p_offset<0 OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'نطاق السجلات غير صالح'; END IF;
 SELECT jsonb_build_object(
  'rows',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY occurred_at DESC,id DESC) FROM (
   SELECT v.id,v.shift_id,v.shift_number,v.phase,v.occurred_at,v.drawer_id,v.drawer_name,v.employee_id,v.employee_name,v.previous_employee_id,v.previous_employee_name,v.expected_cash,v.counted_cash,v.difference,v.document_id,d.number document_number,
   coalesce(r.resolution,'pending') status,r.employee_id resolution_employee_id,r.employee_name resolution_employee_name,r.settled_at,r.note settlement_note,r.document_id resolution_document_id,rd.number resolution_document_number,a.status notification_status
   FROM public.bf_shift_cash_variances v JOIN public.bf_documents d ON d.id=v.document_id LEFT JOIN public.bf_shift_cash_resolutions r ON r.variance_id=v.id LEFT JOIN public.bf_documents rd ON rd.id=r.document_id LEFT JOIN public.bf_shift_cash_alerts a ON a.variance_id=v.id
   WHERE v.cafe_id=p_cafe_id ORDER BY v.occurred_at DESC,v.id DESC OFFSET p_offset LIMIT p_limit) x),'[]'::jsonb),
  'total',(SELECT count(*) FROM public.bf_shift_cash_variances WHERE cafe_id=p_cafe_id),
  'canSettle',EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe_id AND owner_user_id=auth.uid()),
  'employees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.user_id,'name',e.name) ORDER BY e.name,e.user_id) FROM (
   SELECT DISTINCT ON(user_id) user_id,name FROM (
    SELECT s.user_id,s.name,0 priority,now() at_time FROM public.bf_staff s WHERE s.cafe_id=p_cafe_id AND s.active
    UNION ALL SELECT v.employee_id,v.employee_name,1,v.occurred_at FROM public.bf_shift_cash_variances v WHERE v.cafe_id=p_cafe_id
    UNION ALL SELECT v.previous_employee_id,v.previous_employee_name,1,v.occurred_at FROM public.bf_shift_cash_variances v WHERE v.cafe_id=p_cafe_id AND v.previous_employee_id IS NOT NULL
   ) candidates WHERE EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=candidates.user_id AND p.status='active') ORDER BY user_id,priority,at_time DESC
  ) e),'[]'::jsonb)
 ) INTO result;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_cash_handovers(p_cafe_id uuid, p_offset integer DEFAULT 0, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; managed boolean; drawer uuid;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_cash_handovers',NULL);
 role_name:=brand_finance_private.role_for(p_cafe_id);managed:=role_name IN('owner','manager','accountant','auditor');
 IF p_offset IS NULL OR p_offset<0 OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'نطاق سجلات التسليم غير صالح'; END IF;
 PERFORM brand_finance_private.seed(p_cafe_id);drawer:=brand_finance_private.cashier_drawer(p_cafe_id);
 RETURN jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY created_at DESC,id DESC) FROM (
  SELECT h.id,h.shift_id,h.shift_number,h.drawer_id,h.drawer_name,h.receiving_drawer_id,h.receiving_drawer_name,h.amount,h.handover_type,h.from_user_id,h.from_name,h.recipient_user_id,h.recipient_name,h.recipient_phone,h.created_at,
   CASE WHEN r.handover_id IS NULL THEN 'pending' ELSE 'received' END status,r.received_at,r.received_by_name,r.received_counted_cash,d.number document_number,rd.number receipt_document_number
  FROM public.bf_cash_handovers h LEFT JOIN public.bf_cash_handover_receipts r ON r.handover_id=h.id LEFT JOIN public.bf_documents d ON d.id=h.document_id LEFT JOIN public.bf_documents rd ON rd.id=r.document_id
  WHERE h.cafe_id=p_cafe_id AND (managed OR h.from_user_id=auth.uid() OR r.received_by=auth.uid()) ORDER BY h.created_at DESC,h.id DESC OFFSET p_offset LIMIT p_limit
 ) x),'[]'::jsonb),
 'total',(SELECT count(*) FROM public.bf_cash_handovers h LEFT JOIN public.bf_cash_handover_receipts r ON r.handover_id=h.id WHERE h.cafe_id=p_cafe_id AND (managed OR h.from_user_id=auth.uid() OR r.received_by=auth.uid())),
 'canReceive',role_name IN('owner','manager','accountant'),'cashierDrawerId',drawer,
 'cashierDrawers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'busy',EXISTS(SELECT 1 FROM public.bf_shifts s WHERE s.cafe_id=p_cafe_id AND s.account_id=a.id AND s.status IN('open','handover'))) ORDER BY (a.code='1001-CASHIER') DESC,a.id) FROM public.bf_accounts a WHERE a.cafe_id=p_cafe_id AND a.is_cashier_drawer AND a.active),'[]'::jsonb),

 'accountants',coalesce((SELECT jsonb_agg(jsonb_build_object('user_id',s.user_id,'name',s.name) ORDER BY s.name,s.user_id) FROM public.bf_staff s JOIN public.profiles p ON p.id=s.user_id AND p.status='active' WHERE s.cafe_id=p_cafe_id AND s.role IN('manager','accountant') AND s.active),'[]'::jsonb));
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_claim_cash_alerts(p_cafe_id uuid DEFAULT NULL::uuid, p_shift_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a record; result jsonb:='[]'::jsonb; token uuid; phone text;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid alert limit'; END IF;
 UPDATE public.bf_shift_cash_alerts SET status='unknown',completed_at=now(),error_code='lease_expired' WHERE status='processing' AND claimed_at<now()-interval '5 minutes';
 FOR a IN SELECT q.id,v.phase,v.shift_number,v.difference,v.drawer_name,v.employee_name,v.previous_employee_name,q.created_at,c.name brand_name,c.owner_user_id,c.status cafe_status,c.deleted_at,q.cafe_id
  FROM public.bf_shift_cash_alerts q JOIN public.bf_shift_cash_variances v ON v.id=q.variance_id JOIN public.cafes c ON c.id=q.cafe_id
  WHERE q.status='pending' AND (p_cafe_id IS NULL OR q.cafe_id=p_cafe_id) AND (p_shift_id IS NULL OR v.shift_id=p_shift_id)
  ORDER BY q.created_at,q.id LIMIT p_limit FOR UPDATE OF q SKIP LOCKED
 LOOP
  phone:=NULL;
  IF a.cafe_status IN('active','published') AND a.deleted_at IS NULL THEN
   SELECT nullif(btrim(p.phone),'') INTO phone FROM public.profiles p WHERE p.id=a.owner_user_id AND p.status='active';
  END IF;
  IF phone IS NULL THEN UPDATE public.bf_shift_cash_alerts SET status='missing_owner',completed_at=now(),error_code='owner_phone_missing' WHERE id=a.id;CONTINUE; END IF;
  token:=gen_random_uuid();
  UPDATE public.bf_shift_cash_alerts SET status='processing',lease_token=token,claimed_at=now() WHERE id=a.id;
  result:=result||jsonb_build_array(jsonb_build_object('id',a.id,'leaseToken',token,'phase',a.phase,'shiftNumber',a.shift_number,'difference',a.difference,'ownerPhone',phone,'brandName',a.brand_name,'drawerName',a.drawer_name,'employeeName',a.employee_name,'previousEmployeeName',a.previous_employee_name,'createdAt',a.created_at));
 END LOOP;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_claim_company_delivery(p_cafe_id uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE invoice jsonb; delivery public.bf_company_invoice_deliveries%ROWTYPE;
BEGIN
  invoice:=public.brand_finance_company_invoice(p_cafe_id,p_id);
  IF invoice IS NULL THEN RAISE EXCEPTION 'Invoice unavailable' USING ERRCODE='42501'; END IF;
  IF coalesce(invoice#>>'{customer,phone}','') !~ '^9665[0-9]{8}$' THEN RAISE EXCEPTION 'Invalid recipient'; END IF;
  IF invoice ? 'documentType' AND coalesce(invoice->>'deliveryMethod','')<>'whatsapp' AND NOT coalesce((brand_finance_private.invoice_settings(p_cafe_id)#>>'{advanced,socialEnabled}')::boolean AND (brand_finance_private.invoice_settings(p_cafe_id)#>'{advanced,socialPlatforms}') ? 'whatsapp',false) THEN RAISE EXCEPTION 'إرسال الواتساب غير مفعل في إعدادات الفواتير';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60414));
  SELECT * INTO delivery FROM public.bf_company_invoice_deliveries WHERE document_id=(invoice->>'id')::uuid;
  IF FOUND THEN
    IF delivery.status='rejected' AND delivery.attempts<3 AND delivery.finished_at<clock_timestamp()-interval '30 seconds' THEN
      UPDATE public.bf_company_invoice_deliveries SET status='sending',lease_token=gen_random_uuid(),provider_message_id=NULL,finished_at=NULL,attempts=attempts+1
        WHERE document_id=delivery.document_id RETURNING * INTO delivery;
      RETURN jsonb_build_object('claimed',true,'id',delivery.document_id,'leaseToken',delivery.lease_token,'invoice',invoice);
    END IF;
    RETURN jsonb_build_object('claimed',false,'status',delivery.status);
  END IF;
  IF (SELECT count(*) FROM public.bf_company_invoice_deliveries WHERE cafe_id=p_cafe_id AND created_at>clock_timestamp()-interval '1 minute')>=20 THEN RAISE EXCEPTION 'Rate limited'; END IF;
  INSERT INTO public.bf_company_invoice_deliveries(document_id,cafe_id,created_by) VALUES((invoice->>'id')::uuid,p_cafe_id,auth.uid()) RETURNING * INTO delivery;
  RETURN jsonb_build_object('claimed',true,'id',delivery.document_id,'leaseToken',delivery.lease_token,'invoice',invoice);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_claim_company_email(p_cafe_id uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE invoice jsonb;recipient text;advanced jsonb;delivery public.bf_company_invoice_emails%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 invoice:=public.brand_finance_company_invoice(p_cafe_id,p_id);IF invoice IS NULL THEN RAISE EXCEPTION 'Invoice unavailable' USING ERRCODE='42501';END IF;
 advanced:=brand_finance_private.invoice_settings(p_cafe_id)->'advanced';
 IF NOT(coalesce(invoice->>'deliveryMethod','') IN('email','both') OR advanced->>'billingMethod' IN('email','both') OR ((advanced->>'socialEnabled')::boolean AND advanced->'socialPlatforms' ? 'email')) THEN RAISE EXCEPTION 'إرسال البريد الإلكتروني غير مفعل في إعدادات الفواتير';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60414));
 SELECT * INTO delivery FROM public.bf_company_invoice_emails WHERE cafe_id=p_cafe_id AND document_id=(invoice->>'id')::uuid;
 IF FOUND THEN
  IF delivery.status='failed' AND delivery.attempts<3 AND delivery.finished_at<clock_timestamp()-interval '30 seconds' AND delivery.created_at>clock_timestamp()-interval '23 hours' THEN
   UPDATE public.bf_company_invoice_emails SET status='processing',lease_token=gen_random_uuid(),attempts=attempts+1,provider_id=NULL,finished_at=NULL WHERE document_id=delivery.document_id RETURNING * INTO delivery;
  ELSE RETURN jsonb_build_object('claimed',false,'id',delivery.document_id,'email',delivery.email,'status',delivery.status,'idempotencyKey','branda-invoice-email-'||delivery.document_id);END IF;
 ELSE
  recipient:=coalesce(nullif(invoice#>>'{customer,email}',''),(SELECT p.email FROM public.bf_documents d JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=d.party_id WHERE d.cafe_id=p_cafe_id AND d.id=(invoice->>'id')::uuid));
  IF coalesce(recipient,'')!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'أكمل البريد الإلكتروني الصحيح للعميل';END IF;
  IF (SELECT count(*) FROM public.bf_company_invoice_emails WHERE cafe_id=p_cafe_id AND created_at>clock_timestamp()-interval '1 minute')>=20 THEN RAISE EXCEPTION 'تجاوزت حد إرسال الفواتير حاول بعد قليل';END IF;
  INSERT INTO public.bf_company_invoice_emails(document_id,cafe_id,email,created_by) VALUES((invoice->>'id')::uuid,p_cafe_id,recipient,auth.uid()) RETURNING * INTO delivery;
 END IF;
 RETURN jsonb_build_object('claimed',true,'id',delivery.document_id,'leaseToken',delivery.lease_token,'email',delivery.email,'status',delivery.status,'idempotencyKey','branda-invoice-email-'||delivery.document_id);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_claim_customer_messages(p_cafe_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid message batch'; END IF;
 UPDATE public.bf_customer_message_jobs SET state='unknown',finished_at=now(),error_code='dispatch_expired' WHERE public.brand_account_not_cancelled(cafe_id) AND state='dispatching' AND lease_until<=now() AND (p_cafe_id IS NULL OR cafe_id=p_cafe_id);
 UPDATE public.bf_customer_message_jobs j SET state='cancelled',finished_at=now() WHERE public.brand_account_not_cancelled(j.cafe_id) AND state='pending' AND (p_cafe_id IS NULL OR j.cafe_id=p_cafe_id)
 AND (NOT brand_finance_private.customer_loyalty_enabled(j.cafe_id) OR EXISTS(SELECT 1 FROM public.bf_sale_customers s WHERE s.document_id=j.document_id AND s.loyalty_status='refunded'));
 WITH picked AS(SELECT j.id FROM public.bf_customer_message_jobs j WHERE public.brand_account_not_cancelled(j.cafe_id) AND j.state='pending' AND (p_cafe_id IS NULL OR j.cafe_id=p_cafe_id) ORDER BY j.created_at,j.id LIMIT p_limit FOR UPDATE SKIP LOCKED),
 claimed AS(UPDATE public.bf_customer_message_jobs j SET state='dispatching',lease_token=gen_random_uuid(),lease_until=now()+interval '2 minutes' FROM picked WHERE j.id=picked.id RETURNING j.*)
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',j.id,'leaseToken',j.lease_token,'phone',s.phone,'brandName',c.name,'slug',c.slug,'invoiceNumber',d.number,'loyaltyStatus',s.loyalty_status,'cardCode',lc.card_code,'receipt',brand_finance_private.customer_message_receipt(j.cafe_id,j.document_id))),'[]'::jsonb) INTO result
 FROM claimed j JOIN public.bf_sale_customers s ON s.document_id=j.document_id JOIN public.bf_documents d ON d.id=j.document_id JOIN public.cafes c ON c.id=j.cafe_id
 LEFT JOIN public.loyalty_cards lc ON lc.id=s.card_id AND lc.cafe_id=j.cafe_id;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_company_file(p_cafe_id uuid, p_action text DEFAULT 'list'::text, p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_size bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE item public.bf_company_invoice_files%ROWTYPE; result jsonb;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN ('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 IF p_action='list' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY created_at DESC),'[]'::jsonb) INTO result FROM public.bf_company_invoice_files f WHERE cafe_id=p_cafe_id AND uploaded;
  RETURN result;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60415));
 SELECT * INTO item FROM public.bf_company_invoice_files WHERE cafe_id=p_cafe_id AND id=p_id FOR UPDATE;
 IF p_action='prepare' THEN
  IF p_id IS NULL OR coalesce(length(btrim(p_name)),0) NOT BETWEEN 1 AND 255 OR p_size IS NULL OR p_size NOT BETWEEN 1 AND 8388608 THEN RAISE EXCEPTION 'Invalid file'; END IF;
  IF FOUND THEN
   IF item.original_name<>p_name OR item.size_bytes<>p_size OR item.uploaded THEN RAISE EXCEPTION 'File conflict'; END IF;
   RETURN to_jsonb(item);
  END IF;
  IF (SELECT count(*)>=1000 OR coalesce(sum(size_bytes),0)+p_size>268435456 FROM public.bf_company_invoice_files WHERE cafe_id=p_cafe_id) THEN RAISE EXCEPTION 'File capacity reached'; END IF;
  INSERT INTO public.bf_company_invoice_files(id,cafe_id,created_by,original_name,size_bytes,storage_path)
   VALUES(p_id,p_cafe_id,auth.uid(),p_name,p_size,p_cafe_id::text||'/'||p_id::text) RETURNING * INTO item;
  RETURN to_jsonb(item);
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'File unavailable' USING ERRCODE='42501'; END IF;
 IF p_action='finalize' THEN
  IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='branda-company-invoice-files' AND name=item.storage_path AND (metadata->>'size')::bigint=item.size_bytes AND metadata->>'mimetype'='application/octet-stream') THEN RAISE EXCEPTION 'Upload incomplete'; END IF;
  UPDATE public.bf_company_invoice_files SET uploaded=true WHERE id=item.id RETURNING * INTO item;
 ELSIF p_action<>'get' OR NOT item.uploaded THEN RAISE EXCEPTION 'File unavailable' USING ERRCODE='42501'; END IF;
 RETURN to_jsonb(item);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_context(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c public.cafes%ROWTYPE; r text;
BEGIN
 SELECT * INTO c FROM public.cafes WHERE slug=lower(btrim(p_slug)) AND deleted_at IS NULL;
 IF c.id IS NULL THEN RAISE EXCEPTION 'Finance access denied' USING ERRCODE='42501'; END IF;
 r:=brand_finance_private.role_for(c.id);
 RETURN jsonb_build_object('id',c.id,'name',c.name,'slug',c.slug,'role',r,'businessCategory',c.business_category,'maintenance',r='owner' AND c.owner_user_id IS DISTINCT FROM auth.uid() AND brand_finance_private.invoice_settings_maintenance(c.id));
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_convert_quote(p_cafe_id uuid, p_id uuid, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q public.bf_quotes%ROWTYPE; payload jsonb; draft_id uuid; result jsonb;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN ('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60416));
 SELECT * INTO q FROM public.bf_quotes WHERE cafe_id=p_cafe_id AND id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'العرض غير متاح' USING ERRCODE='42501'; END IF;
 IF q.invoice_draft_id IS NOT NULL THEN RETURN (SELECT jsonb_build_object('id',id,'revision',revision) FROM public.bf_invoice_drafts WHERE id=q.invoice_draft_id AND cafe_id=p_cafe_id); END IF;
 IF q.revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'تغير العرض افتح أحدث نسخة' USING ERRCODE='40001'; END IF;
 IF q.payload->>'status' NOT IN ('ready','accepted') THEN RAISE EXCEPTION 'احفظ عرضًا جاهزًا أو مقبولًا قبل التحويل'; END IF;
 IF nullif(q.payload->>'validUntil','')::date < (now() AT TIME ZONE 'Asia/Riyadh')::date THEN RAISE EXCEPTION 'انتهت صلاحية العرض حدّثه قبل التحويل'; END IF;
 payload:=q.payload->'document';
 IF NOT (brand_finance_private.invoice_settings(p_cafe_id)->>'copyNotesOnConversion')::boolean THEN payload:=jsonb_set(payload,'{invoice,note}','""'::jsonb);END IF;
 payload:=jsonb_set(jsonb_set(payload,'{invoice,paymentKind}','"credit"'),'{invoice,accountId}','""');
 payload:=jsonb_set(payload,'{supplyDate}',to_jsonb(((now() AT TIME ZONE 'Asia/Riyadh')::date)::text));
 IF jsonb_typeof(payload->'extraFields')='array' AND jsonb_array_length(payload->'extraFields')<5 THEN
  payload:=jsonb_set(payload,'{extraFields}',(payload->'extraFields')||jsonb_build_array(jsonb_build_object('key',2147483647,'title','عرض السعر','value',q.number::text)));
 END IF;
 draft_id:=gen_random_uuid(); result:=public.brand_finance_save_invoice_draft(p_cafe_id,draft_id,0,payload);
 UPDATE public.bf_quotes SET invoice_draft_id=draft_id,revision=revision+1,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE id=q.id;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_copy_invoice_line_notes(p_cafe_id uuid, p_source_document_id uuid, p_draft_id uuid, p_draft_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE source jsonb;draft public.bf_invoice_drafts%ROWTYPE;historical jsonb;copied jsonb;
BEGIN
  IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  historical:=public.brand_finance_issued_line_notes(p_cafe_id,p_source_document_id)->'lines';
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
  SELECT * INTO draft FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=p_draft_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501';END IF;
  IF draft.revision IS DISTINCT FROM p_draft_revision THEN RAISE EXCEPTION 'Draft conflict' USING ERRCODE='40001';END IF;
  IF jsonb_array_length(historical)>0 THEN
    SELECT snapshot INTO source FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND document_id=p_source_document_id;
    IF source IS NULL OR jsonb_array_length(draft.payload#>'{invoice,lines}')<>jsonb_array_length(source->'lines')
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(source->'lines') WITH ORDINALITY s(value,position) WHERE (SELECT count(*) FROM jsonb_array_elements(draft.payload#>'{invoice,lines}') d WHERE (d->>'key')::numeric=s.position-1 AND coalesce(d->>'productId','')=coalesce(s.value->>'productId','') AND d->>'name'=s.value->>'name' AND (d->>'quantity')::numeric=(s.value->>'quantity')::numeric)<>1)
    THEN RAISE EXCEPTION 'تعذر مطابقة ملاحظات البنود مع مسودة النسخة' USING ERRCODE='22023';END IF;
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('key',h->'lineIndex','notes',h->'notes') ORDER BY (h->>'lineIndex')::integer),'[]'::jsonb) INTO copied FROM jsonb_array_elements(historical) h;
  RETURN public.brand_finance_set_invoice_line_notes(p_cafe_id,p_draft_id,p_draft_revision,0,copied);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_copy_invoice_shipping_charge(p_cafe_id uuid, p_source_document_id uuid, p_draft_id uuid, p_draft_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE historical jsonb;selected jsonb;context jsonb;option public.bf_shipping_options%ROWTYPE;aid uuid;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 historical:=public.brand_finance_issued_shipping_charge(p_cafe_id,p_source_document_id)->'charge';
 context:=public.brand_finance_invoice_shipping_charge_context(p_cafe_id,p_draft_id);
 IF historical IS NOT NULL AND historical<>'null'::jsonb THEN
  selected:=jsonb_build_object('optionId',historical->'optionId','name',historical->'name','amount',historical->'amount','taxRate',historical->'taxRate');
  IF historical->>'optionId' IS NOT NULL THEN
   SELECT * INTO option FROM public.bf_shipping_options WHERE cafe_id=p_cafe_id AND id=(historical->>'optionId')::uuid AND active AND deleted_at IS NULL;
   IF option.id IS NULL OR option.name IS DISTINCT FROM historical->>'name' THEN RAISE EXCEPTION 'تغير خيار الشحن الأصلي اختر خيار النسخة يدويًا' USING ERRCODE='22023';END IF;
  END IF;
  aid:=coalesce(option.account_id,brand_finance_private.account(p_cafe_id,'4000'));
  IF aid::text IS DISTINCT FROM historical->>'accountId' THEN RAISE EXCEPTION 'تغير حساب إيراد الشحن اختر خيار النسخة يدويًا' USING ERRCODE='22023';END IF;
 END IF;
 RETURN public.brand_finance_set_invoice_shipping_charge(p_cafe_id,p_draft_id,p_draft_revision,0,(context->>'settingsRevision')::integer,option.revision,selected);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_credit_notes(p_cafe_id uuid, p_id uuid DEFAULT NULL::uuid, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;filter_party uuid;filter_status text;query_value text;date_from date;date_to date;off integer;lim integer;answer jsonb;total_count bigint;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor','warehouse') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_id IS NOT NULL THEN RETURN (SELECT brand_finance_private.credit_note_record(n) FROM public.bf_credit_notes n WHERE cafe_id=p_cafe_id AND id=p_id AND status<>'deleted');END IF;
 IF jsonb_typeof(p_filters) IS DISTINCT FROM 'object' OR octet_length(p_filters::text)>2000 THEN RAISE EXCEPTION 'Invalid filters';END IF;
 filter_party:=nullif(p_filters->>'partyId','')::uuid;filter_status:=p_filters->>'status';query_value:=lower(trim(coalesce(p_filters->>'query','')));
 date_from:=nullif(p_filters->>'from','')::date;date_to:=nullif(p_filters->>'to','')::date;off:=coalesce((p_filters->>'offset')::integer,0);lim:=coalesce((p_filters->>'limit')::integer,30);
 IF off NOT BETWEEN 0 AND 100000 OR lim NOT BETWEEN 1 AND 100 OR length(query_value)>100 OR (filter_status IS NOT NULL AND filter_status NOT IN('draft','issued')) THEN RAISE EXCEPTION 'Invalid filters';END IF;
 SELECT count(*) INTO total_count FROM public.bf_credit_notes WHERE cafe_id=p_cafe_id AND status<>'deleted' AND (filter_party IS NULL OR party_id=filter_party) AND (filter_status IS NULL OR status=filter_status) AND (date_from IS NULL OR (payload->>'date')::date>=date_from) AND (date_to IS NULL OR (payload->>'date')::date<=date_to) AND (query_value='' OR position(query_value in lower(customer_name||' '||number::text||' '||coalesce(source_number::text,'')||' '||coalesce((SELECT value FROM erp_settings_private.numbers sn WHERE sn.cafe_id=p_cafe_id AND sn.context='sales_credit_note' AND sn.record_id=bf_credit_notes.id AND erp_settings_private.sales_number_visible(p_cafe_id,to_jsonb(bf_credit_notes))),'')))>0);
 SELECT coalesce(jsonb_agg(brand_finance_private.credit_note_record(n,false) ORDER BY created_at DESC,id),'[]'::jsonb) INTO answer FROM (SELECT * FROM public.bf_credit_notes WHERE cafe_id=p_cafe_id AND status<>'deleted' AND (filter_party IS NULL OR party_id=filter_party) AND (filter_status IS NULL OR status=filter_status) AND (date_from IS NULL OR (payload->>'date')::date>=date_from) AND (date_to IS NULL OR (payload->>'date')::date<=date_to) AND (query_value='' OR position(query_value in lower(customer_name||' '||number::text||' '||coalesce(source_number::text,'')||' '||coalesce((SELECT value FROM erp_settings_private.numbers sn WHERE sn.cafe_id=p_cafe_id AND sn.context='sales_credit_note' AND sn.record_id=bf_credit_notes.id AND erp_settings_private.sales_number_visible(p_cafe_id,to_jsonb(bf_credit_notes))),'')))>0) ORDER BY created_at DESC,id LIMIT lim OFFSET off) n;
 RETURN jsonb_build_object('items',answer,'total',total_count,'offset',off,'limit',lim);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_customer_credit(p_cafe_id uuid, p_action text, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;party uuid;request uuid;aid uuid;amount numeric;note text;journal_id uuid:=gen_random_uuid();prior public.bf_requests%ROWTYPE;account public.bf_accounts%ROWTYPE;
 application public.bf_customer_credit_events%ROWTYPE;source public.bf_documents%ROWTYPE;invoice public.bf_documents%ROWTYPE;answer jsonb;before_record jsonb;after_record jsonb;rev integer;balance numeric;offset_value integer:=0;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_action IS NULL OR p_action NOT IN('list','receive','refund','unapply') OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>5000 THEN RAISE EXCEPTION 'Invalid customer credit input' USING ERRCODE='22023';END IF;
 party:=(p_input->>'partyId')::uuid;
 IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=party AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح' USING ERRCODE='42501';END IF;
 IF p_action='list' THEN
  offset_value:=coalesce((p_input->>'offset')::integer,0);IF offset_value<0 OR offset_value>1000000 THEN RAISE EXCEPTION 'Invalid offset' USING ERRCODE='22023';END IF;
  RETURN jsonb_build_object('balance',brand_finance_private.customer_credit_balance(p_cafe_id,party),
   'entries',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'kind',e.action,'amount',e.amount,'createdAt',e.created_at,'documentId',e.invoice_id,'note',d.note) ORDER BY e.created_at DESC,e.id) FROM (SELECT * FROM public.bf_customer_credit_events WHERE cafe_id=p_cafe_id AND party_id=party ORDER BY created_at DESC,id LIMIT 200 OFFSET offset_value) e JOIN public.bf_documents d ON d.cafe_id=e.cafe_id AND d.id=e.document_id),'[]'::jsonb),
   'applications',coalesce((SELECT jsonb_agg(jsonb_build_object('paymentId',e.document_id,'documentId',e.invoice_id,'invoiceNumber',d.number,'displayNumber',x.display_number,'amount',e.amount,'reversible',brand_finance_private.customer_credit_unapply_allowed(p_cafe_id,e.document_id)) ORDER BY e.created_at DESC,e.id) FROM public.bf_customer_credit_events e JOIN public.bf_documents d ON d.cafe_id=e.cafe_id AND d.id=e.invoice_id LEFT JOIN public.bf_invoice_extensions x ON x.document_id=d.id WHERE e.cafe_id=p_cafe_id AND e.party_id=party AND e.action='apply' AND NOT EXISTS(SELECT 1 FROM public.bf_customer_credit_events r WHERE r.application_id=e.id)),'[]'::jsonb));
 END IF;
 IF role_name NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 request:=(p_input->>'requestId')::uuid;note:=btrim(coalesce(p_input->>'note',''));IF request IS NULL OR length(note) NOT BETWEEN 3 AND 500 THEN RAISE EXCEPTION 'أكمل بيان عملية الرصيد' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=request;
 IF FOUND THEN IF prior.operation<>'customer_credit_'||p_action OR prior.payload<>p_input OR prior.created_by<>auth.uid() THEN RAISE EXCEPTION 'Credit request conflict' USING ERRCODE='40001';END IF;RETURN prior.result;END IF;
 PERFORM brand_finance_private.seed(p_cafe_id);PERFORM brand_finance_private.gl_date_open(p_cafe_id,(now() AT TIME ZONE 'Asia/Riyadh')::date);
 IF p_action='receive' AND NOT(brand_finance_private.invoice_settings(p_cafe_id)->>'allowDeposits')::boolean THEN RAISE EXCEPTION 'الدفعات المقدمة غير مفعلة في إعدادات الفواتير';END IF;
 balance:=brand_finance_private.customer_credit_balance(p_cafe_id,party);aid:=brand_finance_private.customer_credit_account(p_cafe_id);
 IF p_action='unapply' THEN
  SELECT * INTO application FROM public.bf_customer_credit_events WHERE cafe_id=p_cafe_id AND party_id=party AND document_id=(p_input->>'paymentId')::uuid AND action='apply';
  IF application.id IS NULL OR NOT brand_finance_private.customer_credit_unapply_allowed(p_cafe_id,application.document_id) THEN RAISE EXCEPTION 'لا يمكن إلغاء رصيد استندت إليه مبالغ معادة أو فترة مقفلة';END IF;
  SELECT * INTO source FROM public.bf_documents d WHERE d.cafe_id=p_cafe_id AND d.id=application.document_id FOR UPDATE;
  SELECT * INTO invoice FROM public.bf_documents d WHERE d.cafe_id=p_cafe_id AND d.id=application.invoice_id FOR UPDATE;
  amount:=application.amount;before_record:=brand_finance_private.invoice_payment_record(source,invoice);
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,reference_id,note,created_by) VALUES(journal_id,p_cafe_id,'journal',party,invoice.id,'إلغاء تطبيق رصيد العميل '||note,auth.uid());
  PERFORM brand_finance_private.invoice_line(p_cafe_id,journal_id,brand_finance_private.account(p_cafe_id,'1100'),amount,0,party,note);
  PERFORM brand_finance_private.invoice_line(p_cafe_id,journal_id,aid,0,amount,party,note);
  SELECT coalesce(max(revision),0)+1 INTO rev FROM public.bf_invoice_payments WHERE source_id=source.id;
  INSERT INTO public.bf_invoice_payments(cafe_id,source_id,invoice_id,revision,payload,status,financial_at,updated_by)
   VALUES(p_cafe_id,source.id,invoice.id,rev,jsonb_build_object('amount',amount,'date',(now() AT TIME ZONE 'Asia/Riyadh')::date,'accountId',null,'status','completed','collectorId',source.created_by,'reference','','details',source.note,'receiptNote','','attachments','[]'::jsonb),'deleted',clock_timestamp(),auth.uid())
   ON CONFLICT(source_id) DO UPDATE SET revision=excluded.revision,status='deleted',financial_at=excluded.financial_at,updated_by=excluded.updated_by,updated_at=clock_timestamp();
  after_record:=brand_finance_private.invoice_payment_record(source,invoice);
  INSERT INTO public.bf_invoice_payment_events(cafe_id,source_id,invoice_id,revision,action,before_state,after_state,correction_id,reason,created_by) VALUES(p_cafe_id,source.id,invoice.id,rev,'delete',before_record,after_record,journal_id,note,auth.uid());
  INSERT INTO public.bf_customer_credit_events(cafe_id,party_id,document_id,invoice_id,application_id,action,amount,delta,created_by) VALUES(p_cafe_id,party,journal_id,invoice.id,application.id,'unapply',amount,amount,auth.uid());
 ELSE
  IF NOT brand_finance_private.invoice_number_valid(p_input->'amount',0.01,1000000000,2) THEN RAISE EXCEPTION 'راجع مبلغ رصيد العميل' USING ERRCODE='22023';END IF;amount:=(p_input->>'amount')::numeric;
  SELECT * INTO account FROM public.bf_accounts a WHERE a.cafe_id=p_cafe_id AND a.id=(p_input->>'accountId')::uuid AND a.active AND a.deleted_at IS NULL AND NOT a.frozen AND NOT a.is_group AND a.kind IN('cash','bank','pos') AND NOT a.is_cashier_drawer;
  IF account.id IS NULL OR EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND account_id=account.id AND status IN('open','handover')) THEN RAISE EXCEPTION 'اختر حساب تحصيل إداريًا خارج الورديات';END IF;
  IF p_action='refund' AND (amount>balance OR amount>brand_finance_private.treasury_balance(p_cafe_id,account.id)) THEN RAISE EXCEPTION 'رصيد العميل أو الحساب لا يكفي لإعادة المبلغ';END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,note,created_by) VALUES(journal_id,p_cafe_id,'journal',party,account.id,note,auth.uid());
  PERFORM brand_finance_private.invoice_line(p_cafe_id,journal_id,account.id,CASE WHEN p_action='receive' THEN amount ELSE 0 END,CASE WHEN p_action='refund' THEN amount ELSE 0 END,party,note);
  PERFORM brand_finance_private.invoice_line(p_cafe_id,journal_id,aid,CASE WHEN p_action='refund' THEN amount ELSE 0 END,CASE WHEN p_action='receive' THEN amount ELSE 0 END,party,note);
  IF p_action='receive' AND account.kind='pos' THEN PERFORM brand_finance_private.terminal_fee_accrue(p_cafe_id,account.id,journal_id,NULL,amount);END IF;
  INSERT INTO public.bf_customer_credit_events(cafe_id,party_id,document_id,action,amount,delta,created_by) VALUES(p_cafe_id,party,journal_id,p_action,amount,CASE WHEN p_action='receive' THEN amount ELSE -amount END,auth.uid());
 END IF;
 answer:=jsonb_build_object('id',journal_id,'balance',brand_finance_private.customer_credit_balance(p_cafe_id,party));
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,request,'customer_credit_'||p_action,p_input,answer,auth.uid());RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_customer_detail(p_cafe_id uuid, p_id uuid, p_tab text DEFAULT 'details'::text, p_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE party public.bf_parties%ROWTYPE; result jsonb; start_row integer;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 IF p_page IS NULL OR p_page NOT BETWEEN 1 AND 400001 OR p_tab IS NULL OR p_tab NOT IN('details','invoices','payments','quotes','messages','balance','timeline') THEN RAISE EXCEPTION 'Invalid customer page' USING ERRCODE='22023'; END IF;
 SELECT * INTO party FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=p_id AND kind='customer';
 IF NOT FOUND THEN RAISE EXCEPTION 'Customer unavailable' USING ERRCODE='42501'; END IF;
 start_row:=(p_page-1)*25;
 WITH invoices AS MATERIALIZED (
  SELECT d AS source,brand_finance_private.document_state(p_cafe_id,d.id) state FROM public.bf_documents d WHERE d.cafe_id=p_cafe_id AND d.party_id=p_id AND d.kind='sale'
 ), payments AS MATERIALIZED (
  SELECT s AS source,i.source AS invoice,coalesce(o.payload->>'date',(s.created_at AT TIME ZONE 'Asia/Riyadh')::date::text) payment_date,(brand_finance_private.payment_document(s)).paid amount
  FROM invoices i JOIN public.bf_documents s ON s.cafe_id=p_cafe_id AND ((s.id=(i.source).id AND s.paid>0) OR (s.reference_id=(i.source).id AND s.kind='settlement' AND s.total>0))
  LEFT JOIN public.bf_invoice_payments o ON o.cafe_id=s.cafe_id AND o.source_id=s.id WHERE coalesce(o.status,'completed')<>'deleted'
 ), quotes AS MATERIALIZED (
  SELECT q AS source FROM public.bf_quotes q WHERE q.cafe_id=p_cafe_id AND q.payload#>>'{document,invoice,partyId}'=p_id::text
 ), messages AS MATERIALIZED (
  SELECT m.id,m.document_id,d.number,m.state,m.provider_status,m.created_at,m.finished_at FROM public.bf_customer_message_jobs m JOIN public.bf_documents d ON d.cafe_id=m.cafe_id AND d.id=m.document_id
  WHERE m.cafe_id=p_cafe_id AND d.party_id=p_id AND (m.state='queued' OR m.provider_status IN('sent','delivered','read'))
 ), balances AS MATERIALIZED (
  SELECT j.id,j.document_id,d.number,d.kind,j.created_at,j.memo,j.debit,j.credit,sum(j.debit-j.credit) OVER(ORDER BY j.created_at,j.id ROWS UNBOUNDED PRECEDING) running_balance
  FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id AND a.kind='receivable' JOIN public.bf_documents d ON d.cafe_id=j.cafe_id AND d.id=j.document_id
  WHERE j.cafe_id=p_cafe_id AND j.party_id=p_id
 ), timeline AS MATERIALIZED (
  SELECT * FROM brand_finance_private.customer_timeline(p_cafe_id,p_id)
 ), counts AS (
  SELECT jsonb_build_object('invoices',(SELECT count(*) FROM invoices),'payments',(SELECT count(*) FROM payments),'quotes',(SELECT count(*) FROM quotes),'messages',(SELECT count(*) FROM messages),'balance',(SELECT count(*) FROM balances),'timeline',(SELECT count(*) FROM timeline)) value
 )
 SELECT jsonb_build_object('customer',to_jsonb(party)-'cafe_id'||jsonb_build_object('balance',coalesce((SELECT sum(debit-credit) FROM balances),0)),
  'tab',p_tab,'page',p_page,'pageSize',25,'total',coalesce((counts.value->>p_tab)::bigint,0),'hasMore',coalesce((counts.value->>p_tab)::bigint,0)>start_row+25,'counts',counts.value,
  'summary',jsonb_build_object('invoiceTotal',coalesce((SELECT sum((source).total) FROM invoices),0),'refundedTotal',coalesce((SELECT sum((state->>'refunded_total')::numeric) FROM invoices),0),
   'outstanding',coalesce((SELECT sum((state->>'outstanding')::numeric) FROM invoices),0),'balance',coalesce((SELECT sum(debit-credit) FROM balances),0),'collected',coalesce((SELECT sum(amount) FROM payments),0),
   'unpaidCount',(SELECT count(*) FROM invoices WHERE (state->>'outstanding')::numeric>0),
   'lastInvoice',(SELECT jsonb_build_object('id',(source).id,'number',(source).number,'date',(source).created_at,'total',(source).total,'outstanding',state->'outstanding') FROM invoices ORDER BY (source).created_at DESC,(source).id DESC LIMIT 1),
   'lastPayment',(SELECT brand_finance_private.invoice_payment_record(source,invoice)||jsonb_build_object('invoiceNumber',(invoice).number) FROM payments ORDER BY payment_date DESC,(source).created_at DESC,(source).id DESC LIMIT 1),
   'lastMessage',(SELECT jsonb_build_object('id',id,'invoiceId',document_id,'invoiceNumber',number,'status',state,'deliveryStatus',provider_status,'createdAt',created_at,'finishedAt',finished_at) FROM messages ORDER BY coalesce(finished_at,created_at) DESC,id DESC LIMIT 1)),
  'invoices',CASE WHEN p_tab='invoices' THEN coalesce((SELECT jsonb_agg(brand_finance_private.invoice_detail_document(p_cafe_id,(source).id) ORDER BY (source).created_at DESC,(source).id DESC) FROM (SELECT * FROM invoices ORDER BY (source).created_at DESC,(source).id DESC OFFSET start_row LIMIT 25) page),'[]'::jsonb) ELSE '[]'::jsonb END,
  'payments',CASE WHEN p_tab='payments' THEN coalesce((SELECT jsonb_agg(brand_finance_private.invoice_payment_record(source,invoice)||jsonb_build_object('invoiceNumber',(invoice).number) ORDER BY payment_date DESC,(source).created_at DESC,(source).id DESC) FROM (SELECT * FROM payments ORDER BY payment_date DESC,(source).created_at DESC,(source).id DESC OFFSET start_row LIMIT 25) page),'[]'::jsonb) ELSE '[]'::jsonb END,
  'quotes',CASE WHEN p_tab='quotes' THEN coalesce((SELECT jsonb_agg(brand_finance_private.quote_record(source) ORDER BY (source).updated_at DESC,(source).id DESC) FROM (SELECT * FROM quotes ORDER BY (source).updated_at DESC,(source).id DESC OFFSET start_row LIMIT 25) page),'[]'::jsonb) ELSE '[]'::jsonb END,
  'messages',CASE WHEN p_tab='messages' THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'invoiceId',document_id,'invoiceNumber',number,'status',state,'deliveryStatus',provider_status,'createdAt',created_at,'finishedAt',finished_at) ORDER BY coalesce(finished_at,created_at) DESC,id DESC) FROM (SELECT * FROM messages ORDER BY coalesce(finished_at,created_at) DESC,id DESC OFFSET start_row LIMIT 25) page),'[]'::jsonb) ELSE '[]'::jsonb END,
  'balance',CASE WHEN p_tab='balance' THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'documentId',document_id,'number',number,'kind',kind,'date',created_at,'memo',memo,'debit',debit,'credit',credit,'runningBalance',running_balance) ORDER BY created_at DESC,id DESC) FROM (SELECT * FROM balances ORDER BY created_at DESC,id DESC OFFSET start_row LIMIT 25) page),'[]'::jsonb) ELSE '[]'::jsonb END,
  'timeline',CASE WHEN p_tab='timeline' THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'kind',kind,'action',action,'date',event_at,'actor',CASE WHEN actor_id IS NULL THEN 'غير مسجل' ELSE brand_finance_private.treasury_actor_name(p_cafe_id,actor_id) END,'documentId',document_id,'quoteId',quote_id) ORDER BY event_at DESC,id DESC) FROM (SELECT * FROM timeline ORDER BY event_at DESC,id DESC OFFSET start_row LIMIT 25) page),'[]'::jsonb) ELSE '[]'::jsonb END
 ) INTO result FROM counts;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_customer_payments(p_cafe_id uuid, p_id uuid DEFAULT NULL::uuid, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;source public.bf_documents%ROWTYPE;invoice public.bf_documents%ROWTYPE;payment jsonb;document jsonb;invoice_document jsonb;archived jsonb;meta jsonb;detail jsonb;
 filter_party uuid;filter_method text;filter_status text;q text;invoice_num text;payment_num text;date_from date;date_to date;ordering text;off integer;lim integer;answer jsonb;cnt bigint;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_id IS NOT NULL THEN
  SELECT * INTO source FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_id AND ((kind='sale' AND paid>0) OR (kind='settlement' AND total>0));
  IF NOT FOUND THEN RETURN NULL;END IF;
  SELECT * INTO invoice FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=CASE WHEN source.kind='sale' THEN source.id ELSE source.reference_id END AND kind='sale';
  IF NOT FOUND THEN RETURN NULL;END IF;
  payment:=brand_finance_private.invoice_payment_record(source,invoice);
  invoice_document:=brand_finance_private.invoice_detail_document(p_cafe_id,invoice.id);
  document:=CASE WHEN source.id=invoice.id THEN invoice_document ELSE brand_finance_private.invoice_detail_document(p_cafe_id,source.id) END;
  SELECT snapshot INTO archived FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND document_id=invoice.id;
  SELECT metadata INTO meta FROM public.bf_invoice_management WHERE cafe_id=p_cafe_id AND document_id=invoice.id;
  meta:=coalesce(meta,'{}');IF NOT(meta ? 'delivery') AND archived->'delivery' IS NOT NULL THEN meta:=meta||jsonb_build_object('delivery',archived->'delivery');END IF;
  detail:=jsonb_build_object('document',invoice_document,'invoice',archived,'metadata',meta,'payments',jsonb_build_array(payment),
   'related',CASE WHEN source.id=invoice.id THEN '[]'::jsonb ELSE jsonb_build_array(document) END,'movements','[]'::jsonb,'journal','[]'::jsonb,'activity','[]'::jsonb,
   'customer',(SELECT jsonb_build_object('id',id,'name',name,'phone',phone,'email',email,'tax_number',tax_number,'details',details) FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=invoice.party_id),
   'warehouse',(SELECT jsonb_build_object('id',id,'name',name) FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id=invoice.warehouse_id),
   'creator',jsonb_build_object('id',invoice.created_by,'name',coalesce((SELECT nullif(name,'') FROM public.bf_staff WHERE cafe_id=p_cafe_id AND user_id=invoice.created_by),(SELECT nullif(full_name,'') FROM public.profiles WHERE id=invoice.created_by),'مستخدم غير مسمى')),
   'paymentCollectors',coalesce((SELECT jsonb_agg(jsonb_build_object('id',u.id,'name',u.name) ORDER BY u.name,u.id) FROM (SELECT c.owner_user_id id,coalesce(nullif(p.full_name,''),'مالك العلامة') name FROM public.cafes c JOIN public.profiles p ON p.id=c.owner_user_id AND p.status='active' WHERE c.id=p_cafe_id UNION SELECT s.user_id,coalesce(nullif(s.name,''),nullif(p.full_name,''),'مستخدم غير مسمى') FROM public.bf_staff s JOIN public.profiles p ON p.id=s.user_id AND p.status='active' WHERE s.cafe_id=p_cafe_id AND s.active AND s.role IN('manager','accountant','cashier') AND s.user_id<>(SELECT owner_user_id FROM public.cafes WHERE id=p_cafe_id)) u),'[]'::jsonb));
  RETURN jsonb_build_object('document',document,'detail',detail,'payment',payment);
 END IF;
 IF jsonb_typeof(p_filters) IS DISTINCT FROM 'object' OR octet_length(p_filters::text)>2500 THEN RAISE EXCEPTION 'Invalid filters';END IF;
 filter_party:=nullif(p_filters->>'partyId','')::uuid;filter_method:=p_filters->>'method';filter_status:=p_filters->>'status';q:=lower(trim(coalesce(p_filters->>'query','')));
 invoice_num:=trim(coalesce(p_filters->>'invoiceNumber',''));payment_num:=trim(coalesce(p_filters->>'paymentNumber',''));ordering:=coalesce(p_filters->>'sort','newest');
 date_from:=nullif(p_filters->>'from','')::date;date_to:=nullif(p_filters->>'to','')::date;off:=coalesce((p_filters->>'offset')::integer,0);lim:=coalesce((p_filters->>'limit')::integer,30);
 IF off NOT BETWEEN 0 AND 100000 OR lim NOT BETWEEN 1 AND 100 OR length(q)>100 OR length(invoice_num)>40 OR payment_num!~'^\d{0,20}$' OR (filter_method IS NOT NULL AND filter_method NOT IN('cash','bank','pos','credit')) OR (filter_status IS NOT NULL AND filter_status NOT IN('completed','pending','deleted')) OR ordering NOT IN('newest','oldest','amount_desc','amount_asc') OR date_from>date_to THEN RAISE EXCEPTION 'راجع خيارات البحث والفترة المحددة';END IF;
 WITH candidates AS NOT MATERIALIZED(
 SELECT s.id,s.created_at,s.number,inv.id invoice_id,inv.number invoice_number,coalesce(ext.display_number,inv.number::text) invoice_display_number,inv.party_id,
 coalesce(p.name,'عميل نقدي') customer_name,s.id=inv.id initial,coalesce(m.status,'completed') status,
 coalesce((m.payload->>'amount')::numeric,CASE WHEN s.kind='sale' THEN s.paid ELSE s.total END) amount,
 coalesce((m.payload->>'date')::date,(s.created_at AT TIME ZONE 'Asia/Riyadh')::date) payment_date,
 coalesce((m.payload->>'accountId')::uuid,s.account_id) account_id,coalesce((m.payload->>'collectorId')::uuid,s.created_by) collector_id,
 CASE WHEN EXISTS(SELECT 1 FROM public.bf_customer_credit_events e WHERE e.cafe_id=s.cafe_id AND e.document_id=s.id AND e.action='apply') THEN 'credit' ELSE a.kind END method,
 CASE WHEN EXISTS(SELECT 1 FROM public.bf_customer_credit_events e WHERE e.cafe_id=s.cafe_id AND e.document_id=s.id AND e.action='apply') THEN 'رصيد العميل' ELSE coalesce(a.name,'غير مسجل') END account_name,
 coalesce(m.payload->>'reference','') reference
 FROM public.bf_documents s JOIN public.bf_documents inv ON inv.cafe_id=s.cafe_id AND inv.kind='sale' AND inv.id=CASE WHEN s.kind='sale' THEN s.id ELSE s.reference_id END
 LEFT JOIN public.bf_invoice_payments m ON m.cafe_id=s.cafe_id AND m.source_id=s.id
 LEFT JOIN public.bf_parties p ON p.cafe_id=inv.cafe_id AND p.id=inv.party_id
 LEFT JOIN public.bf_invoice_extensions ext ON ext.cafe_id=inv.cafe_id AND ext.document_id=inv.id
 LEFT JOIN public.bf_accounts a ON a.cafe_id=s.cafe_id AND a.id=coalesce((m.payload->>'accountId')::uuid,s.account_id)
 WHERE s.cafe_id=p_cafe_id AND ((s.kind='sale' AND s.paid>0) OR (s.kind='settlement' AND s.total>0)) AND (filter_party IS NULL OR inv.party_id=filter_party)
 ),matching AS MATERIALIZED(
 SELECT * FROM candidates c WHERE (CASE WHEN filter_status IS NULL THEN c.status<>'deleted' ELSE c.status=filter_status END)
 AND (filter_method IS NULL OR c.method=filter_method) AND (date_from IS NULL OR c.payment_date>=date_from) AND (date_to IS NULL OR c.payment_date<=date_to)
 AND (invoice_num='' OR lower(c.invoice_display_number)=lower(invoice_num) OR (invoice_num~'^\d+$' AND c.invoice_number::numeric=CASE WHEN invoice_num~'^\d+$' THEN invoice_num::numeric ELSE NULL END))
 AND (payment_num='' OR (NOT c.initial AND c.number::numeric=CASE WHEN payment_num<>'' THEN payment_num::numeric ELSE NULL END))
 AND (q='' OR position(q IN lower(c.customer_name||' '||c.invoice_display_number||' '||c.reference||' '||CASE WHEN c.initial THEN '' ELSE c.number::text END))>0)
 ),page AS MATERIALIZED(
 SELECT *,row_number() OVER(ORDER BY CASE WHEN ordering='amount_desc' THEN amount END DESC,CASE WHEN ordering='amount_asc' THEN amount END ASC,CASE WHEN ordering='oldest' THEN payment_date END ASC,CASE WHEN ordering<>'oldest' THEN payment_date END DESC,created_at DESC,id) ordinal FROM matching
 ORDER BY ordinal LIMIT lim OFFSET off
 ),invoice_states AS MATERIALIZED(SELECT d.id,d.total,brand_finance_private.document_state(p_cafe_id,d.id) state FROM public.bf_documents d JOIN(SELECT DISTINCT invoice_id FROM page) ids ON ids.invoice_id=d.id WHERE d.cafe_id=p_cafe_id)
 SELECT (SELECT count(*) FROM matching),coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'invoiceId',x.invoice_id,'initial',x.initial,'number',CASE WHEN x.initial THEN NULL ELSE x.number END,'invoiceNumber',x.invoice_number,'invoiceDisplayNumber',x.invoice_display_number,
 'invoiceStatus',CASE WHEN coalesce((i.state->>'refunded')::boolean,false) AND (i.state->>'refunded_total')::numeric>0 THEN 'returned' WHEN (i.state->>'outstanding')::numeric<=0 THEN 'paid' WHEN (i.state->>'outstanding')::numeric<greatest(i.total-(i.state->>'refunded_total')::numeric,0) THEN 'partial' ELSE 'unpaid' END,
 'customerId',x.party_id,'customerName',x.customer_name,'amount',x.amount,'effectiveAmount',CASE WHEN x.status='completed' THEN x.amount ELSE 0 END,'date',x.payment_date,'status',x.status,'method',x.method,'accountId',x.account_id,'accountName',x.account_name,'reference',x.reference,
 'collectorName',coalesce((SELECT nullif(name,'') FROM public.bf_staff WHERE cafe_id=p_cafe_id AND user_id=x.collector_id),(SELECT nullif(full_name,'') FROM public.profiles WHERE id=x.collector_id),'مستخدم غير مسمى')) ORDER BY x.ordinal) FROM page x JOIN invoice_states i ON i.id=x.invoice_id),'[]') INTO cnt,answer;
 RETURN jsonb_build_object('items',answer,'total',cnt,'offset',off,'limit',lim);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_customer_sale_prices(p_cafe_id uuid, p_customer_id uuid, p_product_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;
BEGIN
  IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN ('owner','manager','accountant') THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;
  IF p_product_ids IS NULL OR cardinality(p_product_ids) NOT BETWEEN 1 AND 100 OR array_position(p_product_ids,NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid products' USING ERRCODE='22023';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=p_customer_id AND kind='customer') THEN
    RAISE EXCEPTION 'Customer unavailable' USING ERRCODE='42501';
  END IF;
  WITH eligible AS (
    SELECT l.product_id,l.unit_price,d.id,d.created_at,d.number,d.tax_inclusive
    FROM public.bf_documents d JOIN public.bf_document_lines l ON l.cafe_id=d.cafe_id AND l.document_id=d.id
    WHERE d.cafe_id=p_cafe_id AND d.party_id=p_customer_id AND d.kind='sale' AND l.product_id=ANY(p_product_ids)
      -- Fully returned lines and legacy full refunds are not an active sale price.
      AND NOT EXISTS(SELECT 1 FROM public.bf_documents r JOIN public.bf_document_lines rl ON rl.cafe_id=r.cafe_id AND rl.document_id=r.id
        WHERE r.cafe_id=p_cafe_id AND r.reference_id=d.id AND r.kind='refund' AND rl.reference_line_id IS NULL)
      AND l.quantity>coalesce((SELECT sum(rl.quantity) FROM public.bf_document_lines rl JOIN public.bf_documents r ON r.cafe_id=rl.cafe_id AND r.id=rl.document_id
        WHERE rl.cafe_id=p_cafe_id AND rl.reference_line_id=l.id AND r.reference_id=d.id AND r.kind='refund'),0)
  ), latest AS (
    SELECT DISTINCT ON(product_id) product_id,id FROM eligible ORDER BY product_id,created_at DESC,number DESC
  ), prices AS (
    SELECT e.product_id,min(e.unit_price) price,max(e.unit_price) max_price,e.created_at,e.tax_inclusive
    FROM eligible e JOIN latest x ON x.product_id=e.product_id AND x.id=e.id
    GROUP BY e.product_id,e.id,e.created_at,e.tax_inclusive
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object('productId',product_id,'price',price,'maxPrice',max_price,'soldAt',created_at,'taxInclusive',tax_inclusive) ORDER BY product_id),'[]'::jsonb) INTO result FROM prices;
  RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_delete_shipping_option(p_cafe_id uuid, p_id uuid, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE option public.bf_shipping_options%ROWTYPE;
BEGIN
  PERFORM brand_finance_private.shipping_role(p_cafe_id,true);
  IF p_revision IS NULL OR p_revision<1 THEN RAISE EXCEPTION 'Invalid shipping option revision' USING ERRCODE='22023';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60622));
  SELECT * INTO option FROM public.bf_shipping_options WHERE cafe_id=p_cafe_id AND id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'خيار الشحن غير متاح' USING ERRCODE='22023';END IF;
  IF option.deleted_at IS NOT NULL THEN RETURN jsonb_build_object('id',option.id,'revision',option.revision,'deleted',true);END IF;
  IF option.revision<>p_revision THEN RAISE EXCEPTION 'Shipping option conflict' USING ERRCODE='40001';END IF;
  UPDATE public.bf_shipping_options SET deleted_at=clock_timestamp(),updated_at=clock_timestamp(),updated_by=auth.uid(),revision=revision+1 WHERE cafe_id=p_cafe_id AND id=p_id;
  INSERT INTO public.bf_shipping_events(cafe_id,option_id,revision,action,before_value,after_value,created_by) VALUES(p_cafe_id,p_id,p_revision+1,'deleted',brand_finance_private.shipping_option_json(option)-ARRAY['id','revision','createdAt','updatedAt'],NULL,auth.uid());
  RETURN jsonb_build_object('id',option.id,'revision',p_revision+1,'deleted',true);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_gl_document(p_cafe_id uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE doc public.bf_documents;
BEGIN
  PERFORM brand_finance_private.assert_gl_enabled(p_cafe_id);
  IF brand_finance_private.role_for(p_cafe_id) NOT IN('owner','manager','accountant','auditor') THEN
    RAISE EXCEPTION 'لا تملك صلاحية قراءة المستند' USING ERRCODE='42501'; END IF;
  SELECT * INTO doc FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_id;
  IF doc.id IS NULL THEN RAISE EXCEPTION 'المستند غير موجود'; END IF;
  RETURN jsonb_build_object('document',to_jsonb(doc)-'cafe_id',
    'lines',coalesce((SELECT jsonb_agg(to_jsonb(l)-'cafe_id' ORDER BY l.id) FROM public.bf_document_lines l WHERE cafe_id=p_cafe_id AND document_id=p_id),'[]'),
    'journal',coalesce((SELECT jsonb_agg(to_jsonb(j)-'cafe_id'||jsonb_build_object('accountName',a.name,'accountCode',a.code) ORDER BY j.id)
      FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=p_cafe_id AND j.document_id=p_id),'[]'),
    'partyName',(SELECT name FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=doc.party_id),
    'warehouseName',(SELECT name FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id=doc.warehouse_id));
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_gl_execute(p_cafe_id uuid, p_action text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; old public.bf_requests; rec public.bf_gl_drafts; acc public.bf_accounts;
  cfg public.bf_gl_settings; period public.bf_gl_periods; x jsonb; normalized jsonb;
  eid uuid; did uuid; pid uuid; dt date; pend date; yr integer; n bigint; answer jsonb; expected integer;
  before_state jsonb; dr numeric; cr numeric; reason text; group_flag boolean;
BEGIN
  r:=brand_finance_private.role_for(p_cafe_id);
  PERFORM brand_finance_private.assert_gl_enabled(p_cafe_id);
  IF r NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'لا تملك صلاحية تعديل دفتر الأستاذ' USING ERRCODE='42501'; END IF;
  IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000 THEN
    RAISE EXCEPTION 'بيانات الطلب غير صالحة';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
  PERFORM brand_finance_private.seed(p_cafe_id);
  INSERT INTO public.bf_gl_settings(cafe_id) VALUES(p_cafe_id) ON CONFLICT DO NOTHING;
  SELECT * INTO cfg FROM public.bf_gl_settings WHERE cafe_id=p_cafe_id;
  SELECT * INTO old FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
  IF FOUND THEN
    IF old.operation<>'gl:'||p_action OR old.payload<>p_payload OR old.created_by<>auth.uid() THEN
      RAISE EXCEPTION 'معرف الطلب مستخدم ببيانات مختلفة' USING ERRCODE='22023';
    END IF;
    RETURN old.result||jsonb_build_object('duplicate',true);
  END IF;
  eid:=nullif(p_payload->>'id','')::uuid;
  expected:=nullif(p_payload->>'revision','')::integer;
  reason:=btrim(coalesce(p_payload->>'reason',''));
  IF p_action='settings' THEN
    IF r<>'owner' THEN RAISE EXCEPTION 'إعداد الاعتماد للمالك فقط' USING ERRCODE='42501'; END IF;
    IF expected IS DISTINCT FROM cfg.revision THEN RAISE EXCEPTION 'تغير الإعداد حدث الصفحة' USING ERRCODE='40001'; END IF;
    IF length(reason) NOT BETWEEN 5 AND 1000 OR jsonb_typeof(p_payload->'makerChecker') IS DISTINCT FROM 'boolean' THEN
      RAISE EXCEPTION 'حدد سياسة الاعتماد وسبب تعديلها'; END IF;
    before_state:=to_jsonb(cfg);
    UPDATE public.bf_gl_settings SET maker_checker=(p_payload->>'makerChecker')::boolean,revision=revision+1 WHERE cafe_id=p_cafe_id RETURNING * INTO cfg;
    eid:=p_cafe_id; answer:=to_jsonb(cfg)-'cafe_id';
  ELSIF p_action='account_save' THEN
    IF coalesce(p_payload->>'kind','') NOT IN('expense','revenue','equity') THEN
      RAISE EXCEPTION 'أضف حسابات النقد والبنوك وأجهزة الدفع من الخزينة وحسابات الرقابة من وحداتها' USING ERRCODE='23514';
    END IF;
    IF r NOT IN('owner','accountant') THEN RAISE EXCEPTION 'تعديل دليل الحسابات للمالك والمحاسب' USING ERRCODE='42501'; END IF;
    IF eid IS NOT NULL THEN
      SELECT * INTO acc FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=eid FOR UPDATE;
      IF acc.id IS NULL THEN RAISE EXCEPTION 'الحساب غير موجود'; END IF;
      IF expected IS DISTINCT FROM acc.revision THEN RAISE EXCEPTION 'تغير الحساب حدث الصفحة' USING ERRCODE='40001'; END IF;
      before_state:=to_jsonb(acc);
    END IF;
    pid:=nullif(p_payload->>'parentId','')::uuid;
    group_flag:=coalesce((p_payload->>'isGroup')::boolean,false);
    IF length(btrim(coalesce(p_payload->>'name',''))) NOT BETWEEN 1 AND 100
      OR coalesce(p_payload->>'code','') !~ '^[A-Za-z0-9-]{1,30}$'
      OR coalesce(p_payload->>'kind','') NOT IN('cash','bank','pos','employee','receivable','payable','inventory','revenue','expense','equity','vat_input','vat_output','fixed_asset','accumulated_depreciation') THEN
      RAISE EXCEPTION 'راجع اسم الحساب ورمزه ونوعه'; END IF;
    IF pid IS NOT NULL THEN
      IF pid=eid OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=pid AND is_group AND active AND NOT frozen AND kind=p_payload->>'kind') THEN
        RAISE EXCEPTION 'اختر حسابًا أبًا تجميعيًا نشطًا من النوع نفسه'; END IF;
      IF EXISTS(WITH RECURSIVE ancestors AS (
        SELECT id,parent_id FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=pid
        UNION SELECT a.id,a.parent_id FROM public.bf_accounts a JOIN ancestors b ON a.id=b.parent_id WHERE a.cafe_id=p_cafe_id
      ) SELECT 1 FROM ancestors WHERE id=eid) THEN RAISE EXCEPTION 'لا يمكن إنشاء دورة في دليل الحسابات'; END IF;
    END IF;
    IF acc.id IS NOT NULL THEN
      IF acc.code IS DISTINCT FROM p_payload->>'code' OR acc.kind IS DISTINCT FROM p_payload->>'kind' THEN
        RAISE EXCEPTION 'رمز الحساب ونوعه ثابتان بعد إنشائه'; END IF;
      IF group_flag AND EXISTS(SELECT 1 FROM public.bf_journal WHERE cafe_id=p_cafe_id AND account_id=eid) THEN
        RAISE EXCEPTION 'لا يمكن تحويل حساب عليه قيود إلى حساب تجميعي'; END IF;
      IF NOT group_flag AND EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND parent_id=eid) THEN
        RAISE EXCEPTION 'الحساب الأب يجب أن يبقى تجميعيًا'; END IF;
      IF (group_flag OR coalesce((p_payload->>'frozen')::boolean,false) OR NOT coalesce((p_payload->>'active')::boolean,true))
        AND acc.code IN('1000','1010','1020','1030','1100','1200','1300','2000','2100','3000','4000','5000','5100','5200','5300','ERP-WIP','ASSET-COST','ASSET-ACCUM','ASSET-EXPENSE','ASSET-LOSS','ASSET-GAIN','ASSET-REVALUE') THEN
        RAISE EXCEPTION 'لا يمكن إيقاف حساب رقابي تستخدمه العمليات'; END IF;
      UPDATE public.bf_accounts SET name=btrim(p_payload->>'name'),parent_id=pid,is_group=group_flag,
        frozen=coalesce((p_payload->>'frozen')::boolean,false),active=coalesce((p_payload->>'active')::boolean,true),revision=revision+1
        WHERE cafe_id=p_cafe_id AND id=eid RETURNING * INTO acc;
    ELSE
      INSERT INTO public.bf_accounts(cafe_id,name,code,kind,parent_id,is_group)
        VALUES(p_cafe_id,btrim(p_payload->>'name'),p_payload->>'code',p_payload->>'kind',pid,group_flag) RETURNING * INTO acc;
      eid:=acc.id;
    END IF;
    answer:=to_jsonb(acc)-'cafe_id';
  ELSIF p_action IN('period_close','period_reopen') THEN
    IF r<>'owner' THEN RAISE EXCEPTION 'إدارة الفترات للمالك فقط' USING ERRCODE='42501'; END IF;
    dt:=(p_payload->>'from')::date; pend:=(p_payload->>'to')::date;
    IF dt IS NULL OR pend IS NULL OR NOT isfinite(dt) OR NOT isfinite(pend) OR pend<dt OR pend-dt>366
      OR length(reason) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'حدد فترة صحيحة لا تتجاوز عامًا وسبب الإجراء'; END IF;
    SELECT * INTO period FROM public.bf_gl_periods WHERE cafe_id=p_cafe_id AND period_start=dt FOR UPDATE;
    before_state:=to_jsonb(period);
    IF period.cafe_id IS NOT NULL AND (expected IS DISTINCT FROM period.revision OR pend<>period.period_end) THEN
      RAISE EXCEPTION 'تغيرت الفترة حدث الصفحة' USING ERRCODE='40001'; END IF;
    IF p_action='period_close' THEN
      IF pend>=(now() AT TIME ZONE 'Asia/Riyadh')::date THEN
        RAISE EXCEPTION 'اختر نهاية يوم مكتمل قبل اليوم الحالي بتوقيت الرياض';
      END IF;
      IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id
        AND status IN('open','handover') AND opened_at<(pend+1)::timestamp AT TIME ZONE 'Asia/Riyadh') THEN
        RAISE EXCEPTION 'أكمل إقفال الورديات وتسليمها ضمن الفترة قبل إقفال الفترة المالية';
      END IF;
      IF EXISTS(SELECT 1 FROM public.bf_cash_handovers h
        JOIN public.bf_shifts s ON s.cafe_id=h.cafe_id AND s.id=h.shift_id
        WHERE h.cafe_id=p_cafe_id AND s.opened_at<(pend+1)::timestamp AT TIME ZONE 'Asia/Riyadh'
        AND NOT EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts receipt WHERE receipt.cafe_id=h.cafe_id AND receipt.handover_id=h.id)) THEN
        RAISE EXCEPTION 'أكد استلام جميع مبالغ تسليم الصناديق المرتبطة بورديات الفترة أولًا';
      END IF;
      IF period.closed OR EXISTS(SELECT 1 FROM public.bf_gl_periods WHERE cafe_id=p_cafe_id AND closed
        AND period_start<>dt AND daterange(period_start,period_end,'[]') && daterange(dt,pend,'[]')) THEN
        RAISE EXCEPTION 'الفترة مقفلة أو تتداخل مع فترة مقفلة'; END IF;
      IF EXISTS(SELECT 1 FROM public.bf_gl_drafts WHERE cafe_id=p_cafe_id AND document_date BETWEEN dt AND pend AND status IN('submitted','approved')) THEN
        RAISE EXCEPTION 'رحل أو ألغ القيود المعلقة قبل الإقفال'; END IF;
      INSERT INTO public.bf_gl_periods(cafe_id,period_start,period_end) VALUES(p_cafe_id,dt,pend)
        ON CONFLICT(cafe_id,period_start) DO UPDATE SET closed=true,revision=public.bf_gl_periods.revision+1 RETURNING * INTO period;
    ELSE
      IF period.cafe_id IS NULL OR NOT period.closed THEN RAISE EXCEPTION 'الفترة ليست مقفلة'; END IF;
      IF EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe_id AND closed_through>=dt) THEN
        RAISE EXCEPTION 'الفترة مشمولة بإقفال قديم يحتاج مراجعة مستقلة قبل إعادة فتحه'; END IF;
      UPDATE public.bf_gl_periods SET closed=false,revision=revision+1 WHERE cafe_id=p_cafe_id AND period_start=dt RETURNING * INTO period;
    END IF;
    answer:=to_jsonb(period)-'cafe_id';
  ELSE
    IF eid IS NOT NULL THEN
      SELECT * INTO rec FROM public.bf_gl_drafts WHERE cafe_id=p_cafe_id AND id=eid FOR UPDATE;
      IF rec.id IS NULL THEN RAISE EXCEPTION 'القيد غير موجود'; END IF;
      IF expected IS DISTINCT FROM rec.revision THEN RAISE EXCEPTION 'تغير القيد حدث الصفحة قبل المتابعة' USING ERRCODE='40001'; END IF;
      before_state:=to_jsonb(rec);
    ELSIF p_action<>'save' THEN RAISE EXCEPTION 'اختر القيد'; END IF;
    IF p_action='save' THEN
      IF rec.id IS NOT NULL AND rec.status<>'draft' THEN RAISE EXCEPTION 'التعديل متاح للمسودة فقط'; END IF;
      dt:=(p_payload->>'date')::date; PERFORM brand_finance_private.gl_date_open(p_cafe_id,dt);
      IF length(btrim(coalesce(p_payload->>'title',''))) NOT BETWEEN 1 AND 150 OR length(coalesce(p_payload->>'note',''))>2000 THEN
        RAISE EXCEPTION 'اكتب عنوانًا صالحًا للقيد وملاحظة ضمن الحد'; END IF;
      normalized:=brand_finance_private.gl_lines(p_cafe_id,p_payload->'lines');
      IF rec.id IS NULL THEN
        yr:=extract(year FROM dt);
        INSERT INTO public.bf_gl_sequences(cafe_id,kind,period,last_number) VALUES(p_cafe_id,'journal',yr,1)
          ON CONFLICT ON CONSTRAINT bf_gl_sequences_pkey DO UPDATE SET last_number=public.bf_gl_sequences.last_number+1 RETURNING last_number INTO n;
        INSERT INTO public.bf_gl_drafts(cafe_id,number,fiscal_year,title,document_date,note,lines,created_by,last_edited_by)
          VALUES(p_cafe_id,n,yr,btrim(p_payload->>'title'),dt,coalesce(p_payload->>'note',''),normalized,auth.uid(),auth.uid()) RETURNING * INTO rec;
      ELSE
        IF extract(year FROM dt)<>rec.fiscal_year THEN RAISE EXCEPTION 'أنشئ مسودة جديدة عند تغيير سنة الترقيم'; END IF;
        UPDATE public.bf_gl_drafts SET title=btrim(p_payload->>'title'),document_date=dt,note=coalesce(p_payload->>'note',''),
          lines=normalized,last_edited_by=auth.uid(),revision=revision+1,updated_at=now() WHERE id=rec.id RETURNING * INTO rec;
      END IF;
    ELSIF p_action='submit' THEN
      IF rec.status<>'draft' THEN RAISE EXCEPTION 'الإرسال متاح للمسودة فقط'; END IF;
      PERFORM brand_finance_private.gl_lines(p_cafe_id,rec.lines);
      PERFORM brand_finance_private.gl_date_open(p_cafe_id,rec.document_date);
      UPDATE public.bf_gl_drafts SET status='submitted',revision=revision+1,updated_at=now() WHERE id=rec.id RETURNING * INTO rec;
    ELSIF p_action='approve' THEN
      IF rec.status<>'submitted' THEN RAISE EXCEPTION 'أرسل القيد للمراجعة أولًا'; END IF;
      IF cfg.maker_checker AND auth.uid() IN(rec.created_by,rec.last_edited_by) THEN RAISE EXCEPTION 'اعتماد المستند يتطلب مستخدمًا غير منشئه وآخر من عدل مسودته' USING ERRCODE='42501'; END IF;
      PERFORM brand_finance_private.gl_lines(p_cafe_id,rec.lines);
      UPDATE public.bf_gl_drafts SET status='approved',approved_by=auth.uid(),revision=revision+1,updated_at=now() WHERE id=rec.id RETURNING * INTO rec;
    ELSIF p_action='cancel' THEN
      IF rec.status NOT IN('draft','submitted','approved') OR length(reason) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'الإلغاء يحتاج قيدًا غير مرحل وسببًا واضحًا'; END IF;
      UPDATE public.bf_gl_drafts SET status='cancelled',revision=revision+1,updated_at=now() WHERE id=rec.id RETURNING * INTO rec;
    ELSIF p_action IN('post','reverse') THEN
      IF p_action='post' AND rec.status<>'approved' THEN RAISE EXCEPTION 'اعتمد القيد قبل الترحيل'; END IF;
      IF p_action='reverse' AND (rec.status<>'posted' OR length(reason) NOT BETWEEN 5 AND 1000) THEN RAISE EXCEPTION 'العكس يحتاج قيدًا مرحلًا وسببًا واضحًا'; END IF;
      dt:=CASE WHEN p_action='post' THEN rec.document_date ELSE (p_payload->>'date')::date END;
      PERFORM brand_finance_private.gl_date_open(p_cafe_id,dt);
      IF p_action='reverse' AND dt<rec.document_date THEN RAISE EXCEPTION 'تاريخ العكس لا يسبق تاريخ الأصل'; END IF;
      normalized:=brand_finance_private.gl_lines(p_cafe_id,rec.lines);
      IF normalized<>rec.lines THEN RAISE EXCEPTION 'تغيرت بيانات حسابات القيد ألغ القيد وأعد اعتماده'; END IF;
      did:=gen_random_uuid();
      INSERT INTO public.bf_documents(id,cafe_id,kind,note,created_by,created_at,reference_id)
        VALUES(did,p_cafe_id,'journal',left(rec.title||' — '||CASE WHEN p_action='reverse' THEN reason ELSE rec.note END,1000),
          auth.uid(),(dt+time '12:00') AT TIME ZONE 'Asia/Riyadh',CASE WHEN p_action='reverse' THEN rec.document_id ELSE NULL END);
      FOR x IN SELECT value FROM jsonb_array_elements(rec.lines) LOOP
        dr:=(x->>'debit')::numeric; cr:=(x->>'credit')::numeric;
        IF p_action='reverse' THEN dr:=(x->>'credit')::numeric; cr:=(x->>'debit')::numeric; END IF;
        IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND account_id=(x->>'accountId')::uuid AND status='handover') THEN
          RAISE EXCEPTION 'الخزينة قيد التسليم انتظر قبول الاستلام'; END IF;
        INSERT INTO public.bf_journal(cafe_id,document_id,account_id,debit,credit,memo)
          VALUES(p_cafe_id,did,(x->>'accountId')::uuid,dr,cr,coalesce(x->>'memo',''));
      END LOOP;
      IF EXISTS(SELECT 1 FROM public.bf_journal j JOIN public.bf_accounts a ON a.id=j.account_id AND a.cafe_id=j.cafe_id
        WHERE j.cafe_id=p_cafe_id AND a.kind IN('cash','employee') GROUP BY a.id HAVING sum(j.debit-j.credit)<0) THEN
        RAISE EXCEPTION 'رصيد النقدية أو العهدة غير كاف'; END IF;
      UPDATE public.bf_gl_drafts SET status=CASE WHEN p_action='post' THEN 'posted' ELSE 'reversed' END,
        document_id=CASE WHEN p_action='post' THEN did ELSE document_id END,
        reversal_document_id=CASE WHEN p_action='reverse' THEN did ELSE reversal_document_id END,
        revision=revision+1,updated_at=now() WHERE id=rec.id RETURNING * INTO rec;
    ELSE RAISE EXCEPTION 'إجراء دفتر الأستاذ غير معروف'; END IF;
    eid:=rec.id; answer:=to_jsonb(rec)-'cafe_id';
  END IF;
  INSERT INTO public.bf_gl_events(cafe_id,entity_id,action,details,created_by)
    VALUES(p_cafe_id,eid,p_action,jsonb_build_object('before',before_state,'after',answer,'reason',reason,'requestId',p_request_id),auth.uid());
  INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by)
    VALUES(p_cafe_id,p_request_id,'gl:'||p_action,p_payload,answer,auth.uid());
  RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_gl_snapshot(p_cafe_id uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text;
BEGIN
  r:=brand_finance_private.role_for(p_cafe_id);
  PERFORM brand_finance_private.assert_gl_enabled(p_cafe_id);
  IF r NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'لا تملك صلاحية قراءة دفتر الأستاذ' USING ERRCODE='42501'; END IF;
  IF p_offset IS NULL OR p_offset<0 OR p_offset>1000000 THEN RAISE EXCEPTION 'رقم الصفحة غير صالح'; END IF;
  RETURN jsonb_build_object(
    'settings',coalesce((SELECT to_jsonb(s)-'cafe_id'||jsonb_build_object('initialized',true) FROM public.bf_gl_settings s WHERE cafe_id=p_cafe_id),'{"maker_checker":true,"revision":1,"initialized":false}'::jsonb),
    'accounts',coalesce((SELECT jsonb_agg(to_jsonb(a)-'cafe_id' ORDER BY code) FROM public.bf_accounts a WHERE cafe_id=p_cafe_id),'[]'::jsonb),
    'drafts',coalesce((SELECT jsonb_agg(to_jsonb(d)-'cafe_id' ORDER BY created_at DESC,id) FROM
      (SELECT * FROM public.bf_gl_drafts WHERE cafe_id=p_cafe_id ORDER BY created_at DESC,id OFFSET p_offset LIMIT 100) d),'[]'::jsonb),
    'hasMore',EXISTS(SELECT 1 FROM public.bf_gl_drafts WHERE cafe_id=p_cafe_id OFFSET p_offset+100 LIMIT 1),
    'periods',coalesce((SELECT jsonb_agg(to_jsonb(p)-'cafe_id' ORDER BY period_start DESC) FROM public.bf_gl_periods p WHERE cafe_id=p_cafe_id),'[]'::jsonb)
  );
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_history(p_cafe_id uuid, p_kind text, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; rows jsonb; more boolean;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_history',p_kind);
 r:=brand_finance_private.role_for(p_cafe_id);
 IF r='cashier' OR p_offset<0 OR p_offset>10000000 OR p_kind NOT IN('documents','journal','movements') THEN RAISE EXCEPTION 'Finance history access denied' USING ERRCODE='42501'; END IF;
 IF p_kind='documents' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(d)-'cafe_id'-'created_by'||brand_finance_private.document_state(p_cafe_id,d.id)||jsonb_build_object('lines',brand_finance_private.refund_lines(p_cafe_id,d.id,true)) ORDER BY d.created_at DESC,d.id),'[]'::jsonb) INTO rows FROM (SELECT * FROM public.bf_documents WHERE cafe_id=p_cafe_id ORDER BY created_at DESC,id OFFSET p_offset LIMIT 100) d;
  SELECT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=p_cafe_id OFFSET p_offset+100 LIMIT 1) INTO more;
 ELSIF p_kind='journal' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(j)-'cafe_id'-'party_id' ORDER BY j.created_at DESC,j.id),'[]'::jsonb) INTO rows FROM (SELECT * FROM public.bf_journal WHERE cafe_id=p_cafe_id ORDER BY created_at DESC,id OFFSET p_offset LIMIT 100) j;
  SELECT EXISTS(SELECT 1 FROM public.bf_journal WHERE cafe_id=p_cafe_id OFFSET p_offset+100 LIMIT 1) INTO more;
 ELSE
  SELECT coalesce(jsonb_agg(to_jsonb(m)-'cafe_id' ORDER BY m.created_at DESC,m.id),'[]'::jsonb) INTO rows FROM (SELECT * FROM public.bf_movements WHERE cafe_id=p_cafe_id ORDER BY created_at DESC,id OFFSET p_offset LIMIT 100) m;
  SELECT EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=p_cafe_id OFFSET p_offset+100 LIMIT 1) INTO more;
 END IF;
 RETURN jsonb_build_object('rows',rows,'hasMore',more);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_inventory_catalog(p_cafe_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$ BEGIN
 IF brand_finance_private.role_for(p_cafe_id) NOT IN('owner','manager','accountant','warehouse','auditor') THEN RAISE EXCEPTION 'Inventory access denied' USING ERRCODE='42501'; END IF;
 PERFORM brand_finance_private.inventory_catalog_seed(p_cafe_id);
 RETURN jsonb_build_object('items',brand_finance_private.inventory_catalog_items(p_cafe_id),'units',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name) ORDER BY name,id) FROM public.bf_item_units WHERE cafe_id=p_cafe_id),'[]'::jsonb));
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_inventory_unit_save(p_cafe_id uuid, p_name text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE prior public.bf_requests%ROWTYPE; result jsonb; body jsonb:=jsonb_build_object('name',p_name); saved uuid;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 IF brand_finance_private.role_for(p_cafe_id) NOT IN('owner','manager','warehouse') THEN RAISE EXCEPTION 'لا تملك صلاحية إدارة المخزون' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR length(btrim(coalesce(p_name,''))) NOT BETWEEN 1 AND 30 THEN RAISE EXCEPTION 'أدخل اسم وحدة صالحًا'; END IF;
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF prior.operation<>'inventory_unit' OR prior.payload<>body OR prior.created_by<>auth.uid() THEN RAISE EXCEPTION 'Request identifier conflict'; END IF; RETURN prior.result||'{"duplicate":true}'::jsonb; END IF;
 INSERT INTO public.bf_item_units(cafe_id,name) VALUES(p_cafe_id,btrim(p_name)) ON CONFLICT(cafe_id,name) DO UPDATE SET name=excluded.name RETURNING id INTO saved;
 result:=jsonb_build_object('id',saved,'name',btrim(p_name));
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'inventory_unit',body,result,auth.uid());
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_context(p_cafe_id uuid, p_party_id uuid DEFAULT NULL::uuid, p_product_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;menu_ids uuid[];item_ids uuid[];i uuid;v jsonb;cost numeric;known boolean;last_price numeric;f numeric;BEGIN
 IF p_product_ids IS NULL OR cardinality(p_product_ids)>500 OR array_position(p_product_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Invalid product context' USING ERRCODE='22023';END IF;
 SELECT coalesce(array_agg(DISTINCT x),'{}') INTO item_ids FROM unnest(p_product_ids) x WHERE EXISTS(SELECT 1 FROM public.erp_inventory_items WHERE cafe_id=p_cafe_id AND item_id=x);
 SELECT coalesce(array_agg(DISTINCT x),'{}') INTO menu_ids FROM unnest(p_product_ids) x WHERE NOT(x=ANY(item_ids));
 result:=erp_inventory_private.invoice_context_before_sales(p_cafe_id,p_party_id,menu_ids);
 FOREACH i IN ARRAY item_ids LOOP
  v:=erp_inventory_private.sale_item(p_cafe_id,i);f:=(v->>'unitFactor')::numeric;
  SELECT sum(abs(quantity)*average_cost)/nullif(sum(abs(quantity)),0),count(*)>0 AND bool_and(cost_known) AND sum(quantity)>0 INTO cost,known FROM public.bf_stock WHERE cafe_id=p_cafe_id AND item_id=i AND erp_inventory_private.warehouse_allowed(p_cafe_id,warehouse_id,'read');
  SELECT l.unit_price/l.stock_unit_factor*f INTO last_price FROM public.bf_document_lines l JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=l.document_id WHERE l.cafe_id=p_cafe_id AND l.inventory_item_id=i AND d.kind='sale' AND d.party_id=p_party_id AND NOT coalesce((brand_finance_private.document_state(p_cafe_id,d.id)->>'refunded')::boolean,false) ORDER BY d.created_at DESC,d.id DESC,l.id DESC LIMIT 1;
  result:=jsonb_set(result,'{products}',(result->'products')||jsonb_build_array(jsonb_build_object('productId',i,'minimumPrice',CASE WHEN (brand_finance_private.invoice_settings(p_cafe_id)#>>'{advanced,advancedPricing}')::boolean THEN (v->>'minimumPrice')::numeric ELSE 0 END,'averageCost',CASE WHEN known THEN round(cost*f,2) ELSE NULL END,'costKnown',coalesce(known,false),'lastPrice',round(last_price,2),'kind',v->>'kind','vatRate',(v->>'vatRate')::numeric,'taxCategory',v->>'taxCategory','exemptionReason',v->>'exemptionReason')));
 END LOOP;RETURN result;END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_detail(p_cafe_id uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE source public.bf_documents%ROWTYPE; archived jsonb; meta jsonb;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN ('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 SELECT * INTO source FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_id AND kind='sale';
 IF NOT FOUND THEN RAISE EXCEPTION 'Not found' USING ERRCODE='42501'; END IF;
 SELECT snapshot INTO archived FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND document_id=p_id;
 SELECT metadata INTO meta FROM public.bf_invoice_management WHERE cafe_id=p_cafe_id AND document_id=p_id;
 meta:=coalesce(meta,'{}'::jsonb);
 IF NOT(meta ? 'delivery') AND archived->'delivery' IS NOT NULL THEN meta:=meta||jsonb_build_object('delivery',archived->'delivery'); END IF;
 RETURN jsonb_build_object(
 'payments',coalesce((SELECT jsonb_agg(brand_finance_private.invoice_payment_record(payment,source) ORDER BY payment.created_at,payment.id) FROM public.bf_documents payment WHERE payment.cafe_id=p_cafe_id AND ((payment.id=p_id AND payment.paid>0) OR (payment.reference_id=p_id AND payment.kind='settlement' AND payment.total>0))),'[]'::jsonb),
 'paymentCollectors',coalesce((SELECT jsonb_agg(jsonb_build_object('id',u.id,'name',u.name) ORDER BY u.name,u.id) FROM (SELECT c.owner_user_id id,coalesce(nullif(p.full_name,''),'مالك العلامة') name FROM public.cafes c JOIN public.profiles p ON p.id=c.owner_user_id AND p.status='active' WHERE c.id=p_cafe_id UNION SELECT s.user_id,coalesce(nullif(s.name,''),nullif(p.full_name,''),'مستخدم غير مسمى') FROM public.bf_staff s JOIN public.profiles p ON p.id=s.user_id AND p.status='active' WHERE s.cafe_id=p_cafe_id AND s.active AND s.role IN('manager','accountant','cashier') AND s.user_id<>(SELECT owner_user_id FROM public.cafes WHERE id=p_cafe_id)) u),'[]'::jsonb),
 'document',brand_finance_private.invoice_detail_document(p_cafe_id,p_id),
 'customer',(SELECT jsonb_build_object('id',id,'name',name,'phone',phone,'email',email,'tax_number',tax_number,'details',details) FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=source.party_id),
 'warehouse',(SELECT jsonb_build_object('id',id,'name',name) FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id=source.warehouse_id),
 'creator',jsonb_build_object('id',source.created_by,'name',coalesce((SELECT nullif(name,'') FROM public.bf_staff WHERE cafe_id=p_cafe_id AND user_id=source.created_by),(SELECT nullif(full_name,'') FROM public.profiles WHERE id=source.created_by),'مستخدم غير مسمى')),
 'invoice',archived,'metadata',meta,
 'related',coalesce((SELECT jsonb_agg(brand_finance_private.invoice_detail_document(p_cafe_id,d.id) ORDER BY d.created_at,d.id) FROM public.bf_documents d WHERE d.cafe_id=p_cafe_id AND d.reference_id=p_id),'[]'::jsonb),
 'movements',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'itemId',i.id,'sku',i.sku,'unit',i.unit,'warehouseId',w.id,'balance',coalesce((SELECT s.quantity FROM public.bf_stock s WHERE s.cafe_id=m.cafe_id AND s.warehouse_id=m.warehouse_id AND s.item_id=m.item_id),0),'name',i.name,'warehouse',w.name,'quantity',m.quantity,'unit_cost',m.unit_cost,'created_at',m.created_at) ORDER BY m.created_at,m.id) FROM public.bf_movements m JOIN public.bf_items i ON i.cafe_id=m.cafe_id AND i.id=m.item_id JOIN public.bf_warehouses w ON w.cafe_id=m.cafe_id AND w.id=m.warehouse_id WHERE m.cafe_id=p_cafe_id AND m.document_id=p_id),'[]'::jsonb),
 'journal',coalesce((SELECT jsonb_agg(jsonb_build_object('id',j.id,'account',a.name,'debit',j.debit,'credit',j.credit,'memo',j.memo) ORDER BY j.created_at,j.id) FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=p_cafe_id AND j.document_id=p_id),'[]'::jsonb),
 'activity',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'action',a.action,'created_at',a.created_at,'actor',coalesce(nullif(s.name,''),nullif(p.full_name,''),'مستخدم غير مسمى'),'documentId',a.document_id) ORDER BY a.created_at DESC,a.id) FROM (
  SELECT id,action,created_at,created_by,document_id FROM public.bf_invoice_activity WHERE cafe_id=p_cafe_id AND document_id=p_id
  UNION ALL SELECT id,CASE kind WHEN 'sale' THEN 'إنشاء الفاتورة' WHEN 'settlement' THEN 'تسجيل دفعة' WHEN 'refund' THEN 'تسجيل مرتجع' ELSE 'تسجيل مستند مرتبط' END,created_at,created_by,id FROM public.bf_documents WHERE cafe_id=p_cafe_id AND (id=p_id OR reference_id=p_id)
 ) a LEFT JOIN public.bf_staff s ON s.cafe_id=p_cafe_id AND s.user_id=a.created_by LEFT JOIN public.profiles p ON p.id=a.created_by),'[]'::jsonb));
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_drafts(p_cafe_id uuid, p_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; result jsonb;
BEGIN
  r := brand_finance_private.role_for(p_cafe_id);
  IF auth.uid() IS NULL OR coalesce(r,'') NOT IN ('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  IF p_id IS NOT NULL THEN
    SELECT jsonb_build_object('id',id,'revision',revision,'payload',payload) INTO result
      FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=p_id;
    RETURN result;
  END IF;
  SELECT coalesce(jsonb_agg(summary ORDER BY updated_at DESC,id),'[]'::jsonb) INTO result FROM (
    SELECT id,updated_at,jsonb_build_object('id',id,'revision',revision,'updatedAt',updated_at,
      'partyId',payload#>>'{invoice,partyId}','note',left(payload#>>'{invoice,note}',100)) summary
    FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id ORDER BY updated_at DESC,id LIMIT 500
  ) rows;
  RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_extensions(p_cafe_id uuid, p_document_id uuid, p_action text DEFAULT 'read'::text, p_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE source public.bf_documents%ROWTYPE;stored public.bf_invoice_extensions%ROWTYPE;advanced jsonb;status uuid;expected integer;request uuid;prior public.bf_requests%ROWTYPE;archived jsonb;payload jsonb;draft_id uuid:=gen_random_uuid();answer jsonb;amount numeric;rate numeric;reason text;description text;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_action IS NULL OR p_action NOT IN('read','status','debit') OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>5000 THEN RAISE EXCEPTION 'Invalid invoice extension input' USING ERRCODE='22023';END IF;
 IF p_action<>'read' THEN
  IF brand_finance_private.role_for(p_cafe_id) NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 END IF;
 SELECT * INTO source FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_document_id AND kind='sale';
 IF source.id IS NULL THEN RAISE EXCEPTION 'Invoice unavailable' USING ERRCODE='42501';END IF;
 advanced:=brand_finance_private.invoice_settings(p_cafe_id)->'advanced';SELECT * INTO stored FROM public.bf_invoice_extensions WHERE document_id=p_document_id AND cafe_id=p_cafe_id;
 IF p_action='read' THEN RETURN jsonb_build_object('statusId',coalesce(stored.status_id::text,''),'revision',coalesce(stored.revision,0),'sourceId',stored.source_id,
  'profit',CASE WHEN (advanced->>'profitEnabled')::boolean THEN (SELECT jsonb_build_object('revenue',coalesce(sum(net),0),'cost',coalesce(sum(cost),0),'profit',coalesce(sum(net-cost),0),'costKnown',coalesce(bool_and(cost_status='known'),false)) FROM public.bf_document_lines WHERE cafe_id=p_cafe_id AND document_id=p_document_id) ELSE NULL END,
  'debitNotes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.id,'number',d.number,'displayNumber',x.display_number,'total',d.total) ORDER BY d.created_at,d.id) FROM public.bf_invoice_extensions x JOIN public.bf_documents d ON d.cafe_id=x.cafe_id AND d.id=x.document_id WHERE x.cafe_id=p_cafe_id AND x.source_id=p_document_id),'[]'::jsonb));END IF;
 IF p_action='status' THEN
  status:=nullif(p_input->>'statusId','')::uuid;expected:=(p_input->>'revision')::integer;
  IF expected IS NULL OR expected<0 OR (status IS NOT NULL AND (NOT(advanced->>'customStatusesEnabled')::boolean OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(advanced->'statuses') x WHERE x->>'id'=status::text))) THEN RAISE EXCEPTION 'حالة الفاتورة غير متاحة' USING ERRCODE='22023';END IF;
  IF stored.status_id IS NOT DISTINCT FROM status THEN RETURN jsonb_build_object('id',source.id,'revision',coalesce(stored.revision,0));END IF;
  IF expected<>coalesce(stored.revision,0) THEN RAISE EXCEPTION 'Invoice status conflict' USING ERRCODE='40001';END IF;
  INSERT INTO public.bf_invoice_extensions(cafe_id,document_id,display_number,status_id,revision,created_by) VALUES(p_cafe_id,source.id,source.number::text,status,1,auth.uid()) ON CONFLICT(document_id) DO UPDATE SET status_id=excluded.status_id,revision=bf_invoice_extensions.revision+1;
  INSERT INTO public.bf_invoice_extension_events(cafe_id,document_id,action,before_value,after_value,created_by) VALUES(p_cafe_id,source.id,'status',jsonb_build_object('statusId',stored.status_id),jsonb_build_object('statusId',status),auth.uid());
  RETURN jsonb_build_object('id',source.id,'revision',coalesce(stored.revision,0)+1);
 END IF;
 request:=(p_input->>'requestId')::uuid;IF request IS NULL THEN RAISE EXCEPTION 'Invalid debit request' USING ERRCODE='22023';END IF;
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=request;
 IF FOUND THEN IF prior.operation<>'invoice_debit' OR prior.payload<>(p_input||jsonb_build_object('sourceId',p_document_id)) OR prior.created_by<>auth.uid() THEN RAISE EXCEPTION 'Debit request conflict' USING ERRCODE='40001';END IF;RETURN prior.result;END IF;
 SELECT snapshot INTO archived FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND document_id=source.id;
 IF archived IS NULL OR NOT(advanced->>'debitNotesEnabled')::boolean OR stored.source_id IS NOT NULL OR source.party_id IS NULL OR coalesce((brand_finance_private.document_state(p_cafe_id,source.id)->>'refunded')::boolean,false) THEN RAISE EXCEPTION 'الفاتورة غير متاحة لإشعار مدين';END IF;
 IF NOT brand_finance_private.invoice_number_valid(p_input->'amount',0.01,1000000000,2) OR NOT brand_finance_private.invoice_number_valid(p_input->'vatRate',0,15) OR (p_input->>'vatRate')::numeric NOT IN(0,15) THEN RAISE EXCEPTION 'راجع مبلغ الإشعار وضريبته' USING ERRCODE='22023';END IF;
 amount:=(p_input->>'amount')::numeric;rate:=(p_input->>'vatRate')::numeric;reason:=btrim(coalesce(p_input->>'reason',''));description:=btrim(coalesce(p_input->>'description',''));
 IF length(description) NOT BETWEEN 3 AND 500 OR length(reason) NOT BETWEEN 1 AND 250 THEN RAISE EXCEPTION 'أكمل وصف الإشعار المدين وسبب إصداره';END IF;
 payload:=jsonb_build_object('invoice',jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('key',0,'productId','','name',left(description,160),'kind','service','quantity',1,'price',amount,'vatRate',rate,'taxCategory',CASE WHEN rate=15 THEN 'S' ELSE 'Z' END,'exemptionReason',CASE WHEN rate=0 THEN reason ELSE '' END,'description',description)),'warehouseId',source.warehouse_id,'partyId',source.party_id,'accountId','','paymentKind','credit','discountValue',0,'discountKind','amount','taxInclusive',false,'note',description,'currency','SAR','exchangeRate',1,'applyCredit',false),
  'issuer',archived->'seller','supplyDate',(now() AT TIME ZONE 'Asia/Riyadh')::date,'template','standard','deliveryMethod','print','deposit',jsonb_build_object('kind','amount','value',0,'paid',false),'shipping','none','delivery',jsonb_build_object('confirmed',false,'date',''),'attachments','[]'::jsonb,'extraFields','[]'::jsonb);
 PERFORM public.brand_finance_save_invoice_draft(p_cafe_id,draft_id,0,payload);
 answer:=brand_finance_private.issue_company_invoice(p_cafe_id,draft_id,1,amount+round(amount*rate/100,2),source.id,reason);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,request,'invoice_debit',p_input||jsonb_build_object('sourceId',p_document_id),answer,auth.uid());RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_line_note_context(p_cafe_id uuid, p_draft_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE options jsonb; selection public.bf_invoice_line_note_drafts%ROWTYPE; issued_id uuid; selected_lines jsonb;
BEGIN
  options:=public.brand_finance_invoice_line_notes(p_cafe_id,'options');
  IF p_draft_id IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=p_draft_id) THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501';END IF;
    SELECT * INTO selection FROM public.bf_invoice_line_note_drafts WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
    SELECT document_id INTO issued_id FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
    IF issued_id IS NOT NULL THEN
      SELECT coalesce(jsonb_agg(l-'lineIndex' ORDER BY (l->>'key')::numeric),'[]'::jsonb) INTO selected_lines FROM public.bf_invoice_line_notes n CROSS JOIN LATERAL jsonb_array_elements(n.lines) l WHERE n.cafe_id=p_cafe_id AND n.document_id=issued_id;
    END IF;
  END IF;
  RETURN jsonb_build_object('enabled',options->'enabled','notes',options->'notes','settingsRevision',options->'revision','lines',coalesce(selected_lines,selection.lines,'[]'::jsonb),'revision',coalesce(selection.revision,0),'hasSelection',selection.draft_id IS NOT NULL,'issued',issued_id IS NOT NULL);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_line_notes(p_cafe_id uuid, p_action text DEFAULT 'get'::text, p_settings jsonb DEFAULT NULL::jsonb, p_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; current_settings jsonb; current_revision integer; options jsonb;
BEGIN
  role_name:=brand_finance_private.role_for(p_cafe_id);
  IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  IF p_action IS NULL OR p_action NOT IN('get','save','options') THEN RAISE EXCEPTION 'Invalid notes action' USING ERRCODE='22023';END IF;
  IF p_action='save' THEN
    IF role_name<>'owner' THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
    IF p_revision IS NULL OR p_revision<0 THEN RAISE EXCEPTION 'Invalid notes revision' USING ERRCODE='22023';END IF;
    PERFORM brand_finance_private.validate_invoice_line_notes(p_settings);
    PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60621));
  END IF;
  SELECT settings,revision INTO current_settings,current_revision FROM public.bf_invoice_line_note_settings WHERE cafe_id=p_cafe_id;
  current_settings:=coalesce(current_settings,'{"enabled":false,"notes":[]}'::jsonb);current_revision:=coalesce(current_revision,0);
  IF p_action='save' AND current_settings IS DISTINCT FROM p_settings THEN
    IF current_revision<>p_revision THEN RAISE EXCEPTION 'Invoice line notes conflict' USING ERRCODE='40001';END IF;
    INSERT INTO public.bf_invoice_line_note_settings(cafe_id,settings,revision,updated_by) VALUES(p_cafe_id,p_settings,current_revision+1,auth.uid())
      ON CONFLICT(cafe_id) DO UPDATE SET settings=excluded.settings,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=clock_timestamp();
    INSERT INTO public.bf_invoice_line_note_events(cafe_id,revision,before_settings,after_settings,created_by) VALUES(p_cafe_id,current_revision+1,current_settings,p_settings,auth.uid());
    current_settings:=p_settings;current_revision:=current_revision+1;
  END IF;
  IF p_action='options' THEN
    IF (current_settings->>'enabled')::boolean THEN
      SELECT coalesce(jsonb_agg(jsonb_build_object('id',n.value->>'id','text',n.value->>'text') ORDER BY n.ordinality),'[]'::jsonb) INTO options FROM jsonb_array_elements(current_settings->'notes') WITH ORDINALITY n(value,ordinality) WHERE (n.value->>'active')::boolean;
    END IF;
    RETURN jsonb_build_object('enabled',(current_settings->>'enabled')::boolean,'notes',coalesce(options,'[]'::jsonb),'revision',current_revision);
  END IF;
  RETURN jsonb_build_object('settings',current_settings,'revision',current_revision);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_management(p_cafe_id uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; action text:=p_input->>'action'; target uuid; d public.bf_documents%ROWTYPE;
 old_meta jsonb; new_meta jsonb; customer jsonb; value jsonb; changed integer:=0; skipped integer:=0; ids uuid[]; current_delivery boolean;
BEGIN
 r:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR coalesce(r,'') NOT IN ('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>100000 OR action IS NULL OR action NOT IN ('sync','delivery','schedule') OR jsonb_typeof(p_input->'ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_input->'ids') NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Invalid count' USING ERRCODE='22023'; END IF;
 SELECT array_agg(DISTINCT x::uuid ORDER BY x::uuid) INTO ids FROM jsonb_array_elements_text(p_input->'ids') x;
 IF action<>'sync' AND cardinality(ids)<>1 THEN RAISE EXCEPTION 'Invalid count' USING ERRCODE='22023'; END IF;
 FOREACH target IN ARRAY ids LOOP
  SELECT * INTO d FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=target AND kind='sale' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  SELECT metadata INTO old_meta FROM public.bf_invoice_management WHERE cafe_id=p_cafe_id AND document_id=target;
  old_meta:=coalesce(old_meta,'{}'::jsonb); new_meta:=old_meta;
  IF action='sync' THEN
   -- Tax snapshots remain as issued; this refreshes the linked operational customer card.
   SELECT jsonb_build_object('name',name,'phone',phone,'tax_number',tax_number,'details',details) INTO customer FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id=d.party_id AND kind='customer';
   IF customer IS NULL THEN skipped:=skipped+1; CONTINUE; END IF;
   new_meta:=jsonb_set(old_meta,'{customer}',customer);
  ELSIF action='delivery' THEN
   IF jsonb_typeof(p_input->'confirmed') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid delivery' USING ERRCODE='22023'; END IF;
   current_delivery:=coalesce((old_meta#>>'{delivery,confirmed}')::boolean,(SELECT (snapshot#>>'{delivery,confirmed}')::boolean FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND document_id=target),false);
   IF current_delivery=(p_input->>'confirmed')::boolean THEN CONTINUE; END IF;
   new_meta:=jsonb_set(old_meta,'{delivery}',jsonb_build_object('confirmed',(p_input->>'confirmed')::boolean,'date',clock_timestamp()));
  ELSE
   value:=p_input->'schedule';
   IF value IS NULL THEN RAISE EXCEPTION 'Invalid schedule' USING ERRCODE='22023'; END IF;
   IF value<>'null'::jsonb THEN
    IF coalesce((brand_finance_private.document_state(p_cafe_id,target)->>'refunded')::boolean,false) THEN RAISE EXCEPTION 'Invalid schedule for fully refunded invoice' USING ERRCODE='22023'; END IF;
    IF d.party_id IS NULL OR jsonb_typeof(value) IS DISTINCT FROM 'object' OR jsonb_typeof(value->'amount') IS DISTINCT FROM 'number'
     OR (value->>'amount')::numeric<0.01 OR (value->>'amount')::numeric>d.total OR (value->>'amount')::numeric<>round((value->>'amount')::numeric,2) OR ceil(d.total/(value->>'amount')::numeric)>600
     OR coalesce(value->>'frequency','') NOT IN ('weekly','fortnightly','monthly','quarterly','half_yearly','yearly')
     OR coalesce(value->>'start','') !~ '^\d{4}-\d{2}-\d{2}$' OR jsonb_typeof(value->'note') IS DISTINCT FROM 'string' OR length(coalesce(value->>'note',''))>500 THEN RAISE EXCEPTION 'Invalid schedule' USING ERRCODE='22023'; END IF;
    PERFORM (value->>'start')::date;
   END IF;
   new_meta:=jsonb_set(old_meta,'{schedule}',value);
  END IF;
  IF new_meta IS DISTINCT FROM old_meta THEN
   INSERT INTO public.bf_invoice_management(cafe_id,document_id,metadata) VALUES(p_cafe_id,target,new_meta) ON CONFLICT(document_id) DO UPDATE SET metadata=excluded.metadata;
   INSERT INTO public.bf_invoice_activity(cafe_id,document_id,action,created_by) VALUES(p_cafe_id,target,CASE action WHEN 'sync' THEN 'مزامنة بيانات العميل' WHEN 'delivery' THEN CASE WHEN (p_input->>'confirmed')::boolean THEN 'تأكيد التسليم' ELSE 'إلغاء التسليم' END ELSE CASE WHEN value='null'::jsonb THEN 'حذف اتفاقية التقسيط' ELSE 'حفظ اتفاقية التقسيط' END END,auth.uid());
   changed:=changed+1;
  END IF;
 END LOOP;
 RETURN jsonb_build_object('changed',changed,'skipped',skipped);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_order_source(p_cafe_id uuid, p_document_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; source public.bf_invoice_order_sources%ROWTYPE;
BEGIN
  role_name:=brand_finance_private.role_for(p_cafe_id);
  IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_document_id AND kind='sale') THEN RAISE EXCEPTION 'Invoice unavailable' USING ERRCODE='42501';END IF;
  SELECT * INTO source FROM public.bf_invoice_order_sources WHERE cafe_id=p_cafe_id AND document_id=p_document_id;
  RETURN jsonb_build_object('sourceId',source.source_id,'name',source.source_name,'recorded',source.document_id IS NOT NULL);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_order_source_context(p_cafe_id uuid, p_draft_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; config jsonb; config_revision integer; chosen public.bf_invoice_order_source_drafts%ROWTYPE; default_id uuid; issued boolean:=false;
BEGIN
  role_name:=brand_finance_private.role_for(p_cafe_id);
  IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  config:=brand_finance_private.order_source_settings(p_cafe_id);
  SELECT revision INTO config_revision FROM public.bf_order_source_settings WHERE cafe_id=p_cafe_id;
  IF p_draft_id IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=p_draft_id) THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501';END IF;
    SELECT * INTO chosen FROM public.bf_invoice_order_source_drafts WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
    issued:=EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id);
  END IF;
  IF config->>'defaultMode'='specific' THEN default_id:=(config->>'defaultSourceId')::uuid;
  ELSIF config->>'defaultMode'='last' THEN SELECT source_id INTO default_id FROM public.bf_invoice_order_source_last WHERE cafe_id=p_cafe_id AND user_id=auth.uid();END IF;
  IF default_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(config->'sources') s WHERE (s->>'id')::uuid=default_id AND (s->>'active')::boolean) THEN default_id:=NULL;END IF;
  RETURN jsonb_build_object('settings',config,'settingsRevision',coalesce(config_revision,0),'selectedSourceId',chosen.source_id,'selectionRevision',coalesce(chosen.revision,0),'hasSelection',chosen.draft_id IS NOT NULL,'defaultSelectionId',default_id,'issued',issued);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_settings(p_cafe_id uuid, p_action text DEFAULT 'get'::text, p_settings jsonb DEFAULT NULL::jsonb, p_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;stored public.bf_invoice_settings%ROWTYPE;current_settings jsonb;current_revision integer;key text;advanced jsonb;next_number bigint;debit_next bigint;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_action IS NULL OR p_action NOT IN('get','save') THEN RAISE EXCEPTION 'Invalid settings action' USING ERRCODE='22023';END IF;
 IF p_action='save' THEN
  IF role_name<>'owner' AND NOT brand_finance_private.invoice_settings_maintenance(p_cafe_id) THEN RAISE EXCEPTION 'Only the owner can change invoice settings' USING ERRCODE='42501';END IF;
  IF p_revision IS NULL OR p_revision<0 OR jsonb_typeof(p_settings) IS DISTINCT FROM 'object' OR octet_length(p_settings::text)>2000000 THEN RAISE EXCEPTION 'Invalid invoice settings' USING ERRCODE='22023';END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_settings)) NOT IN(9,10) OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_settings) k WHERE k NOT IN('allowLineEditing','previewBeforeSave','priceHints','copyNotesOnConversion','decimalDisplay','allowDeposits','discountMode','allowBelowCost','defaultPaid','advanced')) THEN RAISE EXCEPTION 'Invalid invoice settings keys' USING ERRCODE='22023';END IF;
  FOREACH key IN ARRAY ARRAY['allowLineEditing','previewBeforeSave','copyNotesOnConversion','allowDeposits','allowBelowCost','defaultPaid'] LOOP
   IF jsonb_typeof(p_settings->key) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid invoice setting boolean' USING ERRCODE='22023';END IF;
  END LOOP;
  IF coalesce(p_settings->>'priceHints','') NOT IN('hidden','last') OR coalesce(p_settings->>'decimalDisplay','') NOT IN('always','never','auto') OR coalesce(p_settings->>'discountMode','') NOT IN('both','invoice','line') THEN RAISE EXCEPTION 'Invalid invoice setting option' USING ERRCODE='22023';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 END IF;
 SELECT * INTO stored FROM public.bf_invoice_settings WHERE cafe_id=p_cafe_id;
 current_settings:=coalesce(stored.settings,brand_finance_private.invoice_settings(NULL));
 advanced:=coalesce(current_settings->'advanced',brand_finance_private.invoice_advanced_defaults());
 next_number:=brand_finance_private.invoice_number_next(p_cafe_id,'invoice',advanced->'numbering');debit_next:=brand_finance_private.invoice_number_next(p_cafe_id,'debit',advanced->'debitNumbering');
 advanced:=jsonb_set(jsonb_set(advanced,'{numbering,next}',to_jsonb(next_number)),'{debitNumbering,next}',to_jsonb(debit_next));current_settings:=current_settings||jsonb_build_object('advanced',advanced);current_revision:=coalesce(stored.revision,0);
 IF p_action='save' THEN
  p_settings:=p_settings||jsonb_build_object('advanced',coalesce(p_settings->'advanced',advanced));
  PERFORM brand_finance_private.invoice_advanced_validate(p_cafe_id,p_settings->'advanced');
  IF p_settings IS DISTINCT FROM current_settings THEN
   IF p_revision<>current_revision THEN RAISE EXCEPTION 'Invoice settings conflict' USING ERRCODE='40001';END IF;
   INSERT INTO public.bf_invoice_settings(cafe_id,settings,revision,updated_by) VALUES(p_cafe_id,p_settings,current_revision+1,auth.uid()) ON CONFLICT(cafe_id) DO UPDATE SET settings=excluded.settings,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=clock_timestamp();
   INSERT INTO public.bf_invoice_settings_events(cafe_id,revision,before_settings,after_settings,created_by) VALUES(p_cafe_id,current_revision+1,current_settings,p_settings,auth.uid());current_settings:=p_settings;current_revision:=current_revision+1;
  END IF;
 END IF;
 next_number:=brand_finance_private.invoice_number_next(p_cafe_id,'invoice',current_settings#>'{advanced,numbering}');debit_next:=brand_finance_private.invoice_number_next(p_cafe_id,'debit',current_settings#>'{advanced,debitNumbering}');
 current_settings:=jsonb_set(jsonb_set(current_settings,'{advanced,numbering,next}',to_jsonb(next_number)),'{advanced,debitNumbering,next}',to_jsonb(debit_next));
 RETURN jsonb_build_object('settings',current_settings,'revision',current_revision,'nextNumber',next_number);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_invoice_shipping_charge_context(p_cafe_id uuid, p_draft_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE settings jsonb;settings_revision integer;options jsonb;chosen public.bf_invoice_shipping_drafts%ROWTYPE;issued_id uuid;selected jsonb;
BEGIN
 PERFORM brand_finance_private.shipping_role(p_cafe_id);
 SELECT s.settings,s.revision INTO settings,settings_revision FROM public.bf_shipping_settings s WHERE s.cafe_id=p_cafe_id;
 IF p_draft_id IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=p_draft_id) THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501';END IF;
  SELECT * INTO chosen FROM public.bf_invoice_shipping_drafts WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  SELECT document_id INTO issued_id FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  IF issued_id IS NOT NULL THEN SELECT jsonb_build_object('optionId',snapshot->'optionId','name',snapshot->'name','amount',snapshot->'amount','taxRate',snapshot->'taxRate') INTO selected FROM public.bf_invoice_shipping_charges WHERE cafe_id=p_cafe_id AND document_id=issued_id;ELSE selected:=chosen.selection;END IF;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'name',o.name,'fee',o.fee,'taxRate',o.tax_rate,'revision',o.revision) ORDER BY o.display_order,o.name,o.id),'[]'::jsonb) INTO options FROM public.bf_shipping_options o WHERE o.cafe_id=p_cafe_id AND o.active AND o.deleted_at IS NULL;
 RETURN jsonb_build_object('enabled',coalesce((settings->>'enabled')::boolean,false),'settingsRevision',coalesce(settings_revision,0),'codServiceId',settings->'codServiceId','options',options,'selection',selected,'revision',coalesce(chosen.revision,0),'hasSelection',chosen.draft_id IS NOT NULL,'issued',issued_id IS NOT NULL);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_issue_company_invoice(p_cafe_id uuid, p_draft_id uuid, p_revision integer, p_expected_total numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; config jsonb; selected_id uuid; selected_name text; result jsonb; draft_revision integer;
BEGIN
  role_name:=brand_finance_private.role_for(p_cafe_id);
  IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
  SELECT snapshot INTO result FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  IF FOUND THEN RETURN result;END IF;
  SELECT revision INTO draft_revision FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=p_draft_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501';END IF;
  IF draft_revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'Draft conflict' USING ERRCODE='40001';END IF;
  config:=brand_finance_private.order_source_settings(p_cafe_id);
  SELECT source_id INTO selected_id FROM public.bf_invoice_order_source_drafts WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  IF selected_id IS NULL AND (config->>'required')::boolean THEN RAISE EXCEPTION 'اختر مصدر الطلب قبل إصدار الفاتورة' USING ERRCODE='22023';END IF;
  IF selected_id IS NOT NULL THEN
    SELECT s->>'name' INTO selected_name FROM jsonb_array_elements(config->'sources') s WHERE (s->>'id')::uuid=selected_id AND (s->>'active')::boolean;
    IF selected_name IS NULL THEN RAISE EXCEPTION 'مصدر الطلب غير متاح اختر مصدرًا نشطًا' USING ERRCODE='22023';END IF;
  END IF;
  result:=brand_finance_private.issue_manual_invoice_shipping_actor(auth.uid(),false,p_cafe_id,p_draft_id,p_revision,p_expected_total,NULL,'');
  INSERT INTO public.bf_invoice_order_sources(cafe_id,document_id,source_id,source_name,created_by) VALUES(p_cafe_id,(result->>'id')::uuid,selected_id,selected_name,auth.uid());
  PERFORM brand_finance_private.capture_invoice_line_notes(p_cafe_id,p_draft_id,(result->>'id')::uuid,result->'lines');
  RETURN result;
END $function$

