CREATE OR REPLACE FUNCTION public.brand_finance_journal_activity(p_cafe_id uuid, p_id uuid, p_filters jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE requested_action text;actor uuid;start_date date;end_date date;ordering text;start_row integer;answer jsonb;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant','auditor') OR NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_id) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_filters) IS DISTINCT FROM 'object' OR octet_length(p_filters::text)>2000 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_filters) k WHERE k NOT IN('action','actorId','from','to','sort','offset')) THEN RAISE EXCEPTION 'Invalid activity filters' USING ERRCODE='22023';END IF;
 requested_action:=p_filters->>'action';actor:=nullif(p_filters->>'actorId','')::uuid;ordering:=p_filters->>'sort';start_row:=(p_filters->>'offset')::integer;
 IF requested_action IS NULL OR requested_action NOT IN('all','created','payment','description') OR ordering IS NULL OR ordering NOT IN('newest','oldest') OR start_row IS NULL OR start_row NOT BETWEEN 0 AND 10000000 OR coalesce(p_filters->>'from','') !~ '^(|\d{4}-\d{2}-\d{2})$' OR coalesce(p_filters->>'to','') !~ '^(|\d{4}-\d{2}-\d{2})$' THEN RAISE EXCEPTION 'Invalid activity filters' USING ERRCODE='22023';END IF;
 start_date:=nullif(p_filters->>'from','')::date;end_date:=nullif(p_filters->>'to','')::date;
 IF (start_date IS NOT NULL AND NOT isfinite(start_date)) OR (end_date IS NOT NULL AND NOT isfinite(end_date)) OR start_date>end_date THEN RAISE EXCEPTION 'Invalid activity dates' USING ERRCODE='22023';END IF;
 WITH events AS MATERIALIZED(SELECT * FROM brand_finance_private.journal_activity_rows(p_cafe_id,p_id)),filtered AS MATERIALIZED(
  SELECT * FROM events e WHERE (requested_action='all' OR e.kind=requested_action) AND (actor IS NULL OR e.actor_id=actor) AND (start_date IS NULL OR e.event_at>=(start_date::timestamp AT TIME ZONE 'Asia/Riyadh')) AND (end_date IS NULL OR e.event_at<((end_date+1)::timestamp AT TIME ZONE 'Asia/Riyadh'))
 ),page AS (
  SELECT * FROM filtered ORDER BY CASE WHEN ordering='newest' THEN event_at END DESC,CASE WHEN ordering='oldest' THEN event_at END ASC,CASE WHEN ordering='newest' THEN id END DESC,CASE WHEN ordering='oldest' THEN id END ASC OFFSET start_row LIMIT 25
 ) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'kind',kind,'action',action,'createdAt',event_at,'actorId',actor_id,'actor',brand_finance_private.treasury_actor_name(p_cafe_id,actor_id),'field',field,'lineId',line_id,'before',before_value,'after',after_value,'accountName',account_name,'accountCode',account_code) ORDER BY CASE WHEN ordering='newest' THEN event_at END DESC,CASE WHEN ordering='oldest' THEN event_at END ASC,CASE WHEN ordering='newest' THEN id END DESC,CASE WHEN ordering='oldest' THEN id END ASC) FROM page),'[]'::jsonb),
 'total',(SELECT count(*) FROM filtered),'hasMore',(SELECT count(*)>start_row+25 FROM filtered),'offset',start_row,'pageSize',25,
 'actors',coalesce((SELECT jsonb_agg(jsonb_build_object('id',actor_id,'name',brand_finance_private.treasury_actor_name(p_cafe_id,actor_id)) ORDER BY actor_id) FROM (SELECT DISTINCT actor_id FROM events WHERE actor_id IS NOT NULL) actors),'[]'::jsonb),
 'actionOptions',jsonb_build_array(jsonb_build_object('id','all','label','كل الأنشطة'),jsonb_build_object('id','created','label','إنشاء المستند'),jsonb_build_object('id','payment','label','إجراءات الدفعة'),jsonb_build_object('id','description','label','تعديل الأوصاف'))) INTO answer;
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_journal_detail(p_cafe_id uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;stored public.bf_journal_descriptions%ROWTYPE;source public.bf_documents%ROWTYPE;invoice public.bf_documents%ROWTYPE;draft public.bf_gl_drafts%ROWTYPE;
 actor_role text;editable boolean;copy_mode text:='none';reverse_mode text:='none';copy_reason text:='هذا القيد مرتبط بمصدره ولا ينسخ كقيد يدوي';reverse_reason text:='تعالج آثار هذا القيد من المستند المصدر';
 rows jsonb;manual jsonb;posted_lines jsonb;normalized jsonb;activity jsonb;payment jsonb;state jsonb;
BEGIN
 result:=brand_finance_private.journal_detail_before_descriptions(p_cafe_id,p_id);
 SELECT * INTO source FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_id;
 SELECT * INTO stored FROM public.bf_journal_descriptions WHERE cafe_id=p_cafe_id AND document_id=p_id;
 actor_role:=brand_finance_private.role_for(p_cafe_id);editable:=actor_role IN('owner','manager','accountant');
 SELECT coalesce(jsonb_agg(x.value||jsonb_build_object('memo',coalesce(stored.payload#>>ARRAY['lineMemos',j.id::text],j.memo),'originalMemo',j.memo,'createdAt',j.created_at,'postingDate',(source.created_at AT TIME ZONE 'Asia/Riyadh')::date,'actorId',source.created_by,'actorName',brand_finance_private.treasury_actor_name(p_cafe_id,source.created_by),'documentNumber',source.number,'currency','SAR','localDebit',j.debit,'localCredit',j.credit,'action','posting') ORDER BY x.ordinality),'[]'::jsonb) INTO rows
 FROM jsonb_array_elements(result->'journal') WITH ORDINALITY x(value,ordinality) JOIN public.bf_journal j ON j.cafe_id=p_cafe_id AND j.document_id=p_id AND j.id=(x.value->>'id')::uuid;
 SELECT * INTO draft FROM public.bf_gl_drafts WHERE cafe_id=p_cafe_id AND document_id=p_id;
 IF draft.id IS NOT NULL THEN
  SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('accountId',j.account_id,'code',a.code,'name',a.name,'debit',j.debit,'credit',j.credit,'memo',coalesce(stored.payload#>>ARRAY['lineMemos',j.id::text],j.memo),'projectId',to_jsonb(j)->'project_id','costCenterId',to_jsonb(j)->'cost_center_id')) ORDER BY j.id) INTO posted_lines FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=p_cafe_id AND j.document_id=p_id;
  manual:=to_jsonb(draft)-'cafe_id'||jsonb_build_object('note',coalesce(stored.payload->>'note',source.note),'lines',coalesce(posted_lines,'[]'::jsonb));
  IF NOT brand_finance_private.gl_enabled(p_cafe_id) THEN copy_reason:='دفتر القيود اليدوية غير مفعل لهذه المنشأة';reverse_reason:=copy_reason;
  ELSIF NOT editable THEN copy_reason:='لا تملك صلاحية إنشاء قيد يدوي';reverse_reason:='لا تملك صلاحية عكس القيد اليدوي';
  ELSE
   BEGIN
    normalized:=brand_finance_private.gl_lines(p_cafe_id,posted_lines);
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(posted_lines) WITH ORDINALITY p(value,n) JOIN jsonb_array_elements(normalized) WITH ORDINALITY x(value,n) USING(n) WHERE nullif(p.value->>'projectId','') IS DISTINCT FROM nullif(x.value->>'projectId','') OR nullif(p.value->>'costCenterId','') IS DISTINCT FROM nullif(x.value->>'costCenterId','')) THEN RAISE EXCEPTION 'أبعاد السطر لا يدعمها مسار النسخ الحالي';END IF;
    IF EXISTS((SELECT l->>'accountId',(l->>'debit')::numeric,(l->>'credit')::numeric,nullif(l->>'projectId',''),nullif(l->>'costCenterId','') FROM jsonb_array_elements(draft.lines) l) EXCEPT ALL (SELECT l->>'accountId',(l->>'debit')::numeric,(l->>'credit')::numeric,nullif(l->>'projectId',''),nullif(l->>'costCenterId','') FROM jsonb_array_elements(posted_lines) l)) THEN RAISE EXCEPTION 'أبعاد القيد غير مرتبطة بسطوره المرحلة';END IF;
    copy_mode:='manual';copy_reason:=NULL;
   EXCEPTION WHEN OTHERS THEN copy_reason:='راجع حسابات القيد وأبعاده قبل إنشاء نسخة';END;
   IF draft.status<>'posted' THEN reverse_reason:='لا يمكن عكس قيد سبق عكسه أو لم يرحل';
   ELSE
    BEGIN
     normalized:=brand_finance_private.gl_lines(p_cafe_id,draft.lines);
     IF normalized<>draft.lines THEN RAISE EXCEPTION 'Original manual lines changed';END IF;
     reverse_mode:='manual';reverse_reason:=NULL;
    EXCEPTION WHEN OTHERS THEN reverse_reason:='تغيرت حسابات القيد أو أبعاده راجع دفتر الأستاذ';END;
   END IF;
  END IF;
 ELSIF source.kind='sale' THEN
  IF editable THEN copy_mode:='invoice';copy_reason:=NULL;state:=brand_finance_private.document_state(p_cafe_id,p_id);
   IF NOT coalesce((state->>'refunded')::boolean,false) AND EXISTS(SELECT 1 FROM public.bf_document_lines WHERE cafe_id=p_cafe_id AND document_id=p_id) THEN reverse_mode:='refund';reverse_reason:=NULL;ELSE reverse_reason:='لا توجد كميات متبقية لإرجاعها في الفاتورة';END IF;
  ELSE copy_reason:='لا تملك صلاحية نسخ الفاتورة';reverse_reason:='لا تملك صلاحية طلب مرتجع';END IF;
 ELSIF source.kind='settlement' AND result->>'invoiceId' IS NOT NULL THEN
  SELECT * INTO invoice FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=(result->>'invoiceId')::uuid;
  state:=brand_finance_private.document_state(p_cafe_id,invoice.id);payment:=brand_finance_private.invoice_payment_record(source,invoice);
  IF editable AND (state->>'outstanding')::numeric>0 THEN copy_mode:='payment';copy_reason:=NULL;ELSE copy_reason:='لا يوجد رصيد فاتورة متاح لتسجيل دفعة جديدة';END IF;
  IF editable AND (payment->>'canDelete')::boolean THEN reverse_mode:='payment';reverse_reason:=NULL;ELSE reverse_reason:=coalesce(payment->>'blockedReason','لا يمكن عكس تحصيل هذه الدفعة');END IF;
 END IF;
 activity:=public.brand_finance_journal_activity(p_cafe_id,p_id,jsonb_build_object('action','all','actorId',NULL,'from','','to','','sort','newest','offset',0));
 result:=jsonb_set(result,'{document,note}',to_jsonb(coalesce(stored.payload->>'note',source.note)));
 RETURN result||jsonb_build_object('journal',rows,'metadata',jsonb_build_object('revision',coalesce(stored.revision,0),'canEdit',editable AND (result->>'journalCount')::integer>0,'note',coalesce(stored.payload->>'note',source.note),'originalNote',source.note),
  'manualDraft',manual,'capabilities',jsonb_build_object('canCopy',copy_mode<>'none','canReverse',reverse_mode<>'none','copyMode',copy_mode,'reverseMode',reverse_mode,'copyReason',copy_reason,'reverseReason',reverse_reason),
  'activity',activity->'rows','activityCount',activity->'total','activityTruncated',activity->'hasMore');
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_link_sales_cashier(p_cafe_id uuid, p_phone text, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_name text:=btrim(p_name);v_user auth.users%ROWTYPE;v_staff public.bf_staff%ROWTYPE;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_link_sales_cashier',NULL);
 IF brand_finance_private.role_for(p_cafe_id)<>'owner'
   OR NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe_id AND owner_user_id=auth.uid())
   THEN RAISE EXCEPTION 'Finance owner access required' USING ERRCODE='42501'; END IF;
 IF p_phone IS NULL OR p_phone !~ '^9665[0-9]{8}$' OR v_name IS NULL OR length(v_name) NOT BETWEEN 2 AND 100
   THEN RAISE EXCEPTION 'Invalid sales cashier' USING ERRCODE='22023'; END IF;
 BEGIN
  SELECT * INTO STRICT v_user FROM auth.users WHERE phone IN(p_phone,'+'||p_phone) FOR UPDATE;
 EXCEPTION WHEN no_data_found OR too_many_rows THEN
  RAISE EXCEPTION 'Eligible customer identity required' USING ERRCODE='42501';
 END;
 IF v_user.phone_confirmed_at IS NULL OR v_user.deleted_at IS NOT NULL OR v_user.banned_until>now()
   THEN RAISE EXCEPTION 'Eligible customer identity required' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE id=v_user.id AND status='active' AND role='customer' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Eligible customer identity required' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_staff FROM public.bf_staff WHERE cafe_id=p_cafe_id AND user_id=v_user.id FOR UPDATE;
 IF FOUND THEN
  IF v_staff.role<>'cashier' THEN RAISE EXCEPTION 'Existing finance role cannot be replaced' USING ERRCODE='42501'; END IF;
  IF v_staff.active THEN RETURN jsonb_build_object('id',v_user.id,'changed',false); END IF;
  UPDATE public.bf_staff SET active=true,name=v_name WHERE cafe_id=p_cafe_id AND user_id=v_user.id;
 ELSE
  INSERT INTO public.bf_staff(cafe_id,user_id,name,role,active) VALUES(p_cafe_id,v_user.id,v_name,'cashier',true);
 END IF;
 RETURN jsonb_build_object('id',v_user.id,'changed',true);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_maintenance_cashier(p_cafe_id uuid, p_actor_id uuid, p_maintenance_expires_at timestamp with time zone, p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE session_record record; target auth.users%ROWTYPE; member public.bf_staff%ROWTYPE;
 cashier_name text:=btrim(p_payload->>'name'); cashier_phone text:=p_payload->>'phone'; changed boolean:=true;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_actor_id AND role='platform_admin' AND status='active')
  OR NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe_id AND deleted_at IS NULL AND status IN('active','published'))
  OR NOT platform_access_private.service_enabled(p_cafe_id,'finance')
 THEN RAISE EXCEPTION 'Maintenance administrator required' USING ERRCODE='42501'; END IF;
 SELECT action,new_data INTO session_record FROM public.audit_logs
 WHERE actor_id=p_actor_id AND cafe_id=p_cafe_id AND action IN('maintenance_mode_started','maintenance_mode_ended')
 ORDER BY created_at DESC,id DESC LIMIT 1;
 IF NOT FOUND OR session_record.action<>'maintenance_mode_started'
  OR p_maintenance_expires_at IS NULL OR p_maintenance_expires_at<=clock_timestamp()
  OR (session_record.new_data->>'expires_at')::timestamptz IS DISTINCT FROM p_maintenance_expires_at
 THEN RAISE EXCEPTION 'Active matching maintenance session required' USING ERRCODE='42501'; END IF;
 IF p_operation='authorize' THEN RETURN jsonb_build_object('authorized',true); END IF;
 IF p_operation IS NULL OR p_operation NOT IN('add','link','update')
  OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>2000
  OR cashier_name IS NULL OR length(cashier_name) NOT BETWEEN 2 AND 100
 THEN RAISE EXCEPTION 'Invalid cashier command' USING ERRCODE='22023'; END IF;
 IF p_operation='link' THEN
  IF cashier_phone IS NULL OR cashier_phone !~ '^9665[0-9]{8}$' THEN RAISE EXCEPTION 'Invalid cashier phone' USING ERRCODE='22023'; END IF;
  BEGIN
   SELECT * INTO STRICT target FROM auth.users WHERE phone IN(cashier_phone,'+'||cashier_phone) FOR UPDATE;
  EXCEPTION WHEN no_data_found OR too_many_rows THEN
   RAISE EXCEPTION 'Eligible cashier identity required' USING ERRCODE='42501';
  END;
 ELSE
  SELECT * INTO target FROM auth.users WHERE id=(p_payload->>'userId')::uuid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Eligible cashier identity required' USING ERRCODE='42501'; END IF;
 END IF;
 IF p_operation IN('add','link') THEN
  IF target.phone_confirmed_at IS NULL OR target.deleted_at IS NOT NULL OR target.banned_until>clock_timestamp()
   OR regexp_replace(coalesce(target.phone,''),'^\+','') !~ '^9665[0-9]{8}$'
  THEN RAISE EXCEPTION 'Eligible cashier identity required' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.profiles WHERE id=target.id AND status='active' AND role='customer' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Eligible customer identity required' USING ERRCODE='42501'; END IF;
 END IF;
 IF p_operation='add' THEN
  IF target.raw_app_meta_data->'finance_staff_provisioned' IS DISTINCT FROM 'true'::jsonb
   OR target.raw_app_meta_data->>'finance_cafe_id' IS DISTINCT FROM p_cafe_id::text
   OR EXISTS(SELECT 1 FROM public.bf_staff WHERE user_id=target.id)
  THEN RAISE EXCEPTION 'Trusted unassigned cashier required' USING ERRCODE='42501'; END IF;
  INSERT INTO public.bf_staff(cafe_id,user_id,name,role,active) VALUES(p_cafe_id,target.id,cashier_name,'cashier',true);
 ELSE
  SELECT * INTO member FROM public.bf_staff WHERE cafe_id=p_cafe_id AND user_id=target.id FOR UPDATE;
  IF FOUND AND member.role<>'cashier' THEN RAISE EXCEPTION 'Existing finance role cannot be replaced' USING ERRCODE='42501'; END IF;
  IF p_operation='update' THEN
   IF member.user_id IS NULL OR p_payload->>'role' IS DISTINCT FROM 'cashier' OR jsonb_typeof(p_payload->'active') IS DISTINCT FROM 'boolean'
   THEN RAISE EXCEPTION 'Existing cashier required' USING ERRCODE='42501'; END IF;
   changed:=member.name IS DISTINCT FROM cashier_name OR member.active IS DISTINCT FROM (p_payload->>'active')::boolean;
   UPDATE public.bf_staff SET name=cashier_name,active=(p_payload->>'active')::boolean WHERE cafe_id=p_cafe_id AND user_id=target.id AND role='cashier';
  ELSIF member.user_id IS NOT NULL THEN
   changed:=NOT member.active;
   IF changed THEN UPDATE public.bf_staff SET active=true,name=cashier_name WHERE cafe_id=p_cafe_id AND user_id=target.id AND role='cashier'; END IF;
  ELSE
   INSERT INTO public.bf_staff(cafe_id,user_id,name,role,active) VALUES(p_cafe_id,target.id,cashier_name,'cashier',true);
  END IF;
 END IF;
 IF changed THEN
  INSERT INTO public.audit_logs(actor_id,cafe_id,action,entity_table,entity_id,new_data)
  VALUES(p_actor_id,p_cafe_id,'maintenance_cashier_'||p_operation,'bf_staff',target.id,
   jsonb_build_object('role','cashier','active',CASE WHEN p_operation='update' THEN (p_payload->>'active')::boolean ELSE true END));
 END IF;
 RETURN jsonb_build_object('id',target.id,'role','cashier','changed',changed);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_manage_invoice_payment(p_cafe_id uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE source public.bf_documents%ROWTYPE; invoice public.bf_documents%ROWTYPE; existing public.bf_invoice_payments%ROWTYPE; prior public.bf_requests%ROWTYPE;
 old_value jsonb; new_value jsonb; before_record jsonb; after_record jsonb; requested_action text; state text; request uuid; input_source uuid; input_invoice uuid; old_account uuid; new_account uuid; collector uuid;
 old_paid numeric; new_paid numeric; collected numeric; refund_total numeric; refund_paid numeric; correction uuid; next_revision integer; reason text; guard text; account_row public.bf_accounts%ROWTYPE; amount numeric; financial_changed boolean; payment_date date; result jsonb; event_time timestamptz:=clock_timestamp();
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>30000 OR p_input::text ~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023'; END IF;
 request:=(p_input->>'requestId')::uuid; input_source:=(p_input->>'paymentId')::uuid; input_invoice:=(p_input->>'invoiceId')::uuid; requested_action:=p_input->>'action';
 IF request IS NULL OR input_source IS NULL OR input_invoice IS NULL OR coalesce(requested_action,'') NOT IN('save','delete') OR coalesce((p_input->>'revision')::integer,-1)<0 THEN RAISE EXCEPTION 'Invalid input' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=request;
 IF FOUND THEN
  IF prior.operation<>'invoice_payment' OR prior.payload<>p_input OR prior.created_by<>auth.uid() THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية مختلفة' USING ERRCODE='40001'; END IF;
  RETURN prior.result||jsonb_build_object('duplicate',true);
 END IF;
 SELECT * INTO invoice FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=input_invoice AND kind='sale' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 SELECT * INTO source FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=input_source AND ((id=invoice.id AND kind='sale' AND paid>0) OR (reference_id=invoice.id AND kind='settlement' AND total>0)) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 SELECT * INTO existing FROM public.bf_invoice_payments WHERE cafe_id=p_cafe_id AND source_id=source.id FOR UPDATE;
 IF coalesce(existing.revision,0)<>(p_input->>'revision')::integer THEN RAISE EXCEPTION 'Payment revision conflict' USING ERRCODE='40001'; END IF;
 IF existing.status='deleted' THEN RAISE EXCEPTION 'الدفعة محذوفة ولا يمكن تعديلها'; END IF;
 before_record:=brand_finance_private.invoice_payment_record(source,invoice);
 old_value:=coalesce(existing.payload,jsonb_build_object('amount',CASE WHEN source.kind='sale' THEN source.paid ELSE source.total END,'date',(source.created_at AT TIME ZONE 'Asia/Riyadh')::date,'accountId',source.account_id,'status','completed','collectorId',source.created_by,'reference','','details',CASE WHEN source.kind='sale' THEN '' ELSE source.note END,'receiptNote','','attachments','[]'::jsonb));
 old_paid:=(before_record->>'effectiveAmount')::numeric;old_account:=(old_value->>'accountId')::uuid;
 IF requested_action='delete' THEN
  reason:=btrim(coalesce(p_input->>'reason','')); IF length(reason) NOT BETWEEN 3 AND 500 THEN RAISE EXCEPTION 'أدخل سبب حذف الدفعة'; END IF;
  new_value:=old_value; state:='deleted';new_paid:=0;new_account:=old_account;
 ELSE
  new_value:=p_input->'payload';state:=new_value->>'status';
  IF jsonb_typeof(new_value) IS DISTINCT FROM 'object' OR coalesce(state,'') NOT IN('completed','pending') OR jsonb_typeof(new_value->'amount') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'راجع بيانات الدفعة'; END IF;
  amount:=(new_value->>'amount')::numeric;
  IF amount<0.01 OR amount>1000000000 OR amount<>round(amount,2) OR coalesce(new_value->>'date','') !~ '^\d{4}-\d{2}-\d{2}$'
   OR jsonb_typeof(new_value->'reference') IS DISTINCT FROM 'string' OR length(new_value->>'reference')>160
   OR jsonb_typeof(new_value->'details') IS DISTINCT FROM 'string' OR length(new_value->>'details')>1000
   OR jsonb_typeof(new_value->'receiptNote') IS DISTINCT FROM 'string' OR length(new_value->>'receiptNote')>500
   OR jsonb_typeof(new_value->'attachments') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'راجع مبلغ الدفعة وتاريخها وأطوال الحقول'; END IF;
  payment_date:=(new_value->>'date')::date;
  IF NOT isfinite(payment_date) OR payment_date>(now() AT TIME ZONE 'Asia/Riyadh')::date THEN RAISE EXCEPTION 'اختر تاريخ تحصيل صحيحًا لا يتجاوز اليوم'; END IF;
  new_account:=nullif(new_value->>'accountId','')::uuid;collector:=nullif(new_value->>'collectorId','')::uuid;
  SELECT * INTO account_row FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=new_account AND kind IN('cash','bank','pos');
  IF NOT FOUND THEN RAISE EXCEPTION 'اختر حساب تحصيل تابعًا للعلامة'; END IF;
  IF collector IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=collector AND status='active') OR NOT (EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe_id AND owner_user_id=collector) OR EXISTS(SELECT 1 FROM public.bf_staff WHERE cafe_id=p_cafe_id AND user_id=collector AND active AND role IN('manager','accountant','cashier'))) THEN RAISE EXCEPTION 'اختر محصلًا نشطًا تابعًا للعلامة'; END IF;
  IF jsonb_array_length(new_value->'attachments')>20 OR (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements_text(new_value->'attachments')) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(new_value->'attachments') a WHERE NOT EXISTS(SELECT 1 FROM public.bf_company_invoice_files f WHERE f.cafe_id=p_cafe_id AND f.id=a::uuid AND f.uploaded)) THEN RAISE EXCEPTION 'أحد المرفقات غير جاهز أو لا يتبع العلامة'; END IF;
  new_paid:=CASE WHEN state='completed' THEN amount ELSE 0 END;
 END IF;
 financial_changed:=new_paid<>old_paid OR (new_paid>0 AND new_account IS DISTINCT FROM old_account);
 IF financial_changed THEN
  guard:=brand_finance_private.payment_financial_guard(source,invoice,old_account,coalesce(existing.financial_at,source.created_at));
  IF guard IS NOT NULL THEN RAISE EXCEPTION '%',guard; END IF;
  SELECT * INTO account_row FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=new_account;
  IF NOT FOUND OR NOT account_row.active OR account_row.deleted_at IS NOT NULL OR account_row.frozen OR account_row.is_group THEN RAISE EXCEPTION 'حساب التحصيل الجديد غير نشط أو مجمد'; END IF;
  IF account_row.is_cashier_drawer AND NOT EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND id=coalesce(source.shift_id,invoice.shift_id) AND account_id=new_account AND status='open') THEN RAISE EXCEPTION 'اختر صندوق وردية الفاتورة المفتوحة أو حسابًا إداريًا'; END IF;
  IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND account_id=new_account AND status IN('open','handover') AND (status='handover' OR id IS DISTINCT FROM coalesce(source.shift_id,invoice.shift_id))) THEN RAISE EXCEPTION 'حساب التحصيل الجديد مرتبط بعهدة وردية أخرى'; END IF;
  SELECT (brand_finance_private.payment_document(invoice)).paid+coalesce(sum((brand_finance_private.payment_document(d)).total),0) INTO collected FROM public.bf_documents d WHERE cafe_id=p_cafe_id AND reference_id=invoice.id AND kind='settlement';
  SELECT coalesce(sum(total),0),coalesce(sum(paid),0) INTO refund_total,refund_paid FROM public.bf_documents WHERE cafe_id=p_cafe_id AND reference_id=invoice.id AND kind='refund';
  collected:=collected-old_paid+new_paid;
  IF collected<refund_paid THEN RAISE EXCEPTION 'لا يمكن خفض التحصيل عن المبالغ المعادة للعميل'; END IF;
  IF collected>invoice.total-refund_total+refund_paid THEN RAISE EXCEPTION 'قيمة الدفعة تتجاوز الرصيد المتاح للفاتورة'; END IF;

  PERFORM brand_finance_private.gl_date_open(p_cafe_id,(now() AT TIME ZONE 'Asia/Riyadh')::date);
  correction:=gen_random_uuid();
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,account_id,shift_id,total,reference_id,note,created_by)
   VALUES(correction,p_cafe_id,'journal',invoice.party_id,new_account,coalesce(source.shift_id,invoice.shift_id),abs(new_paid-old_paid),source.id,CASE WHEN requested_action='delete' THEN 'حذف دفعة بتصحيح محاسبي: '||reason ELSE 'تصحيح دفعة الفاتورة رقم '||invoice.number END,auth.uid());
  IF old_account=new_account THEN
   PERFORM brand_finance_private.line(p_cafe_id,correction,new_account,greatest(new_paid-old_paid,0),greatest(old_paid-new_paid,0));
  ELSE
   PERFORM brand_finance_private.line(p_cafe_id,correction,old_account,0,old_paid);
   PERFORM brand_finance_private.line(p_cafe_id,correction,new_account,new_paid,0);
  END IF;
  PERFORM brand_finance_private.line(p_cafe_id,correction,brand_finance_private.account(p_cafe_id,'1100'),greatest(old_paid-new_paid,0),greatest(new_paid-old_paid,0),invoice.party_id);
  IF EXISTS(SELECT 1 FROM public.bf_accounts a WHERE a.cafe_id=p_cafe_id AND a.id IN(old_account,new_account) AND a.kind IN('cash','bank','pos') AND coalesce((SELECT sum(j.debit-j.credit) FROM public.bf_journal j WHERE j.cafe_id=p_cafe_id AND j.account_id=a.id),0)<0) THEN RAISE EXCEPTION 'التصحيح سيجعل رصيد حساب التحصيل سالبًا'; END IF;
  IF account_row.kind='pos' AND (new_paid>old_paid OR (new_paid>0 AND old_account<>new_account)) THEN
   PERFORM brand_finance_private.terminal_monthly_ensure(p_cafe_id);
   PERFORM brand_finance_private.terminal_fee_accrue(p_cafe_id,new_account,correction,NULL,CASE WHEN old_account=new_account THEN new_paid-old_paid ELSE new_paid END);
  END IF;
 END IF;
 next_revision:=coalesce(existing.revision,0)+1;
 INSERT INTO public.bf_invoice_payments(cafe_id,source_id,invoice_id,revision,payload,status,financial_at,updated_by)
  VALUES(p_cafe_id,source.id,invoice.id,next_revision,new_value,state,CASE WHEN financial_changed THEN event_time ELSE coalesce(existing.financial_at,source.created_at) END,auth.uid())
  ON CONFLICT(source_id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload,status=excluded.status,financial_at=excluded.financial_at,updated_by=excluded.updated_by,updated_at=clock_timestamp();
 after_record:=brand_finance_private.invoice_payment_record(source,invoice);
 INSERT INTO public.bf_invoice_payment_events(cafe_id,source_id,invoice_id,revision,action,before_state,after_state,correction_id,reason,created_by)
  VALUES(p_cafe_id,source.id,invoice.id,next_revision,requested_action,before_record,after_record,correction,coalesce(reason,''),auth.uid());
 INSERT INTO public.bf_invoice_activity(cafe_id,document_id,action,created_by) VALUES(p_cafe_id,invoice.id,CASE WHEN requested_action='delete' THEN 'حذف دفعة بتصحيح محاسبي' WHEN financial_changed THEN 'تعديل تحصيل دفعة' ELSE 'تعديل بيانات دفعة' END,auth.uid());
 result:=jsonb_build_object('id',source.id,'revision',next_revision,'duplicate',false);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,request,'invoice_payment',p_input,result,auth.uid());
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_order_sources(p_cafe_id uuid, p_action text DEFAULT 'get'::text, p_settings jsonb DEFAULT NULL::jsonb, p_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; current_settings jsonb; current_revision integer;
BEGIN
  role_name:=brand_finance_private.role_for(p_cafe_id);
  IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  IF p_action IS NULL OR p_action NOT IN('get','save') THEN RAISE EXCEPTION 'Invalid source action' USING ERRCODE='22023';END IF;
  IF p_action='save' THEN
    IF role_name<>'owner' THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
    IF p_revision IS NULL OR p_revision<0 THEN RAISE EXCEPTION 'Invalid revision' USING ERRCODE='22023';END IF;
    PERFORM brand_finance_private.validate_order_source_settings(p_settings);
    PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
  END IF;
  current_settings:=brand_finance_private.order_source_settings(p_cafe_id);
  SELECT revision INTO current_revision FROM public.bf_order_source_settings WHERE cafe_id=p_cafe_id;
  current_revision:=coalesce(current_revision,0);
  IF p_action='save' AND p_settings IS DISTINCT FROM current_settings THEN
    IF p_revision<>current_revision THEN RAISE EXCEPTION 'Order source settings conflict' USING ERRCODE='40001';END IF;
    INSERT INTO public.bf_order_source_settings(cafe_id,settings,revision,updated_by) VALUES(p_cafe_id,p_settings,current_revision+1,auth.uid())
      ON CONFLICT(cafe_id) DO UPDATE SET settings=excluded.settings,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=clock_timestamp();
    INSERT INTO public.bf_order_source_settings_events(cafe_id,revision,before_settings,after_settings,created_by) VALUES(p_cafe_id,current_revision+1,current_settings,p_settings,auth.uid());
    current_settings:=p_settings;current_revision:=current_revision+1;
  END IF;
  RETURN jsonb_build_object('settings',current_settings,'revision',current_revision);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_period_closures(p_cafe_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; rows jsonb; total bigint;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF role_name NOT IN('owner','manager','accountant','auditor') THEN
  RAISE EXCEPTION 'لا تملك صلاحية الاطلاع على سجل إقفال الفترات' USING ERRCODE='42501';
 END IF;
 SELECT count(*) INTO total FROM public.bf_period_closures WHERE cafe_id=p_cafe_id;
 SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.created_at DESC,c.id),'[]'::jsonb) INTO rows
 FROM (SELECT id,previous_closed_through,closed_through,reason,actor_id,created_at,
  brand_finance_private.cash_employee_name(p_cafe_id,actor_id) AS actor_name
  FROM public.bf_period_closures WHERE cafe_id=p_cafe_id ORDER BY created_at DESC,id LIMIT 50) c;
 RETURN jsonb_build_object('rows',rows,'total',total,'hasMore',total>50);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_pos_customer(p_cafe_id uuid, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_phone text;v_card uuid;c public.loyalty_cards;v_enabled boolean;v_rewards jsonb;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_pos_customer',NULL);
 PERFORM brand_finance_private.role_for(p_cafe_id);v_phone:=brand_finance_private.customer_phone(p_phone);
 IF v_phone IS NULL THEN RAISE EXCEPTION 'Customer phone required'; END IF;
 v_enabled:=brand_finance_private.customer_loyalty_enabled(p_cafe_id);v_card:=CASE WHEN v_enabled THEN brand_finance_private.customer_card(p_cafe_id,v_phone) END;
 SELECT * INTO c FROM public.loyalty_cards WHERE id=v_card;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'title',reward_title,'expiresAt',expires_at) ORDER BY issued_at,id),'[]'::jsonb) INTO v_rewards
 FROM public.customer_reward_instances WHERE cafe_id=p_cafe_id AND loyalty_card_id=v_card AND source_type='loyalty' AND status='available' AND (expires_at IS NULL OR expires_at>now());
 RETURN jsonb_build_object('phone',v_phone,'loyaltyEnabled',v_enabled,'pagerEnabled',pager_private.enabled(p_cafe_id),'member',v_card IS NOT NULL,
 'customerName',c.customer_name,'stampsInCycle',coalesce(c.stamps_in_cycle,0),'purchasesRequired',coalesce((SELECT purchases_required FROM public.cafe_loyalty_programs WHERE cafe_id=p_cafe_id AND enabled),0),'rewards',v_rewards);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_pos_pager_page(p_cafe_id uuid, p_page integer DEFAULT 0, p_status text DEFAULT 'active'::text, p_query text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_pos_pager_page',NULL);
 PERFORM brand_finance_private.role_for(p_cafe_id);
 IF NOT pager_private.enabled(p_cafe_id) THEN RAISE EXCEPTION 'Pager service unavailable' USING ERRCODE='42501'; END IF;
 RETURN public.pager_get_page(p_cafe_id,p_page,p_status,p_query);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_prepare_shift_attachment(p_cafe_id uuid, p_shift_id uuid, p_name text, p_mime text, p_size bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.bf_shift_attachments; aid uuid:=gen_random_uuid();
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_prepare_shift_attachment',NULL);
 PERFORM brand_finance_private.role_for(p_cafe_id);
