CREATE OR REPLACE FUNCTION public.brand_finance_receive_shift_cash(p_cafe_id uuid, p_handover_id uuid, p_account_id uuid, p_note text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE h public.bf_cash_handovers%ROWTYPE; role_name text; prior public.bf_requests%ROWTYPE; payload jsonb; result jsonb; doc uuid; n bigint; title text;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_receive_shift_cash',NULL);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));role_name:=brand_finance_private.role_for(p_cafe_id);
 IF role_name NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'استلام العهدة متاح لمالك العلامة أو المحاسب' USING ERRCODE='42501'; END IF;
 p_note:=btrim(coalesce(p_note,''));
 IF p_handover_id IS NULL OR p_account_id IS NULL OR p_request_id IS NULL OR length(p_note)>1000 THEN RAISE EXCEPTION 'بيانات استلام العهدة غير مكتملة'; END IF;
 payload:=jsonb_build_object('handoverId',p_handover_id,'accountId',p_account_id,'note',p_note);
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.operation<>'shift_cash_receive' OR prior.payload<>payload OR prior.created_by<>auth.uid() THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى'; END IF;
  RETURN prior.result||'{"duplicate":true}'::jsonb;
 END IF;
 IF EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe_id AND closed_through>=(now() AT TIME ZONE 'Asia/Riyadh')::date) THEN RAISE EXCEPTION 'الفترة المالية مقفلة'; END IF;
 SELECT * INTO h FROM public.bf_cash_handovers WHERE cafe_id=p_cafe_id AND id=p_handover_id FOR UPDATE;
 IF NOT FOUND OR h.handover_type='next_shift' OR EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts WHERE handover_id=h.id) THEN RAISE EXCEPTION 'سجل التسليم غير متاح للاستلام أو سبق استلامه'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=p_account_id AND kind IN('cash','bank') AND active AND NOT is_cashier_drawer) THEN RAISE EXCEPTION 'اختر خزينة أو حسابا بنكيا نشطا غير صندوق الكاشير'; END IF;
 IF h.amount>0 THEN
  IF coalesce((SELECT sum(debit-credit) FROM public.bf_journal WHERE cafe_id=p_cafe_id AND account_id=brand_finance_private.account(p_cafe_id,'1030') AND party_id=h.party_id),0)<h.amount THEN RAISE EXCEPTION 'رصيد عهدة المستلم لا يكفي لهذه العملية'; END IF;
  doc:=gen_random_uuid();title:=left('استلام نقدية الوردية رقم '||h.shift_number||' المسلمة من '||h.from_name||' إلى عهدة '||h.recipient_name||CASE WHEN p_note='' THEN '' ELSE ' - '||p_note END,1000);
  INSERT INTO public.bf_documents(id,cafe_id,kind,shift_id,account_id,party_id,total,paid,reference_id,note,created_by) VALUES(doc,p_cafe_id,'receipt',h.shift_id,p_account_id,h.party_id,h.amount,h.amount,h.document_id,title,auth.uid()) RETURNING number INTO n;
  PERFORM brand_finance_private.line(p_cafe_id,doc,p_account_id,h.amount,0);
  PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'1030'),0,h.amount,h.party_id);
 END IF;
 INSERT INTO public.bf_cash_handover_receipts(handover_id,cafe_id,received_by,received_by_name,received_counted_cash,account_id,document_id,note) VALUES(h.id,p_cafe_id,auth.uid(),brand_finance_private.cash_employee_name(p_cafe_id,auth.uid()),h.amount,p_account_id,doc,p_note);
 result:=jsonb_build_object('id',h.id,'document_id',doc,'number',n,'amount',h.amount);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'shift_cash_receive',payload,result,auth.uid());
 INSERT INTO public.bf_treasury_audit(cafe_id,actor_id,operation,entity_id,after_data) VALUES(p_cafe_id,auth.uid(),'shift_cash_receive',coalesce(doc,h.id),payload||result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_recurring_invoices(p_cafe_id uuid, p_id uuid DEFAULT NULL::uuid, p_filters jsonb DEFAULT '{}'::jsonb, p_history_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.bf_recurring_invoices%ROWTYPE;role_name text;lim integer;off integer;q text;filter_status text;party uuid;answer jsonb;cnt bigint;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_history_offset IS NULL OR p_history_offset NOT BETWEEN 0 AND 100000 THEN RAISE EXCEPTION 'Invalid page';END IF;
 IF p_id IS NOT NULL THEN SELECT * INTO r FROM public.bf_recurring_invoices WHERE cafe_id=p_cafe_id AND id=p_id AND status<>'deleted';IF NOT FOUND THEN RETURN NULL;END IF;RETURN brand_finance_private.recurring_detail(r,p_history_offset);END IF;
 IF jsonb_typeof(p_filters) IS DISTINCT FROM 'object' OR octet_length(p_filters::text)>2000 THEN RAISE EXCEPTION 'Invalid filters';END IF;
 lim:=coalesce((p_filters->>'limit')::integer,30);off:=coalesce((p_filters->>'offset')::integer,0);q:=lower(trim(coalesce(p_filters->>'query','')));filter_status:=p_filters->>'status';party:=nullif(p_filters->>'partyId','')::uuid;
 IF lim NOT BETWEEN 1 AND 100 OR off NOT BETWEEN 0 AND 100000 OR length(q)>100 OR (filter_status IS NOT NULL AND filter_status NOT IN('active','paused','completed')) THEN RAISE EXCEPTION 'Invalid filters';END IF;
 WITH matches AS MATERIALIZED(SELECT s.id,s.updated_at FROM public.bf_recurring_invoices s JOIN public.bf_parties p ON p.cafe_id=s.cafe_id AND p.id::text=s.payload#>>'{document,invoice,partyId}' WHERE s.cafe_id=p_cafe_id AND s.status<>'deleted' AND (filter_status IS NULL OR s.status=filter_status) AND (party IS NULL OR p.id=party) AND (q='' OR position(q IN lower(s.payload->>'name'||' '||p.name||' '||s.number::text))>0)),page AS(SELECT * FROM matches ORDER BY updated_at DESC,id LIMIT lim OFFSET off)
 SELECT (SELECT count(*) FROM matches),coalesce((SELECT jsonb_agg(brand_finance_private.recurring_summary(s) ORDER BY s.updated_at DESC,s.id) FROM page JOIN public.bf_recurring_invoices s ON s.id=page.id),'[]') INTO cnt,answer;
 RETURN jsonb_build_object('items',answer,'total',cnt,'offset',off,'limit',lim);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_sales_cashier_destinations()
 RETURNS TABLE(id uuid, slug text, name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE candidate record;
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1 FROM auth.users u WHERE u.id=auth.uid() AND u.deleted_at IS NULL
      AND (u.banned_until IS NULL OR u.banned_until<=now())
  ) THEN RAISE EXCEPTION 'Finance authentication required' USING ERRCODE='42501'; END IF;
  FOR candidate IN
    SELECT c.id,c.slug,c.name FROM public.bf_staff s JOIN public.cafes c ON c.id=s.cafe_id
    WHERE s.user_id=auth.uid() AND s.role='cashier' AND s.active
      AND c.deleted_at IS NULL ORDER BY c.slug,c.id
  LOOP
    BEGIN
      -- Reuse live profile, tenant, subscription and role checks at the DB boundary.
      IF brand_finance_private.role_for(candidate.id)='cashier' THEN
        id:=candidate.id;slug:=candidate.slug;name:=candidate.name;
        RETURN NEXT;
      END IF;
    EXCEPTION WHEN insufficient_privilege THEN
      -- A revoked/expired brand cannot hide another valid membership.
      CONTINUE;
    END;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_sales_return_stock(p_cafe_id uuid, p_id uuid, p_revision integer, p_operation text, p_request_id uuid, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;s public.bf_sales_return_stock%ROWTYPE;d public.bf_documents%ROWTYPE;prior public.bf_requests%ROWTYPE;command jsonb;answer jsonb;receipt uuid:=gen_random_uuid();component record;cost numeric:=0;closed_date date;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','warehouse') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_id IS NULL OR p_revision IS NULL OR p_revision<1 OR p_request_id IS NULL OR p_operation IS NULL OR p_operation NOT IN('receive','reject') OR p_note IS NULL OR length(p_note)>500 THEN RAISE EXCEPTION 'Invalid stock request';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 command:=jsonb_build_object('id',p_id,'revision',p_revision,'operation',p_operation,'note',p_note);
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF prior.operation<>'sales_return_stock' OR prior.payload<>command OR prior.created_by<>auth.uid() THEN RAISE EXCEPTION 'Request identity conflict';END IF;RETURN CASE WHEN role_name='warehouse' THEN jsonb_build_object('id',prior.result->'id','stockStatus',prior.result->'stockStatus','stockRevision',prior.result->'stockRevision','stockDocumentId',prior.result->'stockDocumentId') ELSE prior.result END;END IF;
 SELECT * INTO s FROM public.bf_sales_return_stock WHERE cafe_id=p_cafe_id AND return_id=p_id FOR UPDATE;
 IF NOT FOUND OR s.status<>'pending' THEN RAISE EXCEPTION 'الفاتورة ليست بانتظار الاستلام المخزني';END IF;
 IF s.revision<>p_revision THEN RAISE EXCEPTION 'تغير إذن الاستلام' USING ERRCODE='40001';END IF;
 SELECT * INTO STRICT d FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_id AND kind='refund';
 IF p_operation='reject' THEN
  IF length(trim(p_note))=0 THEN RAISE EXCEPTION 'حدد سبب رفض الاستلام';END IF;
  UPDATE public.bf_sales_return_stock SET status='rejected',revision=revision+1 WHERE return_id=p_id;
 ELSE
  SELECT closed_through INTO closed_date FROM public.bf_settings WHERE cafe_id=p_cafe_id;
  IF closed_date IS NOT NULL AND (now() AT TIME ZONE 'Asia/Riyadh')::date<=closed_date THEN RAISE EXCEPTION 'الفترة المحاسبية مقفلة';END IF;
  IF NOT EXISTS(SELECT 1 FROM brand_finance_private.sales_return_components(p_cafe_id,p_id)) THEN RAISE EXCEPTION 'لا توجد أصناف مخزنية لاستلامها';END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,warehouse_id,reference_id,note,created_by) VALUES(receipt,p_cafe_id,'stock_adjust',d.party_id,d.warehouse_id,p_id,'استلام أصناف فاتورة مرتجعة '||d.number,auth.uid());
  UPDATE public.bf_sales_return_stock SET status='received',receipt_document_id=receipt,revision=revision+1 WHERE return_id=p_id;
  FOR component IN SELECT * FROM brand_finance_private.sales_return_components(p_cafe_id,p_id) ORDER BY item_id,warehouse_id,id LOOP
   IF NOT EXISTS(SELECT 1 FROM public.bf_items WHERE cafe_id=p_cafe_id AND id=component.item_id AND active) OR NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id=component.warehouse_id AND active) THEN RAISE EXCEPTION 'الصنف أو مستودع الاستلام غير متاح';END IF;
   cost:=cost+brand_finance_private.stock_move(p_cafe_id,receipt,component.item_id,component.warehouse_id,component.quantity,component.cost/component.quantity);
  END LOOP;
  PERFORM brand_finance_private.invoice_line(p_cafe_id,receipt,brand_finance_private.account(p_cafe_id,'1200'),cost,0,d.party_id,'استلام أصناف فاتورة مرتجعة');
  PERFORM brand_finance_private.invoice_line(p_cafe_id,receipt,brand_finance_private.account(p_cafe_id,'5000'),0,cost,d.party_id,'عكس تكلفة أصناف فاتورة مرتجعة');
 END IF;
 INSERT INTO public.bf_sales_return_stock_events(cafe_id,return_id,operation,note,actor_id,actor_name) VALUES(p_cafe_id,p_id,p_operation,p_note,auth.uid(),brand_finance_private.credit_note_actor(p_cafe_id));
 IF role_name='warehouse' THEN
  SELECT jsonb_build_object('id',return_id,'stockStatus',status,'stockRevision',revision,'stockDocumentId',receipt_document_id) INTO answer FROM public.bf_sales_return_stock WHERE cafe_id=p_cafe_id AND return_id=p_id;
 ELSE answer:=brand_finance_private.sales_return_detail(d);END IF;
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'sales_return_stock',command,answer,auth.uid());
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_sales_returns(p_cafe_id uuid, p_id uuid DEFAULT NULL::uuid, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE d public.bf_documents%ROWTYPE;role_name text;filter_party uuid;filter_stock text;filter_payment text;query_value text;date_from date;date_to date;off integer;lim integer;answer jsonb;total_count bigint;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_id IS NOT NULL THEN SELECT * INTO d FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_id AND kind='refund';IF NOT FOUND THEN RETURN NULL;END IF;RETURN brand_finance_private.sales_return_detail(d);END IF;
 IF jsonb_typeof(p_filters) IS DISTINCT FROM 'object' OR octet_length(p_filters::text)>2000 THEN RAISE EXCEPTION 'Invalid filters';END IF;
 filter_party:=nullif(p_filters->>'partyId','')::uuid;filter_stock:=p_filters->>'stockStatus';filter_payment:=p_filters->>'paymentStatus';query_value:=lower(trim(coalesce(p_filters->>'query','')));
 date_from:=nullif(p_filters->>'from','')::date;date_to:=nullif(p_filters->>'to','')::date;off:=coalesce((p_filters->>'offset')::integer,0);lim:=coalesce((p_filters->>'limit')::integer,30);
 IF off NOT BETWEEN 0 AND 100000 OR lim NOT BETWEEN 1 AND 100 OR length(query_value)>100 OR (filter_stock IS NOT NULL AND filter_stock NOT IN('none','pending','received','rejected')) OR (filter_payment IS NOT NULL AND filter_payment NOT IN('cash','credit','mixed')) THEN RAISE EXCEPTION 'Invalid filters';END IF;
 WITH matching AS MATERIALIZED (
 SELECT r.id,r.created_at FROM public.bf_documents r JOIN public.bf_documents src ON src.cafe_id=r.cafe_id AND src.id=r.reference_id AND src.kind='sale'
 LEFT JOIN public.bf_parties p ON p.cafe_id=r.cafe_id AND p.id=r.party_id
 LEFT JOIN public.bf_sales_return_stock s ON s.cafe_id=r.cafe_id AND s.return_id=r.id
 WHERE r.cafe_id=p_cafe_id AND r.kind='refund' AND (filter_party IS NULL OR r.party_id=filter_party)
 AND (date_from IS NULL OR r.created_at>=(date_from::timestamp AT TIME ZONE 'Asia/Riyadh')) AND (date_to IS NULL OR r.created_at<((date_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh'))
 AND (filter_payment IS NULL OR CASE WHEN r.paid=0 THEN 'credit' WHEN r.paid=r.total THEN 'cash' ELSE 'mixed' END=filter_payment)
 AND (filter_stock IS NULL OR coalesce(s.status,CASE WHEN EXISTS(SELECT 1 FROM public.bf_movements m WHERE m.cafe_id=r.cafe_id AND m.document_id=r.id AND m.quantity>0) THEN 'received' ELSE 'none' END)=filter_stock)
 AND (query_value='' OR position(query_value in lower(coalesce(p.name,'عميل نقدي')||' '||r.number::text||' '||src.number::text))>0)
 ),page AS (SELECT * FROM matching ORDER BY created_at DESC,id LIMIT lim OFFSET off)
 SELECT (SELECT count(*) FROM matching),coalesce((SELECT jsonb_agg(brand_finance_private.sales_return_summary(doc) ORDER BY doc.created_at DESC,doc.id) FROM page JOIN public.bf_documents doc ON doc.cafe_id=p_cafe_id AND doc.id=page.id),'[]') INTO total_count,answer;
 RETURN jsonb_build_object('items',answer,'total',total_count,'offset',off,'limit',lim);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_save_credit_note(p_cafe_id uuid, p_id uuid, p_revision integer, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE n public.bf_credit_notes%ROWTYPE;v jsonb;operation text;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_id IS NULL OR p_revision IS NULL OR p_revision<0 THEN RAISE EXCEPTION 'Invalid identity';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 v:=brand_finance_private.credit_note_validate(p_cafe_id,p_payload,false);
 SELECT * INTO n FROM public.bf_credit_notes WHERE id=p_id FOR UPDATE;
 IF FOUND THEN
  IF n.cafe_id<>p_cafe_id THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  IF n.status<>'draft' THEN RAISE EXCEPTION 'الإشعار الصادر ثابت ولا يمكن تعديل أثره المالي';END IF;
  IF n.payload=p_payload THEN RETURN brand_finance_private.credit_note_record(n);END IF;
  IF n.revision<>p_revision THEN RAISE EXCEPTION 'تغير الإشعار افتح النسخة المحفوظة' USING ERRCODE='40001';END IF;
  UPDATE public.bf_credit_notes SET payload=p_payload,revision=revision+1,updated_at=clock_timestamp(),party_id=nullif(p_payload->>'partyId','')::uuid,warehouse_id=nullif(p_payload->>'warehouseId','')::uuid,source_invoice_id=(p_payload->>'sourceInvoiceId')::uuid,source_number=(v->>'sourceNumber')::bigint,customer_name=v->>'customerName',warehouse_name=v->>'warehouseName',salesperson_name=v->>'salespersonName',lines=v->'lines',subtotal=(v->>'subtotal')::numeric,discount=(v->>'discount')::numeric,tax=(v->>'tax')::numeric,total=(v->>'total')::numeric WHERE id=p_id RETURNING * INTO n;
  operation:='edit';
 ELSE
  IF p_revision<>0 THEN RAISE EXCEPTION 'تغير الإشعار' USING ERRCODE='40001';END IF;
  INSERT INTO public.bf_credit_notes(id,cafe_id,payload,party_id,warehouse_id,source_invoice_id,source_number,customer_name,warehouse_name,salesperson_name,created_by_name,lines,subtotal,discount,tax,total,created_by) VALUES(p_id,p_cafe_id,p_payload,nullif(p_payload->>'partyId','')::uuid,nullif(p_payload->>'warehouseId','')::uuid,(p_payload->>'sourceInvoiceId')::uuid,(v->>'sourceNumber')::bigint,v->>'customerName',v->>'warehouseName',v->>'salespersonName',brand_finance_private.credit_note_actor(p_cafe_id),v->'lines',(v->>'subtotal')::numeric,(v->>'discount')::numeric,(v->>'tax')::numeric,(v->>'total')::numeric,auth.uid()) RETURNING * INTO n;
  operation:='create';
 END IF;
 INSERT INTO public.bf_credit_note_events(cafe_id,note_id,action,actor_id,actor_name) VALUES(p_cafe_id,p_id,operation,auth.uid(),brand_finance_private.credit_note_actor(p_cafe_id));
 RETURN brand_finance_private.credit_note_record(n);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_save_customer(p_cafe_id uuid, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb; r text; detail jsonb; field record; customer_id uuid; contacts jsonb; contact jsonb; contact_field record;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_save_customer',NULL);
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
  r := brand_finance_private.role_for(p_cafe_id);
  IF r NOT IN ('owner','manager','accountant') THEN RAISE EXCEPTION 'Finance manager required' USING ERRCODE='42501'; END IF;
  IF p_payload->>'kind' IS DISTINCT FROM 'customer' THEN RAISE EXCEPTION 'Customer required'; END IF;
  detail := coalesce(p_payload->'details','{}'::jsonb);
  IF jsonb_typeof(detail) <> 'object' OR octet_length(detail::text) > 16000 THEN RAISE EXCEPTION 'Invalid customer details'; END IF;
  FOR field IN SELECT key,value FROM jsonb_each(detail) LOOP
    IF field.key NOT IN ('legalName','taxRegistration','country','region','city','district','street','buildingNumber','additionalNumber','postalCode','unitNumber','shortAddress','addressNotes','governmentIdType','governmentId','commercialRegistration','unifiedNumber','contactName','notes','customerType','firstName','lastName','telephone','governmentEntity','shippingEnabled','shippingName','shippingBuildingNumber','shippingStreet','shippingAdditionalNumber','shippingDistrict','shippingCity','shippingPostalCode','shippingShortAddress','shippingCountry','invoiceMethod','currency','classification','language','contacts')
      OR jsonb_typeof(field.value) <> 'string' OR length(field.value #>> '{}') > (CASE WHEN field.key IN ('notes','addressNotes') THEN 2000 WHEN field.key='contacts' THEN 14000 ELSE 250 END)
    THEN RAISE EXCEPTION 'Invalid customer detail field'; END IF;
  END LOOP;
  IF detail ? 'contacts' THEN
    contacts := (detail->>'contacts')::jsonb;
    IF jsonb_typeof(contacts) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid contacts'; END IF;
    IF jsonb_array_length(contacts)>10 THEN RAISE EXCEPTION 'Too many contacts'; END IF;
    FOR contact IN SELECT value FROM jsonb_array_elements(contacts) LOOP
      IF jsonb_typeof(contact) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid contact'; END IF;
      FOR contact_field IN SELECT key,value FROM jsonb_each(contact) LOOP
        IF contact_field.key NOT IN ('firstName','lastName','email','telephone','phone') OR jsonb_typeof(contact_field.value)<>'string' OR length(contact_field.value #>> '{}')>250 THEN RAISE EXCEPTION 'Invalid contact field'; END IF;
      END LOOP;
    END LOOP;
  END IF;
  IF (detail ? 'customerType' AND detail->>'customerType' NOT IN ('individual','business'))
    OR (detail ? 'invoiceMethod' AND detail->>'invoiceMethod' NOT IN ('print','email','whatsapp'))
    OR (detail ? 'language' AND detail->>'language' NOT IN ('ar','en'))
    OR (detail ? 'currency' AND detail->>'currency' NOT IN ('SAR','AED','USD','EUR','GBP','KWD','BHD','QAR','OMR','EGP'))
    OR (detail ? 'shippingEnabled' AND detail->>'shippingEnabled' NOT IN ('true','false'))
    OR (detail ? 'governmentEntity' AND detail->>'governmentEntity' NOT IN ('true','false'))
  THEN RAISE EXCEPTION 'Invalid customer preference'; END IF;
  customer_id := nullif(p_payload->>'id','')::uuid;
  IF EXISTS (SELECT 1 FROM public.bf_parties WHERE id=customer_id AND (cafe_id<>p_cafe_id OR kind<>'customer')) THEN RAISE EXCEPTION 'Invalid customer' USING ERRCODE='42501'; END IF;
  result := public.brand_finance_execute(p_cafe_id,'party',p_payload,p_request_id);
  -- A replay must not overwrite details changed by a later successful request.
  IF coalesce((result->>'duplicate')::boolean,false) THEN RETURN result; END IF;
  UPDATE public.bf_parties SET details=detail || CASE WHEN details ? 'attachments' THEN jsonb_build_object('attachments',details->'attachments') ELSE '{}'::jsonb END WHERE id=(result->>'id')::uuid AND cafe_id=p_cafe_id AND kind='customer';
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer not saved'; END IF;
  RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_save_invoice_draft(p_cafe_id uuid, p_id uuid, p_revision integer, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; existing public.bf_invoice_drafts%ROWTYPE; next_revision integer;
BEGIN
  r := brand_finance_private.role_for(p_cafe_id);
  IF auth.uid() IS NULL OR coalesce(r,'') NOT IN ('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  IF p_id IS NULL OR p_revision IS NULL OR p_revision < 0 OR p_payload IS NULL
    OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000
    OR jsonb_typeof(p_payload->'invoice') IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_payload#>'{invoice,lines}') IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'Invalid draft' USING ERRCODE='22023'; END IF;
  IF jsonb_array_length(p_payload#>'{invoice,lines}') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid lines' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60413));
  SELECT * INTO existing FROM public.bf_invoice_drafts WHERE id=p_id FOR UPDATE;
  IF FOUND THEN
    IF existing.cafe_id<>p_cafe_id THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
    -- Identical retries after an uncertain network response must not create another draft
    IF existing.payload=p_payload THEN RETURN jsonb_build_object('id',p_id,'revision',existing.revision); END IF;
    IF existing.revision<>p_revision THEN RAISE EXCEPTION 'Draft conflict' USING ERRCODE='40001'; END IF;
    UPDATE public.bf_invoice_drafts SET payload=p_payload,revision=revision+1,updated_by=auth.uid(),updated_at=clock_timestamp()
      WHERE id=p_id RETURNING revision INTO next_revision;
  ELSE
    IF p_revision<>0 THEN RAISE EXCEPTION 'Draft conflict' USING ERRCODE='40001'; END IF;
    IF (SELECT count(*) FROM public.bf_invoice_drafts d WHERE d.cafe_id=p_cafe_id AND NOT EXISTS(SELECT 1 FROM public.bf_company_invoices i WHERE i.cafe_id=d.cafe_id AND i.draft_id=d.id))>=500 THEN RAISE EXCEPTION 'Draft limit reached'; END IF;
    INSERT INTO public.bf_invoice_drafts(id,cafe_id,payload,created_by,updated_by) VALUES(p_id,p_cafe_id,p_payload,auth.uid(),auth.uid());
    next_revision:=1;
  END IF;
  RETURN jsonb_build_object('id',p_id,'revision',next_revision);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_save_journal_descriptions(p_cafe_id uuid, p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE source public.bf_documents%ROWTYPE; stored public.bf_journal_descriptions%ROWTYPE; prior public.bf_requests%ROWTYPE;
 target uuid;request uuid;expected integer;revision integer;before_note text;new_note text;before_memo text;entry jsonb;line public.bf_journal%ROWTYPE;
 memos jsonb;changes integer:=0;answer jsonb;event_time timestamptz:=clock_timestamp();
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>2100000 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_input) k WHERE k NOT IN('id','revision','requestId','note','lineMemos'))
  OR jsonb_typeof(p_input->'revision') IS DISTINCT FROM 'number' OR jsonb_typeof(p_input->'note') IS DISTINCT FROM 'string' OR length(p_input->>'note')>1000 OR jsonb_typeof(p_input->'lineMemos') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid journal description input' USING ERRCODE='22023';END IF;
 target:=(p_input->>'id')::uuid;request:=(p_input->>'requestId')::uuid;expected:=(p_input->>'revision')::integer;
 IF target IS NULL OR request IS NULL OR expected<0 OR jsonb_array_length(p_input->'lineMemos')>2000 OR (SELECT count(*)<>count(DISTINCT x->>'id') FROM jsonb_array_elements(p_input->'lineMemos') x) THEN RAISE EXCEPTION 'Invalid journal description input' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=request;
 IF FOUND THEN
  IF prior.operation<>'journal_descriptions' OR prior.payload<>p_input OR prior.created_by<>auth.uid() THEN RAISE EXCEPTION 'Description request conflict' USING ERRCODE='40001';END IF;
  RETURN prior.result||jsonb_build_object('duplicate',true);
 END IF;
 SELECT * INTO source FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=target FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.bf_journal WHERE cafe_id=p_cafe_id AND document_id=target) THEN RAISE EXCEPTION 'Journal unavailable' USING ERRCODE='42501';END IF;
 SELECT * INTO stored FROM public.bf_journal_descriptions WHERE cafe_id=p_cafe_id AND document_id=target FOR UPDATE;
 IF coalesce(stored.revision,0)<>expected THEN RAISE EXCEPTION 'Description revision conflict' USING ERRCODE='40001';END IF;
 revision:=coalesce(stored.revision,0)+1;before_note:=coalesce(stored.payload->>'note',source.note);new_note:=p_input->>'note';memos:=coalesce(stored.payload->'lineMemos','{}'::jsonb);
 IF before_note IS DISTINCT FROM new_note THEN
  INSERT INTO public.bf_journal_description_events(cafe_id,document_id,revision,field,before_value,after_value,created_by,created_at) VALUES(p_cafe_id,target,revision,'document_note',before_note,new_note,auth.uid(),event_time);changes:=changes+1;
 END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_input->'lineMemos') LOOP
  IF jsonb_typeof(entry) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(entry) k WHERE k NOT IN('id','memo')) OR jsonb_typeof(entry->'memo') IS DISTINCT FROM 'string' OR length(entry->>'memo')>300 THEN RAISE EXCEPTION 'Invalid line description' USING ERRCODE='22023';END IF;
  SELECT * INTO line FROM public.bf_journal WHERE cafe_id=p_cafe_id AND document_id=target AND id=(entry->>'id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'Journal line unavailable' USING ERRCODE='42501';END IF;
  before_memo:=coalesce(memos->>line.id::text,line.memo);
  IF before_memo IS DISTINCT FROM entry->>'memo' THEN
   INSERT INTO public.bf_journal_description_events(cafe_id,document_id,revision,field,line_id,before_value,after_value,created_by,created_at) VALUES(p_cafe_id,target,revision,'line_memo',line.id,before_memo,entry->>'memo',auth.uid(),event_time);changes:=changes+1;
   memos:=memos||jsonb_build_object(line.id::text,entry->>'memo');
  END IF;
 END LOOP;
 IF changes>0 THEN
  INSERT INTO public.bf_journal_descriptions(cafe_id,document_id,revision,payload,updated_by) VALUES(p_cafe_id,target,revision,jsonb_build_object('note',new_note,'lineMemos',memos),auth.uid())
   ON CONFLICT(document_id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload,updated_by=excluded.updated_by,updated_at=clock_timestamp();
 ELSE revision:=coalesce(stored.revision,0);END IF;
 answer:=jsonb_build_object('id',target,'revision',revision,'changed',changes,'duplicate',false);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,request,'journal_descriptions',p_input,answer,auth.uid());
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_save_quote(p_cafe_id uuid, p_id uuid, p_revision integer, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
DECLARE q public.bf_quotes%ROWTYPE; inv jsonb; entry jsonb; rows jsonb:='[]'; final_rows jsonb:='[]';
 product public.menu_products%ROWTYPE; customer_name text:=''; warehouse_name text:=''; strict_refs boolean;
 qty numeric; price numeric; rate numeric; gross numeric; disc numeric; after_row numeric; value numeric;
 subtotal numeric:=0; after_rows numeric:=0; doc_discount numeric; remaining numeric; base_left numeric; allocated numeric;
 taxable numeric; row_tax numeric; row_total numeric; tax numeric:=0; total numeric:=0; inclusive boolean;
 quote_date date; valid_date date;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN ('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 IF p_id IS NULL OR p_revision IS NULL OR p_revision<0 OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000
  OR jsonb_typeof(p_payload->'document') IS DISTINCT FROM 'object' OR jsonb_typeof(p_payload#>'{document,invoice}') IS DISTINCT FROM 'object'
  OR coalesce(p_payload->>'status','') NOT IN ('draft','ready','accepted','rejected') OR coalesce(p_payload->>'date','') !~ '^\d{4}-\d{2}-\d{2}$'
  OR coalesce(p_payload->>'validUntil','') !~ '^(|\d{4}-\d{2}-\d{2})$' OR p_payload::text ~* '"[-+]?(nan|infinity)"'
 THEN RAISE EXCEPTION 'راجع بيانات عرض السعر' USING ERRCODE='22023'; END IF;
 quote_date:=(p_payload->>'date')::date; valid_date:=nullif(p_payload->>'validUntil','')::date;
 IF NOT isfinite(quote_date) OR (valid_date IS NOT NULL AND (NOT isfinite(valid_date) OR valid_date<quote_date)) THEN RAISE EXCEPTION 'تاريخ الانتهاء يجب ألا يسبق تاريخ العرض'; END IF;
 inv:=p_payload#>'{document,invoice}'; strict_refs:=p_payload->>'status'<>'draft';
 IF jsonb_typeof(inv->'lines') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'أضف بنود العرض'; END IF;
 IF jsonb_array_length(inv->'lines') NOT BETWEEN 1 AND 100 OR length(coalesce(inv->>'note',''))>500
  OR coalesce(inv->>'paymentKind','')<>'credit' OR coalesce(inv->>'accountId','')<>''
  OR coalesce(p_payload#>'{document,attachments}','[]')<>'[]'::jsonb
  OR coalesce((p_payload#>>'{document,deposit,value}')::numeric,0)<>0
  OR coalesce((p_payload#>>'{document,deposit,paid}')::boolean,false)
  OR coalesce((p_payload#>>'{document,delivery,confirmed}')::boolean,false)
 THEN RAISE EXCEPTION 'عرض السعر لا يسجل تحصيلًا أو تسليمًا'; END IF;
 IF nullif(inv->>'partyId','') IS NOT NULL THEN
  SELECT name INTO customer_name FROM public.bf_parties WHERE cafe_id=p_cafe_id AND id::text=inv->>'partyId' AND kind='customer' AND (NOT strict_refs OR active);
  IF NOT FOUND THEN RAISE EXCEPTION 'اختر عميلًا متاحًا للعلامة'; END IF;
 ELSIF strict_refs THEN RAISE EXCEPTION 'اختر العميل قبل حفظ العرض'; END IF;
 IF nullif(inv->>'warehouseId','') IS NOT NULL THEN
  SELECT name INTO warehouse_name FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id::text=inv->>'warehouseId' AND (NOT strict_refs OR active);
  IF NOT FOUND THEN RAISE EXCEPTION 'اختر مستودعًا متاحًا للعلامة'; END IF;
 ELSIF strict_refs THEN RAISE EXCEPTION 'اختر المستودع قبل حفظ العرض'; END IF;
 inclusive:=coalesce((inv->>'taxInclusive')::boolean,false);
 FOR entry IN SELECT item.value FROM jsonb_array_elements(inv->'lines') item LOOP
  product:=NULL;
  IF nullif(entry->>'productId','') IS NOT NULL THEN
   SELECT * INTO product FROM public.menu_products WHERE cafe_id=p_cafe_id AND id::text=entry->>'productId' AND deleted_at IS NULL AND (NOT strict_refs OR available);
   IF NOT FOUND THEN RAISE EXCEPTION 'أحد المنتجات غير متاح للعلامة'; END IF;
  ELSIF strict_refs THEN RAISE EXCEPTION 'حدد الصنف في كل بند'; END IF;
  qty:=(entry->>'quantity')::numeric; price:=(entry->>'price')::numeric; rate:=coalesce((entry->>'vatRate')::numeric,(inv->>'vatRate')::numeric,0);
  IF qty IS NULL OR qty<0 OR (strict_refs AND qty=0) OR qty>9999 OR qty<>round(qty,3)
   OR price IS NULL OR price<0 OR price>10000000 OR price<>round(price,2) OR rate<0 OR rate>100 OR rate<>round(rate,2)
   OR length(coalesce(entry->>'description',''))>500 THEN RAISE EXCEPTION 'راجع أسعار وكميات وضريبة البنود'; END IF;
  gross:=round(qty*price,2); value:=coalesce((entry->>'discount')::numeric,0);
  IF coalesce(entry->>'discountKind','amount') NOT IN ('amount','percent') OR value<0 OR (entry->>'discountKind'='percent' AND value>100) THEN RAISE EXCEPTION 'راجع خصم البند'; END IF;
  disc:=round(CASE WHEN entry->>'discountKind'='percent' THEN gross*value/100 ELSE value END,2);
  IF disc>gross THEN RAISE EXCEPTION 'خصم البند أكبر من قيمته'; END IF;
  after_row:=gross-disc; subtotal:=subtotal+gross; after_rows:=after_rows+after_row;
  rows:=rows||jsonb_build_array(jsonb_build_object('productId',coalesce(entry->>'productId',''),'name',coalesce(product.name,''),'description',coalesce(entry->>'description',''),'quantity',qty,'price',price,'rowDiscount',disc,'after',after_row,'vatRate',rate));
 END LOOP;
 value:=CASE WHEN coalesce((inv->>'discountEnabled')::boolean,true) THEN coalesce((inv->>'discountValue')::numeric,0) ELSE 0 END;
 IF coalesce(inv->>'discountKind','amount') NOT IN ('amount','percent') OR value<0 OR (inv->>'discountKind'='percent' AND value>100) THEN RAISE EXCEPTION 'راجع خصم العرض'; END IF;
 doc_discount:=round(CASE WHEN inv->>'discountKind'='percent' THEN after_rows*value/100 ELSE value END,2);
 IF doc_discount>after_rows THEN RAISE EXCEPTION 'خصم العرض أكبر من قيمته'; END IF;
 remaining:=doc_discount; base_left:=after_rows;
 FOR entry IN SELECT item.value FROM jsonb_array_elements(rows) item LOOP
  after_row:=(entry->>'after')::numeric; rate:=(entry->>'vatRate')::numeric;
  allocated:=least(after_row,remaining,CASE WHEN base_left=0 THEN 0 ELSE round(remaining*after_row/base_left,2) END);
  remaining:=remaining-allocated; base_left:=base_left-after_row; taxable:=after_row-allocated;
  row_tax:=round(CASE WHEN inclusive THEN taxable-taxable/(1+rate/100) ELSE taxable*rate/100 END,2);
  row_total:=CASE WHEN inclusive THEN taxable ELSE taxable+row_tax END;
  tax:=tax+row_tax; total:=total+row_total;
  final_rows:=final_rows||jsonb_build_array((entry-'after'-'rowDiscount')||jsonb_build_object('discount',(entry->>'rowDiscount')::numeric+allocated,'net',row_total-row_tax,'tax',row_tax,'total',row_total));
 END LOOP;
 IF total>1000000000 OR (strict_refs AND total<=0) THEN RAISE EXCEPTION 'راجع إجمالي عرض السعر'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60416));
 SELECT * INTO q FROM public.bf_quotes WHERE id=p_id FOR UPDATE;
 IF FOUND THEN
  IF q.cafe_id<>p_cafe_id THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  IF q.payload=p_payload THEN RETURN brand_finance_private.quote_record(q); END IF;
  IF q.invoice_draft_id IS NOT NULL THEN RAISE EXCEPTION 'تم تحويل العرض إلى فاتورة ولا يمكن تعديله'; END IF;
  IF q.revision<>p_revision THEN RAISE EXCEPTION 'تغير العرض في جلسة أخرى افتح أحدث نسخة' USING ERRCODE='40001'; END IF;
  UPDATE public.bf_quotes SET payload=p_payload,revision=revision+1,customer_name=coalesce(customer_name,''),warehouse_name=coalesce(warehouse_name,''),lines=final_rows,
   subtotal=subtotal,discount=subtotal-after_rows+doc_discount,tax=tax,total=total,updated_by=auth.uid(),updated_at=clock_timestamp()
   WHERE id=p_id RETURNING * INTO q;
 ELSE
  IF p_revision<>0 THEN RAISE EXCEPTION 'Quote conflict' USING ERRCODE='40001'; END IF;
  IF (SELECT count(*) FROM public.bf_quotes WHERE cafe_id=p_cafe_id)>=500 THEN RAISE EXCEPTION 'وصلت إلى الحد الأقصى للعروض المحفوظة'; END IF;
  INSERT INTO public.bf_quotes(id,cafe_id,payload,customer_name,warehouse_name,lines,subtotal,discount,tax,total,created_by,updated_by)
   VALUES(p_id,p_cafe_id,p_payload,coalesce(customer_name,''),coalesce(warehouse_name,''),final_rows,subtotal,subtotal-after_rows+doc_discount,tax,total,auth.uid(),auth.uid()) RETURNING * INTO q;
 END IF;
 RETURN brand_finance_private.quote_record(q);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_save_recurring_invoice(p_cafe_id uuid, p_id uuid, p_revision integer, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.bf_recurring_invoices%ROWTYPE;old public.bf_recurring_invoices%ROWTYPE;role_name text;draft uuid:=gen_random_uuid();doc jsonb;totals jsonb;cnt integer;step integer;lead integer;terms integer;first_day date;next_day date;desired text;entry jsonb;final_date date;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_id IS NULL OR p_revision IS NULL OR p_revision<0 OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000 OR p_payload::text~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'راجع بيانات الاشتراك';END IF;
 IF coalesce(length(trim(p_payload->>'name')),0) NOT BETWEEN 1 AND 160 OR jsonb_typeof(p_payload->'active') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_payload->'showPeriod') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع اسم الاشتراك وحالته';END IF;
 cnt:=(p_payload->>'count')::integer;step:=(p_payload->>'interval')::integer;lead:=(p_payload->>'leadDays')::integer;terms:=(p_payload->>'paymentTermsDays')::integer;first_day:=(p_payload->>'firstDate')::date;
 IF cnt IS NULL OR cnt NOT BETWEEN 0 AND 10000 OR step IS NULL OR step NOT BETWEEN 1 AND 365 OR lead IS NULL OR lead NOT BETWEEN 0 AND 365 OR terms IS NULL OR terms NOT BETWEEN 0 AND 3650 THEN RAISE EXCEPTION 'راجع عدد مرات التكرار ومدة الاستحقاق';END IF;
 final_date:=brand_finance_private.recurring_date(first_day,p_payload->>'unit',step,CASE WHEN cnt=0 THEN 5 ELSE cnt END);
 IF final_date+terms>'9999-12-31'::date THEN RAISE EXCEPTION 'تاريخ الاستحقاق خارج النطاق المسموح';END IF;
 doc:=p_payload->'document';
 IF jsonb_typeof(doc) IS DISTINCT FROM 'object' OR doc#>>'{invoice,paymentKind}' IS DISTINCT FROM 'credit' OR coalesce(doc#>>'{invoice,accountId}','')<>'' OR coalesce((doc#>>'{invoice,applyCredit}')::boolean,false) OR coalesce(doc#>>'{invoice,manualNumber}','')<>'' OR coalesce(doc#>>'{invoice,currency}','SAR')<>'SAR' OR coalesce((doc#>>'{invoice,adjustment,amount}')::numeric,0)<>0 OR coalesce(doc#>>'{invoice,priceListId}','')<>'' OR coalesce((doc#>>'{deposit,value}')::numeric,0)<>0 OR coalesce((doc#>>'{deposit,paid}')::boolean,false) OR coalesce(doc->>'shipping','none')<>'none' OR coalesce((doc#>>'{delivery,confirmed}')::boolean,false) OR coalesce(doc->>'deliveryMethod','print')<>'print' OR coalesce(jsonb_array_length(doc->'attachments'),0)>0 OR coalesce(jsonb_array_length(doc->'extraFields'),0)>3 THEN RAISE EXCEPTION 'الفواتير الدورية آجلة دون تحصيل أو إرسال تلقائي أو مرفقات';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO old FROM public.bf_recurring_invoices WHERE id=p_id FOR UPDATE;
 IF FOUND THEN
  IF old.cafe_id<>p_cafe_id OR old.status='deleted' THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  IF old.payload=p_payload THEN RETURN brand_finance_private.recurring_detail(old);END IF;
  IF old.revision<>p_revision THEN RAISE EXCEPTION 'Subscription conflict' USING ERRCODE='40001';END IF;
  IF old.generated_count>0 AND (old.payload->>'firstDate' IS DISTINCT FROM p_payload->>'firstDate' OR old.payload->>'unit' IS DISTINCT FROM p_payload->>'unit' OR old.payload->>'interval' IS DISTINCT FROM p_payload->>'interval') THEN RAISE EXCEPTION 'لا يمكن تغيير بداية التكرار أو فترته بعد إصدار الفواتير';END IF;
  IF cnt>0 AND cnt<old.generated_count THEN RAISE EXCEPTION 'عدد مرات التكرار أقل من الفواتير الصادرة';END IF;
 ELSE IF p_revision<>0 THEN RAISE EXCEPTION 'Subscription conflict' USING ERRCODE='40001';END IF;IF (SELECT count(*) FROM public.bf_recurring_invoices WHERE cafe_id=p_cafe_id AND status<>'deleted')>=500 THEN RAISE EXCEPTION 'تم بلوغ الحد الأقصى للاشتراكات';END IF;END IF;
 doc:=jsonb_set(doc,'{supplyDate}',to_jsonb((now() AT TIME ZONE 'Asia/Riyadh')::date::text));
 INSERT INTO public.bf_invoice_drafts(id,cafe_id,payload,created_by,updated_by) VALUES(draft,p_cafe_id,doc,auth.uid(),auth.uid());
 totals:=brand_finance_private.issue_company_invoice_actor(auth.uid(),true,p_cafe_id,draft,1,NULL,NULL,'');
 DELETE FROM public.bf_invoice_drafts WHERE id=draft;
 desired:=CASE WHEN cnt>0 AND coalesce(old.generated_count,0)>=cnt THEN 'completed' WHEN (p_payload->>'active')::boolean THEN 'active' ELSE 'paused' END;
 next_day:=CASE WHEN desired='completed' THEN NULL ELSE brand_finance_private.recurring_date(first_day,p_payload->>'unit',step,coalesce(old.generated_count,0)) END;
 INSERT INTO public.bf_recurring_invoices(id,cafe_id,payload,totals,status,actor_id,next_date,next_issue_date) VALUES(p_id,p_cafe_id,p_payload,totals,desired,auth.uid(),next_day,next_day-lead)
 ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,totals=excluded.totals,status=excluded.status,actor_id=excluded.actor_id,next_date=excluded.next_date,next_issue_date=excluded.next_issue_date,revision=bf_recurring_invoices.revision+1,next_attempt_at=now(),last_error=NULL,failure_count=0,updated_at=clock_timestamp() RETURNING * INTO r;
 INSERT INTO public.bf_recurring_events(cafe_id,subscription_id,actor_id,action) VALUES(p_cafe_id,p_id,auth.uid(),CASE WHEN old.id IS NULL THEN 'created' ELSE 'updated' END);
 RETURN brand_finance_private.recurring_detail(r);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_save_shipping_option(p_cafe_id uuid, p_id uuid, p_option jsonb, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE current_option public.bf_shipping_options%ROWTYPE;new_option public.bf_shipping_options%ROWTYPE;before_value jsonb;account_id uuid;is_new boolean;
BEGIN
  PERFORM brand_finance_private.shipping_role(p_cafe_id,true);
  IF p_id IS NULL OR p_revision IS NULL OR p_revision<0 OR jsonb_typeof(p_option) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'راجع بيانات خيار الشحن' USING ERRCODE='22023';END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_option))<>7 OR NOT p_option ?& ARRAY['name','active','fee','taxRate','displayOrder','accountId','description']
    OR jsonb_typeof(p_option->'name') IS DISTINCT FROM 'string' OR length(btrim(p_option->>'name')) NOT BETWEEN 1 AND 160 OR p_option->>'name'<>btrim(p_option->>'name')
    OR jsonb_typeof(p_option->'active') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_option->'fee') IS DISTINCT FROM 'number'
    OR jsonb_typeof(p_option->'displayOrder') IS DISTINCT FROM 'number' OR jsonb_typeof(p_option->'description') IS DISTINCT FROM 'string' OR length(p_option->>'description')>1000
    OR (p_option->'taxRate'<>'null'::jsonb AND p_option->'taxRate'<>'15'::jsonb)
    OR (p_option->'accountId'<>'null'::jsonb AND (jsonb_typeof(p_option->'accountId') IS DISTINCT FROM 'string' OR p_option->>'accountId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'))
  THEN RAISE EXCEPTION 'راجع اسم خيار الشحن وحالته وضريبته وحسابه' USING ERRCODE='22023';END IF;
  IF (p_option->>'fee')::numeric NOT BETWEEN 0 AND 10000000 OR (p_option->>'fee')::numeric<>round((p_option->>'fee')::numeric,2) OR (p_option->>'displayOrder')::numeric NOT BETWEEN 0 AND 999999 OR (p_option->>'displayOrder')::numeric<>trunc((p_option->>'displayOrder')::numeric) THEN RAISE EXCEPTION 'راجع رسوم الشحن وترتيب العرض' USING ERRCODE='22023';END IF;
  account_id:=(p_option->>'accountId')::uuid;
  IF account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_accounts a WHERE a.cafe_id=p_cafe_id AND a.id=account_id AND a.active AND a.kind='revenue') THEN RAISE EXCEPTION 'اختر حساب إيراد نشطًا' USING ERRCODE='22023';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60622));
  SELECT * INTO current_option FROM public.bf_shipping_options WHERE cafe_id=p_cafe_id AND id=p_id FOR UPDATE;
  is_new:=NOT FOUND;
  IF NOT is_new THEN
    IF current_option.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'خيار الشحن محذوف' USING ERRCODE='22023';END IF;
    before_value:=brand_finance_private.shipping_option_json(current_option)-ARRAY['id','revision','createdAt','updatedAt'];
    IF before_value=p_option THEN RETURN brand_finance_private.shipping_option_json(current_option);END IF;
  END IF;
  IF coalesce(current_option.revision,0)<>p_revision THEN RAISE EXCEPTION 'Shipping option conflict' USING ERRCODE='40001';END IF;
  IF is_new AND (SELECT count(*) FROM public.bf_shipping_options WHERE cafe_id=p_cafe_id AND deleted_at IS NULL)>=500 THEN RAISE EXCEPTION 'الحد الأقصى ٥٠٠ خيار شحن' USING ERRCODE='22023';END IF;
  INSERT INTO public.bf_shipping_options(id,cafe_id,name,active,fee,tax_rate,display_order,account_id,description,revision,created_by,updated_by)
    VALUES(p_id,p_cafe_id,p_option->>'name',(p_option->>'active')::boolean,(p_option->>'fee')::numeric,(p_option->>'taxRate')::numeric,(p_option->>'displayOrder')::integer,account_id,p_option->>'description',p_revision+1,auth.uid(),auth.uid())
    ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active,fee=excluded.fee,tax_rate=excluded.tax_rate,display_order=excluded.display_order,account_id=excluded.account_id,description=excluded.description,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=clock_timestamp() WHERE public.bf_shipping_options.cafe_id=p_cafe_id RETURNING * INTO new_option;
  IF new_option.id IS NULL THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  INSERT INTO public.bf_shipping_events(cafe_id,option_id,revision,action,before_value,after_value,created_by) VALUES(p_cafe_id,p_id,new_option.revision,CASE WHEN is_new THEN 'created' ELSE 'updated' END,before_value,p_option,auth.uid());
  RETURN brand_finance_private.shipping_option_json(new_option);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_set_invoice_line_notes(p_cafe_id uuid, p_draft_id uuid, p_draft_revision integer, p_revision integer, p_lines jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text;draft public.bf_invoice_drafts%ROWTYPE;selection public.bf_invoice_line_note_drafts%ROWTYPE;issued_id uuid;historical jsonb;normalized jsonb;next_revision integer;
BEGIN
  role_name:=brand_finance_private.role_for(p_cafe_id);
  IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  IF p_draft_revision IS NULL OR p_draft_revision<1 OR p_revision IS NULL OR p_revision<0 THEN RAISE EXCEPTION 'Invalid notes revision' USING ERRCODE='22023';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
  SELECT * INTO draft FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=p_draft_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501';END IF;
  SELECT * INTO selection FROM public.bf_invoice_line_note_drafts WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  SELECT document_id INTO issued_id FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  IF issued_id IS NOT NULL THEN
    SELECT coalesce(jsonb_agg(l-'lineIndex' ORDER BY (l->>'key')::numeric),'[]'::jsonb) INTO historical FROM public.bf_invoice_line_notes n CROSS JOIN LATERAL jsonb_array_elements(n.lines) l WHERE n.cafe_id=p_cafe_id AND n.document_id=issued_id;
    normalized:=brand_finance_private.validate_invoice_line_note_selection(p_lines,coalesce(selection.lines,'[]'::jsonb));
    IF normalized IS DISTINCT FROM historical THEN RAISE EXCEPTION 'لا يمكن تغيير ملاحظات فاتورة صادرة' USING ERRCODE='22023';END IF;
    RETURN jsonb_build_object('revision',coalesce(selection.revision,0),'lines',historical,'issued',true);
  END IF;
  IF draft.revision<>p_draft_revision THEN RAISE EXCEPTION 'Draft conflict' USING ERRCODE='40001';END IF;
  normalized:=brand_finance_private.validate_invoice_line_note_selection(p_lines,draft.payload#>'{invoice,lines}');
  IF selection.draft_id IS NOT NULL AND selection.lines=normalized THEN
    UPDATE public.bf_invoice_line_note_drafts SET draft_revision=p_draft_revision,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
    RETURN jsonb_build_object('revision',selection.revision,'lines',normalized,'issued',false);
  END IF;
  IF coalesce(selection.revision,0)<>p_revision THEN RAISE EXCEPTION 'Invoice line notes conflict' USING ERRCODE='40001';END IF;
  next_revision:=coalesce(selection.revision,0)+1;
  INSERT INTO public.bf_invoice_line_note_drafts(cafe_id,draft_id,lines,revision,draft_revision,updated_by) VALUES(p_cafe_id,p_draft_id,normalized,next_revision,p_draft_revision,auth.uid())
    ON CONFLICT(draft_id) DO UPDATE SET lines=excluded.lines,revision=excluded.revision,draft_revision=excluded.draft_revision,updated_by=excluded.updated_by,updated_at=clock_timestamp();
  RETURN jsonb_build_object('revision',next_revision,'lines',normalized,'issued',false);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_set_invoice_order_source(p_cafe_id uuid, p_draft_id uuid, p_draft_revision integer, p_source_id uuid, p_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; draft public.bf_invoice_drafts%ROWTYPE; chosen public.bf_invoice_order_source_drafts%ROWTYPE; config jsonb; next_revision integer; issued_id uuid; historical public.bf_invoice_order_sources%ROWTYPE;
BEGIN
  role_name:=brand_finance_private.role_for(p_cafe_id);
  IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  IF p_revision IS NULL OR p_revision<0 OR p_draft_revision IS NULL OR p_draft_revision<1 THEN RAISE EXCEPTION 'Invalid source revision' USING ERRCODE='22023';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
  SELECT * INTO draft FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=p_draft_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501';END IF;
  SELECT * INTO chosen FROM public.bf_invoice_order_source_drafts WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  SELECT document_id INTO issued_id FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  IF issued_id IS NOT NULL THEN
    SELECT * INTO historical FROM public.bf_invoice_order_sources WHERE cafe_id=p_cafe_id AND document_id=issued_id;
    IF historical.source_id IS DISTINCT FROM p_source_id THEN RAISE EXCEPTION 'لا يمكن تغيير مصدر طلب فاتورة صادرة' USING ERRCODE='22023';END IF;
    RETURN jsonb_build_object('sourceId',historical.source_id,'revision',coalesce(chosen.revision,0),'issued',true);
  END IF;
  IF draft.revision<>p_draft_revision THEN RAISE EXCEPTION 'Draft conflict' USING ERRCODE='40001';END IF;
  config:=brand_finance_private.order_source_settings(p_cafe_id);
  IF p_source_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(config->'sources') s WHERE (s->>'id')::uuid=p_source_id AND (s->>'active')::boolean) THEN RAISE EXCEPTION 'مصدر الطلب غير متاح اختر مصدرًا نشطًا' USING ERRCODE='22023';END IF;
  INSERT INTO public.bf_invoice_order_source_last(cafe_id,user_id,source_id) VALUES(p_cafe_id,auth.uid(),p_source_id)
    ON CONFLICT(cafe_id,user_id) DO UPDATE SET source_id=excluded.source_id,updated_at=clock_timestamp();
  IF chosen.draft_id IS NOT NULL AND chosen.source_id IS NOT DISTINCT FROM p_source_id THEN RETURN jsonb_build_object('sourceId',chosen.source_id,'revision',chosen.revision,'issued',false);END IF;
  IF coalesce(chosen.revision,0)<>p_revision THEN RAISE EXCEPTION 'Order source selection conflict' USING ERRCODE='40001';END IF;
  next_revision:=coalesce(chosen.revision,0)+1;
  INSERT INTO public.bf_invoice_order_source_drafts(cafe_id,draft_id,source_id,revision,updated_by) VALUES(p_cafe_id,p_draft_id,p_source_id,next_revision,auth.uid())
    ON CONFLICT(draft_id) DO UPDATE SET source_id=excluded.source_id,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=clock_timestamp();
  RETURN jsonb_build_object('sourceId',p_source_id,'revision',next_revision,'issued',false);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_set_invoice_shipping_charge(p_cafe_id uuid, p_draft_id uuid, p_draft_revision integer, p_revision integer, p_settings_revision integer, p_option_revision integer, p_selection jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE draft public.bf_invoice_drafts%ROWTYPE;chosen public.bf_invoice_shipping_drafts%ROWTYPE;option public.bf_shipping_options%ROWTYPE;selected jsonb;historical jsonb;issued_id uuid;settings jsonb;settings_revision integer;aid uuid;next_revision integer;
BEGIN
 IF auth.uid() IS NULL OR coalesce(brand_finance_private.role_for(p_cafe_id),'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_draft_revision IS NULL OR p_draft_revision<1 OR p_revision IS NULL OR p_revision<0 OR p_settings_revision IS NULL OR p_settings_revision<0 THEN RAISE EXCEPTION 'Invalid shipping revision' USING ERRCODE='22023';END IF;
 selected:=brand_finance_private.shipping_charge_selection(p_selection);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 SELECT * INTO draft FROM public.bf_invoice_drafts WHERE cafe_id=p_cafe_id AND id=p_draft_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE='42501';END IF;
 SELECT * INTO chosen FROM public.bf_invoice_shipping_drafts WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
 SELECT document_id INTO issued_id FROM public.bf_company_invoices WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
 IF issued_id IS NOT NULL THEN
  SELECT jsonb_build_object('optionId',snapshot->'optionId','name',snapshot->'name','amount',snapshot->'amount','taxRate',snapshot->'taxRate') INTO historical FROM public.bf_invoice_shipping_charges WHERE cafe_id=p_cafe_id AND document_id=issued_id;
  IF selected IS DISTINCT FROM historical THEN RAISE EXCEPTION 'لا يمكن تغيير شحن فاتورة صادرة' USING ERRCODE='22023';END IF;
  RETURN jsonb_build_object('revision',coalesce(chosen.revision,0),'selection',historical,'issued',true);
 END IF;
 IF draft.revision<>p_draft_revision THEN RAISE EXCEPTION 'Draft conflict' USING ERRCODE='40001';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60622));
 SELECT s.settings,s.revision INTO settings,settings_revision FROM public.bf_shipping_settings s WHERE s.cafe_id=p_cafe_id;
 settings_revision:=coalesce(settings_revision,0);
 IF selected IS NOT NULL AND NOT coalesce((settings->>'enabled')::boolean,false) AND chosen.draft_id IS NOT NULL AND chosen.selection=selected THEN
  UPDATE public.bf_invoice_shipping_drafts SET draft_revision=p_draft_revision,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  RETURN jsonb_build_object('revision',chosen.revision,'selection',selected,'issued',false);
 END IF;
 IF selected IS NOT NULL THEN
  IF NOT coalesce((settings->>'enabled')::boolean,false) THEN RAISE EXCEPTION 'رسوم الشحن غير مفعلة' USING ERRCODE='22023';END IF;
  IF settings_revision<>p_settings_revision THEN RAISE EXCEPTION 'Shipping settings conflict' USING ERRCODE='40001';END IF;
  IF selected->>'optionId' IS NOT NULL THEN
   SELECT * INTO option FROM public.bf_shipping_options WHERE cafe_id=p_cafe_id AND id=(selected->>'optionId')::uuid AND active AND deleted_at IS NULL FOR SHARE;
   IF option.id IS NULL THEN RAISE EXCEPTION 'خيار الشحن غير متاح اختر خيارًا نشطًا' USING ERRCODE='22023';END IF;
   IF option.revision IS DISTINCT FROM p_option_revision OR option.name IS DISTINCT FROM selected->>'name' THEN RAISE EXCEPTION 'Shipping option conflict' USING ERRCODE='40001';END IF;
   aid:=option.account_id;
  ELSIF p_option_revision IS NOT NULL THEN RAISE EXCEPTION 'Invalid custom shipping revision' USING ERRCODE='22023';END IF;
  aid:=coalesce(aid,brand_finance_private.account(p_cafe_id,'4000'));
  IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=aid AND active AND deleted_at IS NULL AND NOT frozen AND NOT is_group AND kind='revenue') THEN RAISE EXCEPTION 'حساب إيراد الشحن غير متاح' USING ERRCODE='22023';END IF;
 END IF;
 IF chosen.draft_id IS NOT NULL AND chosen.selection IS NOT DISTINCT FROM selected AND chosen.account_id IS NOT DISTINCT FROM aid AND chosen.settings_revision=settings_revision AND chosen.option_revision IS NOT DISTINCT FROM option.revision THEN
  UPDATE public.bf_invoice_shipping_drafts SET draft_revision=p_draft_revision,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE cafe_id=p_cafe_id AND draft_id=p_draft_id;
  RETURN jsonb_build_object('revision',chosen.revision,'selection',selected,'issued',false);
 END IF;
 IF coalesce(chosen.revision,0)<>p_revision THEN RAISE EXCEPTION 'Shipping selection conflict' USING ERRCODE='40001';END IF;
 next_revision:=coalesce(chosen.revision,0)+1;
 INSERT INTO public.bf_invoice_shipping_drafts(cafe_id,draft_id,selection,revision,draft_revision,settings_revision,option_revision,account_id,updated_by) VALUES(p_cafe_id,p_draft_id,selected,next_revision,p_draft_revision,settings_revision,option.revision,aid,auth.uid())
 ON CONFLICT(draft_id) DO UPDATE SET selection=excluded.selection,revision=excluded.revision,draft_revision=excluded.draft_revision,settings_revision=excluded.settings_revision,option_revision=excluded.option_revision,account_id=excluded.account_id,updated_by=excluded.updated_by,updated_at=clock_timestamp();
 RETURN jsonb_build_object('revision',next_revision,'selection',selected,'issued',false);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_settle_cash_difference(p_cafe_id uuid, p_variance_id uuid, p_resolution text, p_employee_id uuid, p_note text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v public.bf_shift_cash_variances%ROWTYPE; prior public.bf_requests%ROWTYPE; payload jsonb; result jsonb; doc uuid:=gen_random_uuid(); n bigint; party uuid; employee_name text; title text; amount numeric;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_settle_cash_difference',NULL);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 PERFORM brand_finance_private.role_for(p_cafe_id);
 IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe_id AND owner_user_id=auth.uid()) THEN RAISE EXCEPTION 'اعتماد مالك العلامة مطلوب لتسوية الفرق' USING ERRCODE='42501'; END IF;
 p_note:=btrim(coalesce(p_note,''));
 IF p_variance_id IS NULL OR p_request_id IS NULL OR p_resolution IS NULL OR p_resolution NOT IN('charge_employee','waive') OR length(p_note) NOT BETWEEN 1 AND 1000 OR (p_resolution='charge_employee')<>(p_employee_id IS NOT NULL) THEN RAISE EXCEPTION 'بيانات تسوية الفرق غير مكتملة'; END IF;
 payload:=jsonb_build_object('varianceId',p_variance_id,'resolution',p_resolution,'employeeId',p_employee_id,'note',p_note);
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.operation<>'cash_difference_settle' OR prior.payload<>payload OR prior.created_by<>auth.uid() THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى'; END IF;
  RETURN prior.result||'{"duplicate":true}'::jsonb;
 END IF;
 IF EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe_id AND closed_through>=(now() AT TIME ZONE 'Asia/Riyadh')::date) THEN RAISE EXCEPTION 'الفترة المالية مقفلة'; END IF;
 SELECT * INTO v FROM public.bf_shift_cash_variances WHERE cafe_id=p_cafe_id AND id=p_variance_id FOR UPDATE;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.bf_shift_cash_resolutions WHERE variance_id=p_variance_id) THEN RAISE EXCEPTION 'الفرق غير موجود أو تمت تسويته'; END IF;
 amount:=abs(v.difference);
 IF p_resolution='charge_employee' THEN
  IF v.difference>=0 THEN RAISE EXCEPTION 'تحميل الموظف متاح للعجز فقط'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=p_employee_id AND p.status='active') OR NOT(
   p_employee_id=v.employee_id OR coalesce(p_employee_id=v.previous_employee_id,false) OR EXISTS(SELECT 1 FROM public.bf_staff WHERE cafe_id=p_cafe_id AND user_id=p_employee_id AND active)
  ) THEN RAISE EXCEPTION 'اختر موظفا مرتبطا بهذه العلامة'; END IF;
  employee_name:=CASE WHEN p_employee_id=v.employee_id THEN v.employee_name WHEN p_employee_id=v.previous_employee_id THEN v.previous_employee_name ELSE brand_finance_private.cash_employee_name(p_cafe_id,p_employee_id) END;
  SELECT party_id INTO party FROM public.bf_shift_cash_employee_accounts WHERE cafe_id=p_cafe_id AND user_id=p_employee_id;
  IF party IS NULL THEN
   INSERT INTO public.bf_parties(cafe_id,name,kind) VALUES(p_cafe_id,employee_name,'employee') RETURNING id INTO party;
   INSERT INTO public.bf_shift_cash_employee_accounts(cafe_id,user_id,party_id) VALUES(p_cafe_id,p_employee_id,party);
  END IF;
 END IF;
 title:=left('تسوية فرق '||CASE v.phase WHEN 'opening' THEN 'بداية' ELSE 'إغلاق' END||' الوردية رقم '||v.shift_number||CASE p_resolution WHEN 'charge_employee' THEN ' على الموظف '||employee_name ELSE ' دون تحميل موظف' END||' - '||p_note,1000);
 INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,shift_id,total,reference_id,note,created_by) VALUES(doc,p_cafe_id,'journal',party,v.shift_id,amount,v.document_id,title,auth.uid()) RETURNING number INTO n;
 IF p_resolution='charge_employee' THEN
  PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'1030'),amount,0,party);
  PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.cash_pending_account(p_cafe_id),0,amount);
 ELSIF v.difference<0 THEN
  PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'5300'),amount,0);
  PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.cash_pending_account(p_cafe_id),0,amount);
 ELSE
  INSERT INTO public.bf_accounts(cafe_id,code,name,kind) VALUES(p_cafe_id,'4010','إيرادات أخرى','revenue') ON CONFLICT(cafe_id,code) DO NOTHING;
  PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.cash_pending_account(p_cafe_id),amount,0);
  PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,'4010'),0,amount);
 END IF;
 INSERT INTO public.bf_shift_cash_resolutions(variance_id,cafe_id,resolution,employee_id,employee_name,document_id,note,settled_by) VALUES(v.id,p_cafe_id,p_resolution,p_employee_id,employee_name,doc,p_note,auth.uid());
 result:=jsonb_build_object('id',v.id,'document_id',doc,'number',n);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'cash_difference_settle',payload,result,auth.uid());
 INSERT INTO public.bf_treasury_audit(cafe_id,actor_id,operation,entity_id,after_data) VALUES(p_cafe_id,auth.uid(),'cash_difference_settle',doc,payload||result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_shift_attachment(p_cafe_id uuid, p_attachment_id uuid, p_finalize boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.bf_shift_attachments; r text; s public.bf_shifts; m jsonb;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_shift_attachment',CASE WHEN p_finalize THEN 'write' ELSE 'read' END);
 r:=brand_finance_private.role_for(p_cafe_id);
 IF p_finalize THEN PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412)); END IF;
 SELECT * INTO a FROM public.bf_shift_attachments WHERE cafe_id=p_cafe_id AND id=p_attachment_id FOR UPDATE;
 IF a.id IS NULL THEN RAISE EXCEPTION 'Attachment unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND id=a.shift_id;
 IF a.document_id IS NULL AND (a.uploader_id<>auth.uid() OR s.user_id<>auth.uid() OR s.status<>'open')
 OR a.document_id IS NOT NULL AND r='cashier' AND s.user_id<>auth.uid()
 THEN RAISE EXCEPTION 'Attachment access denied' USING ERRCODE='42501'; END IF;
 IF p_finalize THEN
   IF a.document_id IS NOT NULL OR a.uploader_id<>auth.uid() OR s.user_id<>auth.uid() OR s.status<>'open'
   THEN RAISE EXCEPTION 'Own draft attachment required' USING ERRCODE='42501'; END IF;
   -- Metadata is maintained by the Storage service, never accepted from clients
   SELECT metadata INTO m FROM storage.objects WHERE bucket_id='branda-finance-shift-files' AND name=a.storage_path;
   IF m IS NULL OR (m->>'size')::bigint IS DISTINCT FROM a.size_bytes
   THEN RAISE EXCEPTION 'Uploaded object size mismatch'; END IF;
   UPDATE public.bf_shift_attachments SET uploaded=true WHERE id=a.id RETURNING * INTO a;
 END IF;
 RETURN to_jsonb(a);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_shift_heartbeat(p_cafe_id uuid, p_shift_id uuid, p_device_id uuid, p_pending integer, p_conflicts integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE sh public.bf_shifts%ROWTYPE;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_shift_heartbeat',NULL);
 PERFORM brand_finance_private.role_for(p_cafe_id);
 IF p_device_id IS NULL OR p_pending IS NULL OR p_conflicts IS NULL OR p_pending NOT BETWEEN 0 AND 1000000 OR p_conflicts NOT BETWEEN 0 AND p_pending THEN RAISE EXCEPTION 'Invalid telemetry'; END IF;
 SELECT * INTO sh FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND id=p_shift_id AND user_id=auth.uid();
 IF NOT FOUND THEN RAISE EXCEPTION 'Forbidden shift' USING ERRCODE='42501'; END IF;
 INSERT INTO public.bf_shift_devices(cafe_id,shift_id,device_id,pending_count,conflict_count) VALUES(p_cafe_id,p_shift_id,p_device_id,p_pending,p_conflicts)
 ON CONFLICT(shift_id,device_id) DO UPDATE SET last_seen_at=now(),pending_count=excluded.pending_count,conflict_count=excluded.conflict_count;
 RETURN jsonb_build_object('status',sh.status,'paused',sh.supervisor_paused);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_shift_sessions(p_cafe_id uuid, p_view text DEFAULT 'list'::text, p_shift_id uuid DEFAULT NULL::uuid, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role_name text; q text; filter_account uuid; status_filter text; date_from date; date_to date; ordering text; off integer;
 sh public.bf_shifts%ROWTYPE; answer jsonb; count_rows bigint; shift_json jsonb; items jsonb;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 IF p_view IS NULL OR p_view NOT IN('list','summary','movements','invoices','refunds','payments','activity') OR jsonb_typeof(p_filters) IS DISTINCT FROM 'object' OR octet_length(p_filters::text)>2500 THEN RAISE EXCEPTION 'Invalid filters' USING ERRCODE='22023'; END IF;
 q:=lower(trim(coalesce(p_filters->>'query','')));filter_account:=nullif(p_filters->>'accountId','')::uuid;status_filter:=nullif(p_filters->>'status','');
 date_from:=nullif(p_filters->>'from','')::date;date_to:=nullif(p_filters->>'to','')::date;ordering:=coalesce(p_filters->>'sort','opened_desc');off:=coalesce((p_filters->>'offset')::integer,0);
 IF off NOT BETWEEN 0 AND 100000 OR length(q)>120 OR date_from>date_to OR (status_filter IS NOT NULL AND status_filter NOT IN('open','closed','handover')) OR ordering NOT IN('opened_desc','opened_asc','number_desc','number_asc','closed_desc','employee_asc') THEN RAISE EXCEPTION 'Invalid filters' USING ERRCODE='22023'; END IF;
 IF p_view<>'list' THEN
  SELECT * INTO sh FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND id=p_shift_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
 END IF;
 IF p_view IN('list','summary') THEN
  WITH filtered AS MATERIALIZED(
   SELECT s.*,a.name drawer_name,brand_finance_private.cash_employee_name(p_cafe_id,s.user_id) employee_name
   FROM public.bf_shifts s JOIN public.bf_accounts a ON a.cafe_id=s.cafe_id AND a.id=s.account_id
   WHERE s.cafe_id=p_cafe_id AND (p_view='list' OR s.id=p_shift_id)
   AND (filter_account IS NULL OR s.account_id=filter_account) AND (status_filter IS NULL OR s.status=status_filter)
   AND (date_from IS NULL OR s.opened_at>=date_from::timestamp AT TIME ZONE 'Asia/Riyadh')
   AND (date_to IS NULL OR s.opened_at<(date_to+1)::timestamp AT TIME ZONE 'Asia/Riyadh')
   AND (q='' OR position(q IN lower(concat(s.shift_number,' ',a.name,' ',brand_finance_private.cash_employee_name(p_cafe_id,s.user_id))))>0)
  ),paged AS MATERIALIZED(
   SELECT *,row_number() OVER(ORDER BY
    CASE WHEN ordering='number_asc' THEN shift_number END ASC,CASE WHEN ordering='number_desc' THEN shift_number END DESC,
    CASE WHEN ordering='employee_asc' THEN employee_name END ASC,CASE WHEN ordering='closed_desc' THEN closed_at END DESC NULLS LAST,
    CASE WHEN ordering='opened_asc' THEN opened_at END ASC,CASE WHEN ordering='opened_desc' THEN opened_at END DESC,id DESC) ordinal
   FROM filtered ORDER BY ordinal LIMIT 30 OFFSET CASE WHEN p_view='list' THEN off ELSE 0 END
  ),enriched AS(
   SELECT p.*,CASE WHEN p.status='closed' THEN p.expected_cash ELSE (SELECT coalesce(sum(j.debit-j.credit),0) FROM public.bf_journal j WHERE j.cafe_id=p_cafe_id AND j.account_id=p.account_id) END current_expected,
    d.last_seen_at,coalesce(d.pending_count,0) pending_count,coalesce(d.conflict_count,0) conflict_count,coalesce(d.device_count,0) device_count,
    CASE WHEN p.status='closed' THEN 'closed' WHEN p.supervisor_paused THEN 'paused' WHEN d.last_seen_at IS NULL OR d.last_seen_at<now()-interval '90 seconds' OR d.pending_count>0 THEN 'stalled' ELSE 'active' END monitor_status,
    coalesce(t.sales_total,0) sales_total,coalesce(t.refunded_total,0) refunded_total,coalesce(t.sales_total,0)-coalesce(t.refunded_total,0) net_sales
   FROM paged p
   LEFT JOIN LATERAL(SELECT max(last_seen_at) last_seen_at,sum(pending_count) pending_count,sum(conflict_count) conflict_count,count(*) device_count FROM public.bf_shift_devices WHERE cafe_id=p_cafe_id AND shift_id=p.id) d ON true
   LEFT JOIN LATERAL(SELECT sum(total) FILTER(WHERE kind='sale') sales_total,sum(total) FILTER(WHERE kind='refund') refunded_total FROM public.bf_documents WHERE cafe_id=p_cafe_id AND shift_id=p.id AND kind IN('sale','refund')) t ON true
  ) SELECT (SELECT count(*) FROM filtered),coalesce((SELECT jsonb_agg(to_jsonb(e)-'ordinal' ORDER BY ordinal) FROM enriched e),'[]') INTO count_rows,items;
  IF p_view='list' THEN RETURN jsonb_build_object('rows',items,'total',count_rows,'offset',off,'limit',30); END IF;
  shift_json:=items->0;
  RETURN jsonb_build_object('shift',shift_json,'analytics',public.brand_finance_shift_analytics(p_cafe_id,p_shift_id),'counts',jsonb_build_object(
   'invoices',(SELECT count(*) FROM public.bf_documents WHERE cafe_id=p_cafe_id AND shift_id=p_shift_id AND kind='sale'),
   'refunds',(SELECT count(*) FROM public.bf_documents WHERE cafe_id=p_cafe_id AND shift_id=p_shift_id AND kind='refund'),
   'movements',(SELECT count(*) FROM public.bf_documents WHERE cafe_id=p_cafe_id AND shift_id=p_shift_id AND kind IN('receipt','expense','purchase','transfer') AND CASE WHEN kind='purchase' THEN paid ELSE total END>0),
   'payments',(SELECT count(*) FROM public.bf_documents d WHERE d.cafe_id=p_cafe_id AND d.shift_id=p_shift_id AND ((d.kind='sale' AND d.paid>0) OR (d.kind='settlement' AND d.total>0 AND EXISTS(SELECT 1 FROM public.bf_documents i WHERE i.cafe_id=p_cafe_id AND i.id=d.reference_id AND i.kind='sale')))),
   'activity',1+CASE WHEN sh.closed_at IS NOT NULL THEN 1 ELSE 0 END+(SELECT count(*) FROM public.bf_shift_supervision WHERE cafe_id=p_cafe_id AND shift_id=p_shift_id)));
 END IF;
 IF p_view='activity' THEN
  WITH events AS(
   SELECT sh.id::text||':open' id,'open' action,sh.opened_at created_at,brand_finance_private.cash_employee_name(p_cafe_id,sh.user_id) actor,''::text note
   UNION ALL SELECT sh.id::text||':closed','closed',sh.closed_at,'غير مسجل',sh.note WHERE sh.closed_at IS NOT NULL
   UNION ALL SELECT id::text,action,created_at,actor_name,reason FROM public.bf_shift_supervision WHERE cafe_id=p_cafe_id AND shift_id=p_shift_id
  ),paged AS(SELECT * FROM events ORDER BY created_at DESC,id LIMIT 30 OFFSET off)
  SELECT (SELECT count(*) FROM events),coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'action',action,'createdAt',created_at,'actor',actor,'note',note) ORDER BY created_at DESC,id) FROM paged),'[]') INTO count_rows,items;
  RETURN jsonb_build_object('rows',items,'total',count_rows,'offset',off,'limit',30);
 END IF;
 WITH sources AS MATERIALIZED(
  SELECT d.* FROM public.bf_documents d WHERE d.cafe_id=p_cafe_id AND d.shift_id=p_shift_id AND
   CASE p_view WHEN 'invoices' THEN d.kind='sale' WHEN 'refunds' THEN d.kind='refund'
    WHEN 'movements' THEN d.kind IN('receipt','expense','purchase','transfer') AND CASE WHEN d.kind='purchase' THEN d.paid ELSE d.total END>0
    WHEN 'payments' THEN (d.kind='sale' AND d.paid>0) OR (d.kind='settlement' AND d.total>0 AND EXISTS(SELECT 1 FROM public.bf_documents i WHERE i.cafe_id=p_cafe_id AND i.id=d.reference_id AND i.kind='sale')) ELSE false END
 ),paged AS MATERIALIZED(SELECT * FROM sources ORDER BY created_at DESC,id LIMIT 30 OFFSET off)
 SELECT (SELECT count(*) FROM sources),coalesce((SELECT jsonb_agg(jsonb_build_object(
  'id',d.id,'number',d.number,'kind',d.kind,'createdAt',d.created_at,'customerName',coalesce(p.name,'عميل نقدي'),
  'creatorName',brand_finance_private.cash_employee_name(p_cafe_id,d.created_by),'total',d.total,'paid',CASE WHEN d.kind='purchase' THEN d.paid ELSE d.total END,
  'outstanding',CASE WHEN d.kind='sale' THEN (brand_finance_private.document_state(p_cafe_id,d.id)->>'outstanding')::numeric ELSE 0 END,
  'refundedTotal',CASE WHEN d.kind='sale' THEN (brand_finance_private.document_state(p_cafe_id,d.id)->>'refunded_total')::numeric ELSE 0 END,
  'accountName',coalesce(a.name,'غير مسجل'),'note',d.note,'invoiceId',inv.id,'invoiceNumber',coalesce(ext.display_number,inv.number::text),
  'payment',CASE WHEN p_view='payments' THEN brand_finance_private.invoice_payment_record(d::public.bf_documents,inv) ELSE NULL END
 ) ORDER BY d.created_at DESC,d.id) FROM paged d
 LEFT JOIN public.bf_documents inv ON inv.cafe_id=p_cafe_id AND inv.kind='sale' AND inv.id=CASE WHEN d.kind='sale' THEN d.id ELSE d.reference_id END
 LEFT JOIN public.bf_invoice_extensions ext ON ext.cafe_id=p_cafe_id AND ext.document_id=inv.id
 LEFT JOIN public.bf_parties p ON p.cafe_id=p_cafe_id AND p.id=coalesce(inv.party_id,d.party_id)
 LEFT JOIN public.bf_accounts a ON a.cafe_id=p_cafe_id AND a.id=d.account_id),'[]') INTO count_rows,items;
 RETURN jsonb_build_object('rows',items,'total',count_rows,'offset',off,'limit',30);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_shipping_activity(p_cafe_id uuid, p_id uuid, p_query jsonb DEFAULT '{"to": "", "from": "", "page": 1, "actions": [], "actorIds": [], "direction": "desc"}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE items jsonb;actors jsonb;page_number integer;total integer;sort_direction text;from_time timestamptz;until_time timestamptz;
BEGIN
  PERFORM brand_finance_private.shipping_role(p_cafe_id);
  IF NOT EXISTS(SELECT 1 FROM public.bf_shipping_options WHERE cafe_id=p_cafe_id AND id=p_id) THEN RAISE EXCEPTION 'خيار الشحن غير متاح' USING ERRCODE='22023';END IF;
  IF jsonb_typeof(p_query) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid activity query' USING ERRCODE='22023';END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_query))<>6 OR NOT p_query ?& ARRAY['actions','actorIds','from','to','direction','page']
    OR jsonb_typeof(p_query->'actions') IS DISTINCT FROM 'array' OR jsonb_typeof(p_query->'actorIds') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_query->'from') IS DISTINCT FROM 'string' OR jsonb_typeof(p_query->'to') IS DISTINCT FROM 'string'
    OR coalesce(p_query->>'direction','') NOT IN('asc','desc') OR jsonb_typeof(p_query->'page') IS DISTINCT FROM 'number'
  THEN RAISE EXCEPTION 'راجع فلاتر سجل النشاطات' USING ERRCODE='22023';END IF;
  IF jsonb_array_length(p_query->'actions')>3 OR jsonb_array_length(p_query->'actorIds')>50
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_query->'actions') a WHERE jsonb_typeof(a) IS DISTINCT FROM 'string' OR a#>>'{}' NOT IN('created','updated','deleted'))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_query->'actorIds') a WHERE jsonb_typeof(a) IS DISTINCT FROM 'string' OR a#>>'{}' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
    OR (p_query->>'page')::numeric NOT BETWEEN 1 AND 1000 OR (p_query->>'page')::numeric<>trunc((p_query->>'page')::numeric)
    OR p_query->>'from' !~ '^([0-9]{4}-[0-9]{2}-[0-9]{2})?$' OR p_query->>'to' !~ '^([0-9]{4}-[0-9]{2}-[0-9]{2})?$'
  THEN RAISE EXCEPTION 'راجع فلاتر سجل النشاطات' USING ERRCODE='22023';END IF;
  IF p_query->>'from'<>'' THEN from_time:=(p_query->>'from')::date::timestamp AT TIME ZONE 'Asia/Riyadh';END IF;
  IF p_query->>'to'<>'' THEN until_time:=((p_query->>'to')::date+1)::timestamp AT TIME ZONE 'Asia/Riyadh';END IF;
  IF from_time IS NOT NULL AND until_time IS NOT NULL AND from_time>=until_time THEN RAISE EXCEPTION 'تاريخ البداية يجب ألا يتجاوز تاريخ النهاية' USING ERRCODE='22023';END IF;
  page_number:=(p_query->>'page')::integer;sort_direction:=p_query->>'direction';
  SELECT count(*) INTO total FROM public.bf_shipping_events e WHERE e.cafe_id=p_cafe_id AND e.option_id=p_id
    AND (jsonb_array_length(p_query->'actions')=0 OR p_query->'actions' ? e.action)
    AND (jsonb_array_length(p_query->'actorIds')=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_query->'actorIds') a WHERE a::uuid=e.created_by))
    AND (from_time IS NULL OR e.created_at>=from_time) AND (until_time IS NULL OR e.created_at<until_time);
  page_number:=least(page_number,greatest(1,(total+19)/20));
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'revision',e.revision,'action',e.action,'actorId',e.created_by,'actor',coalesce((SELECT nullif(s.name,'') FROM public.bf_staff s WHERE s.cafe_id=p_cafe_id AND s.user_id=e.created_by),(SELECT nullif(p.full_name,'') FROM public.profiles p WHERE p.id=e.created_by),'مستخدم غير مسمى'),'createdAt',e.created_at,'changes',(SELECT coalesce(jsonb_agg(jsonb_build_object('field',f.name,'before',e.before_value->f.name,'after',e.after_value->f.name) ORDER BY f.position),'[]'::jsonb) FROM unnest(ARRAY['name','active','fee','taxRate','displayOrder','accountId','description']) WITH ORDINALITY f(name,position) WHERE e.before_value->f.name IS DISTINCT FROM e.after_value->f.name)) ORDER BY CASE WHEN sort_direction='asc' THEN e.revision END ASC,CASE WHEN sort_direction='desc' THEN e.revision END DESC),'[]'::jsonb) INTO items
    FROM (SELECT * FROM public.bf_shipping_events v WHERE v.cafe_id=p_cafe_id AND v.option_id=p_id
      AND (jsonb_array_length(p_query->'actions')=0 OR p_query->'actions' ? v.action)
      AND (jsonb_array_length(p_query->'actorIds')=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_query->'actorIds') a WHERE a::uuid=v.created_by))
      AND (from_time IS NULL OR v.created_at>=from_time) AND (until_time IS NULL OR v.created_at<until_time)
      ORDER BY CASE WHEN sort_direction='asc' THEN v.revision END ASC,CASE WHEN sort_direction='desc' THEN v.revision END DESC OFFSET (page_number-1)*20 LIMIT 20) e;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.created_by,'name',coalesce((SELECT nullif(s.name,'') FROM public.bf_staff s WHERE s.cafe_id=p_cafe_id AND s.user_id=a.created_by),(SELECT nullif(p.full_name,'') FROM public.profiles p WHERE p.id=a.created_by),'مستخدم غير مسمى')) ORDER BY a.created_by),'[]'::jsonb) INTO actors FROM (SELECT DISTINCT created_by FROM public.bf_shipping_events WHERE cafe_id=p_cafe_id AND option_id=p_id ORDER BY created_by LIMIT 500) a;
  RETURN jsonb_build_object('items',items,'page',page_number,'total',total,'limit',20,'actors',actors);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_shipping_option(p_cafe_id uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE option public.bf_shipping_options%ROWTYPE;
BEGIN
  PERFORM brand_finance_private.shipping_role(p_cafe_id);
  SELECT * INTO option FROM public.bf_shipping_options WHERE cafe_id=p_cafe_id AND id=p_id AND deleted_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'خيار الشحن غير متاح أو تم حذفه' USING ERRCODE='22023';END IF;
  RETURN brand_finance_private.shipping_option_json(option);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_shipping_options(p_cafe_id uuid, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE search_text text;state text;page_number integer;sort_name text;sort_direction text;total integer;items jsonb;
BEGIN
  PERFORM brand_finance_private.shipping_role(p_cafe_id);
  IF jsonb_typeof(p_query) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid shipping filters' USING ERRCODE='22023';END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_query))<>5 OR NOT p_query ?& ARRAY['query','status','page','sort','direction'] OR jsonb_typeof(p_query->'query') IS DISTINCT FROM 'string' OR length(p_query->>'query')>160 OR coalesce(p_query->>'status','') NOT IN('all','active','inactive') OR coalesce(p_query->>'sort','') NOT IN('displayOrder','name','fee','active') OR coalesce(p_query->>'direction','') NOT IN('asc','desc') OR jsonb_typeof(p_query->'page') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Invalid shipping filters' USING ERRCODE='22023';END IF;
  IF (p_query->>'page')::numeric NOT BETWEEN 1 AND 1000 OR (p_query->>'page')::numeric<>trunc((p_query->>'page')::numeric) THEN RAISE EXCEPTION 'Invalid shipping page' USING ERRCODE='22023';END IF;
  search_text:=btrim(p_query->>'query');state:=p_query->>'status';page_number:=(p_query->>'page')::integer;sort_name:=p_query->>'sort';sort_direction:=p_query->>'direction';
  SELECT count(*) INTO total FROM public.bf_shipping_options o WHERE o.cafe_id=p_cafe_id AND o.deleted_at IS NULL AND strpos(lower(o.name),lower(search_text))>0 AND (state='all' OR o.active=(state='active'));
  page_number:=least(page_number,greatest(1,(total+29)/30));
  SELECT coalesce(jsonb_agg(brand_finance_private.shipping_option_json(o)),'[]'::jsonb) INTO items FROM (
    SELECT s.* FROM public.bf_shipping_options s WHERE s.cafe_id=p_cafe_id AND s.deleted_at IS NULL AND strpos(lower(s.name),lower(search_text))>0 AND (state='all' OR s.active=(state='active'))
    ORDER BY CASE WHEN sort_name='name' AND sort_direction='asc' THEN s.name END ASC,CASE WHEN sort_name='name' AND sort_direction='desc' THEN s.name END DESC,
      CASE WHEN sort_name='fee' AND sort_direction='asc' THEN s.fee END ASC,CASE WHEN sort_name='fee' AND sort_direction='desc' THEN s.fee END DESC,
      CASE WHEN sort_name='active' AND sort_direction='asc' THEN s.active END ASC,CASE WHEN sort_name='active' AND sort_direction='desc' THEN s.active END DESC,
      CASE WHEN sort_name='displayOrder' AND sort_direction='asc' THEN s.display_order END ASC,CASE WHEN sort_name='displayOrder' AND sort_direction='desc' THEN s.display_order END DESC,s.name,s.id
    OFFSET (page_number-1)*30 LIMIT 30
  ) o;
  RETURN jsonb_build_object('items',items,'total',total,'page',page_number,'limit',30);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_shipping_settings(p_cafe_id uuid, p_action text DEFAULT 'get'::text, p_settings jsonb DEFAULT NULL::jsonb, p_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE current_settings jsonb;current_revision integer;service_id uuid;policies jsonb;services jsonb;accounts jsonb;names jsonb;
BEGIN
  PERFORM brand_finance_private.shipping_role(p_cafe_id,p_action='save');
  IF p_action IS NULL OR p_action NOT IN('get','save') THEN RAISE EXCEPTION 'Invalid shipping settings action' USING ERRCODE='22023';END IF;
  policies:=brand_finance_private.invoice_settings(p_cafe_id)#>'{advanced,productPolicies}';
  IF p_action='save' THEN
    IF p_revision IS NULL OR p_revision<0 OR jsonb_typeof(p_settings) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'راجع إعدادات الشحن' USING ERRCODE='22023';END IF;
    IF (SELECT count(*) FROM jsonb_object_keys(p_settings))<>2 OR NOT p_settings ?& ARRAY['enabled','codServiceId'] OR jsonb_typeof(p_settings->'enabled') IS DISTINCT FROM 'boolean'
      OR (p_settings->'codServiceId'<>'null'::jsonb AND (jsonb_typeof(p_settings->'codServiceId') IS DISTINCT FROM 'string' OR p_settings->>'codServiceId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'))
    THEN RAISE EXCEPTION 'راجع إعدادات الشحن وخدمة الدفع عند الاستلام' USING ERRCODE='22023';END IF;
    service_id:=(p_settings->>'codServiceId')::uuid;
    IF service_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.menu_products p WHERE p.cafe_id=p_cafe_id AND p.id=service_id AND p.available AND p.deleted_at IS NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(policies) x WHERE x->>'productId'=p.id::text AND x->>'kind'='service')) THEN RAISE EXCEPTION 'اختر منتج خدمة نشطًا من إعدادات الفواتير' USING ERRCODE='22023';END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60622));
  END IF;
  SELECT settings,revision INTO current_settings,current_revision FROM public.bf_shipping_settings WHERE cafe_id=p_cafe_id;
  current_settings:=coalesce(current_settings,'{"enabled":false,"codServiceId":null}'::jsonb);current_revision:=coalesce(current_revision,0);
  IF p_action='save' AND current_settings IS DISTINCT FROM p_settings THEN
    IF current_revision<>p_revision THEN RAISE EXCEPTION 'Shipping settings conflict' USING ERRCODE='40001';END IF;
    INSERT INTO public.bf_shipping_settings(cafe_id,settings,revision,updated_by) VALUES(p_cafe_id,p_settings,current_revision+1,auth.uid()) ON CONFLICT(cafe_id) DO UPDATE SET settings=excluded.settings,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=clock_timestamp();
    INSERT INTO public.bf_shipping_events(cafe_id,option_id,revision,action,before_value,after_value,created_by) VALUES(p_cafe_id,NULL,current_revision+1,CASE WHEN current_revision=0 THEN 'created' ELSE 'updated' END,current_settings,p_settings,auth.uid());
    current_settings:=p_settings;current_revision:=current_revision+1;
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.name) ORDER BY p.name,p.id),'[]'::jsonb) INTO services FROM public.menu_products p WHERE p.cafe_id=p_cafe_id AND p.available AND p.deleted_at IS NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(policies) x WHERE x->>'productId'=p.id::text AND x->>'kind'='service');
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'name',a.name,'code',a.code) ORDER BY a.code,a.id),'[]'::jsonb) INTO accounts FROM (SELECT id,name,code FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND active AND kind='revenue' ORDER BY code,id LIMIT 500) a;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'name',o.name) ORDER BY o.display_order,o.name,o.id),'[]'::jsonb) INTO names FROM public.bf_shipping_options o WHERE o.cafe_id=p_cafe_id AND o.deleted_at IS NULL;
  RETURN jsonb_build_object('settings',current_settings,'revision',current_revision,'services',services,'accounts',accounts,'optionNames',names);
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_supervise_shift(p_cafe_id uuid, p_shift_id uuid, p_action text, p_reason text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE sh public.bf_shifts%ROWTYPE; old public.bf_shift_supervision%ROWTYPE; body jsonb; result jsonb;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_supervise_shift',NULL);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 IF brand_finance_private.role_for(p_cafe_id) NOT IN('owner','manager') THEN RAISE EXCEPTION 'Finance manager required' USING ERRCODE='42501'; END IF;
 IF p_action IS NULL OR p_action NOT IN('pause','resume') OR p_request_id IS NULL OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'أدخل سبب الإجراء'; END IF;
 body:=jsonb_build_object('shiftId',p_shift_id,'action',p_action,'reason',btrim(p_reason));
 SELECT * INTO old FROM public.bf_shift_supervision WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF old.payload<>body OR old.actor_id<>auth.uid() THEN RAISE EXCEPTION 'Request identifier conflict'; END IF; RETURN old.result; END IF;
 SELECT * INTO sh FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND id=p_shift_id FOR UPDATE;
 IF NOT FOUND OR sh.status<>'open' THEN RAISE EXCEPTION 'الإجراء متاح للورديات المفتوحة فقط'; END IF;
 IF sh.supervisor_paused=(p_action='pause') THEN RAISE EXCEPTION 'حالة الوردية تغيرت حدث السجل'; END IF;
 UPDATE public.bf_shifts SET supervisor_paused=(p_action='pause') WHERE id=sh.id;
 result:=jsonb_build_object('id',sh.id);
 INSERT INTO public.bf_shift_supervision(cafe_id,shift_id,action,reason,actor_id,actor_name,request_id,payload,result) VALUES(p_cafe_id,sh.id,p_action,btrim(p_reason),auth.uid(),brand_finance_private.cash_employee_name(p_cafe_id,auth.uid()),p_request_id,body,result);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_terminal_fee_history(p_cafe_id uuid, p_account_id uuid DEFAULT NULL::uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text; answer jsonb;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_terminal_fee_history',NULL);
 r:=brand_finance_private.role_for(p_cafe_id);
 IF r NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Finance manager required' USING ERRCODE='42501'; END IF;
 IF p_offset IS NULL OR p_offset<0 OR (p_account_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=p_account_id AND kind IN('bank','pos'))) THEN RAISE EXCEPTION 'اختر حسابا بنكيا أو نقطة شبكة لعرض سجل الرسوم'; END IF;
 WITH filtered AS (
  SELECT c.*,s.number source_number,brand_finance_private.terminal_fee_paid(p_cafe_id,c.id) paid,c.total-brand_finance_private.terminal_fee_paid(p_cafe_id,c.id) remaining
  FROM public.bf_terminal_fee_charges c LEFT JOIN public.bf_documents s ON s.cafe_id=c.cafe_id AND s.id=c.source_document_id
  WHERE c.cafe_id=p_cafe_id AND (p_account_id IS NULL OR c.terminal_id=p_account_id OR c.bank_id=p_account_id)
 ), page AS(SELECT * FROM filtered ORDER BY created_at DESC,id DESC OFFSET p_offset LIMIT 100)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM filtered),'rows',coalesce((SELECT jsonb_agg(to_jsonb(p)-'cafe_id' ORDER BY p.created_at DESC,p.id DESC) FROM page p),'[]'::jsonb)) INTO answer;
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_transition_credit_note(p_cafe_id uuid, p_id uuid, p_revision integer, p_operation text, p_request_id uuid, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE n public.bf_credit_notes%ROWTYPE;role_name text;request public.bf_requests%ROWTYPE;command jsonb;answer jsonb;v jsonb;e jsonb;d uuid:=gen_random_uuid();aid uuid;cost numeric:=0;source public.bf_documents%ROWTYPE;credited numeric;refunded numeric;closed_date date;product_line record;sold numeric;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);
 IF auth.uid() IS NULL OR p_operation IS NULL OR p_operation NOT IN('issue','receive','reject','delete') OR p_request_id IS NULL OR p_id IS NULL OR p_revision IS NULL OR p_revision<1 OR p_note IS NULL OR length(p_note)>500 THEN RAISE EXCEPTION 'Invalid credit-note operation';END IF;
 IF (p_operation IN('receive','reject') AND coalesce(role_name,'') NOT IN('owner','manager','warehouse')) OR (p_operation IN('issue','delete') AND coalesce(role_name,'') NOT IN('owner','manager','accountant')) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 command:=jsonb_build_object('id',p_id,'revision',p_revision,'operation',p_operation,'note',p_note);
 SELECT * INTO request FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN
  IF request.operation<>'credit_note' OR request.payload<>command OR request.created_by<>auth.uid() THEN RAISE EXCEPTION 'Request identity conflict';END IF;
  RETURN request.result;
 END IF;
 SELECT * INTO n FROM public.bf_credit_notes WHERE cafe_id=p_cafe_id AND id=p_id FOR UPDATE;
 IF NOT FOUND OR n.status='deleted' THEN RAISE EXCEPTION 'الإشعار غير متاح';END IF;
 IF n.revision<>p_revision THEN RAISE EXCEPTION 'تغير الإشعار افتح النسخة المحفوظة' USING ERRCODE='40001';END IF;
 IF p_operation='delete' THEN
  IF n.status<>'draft' THEN RAISE EXCEPTION 'لا يمكن حذف إشعار صدر أثره المالي';END IF;
  UPDATE public.bf_credit_notes SET status='deleted',revision=revision+1,updated_at=clock_timestamp() WHERE id=p_id RETURNING * INTO n;
 ELSIF p_operation='issue' THEN
  IF n.status<>'draft' THEN RAISE EXCEPTION 'سبق إصدار الإشعار';END IF;
  v:=brand_finance_private.credit_note_validate(p_cafe_id,n.payload,true);
  SELECT closed_through INTO closed_date FROM public.bf_settings WHERE cafe_id=p_cafe_id;
  IF closed_date IS NOT NULL AND (least((n.payload->>'date')::date,(n.payload->>'issueDate')::date)<=closed_date OR (now() AT TIME ZONE 'Asia/Riyadh')::date<=closed_date) THEN RAISE EXCEPTION 'الفترة المحاسبية مقفلة';END IF;
  IF n.source_invoice_id IS NOT NULL THEN
   SELECT * INTO source FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=n.source_invoice_id FOR UPDATE;
   SELECT coalesce(sum(total),0) INTO credited FROM public.bf_credit_notes WHERE cafe_id=p_cafe_id AND source_invoice_id=n.source_invoice_id AND status='issued';
   SELECT coalesce(sum(total),0) INTO refunded FROM public.bf_documents WHERE cafe_id=p_cafe_id AND reference_id=n.source_invoice_id AND kind='refund';
   IF (v->>'total')::numeric+credited+refunded>source.total THEN RAISE EXCEPTION 'قيمة الإشعار تتجاوز المتبقي بعد المرتجعات والإشعارات السابقة';END IF;
   IF (n.payload->>'stockRequired')::boolean THEN
    FOR product_line IN SELECT x->>'productId' product_id,sum((x->>'quantity')::numeric) quantity FROM jsonb_array_elements(v->'lines') x GROUP BY x->>'productId' LOOP
     SELECT coalesce(sum(quantity),0) INTO sold FROM public.bf_document_lines WHERE cafe_id=p_cafe_id AND document_id=source.id AND product_id::text=product_line.product_id;
     SELECT coalesce(sum(l.quantity),0) INTO refunded FROM public.bf_document_lines l JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=l.document_id WHERE d.cafe_id=p_cafe_id AND d.reference_id=source.id AND d.kind='refund' AND l.product_id::text=product_line.product_id;
     SELECT coalesce(sum((x->>'quantity')::numeric),0) INTO credited FROM public.bf_credit_notes c CROSS JOIN LATERAL jsonb_array_elements(c.lines) x WHERE c.cafe_id=p_cafe_id AND c.source_invoice_id=source.id AND c.status='issued' AND (c.payload->>'stockRequired')::boolean AND x->>'productId'=product_line.product_id;
     IF credited+refunded+product_line.quantity>sold THEN RAISE EXCEPTION 'كمية الإشعار تتجاوز الكمية المتبقية من الفاتورة';END IF;
    END LOOP;
   END IF;
  END IF;
  aid:=brand_finance_private.customer_credit_account(p_cafe_id);
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,subtotal,discount,tax,total,note,created_by) VALUES(d,p_cafe_id,'journal',n.party_id,(v->>'subtotal')::numeric,(v->>'discount')::numeric,(v->>'tax')::numeric,(v->>'total')::numeric,left('إشعار دائن '||n.number||' - '||(n.payload->>'reason'),1000),auth.uid());
  PERFORM brand_finance_private.invoice_line(p_cafe_id,d,CASE WHEN EXISTS(SELECT 1 FROM public.erp_contracting_advance_invoices WHERE cafe_id=p_cafe_id AND invoice_id=n.source_invoice_id) THEN aid ELSE brand_finance_private.account(p_cafe_id,'4000') END,(v->>'total')::numeric-(v->>'tax')::numeric,0,n.party_id,'إشعار دائن');
  PERFORM brand_finance_private.invoice_line(p_cafe_id,d,brand_finance_private.account(p_cafe_id,'2100'),(v->>'tax')::numeric,0,n.party_id,'ضريبة الإشعار الدائن');
  PERFORM brand_finance_private.invoice_line(p_cafe_id,d,aid,0,(v->>'total')::numeric,n.party_id,'رصيد إشعار دائن');
  INSERT INTO public.bf_customer_credit_events(cafe_id,party_id,document_id,invoice_id,action,amount,delta,created_by) VALUES(p_cafe_id,n.party_id,d,n.source_invoice_id,'credit_note',(v->>'total')::numeric,(v->>'total')::numeric,auth.uid()); PERFORM erp_settings_private.advance_credit_settle(p_cafe_id,n.source_invoice_id,n.id,(v->>'total')::numeric);
  UPDATE public.bf_credit_notes SET status='issued',stock_status=CASE WHEN (payload->>'stockRequired')::boolean THEN 'pending' ELSE 'none' END,journal_id=d,issued_at=clock_timestamp(),updated_at=clock_timestamp(),revision=revision+1,lines=v->'lines',subtotal=(v->>'subtotal')::numeric,discount=(v->>'discount')::numeric,tax=(v->>'tax')::numeric,total=(v->>'total')::numeric WHERE id=p_id RETURNING * INTO n;
 ELSE
  IF n.status<>'issued' OR n.stock_status<>'pending' THEN RAISE EXCEPTION 'الإذن المخزني ليس بانتظار الاستلام';END IF;
  IF p_operation='reject' THEN
   IF length(trim(p_note))=0 THEN RAISE EXCEPTION 'حدد سبب رفض الاستلام';END IF;
   UPDATE public.bf_credit_notes SET stock_status='rejected',revision=revision+1,updated_at=clock_timestamp() WHERE id=p_id RETURNING * INTO n;
  ELSE
   SELECT closed_through INTO closed_date FROM public.bf_settings WHERE cafe_id=p_cafe_id;
   IF closed_date IS NOT NULL AND (now() AT TIME ZONE 'Asia/Riyadh')::date<=closed_date THEN RAISE EXCEPTION 'الفترة المحاسبية مقفلة';END IF;
   IF NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id=n.warehouse_id AND active) THEN RAISE EXCEPTION 'المستودع غير متاح';END IF;
   INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,warehouse_id,note,created_by) VALUES(d,p_cafe_id,'stock_adjust',n.party_id,n.warehouse_id,'استلام أصناف إشعار دائن '||n.number,auth.uid());
   FOR e IN SELECT component.value FROM jsonb_array_elements(n.lines) line CROSS JOIN LATERAL jsonb_array_elements(line->'components') component LOOP
    IF e->>'itemId' IS NOT NULL THEN
     IF NOT EXISTS(SELECT 1 FROM public.bf_items WHERE cafe_id=p_cafe_id AND id=(e->>'itemId')::uuid AND active) THEN RAISE EXCEPTION 'أحد الأصناف المخزنية غير نشط';END IF;
     cost:=cost+brand_finance_private.stock_move(p_cafe_id,d,(e->>'itemId')::uuid,n.warehouse_id,(e->>'quantity')::numeric,(e->>'unitCost')::numeric);
    END IF;
   END LOOP;
   PERFORM brand_finance_private.invoice_line(p_cafe_id,d,brand_finance_private.account(p_cafe_id,'1200'),cost,0,n.party_id,'استلام أصناف إشعار دائن');
   PERFORM brand_finance_private.invoice_line(p_cafe_id,d,brand_finance_private.account(p_cafe_id,'5000'),0,cost,n.party_id,'عكس تكلفة أصناف مستلمة');
   UPDATE public.bf_credit_notes SET stock_status='received',stock_document_id=d,revision=revision+1,updated_at=clock_timestamp() WHERE id=p_id RETURNING * INTO n;
  END IF;
 END IF;
 INSERT INTO public.bf_credit_note_events(cafe_id,note_id,action,actor_id,actor_name,note) VALUES(p_cafe_id,p_id,p_operation,auth.uid(),brand_finance_private.credit_note_actor(p_cafe_id),p_note);
 answer:=brand_finance_private.credit_note_record(n);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'credit_note',command,answer,auth.uid());
 RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_transition_recurring_invoice(p_cafe_id uuid, p_id uuid, p_revision integer, p_operation text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.bf_recurring_invoices%ROWTYPE;prior public.bf_requests%ROWTYPE;role_name text;command jsonb;answer jsonb;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF p_id IS NULL OR p_request_id IS NULL OR p_revision IS NULL OR p_revision<1 OR p_operation IS NULL OR p_operation NOT IN('pause','resume','delete','run') THEN RAISE EXCEPTION 'Invalid operation';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));command:=jsonb_build_object('id',p_id,'revision',p_revision,'operation',p_operation);
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF prior.operation<>'recurring_invoice' OR prior.payload<>command OR prior.created_by<>auth.uid() THEN RAISE EXCEPTION 'Request identity conflict';END IF;RETURN prior.result;END IF;
 SELECT * INTO r FROM public.bf_recurring_invoices WHERE cafe_id=p_cafe_id AND id=p_id AND status<>'deleted' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'الاشتراك غير متاح';END IF;IF r.revision<>p_revision THEN RAISE EXCEPTION 'Subscription conflict' USING ERRCODE='40001';END IF;
 IF p_operation='delete' AND r.generated_count>0 THEN RAISE EXCEPTION 'الاشتراك أصدر فواتير ويمكن إيقافه فقط';END IF;
 IF p_operation IN('resume','pause') AND r.status='completed' THEN RAISE EXCEPTION 'اكتمل عدد الفواتير المحدد';END IF;
 IF p_operation='run' THEN answer:=brand_finance_private.recurring_run_one(p_id);
 ELSE
 UPDATE public.bf_recurring_invoices SET status=CASE p_operation WHEN 'pause' THEN 'paused' WHEN 'resume' THEN 'active' ELSE 'deleted' END,payload=jsonb_set(payload,'{active}',to_jsonb(p_operation='resume')),actor_id=CASE WHEN p_operation='resume' THEN auth.uid() ELSE actor_id END,revision=revision+1,updated_at=clock_timestamp(),next_attempt_at=now() WHERE id=p_id;
 INSERT INTO public.bf_recurring_events(cafe_id,subscription_id,actor_id,action) VALUES(p_cafe_id,p_id,auth.uid(),p_operation);
 answer:=jsonb_build_object('status',CASE p_operation WHEN 'pause' THEN 'paused' WHEN 'resume' THEN 'active' ELSE 'deleted' END);
 END IF;
 IF p_operation<>'run' OR answer->>'status'='issued' THEN INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'recurring_invoice',command,answer,auth.uid());END IF;RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_treasury_attachment(p_cafe_id uuid, p_document_id uuid, p_action text DEFAULT 'list'::text, p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_size bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.bf_treasury_attachments; obj jsonb; result jsonb; r text;
BEGIN
 PERFORM brand_finance_private.assert_job_access(p_cafe_id,'brand_finance_treasury_attachment',p_action);
 r := brand_finance_private.role_for(p_cafe_id);
 IF r NOT IN ('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Treasury management required' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=p_document_id
   AND kind IN ('receipt','expense','transfer','opening','journal'))
 THEN RAISE EXCEPTION 'Treasury document unavailable' USING ERRCODE='42501'; END IF;
 IF p_action='list' THEN
   SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.created_at),'[]'::jsonb) INTO result
   FROM public.bf_treasury_attachments t WHERE cafe_id=p_cafe_id AND document_id=p_document_id AND uploaded;
   RETURN result;
 END IF;
 IF p_action='stale' THEN
   WITH expired AS (
     UPDATE public.bf_treasury_attachments SET abandoned=true
     WHERE cafe_id=p_cafe_id AND document_id=p_document_id AND NOT uploaded AND expires_at<now()
     RETURNING *
   ) SELECT coalesce(jsonb_agg(to_jsonb(expired)),'[]'::jsonb) INTO result FROM expired;
   RETURN result;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_document_id::text,78021));
 SELECT * INTO a FROM public.bf_treasury_attachments WHERE id=p_id FOR UPDATE;
 IF a.id IS NOT NULL AND (a.cafe_id<>p_cafe_id OR a.document_id<>p_document_id)
 THEN RAISE EXCEPTION 'Attachment unavailable' USING ERRCODE='42501'; END IF;
 IF p_action='prepare' THEN
   IF p_id IS NULL OR p_name IS NULL OR length(trim(p_name)) NOT BETWEEN 1 AND 180
      OR p_name ~ '[[:cntrl:]/\\]' OR p_size IS NULL OR p_size < 1
   THEN RAISE EXCEPTION 'Invalid attachment'; END IF;
   IF a.id IS NOT NULL THEN
     IF a.abandoned OR a.uploader_id<>auth.uid() OR a.original_name<>trim(p_name) OR a.size_bytes<>p_size
     THEN RAISE EXCEPTION 'Attachment request mismatch' USING ERRCODE='42501'; END IF;
     IF NOT a.uploaded THEN UPDATE public.bf_treasury_attachments SET expires_at=now()+interval '3 hours' WHERE id=a.id RETURNING * INTO a; END IF;
     RETURN to_jsonb(a);
   END IF;
   INSERT INTO public.bf_treasury_attachments(id,cafe_id,document_id,uploader_id,storage_path,original_name,size_bytes)
   VALUES(p_id,p_cafe_id,p_document_id,auth.uid(),p_cafe_id::text||'/'||p_document_id::text||'/'||p_id::text,trim(p_name),p_size)
   RETURNING * INTO a;
   RETURN to_jsonb(a);
 END IF;
 IF a.id IS NULL THEN RAISE EXCEPTION 'Attachment unavailable' USING ERRCODE='42501'; END IF;
 IF p_action='get' AND a.uploaded THEN RETURN to_jsonb(a); END IF;
 IF p_action='finalize' THEN
   IF a.abandoned OR a.uploader_id<>auth.uid() THEN RAISE EXCEPTION 'Own attachment required' USING ERRCODE='42501'; END IF;
   IF a.uploaded THEN RETURN to_jsonb(a); END IF;
   SELECT metadata INTO obj FROM storage.objects WHERE bucket_id='branda-finance-treasury-files' AND name=a.storage_path;
   IF obj IS NULL OR (obj->>'size')::bigint IS DISTINCT FROM a.size_bytes
   THEN RAISE EXCEPTION 'Uploaded object size mismatch'; END IF;
   UPDATE public.bf_treasury_attachments SET uploaded=true WHERE id=a.id RETURNING * INTO a;
   RETURN to_jsonb(a);
 END IF;
 IF p_action='purge' AND a.abandoned AND NOT a.uploaded AND a.expires_at<now() THEN
   -- Storage API must delete bytes first; never remove metadata-only storage rows
   IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='branda-finance-treasury-files' AND name=a.storage_path)
   THEN RAISE EXCEPTION 'Storage object still exists'; END IF;
   DELETE FROM public.bf_treasury_attachments WHERE id=a.id;
   RETURN jsonb_build_object('purged',true);
 END IF;
 RAISE EXCEPTION 'Attachment action denied' USING ERRCODE='42501';
END $function$

CREATE OR REPLACE FUNCTION public.brand_finance_treasury_correct(p_cafe_id uuid, p_actor_id uuid, p_maintenance_expires_at timestamp with time zone, p_operation text, p_payload jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE audit_record record; prior public.bf_requests%ROWTYPE; original public.bf_documents%ROWTYPE; recon public.bf_treasury_reconciliations%ROWTYPE;
 a public.bf_accounts%ROWTYPE; line record; doc uuid:=gen_random_uuid(); n bigint; aid uuid; amount numeric; balance numeric; reason text; result jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_actor_id AND role='platform_admin' AND status='active') OR NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe_id AND deleted_at IS NULL AND status IN('active','published')) OR NOT platform_access_private.service_enabled(p_cafe_id,'finance') THEN RAISE EXCEPTION 'Maintenance administrator required' USING ERRCODE='42501'; END IF;
 SELECT action,new_data INTO audit_record FROM public.audit_logs WHERE actor_id=p_actor_id AND cafe_id=p_cafe_id AND action IN('maintenance_mode_started','maintenance_mode_ended') ORDER BY created_at DESC,id DESC LIMIT 1;
 IF NOT FOUND OR audit_record.action<>'maintenance_mode_started' OR p_maintenance_expires_at IS NULL OR p_maintenance_expires_at<=now() OR (audit_record.new_data->>'expires_at')::timestamptz IS DISTINCT FROM p_maintenance_expires_at THEN RAISE EXCEPTION 'Active matching maintenance session required' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>100000 OR p_payload::text ~* '"[-+]?(nan|infinity)"' THEN RAISE EXCEPTION 'Invalid command'; END IF;
 reason:=btrim(coalesce(p_payload->>'reason',''));
 IF length(reason) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'سبب التصحيح مطلوب'; END IF;
 SELECT * INTO prior FROM public.bf_requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN
  IF prior.operation<>'treasury_correct:'||p_operation OR prior.payload<>p_payload OR prior.created_by<>p_actor_id THEN RAISE EXCEPTION 'Request identifier conflict'; END IF;
  RETURN prior.result||'{"duplicate":true}'::jsonb;
 END IF;
 IF EXISTS(SELECT 1 FROM public.bf_settings WHERE cafe_id=p_cafe_id AND closed_through>=(now() AT TIME ZONE 'Asia/Riyadh')::date) THEN RAISE EXCEPTION 'الفترة المالية مقفلة'; END IF;

 IF p_operation IN('reset','reconcile_adjust') AND EXISTS(SELECT 1 FROM public.bf_shift_cash_variances v WHERE v.cafe_id=p_cafe_id AND NOT EXISTS(SELECT 1 FROM public.bf_shift_cash_resolutions r WHERE r.variance_id=v.id)) THEN RAISE EXCEPTION 'سو فروقات الورديات المعلقة قبل تصحيح الأرصدة'; END IF;
 IF p_operation='reverse' AND (EXISTS(SELECT 1 FROM public.bf_shift_cash_variances WHERE cafe_id=p_cafe_id AND document_id=(p_payload->>'documentId')::uuid) OR EXISTS(SELECT 1 FROM public.bf_shift_cash_resolutions WHERE cafe_id=p_cafe_id AND document_id=(p_payload->>'documentId')::uuid)) THEN RAISE EXCEPTION 'قيود فروقات الورديات لا تعكس من التصحيح العام'; END IF;

 IF p_operation IN('reset','reconcile_adjust') AND EXISTS(SELECT 1 FROM public.bf_cash_handovers h WHERE h.cafe_id=p_cafe_id AND NOT EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts r WHERE r.handover_id=h.id)) THEN RAISE EXCEPTION 'استلم تسليمات النقدية المعلقة قبل تصحيح الأرصدة'; END IF;
 IF p_operation='reverse' AND (EXISTS(SELECT 1 FROM public.bf_cash_handovers WHERE cafe_id=p_cafe_id AND document_id=(p_payload->>'documentId')::uuid) OR EXISTS(SELECT 1 FROM public.bf_cash_handover_receipts WHERE cafe_id=p_cafe_id AND document_id=(p_payload->>'documentId')::uuid)) THEN RAISE EXCEPTION 'قيود تسليم واستلام الورديات لا تعكس من التصحيح العام'; END IF;
 IF p_operation='reverse' THEN
  SELECT d.* INTO original FROM public.bf_documents d JOIN public.bf_treasury_documents t ON t.cafe_id=d.cafe_id AND t.document_id=d.id
  WHERE d.cafe_id=p_cafe_id AND d.id=(p_payload->>'documentId')::uuid AND t.operation IN('opening','voucher','transfer','pos_settle','pos_fee_pay');
  IF NOT FOUND OR EXISTS(SELECT 1 FROM public.bf_treasury_documents WHERE cafe_id=p_cafe_id AND reverses_id=original.id) THEN RAISE EXCEPTION 'المستند غير قابل للعكس أو سبق عكسه'; END IF;
  IF EXISTS(SELECT 1 FROM public.bf_terminal_fee_allocations paid JOIN public.bf_terminal_fee_charges charge ON charge.id=paid.charge_id JOIN public.bf_accounts terminal ON terminal.id=charge.terminal_id WHERE paid.cafe_id=p_cafe_id AND paid.document_id=original.id AND terminal.linked_bank_id IS DISTINCT FROM charge.bank_id) THEN RAISE EXCEPTION 'أعد ربط الشبكة بالبنك الأصلي قبل عكس سداد الرسوم'; END IF;
  IF EXISTS(SELECT 1 FROM public.bf_journal j JOIN public.bf_accounts acc ON acc.cafe_id=j.cafe_id AND acc.id=j.account_id WHERE j.cafe_id=p_cafe_id AND j.document_id=original.id AND NOT acc.active) THEN RAISE EXCEPTION 'أعد تفعيل الحساب المؤرشف قبل عكس مستنده'; END IF;
  IF EXISTS(SELECT 1 FROM public.bf_journal j JOIN public.bf_shifts s ON s.cafe_id=j.cafe_id AND s.account_id=j.account_id WHERE j.cafe_id=p_cafe_id AND j.document_id=original.id AND s.status IN('open','handover')) THEN RAISE EXCEPTION 'أغلق الوردية قبل تصحيح حسابها'; END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,account_id,total,reference_id,note,created_by) VALUES(doc,p_cafe_id,'journal',original.account_id,original.total,original.id,reason,p_actor_id) RETURNING number INTO n;
  FOR line IN SELECT * FROM public.bf_journal WHERE cafe_id=p_cafe_id AND document_id=original.id LOOP
   PERFORM brand_finance_private.line(p_cafe_id,doc,line.account_id,line.credit,line.debit,line.party_id);
  END LOOP;
  INSERT INTO public.bf_treasury_documents(cafe_id,document_id,operation,reverses_id) VALUES(p_cafe_id,doc,'reverse',original.id);
 ELSE
  IF p_operation='reconcile_adjust' THEN
   SELECT * INTO recon FROM public.bf_treasury_reconciliations WHERE cafe_id=p_cafe_id AND id=(p_payload->>'reconciliationId')::uuid;
   IF NOT FOUND OR recon.difference=0 OR EXISTS(SELECT 1 FROM public.bf_treasury_reconciliation_resolutions WHERE cafe_id=p_cafe_id AND reconciliation_id=recon.id) THEN RAISE EXCEPTION 'المطابقة غير قابلة للتسوية'; END IF;
   aid:=recon.account_id; amount:=recon.difference;
   IF brand_finance_private.treasury_balance(p_cafe_id,aid)<>recon.expected_amount THEN RAISE EXCEPTION 'تغير الرصيد سجل مطابقة جديدة قبل التسوية'; END IF;
  ELSIF p_operation='reset' THEN
   aid:=nullif(p_payload->>'accountId','')::uuid; balance:=brand_finance_private.treasury_balance(p_cafe_id,aid);
   IF balance IS DISTINCT FROM (p_payload->>'expectedBalance')::numeric THEN RAISE EXCEPTION 'تغير الرصيد حدث البيانات قبل التصحيح'; END IF;
   amount:=-balance;
  ELSE RAISE EXCEPTION 'Unknown treasury correction'; END IF;
  SELECT * INTO a FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=aid AND kind IN('cash','bank','pos') AND active;
  IF NOT FOUND OR amount IS NULL OR amount=0 THEN RAISE EXCEPTION 'Invalid correction account or amount'; END IF;
  IF EXISTS(SELECT 1 FROM public.bf_shifts WHERE cafe_id=p_cafe_id AND account_id=aid AND status IN('open','handover')) THEN RAISE EXCEPTION 'أغلق الوردية قبل تصحيح حسابها'; END IF;
  INSERT INTO public.bf_documents(id,cafe_id,kind,account_id,total,note,created_by) VALUES(doc,p_cafe_id,'journal',aid,abs(amount),reason,p_actor_id) RETURNING number INTO n;
  PERFORM brand_finance_private.line(p_cafe_id,doc,aid,greatest(amount,0),greatest(-amount,0));
  PERFORM brand_finance_private.line(p_cafe_id,doc,brand_finance_private.account(p_cafe_id,CASE WHEN p_operation='reset' THEN '3000' ELSE '5300' END),greatest(-amount,0),greatest(amount,0));
  INSERT INTO public.bf_treasury_documents(cafe_id,document_id,operation) VALUES(p_cafe_id,doc,p_operation);
  IF p_operation='reconcile_adjust' THEN INSERT INTO public.bf_treasury_reconciliation_resolutions(cafe_id,reconciliation_id,document_id) VALUES(p_cafe_id,recon.id,doc); END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM public.bf_accounts acc JOIN public.bf_journal j ON j.cafe_id=acc.cafe_id AND j.account_id=acc.id WHERE acc.cafe_id=p_cafe_id AND acc.kind IN('cash','bank','pos') AND acc.id IN(SELECT account_id FROM public.bf_journal WHERE cafe_id=p_cafe_id AND document_id=doc) GROUP BY acc.id HAVING sum(j.debit-j.credit)<0) THEN RAISE EXCEPTION 'التصحيح يؤدي إلى رصيد سالب'; END IF;
 result:=jsonb_build_object('id',doc,'number',n);
 INSERT INTO public.bf_treasury_audit(cafe_id,actor_id,operation,entity_id,after_data) VALUES(p_cafe_id,p_actor_id,p_operation,doc,p_payload||result);
 INSERT INTO public.bf_requests(cafe_id,request_id,operation,payload,result,created_by) VALUES(p_cafe_id,p_request_id,'treasury_correct:'||p_operation,p_payload,result,p_actor_id);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_attendance_import(p_cafe uuid, p_kind text, p_rows jsonb, p_request uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE prior erp_attendance_private.requests;req jsonb:=jsonb_build_object('import',p_kind,'rows',p_rows);row jsonb;result jsonb;ids jsonb:='[]';op text;BEGIN
 PERFORM erp_attendance_private.authorize(p_cafe,true);PERFORM erp_attendance_private.access(p_cafe,'create');PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 IF p_request IS NULL OR coalesce(jsonb_typeof(p_rows),'')<>'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 500 OR octet_length(p_rows::text)>1000000 OR p_kind NOT IN('logs','days','allocations') THEN RAISE EXCEPTION 'اختر من صف واحد إلى خمسمئة صف للاستيراد';END IF;
 SELECT * INTO prior FROM erp_attendance_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.payload<>req OR prior.actor<>auth.uid() THEN RAISE EXCEPTION 'تعارض معرف طلب الاستيراد';END IF;RETURN prior.result;END IF;
 op:=CASE p_kind WHEN 'logs' THEN 'save_log' WHEN 'days' THEN 'manual_day' ELSE 'save_allocation' END;
 FOR row IN SELECT * FROM jsonb_array_elements(p_rows) LOOP result:=public.erp_attendance_write(p_cafe,op,jsonb_build_object('payload',row,'revision',coalesce((row->>'revision')::integer,0)),gen_random_uuid());IF p_kind='logs' THEN UPDATE public.erp_att_logs SET source='import' WHERE cafe_id=p_cafe AND id=(result->>'id')::uuid;END IF;ids:=ids||jsonb_build_array(result->>'id');END LOOP;
 result:=jsonb_build_object('ids',ids,'count',jsonb_array_length(ids));INSERT INTO erp_attendance_private.requests VALUES(p_cafe,p_request,req,result,auth.uid());RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_attendance_issue_proof(p_cafe uuid, p_actor uuid, p_session uuid, p_ip text DEFAULT NULL::text, p_request uuid DEFAULT gen_random_uuid())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE rid uuid;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 SELECT id INTO rid FROM erp_attendance_private.proofs WHERE cafe_id=p_cafe AND actor=p_actor AND request_id=p_request AND session_id=p_session;IF FOUND THEN RETURN rid;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.erp_att_sessions s JOIN public.erp_hr_employees e ON e.cafe_id=s.cafe_id AND e.id=s.employee_id JOIN public.profiles p ON p.id=e.user_id WHERE s.cafe_id=p_cafe AND s.id=p_session AND s.status IN('draft','open') AND e.active AND e.user_id=p_actor AND p.status='active') THEN RAISE EXCEPTION 'جلسة التوقيع لا تخص الموظف النشط' USING ERRCODE='42501';END IF;
 DELETE FROM erp_attendance_private.proofs WHERE expires_at<now()-interval '1 day';INSERT INTO erp_attendance_private.proofs(cafe_id,actor,session_id,ip,request_id) VALUES(p_cafe,p_actor,p_session,nullif(p_ip,'')::inet,p_request) RETURNING id INTO rid;RETURN rid;
END $function$

CREATE OR REPLACE FUNCTION public.erp_attendance_read(p_cafe uuid, p_module text DEFAULT 'logs'::text, p_query jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE role text;own uuid;tbl text;records jsonb:='[]';total bigint:=0;settings jsonb;employees jsonb;rid uuid:=nullif(p_query->>'id','')::uuid;employee_filter uuid:=nullif(p_query->>'employeeId','')::uuid;type_filter uuid:=nullif(p_query->>'leaveTypeId','')::uuid;page integer:=least(greatest(coalesce((p_query->>'page')::integer,1),1),100000);start_date date:=nullif(p_query->>'from','')::date;end_date date:=nullif(p_query->>'to','')::date;condition text;query text:=left(coalesce(p_query->>'q',''),150);v_status text:=coalesce(p_query->>'status','');events jsonb:='[]';result jsonb;BEGIN
 role:=erp_attendance_private.authorize(p_cafe);PERFORM erp_attendance_private.access(p_cafe,'read');settings:=erp_attendance_private.settings(p_cafe);SELECT id INTO own FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND user_id=auth.uid() AND active;
 IF role='self' AND p_module NOT IN('logs','days','leaves','sessions','balances','schedule','assignments') THEN RAISE EXCEPTION 'هذا القسم متاح لإدارة الحضور' USING ERRCODE='42501';END IF;
 tbl:=CASE p_module WHEN 'logs' THEN 'erp_att_logs' WHEN 'days' THEN 'erp_att_days' WHEN 'sheets' THEN 'erp_att_sheets' WHEN 'permissions' THEN 'erp_att_leaves' WHEN 'leaves' THEN 'erp_att_leaves' WHEN 'shifts' THEN 'erp_att_shifts' WHEN 'allocations' THEN 'erp_att_allocations' WHEN 'sessions' THEN 'erp_att_sessions' WHEN 'policies' THEN 'erp_att_policies' WHEN 'leave-types' THEN 'erp_att_leave_types' WHEN 'flags' THEN 'erp_att_flags' WHEN 'restrictions' THEN 'erp_att_restrictions' WHEN 'approvals' THEN 'erp_att_approvals' WHEN 'devices' THEN 'erp_att_devices' WHEN 'assignments' THEN 'erp_att_assignments' WHEN 'settlements' THEN 'erp_att_settlements' END;
 IF tbl IS NOT NULL THEN
  condition:='t.cafe_id=$1 AND ($2::uuid IS NULL OR t.id=$2) AND ($3='''' OR coalesce(to_jsonb(t)->>''name'','''') ILIKE ''%''||$3||''%'' OR coalesce(to_jsonb(t)->>''note'','''') ILIKE ''%''||$3||''%'') AND ($4='''' OR coalesce(to_jsonb(t)->>''status'',CASE WHEN (to_jsonb(t)->>''voided'')::boolean THEN ''void'' WHEN to_jsonb(t)?''voided'' THEN ''active'' WHEN (to_jsonb(t)->>''active'')::boolean THEN ''active'' ELSE ''inactive'' END)=$4)';
  IF p_module IN('logs','days','permissions','leaves','sessions','assignments','settlements') THEN condition:=condition||' AND ($5::uuid IS NULL OR t.employee_id=$5)';IF role='self' THEN IF p_module='leaves' THEN condition:=condition||' AND (t.employee_id=$6 OR t.approval_snapshot @> jsonb_build_array(jsonb_build_object(''users'',jsonb_build_array(auth.uid()::text))))';ELSE condition:=condition||' AND t.employee_id=$6';END IF;END IF;END IF;
  IF p_module='permissions' THEN condition:=condition||' AND t.kind=''permission''';ELSIF p_module='leaves' THEN condition:=condition||' AND t.kind=''application''';END IF;
  IF p_module='assignments' THEN condition:=condition||' AND ($7::date IS NULL OR coalesce(t.effective_to,''infinity'')>=$7) AND ($8::date IS NULL OR t.effective_from<=$8)';ELSIF p_module='days' THEN condition:=condition||' AND ($7::date IS NULL OR t.work_date>=$7) AND ($8::date IS NULL OR t.work_date<=$8)';ELSIF p_module='logs' THEN condition:=condition||' AND ($7::date IS NULL OR (t.occurred_at AT TIME ZONE $9)>=$7::timestamp) AND ($8::date IS NULL OR (t.occurred_at AT TIME ZONE $9)<($8+1)::timestamp)';ELSIF p_module IN('sheets','permissions','leaves','allocations') THEN condition:=condition||' AND ($7::date IS NULL OR t.to_date>=$7) AND ($8::date IS NULL OR t.from_date<=$8)';END IF;
  EXECUTE format('SELECT count(*) FROM public.%I t WHERE %s',tbl,condition) INTO total USING p_cafe,rid,query,v_status,employee_filter,own,start_date,end_date,settings->>'timezone';
  EXECUTE format('SELECT coalesce(jsonb_agg(v),''[]'') FROM(SELECT to_jsonb(t)||jsonb_build_object(''check_in_at'',(SELECT occurred_at FROM public.erp_att_logs l WHERE l.cafe_id=t.cafe_id AND l.id=(CASE WHEN to_jsonb(t)?''proof'' THEN nullif(to_jsonb(t)->>''check_in'','''')::uuid END)),''check_out_at'',(SELECT occurred_at FROM public.erp_att_logs l WHERE l.cafe_id=t.cafe_id AND l.id=(CASE WHEN to_jsonb(t)?''proof'' THEN nullif(to_jsonb(t)->>''check_out'','''')::uuid END)),''employee_name'',(SELECT concat_ws('' '',e.first_name,e.last_name) FROM public.erp_hr_employees e WHERE e.cafe_id=t.cafe_id AND e.id=nullif(to_jsonb(t)->>''employee_id'','''')::uuid)) v FROM public.%I t WHERE %s ORDER BY coalesce(to_jsonb(t)->>''created_at'',to_jsonb(t)->>''work_date'',to_jsonb(t)->>''effective_from'',to_jsonb(t)->>''name'') DESC,t.id LIMIT 50 OFFSET $10)x',tbl,condition) INTO records USING p_cafe,rid,query,v_status,employee_filter,own,start_date,end_date,settings->>'timezone',(page-1)*50;
  IF rid IS NOT NULL AND total=0 THEN RAISE EXCEPTION 'سجل الحضور غير متاح' USING ERRCODE='42501';END IF;
 ELSIF p_module='settings' THEN records:=jsonb_build_array(jsonb_build_object('id',p_cafe,'revision',settings->'revision','payload',settings));total:=1;
 ELSIF p_module='balances' THEN
  SELECT count(*) INTO total FROM public.erp_hr_employees e CROSS JOIN public.erp_att_leave_types t WHERE e.cafe_id=p_cafe AND t.cafe_id=p_cafe AND (type_filter IS NULL OR t.id=type_filter) AND e.active AND (role<>'self' OR e.id=own) AND (employee_filter IS NULL OR e.id=employee_filter);
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id::text||':'||t.id::text,'employee_id',e.id,'employee_name',concat_ws(' ',e.first_name,e.last_name),'leave_type_id',t.id,'name',t.name,'payload',erp_attendance_private.balance(p_cafe,e.id,t.id,coalesce(start_date,current_date)))),'[]') INTO records FROM(SELECT e.id,e.first_name,e.last_name,t.id typeid FROM public.erp_hr_employees e CROSS JOIN public.erp_att_leave_types t WHERE e.cafe_id=p_cafe AND t.cafe_id=p_cafe AND (type_filter IS NULL OR t.id=type_filter) AND e.active AND(role<>'self' OR e.id=own) AND(employee_filter IS NULL OR e.id=employee_filter) ORDER BY e.code,t.name LIMIT 50 OFFSET (page-1)*50)e JOIN public.erp_att_leave_types t ON t.id=e.typeid;
 ELSIF p_module='schedule' THEN
  start_date:=coalesce(start_date,(now() AT TIME ZONE(settings->>'timezone'))::date);end_date:=coalesce(end_date,start_date+6);IF end_date<start_date OR end_date-start_date>30 THEN RAISE EXCEPTION 'جدول الورديات يعرض حتى واحد وثلاثين يومًا';END IF;
  SELECT count(*) INTO total FROM public.erp_hr_employees e WHERE e.cafe_id=p_cafe AND e.active AND(role<>'self' OR e.id=own) AND(employee_filter IS NULL OR e.id=employee_filter);
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'employee_id',e.id,'employee_name',concat_ws(' ',e.first_name,e.last_name),'payload',jsonb_build_object('days',(SELECT jsonb_agg(jsonb_build_object('date',d::date,'shiftId',coalesce((SELECT a.shift_id FROM public.erp_att_allocations a JOIN public.erp_att_allocation_employees ae ON ae.cafe_id=a.cafe_id AND ae.allocation_id=a.id WHERE ae.cafe_id=p_cafe AND ae.employee_id=e.id AND d::date BETWEEN a.from_date AND a.to_date LIMIT 1),(SELECT primary_shift_id FROM public.erp_att_assignments WHERE cafe_id=p_cafe AND employee_id=e.id AND effective_from<=d::date AND coalesce(effective_to,'infinity')>=d::date LIMIT 1)),'secondaryShiftId',(SELECT secondary_shift_id FROM public.erp_att_assignments WHERE cafe_id=p_cafe AND employee_id=e.id AND effective_from<=d::date AND coalesce(effective_to,'infinity')>=d::date LIMIT 1),'leave',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'type',permission_type)),'[]') FROM public.erp_att_leaves WHERE cafe_id=p_cafe AND employee_id=e.id AND status='approved' AND d::date BETWEEN from_date AND to_date)) ORDER BY d) FROM generate_series(start_date::timestamp,end_date::timestamp,interval '1 day')d)))),'[]') INTO records FROM(SELECT * FROM public.erp_hr_employees e WHERE e.cafe_id=p_cafe AND e.active AND(role<>'self' OR e.id=own) AND(employee_filter IS NULL OR e.id=employee_filter) ORDER BY e.code LIMIT 50 OFFSET (page-1)*50)e;
 ELSE RAISE EXCEPTION 'قسم الحضور غير مدعوم';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'name',concat_ws(' ',first_name,last_name),'code',code,'userId',user_id,'branchId',branch_id,'departmentId',department_id,'designationId',designation_id) ORDER BY code),'[]') INTO employees FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND active AND(role<>'self' OR id=own);
 IF rid IS NOT NULL AND total>0 THEN SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY created_at DESC),'[]') INTO events FROM public.erp_att_events e WHERE cafe_id=p_cafe AND record_id=rid;END IF;
 result:=jsonb_build_object('records',records,'total',total,'employees',employees,'events',events,'ownEmployeeId',own,'actorId',auth.uid(),'isOwner',role='owner','role',role,'canWrite',role IN('owner','manager'),'canApprove',role IN('owner','manager') OR own IS NOT NULL,'settings',settings,
 'shifts',coalesce((SELECT jsonb_agg(payload||jsonb_build_object('id',id,'revision',revision) ORDER BY name) FROM public.erp_att_shifts WHERE cafe_id=p_cafe),'[]'),
 'policies',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY name) FROM public.erp_att_policies p WHERE cafe_id=p_cafe),'[]'),
 'leaveTypes',coalesce((SELECT jsonb_agg(payload||jsonb_build_object('id',id,'revision',revision) ORDER BY name) FROM public.erp_att_leave_types WHERE cafe_id=p_cafe),'[]'),
 'restrictions',CASE WHEN role='self' THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY name) FROM public.erp_att_restrictions p WHERE cafe_id=p_cafe),'[]') END,
