  IF id IS NULL THEN IF brand_finance_private.role_for(c) NOT IN('owner','manager') THEN RAISE EXCEPTION 'اختر أحد فروعك المصرح بها' USING ERRCODE='42501';END IF;ELSIF NOT erp_branch_private.branch_allowed(c,id) THEN RAISE EXCEPTION 'الفرع غير متاح' USING ERRCODE='42501';END IF;
  SELECT revision INTO rev FROM public.erp_branch_scopes WHERE cafe_id=c AND user_id=auth.uid() FOR UPDATE;IF coalesce(rev,0) IS DISTINCT FROM (p->>'revision')::integer THEN RAISE EXCEPTION 'تغير فرع العمل أعد تحميل الصفحة' USING ERRCODE='40001';END IF;
  INSERT INTO public.erp_branch_scopes(cafe_id,user_id,branch_id) VALUES(c,auth.uid(),id) ON CONFLICT(cafe_id,user_id) DO UPDATE SET branch_id=excluded.branch_id,revision=erp_branch_scopes.revision+1;result:=erp_branch_private.scope(c);
 ELSIF p_action='save' THEN
  SELECT * INTO r FROM public.branches WHERE cafe_id=c AND branches.id=id AND deleted_at IS NULL FOR UPDATE;
  IF (FOUND AND r.erp_revision IS DISTINCT FROM (p->>'revision')::integer) OR (NOT FOUND AND coalesce((p->>'revision')::integer,0)<>0) THEN RAISE EXCEPTION 'تغير الفرع أعد تحميله' USING ERRCODE='40001';END IF;
  IF coalesce(btrim(p->>'name'),'')='' OR length(p->>'name')>160 OR length(coalesce(p->>'address',''))>1000 OR length(coalesce(p->>'city',''))>100 OR length(coalesce(p->>'phone',''))>40 OR length(coalesce(p->>'email',''))>200 OR length(coalesce(p->>'code',''))>60 OR length(coalesce(p->>'note',''))>5000 OR length(coalesce(p->>'hours',''))>1000 OR length(coalesce(p->>'taxNumber',''))>40 OR length(coalesce(p->>'registration',''))>80 OR (coalesce(p->>'email','')<>'' AND p->>'email' !~ '^[^ @]+@[^ @]+[.][^ @]+$') OR jsonb_typeof(p->'active') IS DISTINCT FROM 'boolean' OR abs(coalesce((p->>'lat')::numeric,0))>90 OR abs(coalesce((p->>'lng')::numeric,0))>180 OR ((p->>'lat') IS NULL)<>((p->>'lng') IS NULL) THEN RAISE EXCEPTION 'راجع بيانات الفرع وموقعه';END IF;
  IF r.id IS NOT NULL AND r.is_primary AND NOT (p->>'active')::boolean THEN RAISE EXCEPTION 'اختر فرعًا رئيسيًا آخر قبل إيقاف هذا الفرع';END IF;
  id:=coalesce(id,gen_random_uuid());
  IF r.id IS NULL THEN INSERT INTO public.branches(id,cafe_id,name,address,city,phone,lat,lng,hours,active) VALUES(id,c,btrim(p->>'name'),p->>'address',p->>'city',p->>'phone',(p->>'lat')::numeric,(p->>'lng')::numeric,jsonb_build_object('summary',coalesce(p->>'hours','')),(p->>'active')::boolean);
  ELSE UPDATE public.branches SET name=btrim(p->>'name'),address=p->>'address',city=p->>'city',phone=p->>'phone',lat=(p->>'lat')::numeric,lng=(p->>'lng')::numeric,hours=coalesce(hours,'{}')||jsonb_build_object('summary',coalesce(p->>'hours','')),active=(p->>'active')::boolean WHERE cafe_id=c AND branches.id=id;END IF;
  INSERT INTO public.erp_branch_details(cafe_id,id,code,email,tax_number,registration,note) VALUES(c,id,coalesce(p->>'code',''),coalesce(p->>'email',''),coalesce(p->>'taxNumber',''),coalesce(p->>'registration',''),coalesce(p->>'note','')) ON CONFLICT ON CONSTRAINT erp_branch_details_pkey DO UPDATE SET code=excluded.code,email=excluded.email,tax_number=excluded.tax_number,registration=excluded.registration,note=excluded.note;
  result:=jsonb_build_object('id',id,'revision',(SELECT erp_revision FROM public.branches WHERE cafe_id=c AND branches.id=id));
 ELSIF p_action='settings' THEN
  SELECT revision INTO rev FROM public.erp_branch_settings WHERE cafe_id=c FOR UPDATE;IF coalesce(rev,0) IS DISTINCT FROM (p->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت إعدادات الفروع' USING ERRCODE='40001';END IF;
  b:=nullif(p->>'mainBranchId','')::uuid;IF b IS NULL OR NOT EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=c AND branches.id=b AND active AND deleted_at IS NULL) THEN RAISE EXCEPTION 'اختر فرعًا رئيسيًا نشطًا';END IF;
  FOREACH k IN ARRAY ARRAY['shareCustomers','shareProducts','shareSuppliers','shareCostCenters','shareUnitTemplates','specifyAccounts'] LOOP IF jsonb_typeof(p->k) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'إعدادات مشاركة الفروع غير صالحة';END IF;END LOOP;
  UPDATE public.branches SET is_primary=false WHERE cafe_id=c AND is_primary AND branches.id<>b AND deleted_at IS NULL;UPDATE public.branches SET is_primary=true WHERE cafe_id=c AND branches.id=b AND NOT is_primary;
  INSERT INTO public.erp_branch_settings(cafe_id,payload) VALUES(c,p-'revision'-'mainBranchId') ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload,revision=erp_branch_settings.revision+1;id:=b;result:=jsonb_build_object('saved',true);
 ELSIF p_action='members' THEN
  SELECT * INTO r FROM public.branches WHERE cafe_id=c AND branches.id=id FOR UPDATE;IF NOT FOUND OR r.erp_revision IS DISTINCT FROM (p->>'revision')::integer THEN RAISE EXCEPTION 'Branch membership changed' USING ERRCODE='40001';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=c AND branches.id=id AND deleted_at IS NULL) OR jsonb_typeof(p->'employeeIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'employeeIds')>1000 THEN RAISE EXCEPTION 'قائمة الموظفين غير صالحة';END IF;
  DELETE FROM public.erp_branch_members WHERE cafe_id=c AND branch_id=id;
  FOR v IN SELECT value FROM jsonb_array_elements(p->'employeeIds') LOOP e:=(v#>>'{}')::uuid;IF NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=c AND erp_hr_employees.id=e AND active) THEN RAISE EXCEPTION 'الموظف غير متاح';END IF;INSERT INTO public.erp_branch_members VALUES(c,id,e) ON CONFLICT DO NOTHING;END LOOP;UPDATE public.branches SET updated_at=now() WHERE cafe_id=c AND branches.id=id;result:=jsonb_build_object('id',id);
 ELSIF p_action='resource' THEN
  k:=p->>'kind';IF NOT erp_branch_private.resource_exists(c,k,id) OR jsonb_typeof(p->'branchIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'branchIds')>1000 THEN RAISE EXCEPTION 'السجل أو نطاق الفروع غير صالح';END IF;
  IF jsonb_typeof(p->'expectedBranchIds') IS DISTINCT FROM 'array' OR coalesce((SELECT jsonb_agg(branch_id ORDER BY branch_id) FROM public.erp_branch_resources WHERE cafe_id=c AND kind=k AND record_id=id),'[]'::jsonb) IS DISTINCT FROM coalesce((SELECT jsonb_agg((value#>>'{}')::uuid ORDER BY (value#>>'{}')::uuid) FROM jsonb_array_elements(p->'expectedBranchIds')),'[]'::jsonb) THEN RAISE EXCEPTION 'Branch resource scope changed' USING ERRCODE='40001';END IF;
  DELETE FROM public.erp_branch_resources WHERE cafe_id=c AND kind=k AND record_id=id;
  FOR v IN SELECT value FROM jsonb_array_elements(p->'branchIds') LOOP b:=(v#>>'{}')::uuid;IF NOT EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=c AND branches.id=b AND deleted_at IS NULL AND active) THEN RAISE EXCEPTION 'الفرع غير متاح';END IF;INSERT INTO public.erp_branch_resources VALUES(c,k,id,b) ON CONFLICT DO NOTHING;END LOOP;result:=jsonb_build_object('id',id);
 ELSIF p_action='delete' THEN
  SELECT * INTO r FROM public.branches WHERE cafe_id=c AND branches.id=id AND deleted_at IS NULL FOR UPDATE;IF NOT FOUND OR r.erp_revision IS DISTINCT FROM (p->>'revision')::integer THEN RAISE EXCEPTION 'تغير الفرع أعد تحميله' USING ERRCODE='40001';END IF;
  IF r.is_primary OR erp_branch_private.in_use(id) OR EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=c AND branch_id=id AND active) OR EXISTS(SELECT 1 FROM public.erp_branch_members WHERE cafe_id=c AND branch_id=id) OR EXISTS(SELECT 1 FROM public.erp_branch_resources WHERE cafe_id=c AND branch_id=id) OR EXISTS(SELECT 1 FROM public.erp_branch_documents WHERE cafe_id=c AND branch_id=id) OR EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=c AND entity_type='branch' AND record_id=id) THEN RAISE EXCEPTION 'الفرع مرتبط بسجلات أو موظفين أوقفه بدل حذفه';END IF;
  UPDATE public.branches SET active=false,deleted_at=now() WHERE cafe_id=c AND branches.id=id;result:=jsonb_build_object('id',id,'deleted',true);
 ELSE RAISE EXCEPTION 'عملية الفرع غير صالحة';END IF;
 INSERT INTO public.erp_branch_events(cafe_id,branch_id,action,payload,actor) VALUES(c,CASE WHEN p_action IN('resource') THEN NULL ELSE id END,p_action,p,auth.uid());
 INSERT INTO erp_branch_private.requests VALUES(c,p_request,auth.uid(),jsonb_build_object('action',p_action,'input',p),result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_commissions_sales(p_cafe_id uuid, p_from date, p_to date, p_query text DEFAULT ''::text, p_page integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'commissions','read');
 PERFORM erp_commission_private.authorize(p_cafe_id);
 IF p_from IS NULL OR p_to IS NULL OR p_to<p_from OR p_to-p_from>366 OR length(p_query)>100 OR p_page NOT BETWEEN 1 AND 100000 THEN RAISE EXCEPTION 'اختر نطاق بحث صالحًا' USING ERRCODE='22023';END IF;
 RETURN (WITH filtered AS (SELECT d.id,d.number,d.created_at,d.total,coalesce(a.employee_id,d.created_by) employee_id,a.branch_id,coalesce(a.revision,0) revision,(brand_finance_private.document_state(p_cafe_id,d.id)->>'outstanding')::numeric outstanding FROM public.bf_documents d LEFT JOIN public.erp_commission_sales a ON a.cafe_id=d.cafe_id AND a.document_id=d.id WHERE d.cafe_id=p_cafe_id AND d.kind='sale' AND (d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN p_from AND p_to AND (p_query='' OR d.number::text ILIKE '%'||p_query||'%')) SELECT jsonb_build_object('total',(SELECT count(*) FROM filtered),'rows',coalesce((SELECT jsonb_agg(x ORDER BY created_at DESC) FROM (SELECT * FROM filtered ORDER BY created_at DESC,id LIMIT 50 OFFSET (p_page-1)*50) x),'[]')));
END $function$

CREATE OR REPLACE FUNCTION public.erp_commissions_write(p_cafe_id uuid, p_action text, p_data jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r text;v_id uuid:=nullif(p_data->>'id','')::uuid;rule public.erp_commission_rules;period public.erp_commission_periods;previous erp_commission_private.requests;v_result jsonb;v_revision integer;v_target text;v_key text;v_employee uuid;v_branch uuid;v_doc public.bf_documents;
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'commissions',erp_access_private.action(p_action,p_data));
 r:=erp_commission_private.authorize(p_cafe_id,true,p_action IN('approve','reject','reopen','payout'));
 IF p_request_id IS NULL OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR octet_length(p_data::text)>100000 OR p_action IS NULL OR p_action NOT IN('save_rule','delete_rule','create_period','refresh','delete_period','approve','reject','reopen','payout','assign_sale') THEN RAISE EXCEPTION 'عملية العمولة غير صالحة' USING ERRCODE='22023';END IF;
 -- Finance lock first: payout and sales settlement use this same lock order.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,84552));
 SELECT * INTO previous FROM erp_commission_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF previous.actor<>auth.uid() OR previous.action<>p_action OR previous.payload<>p_data THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات مختلفة' USING ERRCODE='22023';END IF;RETURN previous.result;END IF;
 IF p_action IN('save_rule','delete_rule') THEN
  IF r NOT IN('owner','manager') THEN RAISE EXCEPTION 'تعديل قواعد العمولة متاح للمالك والمدير' USING ERRCODE='42501';END IF;
  IF v_id IS NOT NULL THEN SELECT * INTO rule FROM public.erp_commission_rules WHERE cafe_id=p_cafe_id AND id=v_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'القاعدة غير موجودة' USING ERRCODE='42501';END IF;END IF;
  IF coalesce(rule.revision,0) IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت القاعدة أعد تحميلها' USING ERRCODE='40001';END IF;
  IF p_action='save_rule' THEN
   PERFORM erp_commission_private.validate_rule(p_cafe_id,p_data);v_id:=coalesce(v_id,gen_random_uuid());
   INSERT INTO public.erp_commission_rules(id,cafe_id,name,active,payload) VALUES(v_id,p_cafe_id,p_data->>'name',(p_data->>'active')::boolean,p_data-'id'-'revision') ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active,payload=excluded.payload,revision=erp_commission_rules.revision+1;
  ELSE
   IF v_id IS NULL THEN RAISE EXCEPTION 'حدد القاعدة' USING ERRCODE='22023';END IF;DELETE FROM public.erp_commission_rules WHERE cafe_id=p_cafe_id AND id=v_id;
  END IF;
 ELSIF p_action='create_period' THEN
  IF jsonb_typeof(p_data->'ruleIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'ruleIds')>100 OR jsonb_typeof(p_data->'staffIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'staffIds')>500 THEN RAISE EXCEPTION 'راجع معايير الفترة' USING ERRCODE='22023';END IF;
  FOR v_target IN SELECT jsonb_array_elements_text(p_data->'ruleIds') LOOP IF NOT EXISTS(SELECT 1 FROM public.erp_commission_rules WHERE cafe_id=p_cafe_id AND id::text=v_target AND active) THEN RAISE EXCEPTION 'القاعدة المحددة غير متاحة' USING ERRCODE='22023';END IF;END LOOP;
  FOR v_target IN SELECT jsonb_array_elements_text(p_data->'staffIds') LOOP IF NOT erp_org_private.staff(p_cafe_id,v_target::uuid) THEN RAISE EXCEPTION 'الموظف المحدد غير متاح' USING ERRCODE='22023';END IF;END LOOP;
  FOREACH v_key IN ARRAY ARRAY['departmentId','designationId'] LOOP IF p_data->>v_key IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_org_units WHERE cafe_id=p_cafe_id AND id::text=p_data->>v_key AND active AND kind=CASE v_key WHEN 'departmentId' THEN 'department' ELSE 'designation' END) THEN RAISE EXCEPTION 'معيار الهيكل التنظيمي غير متاح' USING ERRCODE='22023';END IF;END LOOP;
  IF p_data->>'branchId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=p_cafe_id AND id::text=p_data->>'branchId' AND active AND deleted_at IS NULL) THEN RAISE EXCEPTION 'الفرع غير متاح' USING ERRCODE='22023';END IF;
  v_id:=gen_random_uuid();INSERT INTO public.erp_commission_periods(id,cafe_id,date_from,date_to,criteria) VALUES(v_id,p_cafe_id,(p_data->>'from')::date,(p_data->>'to')::date,p_data);PERFORM erp_commission_private.fill_period(p_cafe_id,v_id);
 ELSIF p_action='assign_sale' THEN
  v_employee:=(p_data->>'employeeId')::uuid;v_branch:=nullif(p_data->>'branchId','')::uuid;
  IF NOT erp_org_private.staff(p_cafe_id,v_employee) OR (v_branch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.branches WHERE cafe_id=p_cafe_id AND id=v_branch AND active AND deleted_at IS NULL)) THEN RAISE EXCEPTION 'الموظف أو الفرع غير متاح' USING ERRCODE='22023';END IF;
  SELECT * INTO v_doc FROM public.bf_documents WHERE cafe_id=p_cafe_id AND id=v_id AND kind='sale' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'فاتورة المبيعات غير موجودة' USING ERRCODE='42501';END IF;
  IF EXISTS(SELECT 1 FROM public.erp_commission_rows x JOIN public.erp_commission_periods p ON p.id=x.period_id WHERE x.cafe_id=p_cafe_id AND p.status<>'rejected' AND EXISTS(SELECT 1 FROM jsonb_array_elements(x.lines) line WHERE line->>'documentId'=v_id::text)) THEN RAISE EXCEPTION 'الفاتورة ضمن فترة عمولات احذف الفترة المفتوحة أو ارفضها قبل إعادة التعيين' USING ERRCODE='22023';END IF;
  SELECT revision INTO v_revision FROM public.erp_commission_sales WHERE cafe_id=p_cafe_id AND document_id=v_id;
  IF coalesce(v_revision,0) IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير تعيين الفاتورة أعد التحميل' USING ERRCODE='40001';END IF;
  INSERT INTO public.erp_commission_sales(cafe_id,document_id,employee_id,branch_id) VALUES(p_cafe_id,v_id,v_employee,v_branch) ON CONFLICT(cafe_id,document_id) DO UPDATE SET employee_id=excluded.employee_id,branch_id=excluded.branch_id,revision=erp_commission_sales.revision+1;
 ELSE
  SELECT * INTO period FROM public.erp_commission_periods WHERE cafe_id=p_cafe_id AND id=v_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'فترة المبيعات غير موجودة' USING ERRCODE='42501';END IF;
  IF period.revision IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت الفترة أعد تحميلها' USING ERRCODE='40001';END IF;
  IF p_action='refresh' THEN PERFORM erp_commission_private.fill_period(p_cafe_id,v_id);
  ELSIF p_action='delete_period' THEN IF period.status NOT IN('open','rejected') THEN RAISE EXCEPTION 'الفترة المعتمدة أو المصروفة محمية من الحذف' USING ERRCODE='22023';END IF;DELETE FROM public.erp_commission_periods WHERE cafe_id=p_cafe_id AND id=v_id;
  ELSIF p_action IN('approve','reject') THEN
   IF period.status<>'open' THEN RAISE EXCEPTION 'يجب أن تكون الفترة مفتوحة' USING ERRCODE='22023';END IF;
   UPDATE public.erp_commission_periods SET status=CASE p_action WHEN 'approve' THEN 'approved' ELSE 'rejected' END WHERE cafe_id=p_cafe_id AND id=v_id;
  ELSIF p_action='reopen' THEN
   IF period.status NOT IN('approved','rejected') THEN RAISE EXCEPTION 'الفترة المصروفة لا يمكن إعادة فتحها دون عكس التسوية المالية' USING ERRCODE='22023';END IF;
   IF EXISTS(SELECT 1 FROM public.erp_commission_rows x JOIN public.erp_commission_rows other ON other.cafe_id=x.cafe_id AND other.rule_id=x.rule_id AND other.employee_id=x.employee_id JOIN public.erp_commission_periods p ON p.id=other.period_id WHERE x.period_id=v_id AND p.id<>v_id AND p.status<>'rejected' AND p.date_from<=period.date_to AND p.date_to>=period.date_from) THEN RAISE EXCEPTION 'تتداخل الفترة مع فترة أخرى قائمة' USING ERRCODE='22023';END IF;
   UPDATE public.erp_commission_periods SET status='open' WHERE cafe_id=p_cafe_id AND id=v_id;
   PERFORM erp_commission_private.fill_period(p_cafe_id,v_id);
  ELSIF p_action='payout' THEN
   IF period.status<>'approved' OR period.total<=0 THEN RAISE EXCEPTION 'اعتمد فترة بعمولة موجبة قبل الصرف' USING ERRCODE='22023';END IF;
   IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe_id AND id=(p_data->>'accountId')::uuid AND active AND kind IN('cash','bank')) THEN RAISE EXCEPTION 'اختر حساب صرف نشطًا' USING ERRCODE='22023';END IF;
   v_result:=public.brand_finance_execute(p_cafe_id,'treasury',jsonb_build_object('kind','expense','accountId',p_data->>'accountId','amount',period.total,'note','صرف عمولات فترة المبيعات #'||period.number),gen_random_uuid());
   IF v_result->>'id' IS NULL THEN RAISE EXCEPTION 'لم يتأكد قيد صرف العمولة' USING ERRCODE='22023';END IF;
   UPDATE public.erp_commission_periods SET status='paid',payout_id=(v_result->>'id')::uuid WHERE cafe_id=p_cafe_id AND id=v_id;
  END IF;
  IF p_action<>'delete_period' THEN UPDATE public.erp_commission_periods SET revision=revision+1 WHERE cafe_id=p_cafe_id AND id=v_id;END IF;
 END IF;
 INSERT INTO public.erp_commission_events(cafe_id,record_id,actor,action,detail) VALUES(p_cafe_id,v_id,auth.uid(),p_action,p_data);
 v_result:=jsonb_build_object('id',v_id);INSERT INTO erp_commission_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_data,v_result);RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_contracting_advance_assign(p_cafe uuid, p_invoice uuid, p_contract uuid, p_revision integer, p_request uuid, p_scope jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE a public.erp_contracting_advance_invoices;z public.erp_contracting_advance_assignments;cmd jsonb;r jsonb;old_scope text:=current_setting('erp.branch_expected',true);BEGIN
 PERFORM set_config('erp.branch_expected',coalesce(p_scope::text,''),true);PERFORM erp_branch_private.enter(p_cafe);PERFORM erp_branch_private.assert_context(p_cafe);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67131));PERFORM erp_access_private.assert_allowed(p_cafe,'contracting','update');PERFORM erp_branch_private.assert_input(p_cafe,jsonb_build_object('invoiceId',p_invoice,'contract_id',p_contract));
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.erp_contracting_advances(p_cafe)) x WHERE x->>'invoice_id'=p_invoice::text) THEN RAISE EXCEPTION 'فاتورة الدفعة غير متاحة' USING ERRCODE='42501';END IF;
 SELECT * INTO a FROM public.erp_contracting_advance_invoices WHERE cafe_id=p_cafe AND invoice_id=p_invoice FOR UPDATE;SELECT * INTO z FROM public.erp_contracting_advance_assignments WHERE cafe_id=p_cafe AND invoice_id=p_invoice FOR UPDATE;
 cmd:=jsonb_build_object('action','advance_assign','invoice',p_invoice,'contract',p_contract,'revision',p_revision);SELECT result INTO r FROM public.erp_contracting_requests WHERE cafe_id=p_cafe AND id=p_request AND command=cmd;IF FOUND THEN PERFORM set_config('erp.branch_expected',coalesce(old_scope,''),true);RETURN r;END IF;
 IF p_request IS NULL OR z.revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'تغير ربط الدفعة أعد تحميل الصفحة' USING ERRCODE='40001';END IF;
 IF erp_settings_private.advance_used(p_cafe,p_invoice)>0 THEN RAISE EXCEPTION 'اعكس استرداد المستخلص قبل تغيير عقد الدفعة' USING ERRCODE='22023';END IF;
 IF p_contract IS NOT NULL AND (erp_settings_private.advance_available(p_cafe,p_invoice)<=0 OR NOT EXISTS(SELECT 1 FROM public.erp_contracting_documents WHERE cafe_id=p_cafe AND id=p_contract AND project_id=a.project_id AND customer_id=a.party_id AND kind='contract' AND status='active')) THEN RAISE EXCEPTION 'اختر عقدًا نشطًا لنفس المشروع والعميل ودفعة لها رصيد متاح' USING ERRCODE='22023';END IF;
 UPDATE public.erp_contracting_advance_assignments SET contract_id=p_contract,revision=revision+1 WHERE cafe_id=p_cafe AND invoice_id=p_invoice;INSERT INTO public.erp_contracting_events(cafe_id,document_id,action,note,actor) VALUES(p_cafe,a.project_id,CASE WHEN p_contract IS NULL THEN 'advance_unassigned' ELSE 'advance_assigned' END,p_invoice::text,auth.uid());r:=jsonb_build_object('id',p_invoice,'revision',z.revision+1);INSERT INTO public.erp_contracting_requests VALUES(p_cafe,p_request,cmd,r);PERFORM set_config('erp.branch_expected',coalesce(old_scope,''),true);RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.erp_contracting_advance_credit(p_cafe uuid, p_invoice uuid, p_net numeric, p_reason text, p_request uuid, p_scope jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE a public.erp_contracting_advance_invoices;p jsonb;r jsonb;n uuid:=p_request;old_scope text:=current_setting('erp.branch_expected',true);old_credit text:=current_setting('erp.advance_credit',true);t numeric;BEGIN
 PERFORM set_config('erp.branch_expected',coalesce(p_scope::text,''),true);PERFORM erp_branch_private.enter(p_cafe);PERFORM erp_branch_private.assert_context(p_cafe);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67131));PERFORM erp_access_private.assert_allowed(p_cafe,'contracting','approve');PERFORM erp_access_private.assert_allowed(p_cafe,'finance','approve');
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.erp_contracting_advances(p_cafe)) x WHERE x->>'invoice_id'=p_invoice::text) THEN RAISE EXCEPTION 'فاتورة الدفعة غير متاحة' USING ERRCODE='42501';END IF;
 SELECT * INTO a FROM public.erp_contracting_advance_invoices WHERE cafe_id=p_cafe AND invoice_id=p_invoice FOR UPDATE;
 IF p_request IS NULL OR p_net IS NULL OR p_net<=0 OR p_net<>round(p_net,2) OR p_net>a.net OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'راجع قيمة وسبب رد الدفعة' USING ERRCODE='22023';END IF;t:=round(p_net*a.tax_rate/100,2);
 IF EXISTS(SELECT 1 FROM public.erp_contracting_advance_credit_drafts WHERE cafe_id=p_cafe AND note_id=n) THEN
  IF NOT EXISTS(SELECT 1 FROM public.erp_contracting_advance_credit_drafts WHERE cafe_id=p_cafe AND note_id=n AND invoice_id=p_invoice AND net=p_net AND payload->>'reason'=btrim(p_reason)) THEN RAISE EXCEPTION 'تغير محتوى الطلب المكرر' USING ERRCODE='40001';END IF;r:=public.brand_finance_credit_notes(p_cafe,n);PERFORM set_config('erp.branch_expected',coalesce(old_scope,''),true);RETURN r;
 END IF;
 p:=jsonb_build_object('partyId',a.party_id,'warehouseId','','date',current_date,'issueDate',current_date,'salespersonId',NULL,'sourceInvoiceId',p_invoice,'reason',btrim(p_reason),'note','','terms','','template','standard','deliveryMethod','print','stockRequired',false,'discountValue',0,'discountKind','amount','vatRate',a.tax_rate,'taxInclusive',false,'lines',jsonb_build_array(jsonb_build_object('key',1,'productId','','quantity',1,'price',p_net,'description',btrim(p_reason),'vatRate',a.tax_rate)));
 INSERT INTO public.erp_contracting_advance_credit_drafts VALUES(p_cafe,n,p_invoice,p_net,t,p);PERFORM set_config('erp.advance_credit',n::text,true);
 PERFORM public.brand_finance_save_credit_note(p_cafe,n,0,p);r:=public.brand_finance_transition_credit_note(p_cafe,n,1,'issue',gen_random_uuid(),'');
 PERFORM set_config('erp.advance_credit',coalesce(old_credit,''),true);PERFORM set_config('erp.branch_expected',coalesce(old_scope,''),true);RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.erp_contracting_advance_draft(p_cafe uuid, p_input jsonb, p_request uuid, p_scope jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;draft uuid;contract uuid:=nullif(p_input->>'contract_id','')::uuid;project uuid:=(p_input->>'id')::uuid;old_scope text:=current_setting('erp.branch_expected',true);linked public.erp_contracting_invoice_drafts;
BEGIN
 PERFORM set_config('erp.branch_expected',coalesce(p_scope::text,''),true);PERFORM erp_branch_private.enter(p_cafe);PERFORM erp_branch_private.assert_context(p_cafe);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67131));PERFORM erp_access_private.assert_allowed(p_cafe,'contracting','create');PERFORM erp_branch_private.assert_input(p_cafe,p_input);
 IF contract IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_contracting_documents WHERE cafe_id=p_cafe AND id=contract AND kind='contract' AND status='active' AND project_id=project) THEN RAISE EXCEPTION 'اختر عقدًا نشطًا داخل المشروع' USING ERRCODE='22023';END IF;
 result:=public.erp_contracting(p_cafe,'project_invoice',p_input||jsonb_build_object('invoice_kind','invoice'),p_request);draft:=(result->>'draft_id')::uuid;
 SELECT * INTO linked FROM public.erp_contracting_invoice_drafts WHERE cafe_id=p_cafe AND draft_id=draft FOR UPDATE;
 IF linked.kind='advance' THEN PERFORM set_config('erp.branch_expected',coalesce(old_scope,''),true);RETURN result;END IF;
 IF EXISTS(SELECT 1 FROM public.bf_company_invoices WHERE cafe_id=p_cafe AND draft_id=linked.draft_id) THEN RAISE EXCEPTION 'الفاتورة صدرت بالفعل' USING ERRCODE='22023';END IF;
 UPDATE public.erp_contracting_invoice_drafts SET kind='advance' WHERE cafe_id=p_cafe AND draft_id=draft;
 INSERT INTO public.erp_contracting_advance_drafts VALUES(p_cafe,draft,contract);
 INSERT INTO public.erp_contracting_events(cafe_id,document_id,action,note,actor) VALUES(p_cafe,project,'advance_invoice_draft',coalesce(contract::text,''),auth.uid());
 PERFORM set_config('erp.branch_expected',coalesce(old_scope,''),true);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_contracting_forms_read(p_cafe uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE m record;e record;models jsonb:='[]';entries jsonb:='[]';cfg jsonb;visible jsonb;settings boolean;lookups jsonb:='{}';BEGIN
 PERFORM erp_contract_form_private.authorize(p_cafe,'read');PERFORM erp_branch_private.enter(p_cafe);
 settings:=brand_finance_private.role_for(p_cafe)='owner' AND erp_access_private.allowed(p_cafe,'contracting','settings');
 FOR m IN SELECT * FROM public.erp_contracting_forms WHERE cafe_id=p_cafe ORDER BY kind,key LOOP
  cfg:=m.config;
  IF NOT settings AND NOT erp_contract_form_private.allowed(p_cafe,cfg,'read') THEN CONTINUE;END IF;
  visible:=CASE WHEN settings THEN cfg ELSE cfg-'permissions' END;
  IF NOT settings THEN visible:=jsonb_set(visible,'{fields}',coalesce((SELECT jsonb_agg(CASE WHEN f?'defaultValue' AND NOT erp_contract_form_private.value_scope(p_cafe,jsonb_build_array(f),jsonb_build_object(f->>'id',f->'defaultValue')) THEN f-'defaultValue' ELSE f END) FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=ANY(erp_contract_form_private.fields(p_cafe,cfg,'read'))),'[]'));END IF;
  models:=models||jsonb_build_array(visible||jsonb_build_object('id',m.id,'revision',m.revision,'kind',m.kind,'key',m.key,'canCreate',coalesce((cfg->>'active')::boolean,false) AND erp_contract_form_private.allowed(p_cafe,cfg,'create'),'canRead',erp_contract_form_private.allowed(p_cafe,cfg,'read'),'canUpdate',coalesce((cfg->>'active')::boolean,false) AND erp_contract_form_private.allowed(p_cafe,cfg,'update'),'canDelete',erp_contract_form_private.allowed(p_cafe,cfg,'delete'),'allowedFields',jsonb_build_object('create',erp_contract_form_private.fields(p_cafe,cfg,'create'),'read',erp_contract_form_private.fields(p_cafe,cfg,'read'),'update',erp_contract_form_private.fields(p_cafe,cfg,'update'))));
  IF NOT erp_contract_form_private.allowed(p_cafe,cfg,'read') THEN CONTINUE;END IF;
  FOR e IN SELECT * FROM public.erp_contracting_form_entries WHERE cafe_id=p_cafe AND model_id=m.id LOOP
   IF NOT erp_contract_form_private.project_visible(p_cafe,e.project_id) THEN CONTINUE;END IF;
   entries:=entries||jsonb_build_array(jsonb_build_object('id',e.id,'modelId',e.model_id,'projectId',e.project_id,'revision',e.revision,'draft',e.draft,'values',erp_contract_form_private.mask(p_cafe,cfg,e.field_values),'createdAt',e.created_at,'canUpdate',coalesce((cfg->>'active')::boolean,false) AND erp_contract_form_private.allowed(p_cafe,cfg,'update'),'canDelete',erp_contract_form_private.allowed(p_cafe,cfg,'delete'),'canFiles',erp_contract_form_private.allowed(p_cafe,cfg,'update') AND erp_access_private.allowed(p_cafe,'contracting','files') AND cardinality(erp_contract_form_private.fields(p_cafe,cfg,'read'))=jsonb_array_length(cfg->'fields')));
  END LOOP;
 END LOOP;
 IF settings THEN
  lookups:=jsonb_build_object('branches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.branches WHERE cafe_id=p_cafe),'[]'),'departments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_org_units WHERE cafe_id=p_cafe AND kind='department' AND active),'[]'),'designations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_org_units WHERE cafe_id=p_cafe AND kind='designation' AND active),'[]'),'employees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',first_name||' '||last_name)) FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND active),'[]'),'users',coalesce((SELECT jsonb_agg(jsonb_build_object('id',user_id,'name',name)) FROM public.bf_staff WHERE cafe_id=p_cafe AND active),'[]'),'roles',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_roles WHERE cafe_id=p_cafe AND active),'[]'));
 END IF;
 RETURN jsonb_build_object('models',models,'entries',entries,'canConfigure',settings,'lookups',lookups,'branchScope',public.erp_branch_context(p_cafe)->'scope','events',coalesce((SELECT jsonb_agg(jsonb_build_object('id',ev.id,'projectId',ev.project_id,'action',ev.action,'at',ev.at)) FROM public.erp_contracting_form_events ev WHERE ev.cafe_id=p_cafe AND (ev.project_id IS NULL AND settings OR erp_contract_form_private.project_visible(p_cafe,ev.project_id)) AND EXISTS(SELECT 1 FROM public.erp_contracting_forms fm WHERE fm.cafe_id=p_cafe AND fm.id=ev.model_id AND erp_contract_form_private.allowed(p_cafe,fm.config,'read'))),'[]'));
END $function$

CREATE OR REPLACE FUNCTION public.erp_contracting_forms_write(p_cafe uuid, p_action text, p_input jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i uuid:=(p_input->>'id')::uuid;rev integer:=(p_input->>'revision')::integer;m public.erp_contracting_forms;e public.erp_contracting_form_entries;prior erp_contract_form_private.requests;cfg jsonb;v jsonb;r jsonb;a text;k text;pid uuid;mid uuid;keys text[];result jsonb;rowdata record;BEGIN
 a:=CASE WHEN p_action='model' OR p_action='delete' AND p_input->>'entity'='model' THEN 'settings' WHEN p_action='delete' THEN 'delete' WHEN rev=0 THEN 'create' ELSE 'update' END;
 PERFORM erp_contract_form_private.authorize(p_cafe,a);PERFORM erp_branch_private.assert_context(p_cafe);PERFORM erp_branch_private.enter(p_cafe);
 IF p_action NOT IN('model','entry','delete') OR p_request IS NULL OR i IS NULL OR rev IS NULL OR rev<0 OR jsonb_typeof(p_input)<>'object' OR octet_length(p_input::text)>400000 THEN RAISE EXCEPTION 'بيانات النموذج غير صالحة' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 SELECT * INTO prior FROM erp_contract_form_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;
 IF FOUND THEN
  IF prior.actor IS DISTINCT FROM auth.uid() OR prior.action<>p_action OR prior.payload<>p_input THEN RAISE EXCEPTION 'معرف عملية مكرر ببيانات مختلفة' USING ERRCODE='40001';END IF;
  IF prior.result->>'projectId' IS NOT NULL AND NOT erp_contract_form_private.project_visible(p_cafe,(prior.result->>'projectId')::uuid) THEN RAISE EXCEPTION 'المشروع غير متاح' USING ERRCODE='42501';END IF;
  SELECT * INTO m FROM public.erp_contracting_forms WHERE cafe_id=p_cafe AND id=(prior.result->>'modelId')::uuid;
  IF a<>'settings' AND (m.id IS NULL OR NOT erp_contract_form_private.allowed(p_cafe,m.config,'read') OR NOT erp_contract_form_private.allowed(p_cafe,m.config,a)) THEN RAISE EXCEPTION 'النموذج غير متاح' USING ERRCODE='42501';END IF;RETURN prior.result;
 END IF;
 IF p_action='model' THEN
  SELECT * INTO m FROM public.erp_contracting_forms WHERE cafe_id=p_cafe AND id=i FOR UPDATE;
  IF coalesce(m.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  cfg:=p_input-'id'-'revision';
  IF coalesce(cfg->>'kind','') NOT IN('primary','related') OR coalesce(cfg->>'key','')!~'^[a-z][a-z0-9_]{0,59}$' OR length(btrim(coalesce(cfg->>'name',''))) NOT BETWEEN 1 AND 160 OR jsonb_typeof(cfg->'active') IS DISTINCT FROM 'boolean' OR length(coalesce(cfg->>'description',''))>5000 OR jsonb_typeof(cfg->'permissions') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'تعريف النموذج غير صالح' USING ERRCODE='22023';END IF;
  IF m.id IS NOT NULL AND m.kind<>cfg->>'kind' THEN RAISE EXCEPTION 'لا يمكن تغيير نوع النموذج';END IF;
  PERFORM erp_manufacturing_private.validate_custom_fields(cfg->'fields');
  IF coalesce(cfg->>'nameField','')<>'' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=cfg->>'nameField' AND f->>'type' IN('text','number','date','email','phone')) THEN RAISE EXCEPTION 'اختر حقل اسم صالح';END IF;
  FOREACH k IN ARRAY ARRAY['create','read','update','delete'] LOOP PERFORM erp_workflow_private.validate_selector(p_cafe,cfg#>ARRAY['permissions',k]);END LOOP;
  IF jsonb_typeof(cfg#>'{permissions,fieldRules}') IS DISTINCT FROM 'array' OR jsonb_array_length(cfg#>'{permissions,fieldRules}')>50 THEN RAISE EXCEPTION 'قواعد الحقول غير صالحة';END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(cfg#>'{permissions,fieldRules}') LOOP
   PERFORM (r->>'id')::uuid;PERFORM erp_workflow_private.validate_selector(p_cafe,r->'selector');
   FOREACH k IN ARRAY ARRAY['create','read','update'] LOOP
    IF jsonb_typeof(r->k) IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(r->k) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=x)) THEN RAISE EXCEPTION 'صلاحيات الحقول غير صالحة';END IF;
   END LOOP;
  END LOOP;
  FOR r IN SELECT value FROM jsonb_array_elements(cfg#>'{permissions,fieldRules}') LOOP
   IF NOT ((r->'read') @> (r->'create')) OR NOT ((r->'read') @> (r->'update')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE coalesce((f->>'required')::boolean,false) AND NOT (r->'create')?(f->>'id')) THEN RAISE EXCEPTION 'الحقول المطلوبة والقابلة للتعديل يجب أن تكون متاحة للعرض والإضافة';END IF;
  END LOOP;
  FOR rowdata IN SELECT * FROM public.erp_contracting_form_entries WHERE cafe_id=p_cafe AND model_id=i LOOP
   IF EXISTS(SELECT 1 FROM jsonb_object_keys(rowdata.field_values) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=x)) THEN RAISE EXCEPTION 'الحقل يحتوي بيانات محفوظة ولا يمكن حذفه';END IF;
   PERFORM erp_contract_form_private.validate_values(cfg->'fields',rowdata.field_values,p_cafe,rowdata.id,i,0,rowdata.draft);
  END LOOP;
  INSERT INTO public.erp_contracting_forms(id,cafe_id,kind,key,config) VALUES(i,p_cafe,cfg->>'kind',cfg->>'key',cfg) ON CONFLICT(id) DO UPDATE SET config=excluded.config,key=excluded.key,revision=public.erp_contracting_forms.revision+1 WHERE public.erp_contracting_forms.cafe_id=p_cafe;
  IF NOT FOUND THEN RAISE EXCEPTION 'النموذج غير متاح' USING ERRCODE='42501';END IF;mid:=i;
 ELSIF p_action='entry' THEN
  pid:=(p_input->>'projectId')::uuid;mid:=(p_input->>'modelId')::uuid;
  IF NOT erp_contract_form_private.project_visible(p_cafe,pid) THEN RAISE EXCEPTION 'المشروع غير متاح' USING ERRCODE='42501';END IF;
  SELECT * INTO m FROM public.erp_contracting_forms WHERE cafe_id=p_cafe AND id=mid FOR KEY SHARE;
  SELECT * INTO e FROM public.erp_contracting_form_entries WHERE cafe_id=p_cafe AND id=i FOR UPDATE;
  IF m.id IS NULL OR NOT coalesce((m.config->>'active')::boolean,false) OR NOT erp_contract_form_private.allowed(p_cafe,m.config,'read') OR NOT erp_contract_form_private.allowed(p_cafe,m.config,a) THEN RAISE EXCEPTION 'النموذج غير متاح' USING ERRCODE='42501';END IF;
  IF e.id IS NOT NULL AND (e.project_id<>pid OR e.model_id<>mid) THEN RAISE EXCEPTION 'لا يمكن نقل سجل النموذج';END IF;
  IF coalesce(e.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(p_input->'draft') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'values') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'قيم النموذج غير صالحة';END IF;
  keys:=erp_contract_form_private.fields(p_cafe,m.config,a);
  FOR k,v IN SELECT * FROM jsonb_each(p_input->'values') LOOP IF NOT k=ANY(keys) THEN RAISE EXCEPTION 'لا تملك صلاحية تعديل الحقل' USING ERRCODE='42501';END IF;END LOOP;
  v:=coalesce(e.field_values,'{}')||(p_input->'values');v:=erp_manufacturing_private.custom_defaults(m.config->'fields',v);
  IF NOT erp_contract_form_private.value_scope(p_cafe,m.config->'fields',v) THEN RAISE EXCEPTION 'مرجع الحقل غير متاح في الفرع' USING ERRCODE='42501';END IF;
  PERFORM erp_contract_form_private.validate_values(m.config->'fields',v,p_cafe,i,mid,0,(p_input->>'draft')::boolean);
  INSERT INTO public.erp_contracting_form_entries(id,cafe_id,model_id,model_kind,project_id,draft,field_values,created_by) VALUES(i,p_cafe,mid,m.kind,pid,(p_input->>'draft')::boolean,v,auth.uid()) ON CONFLICT(id) DO UPDATE SET field_values=excluded.field_values,draft=excluded.draft,revision=public.erp_contracting_form_entries.revision+1,updated_at=now() WHERE public.erp_contracting_form_entries.cafe_id=p_cafe;
  IF NOT FOUND THEN RAISE EXCEPTION 'السجل غير متاح' USING ERRCODE='42501';END IF;
 ELSIF p_input->>'entity'='model' THEN
  SELECT * INTO m FROM public.erp_contracting_forms WHERE cafe_id=p_cafe AND id=i FOR UPDATE;
  IF m.id IS NULL OR m.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  DELETE FROM public.erp_contracting_forms WHERE cafe_id=p_cafe AND id=i;mid:=i;
 ELSIF p_input->>'entity'='entry' THEN
  e:=erp_contract_form_private.assert_entry(p_cafe,i,'delete');pid:=e.project_id;mid:=e.model_id;
  IF e.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  DELETE FROM public.erp_contracting_form_entries WHERE cafe_id=p_cafe AND id=i;
 ELSE RAISE EXCEPTION 'نوع السجل غير صالح';END IF;
 result:=jsonb_build_object('id',i,'modelId',mid,'projectId',pid,'revision',rev+1);
 INSERT INTO public.erp_contracting_form_events(cafe_id,project_id,model_id,entry_id,action,actor) VALUES(p_cafe,pid,mid,CASE WHEN pid IS NOT NULL THEN i END,p_action,auth.uid());
 INSERT INTO erp_contract_form_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_credits_write_before_memberships(p_cafe uuid, p_action text, p_input jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i uuid;rev integer;old_rev integer;result jsonb;prior erp_credit_private.requests;t public.erp_credit_types;ch public.erp_credit_charges;u public.erp_credit_usages;cu uuid;ty uuid;qty numeric;d date;ex date;line jsonb;n integer;row record;need numeric;take numeric;permission text;
BEGIN
 IF p_request IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>100000 OR p_action NOT IN('type','type_delete','package','package_delete','charge','charge_delete','usage','usage_delete') THEN RAISE EXCEPTION 'راجع بيانات عملية الرصيد';END IF;
 i:=(p_input->>'id')::uuid;rev:=(p_input->>'revision')::integer;IF i IS NULL OR rev IS NULL OR rev<0 THEN RAISE EXCEPTION 'معرف السجل غير صالح';END IF;
 permission:=CASE WHEN p_action LIKE '%_delete' THEN 'delete' WHEN rev=0 THEN 'create' ELSE 'update' END;PERFORM erp_credit_private.authorize(p_cafe,permission);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67951));
 SELECT * INTO prior FROM erp_credit_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>p_action OR prior.input<>p_input THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN prior.result;END IF;
 IF p_action LIKE 'type%' THEN
  SELECT * INTO t FROM public.erp_credit_types WHERE cafe_id=p_cafe AND id=i FOR UPDATE;old_rev:=coalesce(t.revision,0);IF old_rev<>rev THEN RAISE EXCEPTION 'تغير نوع الرصيد' USING ERRCODE='40001';END IF;
  IF p_action='type_delete' THEN IF rev=0 THEN RAISE EXCEPTION 'نوع الرصيد غير موجود';END IF;DELETE FROM public.erp_credit_types WHERE cafe_id=p_cafe AND id=i;
  ELSE
   IF jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'decimals') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع الحالة ووحدات الرصيد';END IF;
   IF NOT(p_input->>'decimals')::boolean AND(EXISTS(SELECT 1 FROM public.erp_credit_charges WHERE cafe_id=p_cafe AND type_id=i AND quantity<>trunc(quantity)) OR EXISTS(SELECT 1 FROM public.erp_credit_package_lines WHERE cafe_id=p_cafe AND type_id=i AND quantity<>trunc(quantity)) OR EXISTS(SELECT 1 FROM public.erp_credit_usages WHERE cafe_id=p_cafe AND type_id=i AND quantity<>trunc(quantity))) THEN RAISE EXCEPTION 'لا يمكن إلغاء الكسور لنوع مرتبط بكميات عشرية';END IF;
   INSERT INTO public.erp_credit_types(cafe_id,id,name,unit,description,active,decimals,revision) VALUES(p_cafe,i,btrim(p_input->>'name'),coalesce(p_input->>'unit',''),coalesce(p_input->>'description',''),(p_input->>'active')::boolean,(p_input->>'decimals')::boolean,rev+1) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,unit=excluded.unit,description=excluded.description,active=excluded.active,decimals=excluded.decimals,revision=excluded.revision;
  END IF;
 ELSIF p_action LIKE 'package%' THEN
  SELECT revision INTO old_rev FROM public.erp_credit_packages WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF coalesce(old_rev,0)<>rev THEN RAISE EXCEPTION 'تغيرت الباقة' USING ERRCODE='40001';END IF;
  IF p_action='package_delete' THEN IF rev=0 THEN RAISE EXCEPTION 'الباقة غير موجودة';END IF;DELETE FROM public.erp_credit_packages WHERE cafe_id=p_cafe AND id=i;
  ELSE
   IF jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'lines') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'lines')>100 OR ((p_input->>'kind')='credit' AND jsonb_array_length(p_input->'lines')=0) OR (p_input->>'price')::numeric<>round((p_input->>'price')::numeric,2) THEN RAISE EXCEPTION 'راجع معلومات الباقة وأنواع الأرصدة';END IF;
   INSERT INTO public.erp_credit_packages(cafe_id,id,name,kind,price,period,period_unit,description,active,revision) VALUES(p_cafe,i,btrim(p_input->>'name'),p_input->>'kind',(p_input->>'price')::numeric,(p_input->>'period')::integer,p_input->>'periodUnit',coalesce(p_input->>'description',''),(p_input->>'active')::boolean,rev+1) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,kind=excluded.kind,price=excluded.price,period=excluded.period,period_unit=excluded.period_unit,description=excluded.description,active=excluded.active,revision=excluded.revision;
   DELETE FROM public.erp_credit_package_lines WHERE cafe_id=p_cafe AND package_id=i;n:=0;
   FOR line IN SELECT value FROM jsonb_array_elements(p_input->'lines') LOOP n:=n+1;ty:=(line->>'typeId')::uuid;qty:=(line->>'quantity')::numeric;SELECT * INTO t FROM public.erp_credit_types WHERE cafe_id=p_cafe AND id=ty AND active;IF NOT FOUND OR qty IS NULL OR qty<=0 OR qty>1e12 OR qty<>round(qty,4) OR(NOT t.decimals AND qty<>trunc(qty)) THEN RAISE EXCEPTION 'راجع نوع الرصيد والكمية وسماح الكسور';END IF;INSERT INTO public.erp_credit_package_lines VALUES(p_cafe,i,ty,qty,n);END LOOP;
  END IF;
 ELSE
  IF p_action LIKE 'charge%' THEN SELECT * INTO ch FROM public.erp_credit_charges WHERE cafe_id=p_cafe AND id=i FOR UPDATE;old_rev:=coalesce(ch.revision,0);IF ch.id IS NOT NULL AND ch.source_kind<>'manual' THEN RAISE EXCEPTION 'الشحنة مرتبطة باشتراك وتدار من مصدرها';END IF;
  ELSE SELECT * INTO u FROM public.erp_credit_usages WHERE cafe_id=p_cafe AND id=i FOR UPDATE;old_rev:=coalesce(u.revision,0);IF u.voided THEN RAISE EXCEPTION 'تم إلغاء حركة الاستهلاك';END IF;END IF;
  IF old_rev<>rev THEN RAISE EXCEPTION 'تغير سجل الرصيد' USING ERRCODE='40001';END IF;
  IF p_action='charge_delete' THEN IF rev=0 THEN RAISE EXCEPTION 'الشحنة غير موجودة';END IF;DELETE FROM public.erp_credit_charges WHERE cafe_id=p_cafe AND id=i;
  ELSIF p_action='usage_delete' THEN IF rev=0 THEN RAISE EXCEPTION 'الاستهلاك غير موجود';END IF;DELETE FROM public.erp_credit_allocations WHERE cafe_id=p_cafe AND usage_id=i;UPDATE public.erp_credit_usages SET voided=true,revision=rev+1 WHERE cafe_id=p_cafe AND id=i;
  ELSE
   cu:=(p_input->>'customerId')::uuid;ty:=(p_input->>'typeId')::uuid;qty:=(p_input->>'quantity')::numeric;
   IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=cu AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
   SELECT * INTO t FROM public.erp_credit_types WHERE cafe_id=p_cafe AND id=ty AND active;IF NOT FOUND OR qty IS NULL OR qty<=0 OR qty>1e12 OR qty<>round(qty,4) OR(NOT t.decimals AND qty<>trunc(qty)) THEN RAISE EXCEPTION 'راجع نوع الرصيد والكمية وسماح الكسور';END IF;
   IF p_action='charge' THEN
    d:=(p_input->>'startsOn')::date;ex:=nullif(p_input->>'expiresOn','')::date;IF d IS NULL OR NOT isfinite(d) OR (ex IS NOT NULL AND NOT isfinite(ex)) THEN RAISE EXCEPTION 'راجع تواريخ الشحنة';END IF;IF jsonb_typeof(p_input->'suspended') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع حالة الشحنة';END IF;
    IF EXISTS(SELECT 1 FROM public.erp_credit_allocations a JOIN public.erp_credit_usages v ON v.cafe_id=a.cafe_id AND v.id=a.usage_id WHERE a.cafe_id=p_cafe AND a.charge_id=i AND(v.customer_id<>cu OR v.type_id<>ty OR v.used_on<d OR v.used_on>ex)) OR qty<coalesce((SELECT sum(quantity) FROM public.erp_credit_allocations WHERE cafe_id=p_cafe AND charge_id=i),0) THEN RAISE EXCEPTION 'التعديل يتعارض مع الاستهلاك المسجل';END IF;
    INSERT INTO public.erp_credit_charges(cafe_id,id,customer_id,type_id,quantity,starts_on,expires_on,description,suspended,revision,created_by) VALUES(p_cafe,i,cu,ty,qty,d,ex,coalesce(p_input->>'description',''),(p_input->>'suspended')::boolean,rev+1,auth.uid()) ON CONFLICT(cafe_id,id) DO UPDATE SET customer_id=excluded.customer_id,type_id=excluded.type_id,quantity=excluded.quantity,starts_on=excluded.starts_on,expires_on=excluded.expires_on,description=excluded.description,suspended=excluded.suspended,revision=excluded.revision;
   ELSE
    d:=(p_input->>'usedOn')::date;IF d IS NULL OR NOT isfinite(d) THEN RAISE EXCEPTION 'راجع تاريخ الاستهلاك';END IF;DELETE FROM public.erp_credit_allocations WHERE cafe_id=p_cafe AND usage_id=i;
    INSERT INTO public.erp_credit_usages(cafe_id,id,customer_id,type_id,quantity,used_on,description,charge_id,revision,created_by) VALUES(p_cafe,i,cu,ty,qty,d,coalesce(p_input->>'description',''),nullif(p_input->>'chargeId','')::uuid,rev+1,auth.uid()) ON CONFLICT(cafe_id,id) DO UPDATE SET customer_id=excluded.customer_id,type_id=excluded.type_id,quantity=excluded.quantity,used_on=excluded.used_on,description=excluded.description,charge_id=excluded.charge_id,revision=excluded.revision;
    need:=qty;FOR row IN SELECT x.id FROM public.erp_credit_charges x WHERE x.cafe_id=p_cafe AND x.customer_id=cu AND x.type_id=ty AND NOT x.suspended AND erp_membership_private.charge_allowed(p_cafe,x.id,d) AND x.starts_on<=d AND(x.expires_on IS NULL OR x.expires_on>=d) AND(nullif(p_input->>'chargeId','') IS NULL OR x.id=(p_input->>'chargeId')::uuid) ORDER BY x.expires_on ASC NULLS LAST,x.starts_on,x.number FOR UPDATE LOOP take:=least(need,erp_credit_private.remaining(p_cafe,row.id));IF take>0 THEN INSERT INTO public.erp_credit_allocations VALUES(p_cafe,i,row.id,take);need:=need-take;END IF;EXIT WHEN need=0;END LOOP;
    IF need>0 THEN RAISE EXCEPTION 'الرصيد المتاح لا يكفي للاستهلاك المطلوب';END IF;
   END IF;
  END IF;
 END IF;
 INSERT INTO public.erp_credit_events(cafe_id,record_id,action,actor) VALUES(p_cafe,i,p_action,auth.uid());result:=jsonb_build_object('id',i,'revision',rev+1,'deleted',p_action LIKE '%_delete');INSERT INTO erp_credit_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_customer_default_price_list(p_cafe uuid, p_customer uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE r text;result uuid;cfg jsonb;BEGIN
 r:=brand_finance_private.role_for(p_cafe);IF coalesce(r,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'غير مصرح' USING ERRCODE='42501';END IF;
 cfg:=brand_finance_private.invoice_settings(p_cafe);IF NOT coalesce((cfg#>>'{advanced,priceListsEnabled}')::boolean,false) THEN RETURN NULL;END IF;
 SELECT l.price_list_id INTO result FROM public.erp_customer_portal_links l WHERE l.cafe_id=p_cafe AND l.customer_id=p_customer AND EXISTS(SELECT 1 FROM public.bf_parties p WHERE p.cafe_id=p_cafe AND p.id=p_customer AND p.kind='customer' AND p.active) AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(cfg#>'{advanced,priceLists}','[]')) x WHERE x->>'id'=l.price_list_id::text AND(x->>'active')::boolean AND(jsonb_array_length(coalesce(x->'partyIds','[]'))=0 OR(x->'partyIds')?p_customer::text));RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_customer_forms_read(p_cafe uuid, p_kind text DEFAULT NULL::text, p_record uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE m record;e record;models jsonb:='[]';entries jsonb:='[]';cfg jsonb;visible jsonb;settings boolean;lookups jsonb:='{}';BEGIN
 PERFORM erp_customer_form_private.authorize(p_cafe,'read');PERFORM erp_branch_private.enter(p_cafe);
 settings:=brand_finance_private.role_for(p_cafe)='owner' AND erp_access_private.allowed(p_cafe,'customers','settings');
 IF p_kind IS NOT NULL AND p_kind NOT IN('customers') OR p_record IS NOT NULL AND p_kind IS NULL THEN RAISE EXCEPTION 'Invalid manufacturing record kind' USING ERRCODE='22023';END IF;
 FOR m IN SELECT * FROM public.erp_customer_forms WHERE cafe_id=p_cafe ORDER BY target_kind,kind,key LOOP
  cfg:=m.config;
  IF NOT settings AND NOT erp_customer_form_private.allowed(p_cafe,cfg,'read') THEN CONTINUE;END IF;
  visible:=CASE WHEN settings THEN cfg ELSE cfg-'permissions' END;
  IF NOT settings THEN visible:=jsonb_set(visible,'{fields}',coalesce((SELECT jsonb_agg(CASE WHEN f?'defaultValue' AND NOT erp_customer_form_private.value_scope(p_cafe,jsonb_build_array(f),jsonb_build_object(f->>'id',f->'defaultValue')) THEN f-'defaultValue' ELSE f END) FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=ANY(erp_customer_form_private.fields(p_cafe,cfg,'read'))),'[]'));END IF;
  models:=models||jsonb_build_array(visible||jsonb_build_object('id',m.id,'revision',m.revision,'kind',m.kind,'targetKind',m.target_kind,'key',m.key,'canCreate',coalesce((cfg->>'active')::boolean,false) AND erp_customer_form_private.allowed(p_cafe,cfg,'create'),'canRead',erp_customer_form_private.allowed(p_cafe,cfg,'read'),'canUpdate',coalesce((cfg->>'active')::boolean,false) AND erp_customer_form_private.allowed(p_cafe,cfg,'update'),'canDelete',erp_customer_form_private.allowed(p_cafe,cfg,'delete'),'allowedFields',jsonb_build_object('create',erp_customer_form_private.fields(p_cafe,cfg,'create'),'read',erp_customer_form_private.fields(p_cafe,cfg,'read'),'update',erp_customer_form_private.fields(p_cafe,cfg,'update'))));
  IF NOT erp_customer_form_private.allowed(p_cafe,cfg,'read') THEN CONTINUE;END IF;
  FOR e IN SELECT * FROM public.erp_customer_form_entries WHERE cafe_id=p_cafe AND model_id=m.id AND p_record IS NOT NULL AND record_id=p_record AND target_kind=p_kind ORDER BY created_at,id LOOP
   IF NOT erp_customer_form_private.record_visible(p_cafe,e.record_id,e.target_kind) THEN CONTINUE;END IF;
   entries:=entries||jsonb_build_array(jsonb_build_object('id',e.id,'modelId',e.model_id,'recordId',e.record_id,'targetKind',e.target_kind,'revision',e.revision,'draft',e.draft,'values',erp_customer_form_private.mask(p_cafe,cfg,e.field_values),'createdAt',e.created_at,'canUpdate',coalesce((cfg->>'active')::boolean,false) AND erp_customer_form_private.allowed(p_cafe,cfg,'update'),'canDelete',erp_customer_form_private.allowed(p_cafe,cfg,'delete'),'canFiles',erp_customer_form_private.allowed(p_cafe,cfg,'update') AND erp_access_private.allowed(p_cafe,'customers','files') AND cardinality(erp_customer_form_private.fields(p_cafe,cfg,'read'))=jsonb_array_length(cfg->'fields')));
  END LOOP;
 END LOOP;
 IF settings THEN
  lookups:=jsonb_build_object('branches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.branches WHERE cafe_id=p_cafe),'[]'),'departments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_org_units WHERE cafe_id=p_cafe AND kind='department' AND active),'[]'),'designations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_org_units WHERE cafe_id=p_cafe AND kind='designation' AND active),'[]'),'employees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',first_name||' '||last_name)) FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND active),'[]'),'users',coalesce((SELECT jsonb_agg(jsonb_build_object('id',user_id,'name',name)) FROM public.bf_staff WHERE cafe_id=p_cafe AND active),'[]'),'roles',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_roles WHERE cafe_id=p_cafe AND active),'[]'));
 END IF;
 RETURN jsonb_build_object('models',models,'entries',entries,'canConfigure',settings,'lookups',lookups,'branchScope',public.erp_branch_context(p_cafe)->'scope','events',coalesce((SELECT jsonb_agg(jsonb_build_object('id',ev.id,'recordId',ev.record_id,'action',ev.action,'at',ev.at)) FROM public.erp_customer_form_events ev WHERE ev.cafe_id=p_cafe AND (ev.record_id IS NULL AND settings OR ev.record_id=p_record AND ev.target_kind=p_kind AND erp_customer_form_private.record_visible(p_cafe,ev.record_id,ev.target_kind)) AND EXISTS(SELECT 1 FROM public.erp_customer_forms fm WHERE fm.cafe_id=p_cafe AND fm.id=ev.model_id AND erp_customer_form_private.allowed(p_cafe,fm.config,'read'))),'[]'));
END $function$

CREATE OR REPLACE FUNCTION public.erp_customer_forms_write(p_cafe uuid, p_action text, p_input jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i uuid:=(p_input->>'id')::uuid;rev integer:=(p_input->>'revision')::integer;m public.erp_customer_forms;e public.erp_customer_form_entries;prior erp_customer_form_private.requests;cfg jsonb;v jsonb;r jsonb;a text;k text;tk text;pid uuid;mid uuid;keys text[];result jsonb;rowdata record;BEGIN
 a:=CASE WHEN p_action='model' OR p_action='delete' AND p_input->>'entity'='model' THEN 'settings' WHEN p_action='delete' THEN 'delete' WHEN rev=0 THEN 'create' ELSE 'update' END;
 PERFORM erp_customer_form_private.authorize(p_cafe,a);PERFORM erp_branch_private.assert_context(p_cafe);PERFORM erp_branch_private.enter(p_cafe);
 IF p_action NOT IN('model','entry','delete') OR p_request IS NULL OR i IS NULL OR rev IS NULL OR rev<0 OR jsonb_typeof(p_input)<>'object' OR octet_length(p_input::text)>400000 THEN RAISE EXCEPTION 'بيانات النموذج غير صالحة' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60414));
 SELECT * INTO prior FROM erp_customer_form_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;
 IF FOUND THEN
  IF prior.actor IS DISTINCT FROM auth.uid() OR prior.action<>p_action OR prior.payload<>p_input THEN RAISE EXCEPTION 'معرف عملية مكرر ببيانات مختلفة' USING ERRCODE='40001';END IF;
  IF prior.result->>'recordId' IS NOT NULL AND NOT erp_customer_form_private.record_visible(p_cafe,(prior.result->>'recordId')::uuid,prior.result->>'targetKind') THEN RAISE EXCEPTION 'سجل العملاء غير متاح' USING ERRCODE='42501';END IF;
  SELECT * INTO m FROM public.erp_customer_forms WHERE cafe_id=p_cafe AND id=(prior.result->>'modelId')::uuid;
  IF a<>'settings' AND (m.id IS NULL OR NOT erp_customer_form_private.allowed(p_cafe,m.config,'read') OR NOT erp_customer_form_private.allowed(p_cafe,m.config,a) OR p_action='entry' AND NOT coalesce((m.config->>'active')::boolean,false)) THEN RAISE EXCEPTION 'النموذج غير متاح' USING ERRCODE='42501';END IF;RETURN prior.result;
 END IF;
 IF p_action='model' THEN
  SELECT * INTO m FROM public.erp_customer_forms WHERE cafe_id=p_cafe AND id=i FOR UPDATE;
  IF coalesce(m.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  cfg:=p_input-'id'-'revision';
  IF m.id IS NULL AND (SELECT count(*) FROM public.erp_customer_forms WHERE cafe_id=p_cafe AND target_kind=cfg->>'targetKind')>=60 THEN RAISE EXCEPTION 'بلغت الحد الأقصى لنماذج العملاء' USING ERRCODE='22023';END IF;
  IF coalesce(cfg->>'targetKind','') NOT IN('customers') OR coalesce(cfg->>'kind','') NOT IN('primary','related') OR coalesce(cfg->>'key','')!~'^[a-z][a-z0-9_]{0,59}$' OR length(btrim(coalesce(cfg->>'name',''))) NOT BETWEEN 1 AND 160 OR jsonb_typeof(cfg->'active') IS DISTINCT FROM 'boolean' OR length(coalesce(cfg->>'description',''))>5000 OR jsonb_typeof(cfg->'permissions') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'تعريف النموذج غير صالح' USING ERRCODE='22023';END IF;
  IF m.id IS NOT NULL AND (m.kind<>cfg->>'kind' OR m.target_kind<>cfg->>'targetKind') THEN RAISE EXCEPTION 'لا يمكن تغيير نوع النموذج';END IF;
  PERFORM erp_manufacturing_private.validate_custom_fields(cfg->'fields');
  IF coalesce(cfg->>'nameField','')<>'' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=cfg->>'nameField' AND f->>'type' IN('text','number','date','email','phone')) THEN RAISE EXCEPTION 'اختر حقل اسم صالح';END IF;
  FOREACH k IN ARRAY ARRAY['create','read','update','delete'] LOOP PERFORM erp_workflow_private.validate_selector(p_cafe,cfg#>ARRAY['permissions',k]);END LOOP;
  IF jsonb_typeof(cfg#>'{permissions,fieldRules}') IS DISTINCT FROM 'array' OR jsonb_array_length(cfg#>'{permissions,fieldRules}')>50 THEN RAISE EXCEPTION 'قواعد الحقول غير صالحة';END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(cfg#>'{permissions,fieldRules}') LOOP
   PERFORM (r->>'id')::uuid;PERFORM erp_workflow_private.validate_selector(p_cafe,r->'selector');
   FOREACH k IN ARRAY ARRAY['create','read','update'] LOOP
    IF jsonb_typeof(r->k) IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(r->k) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=x)) THEN RAISE EXCEPTION 'صلاحيات الحقول غير صالحة';END IF;
   END LOOP;
  END LOOP;
  FOR r IN SELECT value FROM jsonb_array_elements(cfg#>'{permissions,fieldRules}') LOOP
   IF NOT ((r->'read') @> (r->'create')) OR NOT ((r->'read') @> (r->'update')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE coalesce((f->>'required')::boolean,false) AND NOT (r->'create')?(f->>'id')) THEN RAISE EXCEPTION 'الحقول المطلوبة والقابلة للتعديل يجب أن تكون متاحة للعرض والإضافة';END IF;
  END LOOP;
  FOR rowdata IN SELECT * FROM public.erp_customer_form_entries WHERE cafe_id=p_cafe AND model_id=i LOOP
   IF EXISTS(SELECT 1 FROM jsonb_object_keys(rowdata.field_values) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=x)) THEN RAISE EXCEPTION 'الحقل يحتوي بيانات محفوظة ولا يمكن حذفه';END IF;
   PERFORM erp_customer_form_private.validate_values(cfg->'fields',rowdata.field_values,p_cafe,rowdata.id,i,0,rowdata.draft);
  END LOOP;
  INSERT INTO public.erp_customer_forms(id,cafe_id,kind,target_kind,key,config) VALUES(i,p_cafe,cfg->>'kind',cfg->>'targetKind',cfg->>'key',cfg) ON CONFLICT(id) DO UPDATE SET config=excluded.config,key=excluded.key,revision=public.erp_customer_forms.revision+1 WHERE public.erp_customer_forms.cafe_id=p_cafe;
  IF NOT FOUND THEN RAISE EXCEPTION 'النموذج غير متاح' USING ERRCODE='42501';END IF;mid:=i;
 ELSIF p_action='entry' THEN
  pid:=(p_input->>'recordId')::uuid;mid:=(p_input->>'modelId')::uuid;tk:=p_input->>'targetKind';
  IF NOT erp_customer_form_private.record_visible(p_cafe,pid,tk) THEN RAISE EXCEPTION 'سجل العملاء غير متاح' USING ERRCODE='42501';END IF;
  SELECT * INTO m FROM public.erp_customer_forms WHERE cafe_id=p_cafe AND id=mid FOR KEY SHARE;
  SELECT * INTO e FROM public.erp_customer_form_entries WHERE cafe_id=p_cafe AND id=i FOR UPDATE;
  IF e.id IS NULL AND (SELECT count(*) FROM public.erp_customer_form_entries WHERE cafe_id=p_cafe AND target_kind=tk AND record_id=pid)>=500 THEN RAISE EXCEPTION 'بلغت الحد الأقصى لسجلات النماذج' USING ERRCODE='22023';END IF;
  IF m.id IS NULL OR m.target_kind IS DISTINCT FROM tk OR NOT coalesce((m.config->>'active')::boolean,false) OR NOT erp_customer_form_private.allowed(p_cafe,m.config,'read') OR NOT erp_customer_form_private.allowed(p_cafe,m.config,a) THEN RAISE EXCEPTION 'النموذج غير متاح' USING ERRCODE='42501';END IF;
  IF e.id IS NOT NULL AND (e.record_id<>pid OR e.model_id<>mid OR e.target_kind<>tk) THEN RAISE EXCEPTION 'لا يمكن نقل سجل النموذج';END IF;
  IF coalesce(e.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(p_input->'draft') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'values') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'قيم النموذج غير صالحة';END IF;
  keys:=erp_customer_form_private.fields(p_cafe,m.config,a);
  FOR k,v IN SELECT * FROM jsonb_each(p_input->'values') LOOP IF NOT k=ANY(keys) THEN RAISE EXCEPTION 'لا تملك صلاحية تعديل الحقل' USING ERRCODE='42501';END IF;END LOOP;
  v:=coalesce(e.field_values,'{}')||(p_input->'values');v:=erp_manufacturing_private.custom_defaults(m.config->'fields',v);
  IF NOT erp_customer_form_private.value_scope(p_cafe,m.config->'fields',v) THEN RAISE EXCEPTION 'مرجع الحقل غير متاح في الفرع' USING ERRCODE='42501';END IF;
  PERFORM erp_customer_form_private.validate_values(m.config->'fields',v,p_cafe,i,mid,0,(p_input->>'draft')::boolean);
  INSERT INTO public.erp_customer_form_entries(id,cafe_id,model_id,model_kind,target_kind,record_id,draft,field_values,created_by) VALUES(i,p_cafe,mid,m.kind,tk,pid,(p_input->>'draft')::boolean,v,auth.uid()) ON CONFLICT(id) DO UPDATE SET field_values=excluded.field_values,draft=excluded.draft,revision=public.erp_customer_form_entries.revision+1,updated_at=now() WHERE public.erp_customer_form_entries.cafe_id=p_cafe;
  IF NOT FOUND THEN RAISE EXCEPTION 'السجل غير متاح' USING ERRCODE='42501';END IF;
 ELSIF p_input->>'entity'='model' THEN
  SELECT * INTO m FROM public.erp_customer_forms WHERE cafe_id=p_cafe AND id=i FOR UPDATE;
  IF m.id IS NULL OR m.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  DELETE FROM public.erp_customer_forms WHERE cafe_id=p_cafe AND id=i;mid:=i;
 ELSIF p_input->>'entity'='entry' THEN
  e:=erp_customer_form_private.assert_entry(p_cafe,i,'delete');pid:=e.record_id;mid:=e.model_id;tk:=e.target_kind;
  IF e.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  DELETE FROM public.erp_customer_form_entries WHERE cafe_id=p_cafe AND id=i;
 ELSE RAISE EXCEPTION 'نوع السجل غير صالح';END IF;
 result:=jsonb_build_object('id',i,'modelId',mid,'recordId',pid,'targetKind',tk,'revision',rev+1);
 INSERT INTO public.erp_customer_form_events(cafe_id,record_id,target_kind,model_id,entry_id,action,actor) VALUES(p_cafe,pid,tk,mid,CASE WHEN pid IS NOT NULL THEN i END,p_action,auth.uid());
 INSERT INTO erp_customer_form_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_customer_portal_read(p_cafe uuid, p_profile uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE l public.erp_customer_portal_links;cfg jsonb;result jsonb;customer public.bf_parties;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe AND status IN('active','published') AND deleted_at IS NULL) OR NOT platform_access_private.service_enabled(p_cafe,'finance') THEN RAISE EXCEPTION 'بوابة العلامة غير متاحة' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.customer_profiles WHERE cafe_id=p_cafe AND id=p_profile) THEN RAISE EXCEPTION 'حساب العميل غير متاح' USING ERRCODE='42501';END IF;
 cfg:=erp_customer_private.portal_settings(p_cafe);SELECT * INTO l FROM public.erp_customer_portal_links WHERE cafe_id=p_cafe AND profile_id=p_profile AND enabled;SELECT * INTO customer FROM public.bf_parties WHERE cafe_id=p_cafe AND id=l.customer_id AND kind='customer' AND active;
 IF NOT(cfg->>'enabled')::boolean OR customer.id IS NULL THEN RAISE EXCEPTION 'بوابة العميل غير مفعلة لهذا الحساب' USING ERRCODE='42501';END IF;
 result:=jsonb_build_object('customer',jsonb_build_object('id',customer.id,'name',customer.name),'permissions',cfg->'permissions');
 IF(cfg#>>'{permissions,invoices}')::boolean THEN result:=result||jsonb_build_object('invoices',coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.id,'number',coalesce(e.display_number,d.number::text),'date',d.created_at,'total',d.total,'outstanding',(brand_finance_private.document_state(p_cafe,d.id)->>'outstanding')::numeric,'refunded',(brand_finance_private.document_state(p_cafe,d.id)->>'refunded_total')::numeric,'document',CASE WHEN i.document_id IS NULL THEN NULL ELSE jsonb_build_object('seller',i.snapshot->'seller','currency',i.snapshot->>'currency','total',i.snapshot->'total','tax',i.snapshot->'tax','discount',i.snapshot->'discount','lines',(SELECT jsonb_agg(jsonb_build_object('name',x->>'name','quantity',x->'quantity','price',x->'price','tax',x->'tax','total',x->'total')) FROM jsonb_array_elements(i.snapshot->'lines') x)) END) ORDER BY d.created_at DESC) FROM public.bf_documents d LEFT JOIN public.bf_company_invoices i ON i.cafe_id=d.cafe_id AND i.document_id=d.id LEFT JOIN public.bf_invoice_extensions e ON e.cafe_id=d.cafe_id AND e.document_id=d.id WHERE d.cafe_id=p_cafe AND d.party_id=customer.id AND d.kind='sale'),'[]'));END IF;
 IF(cfg#>>'{permissions,statement}')::boolean THEN
  WITH rows AS(SELECT j.id,d.created_at AS date,d.number,d.kind,j.debit,j.credit,sum(j.debit-j.credit) OVER(ORDER BY d.created_at,j.created_at,j.id ROWS UNBOUNDED PRECEDING) AS balance FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id AND a.kind='receivable' JOIN public.bf_documents d ON d.cafe_id=j.cafe_id AND d.id=j.document_id WHERE j.cafe_id=p_cafe AND j.party_id=customer.id)
  SELECT result||jsonb_build_object('statement',coalesce(jsonb_agg(to_jsonb(rows)-'id' ORDER BY date,id),'[]'),'balance',coalesce(sum(debit-credit),0)) INTO result FROM rows;
 END IF;
 IF(cfg#>>'{permissions,appointments}')::boolean THEN result:=result||jsonb_build_object('appointments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'startsAt',starts_at,'duration',duration,'action',action,'status',status) ORDER BY starts_at DESC) FROM public.erp_customer_appointments WHERE cafe_id=p_cafe AND customer_id=customer.id AND share_with_customer),'[]'));END IF;
 IF(cfg#>>'{permissions,memberships}')::boolean THEN result:=result||jsonb_build_object('memberships',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'number',m.number,'packageName',p.name,'joinedOn',m.joined_on,'endsOn',(SELECT max(erp_membership_private.end_date(p_cafe,r.id)) FROM public.erp_membership_renewals r WHERE r.cafe_id=p_cafe AND r.membership_id=m.id AND r.status='paid'),'status',erp_membership_private.status(p_cafe,m.id)) ORDER BY m.created_at DESC) FROM public.erp_memberships m JOIN public.erp_credit_packages p ON p.cafe_id=m.cafe_id AND p.id=m.package_id WHERE m.cafe_id=p_cafe AND m.customer_id=customer.id AND NOT m.deleted),'[]'));END IF;
 IF(cfg#>>'{permissions,credits}')::boolean THEN result:=result||jsonb_build_object('credits',coalesce((SELECT jsonb_agg(jsonb_build_object('id',ch.id,'type',t.name,'unit',t.unit,'quantity',ch.quantity,'remaining',ch.quantity-coalesce((SELECT sum(a.quantity) FROM public.erp_credit_allocations a WHERE a.cafe_id=ch.cafe_id AND a.charge_id=ch.id),0),'startsOn',ch.starts_on,'expiresOn',ch.expires_on,'available',(CASE WHEN ch.source_kind='membership_renewal' THEN EXISTS(SELECT 1 FROM public.erp_membership_renewals rr LEFT JOIN public.erp_memberships mm ON mm.cafe_id=rr.cafe_id AND mm.id=rr.membership_id WHERE rr.cafe_id=p_cafe AND rr.id=ch.source_id AND rr.status='paid' AND NOT coalesce(mm.suspended OR mm.deleted,false)) ELSE NOT ch.suspended END) AND ch.starts_on<=current_date AND(ch.expires_on IS NULL OR ch.expires_on>=current_date) AND erp_membership_private.charge_allowed(p_cafe,ch.id,current_date)) ORDER BY ch.created_at DESC) FROM public.erp_credit_charges ch JOIN public.erp_credit_types t ON t.cafe_id=ch.cafe_id AND t.id=ch.type_id WHERE ch.cafe_id=p_cafe AND ch.customer_id=customer.id),'[]'));END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_customer_services(p_cafe uuid, p_customer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE result jsonb:='{}';s jsonb;BEGIN
 PERFORM erp_customer_private.authorize(p_cafe,'read');IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=p_customer AND kind='customer') THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
 IF erp_access_private.allowed(p_cafe,'memberships','read') THEN s:=public.erp_memberships_read(p_cafe);result:=result||jsonb_build_object('memberships',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'memberships') x WHERE x->>'customerId'=p_customer::text),'[]'),'packages',s->'packages');END IF;
 IF erp_access_private.allowed(p_cafe,'credits','read') THEN s:=public.erp_credits_read(p_cafe);result:=result||jsonb_build_object('charges',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'charges') x WHERE x->>'customerId'=p_customer::text),'[]'),'usages',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'usages') x WHERE x->>'customerId'=p_customer::text),'[]'),'types',s->'types');END IF;
 IF erp_access_private.allowed(p_cafe,'insurance','read') THEN s:=public.erp_insurance_read(p_cafe);s:=jsonb_set(s,'{customers}',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'customers') x WHERE x->>'id'=p_customer::text),'[]'));s:=jsonb_set(s,'{enrollments}',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'enrollments') x WHERE x->>'customerId'=p_customer::text),'[]'));s:=jsonb_set(s,'{invoices}',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'invoices') x WHERE x->>'customerId'=p_customer::text),'[]'));s:=jsonb_set(s,'{drafts}',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'drafts') x WHERE x->>'customerId'=p_customer::text),'[]'));result:=result||jsonb_build_object('insurance',s);END IF;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_employee_asset_act(p_cafe uuid, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.erp_employee_assets;before_row jsonb;req uuid:=(p_command->>'requestId')::uuid;prior erp_employee_asset_private.requests;rid uuid:=(p_command->>'id')::uuid;op text:=p_command->>'action';effective timestamptz:=(p_command->>'effectiveAt')::timestamptz;note text:=coalesce(p_command->>'note','');loc uuid;person uuid;profile_id uuid;kind text;expected date;assigned timestamptz;result jsonb;BEGIN PERFORM erp_access_private.assert_allowed(p_cafe,'custody',erp_access_private.action(p_command->>'action',p_command));
 PERFORM erp_employee_asset_private.authorize(p_cafe,true);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 IF req IS NULL OR effective IS NULL OR NOT isfinite(effective) OR effective>now()+interval '5 minutes' OR length(note)>20000 OR octet_length(p_command::text)>65536 THEN RAISE EXCEPTION 'بيانات الحركة أو تاريخها غير صالحة';END IF;
 SELECT * INTO prior FROM erp_employee_asset_private.requests WHERE cafe_id=p_cafe AND request_id=req;IF FOUND THEN IF prior.payload<>p_command OR prior.actor_id<>auth.uid() THEN RAISE EXCEPTION 'تعارض معرف الطلب';END IF;RETURN prior.result||'{"duplicate":true}';END IF;
 SELECT * INTO a FROM public.erp_employee_assets WHERE cafe_id=p_cafe AND id=rid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'الأصل غير موجود' USING ERRCODE='42501';END IF;IF a.revision IS DISTINCT FROM (p_command->>'revision')::integer THEN RAISE EXCEPTION 'تغير الأصل أعد تحميل الصفحة' USING ERRCODE='40001';END IF;before_row:=to_jsonb(a)-'cafe_id'-'created_by';
 IF op<>'note' AND effective<(SELECT max(effective_at) FROM public.erp_employee_asset_events WHERE cafe_id=p_cafe AND record_id=rid AND action NOT IN('note','edit')) THEN RAISE EXCEPTION 'تاريخ الحركة يسبق آخر حركة عهدة';END IF;
 IF a.status='retired' AND op<>'note' THEN RAISE EXCEPTION 'الأصل مستبعد محاسبيًا';END IF;
 CASE op
 WHEN 'assign' THEN
  IF a.status NOT IN('available','assigned') THEN RAISE EXCEPTION 'الأصل غير متاح للتعيين';END IF;
  kind:=p_command->>'holderKind';person:=nullif(p_command->>'holderUserId','')::uuid;profile_id:=nullif(p_command->>'holderEmployeeId','')::uuid;loc:=nullif(p_command->>'locationId','')::uuid;expected:=nullif(p_command->>'expectedReturnOn','')::date;
  IF kind NOT IN('employee','warehouse') THEN RAISE EXCEPTION 'اختر الموظف أو المخزن';END IF;PERFORM erp_employee_asset_private.validate_holder_profile(p_cafe,kind,person,loc,effective,expected,profile_id);
  UPDATE public.erp_employee_assets SET holder_kind=kind,holder_user_id=CASE WHEN kind='employee' THEN person END,holder_employee_id=CASE WHEN kind='employee' THEN profile_id END,location_id=loc,status='assigned',assigned_at=effective,expected_return_on=expected WHERE cafe_id=p_cafe AND id=rid;
 WHEN 'return' THEN
  IF a.status<>'assigned' THEN RAISE EXCEPTION 'لا توجد عهدة مخصصة للإرجاع';END IF;loc:=coalesce(nullif(p_command->>'locationId','')::uuid,a.location_id);PERFORM erp_employee_asset_private.validate_holder(p_cafe,'unassigned',null,loc,null,null);
  UPDATE public.erp_employee_assets SET holder_kind='unassigned',holder_user_id=null,holder_employee_id=null,location_id=loc,status='available',assigned_at=null,expected_return_on=null WHERE cafe_id=p_cafe AND id=rid;
 WHEN 'maintenance' THEN
  IF a.status NOT IN('available','assigned') THEN RAISE EXCEPTION 'الأصل غير متاح للصيانة';END IF;IF btrim(note)='' THEN RAISE EXCEPTION 'أدخل ملاحظة الصيانة';END IF;
  UPDATE public.erp_employee_assets SET maintenance_previous=before_row,holder_kind='unassigned',holder_user_id=null,holder_employee_id=null,status='maintenance',assigned_at=null,expected_return_on=null WHERE cafe_id=p_cafe AND id=rid;
 WHEN 'restore_maintenance' THEN
  IF a.status<>'maintenance' THEN RAISE EXCEPTION 'الأصل ليس في الصيانة';END IF;IF btrim(note)='' THEN RAISE EXCEPTION 'أدخل ملاحظة انتهاء الصيانة';END IF;
  IF coalesce((p_command->>'restorePrevious')::boolean,true) THEN kind:=coalesce(a.maintenance_previous->>'holder_kind','unassigned');person:=(a.maintenance_previous->>'holder_user_id')::uuid;profile_id:=(a.maintenance_previous->>'holder_employee_id')::uuid;loc:=coalesce((a.maintenance_previous->>'location_id')::uuid,a.location_id);assigned:=(a.maintenance_previous->>'assigned_at')::timestamptz;expected:=(a.maintenance_previous->>'expected_return_on')::date;
  ELSE kind:='unassigned';loc:=a.location_id;END IF;PERFORM erp_employee_asset_private.validate_holder_profile(p_cafe,kind,person,loc,assigned,expected,profile_id);
  UPDATE public.erp_employee_assets SET holder_kind=kind,holder_user_id=CASE WHEN kind='employee' THEN person END,holder_employee_id=CASE WHEN kind='employee' THEN profile_id END,location_id=loc,status=CASE WHEN kind='unassigned' THEN 'available' ELSE 'assigned' END,assigned_at=assigned,expected_return_on=expected,maintenance_previous=null WHERE cafe_id=p_cafe AND id=rid;
 WHEN 'stop' THEN IF a.status<>'available' THEN RAISE EXCEPTION 'أرجع العهدة قبل إيقاف الأصل';END IF;UPDATE public.erp_employee_assets SET status='stopped' WHERE cafe_id=p_cafe AND id=rid;
 WHEN 'resume' THEN IF a.status<>'stopped' THEN RAISE EXCEPTION 'الأصل ليس متوقفًا';END IF;UPDATE public.erp_employee_assets SET status='available' WHERE cafe_id=p_cafe AND id=rid;
 WHEN 'note' THEN IF btrim(note)='' THEN RAISE EXCEPTION 'أدخل الملاحظة';END IF;
 WHEN 'delete' THEN IF a.status<>'available' OR EXISTS(SELECT 1 FROM public.erp_employee_asset_events WHERE cafe_id=p_cafe AND record_id=rid AND action NOT IN('create','edit','note')) THEN RAISE EXCEPTION 'لا يمكن حذف أصل له حركات عهدة';END IF;DELETE FROM public.erp_employee_assets WHERE cafe_id=p_cafe AND id=rid;
 ELSE RAISE EXCEPTION 'حركة العهدة غير مدعومة';END CASE;
 IF op<>'delete' THEN UPDATE public.erp_employee_assets SET revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe AND id=rid;END IF;
 INSERT INTO public.erp_employee_asset_events(cafe_id,record_id,action,effective_at,note,before_state,after_state,actor_id) VALUES(p_cafe,rid,op,effective,note,before_row,coalesce((SELECT to_jsonb(x)-'cafe_id'-'created_by' FROM public.erp_employee_assets x WHERE cafe_id=p_cafe AND id=rid),'{}'),auth.uid());
 result:=jsonb_build_object('id',rid,'revision',coalesce((SELECT revision FROM public.erp_employee_assets WHERE cafe_id=p_cafe AND id=rid),a.revision+1),'deleted',op='delete');INSERT INTO erp_employee_asset_private.requests VALUES(p_cafe,req,p_command,result,auth.uid());RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_employee_asset_save(p_cafe uuid, p_payload jsonb, p_id uuid DEFAULT NULL::uuid, p_revision integer DEFAULT 0, p_request uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE old public.erp_employee_assets;unit public.erp_asset_units;rid uuid:=coalesce(p_id,gen_random_uuid());prior erp_employee_asset_private.requests;req jsonb;result jsonb;photo uuid:=nullif(p_payload->>'photoId','')::uuid;holder text:=p_payload->>'holderKind';person uuid:=nullif(p_payload->>'holderUserId','')::uuid;profile_id uuid:=nullif(p_payload->>'holderEmployeeId','')::uuid;location uuid:=(p_payload->>'locationId')::uuid;assigned timestamptz:=nullif(p_payload->>'assignedAt','')::timestamptz;expected date:=nullif(p_payload->>'expectedReturnOn','')::date;linked uuid:=nullif(p_payload->>'financialUnitId','')::uuid;typeid uuid:=nullif(p_payload->>'typeId','')::uuid;BEGIN PERFORM erp_access_private.assert_allowed(p_cafe,'custody',CASE WHEN p_revision=0 THEN 'create' ELSE 'update' END);
 PERFORM erp_employee_asset_private.authorize(p_cafe,true);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 IF p_request IS NULL OR coalesce(jsonb_typeof(p_payload),'')<>'object' OR octet_length(p_payload::text)>65536 THEN RAISE EXCEPTION 'بيانات الأصل غير صالحة';END IF;
 req:=jsonb_build_object('save',p_payload,'id',p_id,'revision',p_revision);SELECT * INTO prior FROM erp_employee_asset_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;
 IF FOUND THEN IF prior.payload<>req OR prior.actor_id<>auth.uid() THEN RAISE EXCEPTION 'تعارض معرف الطلب';END IF;RETURN prior.result||'{"duplicate":true}';END IF;
 IF p_id IS NOT NULL THEN SELECT * INTO old FROM public.erp_employee_assets WHERE cafe_id=p_cafe AND id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'الأصل غير موجود' USING ERRCODE='42501';END IF;IF old.revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'تغير الأصل أعد تحميل الصفحة' USING ERRCODE='40001';END IF;
  IF old.status='retired' OR old.financial_unit_id IS DISTINCT FROM linked THEN RAISE EXCEPTION 'لا تعدل ارتباط الأصل المحاسبي بعد إنشاء العهدة';END IF;
  IF old.holder_kind IS DISTINCT FROM holder OR old.holder_user_id IS DISTINCT FROM (CASE WHEN holder='employee' THEN person END) OR old.holder_employee_id IS DISTINCT FROM (CASE WHEN holder='employee' THEN profile_id END) OR old.location_id IS DISTINCT FROM location OR old.assigned_at IS DISTINCT FROM assigned OR old.expected_return_on IS DISTINCT FROM expected THEN RAISE EXCEPTION 'استخدم تعيين الأصل أو إرجاع العهدة لتغيير معلومات الحفظ';END IF;
 END IF;
 PERFORM erp_employee_asset_private.validate_holder_profile(p_cafe,holder,person,location,assigned,expected,profile_id);
 IF typeid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_employee_asset_types WHERE cafe_id=p_cafe AND id=typeid AND (active OR old.type_id=typeid)) THEN RAISE EXCEPTION 'نوع الأصل غير موجود أو غير نشط';END IF;
 IF linked IS NOT NULL THEN SELECT * INTO unit FROM public.erp_asset_units WHERE cafe_id=p_cafe AND id=linked FOR UPDATE;IF NOT FOUND OR unit.status<>'in_service' THEN RAISE EXCEPTION 'الوحدة المحاسبية غير متاحة';END IF;END IF;
 IF photo IS NOT NULL THEN
  PERFORM 1 FROM public.erp_files f WHERE f.cafe_id=p_cafe AND f.entity_type='employee_asset' AND f.record_id=p_id AND f.id=photo AND f.uploaded AND f.mime IN('image/jpeg','image/png') AND EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='erp-record-files' AND o.name=f.path) FOR KEY SHARE OF f;
  IF NOT FOUND THEN RAISE EXCEPTION 'اختر صورة محفوظة ومتاحة لهذا الأصل';END IF;
 END IF;
 IF p_id IS NULL THEN INSERT INTO public.erp_employee_assets(id,cafe_id,name,code,financial_unit_id,type_id,location_id,holder_kind,holder_user_id,holder_employee_id,status,serial,barcode,warranty_on,description,specifications,photo_id,assigned_at,expected_return_on,created_by) VALUES(rid,p_cafe,btrim(p_payload->>'name'),btrim(p_payload->>'code'),linked,typeid,location,holder,CASE WHEN holder='employee' THEN person END,CASE WHEN holder='employee' THEN profile_id END,CASE WHEN holder='unassigned' THEN 'available' ELSE 'assigned' END,coalesce(p_payload->>'serial',''),coalesce(p_payload->>'barcode',''),nullif(p_payload->>'warrantyOn','')::date,coalesce(p_payload->>'description',''),coalesce(p_payload->>'specifications',''),photo,CASE WHEN holder<>'unassigned' THEN coalesce(assigned,now()) END,expected,auth.uid());
 ELSE UPDATE public.erp_employee_assets SET name=btrim(p_payload->>'name'),code=btrim(p_payload->>'code'),type_id=typeid,serial=coalesce(p_payload->>'serial',''),barcode=coalesce(p_payload->>'barcode',''),warranty_on=nullif(p_payload->>'warrantyOn','')::date,description=coalesce(p_payload->>'description',''),specifications=coalesce(p_payload->>'specifications',''),photo_id=photo,revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe AND id=rid;END IF;
 INSERT INTO public.erp_employee_asset_events(cafe_id,record_id,action,effective_at,before_state,after_state,actor_id) SELECT p_cafe,rid,CASE WHEN p_id IS NULL THEN 'create' ELSE 'edit' END,now(),coalesce(to_jsonb(old)-'cafe_id'-'created_by','{}'),to_jsonb(a)-'cafe_id'-'created_by',auth.uid() FROM public.erp_employee_assets a WHERE cafe_id=p_cafe AND id=rid;
 SELECT jsonb_build_object('id',rid,'revision',revision) INTO result FROM public.erp_employee_assets WHERE cafe_id=p_cafe AND id=rid;INSERT INTO erp_employee_asset_private.requests VALUES(p_cafe,p_request,req,result,auth.uid());RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_employee_asset_type(p_cafe uuid, p_payload jsonb, p_id uuid DEFAULT NULL::uuid, p_revision integer DEFAULT 0, p_delete boolean DEFAULT false, p_request uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE old public.erp_employee_asset_types;rid uuid:=coalesce(p_id,gen_random_uuid());req jsonb:=jsonb_build_object('type',p_payload,'id',p_id,'revision',p_revision,'delete',p_delete);prior erp_employee_asset_private.requests;result jsonb;BEGIN PERFORM erp_access_private.assert_allowed(p_cafe,'custody',CASE WHEN p_delete THEN 'delete' ELSE 'settings' END);
 PERFORM erp_employee_asset_private.authorize(p_cafe,true);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));IF p_request IS NULL OR octet_length(p_payload::text)>10000 THEN RAISE EXCEPTION 'بيانات النوع غير صالحة';END IF;
 SELECT * INTO prior FROM erp_employee_asset_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.payload<>req OR prior.actor_id<>auth.uid() THEN RAISE EXCEPTION 'تعارض معرف الطلب';END IF;RETURN prior.result||'{"duplicate":true}';END IF;
 IF p_id IS NOT NULL THEN SELECT * INTO old FROM public.erp_employee_asset_types WHERE cafe_id=p_cafe AND id=p_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'نوع الأصل غير موجود' USING ERRCODE='42501';END IF;IF old.revision IS DISTINCT FROM p_revision THEN RAISE EXCEPTION 'تغير نوع الأصل أعد تحميل الصفحة' USING ERRCODE='40001';END IF;END IF;
 IF p_delete THEN IF p_id IS NULL THEN RAISE EXCEPTION 'اختر نوع الأصل';END IF;DELETE FROM public.erp_employee_asset_types WHERE cafe_id=p_cafe AND id=p_id;
 ELSIF p_id IS NULL THEN INSERT INTO public.erp_employee_asset_types(id,cafe_id,name,description,active) VALUES(rid,p_cafe,btrim(p_payload->>'name'),coalesce(p_payload->>'description',''),coalesce((p_payload->>'active')::boolean,true));
 ELSE UPDATE public.erp_employee_asset_types SET name=btrim(p_payload->>'name'),description=coalesce(p_payload->>'description',''),active=coalesce((p_payload->>'active')::boolean,true),revision=revision+1 WHERE cafe_id=p_cafe AND id=rid;END IF;
 result:=jsonb_build_object('id',rid,'deleted',p_delete);INSERT INTO erp_employee_asset_private.requests VALUES(p_cafe,p_request,req,result,auth.uid());RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_file(p_cafe_id uuid, p_action text, p_type text, p_record_id uuid, p_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE f public.erp_files; result jsonb; suffix text;
BEGIN
 PERFORM erp_file_private.assert_record(p_cafe_id,p_type,p_record_id,p_action IN('prepare','complete','remove'));
 IF p_action='list' THEN RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id'-'created_by'-'sha256' ORDER BY created_at) FROM public.erp_files x WHERE cafe_id=p_cafe_id AND entity_type=p_type AND record_id=p_record_id),'[]'); END IF;
 IF p_id IS NULL THEN RAISE EXCEPTION 'معرف الملف مطلوب' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 SELECT * INTO f FROM public.erp_files WHERE id=p_id FOR UPDATE;
 IF FOUND AND (f.cafe_id<>p_cafe_id OR f.entity_type<>p_type OR f.record_id<>p_record_id) THEN RAISE EXCEPTION 'الملف غير متاح' USING ERRCODE='42501'; END IF;
 IF p_action='prepare' THEN
  IF p_type<>'document_template' AND p_metadata->>'mime' IN('text/csv','text/plain','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') THEN RAISE EXCEPTION 'نوع الملف غير مسموح لهذا السجل' USING ERRCODE='22023';END IF;
  IF f.id IS NOT NULL THEN
   IF f.sha256 IS DISTINCT FROM p_metadata->>'sha256' OR f.size_bytes IS DISTINCT FROM (p_metadata->>'size')::integer OR f.name IS DISTINCT FROM p_metadata->>'name' OR f.mime IS DISTINCT FROM p_metadata->>'mime' OR f.created_by<>auth.uid() THEN RAISE EXCEPTION 'معرف الملف مستخدم لمحتوى آخر' USING ERRCODE='22023'; END IF;
   RETURN to_jsonb(f)-'cafe_id'-'created_by';
  END IF;
  suffix:=CASE p_metadata->>'mime' WHEN 'image/jpeg' THEN 'jpg' WHEN 'image/png' THEN 'png' WHEN 'application/pdf' THEN 'pdf' WHEN 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' THEN 'docx' WHEN 'text/csv' THEN 'csv' WHEN 'text/plain' THEN 'txt' WHEN 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' THEN 'xlsx' END;
  IF suffix IS NULL THEN RAISE EXCEPTION 'نوع الملف غير مسموح' USING ERRCODE='22023'; END IF;
  INSERT INTO public.erp_files(id,cafe_id,entity_type,record_id,name,mime,size_bytes,sha256,path,created_by) VALUES(p_id,p_cafe_id,p_type,p_record_id,p_metadata->>'name',p_metadata->>'mime',(p_metadata->>'size')::integer,p_metadata->>'sha256',p_cafe_id::text||'/'||p_id::text||'.'||suffix,auth.uid()) RETURNING * INTO f;
 ELSIF f.id IS NULL THEN RAISE EXCEPTION 'الملف غير موجود' USING ERRCODE='22023';
 ELSIF p_action='complete' THEN
  IF f.created_by<>auth.uid() THEN RAISE EXCEPTION 'لا تملك صلاحية إكمال هذا الرفع' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='erp-record-files' AND name=f.path AND (metadata->>'size')::bigint=f.size_bytes AND metadata->>'mimetype'=f.mime) THEN RAISE EXCEPTION 'لم يكتمل رفع الملف' USING ERRCODE='22023'; END IF;
  UPDATE public.erp_files SET uploaded=true WHERE id=p_id RETURNING * INTO f;
 ELSIF p_action='remove' THEN
  -- Physical Storage deletion is performed through its API before removing the link.
  IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='erp-record-files' AND name=f.path) THEN RAISE EXCEPTION 'أكمل حذف الملف من التخزين أولًا' USING ERRCODE='22023'; END IF;
  DELETE FROM public.erp_files WHERE id=p_id;
 ELSIF p_action<>'get' THEN RAISE EXCEPTION 'إجراء ملف غير معروف' USING ERRCODE='22023'; END IF;
 RETURN to_jsonb(f)-'cafe_id'-'created_by';
END $function$

CREATE OR REPLACE FUNCTION public.erp_file_access(p_path text, p_write boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE f public.erp_files;
BEGIN
 SELECT * INTO f FROM public.erp_files WHERE path=p_path;
 IF NOT FOUND THEN RETURN false; END IF;
 PERFORM erp_file_private.assert_record(f.cafe_id,f.entity_type,f.record_id,p_write);
 RETURN CASE WHEN p_write THEN f.created_by=auth.uid() AND NOT f.uploaded ELSE f.uploaded OR f.created_by=auth.uid() END;
EXCEPTION WHEN SQLSTATE '42501' OR SQLSTATE '22023' THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.erp_finance_generate_due(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE branch_prior jsonb;s public.erp_finance_schedules;n integer:=0;failed integer:=0;old_sub text:=current_setting('request.jwt.claim.sub',true);old_claims text:=current_setting('request.jwt.claims',true);BEGIN
 FOR s IN SELECT * FROM public.erp_finance_schedules WHERE public.brand_account_not_cancelled(cafe_id) AND active AND next_date<=(now() AT TIME ZONE 'Asia/Riyadh')::date ORDER BY next_date LIMIT least(greatest(p_limit,1),200) LOOP
  BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(s.cafe_id::text,60412));IF NOT EXISTS(SELECT 1 FROM public.erp_finance_schedules WHERE cafe_id=s.cafe_id AND id=s.id AND active AND revision=s.revision AND next_date=s.next_date) THEN CONTINUE;END IF;PERFORM set_config('request.jwt.claim.sub',s.created_by::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',s.created_by)::text,true);branch_prior:=erp_branch_private.enter_job(s.cafe_id,'erp_finance_schedules',s.id,s.created_by);PERFORM erp_finance_private.generate_schedule(s.cafe_id,s.id);PERFORM erp_branch_private.exit_job(branch_prior);n:=n+1;
  EXCEPTION WHEN OTHERS THEN UPDATE public.erp_finance_schedules SET last_error='تعذر إنشاء السند راجع الصلاحيات والفترة والحقول والرصيد',active=false,revision=revision+1 WHERE cafe_id=s.cafe_id AND id=s.id;failed:=failed+1;END;
 END LOOP;
 PERFORM set_config('request.jwt.claim.sub',coalesce(old_sub,''),true);PERFORM set_config('request.jwt.claims',coalesce(old_claims,''),true);RETURN jsonb_build_object('generated',n,'failed',failed);
END $function$

CREATE OR REPLACE FUNCTION public.erp_hr_import(p_cafe_id uuid, p_rows jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE previous erp_hr_private.requests;row jsonb;ids jsonb:='[]';result jsonb;BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'hr','create');
 PERFORM erp_hr_private.authorize(p_cafe_id,true);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,83421));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,92500));
 IF p_request_id IS NULL OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rows) NOT BETWEEN 1 AND 100 OR octet_length(p_rows::text)>4000000 THEN RAISE EXCEPTION 'ملف الاستيراد يتجاوز الحد المسموح';END IF;
 SELECT * INTO previous FROM erp_hr_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF previous.actor<>auth.uid() OR previous.action<>'import' OR previous.payload<>p_rows THEN RAISE EXCEPTION 'معرف الاستيراد مستخدم لمحتوى آخر';END IF;RETURN previous.result;END IF;
 FOR row IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
  IF row->>'id' IS NOT NULL OR row->>'userId' IS NOT NULL THEN RAISE EXCEPTION 'الاستيراد مخصص لموظفين جدد دون حساب دخول';END IF;
  result:=public.erp_hr_write(p_cafe_id,'save_employee',row,gen_random_uuid());ids:=ids||jsonb_build_array(result->>'id');
 END LOOP;
 result:=jsonb_build_object('ids',ids,'count',jsonb_array_length(ids));INSERT INTO erp_hr_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),'import',p_rows,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_hr_write(p_cafe_id uuid, p_action text, p_data jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
DECLARE previous erp_hr_private.requests;rid uuid:=(p_data->>'id')::uuid;old public.erp_hr_employees;doc public.erp_hr_document_types;settings public.erp_hr_settings;rev integer;result jsonb;v_code text;counter bigint;template public.erp_task_templates;flow uuid;parent uuid;manager_user uuid;sync_prior text;BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'hr',erp_access_private.action(p_action,p_data));
 PERFORM erp_hr_private.authorize(p_cafe_id,true);PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,83421));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,92500));
 IF p_request_id IS NULL OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR octet_length(p_data::text)>50000 THEN RAISE EXCEPTION 'طلب الموظفين غير صالح';END IF;
 SELECT * INTO previous FROM erp_hr_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF previous.actor<>auth.uid() OR previous.action<>p_action OR previous.payload<>p_data THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى';END IF;RETURN previous.result;END IF;
 IF p_action='save_employee' THEN
  IF rid IS NOT NULL THEN SELECT * INTO old FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id AND id=rid FOR UPDATE;IF NOT FOUND OR old.revision IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير ملف الموظف أعد تحميله' USING ERRCODE='40001';END IF;ELSE rid:=gen_random_uuid();END IF;
  PERFORM erp_hr_private.validate(p_cafe_id,p_data,rid);v_code:=btrim(coalesce(p_data->>'code',''));
  IF v_code='' THEN IF old.id IS NOT NULL THEN v_code:=old.code;ELSE SELECT coalesce(max(number),0)+1 INTO counter FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id;LOOP v_code:='EMP-'||counter;EXIT WHEN NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id AND erp_hr_employees.code=v_code);counter:=counter+1;END LOOP;END IF;END IF;
  INSERT INTO public.erp_hr_employees(id,cafe_id,code,first_name,last_name,active,user_id,payload,branch_id,department_id,designation_id,level_id,type_id,manager_id) VALUES(rid,p_cafe_id,v_code,btrim(p_data->>'firstName'),btrim(coalesce(p_data->>'lastName','')),(p_data->>'active')::boolean,(p_data->>'userId')::uuid,p_data-ARRAY['id','revision'],(p_data->>'branchId')::uuid,(p_data->>'departmentId')::uuid,(p_data->>'designationId')::uuid,(p_data->>'levelId')::uuid,(p_data->>'typeId')::uuid,(p_data->>'managerId')::uuid)
  ON CONFLICT(id) DO UPDATE SET code=excluded.code,first_name=excluded.first_name,last_name=excluded.last_name,active=excluded.active,user_id=excluded.user_id,payload=excluded.payload,branch_id=excluded.branch_id,department_id=excluded.department_id,designation_id=excluded.designation_id,level_id=excluded.level_id,type_id=excluded.type_id,manager_id=excluded.manager_id,revision=erp_hr_employees.revision+1,updated_at=now();
  IF p_data->>'userId' IS NOT NULL THEN
   SELECT revision INTO rev FROM public.erp_org_assignments WHERE cafe_id=p_cafe_id AND user_id=(p_data->>'userId')::uuid;
   SELECT user_id INTO manager_user FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id AND id=(p_data->>'managerId')::uuid;
   sync_prior:=current_setting('erp.hr.syncing',true);PERFORM set_config('erp.hr.syncing','true',true);
   PERFORM public.erp_organization_write(p_cafe_id,'assign',jsonb_build_object('userId',p_data->>'userId','revision',coalesce(rev,0),'departmentId',p_data->'departmentId','designationId',p_data->'designationId','levelId',p_data->'levelId','typeId',p_data->'typeId','managerId',manager_user),gen_random_uuid());
   PERFORM set_config('erp.hr.syncing',coalesce(sync_prior,''),true);
  END IF;
 ELSIF p_action='photo' THEN
  IF p_data->>'fileId' IS NOT NULL THEN PERFORM erp_hr_private.file(p_cafe_id,rid,(p_data->>'fileId')::uuid,true);END IF;
  UPDATE public.erp_hr_employees SET photo_file_id=(p_data->>'fileId')::uuid,revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe_id AND id=rid AND revision=(p_data->>'revision')::integer;IF NOT FOUND THEN RAISE EXCEPTION 'تغير ملف الموظف' USING ERRCODE='40001';END IF;
 ELSIF p_action='delete_employee' THEN
  DELETE FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id AND id=rid AND revision=(p_data->>'revision')::integer;IF NOT FOUND THEN RAISE EXCEPTION 'تغير ملف الموظف أعد تحميله' USING ERRCODE='40001';END IF;
 ELSIF p_action='save_document_type' THEN
  IF length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 150 OR jsonb_typeof(p_data->'required') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_data->'expires') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_data->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع نوع المستند';END IF;
  IF rid IS NULL THEN INSERT INTO public.erp_hr_document_types(cafe_id,name,required,expires,active) VALUES(p_cafe_id,btrim(p_data->>'name'),(p_data->>'required')::boolean,(p_data->>'expires')::boolean,(p_data->>'active')::boolean) RETURNING id INTO rid;
  ELSE UPDATE public.erp_hr_document_types SET name=btrim(p_data->>'name'),required=(p_data->>'required')::boolean,expires=(p_data->>'expires')::boolean,active=(p_data->>'active')::boolean,revision=revision+1 WHERE cafe_id=p_cafe_id AND id=rid AND revision=(p_data->>'revision')::integer;IF NOT FOUND THEN RAISE EXCEPTION 'تغير نوع المستند' USING ERRCODE='40001';END IF;END IF;
 ELSIF p_action='delete_document_type' THEN DELETE FROM public.erp_hr_document_types WHERE cafe_id=p_cafe_id AND id=rid AND revision=(p_data->>'revision')::integer;IF NOT FOUND THEN RAISE EXCEPTION 'تغير نوع المستند' USING ERRCODE='40001';END IF;
 ELSIF p_action='save_document' THEN
  parent:=(p_data->>'employeeId')::uuid;SELECT * INTO doc FROM public.erp_hr_document_types WHERE cafe_id=p_cafe_id AND id=(p_data->>'typeId')::uuid AND active;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id AND id=parent) OR NOT EXISTS(SELECT 1 FROM public.erp_files WHERE cafe_id=p_cafe_id AND id=(p_data->>'fileId')::uuid AND entity_type='hr_employee' AND record_id=parent AND uploaded) THEN RAISE EXCEPTION 'الموظف أو نوع المستند أو الملف غير متاح';END IF;
  PERFORM erp_hr_private.file(p_cafe_id,parent,(p_data->>'fileId')::uuid);
  IF doc.expires AND p_data->>'expiresOn' IS NULL THEN RAISE EXCEPTION 'حدد تاريخ انتهاء المستند';END IF;
  IF rid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_hr_documents WHERE cafe_id=p_cafe_id AND id=rid AND revision=(p_data->>'revision')::integer AND employee_id=parent) THEN RAISE EXCEPTION 'تغير مستند الموظف' USING ERRCODE='40001';END IF;
  rid:=coalesce(rid,gen_random_uuid());INSERT INTO public.erp_hr_documents(id,cafe_id,employee_id,type_id,file_id,number,issued_on,expires_on,note) VALUES(rid,p_cafe_id,parent,doc.id,(p_data->>'fileId')::uuid,coalesce(p_data->>'number',''),(p_data->>'issuedOn')::date,(p_data->>'expiresOn')::date,coalesce(p_data->>'note','')) ON CONFLICT(id) DO UPDATE SET type_id=excluded.type_id,file_id=excluded.file_id,number=excluded.number,issued_on=excluded.issued_on,expires_on=excluded.expires_on,note=excluded.note,revision=erp_hr_documents.revision+1;
 ELSIF p_action='delete_document' THEN DELETE FROM public.erp_hr_documents WHERE cafe_id=p_cafe_id AND id=rid AND revision=(p_data->>'revision')::integer RETURNING employee_id INTO parent;IF NOT FOUND THEN RAISE EXCEPTION 'تغير مستند الموظف' USING ERRCODE='40001';END IF;
 ELSIF p_action='settings' THEN
  SELECT * INTO settings FROM public.erp_hr_settings WHERE cafe_id=p_cafe_id;IF coalesce(settings.revision,0) IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت الإعدادات' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(p_data->'onboardingEnabled') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_data->'offboardingEnabled') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'إعدادات المسارات غير صالحة';END IF;
  IF ((p_data->>'onboardingEnabled')::boolean AND NOT EXISTS(SELECT 1 FROM public.erp_task_templates WHERE cafe_id=p_cafe_id AND id=(p_data->>'onboardingTemplateId')::uuid AND active)) OR ((p_data->>'offboardingEnabled')::boolean AND NOT EXISTS(SELECT 1 FROM public.erp_task_templates WHERE cafe_id=p_cafe_id AND id=(p_data->>'offboardingTemplateId')::uuid AND active)) THEN RAISE EXCEPTION 'اختر قالب مهام نشط لكل مسار مفعل';END IF;
  INSERT INTO public.erp_hr_settings(cafe_id,onboarding_enabled,offboarding_enabled,onboarding_template_id,offboarding_template_id) VALUES(p_cafe_id,(p_data->>'onboardingEnabled')::boolean,(p_data->>'offboardingEnabled')::boolean,(p_data->>'onboardingTemplateId')::uuid,(p_data->>'offboardingTemplateId')::uuid) ON CONFLICT(cafe_id) DO UPDATE SET onboarding_enabled=excluded.onboarding_enabled,offboarding_enabled=excluded.offboarding_enabled,onboarding_template_id=excluded.onboarding_template_id,offboarding_template_id=excluded.offboarding_template_id,revision=erp_hr_settings.revision+1;rid:=p_cafe_id;
 ELSIF p_action='start_flow' THEN
  SELECT * INTO old FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id AND id=rid;IF NOT FOUND OR old.revision IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير ملف الموظف' USING ERRCODE='40001';END IF;
  SELECT * INTO settings FROM public.erp_hr_settings WHERE cafe_id=p_cafe_id;
  IF coalesce(p_data->>'kind','') NOT IN('onboarding','offboarding') OR NOT coalesce(CASE p_data->>'kind' WHEN 'onboarding' THEN settings.onboarding_enabled ELSE settings.offboarding_enabled END,false) THEN RAISE EXCEPTION 'مسار الموظف غير مفعل';END IF;
  IF EXISTS(SELECT 1 FROM public.erp_hr_employee_flows WHERE cafe_id=p_cafe_id AND employee_id=rid AND kind=p_data->>'kind') THEN RAISE EXCEPTION 'مسار الموظف موجود بالفعل';END IF;
  SELECT * INTO template FROM public.erp_task_templates WHERE cafe_id=p_cafe_id AND id=CASE p_data->>'kind' WHEN 'onboarding' THEN settings.onboarding_template_id ELSE settings.offboarding_template_id END AND active;IF NOT FOUND THEN RAISE EXCEPTION 'قالب المسار غير متاح';END IF;
  flow:=(public.erp_tasks_execute(p_cafe_id,'save_flow',jsonb_build_object('name',template.name||' - '||old.first_name||' '||old.last_name,'description',old.code,'templateId',template.id,'assigneeId',p_data->>'assigneeId','lines',template.lines),gen_random_uuid())->>'id')::uuid;
  INSERT INTO public.erp_hr_employee_flows(cafe_id,employee_id,kind,flow_id) VALUES(p_cafe_id,rid,p_data->>'kind',flow);
 ELSE RAISE EXCEPTION 'إجراء الموظفين غير معروف';END IF;
 INSERT INTO public.erp_hr_events(cafe_id,record_id,action,actor) VALUES(p_cafe_id,coalesce(parent,rid),p_action,auth.uid());
 result:=jsonb_build_object('id',rid,'flowId',flow);INSERT INTO erp_hr_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_data,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_manufacturing_forms_read(p_cafe uuid, p_kind text DEFAULT NULL::text, p_record uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE m record;e record;models jsonb:='[]';entries jsonb:='[]';cfg jsonb;visible jsonb;settings boolean;lookups jsonb:='{}';BEGIN
 PERFORM erp_mfg_form_private.authorize(p_cafe,'read');PERFORM erp_branch_private.enter(p_cafe);
 settings:=brand_finance_private.role_for(p_cafe)='owner' AND erp_access_private.allowed(p_cafe,'manufacturing','settings');
 IF p_kind IS NOT NULL AND p_kind NOT IN('orders','plans') OR p_record IS NOT NULL AND p_kind IS NULL THEN RAISE EXCEPTION 'Invalid manufacturing record kind' USING ERRCODE='22023';END IF;
 FOR m IN SELECT * FROM public.erp_manufacturing_forms WHERE cafe_id=p_cafe ORDER BY target_kind,kind,key LOOP
  cfg:=m.config;
  IF NOT settings AND NOT erp_mfg_form_private.allowed(p_cafe,cfg,'read') THEN CONTINUE;END IF;
  visible:=CASE WHEN settings THEN cfg ELSE cfg-'permissions' END;
  IF NOT settings THEN visible:=jsonb_set(visible,'{fields}',coalesce((SELECT jsonb_agg(CASE WHEN f?'defaultValue' AND NOT erp_mfg_form_private.value_scope(p_cafe,jsonb_build_array(f),jsonb_build_object(f->>'id',f->'defaultValue')) THEN f-'defaultValue' ELSE f END) FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=ANY(erp_mfg_form_private.fields(p_cafe,cfg,'read'))),'[]'));END IF;
  models:=models||jsonb_build_array(visible||jsonb_build_object('id',m.id,'revision',m.revision,'kind',m.kind,'targetKind',m.target_kind,'key',m.key,'canCreate',coalesce((cfg->>'active')::boolean,false) AND erp_mfg_form_private.allowed(p_cafe,cfg,'create'),'canRead',erp_mfg_form_private.allowed(p_cafe,cfg,'read'),'canUpdate',coalesce((cfg->>'active')::boolean,false) AND erp_mfg_form_private.allowed(p_cafe,cfg,'update'),'canDelete',erp_mfg_form_private.allowed(p_cafe,cfg,'delete'),'allowedFields',jsonb_build_object('create',erp_mfg_form_private.fields(p_cafe,cfg,'create'),'read',erp_mfg_form_private.fields(p_cafe,cfg,'read'),'update',erp_mfg_form_private.fields(p_cafe,cfg,'update'))));
  IF NOT erp_mfg_form_private.allowed(p_cafe,cfg,'read') THEN CONTINUE;END IF;
  FOR e IN SELECT * FROM public.erp_manufacturing_form_entries WHERE cafe_id=p_cafe AND model_id=m.id AND p_record IS NOT NULL AND record_id=p_record AND target_kind=p_kind ORDER BY created_at,id LOOP
   IF NOT erp_mfg_form_private.record_visible(p_cafe,e.record_id,e.target_kind) THEN CONTINUE;END IF;
   entries:=entries||jsonb_build_array(jsonb_build_object('id',e.id,'modelId',e.model_id,'recordId',e.record_id,'targetKind',e.target_kind,'revision',e.revision,'draft',e.draft,'values',erp_mfg_form_private.mask(p_cafe,cfg,e.field_values),'createdAt',e.created_at,'canUpdate',coalesce((cfg->>'active')::boolean,false) AND erp_mfg_form_private.allowed(p_cafe,cfg,'update'),'canDelete',erp_mfg_form_private.allowed(p_cafe,cfg,'delete'),'canFiles',erp_mfg_form_private.allowed(p_cafe,cfg,'update') AND erp_access_private.allowed(p_cafe,'manufacturing','files') AND cardinality(erp_mfg_form_private.fields(p_cafe,cfg,'read'))=jsonb_array_length(cfg->'fields')));
  END LOOP;
 END LOOP;
 IF settings THEN
  lookups:=jsonb_build_object('branches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.branches WHERE cafe_id=p_cafe),'[]'),'departments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_org_units WHERE cafe_id=p_cafe AND kind='department' AND active),'[]'),'designations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_org_units WHERE cafe_id=p_cafe AND kind='designation' AND active),'[]'),'employees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',first_name||' '||last_name)) FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND active),'[]'),'users',coalesce((SELECT jsonb_agg(jsonb_build_object('id',user_id,'name',name)) FROM public.bf_staff WHERE cafe_id=p_cafe AND active),'[]'),'roles',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_roles WHERE cafe_id=p_cafe AND active),'[]'));
 END IF;
 RETURN jsonb_build_object('models',models,'entries',entries,'canConfigure',settings,'lookups',lookups,'branchScope',public.erp_branch_context(p_cafe)->'scope','events',coalesce((SELECT jsonb_agg(jsonb_build_object('id',ev.id,'recordId',ev.record_id,'action',ev.action,'at',ev.at)) FROM public.erp_manufacturing_form_events ev WHERE ev.cafe_id=p_cafe AND (ev.record_id IS NULL AND settings OR ev.record_id=p_record AND ev.target_kind=p_kind AND erp_mfg_form_private.record_visible(p_cafe,ev.record_id,ev.target_kind)) AND EXISTS(SELECT 1 FROM public.erp_manufacturing_forms fm WHERE fm.cafe_id=p_cafe AND fm.id=ev.model_id AND erp_mfg_form_private.allowed(p_cafe,fm.config,'read'))),'[]'));
END $function$

CREATE OR REPLACE FUNCTION public.erp_manufacturing_forms_write(p_cafe uuid, p_action text, p_input jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i uuid:=(p_input->>'id')::uuid;rev integer:=(p_input->>'revision')::integer;m public.erp_manufacturing_forms;e public.erp_manufacturing_form_entries;prior erp_mfg_form_private.requests;cfg jsonb;v jsonb;r jsonb;a text;k text;tk text;pid uuid;mid uuid;keys text[];result jsonb;rowdata record;BEGIN
 a:=CASE WHEN p_action='model' OR p_action='delete' AND p_input->>'entity'='model' THEN 'settings' WHEN p_action='delete' THEN 'delete' WHEN rev=0 THEN 'create' ELSE 'update' END;
 PERFORM erp_mfg_form_private.authorize(p_cafe,a);PERFORM erp_branch_private.assert_context(p_cafe);PERFORM erp_branch_private.enter(p_cafe);
 IF p_action NOT IN('model','entry','delete') OR p_request IS NULL OR i IS NULL OR rev IS NULL OR rev<0 OR jsonb_typeof(p_input)<>'object' OR octet_length(p_input::text)>400000 THEN RAISE EXCEPTION 'بيانات النموذج غير صالحة' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60413));
 SELECT * INTO prior FROM erp_mfg_form_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;
 IF FOUND THEN
  IF prior.actor IS DISTINCT FROM auth.uid() OR prior.action<>p_action OR prior.payload<>p_input THEN RAISE EXCEPTION 'معرف عملية مكرر ببيانات مختلفة' USING ERRCODE='40001';END IF;
  IF prior.result->>'recordId' IS NOT NULL AND NOT erp_mfg_form_private.record_visible(p_cafe,(prior.result->>'recordId')::uuid,prior.result->>'targetKind') THEN RAISE EXCEPTION 'سجل التصنيع غير متاح' USING ERRCODE='42501';END IF;
  SELECT * INTO m FROM public.erp_manufacturing_forms WHERE cafe_id=p_cafe AND id=(prior.result->>'modelId')::uuid;
  IF a<>'settings' AND (m.id IS NULL OR NOT erp_mfg_form_private.allowed(p_cafe,m.config,'read') OR NOT erp_mfg_form_private.allowed(p_cafe,m.config,a) OR p_action='entry' AND NOT coalesce((m.config->>'active')::boolean,false)) THEN RAISE EXCEPTION 'النموذج غير متاح' USING ERRCODE='42501';END IF;RETURN prior.result;
 END IF;
 IF p_action='model' THEN
  SELECT * INTO m FROM public.erp_manufacturing_forms WHERE cafe_id=p_cafe AND id=i FOR UPDATE;
  IF coalesce(m.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  cfg:=p_input-'id'-'revision';
  IF m.id IS NULL AND (SELECT count(*) FROM public.erp_manufacturing_forms WHERE cafe_id=p_cafe AND target_kind=cfg->>'targetKind')>=60 THEN RAISE EXCEPTION 'بلغت الحد الأقصى لنماذج التصنيع' USING ERRCODE='22023';END IF;
  IF coalesce(cfg->>'targetKind','') NOT IN('orders','plans') OR coalesce(cfg->>'kind','') NOT IN('primary','related') OR coalesce(cfg->>'key','')!~'^[a-z][a-z0-9_]{0,59}$' OR length(btrim(coalesce(cfg->>'name',''))) NOT BETWEEN 1 AND 160 OR jsonb_typeof(cfg->'active') IS DISTINCT FROM 'boolean' OR length(coalesce(cfg->>'description',''))>5000 OR jsonb_typeof(cfg->'permissions') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'تعريف النموذج غير صالح' USING ERRCODE='22023';END IF;
  IF m.id IS NOT NULL AND (m.kind<>cfg->>'kind' OR m.target_kind<>cfg->>'targetKind') THEN RAISE EXCEPTION 'لا يمكن تغيير نوع النموذج';END IF;
  PERFORM erp_manufacturing_private.validate_custom_fields(cfg->'fields');
  IF coalesce(cfg->>'nameField','')<>'' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=cfg->>'nameField' AND f->>'type' IN('text','number','date','email','phone')) THEN RAISE EXCEPTION 'اختر حقل اسم صالح';END IF;
  FOREACH k IN ARRAY ARRAY['create','read','update','delete'] LOOP PERFORM erp_workflow_private.validate_selector(p_cafe,cfg#>ARRAY['permissions',k]);END LOOP;
  IF jsonb_typeof(cfg#>'{permissions,fieldRules}') IS DISTINCT FROM 'array' OR jsonb_array_length(cfg#>'{permissions,fieldRules}')>50 THEN RAISE EXCEPTION 'قواعد الحقول غير صالحة';END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(cfg#>'{permissions,fieldRules}') LOOP
   PERFORM (r->>'id')::uuid;PERFORM erp_workflow_private.validate_selector(p_cafe,r->'selector');
   FOREACH k IN ARRAY ARRAY['create','read','update'] LOOP
    IF jsonb_typeof(r->k) IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(r->k) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=x)) THEN RAISE EXCEPTION 'صلاحيات الحقول غير صالحة';END IF;
   END LOOP;
  END LOOP;
  FOR r IN SELECT value FROM jsonb_array_elements(cfg#>'{permissions,fieldRules}') LOOP
   IF NOT ((r->'read') @> (r->'create')) OR NOT ((r->'read') @> (r->'update')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE coalesce((f->>'required')::boolean,false) AND NOT (r->'create')?(f->>'id')) THEN RAISE EXCEPTION 'الحقول المطلوبة والقابلة للتعديل يجب أن تكون متاحة للعرض والإضافة';END IF;
  END LOOP;
  FOR rowdata IN SELECT * FROM public.erp_manufacturing_form_entries WHERE cafe_id=p_cafe AND model_id=i LOOP
   IF EXISTS(SELECT 1 FROM jsonb_object_keys(rowdata.field_values) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'fields') f WHERE f->>'id'=x)) THEN RAISE EXCEPTION 'الحقل يحتوي بيانات محفوظة ولا يمكن حذفه';END IF;
   PERFORM erp_mfg_form_private.validate_values(cfg->'fields',rowdata.field_values,p_cafe,rowdata.id,i,0,rowdata.draft);
  END LOOP;
  INSERT INTO public.erp_manufacturing_forms(id,cafe_id,kind,target_kind,key,config) VALUES(i,p_cafe,cfg->>'kind',cfg->>'targetKind',cfg->>'key',cfg) ON CONFLICT(id) DO UPDATE SET config=excluded.config,key=excluded.key,revision=public.erp_manufacturing_forms.revision+1 WHERE public.erp_manufacturing_forms.cafe_id=p_cafe;
  IF NOT FOUND THEN RAISE EXCEPTION 'النموذج غير متاح' USING ERRCODE='42501';END IF;mid:=i;
 ELSIF p_action='entry' THEN
  pid:=(p_input->>'recordId')::uuid;mid:=(p_input->>'modelId')::uuid;tk:=p_input->>'targetKind';
  IF NOT erp_mfg_form_private.record_visible(p_cafe,pid,tk) THEN RAISE EXCEPTION 'سجل التصنيع غير متاح' USING ERRCODE='42501';END IF;
  SELECT * INTO m FROM public.erp_manufacturing_forms WHERE cafe_id=p_cafe AND id=mid FOR KEY SHARE;
  SELECT * INTO e FROM public.erp_manufacturing_form_entries WHERE cafe_id=p_cafe AND id=i FOR UPDATE;
  IF e.id IS NULL AND (SELECT count(*) FROM public.erp_manufacturing_form_entries WHERE cafe_id=p_cafe AND target_kind=tk AND record_id=pid)>=500 THEN RAISE EXCEPTION 'بلغت الحد الأقصى لسجلات النماذج' USING ERRCODE='22023';END IF;
  IF m.id IS NULL OR m.target_kind IS DISTINCT FROM tk OR NOT coalesce((m.config->>'active')::boolean,false) OR NOT erp_mfg_form_private.allowed(p_cafe,m.config,'read') OR NOT erp_mfg_form_private.allowed(p_cafe,m.config,a) THEN RAISE EXCEPTION 'النموذج غير متاح' USING ERRCODE='42501';END IF;
  IF e.id IS NOT NULL AND (e.record_id<>pid OR e.model_id<>mid OR e.target_kind<>tk) THEN RAISE EXCEPTION 'لا يمكن نقل سجل النموذج';END IF;
  IF coalesce(e.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(p_input->'draft') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'values') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'قيم النموذج غير صالحة';END IF;
  keys:=erp_mfg_form_private.fields(p_cafe,m.config,a);
  FOR k,v IN SELECT * FROM jsonb_each(p_input->'values') LOOP IF NOT k=ANY(keys) THEN RAISE EXCEPTION 'لا تملك صلاحية تعديل الحقل' USING ERRCODE='42501';END IF;END LOOP;
  v:=coalesce(e.field_values,'{}')||(p_input->'values');v:=erp_manufacturing_private.custom_defaults(m.config->'fields',v);
  IF NOT erp_mfg_form_private.value_scope(p_cafe,m.config->'fields',v) THEN RAISE EXCEPTION 'مرجع الحقل غير متاح في الفرع' USING ERRCODE='42501';END IF;
  PERFORM erp_mfg_form_private.validate_values(m.config->'fields',v,p_cafe,i,mid,0,(p_input->>'draft')::boolean);
  INSERT INTO public.erp_manufacturing_form_entries(id,cafe_id,model_id,model_kind,target_kind,record_id,draft,field_values,created_by) VALUES(i,p_cafe,mid,m.kind,tk,pid,(p_input->>'draft')::boolean,v,auth.uid()) ON CONFLICT(id) DO UPDATE SET field_values=excluded.field_values,draft=excluded.draft,revision=public.erp_manufacturing_form_entries.revision+1,updated_at=now() WHERE public.erp_manufacturing_form_entries.cafe_id=p_cafe;
  IF NOT FOUND THEN RAISE EXCEPTION 'السجل غير متاح' USING ERRCODE='42501';END IF;
 ELSIF p_input->>'entity'='model' THEN
  SELECT * INTO m FROM public.erp_manufacturing_forms WHERE cafe_id=p_cafe AND id=i FOR UPDATE;
  IF m.id IS NULL OR m.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  DELETE FROM public.erp_manufacturing_forms WHERE cafe_id=p_cafe AND id=i;mid:=i;
 ELSIF p_input->>'entity'='entry' THEN
  e:=erp_mfg_form_private.assert_entry(p_cafe,i,'delete');pid:=e.record_id;mid:=e.model_id;tk:=e.target_kind;
  IF e.revision IS DISTINCT FROM rev THEN RAISE EXCEPTION 'Conflict' USING ERRCODE='40001';END IF;
  DELETE FROM public.erp_manufacturing_form_entries WHERE cafe_id=p_cafe AND id=i;
 ELSE RAISE EXCEPTION 'نوع السجل غير صالح';END IF;
 result:=jsonb_build_object('id',i,'modelId',mid,'recordId',pid,'targetKind',tk,'revision',rev+1);
 INSERT INTO public.erp_manufacturing_form_events(cafe_id,record_id,target_kind,model_id,entry_id,action,actor) VALUES(p_cafe,pid,tk,mid,CASE WHEN pid IS NOT NULL THEN i END,p_action,auth.uid());
 INSERT INTO erp_mfg_form_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_memberships_write_before_edit(p_cafe uuid, p_action text, p_input jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i uuid;rev integer;m public.erp_memberships;f public.erp_membership_freezes;r public.erp_membership_renewals;prior erp_membership_private.requests;result jsonb;mid uuid;start_date date;end_date date;current_rev integer;settings jsonb;
BEGIN
 IF p_action NOT IN('create','edit','renew','freeze','freeze_delete','suspend','resume','delete','policy') OR p_request IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>20000 THEN RAISE EXCEPTION 'الإجراء غير صالح';END IF;
 PERFORM erp_membership_private.authorize(p_cafe,CASE WHEN p_action='policy' THEN 'settings' WHEN p_action IN('delete','freeze_delete') THEN 'delete' WHEN p_action IN('create','renew','freeze') THEN 'create' ELSE 'update' END);
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67951));PERFORM erp_membership_private.sync(p_cafe);
 SELECT * INTO prior FROM erp_membership_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>p_action OR prior.input<>p_input THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN prior.result;END IF;
 i:=nullif(p_input->>'id','')::uuid;rev:=(p_input->>'revision')::integer;IF rev IS NULL OR rev<0 OR(p_action<>'policy' AND i IS NULL) THEN RAISE EXCEPTION 'راجع معرف السجل وإصداره';END IF;
 IF p_action='policy' THEN
  SELECT revision INTO current_rev FROM public.erp_membership_settings WHERE cafe_id=p_cafe;IF coalesce(current_rev,0)<>rev THEN RAISE EXCEPTION 'تغيرت إعدادات العضويات' USING ERRCODE='40001';END IF;
  IF(p_input->>'graceDays')::integer NOT BETWEEN 0 AND 365 OR p_input->>'graceDays' IS NULL OR coalesce(p_input->>'attendance','') NOT IN('all','members','active') OR coalesce(p_input->>'invoiceStatus','') NOT IN('draft','issued') OR length(coalesce(p_input#>>'{issuer,name}',''))>160 OR length(coalesce(p_input#>>'{issuer,address}',''))>500 OR length(coalesce(p_input#>>'{issuer,vatNumber}',''))>15 THEN RAISE EXCEPTION 'راجع سياسة العضويات';END IF;
  IF nullif(p_input->>'warehouseId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe AND id=(p_input->>'warehouseId')::uuid AND active) THEN RAISE EXCEPTION 'المستودع غير متاح';END IF;
  IF p_input->>'invoiceStatus'='issued' AND(nullif(p_input->>'warehouseId','') IS NULL OR length(coalesce(p_input#>>'{issuer,name}',''))<2 OR length(coalesce(p_input#>>'{issuer,address}',''))<8 OR coalesce(p_input#>>'{issuer,vatNumber}','')!~'^3[0-9]{13}3$') THEN RAISE EXCEPTION 'أكمل بيانات البائع والمستودع للإصدار التلقائي';END IF;
  INSERT INTO public.erp_membership_settings VALUES(p_cafe,rev+1,p_input-'revision') ON CONFLICT(cafe_id) DO UPDATE SET revision=excluded.revision,payload=excluded.payload;result:=jsonb_build_object('id',p_cafe);mid:=NULL;i:=p_cafe;
 ELSIF p_action='create' THEN
  IF rev<>0 OR EXISTS(SELECT 1 FROM public.erp_memberships WHERE cafe_id=p_cafe AND id=i) THEN RAISE EXCEPTION 'العضوية موجودة بالفعل' USING ERRCODE='40001';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=(p_input->>'customerId')::uuid AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
  start_date:=(p_input->>'joinedOn')::date;IF start_date IS NULL OR NOT isfinite(start_date) THEN RAISE EXCEPTION 'راجع تاريخ الالتحاق';END IF;
  INSERT INTO public.erp_memberships(cafe_id,id,customer_id,package_id,joined_on,description,created_by) VALUES(p_cafe,i,(p_input->>'customerId')::uuid,(p_input->>'packageId')::uuid,start_date,coalesce(p_input->>'description',''),auth.uid());mid:=i;
  result:=erp_membership_private.create_renewal(p_cafe,i,(p_input->>'customerId')::uuid,(p_input->>'packageId')::uuid,(p_input->>'invoiceDate')::date);
 ELSIF p_action IN('freeze','freeze_delete') THEN
  SELECT * INTO f FROM public.erp_membership_freezes WHERE cafe_id=p_cafe AND id=i FOR UPDATE;IF coalesce(f.revision,0)<>rev OR f.voided THEN RAISE EXCEPTION 'تغيرت فترة التوقف' USING ERRCODE='40001';END IF;
  mid:=CASE WHEN p_action='freeze' THEN(p_input->>'membershipId')::uuid ELSE f.membership_id END;SELECT * INTO m FROM public.erp_memberships WHERE cafe_id=p_cafe AND id=mid AND NOT deleted FOR UPDATE;IF m.id IS NULL THEN RAISE EXCEPTION 'العضوية غير متاحة';END IF;
  IF p_action='freeze_delete' THEN IF f.id IS NULL THEN RAISE EXCEPTION 'فترة التوقف غير موجودة';END IF;UPDATE public.erp_membership_freezes SET voided=true,revision=rev+1 WHERE cafe_id=p_cafe AND id=i;
  ELSE
   IF m.revision<>(p_input->>'membershipRevision')::integer OR(f.id IS NOT NULL AND f.membership_id<>mid) THEN RAISE EXCEPTION 'تغيرت العضوية' USING ERRCODE='40001';END IF;
   start_date:=(p_input->>'startsOn')::date;end_date:=(p_input->>'endsOn')::date;
   IF start_date IS NULL OR end_date IS NULL OR NOT isfinite(start_date) OR NOT isfinite(end_date) OR end_date<start_date OR end_date-start_date>365 OR jsonb_typeof(p_input->'extendMembership') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'extendCredits') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع فترة التوقف وخيارات التمديد';END IF;
   SELECT * INTO r FROM public.erp_membership_renewals WHERE cafe_id=p_cafe AND membership_id=mid AND status='paid' AND starts_on<=start_date AND erp_membership_private.end_date(p_cafe,id)>=start_date ORDER BY starts_on DESC LIMIT 1;IF r.id IS NULL THEN RAISE EXCEPTION 'فترة التوقف يجب أن تبدأ ضمن اشتراك مدفوع';END IF;
   IF EXISTS(SELECT 1 FROM public.erp_membership_freezes WHERE cafe_id=p_cafe AND membership_id=mid AND id<>i AND NOT voided AND starts_on<=end_date AND ends_on>=start_date) THEN RAISE EXCEPTION 'فترة التوقف تتداخل مع فترة أخرى';END IF;
   IF EXISTS(SELECT 1 FROM public.erp_credit_allocations a JOIN public.erp_credit_usages u ON u.cafe_id=a.cafe_id AND u.id=a.usage_id JOIN public.erp_credit_charges ch ON ch.cafe_id=a.cafe_id AND ch.id=a.charge_id JOIN public.erp_membership_renewals rr ON rr.cafe_id=ch.cafe_id AND rr.id=ch.source_id WHERE a.cafe_id=p_cafe AND rr.membership_id=mid AND u.used_on BETWEEN start_date AND end_date) THEN RAISE EXCEPTION 'الفترة تتضمن استهلاكًا مسجلًا ولا يمكن إيقافها';END IF;
   INSERT INTO public.erp_membership_freezes VALUES(p_cafe,i,mid,r.id,start_date,end_date,(p_input->>'extendMembership')::boolean,(p_input->>'extendCredits')::boolean,false,rev+1) ON CONFLICT(cafe_id,id) DO UPDATE SET starts_on=excluded.starts_on,ends_on=excluded.ends_on,extend_membership=excluded.extend_membership,extend_credits=excluded.extend_credits,revision=excluded.revision;
  END IF;
  IF EXISTS(SELECT 1 FROM public.erp_credit_allocations a JOIN public.erp_credit_usages u ON u.cafe_id=a.cafe_id AND u.id=a.usage_id JOIN public.erp_credit_charges ch ON ch.cafe_id=a.cafe_id AND ch.id=a.charge_id JOIN public.erp_membership_renewals rr ON rr.cafe_id=ch.cafe_id AND rr.id=ch.source_id WHERE a.cafe_id=p_cafe AND rr.membership_id=mid AND u.used_on>erp_membership_private.end_date(p_cafe,rr.id,true)) THEN RAISE EXCEPTION 'التعديل يقصر رصيدًا استهلك بالفعل خلال فترة التمديد';END IF;
  UPDATE public.erp_memberships SET revision=revision+1 WHERE cafe_id=p_cafe AND id=mid;result:=jsonb_build_object('id',mid);
 ELSE
  SELECT * INTO m FROM public.erp_memberships WHERE cafe_id=p_cafe AND id=i AND NOT deleted FOR UPDATE;IF m.id IS NULL THEN RAISE EXCEPTION 'العضوية غير متاحة';END IF;IF m.revision<>rev THEN RAISE EXCEPTION 'تغيرت العضوية' USING ERRCODE='40001';END IF;mid:=i;
  IF p_action='renew' THEN
   IF EXISTS(SELECT 1 FROM public.erp_membership_renewals WHERE cafe_id=p_cafe AND membership_id=i AND status='pending') THEN RAISE EXCEPTION 'يوجد اشتراك بانتظار الإصدار أو السداد';END IF;
   result:=erp_membership_private.create_renewal(p_cafe,i,m.customer_id,(p_input->>'packageId')::uuid,(p_input->>'invoiceDate')::date);
  ELSIF p_action='edit' THEN UPDATE public.erp_memberships SET description=coalesce(p_input->>'description','') WHERE cafe_id=p_cafe AND id=i;
  ELSIF p_action='suspend' THEN UPDATE public.erp_memberships SET suspended=true WHERE cafe_id=p_cafe AND id=i;
  ELSIF p_action='resume' THEN UPDATE public.erp_memberships SET suspended=false WHERE cafe_id=p_cafe AND id=i;
  ELSIF p_action='delete' THEN UPDATE public.erp_memberships SET deleted=true,suspended=true WHERE cafe_id=p_cafe AND id=i;
  END IF;
  UPDATE public.erp_memberships SET revision=revision+1 WHERE cafe_id=p_cafe AND id=i;result:=coalesce(result,jsonb_build_object('id',i,'deleted',p_action='delete'));
 END IF;
 PERFORM erp_membership_private.sync(p_cafe);INSERT INTO public.erp_membership_events(cafe_id,membership_id,record_id,action,actor) VALUES(p_cafe,mid,i,p_action,auth.uid());INSERT INTO erp_membership_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_my_permissions(p_cafe_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.erp_roles%ROWTYPE;a public.erp_role_assignments%ROWTYPE;employee_active boolean;counted integer;base_role text;
BEGIN
 base_role:=brand_finance_private.role_for(p_cafe_id);IF auth.uid() IS NULL OR base_role IS NULL THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
 IF base_role='owner' THEN RETURN jsonb_build_object('custom',false,'active',true,'permissions','{}'::jsonb,'blocked','[]'::jsonb,'roleName',NULL);END IF;
 SELECT count(*) INTO counted FROM public.erp_role_assignments x LEFT JOIN public.erp_hr_employees e ON e.cafe_id=x.cafe_id AND e.id=x.employee_id WHERE x.cafe_id=p_cafe_id AND coalesce(x.user_id,e.user_id)=auth.uid();
 IF counted=0 THEN RETURN jsonb_build_object('custom',false,'active',true,'permissions','{}'::jsonb,'blocked','[]'::jsonb,'roleName',NULL);END IF;
 IF counted>1 THEN RETURN jsonb_build_object('custom',true,'active',false,'permissions','{}'::jsonb,'blocked',to_jsonb(erp_access_private.domains()),'roleName','تعارض تعيين الأدوار');END IF;
 SELECT x.* INTO a FROM public.erp_role_assignments x LEFT JOIN public.erp_hr_employees e ON e.cafe_id=x.cafe_id AND e.id=x.employee_id WHERE x.cafe_id=p_cafe_id AND coalesce(x.user_id,e.user_id)=auth.uid();SELECT coalesce((SELECT active FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id AND id=a.employee_id),true) INTO employee_active;SELECT * INTO r FROM public.erp_roles WHERE cafe_id=p_cafe_id AND id=a.role_id;
 RETURN jsonb_build_object('custom',true,'active',r.active AND employee_active,'permissions',r.permissions,'blocked',r.blocked,'roleName',r.name);
END $function$

CREATE OR REPLACE FUNCTION public.erp_organization_write(p_cafe_id uuid, p_action text, p_data jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE old public.erp_org_units;a public.erp_org_assignments;prev erp_org_private.requests;v_id uuid:=nullif(p_data->>'id','')::uuid;v_parent uuid:=nullif(p_data->>'parentId','')::uuid;v_kind text:=p_data->>'kind';v_managers uuid[];v_manager uuid;v_cursor uuid;v_seen uuid[];v_field text;v_target uuid;v_result jsonb;v_user uuid;v_department uuid;v_designation uuid;
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'organization',erp_access_private.action(p_action,p_data));
 IF auth.uid() IS NULL OR brand_finance_private.role_for(p_cafe_id) IS DISTINCT FROM 'owner' THEN RAISE EXCEPTION 'إدارة الهيكل التنظيمي متاحة للمالك' USING ERRCODE='42501';END IF;
 IF p_request_id IS NULL OR p_action IS NULL OR p_action NOT IN('save','delete','status','assign') OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR octet_length(p_data::text)>20000 THEN RAISE EXCEPTION 'بيانات العملية غير صالحة' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,83421));
 SELECT * INTO prev FROM erp_org_private.requests WHERE cafe_id=p_cafe_id AND request_id=p_request_id;
 IF FOUND THEN IF prev.actor<>auth.uid() OR prev.action<>p_action OR prev.payload<>p_data THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات مختلفة' USING ERRCODE='22023';END IF;RETURN prev.result;END IF;
 IF p_action='assign' THEN
  v_user:=(p_data->>'userId')::uuid;v_manager:=nullif(p_data->>'managerId','')::uuid;
  IF NOT erp_org_private.staff(p_cafe_id,v_user) OR (v_manager IS NOT NULL AND NOT erp_org_private.staff(p_cafe_id,v_manager)) THEN RAISE EXCEPTION 'اختر موظفًا ومديرًا من العلامة نفسها' USING ERRCODE='22023';END IF;
  SELECT * INTO a FROM public.erp_org_assignments WHERE cafe_id=p_cafe_id AND user_id=v_user;
  IF coalesce(a.revision,0) IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير تعيين الموظف أعد التحميل' USING ERRCODE='40001';END IF;
  FOREACH v_field IN ARRAY ARRAY['department','designation','level','type'] LOOP
   v_target:=nullif(p_data->>(v_field||'Id'),'')::uuid;
   IF v_target IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_org_units WHERE cafe_id=p_cafe_id AND id=v_target AND kind=v_field AND active) THEN RAISE EXCEPTION 'اختر سجلًا تنظيميًا نشطًا من العلامة نفسها' USING ERRCODE='22023';END IF;
  END LOOP;
  v_department:=nullif(p_data->>'departmentId','')::uuid;v_designation:=nullif(p_data->>'designationId','')::uuid;
  IF v_designation IS NOT NULL AND EXISTS(SELECT 1 FROM public.erp_org_units WHERE id=v_designation AND parent_id IS NOT NULL AND parent_id IS DISTINCT FROM v_department) THEN RAISE EXCEPTION 'المسمى الوظيفي مرتبط بقسم مختلف' USING ERRCODE='22023';END IF;
  v_seen:=ARRAY[v_user];v_cursor:=v_manager;
  WHILE v_cursor IS NOT NULL LOOP
   IF v_cursor=ANY(v_seen) THEN RAISE EXCEPTION 'لا يمكن إنشاء حلقة في تسلسل المديرين' USING ERRCODE='22023';END IF;
   v_seen:=array_append(v_seen,v_cursor);SELECT manager_id INTO v_cursor FROM public.erp_org_assignments WHERE cafe_id=p_cafe_id AND user_id=v_cursor;
  END LOOP;
  INSERT INTO public.erp_org_assignments(cafe_id,user_id,department_id,designation_id,level_id,type_id,manager_id) VALUES(p_cafe_id,v_user,v_department,v_designation,nullif(p_data->>'levelId','')::uuid,nullif(p_data->>'typeId','')::uuid,v_manager)
  ON CONFLICT(cafe_id,user_id) DO UPDATE SET department_id=excluded.department_id,designation_id=excluded.designation_id,level_id=excluded.level_id,type_id=excluded.type_id,manager_id=excluded.manager_id,revision=erp_org_assignments.revision+1;
  v_id:=v_user;
 ELSE
  IF v_id IS NOT NULL THEN SELECT * INTO old FROM public.erp_org_units WHERE cafe_id=p_cafe_id AND id=v_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'السجل غير موجود' USING ERRCODE='42501';END IF;END IF;
  IF coalesce(old.revision,0) IS DISTINCT FROM (p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير السجل أعد التحميل' USING ERRCODE='40001';END IF;
  IF p_action='save' THEN
   IF v_kind IS NULL OR v_kind NOT IN('department','designation','level','type') OR (old.id IS NOT NULL AND old.kind<>v_kind) THEN RAISE EXCEPTION 'نوع السجل غير صالح' USING ERRCODE='22023';END IF;
   IF v_parent IS NOT NULL AND (v_kind NOT IN('department','designation') OR NOT EXISTS(SELECT 1 FROM public.erp_org_units WHERE cafe_id=p_cafe_id AND id=v_parent AND kind='department' AND active)) THEN RAISE EXCEPTION 'القسم المرتبط غير متاح' USING ERRCODE='22023';END IF;
   v_seen:=ARRAY[coalesce(v_id,gen_random_uuid())];v_cursor:=v_parent;
   WHILE v_cursor IS NOT NULL LOOP
    IF v_cursor=ANY(v_seen) THEN RAISE EXCEPTION 'لا يمكن إنشاء حلقة بين الأقسام' USING ERRCODE='22023';END IF;
    v_seen:=array_append(v_seen,v_cursor);SELECT parent_id INTO v_cursor FROM public.erp_org_units WHERE cafe_id=p_cafe_id AND id=v_cursor;
   END LOOP;
   SELECT coalesce(array_agg(value::uuid),'{}') INTO v_managers FROM jsonb_array_elements_text(coalesce(p_data->'managerIds','[]'));
   IF cardinality(v_managers)>100 OR (v_kind<>'department' AND cardinality(v_managers)>0) OR EXISTS(SELECT 1 FROM unnest(v_managers) m WHERE NOT erp_org_private.staff(p_cafe_id,m)) THEN RAISE EXCEPTION 'راجع المديرين المعينين للقسم' USING ERRCODE='22023';END IF;
   IF old.kind='designation' AND old.parent_id IS DISTINCT FROM v_parent AND EXISTS(SELECT 1 FROM public.erp_org_assignments WHERE cafe_id=p_cafe_id AND designation_id=v_id AND v_parent IS NOT NULL AND department_id IS DISTINCT FROM v_parent) THEN RAISE EXCEPTION 'حدّث تعيينات الموظفين قبل تغيير قسم المسمى الوظيفي' USING ERRCODE='22023';END IF;
   v_id:=coalesce(v_id,gen_random_uuid());
   INSERT INTO public.erp_org_units(id,cafe_id,kind,name,abbreviation,description,active,parent_id,manager_ids) VALUES(v_id,p_cafe_id,v_kind,btrim(p_data->>'name'),coalesce(p_data->>'abbreviation',''),coalesce(p_data->>'description',''),coalesce((p_data->>'active')::boolean,true),v_parent,v_managers)
   ON CONFLICT(id) DO UPDATE SET name=excluded.name,abbreviation=excluded.abbreviation,description=excluded.description,active=excluded.active,parent_id=excluded.parent_id,manager_ids=excluded.manager_ids,revision=erp_org_units.revision+1,updated_at=now();
  ELSIF p_action='status' THEN
   IF v_id IS NULL OR jsonb_typeof(p_data->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'الحالة غير صالحة' USING ERRCODE='22023';END IF;
   UPDATE public.erp_org_units SET active=(p_data->>'active')::boolean,revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe_id AND id=v_id;
  ELSE
   IF v_id IS NULL THEN RAISE EXCEPTION 'حدد السجل المطلوب' USING ERRCODE='22023';END IF;
   DELETE FROM public.erp_org_units WHERE cafe_id=p_cafe_id AND id=v_id;
  END IF;
 END IF;
 INSERT INTO public.erp_org_events(cafe_id,record_id,action,detail,actor) VALUES(p_cafe_id,v_id,p_action,p_data,auth.uid());
 v_result:=jsonb_build_object('id',v_id);
 INSERT INTO erp_org_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),p_action,p_data,v_result);
 RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_payroll_renew_due(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE branch_prior jsonb;item record;r public.erp_payroll_records;rid uuid;done integer:=0;failed integer:=0;BEGIN
 FOR item IN SELECT p.id,p.cafe_id,c.owner_user_id FROM public.erp_payroll_records p JOIN public.cafes c ON c.id=p.cafe_id WHERE p.kind='contract' AND p.status='active' AND coalesce((p.payload->>'autoRenew')::boolean,false) AND p.date_to<(now() AT TIME ZONE 'Asia/Riyadh')::date AND c.status='active' AND c.deleted_at IS NULL AND platform_access_private.service_enabled(c.id,'finance') AND NOT EXISTS(SELECT 1 FROM public.erp_payroll_records child WHERE child.cafe_id=p.cafe_id AND child.kind='contract' AND child.payload->>'parentId'=p.id::text AND child.status<>'cancelled') ORDER BY p.date_to,p.id LIMIT greatest(1,least(p_limit,100)) LOOP
  BEGIN
   PERFORM pg_advisory_xact_lock(hashtextextended(item.cafe_id::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(item.cafe_id::text,95500));
   SELECT * INTO r FROM public.erp_payroll_records WHERE id=item.id AND status='active' AND coalesce((payload->>'autoRenew')::boolean,false) FOR UPDATE;
   IF NOT FOUND OR EXISTS(SELECT 1 FROM public.erp_payroll_records WHERE cafe_id=item.cafe_id AND payload->>'parentId'=item.id::text AND status<>'cancelled') THEN CONTINUE;END IF;
   branch_prior:=erp_branch_private.enter_job(item.cafe_id,'erp_payroll_records',item.id,item.owner_user_id);rid:=erp_payroll_private.renew(item.cafe_id,item.id);PERFORM erp_branch_private.exit_job(branch_prior);INSERT INTO public.erp_payroll_events(cafe_id,record_id,action,actor,detail) VALUES(item.cafe_id,rid,'auto_renew',item.owner_user_id,jsonb_build_object('previousContractId',item.id));done:=done+1;
  EXCEPTION WHEN OTHERS THEN failed:=failed+1;INSERT INTO public.erp_payroll_events(cafe_id,record_id,action,actor,detail) VALUES(item.cafe_id,item.id,'auto_renew_failed',item.owner_user_id,jsonb_build_object('code',SQLSTATE));END;
 END LOOP;RETURN jsonb_build_object('renewed',done,'failed',failed);
END $function$

CREATE OR REPLACE FUNCTION public.erp_purchase_credit_write(p_cafe uuid, p_action text, p_payload jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c uuid:=p_cafe;p jsonb:=p_payload;n public.erp_purchase_credit_notes%ROWTYPE;original public.bf_documents%ROWTYPE;
 prior erp_purchase_private.requests;rid uuid;doc uuid;revdoc uuid;aid uuid;b uuid;v jsonb;result jsonb;
 amount numeric;discount numeric;rate numeric;net numeric;tax numeric;total numeric;d date;entry record;
BEGIN
 PERFORM erp_purchase_private.authorize(c,'read');PERFORM erp_branch_private.enter(c);PERFORM erp_branch_private.assert_context(c);
 IF p_request IS NULL OR jsonb_typeof(p) IS DISTINCT FROM 'object' OR octet_length(p::text)>20000 OR p_action NOT IN('save','post','draft','delete','cancel','payment') THEN RAISE EXCEPTION 'طلب الإشعار غير صالح';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(c::text,60412));
 SELECT * INTO prior FROM erp_purchase_private.requests WHERE cafe_id=c AND request_id=p_request;
 IF FOUND THEN
  IF prior.actor IS DISTINCT FROM auth.uid() OR prior.action IS DISTINCT FROM 'credit_note_'||p_action OR prior.payload IS DISTINCT FROM p THEN RAISE EXCEPTION 'معرف الطلب مستخدم لعملية أخرى';END IF;
  SELECT to_jsonb(source_row) INTO v FROM public.bf_documents source_row WHERE source_row.cafe_id=c AND source_row.id=(prior.result->>'sourceDocumentId')::uuid;
  IF v IS NULL THEN RAISE EXCEPTION 'المصدر لم يعد متاحًا' USING ERRCODE='42501';END IF;
  PERFORM erp_branch_private.assert_input(c,v);
  PERFORM erp_branch_private.assert_input(c,jsonb_build_object('document_id',prior.result->'sourceDocumentId','branch_id',prior.result->'branchId'));
  IF NOT erp_branch_private.allowed_resource(c,erp_branch_private.current_branch(c),'account',(prior.result->>'expenseAccountId')::uuid) THEN RAISE EXCEPTION 'حساب الإشعار غير متاح في الفرع' USING ERRCODE='42501';END IF;
  RETURN prior.result;
 END IF;
 rid:=(p->>'id')::uuid;IF rid IS NULL OR jsonb_typeof(p->'revision') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'اختر الإشعار وأعد تحميل نسخته';END IF;
 SELECT * INTO n FROM public.erp_purchase_credit_notes WHERE cafe_id=c AND id=rid FOR UPDATE;
 IF coalesce(n.revision,0) IS DISTINCT FROM (p->>'revision')::integer THEN RAISE EXCEPTION 'تغير الإشعار أعد تحميله' USING ERRCODE='40001';END IF;
 IF n.id IS NULL AND p_action<>'save' THEN RAISE EXCEPTION 'الإشعار غير متاح' USING ERRCODE='42501';END IF;
 IF n.id IS NOT NULL THEN
  PERFORM erp_branch_private.assert_input(c,to_jsonb(n));
  IF NOT erp_branch_private.allowed_resource(c,erp_branch_private.current_branch(c),'account',(n.payload->>'expenseAccountId')::uuid) THEN RAISE EXCEPTION 'حساب الإشعار غير متاح في الفرع' USING ERRCODE='42501';END IF;
 END IF;
 SELECT * INTO original FROM public.bf_documents WHERE cafe_id=c AND id=CASE WHEN n.id IS NULL THEN (p->>'invoiceId')::uuid ELSE n.source_document_id END AND kind='purchase' FOR UPDATE;
 IF original.id IS NULL OR EXISTS(SELECT 1 FROM public.erp_purchase_credit_postings WHERE cafe_id=c AND document_id=original.id) THEN RAISE EXCEPTION 'اختر فاتورة شراء أصلية';END IF;
 PERFORM erp_branch_private.assert_input(c,to_jsonb(original));SELECT branch_id INTO b FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=original.id;
 IF n.id IS NOT NULL AND n.branch_id IS DISTINCT FROM b THEN RAISE EXCEPTION 'تغير فرع الفاتورة الأصلية أعد مراجعة الإشعار' USING ERRCODE='40001';END IF;
 IF NOT erp_branch_private.row_allowed(c,b,p) THEN RAISE EXCEPTION 'الحساب غير متاح لفرع الفاتورة' USING ERRCODE='42501';END IF;
 IF p_action='save' THEN
  PERFORM erp_purchase_private.authorize(c,CASE WHEN n.id IS NULL THEN 'create' ELSE 'update' END);
  IF NOT coalesce((erp_purchase_private.settings(c)->>'allowCreditNotes')::boolean,false) THEN RAISE EXCEPTION 'فعّل الإشعارات الدائنة من إعدادات المشتريات';END IF;
  IF n.id IS NOT NULL AND (n.status<>'draft' OR n.source_document_id IS DISTINCT FROM (p->>'invoiceId')::uuid) THEN RAISE EXCEPTION 'حوّل الإشعار إلى مسودة قبل تعديله ولا تغير فاتورته الأصلية';END IF;
  amount:=(p->>'amount')::numeric;discount:=(p->>'discount')::numeric;rate:=(p->>'taxRate')::numeric;aid:=(p->>'expenseAccountId')::uuid;d:=(p->>'date')::date;
  IF amount IS NULL OR amount<=0 OR amount>1e9 OR amount<>round(amount,2) OR discount IS NULL OR discount<0 OR discount>=amount OR discount<>round(discount,2) OR rate IS NULL OR rate<0 OR rate>100 OR rate<>round(rate,3) OR d IS NULL OR NOT isfinite(d) OR length(btrim(coalesce(p->>'description',''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'راجع وصف الإشعار والمبلغ والخصم والضريبة والتاريخ';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=c AND id=aid AND active AND kind='expense') OR NOT erp_branch_private.allowed_resource(c,b,'account',aid) THEN RAISE EXCEPTION 'اختر حساب مصروف نشطًا متاحًا للفرع';END IF;
  net:=amount-discount;tax:=round(net*rate/100,2);total:=net+tax;
  IF total>1e9 THEN RAISE EXCEPTION 'إجمالي الإشعار يتجاوز الحد المسموح';END IF;
  v:=jsonb_build_object('date',d,'description',btrim(p->>'description'),'amount',amount,'discount',discount,'taxRate',rate,'expenseAccountId',aid,'net',net,'tax',tax,'total',total);
  IF n.id IS NULL THEN
   INSERT INTO public.erp_purchase_credit_notes(id,cafe_id,source_document_id,branch_id,payload,created_by) VALUES(rid,c,original.id,b,v,auth.uid());
  ELSE UPDATE public.erp_purchase_credit_notes SET payload=v,revision=revision+1 WHERE cafe_id=c AND id=rid;END IF;
 ELSIF p_action='post' THEN
  PERFORM erp_purchase_private.authorize(c,'approve');
  IF n.status<>'draft' OR NOT coalesce((erp_purchase_private.settings(c)->>'allowCreditNotes')::boolean,false) THEN RAISE EXCEPTION 'الإشعار ليس مسودة أو الخاصية غير مفعلة';END IF;
  v:=n.payload;d:=(v->>'date')::date;PERFORM erp_purchase_private.period(c,d);aid:=(v->>'expenseAccountId')::uuid;
  IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=c AND id=aid AND active AND kind='expense') OR NOT erp_branch_private.allowed_resource(c,b,'account',aid) THEN RAISE EXCEPTION 'حساب المصروف لم يعد متاحًا للفرع';END IF;
  net:=(v->>'net')::numeric;tax:=(v->>'tax')::numeric;total:=(v->>'total')::numeric;
  IF (p->>'expectedTotal')::numeric IS DISTINCT FROM total THEN RAISE EXCEPTION 'راجع إجمالي الإشعار قبل الإصدار' USING ERRCODE='40001';END IF;
  doc:=gen_random_uuid();
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,reference_id,note,created_by,subtotal,tax,total,paid,created_at)
   VALUES(doc,c,'purchase',original.party_id,original.id,'إشعار دائن مشتريات '||n.code||' — '||(v->>'description'),auth.uid(),net,tax,total,0,d::timestamp AT TIME ZONE 'Asia/Riyadh');
  PERFORM erp_purchase_private.credit_bind(c,doc,b);
  PERFORM brand_finance_private.line(c,doc,aid,net,0);
  PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'1300'),tax,0);
  PERFORM brand_finance_private.line(c,doc,brand_finance_private.account(c,'2000'),0,total,original.party_id);
  PERFORM erp_purchase_private.balance(c,doc);
  INSERT INTO public.erp_purchase_credit_postings(cafe_id,note_id,document_id) VALUES(c,rid,doc);
  UPDATE public.erp_purchase_credit_notes SET document_id=doc,status='posted',revision=revision+1 WHERE cafe_id=c AND id=rid;
 ELSIF p_action='draft' THEN
  PERFORM erp_purchase_private.authorize(c,'approve');
  IF n.status<>'posted' OR n.document_id IS NULL THEN RAISE EXCEPTION 'الإشعار ليس مصدرًا';END IF;
  PERFORM erp_purchase_private.period(c,(now() AT TIME ZONE 'Asia/Riyadh')::date);PERFORM erp_purchase_private.period(c,(n.payload->>'date')::date);
  IF EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=c AND reference_id=n.document_id) OR EXISTS(SELECT 1 FROM public.erp_purchase_credit_uses WHERE cafe_id=c AND invoice_id=n.document_id) THEN RAISE EXCEPTION 'الإشعار مرتبط بدفعة أو معاملة لاحقة ولا يقبل التحويل إلى مسودة';END IF;
  revdoc:=gen_random_uuid();
  INSERT INTO public.bf_documents(id,cafe_id,kind,party_id,reference_id,note,created_by,subtotal,tax,total,paid)
   VALUES(revdoc,c,'refund',original.party_id,n.document_id,'عكس إصدار الإشعار الدائن '||n.code,auth.uid(),(n.payload->>'net')::numeric,(n.payload->>'tax')::numeric,(n.payload->>'total')::numeric,0);
  PERFORM erp_purchase_private.credit_bind(c,revdoc,b);
  FOR entry IN SELECT * FROM public.bf_journal WHERE cafe_id=c AND document_id=n.document_id LOOP
   PERFORM brand_finance_private.line(c,revdoc,entry.account_id,entry.credit,entry.debit,entry.party_id);
  END LOOP;
  PERFORM erp_purchase_private.balance(c,revdoc);
  UPDATE public.erp_purchase_credit_postings SET reversal_document_id=revdoc WHERE cafe_id=c AND document_id=n.document_id AND reversal_document_id IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'سبق عكس إصدار الإشعار' USING ERRCODE='40001';END IF;
  UPDATE public.erp_purchase_credit_notes SET status='draft',document_id=NULL,revision=revision+1 WHERE cafe_id=c AND id=rid;
 ELSIF p_action='payment' THEN
  PERFORM erp_purchase_private.authorize(c,'approve');
  IF n.status<>'posted' OR n.document_id IS NULL THEN RAISE EXCEPTION 'أصدر الإشعار قبل دفعه';END IF;
  IF NOT coalesce(isfinite((p->>'date')::date),false) THEN RAISE EXCEPTION 'تاريخ الدفعة غير صالح';END IF;
  result:=jsonb_build_object('supplierId',original.party_id,'invoiceId',n.document_id,'accountId',p->'accountId','amount',p->'amount','date',p->'date','note','دفع إشعار دائن '||n.code);
  doc:=erp_purchase_private.payment(c,result);PERFORM erp_purchase_private.credit_bind(c,doc,b);
  UPDATE public.erp_purchase_credit_notes SET revision=revision+1 WHERE cafe_id=c AND id=rid;
 ELSIF p_action IN('delete','cancel') THEN
  PERFORM erp_purchase_private.authorize(c,'delete');
  IF n.status<>'draft' THEN RAISE EXCEPTION 'يمكن حذف أو إلغاء المسودة فقط';END IF;
  IF p_action='delete' THEN
   IF EXISTS(SELECT 1 FROM public.erp_purchase_credit_postings WHERE cafe_id=c AND note_id=rid) THEN RAISE EXCEPTION 'للإشعار تاريخ مالي استخدم الإلغاء للاحتفاظ به';END IF;
   DELETE FROM public.erp_purchase_credit_notes WHERE cafe_id=c AND id=rid;
  ELSE UPDATE public.erp_purchase_credit_notes SET status='cancelled',revision=revision+1 WHERE cafe_id=c AND id=rid;END IF;
 END IF;
 result:=jsonb_build_object('id',rid,'documentId',doc,'reversalId',revdoc,'sourceDocumentId',original.id,'branchId',b,'expenseAccountId',CASE WHEN p_action='save' THEN p->'expenseAccountId' ELSE n.payload->'expenseAccountId' END);
 INSERT INTO erp_purchase_private.requests VALUES(c,p_request,auth.uid(),'credit_note_'||p_action,p,result);
 INSERT INTO public.erp_purchase_events(cafe_id,record_id,action,payload,actor) VALUES(c,rid,'credit_note_'||p_action,result,auth.uid());
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_purchases_read(p_cafe_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE j jsonb;BEGIN
 j:=erp_purchase_private.purchases_read_before_credit_notes(p_cafe_id);
 j:=jsonb_set(j,'{invoices}',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(j->'invoices')x WHERE NOT EXISTS(SELECT 1 FROM public.erp_purchase_credit_postings h WHERE h.cafe_id=p_cafe_id AND (h.document_id=(x->>'id')::uuid OR h.reversal_document_id=(x->>'id')::uuid))),'[]'));
 RETURN j||jsonb_build_object('creditNotes',public.erp_purchase_credit_read(p_cafe_id));
END $function$

CREATE OR REPLACE FUNCTION public.erp_rental_customer(p_cafe uuid, p_profile uuid, p_action text, p_input jsonb DEFAULT '{}'::jsonb, p_request uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE profile public.customer_profiles;cfg jsonb;result jsonb;prior public.erp_rental_requests;party uuid;ids uuid[];s timestamptz;e timestamptz;oid uuid;q jsonb;f jsonb;value jsonb;old public.erp_rental_reservations;
BEGIN
 SELECT * INTO profile FROM public.customer_profiles WHERE cafe_id=p_cafe AND id=p_profile;IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found' USING ERRCODE='42501';END IF;
 SELECT payload INTO cfg FROM public.erp_rental_settings WHERE cafe_id=p_cafe;IF NOT coalesce((cfg->>'onlineBooking')::boolean,false) THEN RAISE EXCEPTION 'الحجز عبر واجهة العميل غير متاح حاليًا' USING ERRCODE='42501';END IF;
 IF p_action='read' THEN RETURN jsonb_build_object('units',coalesce((SELECT jsonb_agg(jsonb_build_object('id',u.id,'name',u.payload->>'name','type',t.payload->>'name')) FROM public.erp_rental_units u JOIN public.erp_rental_types t ON t.cafe_id=u.cafe_id AND t.id=(u.payload->>'typeId')::uuid WHERE u.cafe_id=p_cafe AND (u.payload->>'active')::boolean AND (t.payload->>'active')::boolean),'[]'),'fields',cfg->'fields','reservations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'number',r.number,'startsAt',r.starts_at,'endsAt',r.ends_at,'total',r.total,'status',r.status,'canCancel',r.status='pending' AND r.draft_id IS NULL) ORDER BY r.created_at DESC) FROM public.erp_rental_reservations r WHERE r.cafe_id=p_cafe AND r.payload->>'customerProfileId'=p_profile::text),'[]'));END IF;
 IF jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>20000 THEN RAISE EXCEPTION 'طلب الحجز غير صالح' USING ERRCODE='22023';END IF;
 IF p_action NOT IN('quote','book','cancel') THEN RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));
 IF p_action<>'quote' THEN
  IF p_request IS NULL THEN RAISE EXCEPTION 'Request id required' USING ERRCODE='22023';END IF;
  SELECT * INTO prior FROM public.erp_rental_requests WHERE cafe_id=p_cafe AND request_id=p_request;
  IF FOUND THEN IF prior.actor<>p_profile OR prior.action IS DISTINCT FROM 'customer_'||p_action OR prior.payload IS DISTINCT FROM p_input THEN RAISE EXCEPTION 'تغير طلب الحجز' USING ERRCODE='40001';END IF;RETURN prior.result;END IF;
 END IF;
 IF p_action='cancel' THEN
  SELECT * INTO old FROM public.erp_rental_reservations WHERE cafe_id=p_cafe AND id=(p_input->>'id')::uuid AND payload->>'customerProfileId'=p_profile::text FOR UPDATE;
  IF NOT FOUND OR old.status<>'pending' OR old.draft_id IS NOT NULL THEN RAISE EXCEPTION 'لا يمكن إلغاء هذا الحجز من واجهة العميل تواصل مع الإدارة' USING ERRCODE='42501';END IF;
  oid:=old.id;UPDATE public.erp_rental_reservations SET status='cancelled',revision=revision+1 WHERE id=oid;UPDATE public.erp_rental_reservation_units SET active=false WHERE reservation_id=oid;result:=jsonb_build_object('id',oid);
 ELSE
  ids:=ARRAY(SELECT x::uuid FROM jsonb_array_elements_text(p_input->'unitIds') x);s:=(p_input->>'start')::timestamptz;e:=(p_input->>'end')::timestamptz;
  IF cardinality(ids) NOT BETWEEN 1 AND 10 OR s<now() OR s>now()+interval '366 days' OR e-s>interval '90 days' THEN RAISE EXCEPTION 'اختر حتى عشر وحدات ومدة حجز مستقبلية حتى 90 يومًا' USING ERRCODE='22023';END IF;
  q:=erp_rental_private.quote(p_cafe,ids,s,e);IF p_action='quote' THEN RETURN jsonb_build_object('total',q->'total');END IF;
  IF (q->>'total')::numeric IS DISTINCT FROM (p_input->>'expectedTotal')::numeric THEN RAISE EXCEPTION 'تغير السعر أعد التحقق قبل الحجز' USING ERRCODE='40001';END IF;
  IF (SELECT count(*) FROM public.erp_rental_reservations WHERE cafe_id=p_cafe AND payload->>'customerProfileId'=p_profile::text AND status='pending')>=10 THEN RAISE EXCEPTION 'لديك عشرة طلبات معلقة تواصل مع الإدارة' USING ERRCODE='22023';END IF;
  FOR f IN SELECT x FROM jsonb_array_elements(coalesce(cfg->'fields','[]')) x LOOP
   value:=p_input->'fields'->(f->>'key');IF (f->>'required')::boolean AND(value IS NULL OR value='null' OR value='""' OR (f->>'type'='checkbox' AND value<>'true')) THEN RAISE EXCEPTION 'أكمل الحقول الإضافية المطلوبة' USING ERRCODE='22023';END IF;
   IF value IS NOT NULL AND value<>'null' AND value<>'""' THEN
    IF f->>'type'='number' AND jsonb_typeof(value)<>'number' OR f->>'type'='checkbox' AND jsonb_typeof(value)<>'boolean' OR f->>'type' IN('text','date') AND jsonb_typeof(value)<>'string' OR length(value::text)>2000 THEN RAISE EXCEPTION 'راجع نوع الحقل الإضافي' USING ERRCODE='22023';END IF;
    IF f->>'type'='date' THEN PERFORM(value#>>'{}')::date;END IF;
   END IF;
  END LOOP;
  IF profile.phone IS NULL OR length(regexp_replace(profile.phone,'[^0-9]','','g'))<8 THEN RAISE EXCEPTION 'أكمل رقم جوالك في حساب العميل' USING ERRCODE='22023';END IF;
  SELECT id INTO party FROM public.bf_parties WHERE cafe_id=p_cafe AND kind='customer' AND active AND regexp_replace(phone,'[^0-9]','','g')=regexp_replace(profile.phone,'[^0-9]','','g') ORDER BY id LIMIT 1;
  IF party IS NULL THEN party:=gen_random_uuid();INSERT INTO public.bf_parties(id,cafe_id,kind,name,phone) VALUES(party,p_cafe,'customer',coalesce(nullif(btrim(profile.full_name),''),'عميل الإيجارات'),profile.phone);END IF;
  oid:=gen_random_uuid();INSERT INTO public.erp_rental_reservations(id,cafe_id,customer_id,starts_at,ends_at,payload,total,breakdown) VALUES(oid,p_cafe,party,s,e,jsonb_build_object('id',oid,'customerId',party,'customerProfileId',p_profile,'unitIds',to_jsonb(ids),'startsAt',s,'endsAt',e,'notes',left(coalesce(p_input->>'notes',''),2000),'tags','[]'::jsonb,'autoInvoice',false,'expectedTotal',q->'total','invoiceLineMode',q->>'lineMode','fields',coalesce(p_input->'fields','{}')), (q->>'total')::numeric,q->'lines');
  INSERT INTO public.erp_rental_reservation_units SELECT p_cafe,x,oid,NULL,s,e,true FROM unnest(ids) x;result:=jsonb_build_object('id',oid);
 END IF;
 INSERT INTO public.erp_rental_events(cafe_id,record_id,entity,action,details) VALUES(p_cafe,oid,'reservation','customer_'||p_action,jsonb_build_object('customerProfileId',p_profile));INSERT INTO public.erp_rental_requests VALUES(p_cafe,p_request,p_profile,'customer_'||p_action,p_input,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_requests_read(p_cafe uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.erp_request_types;r public.erp_staff_requests;types jsonb:='[]';records jsonb:='[]';visible uuid[]:='{}';configure boolean:=erp_requests_private.base(p_cafe,'settings');cfg jsonb;more_read boolean;more_edit boolean;more_delete boolean;lookups jsonb;subjects jsonb;
BEGIN
 IF NOT erp_requests_private.base(p_cafe,'read') THEN RAISE EXCEPTION 'لا تملك صلاحية الطلبات' USING ERRCODE='42501';END IF;
 FOR t IN SELECT * FROM public.erp_request_types WHERE cafe_id=p_cafe ORDER BY config->>'name' LOOP
  IF configure OR erp_requests_private.type_allowed(p_cafe,t.config,'view') OR erp_requests_private.type_allowed(p_cafe,t.config,'create') OR EXISTS(SELECT 1 FROM public.erp_staff_requests q WHERE q.cafe_id=p_cafe AND q.type_id=t.id AND NOT deleted AND erp_requests_private.self(p_cafe,q.employee_id,q.user_id)) THEN
   more_read:=configure OR coalesce((t.config->>'moreActive')::boolean,false) AND erp_workflow_private.selector(p_cafe,t.config->'morePermissions'->'read');
   more_edit:=configure OR more_read AND erp_requests_private.base(p_cafe,'update') AND erp_workflow_private.selector(p_cafe,t.config->'morePermissions'->CASE WHEN t.config->'moreValues'='{}'::jsonb THEN 'create' ELSE 'update' END);
   more_delete:=configure OR more_read AND erp_requests_private.base(p_cafe,'delete') AND erp_workflow_private.selector(p_cafe,t.config->'morePermissions'->'delete');
   cfg:=t.config-CASE WHEN more_read THEN '__none' ELSE 'moreValues' END;
   types:=types||jsonb_build_array(cfg||jsonb_build_object('id',t.id,'revision',t.revision,'canCreate',(t.config->>'active')::boolean AND erp_requests_private.type_allowed(p_cafe,t.config,'create'),'canOthers',erp_requests_private.type_allowed(p_cafe,t.config,'others'),'canConfigure',configure,'canReadMore',more_read,'canEditMore',more_edit,'canDeleteMore',more_delete,'count',(SELECT count(*) FROM public.erp_staff_requests q WHERE q.cafe_id=p_cafe AND q.type_id=t.id AND erp_requests_private.can(p_cafe,q,t.config,'view'))));
  END IF;
  FOR r IN SELECT * FROM public.erp_staff_requests WHERE cafe_id=p_cafe AND type_id=t.id ORDER BY created_at DESC LOOP
   IF erp_requests_private.can(p_cafe,r,t.config,'view') THEN
    visible:=array_append(visible,r.id);
    records:=records||jsonb_build_array(r.payload||jsonb_build_object('id',r.id,'revision',r.revision,'number',r.number,'typeId',r.type_id,'employeeId',r.employee_id,'userId',r.user_id,'employeeName',coalesce((SELECT first_name||' '||last_name FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND id=r.employee_id),(SELECT name FROM public.bf_staff WHERE cafe_id=p_cafe AND user_id=r.user_id),(SELECT name FROM public.cafes WHERE id=p_cafe AND owner_user_id=r.user_id),'موظف'),'typeName',t.config->>'name','status',r.status,'closed',r.closed,'createdAt',r.created_at,'updatedAt',r.updated_at,'fields',r.config->'fields','steps',r.config->'steps','step',r.step,'approvals',r.approvals,'emailDraft',CASE WHEN erp_requests_private.can(p_cafe,r,t.config,'edit') THEN r.email_draft ELSE NULL END,'canEdit',erp_requests_private.can(p_cafe,r,t.config,'edit'),'canDelete',erp_requests_private.can(p_cafe,r,t.config,'delete'),'canFiles',erp_requests_private.can(p_cafe,r,t.config,'files'),'notifyApprovers',coalesce((r.config->>'notifyApprovers')::boolean,false),'canApprove',erp_requests_private.can(p_cafe,r,t.config,'approve'),'canRevoke',erp_requests_private.can(p_cafe,r,t.config,'revoke'),'canClose',erp_requests_private.can(p_cafe,r,t.config,'close')));
   END IF;
  END LOOP;
 END LOOP;
 SELECT jsonb_build_object('branches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.branches WHERE cafe_id=p_cafe AND active AND deleted_at IS NULL),'[]'),'departments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_org_units WHERE cafe_id=p_cafe AND kind='department' AND active),'[]'),'designations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_org_units WHERE cafe_id=p_cafe AND kind='designation' AND active),'[]'),'employees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',first_name||' '||last_name)) FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND active),'[]'),'users',coalesce((SELECT jsonb_agg(x) FROM(SELECT user_id id,name FROM public.bf_staff WHERE cafe_id=p_cafe AND active UNION SELECT owner_user_id,name FROM public.cafes WHERE id=p_cafe)x),'[]'),'roles',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name)) FROM public.erp_roles WHERE cafe_id=p_cafe AND active),'[]')) INTO lookups;
 SELECT coalesce(jsonb_agg(x ORDER BY name),'[]') INTO subjects FROM(
 SELECT e.id,e.first_name||' '||e.last_name name,'employee' kind,e.user_id=auth.uid() self,concat_ws(' ',e.code,e.payload->>'email',o.name,b.name) search FROM public.erp_hr_employees e LEFT JOIN public.erp_org_units o ON o.cafe_id=e.cafe_id AND o.id=e.department_id LEFT JOIN public.branches b ON b.cafe_id=e.cafe_id AND b.id=e.branch_id WHERE e.cafe_id=p_cafe AND e.active
 UNION ALL SELECT s.user_id,s.name,'user',s.user_id=auth.uid(),s.name FROM public.bf_staff s WHERE s.cafe_id=p_cafe AND s.active AND NOT EXISTS(SELECT 1 FROM public.erp_hr_employees e WHERE e.cafe_id=p_cafe AND e.user_id=s.user_id AND active)
 UNION ALL SELECT owner_user_id,name,'user',owner_user_id=auth.uid(),name FROM public.cafes WHERE id=p_cafe AND NOT EXISTS(SELECT 1 FROM public.erp_hr_employees e WHERE e.cafe_id=p_cafe AND e.user_id=cafes.owner_user_id AND active))x;
 RETURN jsonb_build_object('types',types,'records',records,'canConfigure',configure,'lookups',lookups,'subjects',subjects,'sources',jsonb_build_object('employees',jsonb_build_object('label','حسابات الموظفين','options',lookups->'users')),'events',coalesce((SELECT jsonb_agg(jsonb_build_object('id',e.id,'recordId',e.record_id,'action',e.action,'note',e.note,'detail',e.detail,'at',e.at,'actorName',coalesce(s.name,'المالك')) ORDER BY e.at DESC) FROM public.erp_request_events e LEFT JOIN public.bf_staff s ON s.cafe_id=e.cafe_id AND s.user_id=e.actor WHERE e.cafe_id=p_cafe AND (e.record_id=ANY(visible) OR configure AND EXISTS(SELECT 1 FROM public.erp_request_types WHERE cafe_id=p_cafe AND id=e.record_id))),'[]'));
END $function$

CREATE OR REPLACE FUNCTION public.erp_requests_write(p_cafe uuid, p_action text, p_input jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_variable
DECLARE id uuid:=(p_input->>'id')::uuid;rev integer:=(p_input->>'revision')::integer;t public.erp_request_types;r public.erp_staff_requests;prior erp_requests_private.requests;result jsonb;cfg jsonb;v jsonb;k text;a text;own boolean;note text:=coalesce(p_input->>'note','');target_status text;draft boolean;detail jsonb:='{}';
BEGIN
 IF NOT erp_requests_private.base(p_cafe,'read') THEN RAISE EXCEPTION 'لا تملك صلاحية الطلبات' USING ERRCODE='42501';END IF;
 IF p_request IS NULL OR id IS NULL OR rev IS NULL OR rev<0 OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>524288 OR length(note)>3000 OR coalesce(p_action,'') NOT IN('type','type_delete','type_active','more','more_delete','record','submit','delete','approve','reject','revoke','close','reopen','email_draft') THEN RAISE EXCEPTION 'بيانات العملية غير صالحة';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text||':requests',0));
 SELECT * INTO prior FROM erp_requests_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;
 IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>p_action OR prior.payload<>p_input THEN RAISE EXCEPTION 'رمز العملية مستخدم ببيانات مختلفة';END IF;RETURN prior.result;END IF;
 IF p_action IN('type','type_delete','type_active','more','more_delete') THEN
  SELECT * INTO t FROM public.erp_request_types WHERE cafe_id=p_cafe AND erp_request_types.id=id FOR UPDATE;
  IF coalesce(t.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'تغير نوع الطلب أعد تحميله' USING ERRCODE='40001';END IF;
  IF p_action NOT IN('more','more_delete') AND NOT erp_requests_private.base(p_cafe,'settings') THEN RAISE EXCEPTION 'إعداد أنواع الطلبات متاح للمالك فقط' USING ERRCODE='42501';END IF;
  IF p_action='type' THEN
   cfg:=p_input-'id'-'revision';
   IF length(btrim(coalesce(cfg->>'name',''))) NOT BETWEEN 1 AND 200 OR coalesce(cfg->>'icon','') NOT IN('document','person','calendar','cash','building','box','tools','heart') OR jsonb_typeof(cfg->'active') IS DISTINCT FROM 'boolean' OR jsonb_typeof(cfg->'allowSelfApproval') IS DISTINCT FROM 'boolean' OR jsonb_typeof(cfg->'notifyApprovers') IS DISTINCT FROM 'boolean' OR jsonb_typeof(cfg->'steps') IS DISTINCT FROM 'array' OR jsonb_array_length(cfg->'steps') NOT BETWEEN 1 AND 20 OR length(btrim(coalesce(cfg->>'moreName',''))) NOT BETWEEN 1 AND 150 OR jsonb_typeof(cfg->'moreActive') IS DISTINCT FROM 'boolean' OR length(coalesce(cfg->>'moreDescription',''))>3000 THEN RAISE EXCEPTION 'راجع بيانات النوع وخطوات الموافقة';END IF;
   FOREACH k IN ARRAY ARRAY['create','others','view','approve'] LOOP PERFORM erp_workflow_private.validate_selector(p_cafe,cfg->'permissions'->k);END LOOP;
   FOREACH k IN ARRAY ARRAY['create','update','read','delete'] LOOP PERFORM erp_workflow_private.validate_selector(p_cafe,cfg->'morePermissions'->k);END LOOP;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(cfg->'steps') x GROUP BY x->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'خطوات الموافقة مكررة';END IF;
   FOR v IN SELECT value FROM jsonb_array_elements(cfg->'steps') LOOP PERFORM (v->>'id')::uuid;IF v->>'id' IS NULL OR length(btrim(coalesce(v->>'name',''))) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'اسم خطوة الموافقة مطلوب';END IF;PERFORM erp_workflow_private.validate_selector(p_cafe,v->'selector');END LOOP;
   PERFORM erp_manufacturing_private.validate_custom_fields(cfg->'fields');PERFORM erp_requests_private.field_scope(cfg->'fields');PERFORM erp_manufacturing_private.validate_custom_fields(cfg->'moreFields');PERFORM erp_requests_private.field_scope(cfg->'moreFields');
   -- Saving a schema may precede entering required values or uploading its attachments.
   v:=erp_manufacturing_private.custom_defaults(cfg->'moreFields',coalesce(cfg->'moreValues','{}'));PERFORM erp_requests_private.validate_more(cfg->'moreFields',v,p_cafe,id,NULL,0,true);cfg:=jsonb_set(cfg,'{moreValues}',v);
   INSERT INTO public.erp_request_types(id,cafe_id,config) VALUES(id,p_cafe,cfg) ON CONFLICT ON CONSTRAINT erp_request_types_cafe_id_id_key DO UPDATE SET config=excluded.config,revision=erp_request_types.revision+1,updated_at=now();
  ELSIF p_action='type_delete' THEN IF t.id IS NULL THEN RAISE EXCEPTION 'النوع غير موجود';END IF;DELETE FROM public.erp_request_types WHERE cafe_id=p_cafe AND erp_request_types.id=id;
  ELSIF p_action='type_active' THEN IF t.id IS NULL THEN RAISE EXCEPTION 'النوع غير موجود';END IF;UPDATE public.erp_request_types SET config=jsonb_set(config,'{active}',to_jsonb(NOT(config->>'active')::boolean)),revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe AND erp_request_types.id=id;
  ELSE
   a:=CASE WHEN p_action='more_delete' THEN 'delete' WHEN t.config->'moreValues'='{}'::jsonb THEN 'create' ELSE 'update' END;
   IF t.id IS NULL OR NOT erp_requests_private.base(p_cafe,CASE WHEN a='create' THEN 'update' ELSE a END) OR NOT(erp_requests_private.base(p_cafe,'settings') OR (t.config->>'moreActive')::boolean AND erp_requests_private.type_allowed(p_cafe,t.config,'view') AND erp_workflow_private.selector(p_cafe,t.config->'morePermissions'->'read') AND erp_workflow_private.selector(p_cafe,t.config->'morePermissions'->a)) THEN RAISE EXCEPTION 'لا تملك صلاحية المعلومات الإضافية' USING ERRCODE='42501';END IF;
   v:=CASE WHEN p_action='more_delete' THEN '{}'::jsonb ELSE erp_manufacturing_private.custom_defaults(t.config->'moreFields',p_input->'values') END;
   IF p_action='more' THEN PERFORM erp_requests_private.validate_more(t.config->'moreFields',v,p_cafe,id);END IF;
   UPDATE public.erp_request_types SET config=jsonb_set(config,'{moreValues}',v),revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe AND erp_request_types.id=id;
  END IF;
 ELSE
  SELECT * INTO r FROM public.erp_staff_requests WHERE cafe_id=p_cafe AND erp_staff_requests.id=id FOR UPDATE;
  IF r.deleted OR coalesce(r.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'تغير الطلب أعد تحميله' USING ERRCODE='40001';END IF;
  SELECT * INTO t FROM public.erp_request_types WHERE cafe_id=p_cafe AND erp_request_types.id=coalesce(r.type_id,(p_input->>'typeId')::uuid) FOR SHARE;
  IF t.id IS NULL THEN RAISE EXCEPTION 'نوع الطلب غير متاح';END IF;
  IF p_action='record' THEN
   draft:=(p_input->>'draft')::boolean;
   IF draft IS NULL OR NOT(t.config->>'active')::boolean OR NOT erp_requests_private.base(p_cafe,CASE WHEN rev=0 THEN 'create' ELSE 'update' END) OR (rev=0 AND NOT erp_requests_private.type_allowed(p_cafe,t.config,'create')) OR (rev>0 AND NOT erp_requests_private.can(p_cafe,r,t.config,'edit')) THEN RAISE EXCEPTION 'لا تملك صلاحية إضافة أو تعديل هذا الطلب' USING ERRCODE='42501';END IF;
   IF num_nonnulls(p_input->>'employeeId',p_input->>'userId')<>1 OR (p_input->>'typeId')::uuid IS DISTINCT FROM t.id THEN RAISE EXCEPTION 'اختر موظفًا واحدًا من النوع المحدد';END IF;
   IF p_input->>'employeeId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_hr_employees WHERE cafe_id=p_cafe AND erp_hr_employees.id=(p_input->>'employeeId')::uuid AND active) OR p_input->>'userId' IS NOT NULL AND NOT(EXISTS(SELECT 1 FROM public.bf_staff WHERE cafe_id=p_cafe AND user_id=(p_input->>'userId')::uuid AND active) OR EXISTS(SELECT 1 FROM public.cafes WHERE cafes.id=p_cafe AND owner_user_id=(p_input->>'userId')::uuid)) THEN RAISE EXCEPTION 'الموظف غير متاح في العلامة';END IF;
   own:=coalesce(erp_requests_private.self(p_cafe,(p_input->>'employeeId')::uuid,(p_input->>'userId')::uuid),false);
   IF NOT own AND NOT erp_requests_private.type_allowed(p_cafe,t.config,'others') THEN RAISE EXCEPTION 'لا يمكنك إضافة طلب بالنيابة عن الآخرين' USING ERRCODE='42501';END IF;
   IF length(btrim(coalesce(p_input->>'description',''))) NOT BETWEEN 1 AND 10000 OR p_input->>'applicationDate' IS NULL OR p_input->>'executionDate' IS NULL OR NOT isfinite((p_input->>'applicationDate')::date) OR NOT isfinite((p_input->>'executionDate')::date) THEN RAISE EXCEPTION 'راجع وصف وتواريخ الطلب';END IF;
   cfg:=t.config;v:=erp_manufacturing_private.custom_defaults(cfg->'fields',p_input->'customValues');PERFORM erp_requests_private.validate_values(cfg->'fields',v,p_cafe,id,t.id,0,draft);
   INSERT INTO public.erp_staff_requests(id,cafe_id,type_id,employee_id,user_id,payload,config,status,created_by) VALUES(id,p_cafe,t.id,(p_input->>'employeeId')::uuid,(p_input->>'userId')::uuid,jsonb_build_object('applicationDate',p_input->>'applicationDate','executionDate',p_input->>'executionDate','description',p_input->>'description','customValues',v),cfg,CASE WHEN draft THEN 'draft' ELSE 'pending' END,auth.uid()) ON CONFLICT ON CONSTRAINT erp_staff_requests_cafe_id_id_key DO UPDATE SET employee_id=excluded.employee_id,user_id=excluded.user_id,payload=excluded.payload,config=excluded.config,status=excluded.status,step=0,approvals='[]',email_draft=NULL,revision=erp_staff_requests.revision+1,updated_at=now();
   detail:=jsonb_build_object('approvalReset',rev>0,'draft',draft);
  ELSIF p_action='submit' THEN
   IF r.status<>'draft' OR NOT erp_requests_private.can(p_cafe,r,t.config,'edit') OR NOT(t.config->>'active')::boolean THEN RAISE EXCEPTION 'المسودة غير متاحة للتقديم' USING ERRCODE='42501';END IF;
   v:=erp_manufacturing_private.custom_defaults(t.config->'fields',r.payload->'customValues');PERFORM erp_requests_private.validate_values(t.config->'fields',v,p_cafe,id,t.id);
   UPDATE public.erp_staff_requests SET payload=jsonb_set(payload,'{customValues}',v),config=t.config,status='pending',revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe AND erp_staff_requests.id=id;
  ELSE
   a:=CASE WHEN p_action IN('approve','reject') THEN 'approve' WHEN p_action IN('close','reopen') THEN 'close' WHEN p_action='email_draft' THEN 'edit' ELSE p_action END;
   IF NOT erp_requests_private.can(p_cafe,r,t.config,a) THEN RAISE EXCEPTION 'الطلب أو خطوة الموافقة غير متاح لهذه العملية' USING ERRCODE='42501';END IF;
   IF p_action='approve' THEN
    target_status:=CASE WHEN r.step+1=jsonb_array_length(r.config->'steps') THEN 'approved' ELSE 'pending' END;
    UPDATE public.erp_staff_requests SET approvals=approvals||jsonb_build_array(jsonb_build_object('actor',auth.uid(),'name',coalesce((SELECT name FROM public.bf_staff WHERE cafe_id=p_cafe AND user_id=auth.uid()),'المالك'),'step',step,'at',now(),'note',note)),step=step+1,status=target_status WHERE cafe_id=p_cafe AND erp_staff_requests.id=id;detail:=jsonb_build_object('step',r.step,'status',target_status);
   ELSIF p_action='reject' THEN IF length(btrim(note))=0 THEN RAISE EXCEPTION 'أدخل سبب رفض الطلب';END IF;UPDATE public.erp_staff_requests SET status='rejected' WHERE cafe_id=p_cafe AND erp_staff_requests.id=id;
   ELSIF p_action='revoke' THEN IF length(btrim(note))=0 THEN RAISE EXCEPTION 'أدخل سبب إلغاء الموافقة أو إعادة المراجعة';END IF;UPDATE public.erp_staff_requests SET status='pending',step=0,approvals='[]' WHERE cafe_id=p_cafe AND erp_staff_requests.id=id;detail:=jsonb_build_object('previousApprovals',r.approvals,'previousStatus',r.status);
   ELSIF p_action IN('close','reopen') THEN IF r.closed=(p_action='close') THEN RAISE EXCEPTION 'حالة الطلب تغيرت بالفعل';END IF;UPDATE public.erp_staff_requests SET closed=p_action='close' WHERE cafe_id=p_cafe AND erp_staff_requests.id=id;
   ELSIF p_action='delete' THEN UPDATE public.erp_staff_requests SET deleted=true WHERE cafe_id=p_cafe AND erp_staff_requests.id=id;
   ELSIF p_action='email_draft' THEN IF length(btrim(coalesce(p_input->>'subject',''))) NOT BETWEEN 1 AND 200 OR length(btrim(coalesce(p_input->>'body',''))) NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'أدخل عنوان ونص البريد الإلكتروني';END IF;UPDATE public.erp_staff_requests SET email_draft=jsonb_build_object('subject',p_input->>'subject','body',p_input->>'body') WHERE cafe_id=p_cafe AND erp_staff_requests.id=id;
   END IF;
   UPDATE public.erp_staff_requests SET revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe AND erp_staff_requests.id=id;
  END IF;
 END IF;
 result:=jsonb_build_object('id',id,'revision',rev+1,'deleted',p_action IN('delete','type_delete'));
 INSERT INTO public.erp_request_events(cafe_id,record_id,action,actor,note,detail) VALUES(p_cafe,id,p_action,auth.uid(),note,detail);
 INSERT INTO erp_requests_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_roles(p_cafe_id uuid, p_action text DEFAULT 'read'::text, p_input jsonb DEFAULT '{}'::jsonb, p_request uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.erp_roles%ROWTYPE;a public.erp_role_assignments%ROWTYPE;prior erp_access_private.requests%ROWTYPE;role_name text;cmd jsonb;answer jsonb;rid uuid;revision integer;domain text;key text;v jsonb;target uuid;employee public.erp_hr_employees%ROWTYPE;
BEGIN
 role_name:=brand_finance_private.role_for(p_cafe_id);IF auth.uid() IS NULL OR coalesce(role_name,'')<>'owner' THEN RAISE EXCEPTION 'إدارة الأدوار متاحة لمالك العلامة فقط' USING ERRCODE='42501';END IF;
 IF p_action='read' THEN RETURN jsonb_build_object('roles',coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id'||jsonb_build_object('assigned_count',(SELECT count(*) FROM public.erp_role_assignments WHERE cafe_id=p_cafe_id AND role_id=x.id)) ORDER BY x.created_at DESC) FROM public.erp_roles x WHERE cafe_id=p_cafe_id),'[]'::jsonb),'assignments',coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id'||jsonb_build_object('name',coalesce(s.name,concat_ws(' ',e.first_name,e.last_name)),'finance_role',s.role,'active',coalesce(s.active,e.active,false))) FROM public.erp_role_assignments x LEFT JOIN public.erp_hr_employees e ON e.cafe_id=x.cafe_id AND e.id=x.employee_id LEFT JOIN public.bf_staff s ON s.cafe_id=x.cafe_id AND s.user_id=coalesce(x.user_id,e.user_id) WHERE x.cafe_id=p_cafe_id),'[]'::jsonb),'users',coalesce((SELECT jsonb_agg(jsonb_build_object('id',user_id,'name',name,'role',role,'active',active)) FROM public.bf_staff WHERE cafe_id=p_cafe_id),'[]'::jsonb),'employees',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',concat_ws(' ',first_name,last_name),'user_id',user_id,'active',active)) FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id),'[]'::jsonb),'events',coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id'-'actor' ORDER BY created_at DESC) FROM (SELECT * FROM public.erp_role_events WHERE cafe_id=p_cafe_id ORDER BY created_at DESC LIMIT 200) x),'[]'::jsonb),'canWrite',true,'ownerId',auth.uid());END IF;
 IF p_request IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>25000 THEN RAISE EXCEPTION 'طلب غير صالح';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,67939));cmd:=jsonb_build_object('action',p_action,'input',p_input);SELECT * INTO prior FROM erp_access_private.requests WHERE cafe_id=p_cafe_id AND id=p_request;
 IF FOUND THEN IF prior.actor<>auth.uid() OR prior.command<>cmd THEN RAISE EXCEPTION 'تعارض معرف العملية' USING ERRCODE='40001';END IF;RETURN prior.result;END IF;
 rid:=(p_input->>'id')::uuid;
 IF p_action='save' THEN
  SELECT * INTO r FROM public.erp_roles WHERE cafe_id=p_cafe_id AND id=rid FOR UPDATE;IF coalesce(r.revision,0) IS DISTINCT FROM (p_input->>'revision')::integer THEN RAISE EXCEPTION 'تغير الدور أعد تحميله' USING ERRCODE='40001';END IF;
  IF p_input->>'kind' NOT IN('user','employee') OR jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'permissions') IS DISTINCT FROM 'object' OR jsonb_typeof(p_input->'blocked') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'راجع نوع الدور والصلاحيات';END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_input->'permissions'))<>cardinality(erp_access_private.domains()) OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_input->'permissions') k WHERE NOT k=ANY(erp_access_private.domains())) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_input->'blocked') b WHERE NOT b=ANY(erp_access_private.domains())) THEN RAISE EXCEPTION 'مجموعة الصلاحيات غير صالحة';END IF;
  FOREACH domain IN ARRAY erp_access_private.domains() LOOP
   v:=p_input->'permissions'->domain;IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(v))<>7 THEN RAISE EXCEPTION 'راجع مجموعة الصلاحيات';END IF;
   FOREACH key IN ARRAY ARRAY['read','create','update','delete','approve','settings','files'] LOOP IF jsonb_typeof(v->key) IS DISTINCT FROM 'boolean' OR ((v->>key)::boolean AND NOT(v->>'read')::boolean) OR (p_input->>'kind'='employee' AND domain NOT IN('hr','organization','custody','attendance','payroll') AND (v->>key)::boolean) THEN RAISE EXCEPTION 'راجع صلاحيات العرض ونوع الموظف';END IF;END LOOP;
  END LOOP;
  INSERT INTO public.erp_roles(cafe_id,id,name,description,kind,active,permissions,blocked) VALUES(p_cafe_id,rid,p_input->>'name',p_input->>'description',p_input->>'kind',(p_input->>'active')::boolean,p_input->'permissions',p_input->'blocked') ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,description=excluded.description,kind=excluded.kind,active=excluded.active,permissions=excluded.permissions,blocked=excluded.blocked,revision=erp_roles.revision+1,updated_at=now() RETURNING erp_roles.revision INTO revision;
 ELSIF p_action='delete_many' THEN
  IF jsonb_typeof(p_input->'entries') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'entries') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'اختر الأدوار المطلوب حذفها';END IF;
  FOR v IN SELECT value FROM jsonb_array_elements(p_input->'entries') LOOP
   DELETE FROM public.erp_roles WHERE cafe_id=p_cafe_id AND id=(v->>'id')::uuid AND erp_roles.revision=(v->>'revision')::integer RETURNING erp_roles.revision INTO revision;IF revision IS NULL THEN RAISE EXCEPTION 'تغير أحد الأدوار أعد تحميل القائمة' USING ERRCODE='40001';END IF;
   INSERT INTO public.erp_role_events(cafe_id,record_id,action,actor) VALUES(p_cafe_id,(v->>'id')::uuid,'delete',auth.uid());
  END LOOP;rid:=p_request;revision:=0;
 ELSIF p_action='delete' THEN
  DELETE FROM public.erp_roles WHERE cafe_id=p_cafe_id AND id=rid AND erp_roles.revision=(p_input->>'revision')::integer RETURNING erp_roles.revision INTO revision;IF revision IS NULL THEN RAISE EXCEPTION 'تغير الدور أعد تحميله' USING ERRCODE='40001';END IF;
 ELSIF p_action='assign' THEN
  SELECT * INTO a FROM public.erp_role_assignments WHERE cafe_id=p_cafe_id AND id=rid FOR UPDATE;IF coalesce(a.revision,0) IS DISTINCT FROM (p_input->>'revision')::integer THEN RAISE EXCEPTION 'تغير التعيين' USING ERRCODE='40001';END IF;
  SELECT * INTO r FROM public.erp_roles WHERE cafe_id=p_cafe_id AND id=(p_input->>'role_id')::uuid AND active;IF r.id IS NULL THEN RAISE EXCEPTION 'اختر دورًا نشطًا';END IF;
  IF num_nonnulls(nullif(p_input->>'user_id',''),nullif(p_input->>'employee_id',''))<>1 THEN RAISE EXCEPTION 'اختر حسابًا أو موظفًا';END IF;
  target:=nullif(p_input->>'user_id','')::uuid;
  IF target IS NULL THEN SELECT * INTO employee FROM public.erp_hr_employees WHERE cafe_id=p_cafe_id AND id=(p_input->>'employee_id')::uuid AND active;IF employee.id IS NULL THEN RAISE EXCEPTION 'الموظف غير متاح';END IF;target:=employee.user_id;
  ELSIF NOT EXISTS(SELECT 1 FROM public.bf_staff WHERE cafe_id=p_cafe_id AND user_id=target AND active) THEN RAISE EXCEPTION 'حساب المستخدم غير نشط';END IF;
  IF target=(SELECT owner_user_id FROM public.cafes WHERE id=p_cafe_id) THEN RAISE EXCEPTION 'لا يمكن تقييد المالك بدور مخصص';END IF;
  IF target IS NOT NULL AND EXISTS(SELECT 1 FROM public.erp_role_assignments x LEFT JOIN public.erp_hr_employees e ON e.cafe_id=x.cafe_id AND e.id=x.employee_id WHERE x.cafe_id=p_cafe_id AND x.id<>rid AND coalesce(x.user_id,e.user_id)=target) THEN RAISE EXCEPTION 'للحساب دور معيّن بالفعل';END IF;
  INSERT INTO public.erp_role_assignments(cafe_id,id,role_id,user_id,employee_id) VALUES(p_cafe_id,rid,r.id,nullif(p_input->>'user_id','')::uuid,nullif(p_input->>'employee_id','')::uuid) ON CONFLICT(cafe_id,id) DO UPDATE SET role_id=excluded.role_id,user_id=excluded.user_id,employee_id=excluded.employee_id,revision=erp_role_assignments.revision+1 RETURNING erp_role_assignments.revision INTO revision;
 ELSIF p_action='unassign' THEN
  DELETE FROM public.erp_role_assignments WHERE cafe_id=p_cafe_id AND id=rid AND erp_role_assignments.revision=(p_input->>'revision')::integer RETURNING erp_role_assignments.revision INTO revision;IF revision IS NULL THEN RAISE EXCEPTION 'تغير التعيين' USING ERRCODE='40001';END IF;
 ELSE RAISE EXCEPTION 'إجراء غير صالح';END IF;
 answer:=jsonb_build_object('id',rid,'revision',revision);INSERT INTO public.erp_role_events(cafe_id,record_id,action,actor) VALUES(p_cafe_id,rid,p_action,auth.uid());INSERT INTO erp_access_private.requests VALUES(p_cafe_id,p_request,auth.uid(),cmd,answer);RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.erp_store(p_cafe_id uuid, p_action text DEFAULT 'list'::text, p_record jsonb DEFAULT NULL::jsonb, p_revision integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.erp_store_records%ROWTYPE; role_name text; record_id uuid; kind_name text; d jsonb; entry jsonb; seen uuid[]; parent_id uuid; a jsonb; form_definition jsonb; field_definition jsonb; field_name text; allowed_names text[]; submission public.erp_store_submissions%ROWTYPE;
BEGIN PERFORM erp_access_private.assert_allowed(p_cafe_id,'store',erp_access_private.action(p_action,coalesce(p_record,'{}')||jsonb_build_object('revision',coalesce(p_revision,0))));
  role_name:=brand_finance_private.role_for(p_cafe_id);
  IF auth.uid() IS NULL OR coalesce(role_name,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  IF p_action='list' THEN RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)-'cafe_id'-'updated_by' ORDER BY x.updated_at DESC,x.id) FROM public.erp_store_records x WHERE x.cafe_id=p_cafe_id),'[]'::jsonb);END IF;
  IF role_name<>'owner' THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';END IF;
  IF p_action IS NULL OR p_action NOT IN ('save','delete','submit','submissions') OR p_record IS NULL THEN RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023';END IF;
  record_id:=(p_record->>'id')::uuid;
  IF record_id IS NULL THEN RAISE EXCEPTION 'Missing record' USING ERRCODE='22023';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,63130));
  SELECT * INTO r FROM public.erp_store_records WHERE cafe_id=p_cafe_id AND id=record_id FOR UPDATE;
  IF p_action IN ('submit','submissions') THEN
    IF r.id IS NULL OR r.kind<>'page' THEN RAISE EXCEPTION 'Page unavailable' USING ERRCODE='42501'; END IF;
    IF p_action='submit' THEN
      SELECT value INTO form_definition FROM jsonb_path_query(r.data,'$.blocks.** ? (@.type == "form")') AS q(value) WHERE value->>'id'=p_record->>'formId' LIMIT 1;
      IF form_definition IS NULL OR jsonb_typeof(p_record->'values') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Form unavailable' USING ERRCODE='22023';END IF;
      allowed_names:=ARRAY[]::text[];
      FOR field_definition IN SELECT value FROM jsonb_path_query(form_definition,'$.** ? (@.type == "input" || @.type == "textarea" || @.type == "select" || @.type == "checkbox" || @.type == "radio")') AS q(value) LOOP
        field_name:=coalesce(nullif(field_definition->>'name',''),field_definition->>'id');allowed_names:=array_append(allowed_names,field_name);
        IF (field_definition->>'required')::boolean AND length(btrim(coalesce(p_record->'values'->>field_name,'')))=0 THEN RAISE EXCEPTION 'أكمل حقول النموذج المطلوبة' USING ERRCODE='22023';END IF;
        IF field_definition->>'type'='select' AND p_record->'values'->>field_name IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(field_definition->'options') o WHERE o=p_record->'values'->>field_name) THEN RAISE EXCEPTION 'Invalid form selection' USING ERRCODE='22023';END IF;
      END LOOP;
      IF EXISTS(SELECT 1 FROM jsonb_each(p_record->'values') x WHERE NOT (x.key=ANY(allowed_names)) OR jsonb_typeof(x.value)<>'string' OR length(x.value#>>'{}')>2000) THEN RAISE EXCEPTION 'Invalid form values' USING ERRCODE='22023';END IF;
      SELECT * INTO submission FROM public.erp_store_submissions WHERE cafe_id=p_cafe_id AND id=(p_record->>'requestId')::uuid;
      IF submission.id IS NOT NULL AND (submission.page_id<>record_id OR submission.values IS DISTINCT FROM p_record->'values') THEN RAISE EXCEPTION 'Form request conflict' USING ERRCODE='22023';END IF;
      INSERT INTO public.erp_store_submissions(id,cafe_id,page_id,values,actor) VALUES((p_record->>'requestId')::uuid,p_cafe_id,record_id,p_record->'values',auth.uid()) ON CONFLICT(cafe_id,id) DO NOTHING;
      RETURN jsonb_build_object('saved',true);
    END IF;
    RETURN coalesce((SELECT jsonb_agg(to_jsonb(s)-'cafe_id'-'actor' ORDER BY s.at DESC) FROM (SELECT * FROM public.erp_store_submissions WHERE cafe_id=p_cafe_id AND page_id=record_id ORDER BY at DESC LIMIT 500) s),'[]'::jsonb);
  END IF;
  IF p_revision IS NULL OR p_revision<0 OR coalesce(r.revision,0)<>p_revision THEN RAISE EXCEPTION 'Store revision conflict' USING ERRCODE='40001';END IF;
  IF p_action='delete' THEN
    IF r.id IS NULL THEN RAISE EXCEPTION 'Record unavailable' USING ERRCODE='42501';END IF;
    IF r.kind IN ('menu','settings') THEN RAISE EXCEPTION 'Cannot delete singleton' USING ERRCODE='22023';END IF;
    IF r.kind='page' AND EXISTS(SELECT 1 FROM public.erp_store_records m CROSS JOIN LATERAL jsonb_array_elements(m.data->'items') i WHERE m.cafe_id=p_cafe_id AND m.kind='menu' AND i->>'type'='content_page' AND i->>'target'=r.id::text) THEN RAISE EXCEPTION 'أزل الصفحة من عناصر القائمة قبل حذفها' USING ERRCODE='22023';END IF;
    IF r.kind='gallery' AND EXISTS(SELECT 1 FROM public.erp_store_records p CROSS JOIN LATERAL jsonb_path_query(p.data,'$.blocks.** ? (@.type == "image")') AS img(value) CROSS JOIN LATERAL jsonb_array_elements(r.data->'assets') AS asset_item(value) WHERE p.cafe_id=p_cafe_id AND p.kind='page' AND img.value->>'assetId'=asset_item.value->>'id') THEN RAISE EXCEPTION 'المعرض يحتوي صورًا مستخدمة في صفحات المتجر' USING ERRCODE='22023';END IF;
    INSERT INTO public.erp_store_events(cafe_id,record_id,action,revision,before_data,actor) VALUES(p_cafe_id,record_id,'delete',r.revision,to_jsonb(r),auth.uid());
    DELETE FROM public.erp_store_records WHERE cafe_id=p_cafe_id AND id=record_id;
    RETURN jsonb_build_object('id',record_id);
  END IF;
  kind_name:=p_record->>'kind';d:=p_record->'data';
  IF kind_name IS NULL OR kind_name NOT IN('page','gallery','menu','settings') OR jsonb_typeof(d) IS DISTINCT FROM 'object' OR octet_length(d::text)>700000 OR (r.id IS NOT NULL AND r.kind<>kind_name) THEN RAISE EXCEPTION 'Invalid store record' USING ERRCODE='22023';END IF;
  IF kind_name='page' THEN
    IF coalesce(d->>'kind','') NOT IN('page','section') THEN RAISE EXCEPTION 'Invalid content kind' USING ERRCODE='22023';END IF;
    PERFORM brand_finance_private.validate_store_blocks(d->'blocks');
    IF EXISTS(SELECT 1 FROM jsonb_path_query(d,'$.blocks.** ? (@.type == "image")') AS img(value) WHERE coalesce(img.value->>'assetId','')<>'' AND NOT EXISTS(SELECT 1 FROM public.erp_store_records g CROSS JOIN LATERAL jsonb_array_elements(g.data->'assets') AS asset_item(value) WHERE g.cafe_id=p_cafe_id AND g.kind='gallery' AND asset_item.value->>'id'=img.value->>'assetId')) THEN RAISE EXCEPTION 'اختر صورة محفوظة في معرض هذه العلامة' USING ERRCODE='22023';END IF;
  ELSIF kind_name='gallery' THEN
    IF jsonb_typeof(d->'assets') IS DISTINCT FROM 'array' OR jsonb_array_length(d->'assets')>100 THEN RAISE EXCEPTION 'Invalid gallery' USING ERRCODE='22023';END IF;
    FOR a IN SELECT value FROM jsonb_array_elements(d->'assets') LOOP
      IF coalesce(a->>'path','') !~ ('^'||p_cafe_id::text||'/[a-f0-9-]{36}\.webp$') OR length(coalesce(a->>'name','')) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Invalid gallery asset ownership' USING ERRCODE='22023';END IF;
    END LOOP;
    IF r.id IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.data->'assets') old_asset WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d->'assets') new_asset WHERE new_asset->>'id'=old_asset->>'id') AND EXISTS(SELECT 1 FROM public.erp_store_records p CROSS JOIN LATERAL jsonb_path_query(p.data,'$.blocks.** ? (@.type == "image")') AS img(value) WHERE p.cafe_id=p_cafe_id AND p.kind='page' AND img.value->>'assetId'=old_asset->>'id')) THEN RAISE EXCEPTION 'الصورة مستخدمة في صفحة متجر عدل الصفحة أولًا' USING ERRCODE='22023';END IF;
  ELSIF kind_name='menu' THEN
    IF jsonb_typeof(d->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(d->'items')>100 THEN RAISE EXCEPTION 'Invalid menu' USING ERRCODE='22023';END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(d->'items') x GROUP BY x->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Duplicate menu IDs' USING ERRCODE='22023';END IF;
    FOR entry IN SELECT value FROM jsonb_array_elements(d->'items') LOOP
      IF coalesce(entry->>'type','') NOT IN('link','category','product','content_page','home','contact_us','rental') OR length(btrim(coalesce(entry->>'title',''))) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Invalid menu item' USING ERRCODE='22023';END IF;
      IF entry->>'type'='link' AND coalesce(entry->>'target','') !~* '^(https?://|mailto:|tel:|/([^/]|$)|#)' THEN RAISE EXCEPTION 'Invalid menu link' USING ERRCODE='22023';END IF;
      IF entry->>'type'='content_page' AND NOT EXISTS(SELECT 1 FROM public.erp_store_records WHERE cafe_id=p_cafe_id AND kind='page' AND id::text=entry->>'target') THEN RAISE EXCEPTION 'Content page unavailable' USING ERRCODE='22023';END IF;
      IF entry->>'type'='product' AND NOT EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id=p_cafe_id AND id::text=entry->>'target' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Product unavailable' USING ERRCODE='22023';END IF;
      IF entry->>'type'='category' AND NOT EXISTS(SELECT 1 FROM public.menu_categories WHERE cafe_id=p_cafe_id AND name=entry->>'target') THEN RAISE EXCEPTION 'Category unavailable' USING ERRCODE='22023';END IF;
      seen:=ARRAY[(entry->>'id')::uuid];parent_id:=(entry->>'parentId')::uuid;
      WHILE parent_id IS NOT NULL LOOP
        IF parent_id=ANY(seen) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d->'items') x WHERE x->>'id'=parent_id::text) THEN RAISE EXCEPTION 'Invalid menu hierarchy' USING ERRCODE='22023';END IF;
        seen:=array_append(seen,parent_id);SELECT (x->>'parentId')::uuid INTO parent_id FROM jsonb_array_elements(d->'items') x WHERE x->>'id'=parent_id::text;
      END LOOP;
    END LOOP;
  ELSE
    IF coalesce(d->>'template','') NOT IN('arabic','english') OR jsonb_typeof(d->'showOutOfStock') IS DISTINCT FROM 'boolean' OR jsonb_typeof(d->'lowStockThreshold') IS DISTINCT FROM 'number' OR (d->>'lowStockThreshold')::numeric NOT BETWEEN 0 AND 1000000 THEN RAISE EXCEPTION 'Invalid store settings' USING ERRCODE='22023';END IF;
    IF d->>'warehouseId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.bf_warehouses WHERE cafe_id=p_cafe_id AND id=(d->>'warehouseId')::uuid AND active) THEN RAISE EXCEPTION 'Warehouse unavailable' USING ERRCODE='22023';END IF;
  END IF;
  INSERT INTO public.erp_store_records(id,cafe_id,kind,title,key,data,revision,updated_by) VALUES(record_id,p_cafe_id,kind_name,p_record->>'title',p_record->>'key',d,p_revision+1,auth.uid())
    ON CONFLICT(cafe_id,id) DO UPDATE SET title=excluded.title,key=excluded.key,data=excluded.data,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=clock_timestamp();
  INSERT INTO public.erp_store_events(cafe_id,record_id,action,revision,before_data,after_data,actor) VALUES(p_cafe_id,record_id,'save',p_revision+1,CASE WHEN r.id IS NULL THEN NULL ELSE to_jsonb(r) END,p_record,auth.uid());
  RETURN (SELECT to_jsonb(x)-'cafe_id'-'updated_by' FROM public.erp_store_records x WHERE x.cafe_id=p_cafe_id AND x.id=record_id);
END $function$

CREATE OR REPLACE FUNCTION public.erp_store_media_access(p_name text, p_write boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tenant_id uuid; role_name text;
BEGIN IF NOT erp_access_private.allowed(nullif(split_part(p_name,'/',1),'')::uuid,'store',CASE WHEN p_write THEN 'files' ELSE 'read' END) THEN RETURN false;END IF;
  IF auth.uid() IS NULL OR p_name !~ '^[a-f0-9-]{36}/[a-f0-9-]{36}\.webp$' THEN RETURN false;END IF;
  tenant_id:=split_part(p_name,'/',1)::uuid;role_name:=brand_finance_private.role_for(tenant_id);
  RETURN coalesce(CASE WHEN p_write THEN role_name='owner' ELSE role_name IN('owner','manager','accountant','auditor') END,false);
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.erp_store_public_read(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v jsonb; c uuid; w uuid; products jsonb; low numeric;
BEGIN
 v:=erp_store_public_private.publication(p_slug);IF v IS NULL THEN RETURN NULL;END IF;c:=(v#>>'{cafe,id}')::uuid;w:=(v#>>'{settings,warehouseId}')::uuid;low:=(v#>>'{settings,lowStockThreshold}')::numeric;
 IF w IS NULL THEN SELECT id INTO w FROM public.bf_warehouses WHERE cafe_id=c AND active ORDER BY is_default DESC,name,id LIMIT 1;END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY x->>'category',x->>'name',x->>'id'),'[]') INTO products FROM (
 SELECT jsonb_build_object('id',p.id,'name',p.name,'description',coalesce(p.description,''),'price',p.price,'imageUrl',p.image_url,'category',coalesce(cat.name,p.legacy_category,''),'available',p.available AND (s.parts=0 OR coalesce(s.qty,0)>0),'lowStock',s.parts>0 AND coalesce(s.qty,0)>0 AND s.qty<=low) x
 FROM public.menu_products p LEFT JOIN public.menu_categories cat ON cat.id=p.category_id AND cat.cafe_id=p.cafe_id
 CROSS JOIN LATERAL(SELECT count(*) parts,min(CASE WHEN i.active THEN (coalesce((SELECT sum(st.quantity) FROM public.bf_stock st JOIN public.bf_warehouses wh ON wh.cafe_id=st.cafe_id AND wh.id=st.warehouse_id AND wh.active WHERE st.cafe_id=c AND st.warehouse_id=w AND st.item_id=l.item_id),0)-erp_inventory_private.reserved(c,l.item_id,w))/l.quantity ELSE 0 END) qty FROM public.bf_item_product_links l JOIN public.bf_items i ON i.cafe_id=l.cafe_id AND i.id=l.item_id WHERE l.cafe_id=c AND l.product_id=p.id)s
 WHERE p.cafe_id=c AND p.deleted_at IS NULL AND p.branch_id IS NULL AND (coalesce((v#>>'{settings,showOutOfStock}')::boolean,false) OR (p.available AND (s.parts=0 OR coalesce(s.qty,0)>0)))
 ) q;
 RETURN (v-'assets')||jsonb_build_object('assets',coalesce((SELECT jsonb_agg(a-'path') FROM jsonb_array_elements(v->'assets') a),'[]'),'products',products);
END$function$

CREATE OR REPLACE FUNCTION public.erp_store_public_submit(p_slug text, p_version uuid, p_page uuid, p_form uuid, p_request uuid, p_values jsonb, p_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v jsonb;c uuid;b jsonb;f jsonb;n text;names text[]:=ARRAY[]::text[];old public.erp_store_public_submissions%ROWTYPE;used integer;
BEGIN
 v:=erp_store_public_private.publication(p_slug);IF v IS NULL OR v->>'versionId' IS DISTINCT FROM p_version::text THEN RAISE EXCEPTION 'Store publication unavailable' USING ERRCODE='42501';END IF;c:=(v#>>'{cafe,id}')::uuid;
 IF p_request IS NULL OR p_fingerprint IS NULL OR p_fingerprint !~ '^[a-f0-9]{64}$' OR jsonb_typeof(p_values) IS DISTINCT FROM 'object' OR octet_length(p_values::text)>20000 THEN RAISE EXCEPTION 'Invalid submission' USING ERRCODE='22023';END IF;
 SELECT form INTO b FROM jsonb_array_elements(v->'pages') page CROSS JOIN LATERAL jsonb_path_query(page,'$.data.blocks.** ? (@.type == "form")') form WHERE page->>'id'=p_page::text AND form->>'id'=p_form::text LIMIT 1;
 IF b IS NULL THEN RAISE EXCEPTION 'Unknown public form' USING ERRCODE='22023';END IF;
 FOR f IN SELECT DISTINCT value FROM jsonb_path_query(b,'$.children.** ? (@.type == "input" || @.type == "textarea" || @.type == "select" || @.type == "checkbox" || @.type == "radio")') AS q(value) LOOP
  n:=coalesce(nullif(f->>'name',''),f->>'id');names:=array_append(names,n);
  IF ((f->>'required')::boolean AND coalesce(btrim(p_values->>n),'')='') OR (p_values ? n AND (jsonb_typeof(p_values->n)<>'string' OR length(p_values->>n)>2000)) OR (f->>'type' IN('select','radio') AND coalesce(p_values->>n,'')<>'' AND NOT f->'options' ? (p_values->>n)) OR (f->>'type'='checkbox' AND coalesce(p_values->>n,'') NOT IN('','on')) THEN RAISE EXCEPTION 'Invalid form field' USING ERRCODE='22023';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_values) k WHERE NOT k=ANY(names)) THEN RAISE EXCEPTION 'Unknown form field' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(63131,hashtext(c::text||p_request::text));
 SELECT * INTO old FROM public.erp_store_public_submissions WHERE cafe_id=c AND id=p_request;
 IF FOUND THEN IF old.page_id<>p_page OR old.form_id<>p_form OR old.version_id<>p_version OR old.values<>p_values OR old.fingerprint<>p_fingerprint THEN RAISE EXCEPTION 'Request conflict' USING ERRCODE='23505';END IF;RETURN jsonb_build_object('id',old.id);END IF;
 INSERT INTO erp_store_public_private.rates(cafe_id,fingerprint,hour,used) VALUES(c,p_fingerprint,date_trunc('hour',now()),1) ON CONFLICT(cafe_id,fingerprint,hour) DO UPDATE SET used=rates.used+1 RETURNING rates.used INTO used;
 IF used>30 THEN RAISE EXCEPTION 'Submission rate exceeded' USING ERRCODE='54000';END IF;
 IF (SELECT count(*) FROM public.erp_store_public_submissions WHERE cafe_id=c AND fingerprint=p_fingerprint AND created_at>now()-interval '1 minute')>=5 THEN RAISE EXCEPTION 'Submission rate exceeded' USING ERRCODE='54000';END IF;
 INSERT INTO public.erp_store_public_submissions(cafe_id,id,version_id,page_id,form_id,values,fingerprint) VALUES(c,p_request,p_version,p_page,p_form,p_values,p_fingerprint);
 RETURN jsonb_build_object('id',p_request);
END$function$

CREATE OR REPLACE FUNCTION public.erp_store_publish(p_cafe uuid, p_action text DEFAULT 'read'::text, p_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE pub public.erp_store_publications%ROWTYPE; pages jsonb; menus jsonb; assets jsonb; settings jsonb; snapshot jsonb; vid uuid; row record; b jsonb; f jsonb; names text[]; home uuid; contact uuid; footer uuid;
BEGIN
 IF brand_finance_private.role_for(p_cafe) IS DISTINCT FROM 'owner' OR erp_store_public_private.enabled(p_cafe) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Store publication denied' USING ERRCODE='42501'; END IF;
 IF p_action IS NULL OR p_action NOT IN('read','submissions','publish','unpublish') THEN RAISE EXCEPTION 'Invalid publication action' USING ERRCODE='22023'; END IF;
 PERFORM erp_access_private.assert_allowed(p_cafe,'store',CASE WHEN p_action='read' OR p_action='submissions' THEN 'read' ELSE 'update' END);
 IF p_action IN('publish','unpublish') THEN
  PERFORM pg_advisory_xact_lock(63130,hashtext(p_cafe::text));
  SELECT * INTO pub FROM public.erp_store_publications WHERE cafe_id=p_cafe FOR UPDATE;
 ELSE
  SELECT * INTO pub FROM public.erp_store_publications WHERE cafe_id=p_cafe;
 END IF;
 IF p_action='submissions' THEN RETURN coalesce((SELECT jsonb_agg(x) FROM (SELECT id,page_id,form_id,values,created_at AS at FROM public.erp_store_public_submissions WHERE cafe_id=p_cafe AND page_id=(p_input->>'pageId')::uuid ORDER BY created_at DESC LIMIT 500)x),'[]'); END IF;
 IF p_action='read' THEN RETURN coalesce(to_jsonb(pub)-'cafe_id','{"enabled":false,"revision":0}'::jsonb)||jsonb_build_object('selection',(SELECT data->'selection' FROM public.erp_store_public_versions WHERE cafe_id=p_cafe AND id=pub.version_id)); END IF;
 IF coalesce(pub.revision,0) IS DISTINCT FROM (p_input->>'revision')::integer THEN RAISE EXCEPTION 'Publication changed' USING ERRCODE='40001'; END IF;
 IF p_action='unpublish' THEN IF pub.version_id IS NOT NULL THEN INSERT INTO public.erp_store_events(cafe_id,record_id,action,revision,before_data,after_data,actor) VALUES(p_cafe,pub.version_id,'unpublish',pub.revision+1,to_jsonb(pub),jsonb_build_object('enabled',false),auth.uid());END IF;UPDATE public.erp_store_publications SET enabled=false,revision=revision+1,updated_at=now() WHERE cafe_id=p_cafe; RETURN public.erp_store_publish(p_cafe,'read'); END IF;
 IF p_action<>'publish' OR jsonb_typeof(p_input->'pageIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p_input->'pageIds')>100 THEN RAISE EXCEPTION 'Invalid publication' USING ERRCODE='22023'; END IF;
 home:=(p_input->>'homePageId')::uuid;contact:=(p_input->>'contactPageId')::uuid;footer:=(p_input->>'footerSectionId')::uuid;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_input->'pageIds') a WHERE NOT EXISTS(SELECT 1 FROM public.erp_store_records r WHERE r.cafe_id=p_cafe AND r.kind='page' AND r.id=a::uuid)) THEN RAISE EXCEPTION 'Unknown page' USING ERRCODE='22023'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title,'key',key,'data',data) ORDER BY title,id),'[]') INTO pages FROM public.erp_store_records WHERE cafe_id=p_cafe AND kind='page' AND p_input->'pageIds' ? id::text;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY[home,contact,footer]) v WHERE v IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pages) a WHERE a->>'id'=v::text)) THEN RAISE EXCEPTION 'Select the referenced pages' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(pages) a WHERE (a->>'id'=footer::text AND a#>>'{data,kind}'<>'section') OR (a->>'id'=ANY(ARRAY[home::text,contact::text]) AND a#>>'{data,kind}'<>'page')) THEN RAISE EXCEPTION 'Invalid page placement' USING ERRCODE='22023'; END IF;
 SELECT data INTO menus FROM public.erp_store_records WHERE cafe_id=p_cafe AND kind='menu';
 menus:=coalesce(menus,'{"items":[]}'::jsonb);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(menus->'items') m WHERE m->>'type'='content_page' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pages) a WHERE a->>'id'=m->>'target' AND a#>>'{data,kind}'='page')) THEN RAISE EXCEPTION 'A menu page is not selected for publication' USING ERRCODE='22023'; END IF;
 SELECT data INTO settings FROM public.erp_store_records WHERE cafe_id=p_cafe AND kind='settings';
 IF contact IS NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(menus->'items') m WHERE m->>'type'='contact_us') THEN RAISE EXCEPTION 'Choose a contact page' USING ERRCODE='22023'; END IF;
 settings:=coalesce(settings,'{"template":"arabic","lowStockThreshold":10,"showOutOfStock":false,"warehouseId":null}'::jsonb);
 -- Published forms must have unique names and cannot contain nested forms.
 FOR row IN SELECT value AS page FROM jsonb_array_elements(pages) LOOP
  PERFORM brand_finance_private.validate_store_blocks(row.page#>'{data,blocks}',0);
  FOR b IN SELECT value FROM jsonb_path_query(row.page,'$.data.blocks.** ? (@.type == "form")') AS q(value) LOOP
   names:=ARRAY[]::text[];
   FOR f IN SELECT DISTINCT value FROM jsonb_path_query(b,'$.children.** ? (@.type == "input" || @.type == "textarea" || @.type == "select" || @.type == "checkbox" || @.type == "radio" || @.type == "form")') AS q(value) LOOP
    IF f->>'type'='form' OR coalesce(nullif(f->>'name',''),f->>'id')='__branda_store_guard' OR coalesce(nullif(f->>'name',''),f->>'id')=ANY(names) THEN RAISE EXCEPTION 'Duplicate or nested form fields' USING ERRCODE='22023'; END IF;
    names:=array_append(names,coalesce(nullif(f->>'name',''),f->>'id'));
   END LOOP;
  END LOOP;
 END LOOP;
 SELECT coalesce(jsonb_agg(a-'url'),'[]') INTO assets FROM public.erp_store_records r CROSS JOIN LATERAL jsonb_array_elements(r.data->'assets') a WHERE r.cafe_id=p_cafe AND r.kind='gallery' AND EXISTS(SELECT 1 FROM jsonb_path_query(pages,'$.**.assetId') v WHERE v#>>'{}'=a->>'id');
 snapshot:=jsonb_build_object('pages',pages,'menu',menus,'settings',settings,'assets',assets,'selection',jsonb_build_object('pageIds',p_input->'pageIds','homePageId',home,'contactPageId',contact,'footerSectionId',footer));
 INSERT INTO public.erp_store_public_versions(cafe_id,data,created_by) VALUES(p_cafe,snapshot,auth.uid()) RETURNING id INTO vid;
 INSERT INTO public.erp_store_publications(cafe_id,version_id,enabled) VALUES(p_cafe,vid,true) ON CONFLICT(cafe_id) DO UPDATE SET version_id=excluded.version_id,enabled=true,revision=erp_store_publications.revision+1,updated_at=now();
 INSERT INTO public.erp_store_events(cafe_id,record_id,action,revision,before_data,after_data,actor) VALUES(p_cafe,vid,'publish',coalesce(pub.revision,0)+1,to_jsonb(pub),jsonb_build_object('versionId',vid,'selection',snapshot->'selection'),auth.uid());
 RETURN public.erp_store_publish(p_cafe,'read');
END$function$

CREATE OR REPLACE FUNCTION public.erp_system_api(p_hash text, p_resource text, p_method text DEFAULT 'GET'::text, p_input jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE k public.erp_system_api_keys;h erp_settings_private.api_hashes;c public.cafes;rows jsonb;answer jsonb;v_status integer:=200;offset_value integer:=coalesce((p_input->>'offset')::integer,0);requested uuid:=(p_input->>'id')::uuid;prior_claim text;domain text;
BEGIN
 IF p_hash!~'^[a-f0-9]{64}$' THEN RETURN jsonb_build_object('status',401,'error','invalid_key');END IF;
 SELECT * INTO h FROM erp_settings_private.api_hashes WHERE token_hash=p_hash FOR UPDATE;
 SELECT * INTO k FROM public.erp_system_api_keys WHERE id=h.id AND active AND (expires_at IS NULL OR expires_at>now());
 IF k.id IS NULL THEN RETURN jsonb_build_object('status',401,'error','invalid_key');END IF;
 SELECT * INTO c FROM public.cafes WHERE id=k.cafe_id AND deleted_at IS NULL;
 IF c.id IS NULL OR c.status<>'active' OR k.created_by IS DISTINCT FROM c.owner_user_id OR NOT platform_access_private.service_enabled(c.id,'finance') OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=c.owner_user_id AND status='active') THEN RETURN jsonb_build_object('status',403,'error','unavailable');END IF;
 IF h.window_started<now()-interval '1 minute' THEN UPDATE erp_settings_private.api_hashes SET window_started=now(),window_count=1 WHERE id=k.id;ELSIF h.window_count>=60 THEN RETURN jsonb_build_object('status',429,'error','rate_limit');ELSE UPDATE erp_settings_private.api_hashes SET window_count=window_count+1 WHERE id=k.id;END IF;
 IF p_resource='capabilities' AND p_method='GET' THEN RETURN jsonb_build_object('status',200,'data',jsonb_build_object('scopes',k.scopes,'purpose',k.purpose,'brand',c.name));END IF;
 domain:=CASE p_resource WHEN 'invoices' THEN 'finance' ELSE p_resource END;
 IF p_resource NOT IN('customers','invoices','inventory','requests') OR p_method NOT IN('GET','POST') OR p_method='POST' AND p_resource<>'requests' THEN v_status:=404;
 ELSIF NOT k.scopes ? (p_resource||CASE WHEN p_method='GET' THEN ':read' ELSE ':write' END) OR EXISTS(SELECT 1 FROM public.erp_system_settings WHERE cafe_id=k.cafe_id AND kind='apps' AND payload->domain='false'::jsonb) THEN v_status:=403;
 ELSIF offset_value NOT BETWEEN 0 AND 1000000 OR octet_length(p_input::text)>524288 THEN v_status:=400;
 ELSE
  IF p_method='POST' THEN
   prior_claim:=current_setting('request.jwt.claim.sub',true);PERFORM set_config('request.jwt.claim.sub',c.owner_user_id::text,true);
   BEGIN answer:=public.erp_requests_write(k.cafe_id,'record',p_input->'data',(p_input->>'requestId')::uuid);EXCEPTION WHEN OTHERS THEN v_status:=400;answer:=jsonb_build_object('error','invalid_request');END;
   PERFORM set_config('request.jwt.claim.sub',coalesce(prior_claim,''),true);
  ELSIF p_resource='customers' THEN
   SELECT coalesce(jsonb_agg(x),'[]') INTO rows FROM(SELECT id,name,phone,email,tax_number,active FROM public.bf_parties WHERE cafe_id=k.cafe_id AND kind='customer' AND (requested IS NULL OR id=requested) ORDER BY id LIMIT 100 OFFSET offset_value)x;answer:=jsonb_build_object('rows',rows,'offset',offset_value,'limit',100);
  ELSIF p_resource='invoices' THEN
   SELECT coalesce(jsonb_agg(x),'[]') INTO rows FROM(SELECT i.document_id id,d.number,d.party_id,d.created_at,d.total,(brand_finance_private.document_state(d.cafe_id,d.id)->>'outstanding')::numeric outstanding,i.snapshot->>'currency' currency FROM public.bf_company_invoices i JOIN public.bf_documents d ON d.cafe_id=i.cafe_id AND d.id=i.document_id WHERE i.cafe_id=k.cafe_id AND (requested IS NULL OR i.document_id=requested) ORDER BY d.created_at DESC,d.id LIMIT 100 OFFSET offset_value)x;answer:=jsonb_build_object('rows',rows,'offset',offset_value,'limit',100);
  ELSIF p_resource='inventory' THEN
   SELECT coalesce(jsonb_agg(x),'[]') INTO rows FROM(SELECT id,name,sku,barcode,active FROM public.bf_items WHERE cafe_id=k.cafe_id AND (requested IS NULL OR id=requested) ORDER BY id LIMIT 100 OFFSET offset_value)x;answer:=jsonb_build_object('rows',rows,'offset',offset_value,'limit',100);
  ELSE
   SELECT coalesce(jsonb_agg(x),'[]') INTO rows FROM(SELECT id,number,type_id,status,closed,employee_id,user_id,payload,created_at,revision FROM public.erp_staff_requests WHERE cafe_id=k.cafe_id AND NOT deleted AND (requested IS NULL OR id=requested) ORDER BY created_at DESC,id LIMIT 100 OFFSET offset_value)x;answer:=jsonb_build_object('rows',rows,'offset',offset_value,'limit',100);
  END IF;
 END IF;
 INSERT INTO public.erp_system_api_usage(cafe_id,key_id,resource,method,status,purpose) VALUES(k.cafe_id,k.id,left(p_resource,80),left(p_method,10),v_status,k.purpose);
 UPDATE public.erp_system_api_keys SET last_used_at=now() WHERE id=k.id;
 RETURN jsonb_build_object('status',v_status,'data',CASE WHEN v_status=200 THEN answer ELSE NULL END,'error',CASE WHEN v_status=200 THEN NULL ELSE 'not_allowed' END);
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_backup(p_cafe uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE t record;rows jsonb;tables jsonb:='{}';total bigint:=0;BEGIN
 PERFORM erp_settings_private.authorize(p_cafe);
 FOR t IN SELECT c.relname FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN('r','p') AND(c.relname LIKE 'erp\_%' ESCAPE '\' OR c.relname LIKE 'bf\_%' ESCAPE '\' OR c.relname='branches') AND c.relname NOT IN('erp_system_integrations','erp_system_api_keys','erp_system_api_usage') AND EXISTS(SELECT 1 FROM pg_catalog.pg_attribute a WHERE a.attrelid=c.oid AND a.attname='cafe_id' AND NOT a.attisdropped) ORDER BY c.relname LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) FROM(SELECT * FROM public.%I WHERE cafe_id=$1 LIMIT 50001)x',t.relname) INTO rows USING p_cafe;
  IF jsonb_array_length(rows)>50000 THEN RAISE EXCEPTION 'حجم أحد سجلات النظام يتطلب نسخة مجدولة من الدعم';END IF;
  total:=total+octet_length(rows::text);IF total>80000000 THEN RAISE EXCEPTION 'حجم البيانات يتطلب نسخة مجدولة من الدعم';END IF;
  tables:=tables||jsonb_build_object(t.relname,rows);
 END LOOP;
 RETURN jsonb_build_object('format','branda-erp-backup-v1','createdAt',now(),'cafeId',p_cafe,'tables',tables,'exclusions',jsonb_build_array('Authentication and login credentials','API access keys and provider credentials','POS/menu/loyalty tables outside ERP','Storage buckets outside erp-record-files and erp-store-media'),'files',coalesce((SELECT jsonb_agg(jsonb_build_object('bucket',bucket_id,'path',name,'size',coalesce((metadata->>'size')::bigint,0))) FROM storage.objects WHERE bucket_id IN('erp-record-files','erp-store-media') AND split_part(name,'/',1)=p_cafe::text),'[]'));
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_integration_verified(p_cafe uuid, p_id uuid, p_revision integer, p_actor uuid, p_ok boolean, p_message text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe AND owner_user_id=p_actor AND deleted_at IS NULL) THEN RAISE EXCEPTION 'غير مصرح';END IF;
 UPDATE public.erp_system_integrations SET verification=CASE WHEN p_ok THEN 'verified' ELSE 'failed' END,verified_at=CASE WHEN p_ok THEN now() ELSE NULL END,verification_message=left(p_message,300),enabled=false,revision=revision+1 WHERE cafe_id=p_cafe AND id=p_id AND revision=p_revision;
 IF NOT FOUND THEN RETURN false;END IF;
 INSERT INTO public.erp_system_events(cafe_id,actor,action,target) VALUES(p_cafe,p_actor,'integration_verify',p_id::text);RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_numbering(p_cafe uuid, p_action text DEFAULT 'get'::text, p_input jsonb DEFAULT '{}'::jsonb, p_request uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE cfg jsonb;rev integer;ctx text:=p_input->>'context';prior erp_settings_private.requests;result jsonb;BEGIN
 PERFORM erp_settings_private.authorize(p_cafe);
 IF p_action='get' THEN RETURN coalesce((SELECT jsonb_agg(payload||jsonb_build_object('context',context,'revision',revision) ORDER BY context) FROM public.erp_system_numbering WHERE cafe_id=p_cafe),'[]');END IF;
 IF p_action<>'save' OR p_request IS NULL OR p_input->>'revision' IS NULL OR NOT EXISTS(SELECT 1 FROM erp_settings_private.number_contexts WHERE context=ctx) THEN RAISE EXCEPTION 'سياق الترقيم غير صالح';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text||':system-settings',0));
 SELECT * INTO prior FROM erp_settings_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;
 IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>'numbering' OR prior.fingerprint<>md5(p_input::text) THEN RAISE EXCEPTION 'معرف العملية مستخدم';END IF;RETURN prior.result;END IF;
 SELECT revision INTO rev FROM public.erp_system_numbering WHERE cafe_id=p_cafe AND context=ctx FOR UPDATE;
 IF coalesce(rev,0) IS DISTINCT FROM (p_input->>'revision')::integer THEN RAISE EXCEPTION 'تغير التسلسل بعد إنشاء سجل أعد تحميله' USING ERRCODE='40001';END IF;
 cfg:=p_input-'context'-'revision';
 IF coalesce(cfg->>'mode','') NOT IN('numeric','alpha','alphanumeric') OR coalesce(cfg->>'reset','') NOT IN('continue','separate','change') OR (cfg->>'next')::bigint NOT BETWEEN 1 AND 999999999999 OR cfg->>'next' IS NULL OR (cfg->>'padding')::integer NOT BETWEEN 1 AND 12 OR cfg->>'padding' IS NULL OR length(coalesce(cfg->>'prefix',''))>27 OR cfg->>'prefix'~'[^A-Za-z0-9ء-ي{}_\-]' OR replace(replace(replace(replace(cfg->>'prefix','{YYYY}',''),'{YY}',''),'{MM}',''),'{DD}','')~'[{}]' OR cfg->'unique' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'راجع صيغة الترقيم والرقم التالي';END IF;
 INSERT INTO public.erp_system_numbering(cafe_id,context,payload) VALUES(p_cafe,ctx,cfg) ON CONFLICT(cafe_id,context) DO UPDATE SET payload=excluded.payload,revision=erp_system_numbering.revision+1;
 DELETE FROM erp_settings_private.number_counters WHERE cafe_id=p_cafe AND context=ctx;
 result:=jsonb_build_object('context',ctx,'revision',coalesce(rev,0)+1);
 INSERT INTO public.erp_system_events(cafe_id,actor,action,target) VALUES(p_cafe,auth.uid(),'numbering',ctx);
 INSERT INTO erp_settings_private.requests VALUES(p_cafe,p_request,auth.uid(),'numbering',md5(p_input::text),result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_oauth_consent(p_cafe uuid, p_client uuid, p_redirect text, p_challenge text, p_scopes jsonb, p_code_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$BEGIN
 PERFORM erp_settings_private.authorize(p_cafe);
 IF p_code_hash IS NULL OR p_code_hash!~'^[a-f0-9]{64}$' OR p_challenge IS NULL OR p_challenge!~'^[A-Za-z0-9_-]{43}$' OR jsonb_typeof(p_scopes) IS DISTINCT FROM 'array' OR jsonb_array_length(p_scopes) NOT BETWEEN 1 AND 4 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_scopes) v WHERE v NOT IN('customers:read','invoices:read','inventory:read','requests:read')) OR NOT EXISTS(SELECT 1 FROM erp_settings_private.oauth_clients WHERE id=p_client AND redirect_uris ? p_redirect) THEN RAISE EXCEPTION 'invalid_request' USING ERRCODE='22023';END IF;
 IF (SELECT count(*) FROM erp_settings_private.oauth_grants WHERE actor=auth.uid() AND expires_at>now() AND used_at IS NULL)>20 THEN RAISE EXCEPTION 'rate_limited' USING ERRCODE='22023';END IF;
 INSERT INTO erp_settings_private.oauth_grants(code_hash,client_id,cafe_id,actor,redirect_uri,challenge,scopes) VALUES(p_code_hash,p_client,p_cafe,auth.uid(),p_redirect,p_challenge,p_scopes);
 INSERT INTO public.erp_system_events(cafe_id,actor,action,target) VALUES(p_cafe,auth.uid(),'oauth_consent',p_client::text);
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_oauth_register(p_name text, p_redirects jsonb, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE c erp_settings_private.oauth_clients;BEGIN
 IF p_name IS NULL OR length(trim(p_name)) NOT BETWEEN 1 AND 100 OR p_hash IS NULL OR p_hash!~'^[a-f0-9]{64}$' OR jsonb_typeof(p_redirects) IS DISTINCT FROM 'array' OR jsonb_array_length(p_redirects) NOT BETWEEN 1 AND 5 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_redirects) v WHERE length(v)>2000 OR v!~'^https://[^/@?#]+(/[^#]*)?$' AND v!~'^http://(localhost|127\.0\.0\.1)(:[0-9]+)?(/[^#]*)?$') THEN RAISE EXCEPTION 'invalid_client_metadata' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('erp_oauth_registration',0));
 IF (SELECT count(*) FROM erp_settings_private.oauth_clients WHERE registration_hash=p_hash AND created_at>now()-interval '1 hour')>=10 OR (SELECT count(*) FROM erp_settings_private.oauth_clients WHERE created_at>now()-interval '1 day')>=1000 THEN RETURN jsonb_build_object('error','rate_limited');END IF;
 INSERT INTO erp_settings_private.oauth_clients(name,redirect_uris,registration_hash) VALUES(trim(p_name),p_redirects,p_hash) RETURNING * INTO c;
 RETURN jsonb_build_object('id',c.id,'name',c.name,'redirectUris',c.redirect_uris);
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_oauth_token(p_client uuid, p_grant text, p_hash text, p_redirect text, p_challenge text, p_access_hash text, p_prefix text, p_refresh_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE g erp_settings_private.oauth_grants;r erp_settings_private.oauth_refresh;k public.erp_system_api_keys;actor_id uuid;BEGIN
 IF p_hash IS NULL OR p_hash!~'^[a-f0-9]{64}$' OR p_access_hash IS NULL OR p_access_hash!~'^[a-f0-9]{64}$' OR p_refresh_hash IS NULL OR p_refresh_hash!~'^[a-f0-9]{64}$' OR p_prefix IS NULL OR length(p_prefix) NOT BETWEEN 7 AND 20 THEN RETURN jsonb_build_object('error','invalid_request');END IF;
 IF p_grant='authorization_code' THEN
  SELECT * INTO g FROM erp_settings_private.oauth_grants WHERE code_hash=p_hash FOR UPDATE;
  IF g.code_hash IS NULL OR g.client_id IS DISTINCT FROM p_client OR g.used_at IS NOT NULL OR g.expires_at<=now() OR g.redirect_uri IS DISTINCT FROM p_redirect OR g.challenge IS DISTINCT FROM p_challenge THEN RETURN jsonb_build_object('error','invalid_grant');END IF;
  IF NOT EXISTS(SELECT 1 FROM public.cafes c JOIN public.profiles p ON p.id=c.owner_user_id WHERE c.id=g.cafe_id AND c.owner_user_id=g.actor AND public.brand_account_not_cancelled(c.id) AND p.status='active') THEN RETURN jsonb_build_object('error','invalid_grant');END IF;
  actor_id:=g.actor;
  INSERT INTO public.erp_system_api_keys(id,cafe_id,created_by,name,prefix,scopes,purpose,expires_at) SELECT gen_random_uuid(),g.cafe_id,g.actor,'OAuth · '||name,p_prefix,g.scopes,'copilot',now()+interval '1 hour' FROM erp_settings_private.oauth_clients WHERE id=p_client RETURNING * INTO k;
  INSERT INTO erp_settings_private.api_hashes(id,token_hash) VALUES(k.id,p_access_hash);
  UPDATE erp_settings_private.oauth_grants SET used_at=now() WHERE code_hash=p_hash;
 ELSIF p_grant='refresh_token' THEN
  SELECT * INTO r FROM erp_settings_private.oauth_refresh WHERE token_hash=p_hash FOR UPDATE;
  IF r.token_hash IS NULL OR r.client_id IS DISTINCT FROM p_client OR r.expires_at<=now() THEN RETURN jsonb_build_object('error','invalid_grant');END IF;IF r.used_at IS NOT NULL THEN UPDATE public.erp_system_api_keys SET active=false,revision=revision+1 WHERE id=r.key_id AND active;RETURN jsonb_build_object('error','invalid_grant');END IF;
  SELECT * INTO k FROM public.erp_system_api_keys WHERE id=r.key_id FOR UPDATE;
  IF k.id IS NULL OR NOT k.active OR k.purpose<>'copilot' THEN RETURN jsonb_build_object('error','invalid_grant');END IF;
  SELECT c.owner_user_id INTO actor_id FROM public.cafes c JOIN public.profiles p ON p.id=c.owner_user_id WHERE c.id=k.cafe_id AND c.owner_user_id=k.created_by AND public.brand_account_not_cancelled(c.id) AND p.status='active';
  IF actor_id IS NULL THEN RETURN jsonb_build_object('error','invalid_grant');END IF;
  UPDATE public.erp_system_api_keys SET expires_at=now()+interval '1 hour',prefix=p_prefix,revision=revision+1 WHERE id=k.id;
  UPDATE erp_settings_private.api_hashes SET token_hash=p_access_hash WHERE id=k.id;
  UPDATE erp_settings_private.oauth_refresh SET used_at=now() WHERE token_hash=p_hash;
 ELSE RETURN jsonb_build_object('error','unsupported_grant_type');END IF;
 INSERT INTO erp_settings_private.oauth_refresh(token_hash,client_id,key_id) VALUES(p_refresh_hash,p_client,k.id);
 INSERT INTO public.erp_system_events(cafe_id,actor,action,target) VALUES(k.cafe_id,actor_id,'oauth_token',k.id::text);
 RETURN jsonb_build_object('scope',(SELECT string_agg(v,' ') FROM jsonb_array_elements_text(k.scopes) v),'expires_in',3600);
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_payment_collect(p_cafe uuid, p_proof uuid, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE proof erp_settings_private.payment_proofs;b uuid;account_id uuid;prior_proof text:=current_setting('erp.payment_proof',true);prior_cafe text:=current_setting('erp.branch_cafe',true);prior_branch text:=current_setting('erp.branch_id',true);result jsonb;BEGIN
 PERFORM erp_settings_private.authorize(p_cafe);
 SELECT * INTO proof FROM erp_settings_private.payment_proofs WHERE cafe_id=p_cafe AND id=p_proof FOR UPDATE;
 IF proof.id IS NULL OR proof.actor IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'تأكيد الدفع غير متاح' USING ERRCODE='42501';END IF;
 SELECT branch_id INTO b FROM public.erp_branch_documents WHERE cafe_id=p_cafe AND document_id=proof.invoice_id;
 IF b IS NOT NULL AND NOT erp_branch_private.branch_allowed(p_cafe,b) THEN RAISE EXCEPTION 'فرع الفاتورة غير متاح للتحصيل' USING ERRCODE='42501';END IF;
 SELECT nullif(config->>'accountId','')::uuid INTO account_id FROM public.erp_system_integrations WHERE cafe_id=p_cafe AND id=proof.integration_id;
 IF proof.used_at IS NULL AND NOT erp_branch_private.allowed_resource(p_cafe,b,'account',account_id) THEN RAISE EXCEPTION 'حساب التحصيل غير متاح لفرع الفاتورة' USING ERRCODE='42501';END IF;
 PERFORM set_config('erp.payment_proof',p_proof::text,true);PERFORM set_config('erp.branch_cafe',p_cafe::text,true);PERFORM set_config('erp.branch_id',coalesce(b::text,''),true);
 result:=erp_settings_private.erp_system_payment_collect_before_source_branch(p_cafe,p_proof,p_request);
 PERFORM set_config('erp.payment_proof',coalesce(prior_proof,''),true);PERFORM set_config('erp.branch_cafe',coalesce(prior_cafe,''),true);PERFORM set_config('erp.branch_id',coalesce(prior_branch,''),true);
 RETURN result;
EXCEPTION WHEN OTHERS THEN
 PERFORM set_config('erp.payment_proof',coalesce(prior_proof,''),true);PERFORM set_config('erp.branch_cafe',coalesce(prior_cafe,''),true);PERFORM set_config('erp.branch_id',coalesce(prior_branch,''),true);RAISE;
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_payment_proof(p_cafe uuid, p_integration uuid, p_revision integer, p_actor uuid, p_provider_id text, p_invoice uuid, p_amount numeric, p_currency text, p_fingerprint text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE i public.erp_system_integrations;proof erp_settings_private.payment_proofs;BEGIN
 SELECT * INTO i FROM public.erp_system_integrations WHERE cafe_id=p_cafe AND id=p_integration AND revision=p_revision AND channel='payment' AND enabled AND verification='verified' FOR SHARE;
 IF i.id IS NULL OR coalesce((i.config->>'sandbox')::boolean,false) OR p_provider_id IS NULL OR p_amount IS NULL OR p_currency IS NULL OR p_fingerprint IS NULL OR NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe AND owner_user_id=p_actor AND deleted_at IS NULL) OR p_provider_id!~'^[A-Za-z0-9_-]{5,100}$' OR p_amount<=0 OR p_amount>1e9 OR p_amount<>round(p_amount,2) OR p_currency NOT IN('SAR','USD','EUR','GBP','AED') OR p_fingerprint!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'بيانات تأكيد الدفع غير صالحة';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text||i.provider||p_provider_id,0));
 SELECT * INTO proof FROM erp_settings_private.payment_proofs WHERE cafe_id=p_cafe AND provider=i.provider AND provider_id=p_provider_id FOR UPDATE;
 IF proof.id IS NOT NULL THEN IF proof.integration_id<>p_integration OR proof.actor<>p_actor OR proof.invoice_id<>p_invoice OR proof.amount<>p_amount OR proof.currency<>p_currency THEN RAISE EXCEPTION 'عملية الدفع مرتبطة بفاتورة أو مبلغ مختلف';END IF;IF proof.used_at IS NULL THEN UPDATE erp_settings_private.payment_proofs SET verified_at=now(),fingerprint=p_fingerprint WHERE id=proof.id;END IF;RETURN proof.id;END IF;
 INSERT INTO erp_settings_private.payment_proofs(cafe_id,integration_id,provider,provider_id,invoice_id,amount,currency,fingerprint,actor) VALUES(p_cafe,p_integration,i.provider,p_provider_id,p_invoice,p_amount,p_currency,p_fingerprint,p_actor) RETURNING id INTO proof.id;RETURN proof.id;
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_product_configuration(p_cafe uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE d public.erp_system_product_defaults;t1 numeric;t2 numeric;BEGIN
 IF auth.uid() IS NULL OR brand_finance_private.role_for(p_cafe) IS NULL THEN RAISE EXCEPTION 'لا تملك صلاحية هذه العلامة' USING ERRCODE='42501';END IF;
 SELECT * INTO d FROM public.erp_system_product_defaults WHERE cafe_id=p_cafe;
 SELECT rate INTO t1 FROM public.erp_system_taxes WHERE cafe_id=p_cafe AND id=d.tax1_id AND active;SELECT rate INTO t2 FROM public.erp_system_taxes WHERE cafe_id=p_cafe AND id=d.tax2_id AND active;
 RETURN jsonb_build_object('revision',coalesce(d.revision,0),'tax1Id',d.tax1_id,'tax2Id',d.tax2_id,'tax1',CASE WHEN d.cafe_id IS NULL THEN 15 ELSE coalesce(t1,0) END,'tax2',coalesce(t2,0),'soldItemType',coalesce(d.sold_item_type,'product'),'taxes',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'rate',rate,'active',active,'revision',revision) ORDER BY name) FROM public.erp_system_taxes WHERE cafe_id=p_cafe),'[]'));
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_product_configuration_save(p_cafe uuid, p_action text, p_input jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE id uuid:=(p_input->>'id')::uuid;rev integer:=(p_input->>'revision')::integer;d public.erp_system_product_defaults;t public.erp_system_taxes;t1 uuid:=(p_input->>'tax1Id')::uuid;t2 uuid:=(p_input->>'tax2Id')::uuid;total numeric;result jsonb;prior erp_settings_private.requests;BEGIN
 PERFORM erp_settings_private.authorize(p_cafe);IF p_request IS NULL OR rev IS NULL OR p_action NOT IN('tax','defaults') THEN RAISE EXCEPTION 'راجع إعدادات الضرائب';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text||':system-settings',0));SELECT * INTO prior FROM erp_settings_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;
 IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>'products_'||p_action OR prior.fingerprint<>md5(p_input::text) THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN prior.result;END IF;
 IF p_action='tax' THEN
  SELECT * INTO t FROM public.erp_system_taxes WHERE cafe_id=p_cafe AND erp_system_taxes.id=(p_input->>'id')::uuid FOR UPDATE;
  IF coalesce(t.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'تغيرت الضريبة أعد تحميلها' USING ERRCODE='40001';END IF;
  IF id IS NULL OR length(trim(coalesce(p_input->>'name',''))) NOT BETWEEN 1 AND 100 OR coalesce(p_input->>'rate','') NOT IN('0','15') OR jsonb_typeof(p_input->'active') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع اسم الضريبة ونسبتها';END IF;
  IF t.id IS NOT NULL AND(t.rate<>(p_input->>'rate')::numeric OR NOT(p_input->>'active')::boolean) AND EXISTS(SELECT 1 FROM public.erp_system_product_defaults WHERE cafe_id=p_cafe AND(tax1_id=t.id OR tax2_id=t.id)) THEN RAISE EXCEPTION 'غيّر الضريبة الافتراضية أولًا قبل تعديل نسبة ضريبة مستخدمة أو إيقافها';END IF;
  INSERT INTO public.erp_system_taxes(id,cafe_id,name,rate,active) VALUES(id,p_cafe,trim(p_input->>'name'),(p_input->>'rate')::numeric,(p_input->>'active')::boolean) ON CONFLICT ON CONSTRAINT erp_system_taxes_pkey DO UPDATE SET name=excluded.name,rate=excluded.rate,active=excluded.active,revision=erp_system_taxes.revision+1 WHERE erp_system_taxes.cafe_id=p_cafe;
 ELSE
  SELECT * INTO d FROM public.erp_system_product_defaults WHERE cafe_id=p_cafe FOR UPDATE;IF coalesce(d.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'تغيرت افتراضيات المنتجات أعد تحميلها' USING ERRCODE='40001';END IF;
  IF coalesce(p_input->>'soldItemType','') NOT IN('product','service','work') OR t1 IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_system_taxes WHERE cafe_id=p_cafe AND erp_system_taxes.id=t1 AND active) OR t2 IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.erp_system_taxes WHERE cafe_id=p_cafe AND erp_system_taxes.id=t2 AND active) THEN RAISE EXCEPTION 'اختر ضرائب نشطة ونوع بند صالحًا';END IF;
  SELECT coalesce((SELECT rate FROM public.erp_system_taxes WHERE cafe_id=p_cafe AND erp_system_taxes.id=t1),0)+coalesce((SELECT rate FROM public.erp_system_taxes WHERE cafe_id=p_cafe AND erp_system_taxes.id=t2),0) INTO total;
  IF total NOT IN(0,15) THEN RAISE EXCEPTION 'مجموع الضريبتين يجب أن يطابق نسب الفاتورة المدعومة صفر أو 15 بالمئة';END IF;
  INSERT INTO public.erp_system_product_defaults(cafe_id,tax1_id,tax2_id,sold_item_type) VALUES(p_cafe,t1,t2,p_input->>'soldItemType') ON CONFLICT ON CONSTRAINT erp_system_product_defaults_pkey DO UPDATE SET tax1_id=excluded.tax1_id,tax2_id=excluded.tax2_id,sold_item_type=excluded.sold_item_type,revision=erp_system_product_defaults.revision+1;
 END IF;
 result:=public.erp_system_product_configuration(p_cafe);INSERT INTO erp_settings_private.requests VALUES(p_cafe,p_request,auth.uid(),'products_'||p_action,md5(p_input::text),result);INSERT INTO public.erp_system_events(cafe_id,actor,action,target) VALUES(p_cafe,auth.uid(),'products_'||p_action,coalesce(id::text,'defaults'));RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.erp_system_settings_write(p_cafe uuid, p_action text, p_data jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
<<system_write>>
DECLARE rev integer:=(p_data->>'revision')::integer;id uuid:=(p_data->>'id')::uuid;current_revision integer;result jsonb;prior erp_settings_private.requests;v jsonb;key text;cfg jsonb;integration public.erp_system_integrations;k public.erp_system_api_keys;target text:=p_action;
BEGIN
 PERFORM erp_settings_private.authorize(p_cafe);
 IF p_request IS NULL OR rev IS NULL OR rev<0 OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR octet_length(p_data::text)>524288 OR p_action NOT IN('general','brand','apps','integration','integration_toggle','integration_delete','key','key_revoke') THEN RAISE EXCEPTION 'بيانات الإعدادات غير صالحة';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text||':system-settings',0));
 SELECT * INTO prior FROM erp_settings_private.requests WHERE cafe_id=p_cafe AND request_id=p_request;
 IF FOUND THEN IF prior.actor<>auth.uid() OR prior.action<>p_action OR prior.fingerprint<>md5(p_data::text) THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات مختلفة';END IF;RETURN prior.result;END IF;
 IF p_action IN('general','brand','apps') THEN
  SELECT revision INTO current_revision FROM public.erp_system_settings WHERE cafe_id=p_cafe AND kind=p_action FOR UPDATE;
  IF coalesce(current_revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'تغيرت الإعدادات أعد تحميلها' USING ERRCODE='40001';END IF;
  cfg:=p_data-'revision';
  IF p_action='general' THEN
   IF length(btrim(coalesce(cfg->>'businessName',''))) NOT BETWEEN 1 AND 160 OR coalesce(cfg->>'country','')<>'SA' OR coalesce(cfg->>'currency','')<>'SAR' OR coalesce(cfg->>'language','')<>'ar' OR coalesce(cfg->>'negativeFormat','') NOT IN('minus','parentheses') OR coalesce(cfg->>'dateFormat','') NOT IN('dd/MM/yyyy','MM/dd/yyyy','yyyy-MM-dd') OR coalesce(cfg->>'timezone','') NOT IN('Asia/Riyadh','Asia/Dubai','Asia/Kuwait','Asia/Qatar','Africa/Cairo','UTC') OR coalesce(cfg->>'documentView','') NOT IN('browser','pdf') OR (cfg->>'weekStart')::integer NOT BETWEEN 0 AND 6 OR cfg->>'weekStart' IS NULL THEN RAISE EXCEPTION 'راجع بيانات النشاط وتهيئة النظام';END IF;
   IF EXISTS(SELECT 1 FROM jsonb_each(cfg) e WHERE e.key NOT IN('businessName','phone','mobile','building','street','secondary','district','city','postal','shortAddress','country','taxNumber','identifierType','identifier','currency','negativeFormat','language','weekStart','dateFormat','timezone','documentView','firstName','lastName','defaultPriceListId') OR length(e.value::text)>400) THEN RAISE EXCEPTION 'حقل إعدادات غير صالح';END IF;
   IF cfg->>'defaultPriceListId' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(brand_finance_private.invoice_settings(p_cafe)#>'{advanced,priceLists}') x WHERE x->>'id'=cfg->>'defaultPriceListId' AND (x->>'active')::boolean) THEN RAISE EXCEPTION 'قائمة الأسعار غير متاحة';END IF;
   PERFORM public.save_owner_cafe_settings(p_cafe,jsonb_build_object('cafe_name',cfg->>'businessName','owner_name',btrim(coalesce(cfg->>'firstName','')||' '||coalesce(cfg->>'lastName','')),'owner_phone',cfg->>'mobile','tax_number',cfg->>'taxNumber','commercial_register',cfg->>'identifier'));
  ELSIF p_action='brand' THEN
   FOREACH key IN ARRAY ARRAY['primary','ink','background'] LOOP IF coalesce(cfg->>key,'')!~'^#[0-9a-fA-F]{6}$' THEN RAISE EXCEPTION 'اختر ألوانًا صالحة';END IF;END LOOP;
   IF length(coalesce(cfg->>'logo',''))>150000 OR coalesce(cfg->>'logo','')<>'' AND cfg->>'logo'!~'^data:image/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$' OR EXISTS(SELECT 1 FROM jsonb_object_keys(cfg) property(field_name) WHERE property.field_name NOT IN('primary','ink','background','logo')) THEN RAISE EXCEPTION 'الشعار غير صالح';END IF;
  ELSE
   IF EXISTS(SELECT 1 FROM jsonb_each(cfg) e WHERE NOT e.key=ANY(erp_access_private.domains()) OR e.key IN('store','templates') OR jsonb_typeof(e.value)<>'boolean') THEN RAISE EXCEPTION 'اختر تطبيقًا متاحًا في النظام';END IF;
  END IF;
  INSERT INTO public.erp_system_settings(cafe_id,kind,payload) VALUES(p_cafe,p_action,cfg) ON CONFLICT(cafe_id,kind) DO UPDATE SET payload=excluded.payload,revision=erp_system_settings.revision+1,updated_at=now();
 ELSIF p_action LIKE 'integration%' THEN
  IF id IS NULL THEN RAISE EXCEPTION 'معرف الاتصال مطلوب';END IF;target:=id::text;
  SELECT * INTO integration FROM public.erp_system_integrations WHERE cafe_id=p_cafe AND erp_system_integrations.id=system_write.id FOR UPDATE;
  IF coalesce(integration.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'تغير الاتصال أعد تحميله' USING ERRCODE='40001';END IF;
  IF p_action='integration_delete' THEN DELETE FROM public.erp_system_integrations WHERE cafe_id=p_cafe AND erp_system_integrations.id=system_write.id;
  ELSIF p_action='integration_toggle' THEN
   IF integration.id IS NULL OR jsonb_typeof(p_data->'enabled') IS DISTINCT FROM 'boolean' OR (p_data->>'enabled')::boolean AND (integration.verification<>'verified' OR integration.verified_at<now()-interval '30 days') THEN RAISE EXCEPTION 'تحقق من الاتصال قبل تفعيله';END IF;
   UPDATE public.erp_system_integrations SET enabled=(p_data->>'enabled')::boolean,revision=revision+1 WHERE cafe_id=p_cafe AND erp_system_integrations.id=system_write.id;
  ELSE
   cfg:=p_data->'config';
   IF coalesce(p_data->>'channel','') NOT IN('smtp','sms','payment') OR length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 100 OR jsonb_typeof(cfg) IS DISTINCT FROM 'object' OR jsonb_typeof(p_data->'secretFields') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'secretFields')>10 OR length(coalesce(p_data->>'ciphertext','')) NOT BETWEEN 10 AND 64000 OR p_data->>'ciphertext'!~'^v1[.]' THEN RAISE EXCEPTION 'راجع الاتصال وبياناته المحمية';END IF;
   IF EXISTS(SELECT 1 FROM jsonb_each(cfg) e WHERE e.key NOT IN('fromName','fromEmail','host','port','secure','username','accountSid','authId','from','sender_name','phone_number_id','whatsapp_business_account_id','message_template','message_template_locale','sandbox_to_number','sandbox','accountId','publicKey','clientId','genericVerifyUrl','genericVerifyMethod','genericVerifyBody','genericSendUrl','genericFormat','genericBody','genericVerifyPath','genericVerifyValue','genericSuccessPath','genericSuccessValue','genericIdPath','genericAuthHeader','genericAuthSecret','genericAuthPrefix') OR length(e.value::text)>2100) THEN RAISE EXCEPTION 'حقل اتصال غير صالح أو غير محمي';END IF;
   IF cfg ? 'genericSendUrl' AND (NOT erp_settings_private.safe_provider_template((cfg->>'genericBody')::jsonb) OR cfg->>'genericVerifyMethod'='POST' AND NOT erp_settings_private.safe_provider_template((cfg->>'genericVerifyBody')::jsonb)) THEN RAISE EXCEPTION 'استخدم متغيرات الأسرار المحمية داخل قالب المزود';END IF;
   IF p_data->>'channel'='smtp' AND (p_data->>'provider'<>'smtp' OR cfg->>'host'!~'^[a-zA-Z0-9.-]{3,253}$' OR (cfg->>'port')::integer NOT IN(465,587) OR jsonb_typeof(cfg->'secure') IS DISTINCT FROM 'boolean' OR cfg->>'fromEmail'!~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$') THEN RAISE EXCEPTION 'راجع إعدادات خادم البريد';END IF;
   IF p_data->>'channel'='sms' AND p_data->>'provider' NOT IN('twilio','plivo','jawaly','taqnyat','msegat','alghaddm','hawa','hisms','mobilenet','mobilyws','malath','jawalb','morasa','whatsapp') OR p_data->>'channel'='payment' AND p_data->>'provider' NOT IN('stripe','moyasar','tap','paypal','manual') THEN RAISE EXCEPTION 'مزود الاتصال غير صالح';END IF;
   IF cfg->>'accountId' IS NOT NULL AND cfg->>'accountId'<>'' AND NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=p_cafe AND bf_accounts.id=(cfg->>'accountId')::uuid AND kind IN('cash','bank','pos') AND active AND NOT coalesce(frozen,false) AND deleted_at IS NULL) THEN RAISE EXCEPTION 'حساب التحصيل غير متاح';END IF;
   INSERT INTO public.erp_system_integrations(id,cafe_id,channel,provider,name,config,secret_fields) VALUES(id,p_cafe,p_data->>'channel',p_data->>'provider',p_data->>'name',cfg,p_data->'secretFields') ON CONFLICT ON CONSTRAINT erp_system_integrations_cafe_id_id_key DO UPDATE SET channel=excluded.channel,provider=excluded.provider,name=excluded.name,config=excluded.config,secret_fields=excluded.secret_fields,enabled=false,verified_at=NULL,verification='unverified',verification_message='',revision=erp_system_integrations.revision+1;
   INSERT INTO erp_settings_private.secrets VALUES(p_cafe,id,p_data->>'ciphertext') ON CONFLICT ON CONSTRAINT secrets_pkey DO UPDATE SET ciphertext=excluded.ciphertext;
  END IF;
 ELSIF p_action='key' THEN
  IF id IS NULL THEN RAISE EXCEPTION 'معرف المفتاح مطلوب';END IF;target:=id::text;SELECT * INTO k FROM public.erp_system_api_keys WHERE cafe_id=p_cafe AND erp_system_api_keys.id=system_write.id FOR UPDATE;
  IF coalesce(k.revision,0) IS DISTINCT FROM rev THEN RAISE EXCEPTION 'تغير المفتاح أعد تحميله' USING ERRCODE='40001';END IF;
  IF length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 100 OR coalesce(p_data->>'purpose','') NOT IN('api','copilot') OR jsonb_typeof(p_data->'scopes') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'scopes') NOT BETWEEN 1 AND 5 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_data->'scopes') s WHERE s NOT IN('customers:read','invoices:read','inventory:read','requests:read','requests:write')) OR (coalesce(k.purpose,p_data->>'purpose')='copilot' AND (p_data->'scopes') ? 'requests:write') OR (k.id IS NOT NULL AND k.purpose IS DISTINCT FROM p_data->>'purpose') OR (p_data->>'expiresAt')::timestamptz<=now() THEN RAISE EXCEPTION 'راجع صلاحيات المفتاح وتاريخ انتهائه';END IF;
  IF rev=0 THEN
   IF coalesce(p_data->>'hash','')!~'^[a-f0-9]{64}$' OR coalesce(p_data->>'prefix','')!~'^branda_[A-Za-z0-9_-]{6,16}$' THEN RAISE EXCEPTION 'بصمة المفتاح غير صالحة';END IF;
   INSERT INTO public.erp_system_api_keys(id,cafe_id,created_by,name,prefix,scopes,purpose,expires_at) VALUES(id,p_cafe,auth.uid(),p_data->>'name',p_data->>'prefix',p_data->'scopes',p_data->>'purpose',(p_data->>'expiresAt')::timestamptz);
   INSERT INTO erp_settings_private.api_hashes(id,token_hash) VALUES(id,p_data->>'hash');
  ELSE UPDATE public.erp_system_api_keys SET name=p_data->>'name',scopes=p_data->'scopes',expires_at=(p_data->>'expiresAt')::timestamptz,revision=revision+1 WHERE cafe_id=p_cafe AND erp_system_api_keys.id=system_write.id;END IF;
 ELSIF p_action='key_revoke' THEN
  UPDATE public.erp_system_api_keys SET active=false,revision=revision+1 WHERE cafe_id=p_cafe AND erp_system_api_keys.id=system_write.id AND revision=rev;
  IF NOT FOUND THEN RAISE EXCEPTION 'تغير المفتاح أعد تحميله' USING ERRCODE='40001';END IF;target:=id::text;
 END IF;
 result:=jsonb_build_object('id',id,'revision',rev+1);
 INSERT INTO public.erp_system_events(cafe_id,actor,action,target) VALUES(p_cafe,auth.uid(),p_action,target);
 INSERT INTO erp_settings_private.requests VALUES(p_cafe,p_request,auth.uid(),p_action,md5(p_data::text),result);RETURN result;
END $function$

