CREATE OR REPLACE FUNCTION public.erp_treasury_correct(p_cafe_id uuid, p_user_id uuid, p_scope jsonb, p_actor_id uuid, p_maintenance_expires_at timestamp with time zone, p_operation text, p_payload jsonb, p_request_id uuid)
