CREATE OR REPLACE FUNCTION brand_finance_private.contracting_invoice_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE cert public.erp_contracting_documents%ROWTYPE;actual public.bf_documents%ROWTYPE;expected jsonb;received jsonb;applied numeric;remaining numeric;payment_id uuid;
BEGIN
 SELECT * INTO cert FROM public.erp_contracting_documents WHERE cafe_id=NEW.cafe_id AND invoice_draft_id=NEW.draft_id FOR UPDATE;
 IF NOT FOUND THEN
  IF EXISTS(SELECT 1 FROM public.erp_contracting_invoice_drafts l JOIN public.erp_contracting_documents p ON p.cafe_id=l.cafe_id AND p.id=l.project_id JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=NEW.document_id WHERE l.cafe_id=NEW.cafe_id AND l.draft_id=NEW.draft_id AND p.customer_id IS DISTINCT FROM d.party_id) THEN RAISE EXCEPTION 'عميل الفاتورة لا يطابق عميل المشروع' USING ERRCODE='22023';END IF;
  INSERT INTO public.erp_contracting_links(cafe_id,project_id,document_id,relation) SELECT cafe_id,project_id,NEW.document_id,CASE WHEN kind='advance' THEN 'advance_invoice' ELSE 'project_invoice' END FROM public.erp_contracting_invoice_drafts WHERE cafe_id=NEW.cafe_id AND draft_id=NEW.draft_id ON CONFLICT DO NOTHING;
  RETURN NEW;
 END IF;
 IF cert.invoice_id IS NOT NULL AND cert.invoice_id<>NEW.document_id THEN RAISE EXCEPTION 'تمت فوترة المستخلص بالفعل' USING ERRCODE='22023';END IF;
 SELECT * INTO actual FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.document_id;
 IF cert.kind<>'certificate' OR cert.status<>'approved' OR actual.party_id IS DISTINCT FROM cert.customer_id OR actual.total<>cert.total OR actual.tax<>cert.tax OR actual.subtotal<>cert.subtotal OR actual.discount<>0 OR (NEW.snapshot->>'currency') IS DISTINCT FROM 'SAR' THEN RAISE EXCEPTION 'يجب أن تطابق فاتورة المستخلص البنود والعميل والقيم المعتمدة' USING ERRCODE='22023';END IF;
 SELECT jsonb_agg(jsonb_build_array(name,quantity,round(unit_price,2),round(quantity*unit_price,2),round(round(quantity*unit_price,2)*tax_rate/100,2)) ORDER BY name,quantity,unit_price) INTO expected FROM public.erp_contracting_lines WHERE cafe_id=cert.cafe_id AND document_id=cert.id AND kind='work' AND quantity>0;
 SELECT jsonb_agg(jsonb_build_array(name,quantity,unit_price,net,tax) ORDER BY name,quantity,unit_price) INTO received FROM public.bf_document_lines WHERE cafe_id=NEW.cafe_id AND document_id=NEW.document_id;
 IF expected IS DISTINCT FROM received THEN RAISE EXCEPTION 'بنود الفاتورة لا تطابق المستخلص المعتمد' USING ERRCODE='22023';END IF;
 applied:=coalesce((NEW.snapshot->>'creditApplied')::numeric,0);remaining:=cert.recovery-applied;
 IF remaining<0 OR coalesce((NEW.snapshot->>'paid')::numeric,0)+remaining>cert.total-cert.retention THEN RAISE EXCEPTION 'الدفعة تتجاوز صافي المستخلص أو مقدار الاسترداد المعتمد' USING ERRCODE='22023';END IF;
 IF remaining>0 THEN
  payment_id:=erp_settings_private.apply_advance_recovery(cert.cafe_id,NEW.document_id,remaining,cert.id);
  NEW.snapshot:=NEW.snapshot||jsonb_build_object('paid',coalesce((NEW.snapshot->>'paid')::numeric,0)+remaining,'creditApplied',cert.recovery,'sar',coalesce(NEW.snapshot->'sar','{}')||jsonb_build_object('paid',coalesce((NEW.snapshot#>>'{sar,paid}')::numeric,0)+remaining,'creditApplied',cert.recovery));
  IF cert.project_id IS NOT NULL THEN INSERT INTO public.erp_contracting_links(cafe_id,project_id,document_id,relation) VALUES(cert.cafe_id,cert.project_id,payment_id,'advance_recovery') ON CONFLICT DO NOTHING;END IF;
 END IF;
 NEW.snapshot:=NEW.snapshot||jsonb_build_object('advanceApplications',coalesce((SELECT jsonb_agg(jsonb_build_object('invoiceId',a.invoice_id,'number',e.display_number,'issuedAt',a.created_at,'invoiceTypeCode','386','amount',x.amount,'net',x.net,'tax',x.tax)) FROM public.erp_contracting_advance_allocations x JOIN public.erp_contracting_advance_invoices a ON a.cafe_id=x.cafe_id AND a.invoice_id=x.advance_id LEFT JOIN public.bf_invoice_extensions e ON e.cafe_id=a.cafe_id AND e.document_id=a.invoice_id WHERE x.cafe_id=NEW.cafe_id AND x.invoice_id=NEW.document_id),'[]'::jsonb),'advanceTaxAdjusted',coalesce((SELECT sum(tax) FROM public.erp_contracting_advance_allocations WHERE cafe_id=NEW.cafe_id AND invoice_id=NEW.document_id),0)); UPDATE public.erp_contracting_documents SET invoice_id=NEW.document_id,revision=revision+1,updated_at=clock_timestamp() WHERE cafe_id=cert.cafe_id AND id=cert.id;
 IF cert.project_id IS NOT NULL THEN INSERT INTO public.erp_contracting_links(cafe_id,project_id,document_id,relation) VALUES(cert.cafe_id,cert.project_id,NEW.document_id,'certificate_invoice') ON CONFLICT DO NOTHING;END IF;
 INSERT INTO public.erp_contracting_events(cafe_id,document_id,action,note,actor) VALUES(cert.cafe_id,cert.id,'invoice_issued',actual.number::text,auth.uid());
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_insurance_private.invoice_issued()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE binding public.erp_insurance_invoices;payload jsonb;entry jsonb;rule jsonb;rule_id text;totals jsonb:='{}';groups jsonb:='[]';amount numeric;company numeric;customer numeric;company_total numeric:=0;customer_total numeric:=0;max_amount numeric;category_names text;idx integer:=0;
BEGIN
 SELECT * INTO binding FROM public.erp_insurance_invoices WHERE cafe_id=NEW.cafe_id AND draft_id=NEW.draft_id FOR UPDATE;IF NOT FOUND THEN RETURN NEW;END IF;
 SELECT d.payload INTO payload FROM public.bf_invoice_drafts d WHERE d.cafe_id=NEW.cafe_id AND d.id=NEW.draft_id;
 IF binding.pricing_hash<>erp_insurance_private.pricing_hash(payload) OR NOT EXISTS(SELECT 1 FROM public.erp_insurance_enrollments e WHERE e.cafe_id=NEW.cafe_id AND e.customer_id=binding.customer_id AND e.revision=binding.enrollment_revision AND e.class_id=binding.class_id) THEN RAISE EXCEPTION 'تغيرت بنود الفاتورة أو فئة العميل أعد حساب التأمين قبل الإصدار' USING ERRCODE='22023';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.erp_insurance_companies WHERE cafe_id=NEW.cafe_id AND id=binding.company_id AND active) THEN RAISE EXCEPTION 'شركة التأمين غير نشطة';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.erp_insurance_classes WHERE cafe_id=NEW.cafe_id AND id=binding.class_id AND active AND rules=binding.rules_snapshot) THEN RAISE EXCEPTION 'تغيرت قواعد الفئة أعد حساب التأمين قبل الإصدار';END IF;
 IF jsonb_array_length(binding.line_rules)<>jsonb_array_length(NEW.snapshot->'lines') THEN RAISE EXCEPTION 'عدد بنود التغطية لا يطابق الفاتورة';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(NEW.snapshot->'lines') LOOP
  rule_id:=coalesce(binding.line_rules->idx->>'ruleId','uncovered');idx:=idx+1;amount:=(entry->>'total')::numeric;
  IF amount IS NULL OR amount<0 THEN RAISE EXCEPTION 'قيمة بند التأمين غير صالحة';END IF;
  totals:=jsonb_set(totals,ARRAY[rule_id],to_jsonb(coalesce((totals->>rule_id)::numeric,0)+amount));
 END LOOP;
 FOR rule_id,amount IN SELECT key,value::numeric FROM jsonb_each_text(totals) LOOP
  SELECT value INTO rule FROM jsonb_array_elements(binding.rules_snapshot) WHERE value->>'id'=rule_id;
  company:=round(amount*coalesce((rule->>'companyShare')::numeric,0)/100,2);customer:=amount-company;max_amount:=nullif(rule->>'maxCopayment','')::numeric;
  IF max_amount IS NOT NULL THEN IF rule->>'capFor'='company' THEN company:=least(company,max_amount);customer:=amount-company;ELSE customer:=least(customer,max_amount);company:=amount-customer;END IF;END IF;
  SELECT string_agg(name,' / ' ORDER BY name) INTO category_names FROM erp_insurance_private.categories(NEW.cafe_id) WHERE id::text IN(SELECT jsonb_array_elements_text(coalesce(rule->'categories','[]')));
  groups:=groups||jsonb_build_array(jsonb_build_object('ruleId',nullif(rule_id,'uncovered'),'label',CASE WHEN rule_id='uncovered' THEN 'غير مشمول' ELSE coalesce(category_names,'كل التصنيفات') END,'total',amount,'company',company,'customer',customer,'discount',coalesce(rule->'discount','0'::jsonb),'maxCopayment',max_amount,'capFor',coalesce(rule->>'capFor','customer')));company_total:=company_total+company;customer_total:=customer_total+customer;
 END LOOP;
 IF company_total+customer_total<>(NEW.snapshot->>'total')::numeric THEN RAISE EXCEPTION 'مجموع حصص التأمين لا يطابق إجمالي الفاتورة';END IF;
 UPDATE public.erp_insurance_invoices SET invoice_id=NEW.document_id,coverage=jsonb_build_object('total',company_total+customer_total,'company',company_total,'customer',customer_total,'groups',groups),revision=revision+1 WHERE cafe_id=NEW.cafe_id AND id=binding.id;
 INSERT INTO public.erp_insurance_events(cafe_id,record_id,action,actor) VALUES(NEW.cafe_id,binding.id,'invoice_issued',auth.uid());RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_rental_private.invoice_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE customer uuid;expected numeric;tax numeric;contract_status text;actual public.bf_documents;sales_account uuid;default_account uuid;net numeric;
BEGIN
 SELECT customer_id,total,status INTO customer,expected,contract_status FROM public.erp_rental_reservations WHERE cafe_id=NEW.cafe_id AND draft_id=NEW.draft_id;
 IF NOT FOUND THEN SELECT c.customer_id,i.amount+round(i.amount*(c.payload->>'taxRate')::numeric/100,2),c.status,(c.payload->>'salesAccountId')::uuid INTO customer,expected,contract_status,sales_account FROM public.erp_rental_installments i JOIN public.erp_rental_contracts c ON c.cafe_id=i.cafe_id AND c.id=i.contract_id WHERE i.cafe_id=NEW.cafe_id AND i.draft_id=NEW.draft_id;END IF;
 IF customer IS NULL THEN RETURN NEW;END IF;
 SELECT * INTO actual FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.document_id;
 IF actual.party_id IS DISTINCT FROM customer OR actual.total IS DISTINCT FROM expected OR actual.kind IS DISTINCT FROM 'sale' OR contract_status='cancelled' OR (NEW.snapshot->>'currency') IS DISTINCT FROM 'SAR' THEN RAISE EXCEPTION 'عميل الفاتورة وإجماليها وعملتها يجب أن تطابق الحجز أو قسط العقد' USING ERRCODE='22023';END IF;
 IF sales_account IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=NEW.cafe_id AND id=sales_account AND kind='revenue' AND active AND NOT frozen AND NOT is_group AND deleted_at IS NULL) THEN RAISE EXCEPTION 'حساب إيرادات العقد غير متاح' USING ERRCODE='22023';END IF;
  default_account:=brand_finance_private.account(NEW.cafe_id,'4000');
  IF sales_account<>default_account THEN
   SELECT coalesce(sum(credit-debit),0) INTO net FROM public.bf_journal WHERE cafe_id=NEW.cafe_id AND document_id=NEW.document_id AND account_id=default_account;
   IF net>0 THEN PERFORM brand_finance_private.line(NEW.cafe_id,NEW.document_id,default_account,net,0);PERFORM brand_finance_private.line(NEW.cafe_id,NEW.document_id,sales_account,0,net);END IF;
   INSERT INTO public.erp_rental_invoice_accounts VALUES(NEW.cafe_id,NEW.document_id,sales_account);
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.template_source_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE row_data jsonb:=to_jsonb(NEW);c uuid;target uuid;entity_name text;payment_doc jsonb;
BEGIN
 c:=(row_data->>'cafe_id')::uuid;target:=coalesce(nullif(row_data->>'document_id',''),nullif(row_data->>'id',''))::uuid;
 entity_name:=CASE TG_TABLE_NAME WHEN 'bf_company_invoices' THEN CASE WHEN row_data#>>'{snapshot,documentType}'='debit' THEN 'debit' ELSE 'invoice' END WHEN 'erp_bookings' THEN 'appointment' WHEN 'erp_booking_lines' THEN 'appointment' WHEN 'bf_quotes' THEN 'quotation' WHEN 'bf_credit_notes' THEN 'credit_note' WHEN 'erp_work_orders' THEN 'work_order' WHEN 'bf_documents' THEN CASE WHEN row_data->>'kind'='refund' THEN 'refund' WHEN row_data->>'kind'='settlement' THEN 'invoice' END END;
 IF TG_TABLE_NAME='erp_booking_lines' THEN target:=(row_data->>'booking_id')::uuid;END IF;
 IF TG_TABLE_NAME='bf_invoice_payments' THEN
  SELECT to_jsonb(d) INTO payment_doc FROM public.bf_documents d WHERE d.cafe_id=c AND d.id=(row_data->>'source_id')::uuid;
