CREATE OR REPLACE FUNCTION brand_finance_private.credit_refund_line_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE source uuid;credited numeric;refunded numeric;sold numeric;
BEGIN
 SELECT reference_id INTO source FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.document_id AND kind='refund';
 IF source IS NOT NULL AND NEW.product_id IS NOT NULL THEN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));
  SELECT coalesce(sum((line->>'quantity')::numeric),0) INTO credited FROM public.bf_credit_notes n CROSS JOIN LATERAL jsonb_array_elements(n.lines) line WHERE n.cafe_id=NEW.cafe_id AND n.source_invoice_id=source AND n.status='issued' AND (n.payload->>'stockRequired')::boolean AND line->>'productId'=NEW.product_id::text;
  IF credited>0 THEN
   SELECT coalesce(sum(quantity),0) INTO sold FROM public.bf_document_lines WHERE cafe_id=NEW.cafe_id AND document_id=source AND product_id=NEW.product_id;
   SELECT coalesce(sum(l.quantity),0) INTO refunded FROM public.bf_document_lines l JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=l.document_id WHERE d.cafe_id=NEW.cafe_id AND d.reference_id=source AND d.kind='refund' AND l.product_id=NEW.product_id;
   IF credited+refunded+NEW.quantity>sold THEN RAISE EXCEPTION 'سبق استلام كمية الصنف بإشعار دائن';END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION gift_commerce_private.refund_catalog_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l public.gift_order_lines%ROWTYPE;details jsonb;stock integer;options jsonb;
BEGIN
 IF NEW.reference_line_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.bf_documents WHERE id=NEW.document_id AND cafe_id=NEW.cafe_id AND kind='refund') THEN RETURN NEW;END IF;
 SELECT * INTO l FROM public.gift_order_lines WHERE cafe_id=NEW.cafe_id AND finance_line_id=NEW.reference_line_id AND stock_tracked;
 IF NOT FOUND THEN RETURN NEW;END IF;
 IF NEW.quantity<>trunc(NEW.quantity) THEN RAISE EXCEPTION 'كمية إرجاع هذا المنتج يجب أن تكون عددًا صحيحًا';END IF;
 SELECT commerce_details INTO details FROM public.menu_products WHERE id=l.product_id AND cafe_id=l.cafe_id FOR UPDATE;
 IF l.option_id IS NULL THEN
  stock:=(details->>'stock')::integer;
  IF stock IS NOT NULL THEN UPDATE public.menu_products SET commerce_details=jsonb_set(details,'{stock}',to_jsonb(stock+NEW.quantity::integer)),updated_at=now() WHERE id=l.product_id AND cafe_id=l.cafe_id;END IF;
 ELSE
  SELECT (x->>'stock')::integer INTO stock FROM jsonb_array_elements(details->'options') x WHERE x->>'id'=l.option_id;
  IF stock IS NOT NULL THEN
   SELECT jsonb_agg(CASE WHEN x->>'id'=l.option_id THEN jsonb_set(x,'{stock}',to_jsonb(stock+NEW.quantity::integer)) ELSE x END ORDER BY ord) INTO options FROM jsonb_array_elements(details->'options') WITH ORDINALITY a(x,ord);
   UPDATE public.menu_products SET commerce_details=jsonb_set(details,'{options}',options),updated_at=now() WHERE id=l.product_id AND cafe_id=l.cafe_id;
  END IF;
 END IF;
 RETURN NEW;
END $function$

