CREATE OR REPLACE FUNCTION erp_customer_private.credit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE cfg jsonb;p jsonb;balance numeric;BEGIN
 IF NEW.kind<>'sale' OR NEW.shift_id IS NOT NULL OR NEW.party_id IS NULL OR NEW.total<=NEW.paid THEN RETURN NEW;END IF;
 SELECT s.payload,c.payload INTO cfg,p FROM public.erp_customer_profiles c LEFT JOIN public.erp_customer_settings s ON s.cafe_id=c.cafe_id WHERE c.cafe_id=NEW.cafe_id AND c.id=NEW.party_id;IF p IS NULL THEN RETURN NEW;END IF;
 IF coalesce((cfg->>'creditLimit')::boolean,false) AND nullif(p->>'creditLimit','') IS NOT NULL THEN
  SELECT coalesce(sum(j.debit-j.credit),0) INTO balance FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=NEW.cafe_id AND j.party_id=NEW.party_id AND a.kind='receivable';
  IF balance+NEW.total-NEW.paid>(p->>'creditLimit')::numeric THEN RAISE EXCEPTION 'الفاتورة تتجاوز الحد الائتماني للعميل';END IF;
 END IF;
 IF coalesce((cfg->>'creditDays')::boolean,false) AND nullif(p->>'creditDays','') IS NOT NULL AND EXISTS(SELECT 1 FROM public.bf_documents d WHERE d.cafe_id=NEW.cafe_id AND d.party_id=NEW.party_id AND d.kind='sale' AND (d.created_at AT TIME ZONE 'Asia/Riyadh')::date+(p->>'creditDays')::integer<(now() AT TIME ZONE 'Asia/Riyadh')::date AND (brand_finance_private.document_state(NEW.cafe_id,d.id)->>'outstanding')::numeric>0) THEN RAISE EXCEPTION 'للعميل فواتير تجاوزت المدة الائتمانية';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_settings_private.assign_display_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE j jsonb:=to_jsonb(NEW);ctx text;reference public.bf_documents;draft uuid;BEGIN
 IF TG_TABLE_NAME='bf_documents' THEN
  SELECT * INTO reference FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.reference_id;
  IF NEW.kind='settlement' THEN
   ctx:=CASE reference.kind WHEN 'sale' THEN 'invoice_payment' WHEN 'purchase' THEN 'purchase_payment' WHEN 'refund' THEN CASE WHEN EXISTS(SELECT 1 FROM public.bf_documents d WHERE d.cafe_id=NEW.cafe_id AND d.id=reference.reference_id AND d.kind='purchase') THEN 'purchase_return_payment' ELSE 'refund_payment' END END;
  ELSIF NEW.kind='refund' THEN
   ctx:=CASE WHEN reference.kind='purchase' THEN CASE WHEN EXISTS(SELECT 1 FROM public.erp_purchase_debits WHERE cafe_id=NEW.cafe_id AND document_id=NEW.id) THEN 'purchase_debit' ELSE 'purchase_return' END WHEN reference.kind='sale' THEN 'sales_return' END;
  ELSIF NEW.kind='journal' THEN
   SELECT id INTO draft FROM public.bf_gl_drafts WHERE cafe_id=NEW.cafe_id AND document_id=NEW.id;
   IF draft IS NOT NULL THEN RETURN NEW;END IF;ctx:='automatic_journal';
  END IF;
 ELSE ctx:=CASE TG_TABLE_NAME WHEN 'erp_bookings' THEN 'booking' WHEN 'erp_rental_reservations' THEN 'rental_reservation' WHEN 'erp_task_templates' THEN 'task_template' WHEN 'bf_gl_drafts' THEN 'manual_journal' WHEN 'erp_finance_custody_movements' THEN CASE WHEN j->>'kind'='settlement' THEN 'custody_settlement' END END;
 END IF;
 IF ctx IS NOT NULL THEN PERFORM erp_settings_private.allocate_number((j->>'cafe_id')::uuid,ctx,(j->>'id')::uuid,coalesce((j->>'created_at')::timestamptz,now()));END IF;
 -- A paid refund is itself the actual cash movement, not a fictitious settlement child
 IF TG_TABLE_NAME='bf_documents' AND j->>'kind'='refund' AND coalesce((j->>'paid')::numeric,0)>0 AND reference.kind IN('sale','purchase') THEN PERFORM erp_settings_private.allocate_number(NEW.cafe_id,CASE reference.kind WHEN 'purchase' THEN 'purchase_return_payment' ELSE 'refund_payment' END,NEW.id,NEW.created_at);END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.template_source_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE row_data jsonb:=to_jsonb(NEW);c uuid;target uuid;entity_name text;payment_doc jsonb;
BEGIN
 c:=(row_data->>'cafe_id')::uuid;target:=coalesce(nullif(row_data->>'document_id',''),nullif(row_data->>'id',''))::uuid;
 entity_name:=CASE TG_TABLE_NAME WHEN 'bf_company_invoices' THEN CASE WHEN row_data#>>'{snapshot,documentType}'='debit' THEN 'debit' ELSE 'invoice' END WHEN 'erp_bookings' THEN 'appointment' WHEN 'erp_booking_lines' THEN 'appointment' WHEN 'bf_quotes' THEN 'quotation' WHEN 'bf_credit_notes' THEN 'credit_note' WHEN 'erp_work_orders' THEN 'work_order' WHEN 'bf_documents' THEN CASE WHEN row_data->>'kind'='refund' THEN 'refund' WHEN row_data->>'kind'='settlement' THEN 'invoice' END END;
 IF TG_TABLE_NAME='erp_booking_lines' THEN target:=(row_data->>'booking_id')::uuid;END IF;
 IF TG_TABLE_NAME='bf_invoice_payments' THEN
  SELECT to_jsonb(d) INTO payment_doc FROM public.bf_documents d WHERE d.cafe_id=c AND d.id=(row_data->>'source_id')::uuid;
  target:=CASE WHEN payment_doc->>'kind'='settlement' THEN (payment_doc->>'reference_id')::uuid ELSE (payment_doc->>'id')::uuid END;
  IF payment_doc->>'kind' IN('sale','settlement') THEN entity_name:=CASE WHEN brand_finance_private.document_state(c,target)->>'document_type'='debit' THEN 'debit' ELSE 'invoice' END;END IF;
 END IF;
 IF TG_TABLE_NAME='bf_documents' AND row_data->>'kind'='settlement' THEN target:=(row_data->>'reference_id')::uuid;END IF;
 IF entity_name IS NOT NULL AND target IS NOT NULL THEN PERFORM brand_finance_private.template_enqueue(c,entity_name,target);END IF;RETURN NEW;
EXCEPTION WHEN OTHERS THEN INSERT INTO public.erp_template_events(cafe_id,record_id,action,actor) VALUES(c,target,'enqueue_failed:'||SQLSTATE,auth.uid());RETURN NEW;
END $function$

