CREATE OR REPLACE FUNCTION erp_settings_private.assign_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE ctx erp_settings_private.number_contexts;j jsonb:=to_jsonb(NEW);v text;present boolean;BEGIN
 IF j->>'cafe_id' IS NULL OR j->>'id' IS NULL THEN RETURN NEW;END IF;
 EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id=$2)',TG_TABLE_NAME) INTO present USING (j->>'cafe_id')::uuid,(j->>'id')::uuid;IF present THEN RETURN NEW;END IF;
 FOR ctx IN SELECT * FROM erp_settings_private.number_contexts WHERE table_name=TG_TABLE_NAME AND (filter_key IS NULL OR j->>filter_key=filter_value) LOOP
  v:=erp_settings_private.allocate_number((j->>'cafe_id')::uuid,ctx.context,(j->>'id')::uuid,coalesce((j->>'created_at')::timestamptz,now()));
  IF v IS NOT NULL THEN j:=jsonb_set(j,string_to_array(ctx.column_path,'.'),to_jsonb(v));IF ctx.column_path IN('code','number') AND j->'payload' ? ctx.column_path THEN j:=jsonb_set(j,ARRAY['payload',ctx.column_path],to_jsonb(v));END IF;NEW:=jsonb_populate_record(NEW,j);END IF;
 END LOOP;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.gl_line_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.bf_accounts; d timestamptz;
BEGIN
  IF NOT brand_finance_private.gl_enabled(NEW.cafe_id) THEN RETURN NEW; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.cafe_id::text,60412));
  SELECT * INTO a FROM public.bf_accounts WHERE cafe_id=NEW.cafe_id AND id=NEW.account_id FOR SHARE;
  IF a.id IS NULL OR a.is_group OR a.frozen OR NOT a.active THEN
    RAISE EXCEPTION 'الحساب غير نشط أو مجمد أو تجميعي';
  END IF;
  SELECT created_at INTO d FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.document_id;
  PERFORM brand_finance_private.gl_date_open(NEW.cafe_id,(d AT TIME ZONE 'Asia/Riyadh')::date);
  -- One accounting date for source document and every journal line
  NEW.created_at:=d;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION brand_finance_private.terminal_sale_fee()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE d public.bf_documents%ROWTYPE;
BEGIN
 IF NEW.debit<=0 OR NOT EXISTS(SELECT 1 FROM public.bf_accounts WHERE cafe_id=NEW.cafe_id AND id=NEW.account_id AND kind='pos') THEN RETURN NEW; END IF;
 SELECT * INTO d FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.document_id;
 IF d.kind='sale' OR (d.kind='settlement' AND EXISTS(SELECT 1 FROM public.bf_documents WHERE cafe_id=d.cafe_id AND id=d.reference_id AND kind='sale')) THEN
  PERFORM brand_finance_private.terminal_monthly_ensure(NEW.cafe_id);
  PERFORM brand_finance_private.terminal_fee_accrue(NEW.cafe_id,NEW.account_id,NEW.document_id,NULL,NEW.debit);
 END IF;
 RETURN NEW;
END $function$

