CREATE OR REPLACE FUNCTION platform_access_private.guard_service_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NOT public.is_platform_admin() AND NOT platform_access_private.service_enabled(NEW.cafe_id,TG_ARGV[0])
    THEN RAISE EXCEPTION 'Service unavailable for current subscription' USING ERRCODE='42501'; END IF;
  IF TG_OP='UPDATE' AND OLD.cafe_id IS DISTINCT FROM NEW.cafe_id AND NOT public.is_platform_admin()
    THEN RAISE EXCEPTION 'Service tenant cannot change' USING ERRCODE='42501'; END IF;
  IF NOT public.is_platform_admin() AND TG_TABLE_NAME='customer_reward_instances' THEN
    IF NEW.source_type<>'loyalty' THEN RAISE EXCEPTION 'Experience rewards are archived' USING ERRCODE='42501'; END IF;
  END IF;
  IF NOT public.is_platform_admin() AND TG_TABLE_NAME='customer_reward_redemptions' THEN
    IF NOT EXISTS(SELECT 1 FROM public.customer_reward_instances r WHERE r.id=NEW.reward_instance_id
      AND r.cafe_id=NEW.cafe_id AND r.source_type='loyalty')
      THEN RAISE EXCEPTION 'Reward service unavailable' USING ERRCODE='42501'; END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.queue_rast_wallet_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_cafe_id uuid := NEW.cafe_id;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.cafes WHERE id = v_cafe_id AND platform_access_private.service_enabled(v_cafe_id,'loyalty')) THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME = 'loyalty_cards' THEN
    UPDATE public.wallet_passes SET updated_at = GREATEST(clock_timestamp(),updated_at + interval '1 microsecond') WHERE card_id = NEW.id AND cafe_id = v_cafe_id;
    INSERT INTO public.wallet_notification_jobs(cafe_id,card_id,kind)
      SELECT v_cafe_id,NEW.id,'sync' WHERE EXISTS(SELECT 1 FROM public.wallet_passes WHERE card_id = NEW.id)
      ON CONFLICT DO NOTHING;
  ELSE
    UPDATE public.wallet_passes SET updated_at = GREATEST(clock_timestamp(),updated_at + interval '1 microsecond') WHERE cafe_id = v_cafe_id;
    INSERT INTO public.wallet_notification_jobs(cafe_id,card_id,kind)
      SELECT DISTINCT v_cafe_id,card_id,'sync' FROM public.wallet_passes WHERE cafe_id = v_cafe_id
      ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$function$

