CREATE OR REPLACE FUNCTION erp_employee_asset_private.sync_unit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE aid uuid;BEGIN
 IF NEW.financial_unit_id IS NULL OR NEW.status='retired' THEN RETURN NEW;END IF;
