 kind:=CASE TG_TABLE_NAME WHEN 'bf_parties' THEN row->>'kind' WHEN 'bf_items' THEN 'item' WHEN 'bf_accounts' THEN 'account' WHEN 'erp_cost_centers' THEN 'cost_center' WHEN 'erp_inventory_catalogs' THEN CASE WHEN row->>'kind'='unit_template' THEN 'unit_template' ELSE '' END ELSE '' END;
 IF NOT erp_branch_private.row_allowed(c,b,row,kind) THEN RAISE EXCEPTION 'لا يمكن تعديل سجل خارج الفرع المختار' USING ERRCODE='42501';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE PERFORM erp_branch_private.assert_input(c,to_jsonb(NEW));RETURN NEW;END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_settings_private.assign_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE ctx erp_settings_private.number_contexts;j jsonb:=to_jsonb(NEW);v text;present boolean;BEGIN
 IF j->>'cafe_id' IS NULL OR j->>'id' IS NULL THEN RETURN NEW;END IF;
 EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE cafe_id=$1 AND id=$2)',TG_TABLE_NAME) INTO present USING (j->>'cafe_id')::uuid,(j->>'id')::uuid;IF present THEN RETURN NEW;END IF;
 FOR ctx IN SELECT * FROM erp_settings_private.number_contexts WHERE table_name=TG_TABLE_NAME AND (filter_key IS NULL OR j->>filter_key=filter_value) LOOP
  v:=erp_settings_private.allocate_number((j->>'cafe_id')::uuid,ctx.context,(j->>'id')::uuid,coalesce((j->>'created_at')::timestamptz,now()));
  IF v IS NOT NULL THEN j:=jsonb_set(j,string_to_array(ctx.column_path,'.'),to_jsonb(v));IF ctx.column_path IN('code','number') AND j->'payload' ? ctx.column_path THEN j:=jsonb_set(j,ARRAY['payload',ctx.column_path],to_jsonb(v));END IF;NEW:=jsonb_populate_record(NEW,j);END IF;
 END LOOP;RETURN NEW;
END $function$

