CREATE OR REPLACE FUNCTION erp_inventory_private.tracking_mode_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE mode text;prior_mode text;BEGIN
 IF TG_OP='UPDATE' THEN prior_mode:=OLD.tracking_mode;ELSE SELECT tracking_mode INTO prior_mode FROM public.erp_inventory_items WHERE cafe_id=NEW.cafe_id AND item_id=NEW.item_id;END IF;prior_mode:=coalesce(prior_mode,'quantity');
 mode:=coalesce(NEW.payload->>'trackingMode',prior_mode);
 IF mode NOT IN('quantity','serial','lot','expiry','lot_expiry') OR NEW.kind<>'product' AND mode<>'quantity' THEN RAISE EXCEPTION 'طريقة تتبع الصنف غير صالحة';END IF;
 IF mode IS DISTINCT FROM prior_mode AND EXISTS(SELECT 1 FROM public.bf_movements WHERE cafe_id=NEW.cafe_id AND item_id=NEW.item_id) THEN RAISE EXCEPTION 'لا يمكن تغيير طريقة تتبع صنف له حركات مخزنية';END IF;
 IF mode<>'quantity' AND prior_mode='quantity' AND NOT coalesce((SELECT (payload->>'trackingEnabled')::boolean FROM public.erp_inventory_settings WHERE cafe_id=NEW.cafe_id),false) THEN RAISE EXCEPTION 'فعّل تتبع المنتجات من إعدادات المخزون';END IF;
 NEW.tracking_mode:=mode;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_settings_private.product_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE d public.erp_system_product_defaults;tax numeric;BEGIN
 IF EXISTS(SELECT 1 FROM public.erp_inventory_items WHERE cafe_id=NEW.cafe_id AND item_id=NEW.item_id) THEN RETURN NEW;END IF;
 SELECT * INTO d FROM public.erp_system_product_defaults WHERE cafe_id=NEW.cafe_id;IF NOT FOUND THEN RETURN NEW;END IF;
 IF NOT(NEW.payload ? 'tax1') THEN SELECT rate INTO tax FROM public.erp_system_taxes WHERE cafe_id=NEW.cafe_id AND id=d.tax1_id AND active;NEW.payload:=NEW.payload||jsonb_build_object('tax1',coalesce(tax,0),'defaultTax1Id',d.tax1_id);END IF;
 IF NOT(NEW.payload ? 'tax2') THEN SELECT rate INTO tax FROM public.erp_system_taxes WHERE cafe_id=NEW.cafe_id AND id=d.tax2_id AND active;NEW.payload:=NEW.payload||jsonb_build_object('tax2',coalesce(tax,0),'defaultTax2Id',d.tax2_id);END IF;
 RETURN NEW;
END $function$

