CREATE OR REPLACE FUNCTION erp_branch_private.capture_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE c uuid:=NEW.cafe_id;b uuid;row jsonb:=to_jsonb(NEW);rid uuid;kind text;BEGIN
 IF nullif(current_setting('erp.branch_cafe',true),'') IS DISTINCT FROM c::text THEN RETURN NEW;END IF;b:=nullif(current_setting('erp.branch_id',true),'')::uuid;IF b IS NULL THEN RETURN NEW;END IF;
 IF NOT erp_branch_private.row_allowed(c,b,row,'') THEN RAISE EXCEPTION 'سجل خارج الفرع المختار' USING ERRCODE='42501';END IF;
 rid:=coalesce(nullif(row->>'id',''),nullif(row->>'item_id',''))::uuid;
 IF TG_TABLE_NAME='bf_documents' THEN
  IF NEW.reference_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=NEW.reference_id AND branch_id<>b) THEN RAISE EXCEPTION 'المستند الأصلي تابع لفرع آخر' USING ERRCODE='42501';END IF;
  INSERT INTO public.erp_branch_documents(cafe_id,document_id,branch_id) VALUES(c,rid,b);
 ELSE
  kind:=CASE TG_TABLE_NAME WHEN 'bf_parties' THEN row->>'kind' WHEN 'bf_items' THEN 'item' WHEN 'erp_cost_centers' THEN 'cost_center' WHEN 'erp_inventory_catalogs' THEN CASE WHEN row->>'kind'='unit_template' THEN 'unit_template' END ELSE NULL END;
  IF TG_TABLE_NAME='erp_inventory_catalogs' AND kind IS NULL THEN RETURN NEW;END IF;
  IF kind IS NOT NULL THEN INSERT INTO public.erp_branch_resources VALUES(c,kind,rid,b) ON CONFLICT DO NOTHING;ELSE INSERT INTO public.erp_branch_records VALUES(c,TG_TABLE_NAME,rid,b) ON CONFLICT DO NOTHING;END IF;
 END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.cleanup_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE row jsonb:=to_jsonb(OLD);rid uuid;k text;BEGIN
 rid:=coalesce(nullif(row->>'id',''),nullif(row->>'item_id',''))::uuid;k:=CASE TG_TABLE_NAME WHEN 'bf_parties' THEN row->>'kind' WHEN 'bf_items' THEN 'item' WHEN 'bf_accounts' THEN 'account' WHEN 'erp_cost_centers' THEN 'cost_center' WHEN 'erp_inventory_catalogs' THEN CASE WHEN row->>'kind'='unit_template' THEN 'unit_template' END END;
 DELETE FROM public.erp_branch_records WHERE cafe_id=OLD.cafe_id AND table_name=TG_TABLE_NAME AND record_id=rid;
 IF k IS NOT NULL THEN DELETE FROM public.erp_branch_resources WHERE cafe_id=OLD.cafe_id AND kind=k AND record_id=rid;END IF;RETURN OLD;
END $function$

CREATE OR REPLACE FUNCTION erp_branch_private.guard_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE c uuid:=OLD.cafe_id;b uuid;row jsonb:=to_jsonb(OLD);kind text;BEGIN
 IF nullif(current_setting('erp.branch_cafe',true),'') IS DISTINCT FROM c::text THEN IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END IF;b:=nullif(current_setting('erp.branch_id',true),'')::uuid;
 kind:=CASE TG_TABLE_NAME WHEN 'bf_parties' THEN row->>'kind' WHEN 'bf_items' THEN 'item' WHEN 'bf_accounts' THEN 'account' WHEN 'erp_cost_centers' THEN 'cost_center' WHEN 'erp_inventory_catalogs' THEN CASE WHEN row->>'kind'='unit_template' THEN 'unit_template' ELSE '' END ELSE '' END;
 IF NOT erp_branch_private.row_allowed(c,b,row,kind) THEN RAISE EXCEPTION 'لا يمكن تعديل سجل خارج الفرع المختار' USING ERRCODE='42501';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE PERFORM erp_branch_private.assert_input(c,to_jsonb(NEW));RETURN NEW;END IF;
END $function$

CREATE OR REPLACE FUNCTION erp_settings_private.assign_display_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$DECLARE j jsonb:=to_jsonb(NEW);ctx text;reference public.bf_documents;draft uuid;BEGIN
 IF TG_TABLE_NAME='bf_documents' THEN
  SELECT * INTO reference FROM public.bf_documents WHERE cafe_id=NEW.cafe_id AND id=NEW.reference_id;
  IF NEW.kind='settlement' THEN
   ctx:=CASE reference.kind WHEN 'sale' THEN 'invoice_payment' WHEN 'purchase' THEN 'purchase_payment' WHEN 'refund' THEN CASE WHEN EXISTS(SELECT 1 FROM public.bf_documents d WHERE d.cafe_id=NEW.cafe_id AND d.id=reference.reference_id AND d.kind='purchase') THEN 'purchase_return_payment' ELSE 'refund_payment' END END;
  ELSIF NEW.kind='refund' THEN
   ctx:=CASE WHEN reference.kind='purchase' THEN CASE WHEN EXISTS(SELECT 1 FROM public.erp_purchase_debits WHERE cafe_id=NEW.cafe_id AND document_id=NEW.id) THEN 'purchase_debit' ELSE 'purchase_return' END WHEN reference.kind='sale' THEN 'sales_return' END;
  ELSIF NEW.kind='journal' THEN
   SELECT id INTO draft FROM public.bf_gl_drafts WHERE cafe_id=NEW.cafe_id AND document_id=NEW.id;
   IF draft IS NOT NULL THEN RETURN NEW;END IF;ctx:='automatic_journal';
  END IF;
 ELSE ctx:=CASE TG_TABLE_NAME WHEN 'erp_bookings' THEN 'booking' WHEN 'erp_rental_reservations' THEN 'rental_reservation' WHEN 'erp_task_templates' THEN 'task_template' WHEN 'bf_gl_drafts' THEN 'manual_journal' WHEN 'erp_finance_custody_movements' THEN CASE WHEN j->>'kind'='settlement' THEN 'custody_settlement' END END;
 END IF;
 IF ctx IS NOT NULL THEN PERFORM erp_settings_private.allocate_number((j->>'cafe_id')::uuid,ctx,(j->>'id')::uuid,coalesce((j->>'created_at')::timestamptz,now()));END IF;
 -- A paid refund is itself the actual cash movement, not a fictitious settlement child
 IF TG_TABLE_NAME='bf_documents' AND j->>'kind'='refund' AND coalesce((j->>'paid')::numeric,0)>0 AND reference.kind IN('sale','purchase') THEN PERFORM erp_settings_private.allocate_number(NEW.cafe_id,CASE reference.kind WHEN 'purchase' THEN 'purchase_return_payment' ELSE 'refund_payment' END,NEW.id,NEW.created_at);END IF;RETURN NEW;
END $function$

