CREATE OR REPLACE FUNCTION public.guard_rast_loyalty_ledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_old_cafe uuid; v_new_cafe uuid; v_rast boolean;
BEGIN
  IF TG_OP <> 'INSERT' THEN v_old_cafe := OLD.cafe_id; END IF;
  IF TG_OP <> 'DELETE' THEN v_new_cafe := NEW.cafe_id; END IF;
  SELECT EXISTS(SELECT 1 FROM public.cafes WHERE id IN (v_old_cafe,v_new_cafe)) INTO v_rast;
  IF v_rast AND current_user NOT IN ('postgres','supabase_admin','service_role') THEN
    RAISE EXCEPTION 'Use authorized Rast loyalty operations' USING ERRCODE='42501';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_access_private.guard_service_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NOT public.is_platform_admin() AND NOT platform_access_private.service_enabled(NEW.cafe_id,TG_ARGV[0])
    THEN RAISE EXCEPTION 'Service unavailable for current subscription' USING ERRCODE='42501'; END IF;
  IF TG_OP='UPDATE' AND OLD.cafe_id IS DISTINCT FROM NEW.cafe_id AND NOT public.is_platform_admin()
